39 \\u0420\\u0423\\u0421\\u0410\\u041b \\u0438 En+Group. \\u041f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043c\\u0430 \\u043f\\u0440\\u0435\\u0434\\u043f\\u043e\\u043b\\u0430\\u0433\\u0430\\u0435\\u0442 \\u0442\\u0440\\u0438 \\u044d\\u0442\\u0430\\u043f\\u0430 \\u043f\\u043e \\u043f\\u0440\\u043e\\u0435\\u043a\\u0442\\u043d\\u044b\\u043c \\u0431\\u043b\\u043e\\u043a\\u0430\\u043c Web, 1C, \\u0438\\u043d\\u0444\\u043e\\u0440\\u043c\\u0430\\u0446\\u0438\\u043e\\u043d\\u043d\\u0430\\u044f \\u0431\\u0435\\u0437\\u043e\\u043f\\u0430\\u0441\\u043d\\u043e\\u0441\\u0442\\u044c \\u0438\\u043b\\u0438 \\u0441\\u0435\\u0442\\u0435\\u0432\\u0430\\u044f \\u0438\\u043d\\u0444\\u0440\\u0430\\u0441\\u0442\\u0440\\u0443\\u043a\\u0442\\u0443\\u0440\\u0430.\\r\\n\\r\\n\\u0412 \\u043f\\u0435\\u0440\\u0432\\u043e\\u043c \\u0442\\u0443\\u0440\\u0435 (\\u043c\\u0430\\u0440\\u0442-\\u0438\\u044e\\u043d\\u044c) \\u0432\\u0442\\u043e\\u0440\\u043e\\u043a\\u0443\\u0440\\u0441\\u043d\\u0438\\u043a\\u0438 \\u0443\\u0437\\u043d\\u0430\\u044e\\u0442 \\u043e \\u0434\\u0435\\u044f\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u0438 \\u043a\\u043e\\u043c\\u043f\\u0430\\u043d\\u0438\\u0438, \\u043f\\u0440\\u043e\\u0441\\u043b\\u0443\\u0448\\u0430\\u044e\\u0442 \\u043a\\u0443\\u0440\\u0441 \\u043b\\u0435\\u043a\\u0446\\u0438\\u0439, \\u043f\\u043e\\u0441\\u0435\\u0442\\u044f\\u0442 \\u043c\\u0430\\u0441\\u0442\\u0435\\u0440-\\u043a\\u043b\\u0430\\u0441\\u0441\\u044b, \\u0440\\u0435\\u0448\\u0430\\u0442 \\u0440\\u0435\\u0430\\u043b\\u044c\\u043d\\u044b\\u0435 \\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0435 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0438. \\u0421\\u0442\\u0443\\u0434\\u0435\\u043d\\u0442\\u044b \\u043f\\u043e\\u0437\\u043d\\u0430\\u043a\\u043e\\u043c\\u044f\\u0442\\u0441\\u044f \\u0441 \\u043d\\u0430\\u0441\\u0442\\u0430\\u0432\\u043d\\u0438\\u043a\\u0430\\u043c\\u0438 \\u0438 \\u043c\\u0435\\u043d\\u0442\\u043e\\u