INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(1, NULL, NULL, 'Разработка цифрового двойника авиастроительного предприятия с применение VR (unity)', 15, 'Создание цифрового двойника производственного помещения в образовательном сегменте позволит обеспечить доступные инструменты для пользователей и дополнить обучающие программы интерактивным визуальным контентом. Погружение студентов в производственную атмосферу, без физического присутствия на производстве.', 'В настоящее время имеется следующий задел по проекту: разработано 1 станция виртуальной сборки, виртуализированы 3 лабораторных работ. \nВ рамках данного проекта планируется масштабировать виртуальные цеха авиастроительного предприятия, доработать имеющийся сценарий агрегатно-сборочных работ.\n', 2, '2022-09-01', '2023-05-30', '', 'Иркутский авиазавод, применение современных ИТ инструментов для цифровизации производств', NULL, 'Создан симулятор (тренажер), содержащий следующие функции:\n1. Знакомство с конструкцией авиационных узлов и агрегатов (членение агрегатов и узлов)\n2. Монтаж и ППР сборочного приспособления (доработка существующего функционала)', 'Знания: принципы работы с gamedev\nУмения: читать и составлять техническую документа. \nНавыки: работа с графическими редакторами, создание и реализация сценария\n', 'Говорков Алексей Сергеевич', 9, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2, NULL, NULL, 'Разработка цифрового следа обучающего ИРНИТУ (на примере студента института ИТиАД)', 15, 'Разработка решения для сбора цифрового следа обучающихся ИРНИТУ (на примере обучающихся Института информационных технологий и анализа данных)', 'Целью данного проекта является разработка концепции, модели и прототипа (макетная реализация) информационной системы для сбора данных, являющихся составляющими цифрового следа студентов, обучающихся в ИРНИТУ. Собираемые данные содержат информацию об активностях студентов и достигнутых результатах в рамках этих активностей. Под «активностью студента» в проекте понимается участие обучающегося в учебных, научных и общественных мероприятиях, проводимых в университете и за его пределами. \nВ настоящее время имеется следующий задел по проекту: в информационных системах университета фиксируются данные об успеваемости студентов, проводимых мероприятиях, победителях и призерах олимпиад и конференций.\nВ рамках данного проекта планируется разработка концепции (принципиальной модели сбора цифрового следа студентов), модели бизнес-процессов для сбора информации о деятельности студентов, проектирование хранилища данных и реализация прототипа информационной системы\n', 2, '2022-09-01', '2023-05-30', '', 'Управление по молодёжной политике, Учебно-методическое управление, Управление научной деятельности', NULL, 'Концепция системы для сбора данных о деятельности студентов, проект информационной системы для фиксации цифрового следа, реализация системы на уровне прототипа', 'Знания: принципы построения информационных систем, основы веб-программирования, принципы интеграции информационных систем, нотация Чена, стандарты описания UML, IDEF0.\nУмения: анализировать проблему и ставить задачу, читать и составлять техническую документацию с использованием стандартов UML, IDEF0, моделировать данные, составление SQL-запросов.\nНавыки: проектирования информационных систем, работа с реляционными СУБД, разработка JavaScript-скриптов, разработка php-скриптов.\n', 'Копайгородский Алексей Николаевич', 9, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3, NULL, '2022-08-30 10:36:46', 'Применение фотограмметрии для построения 3D моделей объектов при проектировании', 15, 'Разработать и опробовать методику построения 3D модели ( dwg-формат) по массиву фотографий объекта', 'При выполнении предпроектных обследований действующего электрооборудования значительную часть времени занимают обмерные работы. Зачастую, по условиям безопасного выполнения работ, не все замеры можно выполнить.', 2, '2022-09-01', '2023-05-30', NULL, 'ГК «ЕвроСибЭнерго»', NULL, 'Разработана методика должна содержать последовательность действий, требования к исходному материалу (качество, количество и ракурс фотографий) и условия (освещенность и т.п).\r\nРазработанная методика позволяет выполнять работы (получение объемных планов/чертежей расположения оборудования) с меньшими трудозатратами по сравнению с натурными обмерами..\r\nСтоимость применяемого оборудования и ресурсов для обработки фотографий должна быть экономически выгодна по сравнению с классическими методами..\r\nПроведен эксперимент.', 'Знания: принципы работы с C#/Python/OpenCV\r\nУмения: читать и составлять техническую документа. \r\nНавыки: работа с графическими редакторами, создание и реализация алгоритма', 'Григорьев Станислав Валентинович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4, NULL, '2023-02-17 08:28:34', 'Развитие веб-платформы «Ярмарка проектов ИРНИТУ»', 15, 'Создание решения для поддержки процесса распределения студентов ИРНИТУ в рамках проектной деятельности', 'Данный проект основывается на результатах проекта «Развитие веб-платформы “Ярмарка проектов” института ИТиАД»\r\nВ настоящее время имеется следующий задел по проекту: разработано веб-приложение позволяющее студентам просматривать карточки проектов, осуществлять сбор заявок от студентов на участие и автоматически распределять студентов по проектам с учетом их предпочтений и принадлежности к тому или иному направлению подготовки\r\nВ рамках данного проекта планируется доработать имеющуюся систему для поддержки процесса распределения студентов ИРНИТУ по проектам, для чего необходимо реализовать интерфейс руководителя центра проектного обучения, а также разработать механизмы дальнейшей интеграции с «АИС Университет»', 2, '2022-09-01', '2023-05-30', NULL, 'Центр проектного обучения', NULL, 'Реализация следующих функций: добавление отзыва руководителя на работу участника проекта,  интерфейс руководителя центра проектного обучения для загрузки аннотаций проектов в систему, ручного перераспределения студентов по проектам, запуска механизма автоматического распределения студентов, в том числе «молчунов» (не подавших заявки на проекты), выгрузки списков распределения студентов по проектам.', 'Знания: принципы работы веб-сайта, основы веб-программирования, ORM-фреймворки, нотация Чена, стандарты описания UML, IDEF0, RDF\r\nУмения: читать и составлять техническую документацию с использованием стандартов UML, IDEF0, RDF, моделирование данных, составление SQL-запросов, \r\nНавыки: работа с СУБД MySQL, администрирование Linux, работа с Figma, разработка JavaScript скриптов, разработка php-скриптов, работы с Laravel', 'Аршинский Вадим Леонидович, Серышева Ирина Анатольевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5, NULL, NULL, 'Разработка методов и программного средства автоматического извлечения данных из таблиц', 15, 'Создание решения для поддержки процесса автоматического извлечения данных из таблиц', 'Данный проект связан с разработкой модуля семантической интерпретации таблиц в рамках веб-платформы TALISMAN, предназначенной для построения предметно-ориентированных интеллектуальных систем поиска и извлечения информации. Разработка проводиться совместно с Институтом системного программирования им. В.П. Иванникова РАН и Институтом динамики систем и теории управления им. В.М. Матросова СО РАН.\nОсновная задача модуля – извлечение знаний в виде набора фактов из реляционных таблиц, содержащихся в различных документах (PDF, DOCX, HTML и др.) и наполнение этими фактами целевого графа знаний (labeled property graph).\nВ настоящее время имеется следующий задел по проекту: разработан модуль для автоматизированного извлечения фактов из строк реляционных таблиц на основе специально подготовленной конфигурации в формате JSON (в этой конфигурации явно указывается, какие факты и откуда извлекать).\nВ рамках данного проекта планируется доработать имеющийся модуль, сделать его более универсальным, в том числе для случаев, когда в документе много таблиц и они разные по структуре. В частности, необходимо реализовать автоматическое распознавание типов таблиц (вертикальная, горизонтальная, матричная) и приведение их к реляционной форме, включая отдельные задачи по нормализации данных и определению заголовков таблиц.\nВ целом данный проект связан с крупной и актуальной на сегодняшний день научной проблемой – автоматического понимания табличной информации (table understanding). Проект соответствует мировому уровню.\n', 3, '2022-09-01', '2023-05-30', '', 'ИДСТУ СО РАН / ИСП РАН', NULL, 'Реализация следующих функций: автоматическое распознавание типов таблиц, автоматическое приведение распознанных таблиц к реляционной форме, автоматическая идентификация данных и метаданных (заголовков) в таблицах.', 'Знания: общее представление о научной проблеме понимания табличной информации, принципы интеграции и настройки готовых программных решений, объектно-ориентированное программирование, основы обработки естественного языка (NLP) и машинного обучения, в частности глубокие нейросетевые модели (DNN), CRF, SVM.\nУмения: программирование в объектно-ориентированном стиле на языке Python, формирование тестовых и обучающих выборок, проведение тестов производительности, взаимодействие в команде разработчиков, составление документации\nНавыки: работа с платформой TALISMAN, работа с форматом JSON, разработка py-скриптов, работа на ML-платформе TensorFlow, администрирование Linux, работа в системе контроля версий Git\n', 'Юрин Александр Юрьевич, Дородных Никита Олегович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6, NULL, '2022-06-24 08:13:59', 'Развитие системы «Рейтинг студентов»', 15, 'Автоматизация процесса формирования списков студентов на получение повышенной стипендии', 'Данный проект основывается на результатах проекта «Рейтинг студентов». \r\nНа данный момент в рамках проекта выполнены следующие работы: анализ деятельности по начислению рейтинговой стипендии студентам ИрНИТУ; выделено пять модулей данного процесса; проведены подробный анализ и  проектирование модуля распределения стипендии; разрабатывается прототип версия модуля распределения стипендии.\r\nВ рамках данного проекта планируется выполнение дальнейших работ по разработке системы «Рейтинг студентов»:  выпустить первый релиз  модуля  распределения стипендии; выполнить детальный анализ и проектирование модуля формирования коллективов, разработать механизм интеграции проекта с  «АИС Университет»', 3, '2022-09-01', '2023-05-30', NULL, 'Управление информатизации ИРНИТУ', NULL, 'Результат данного проекта: проектная документация модуля формирования коллективов  и реализация модуля распределения стипендии.', 'Знания: нотаций URL,  IDEF0, DFD,  RDF, нотация Чена, основы веб-программирования, основы проектирования программ\r\nУмения:  применять методы проектирования программного продукта, работать  с инструментальными средствами, поддерживающими создание программного обеспечения; использовать методы организации работы в коллективах разработчиков программного обеспечения; \r\nНавыки:  работа с СУБД SQL, работа с Figma, разработка JavaScript скриптов, разработка php-скриптов, работы с Laravel и React, HTML, CSS', 'Бахвалова Зинаида Андреевна, Каташевцев Михаил Дмитриевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7, NULL, NULL, 'Создание интеллектуальной технологии цифрового материаловедения для анализа и прогнозирования свойств кристаллических кремниевых материалов для солнечной энергетики', 15, 'Разработка программно-инструментальных средств для автоматизированного анализа структурных, электрических и эксплуатационных свойств поликристаллических материалов с целью создания универсальных руководящих принципов получения высокопроизводительных материалов для солнечной энергетики. ', 'В рамках заявляемого проекта предполагается использовать мультикристаллический кремний в качестве модельного материала для разработки комплекса программ, реализующих следующие полезные модели:\n• усовершенствованная  нейронная сеть  для идентификации параметров ориентации монокристаллических зёрен в промышленных слитках мультикремния по их сканированным изображениям;\n• модель для  автоматизированного зонирования макроструктуры продольных пластин слитков мультикремния с целью поиска взаимосвязей между пространственным распределением зон на изображениях пластин и условиями направленной кристаллизации. \n', 3, '2022-09-01', '2023-05-30', '', 'Институт геохимии им. А.П. Виноградова СО РАН', NULL, '1. Усовершенствованная методика проведения автоматизированного статистического анализа сканированных изображений продольных и поперечных пластин мультикремния с применением кластерного анализа с целью поиска небольшого числа малых репрезентативных областей для сканирования с помощью выборочного ориентационного метода анализа дифракции обратно-рассеянных электронов (ДОРЭ);\n2. Нейронная сеть, улавливающая взаимосвязи оттенков серого цвета отдельных точек сканированного изображения и исходных данных ДОРЭ (матрица значений углов Эйлера) соответствующего образца и на основе этого идентифицирующая  параметры ориентации зёрен (на макроуровне) на всей площади сканированной пластины;\n3. Нейронная сеть, способная решать указанные задачи на разных пластинах мультикремния;\n4. Модель, с помощью которой будут выявлены зоны макроструктуры на сканированных изображениях продольных пластин слитков мультикремния;\n5.  Прототип программного комплекса для автоматизированного анализа структурных, электрических и эксплуатационных свойств поликристаллических материалов\n', 'Знания: математические и алгоритмические  основы моделей  машинного обучения, основы программирования на языке Python, стандарты описания UML, IDEF0.\nУмения: применить  знания основ высшей математики и математической статистики на практике, создавать модели  машинного обучения для решения научно-исследовательских и промышленных  задач, читать и составлять техническую документацию с использованием стандартов UML, IDEF0.\nНавыки: реализация нейронных сетей и других алгоритмов машинного обучения  с помощью языка Python,  создание GUI –приложений на языке Python\n', 'Осипова Елизавета Алексеевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8, NULL, NULL, 'Разработка концепции Ситуационно-аналитического центра энергетической компании', 15, 'Разработка концепции Ситуационно-аналитического центра энергетической компании', 'В компании создан САЦ, но нет стратегии по наполнению данными и анализу этих данных. Необходимо выполнить ряд задач: 1) Сократить время реагирования и ликвидации аварий и нештатных ситуаций. 2) Найти способы снижение аварийности основного и вспомогательного оборудования, за счет оперативного оповещения о внештатных ситуациях. 3) Найти способ сокращения затрат на ТОиР. 4) Сформировать предложения, направленных на увеличение надежности работы оборудования энергетического оборудования. 5) Повысить достоверность и оперативности доставки и обработки информации об авариях, чрезвычайных и нештатных ситуациях, связанных с производственной деятельностью объектов управления, а также ЧС природного и техногенного характера. 6) Снизить трудоемкость процессов отслеживания текущей ситуации и подготовки оперативных сводок, справок и отчетов.', 2, '2022-09-01', '2023-05-30', '', 'ООО \"Эн+ Диджитал\"', NULL, 'Концепция с детальным описанием бизнес-процессов, систем целевой модели; информационных потоков, методов их обработки. Выделение целей использования  и групп пользователей.', 'Знания: понятие ситуационно-аналитических центров, основы программирования на языках высокого уровня, знакомство с методами визуальной аналитики, нотация Чена, стандарты описания UML, IDEF0, BPMN\nУмения: читать и составлять техническую документацию с использованием стандартов UML, IDEF0, BPMN\nНавыки: администрирование, работа с СУБД, работа с Dashboard  разработка JavaScript скриптов, разработка php-скриптов, работы\n', 'Массель Алексей Геннадьевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(9, NULL, NULL, 'Инструментальные средства для моделирования интеллектуальных интегрированных энергетических систем на основе мультиагентного подхода', 15, '', 'Разработка средств для моделирования интеллектуальных интегрированных энергетических систем', 2, '2022-09-01', '2023-05-30', '', 'ИСЭМ СО РАН, возможно участие в грантах и публикация научных статей', NULL, 'Мультиагентная система для моделирования интеллектуальных интегрированных энергетических систем при решении задач их управления', 'Знания: принципы проведения мультиагентного моделирования, обучение с подкреплением \nУмения: применение машинного обучения, моделирование энергетических систем, их подсистем и элементов. \nНавыки: работа в программной среде AnyLogic, разработка моделей в MatLab, работа с программными библиотеками, реализующими обучение с подкреплением\n', 'Барахтенко Евгений Алексеевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(10, NULL, NULL, 'Разработка программы \"Информационно-аналитическая платформа по решению транспортно-логистической задачи”', 15, 'Создание программного решения для поддержки процесса распределения сырья и товаров для нормированного снабжения населения.', 'Информационно-аналитическая платформа предназначена для решения транспортно-логистической задачи, целью которой является расчет наиболее оптимальных маршрутов доставки (поставки) сырья и товаров (далее – грузы) для нормированного снабжения населения (далее – НСН) продовольственными и непродовольственными товарами в период мобилизации, период действия военного положения и военное время. Расчет стоимости перевозок (с учетом их объемов и периодичности доставки) с точки зрения минимизации между хозяйствующими субъектами, расположенными на территории Иркутской области (от поставщика до получателя) в объемах необходимой потребности для обеспечения бесперебойного НСН товарами первой необходимости (по заданной номенклатуре товаров) при минимально возможных сроках доставки и затратах на перевозку. Получать возможность анализа ритмичности поставок, наличия минимально необходимого остатка товаров, каждого вида, у конечного получателя и оперативное перераспределение поставок при возникновении угрозы снижения минимально необходимого остатка товаров для обеспечения бесперебойного НСН товарами первой необходимости (по заданной номенклатуре товаров), а также возможностей и особенностей транспортной инфраструктуры Иркутской области.', 3, '2022-09-01', '2023-05-30', '', 'Администрация Иркутской области', NULL, 'Программа должна обеспечивать возможность выполнения перечисленных ниже функций.\n- Разделение прав пользователей, использующих программу:\n- Возможность корректировки баз данных с условно постоянной информацией (сведения о субъектах региона, транспортной доступности, нормах обеспечения регионов).\n- Возможность диалогового ввода и корректировки исходных данных для расчета планов поставок.\n- Возможность расчета оптимальных маршрутов доставки грузов с точки зрения минимизации стоимости перевозок (с учетом их объемов и периодичности доставки) между хозяйствующими субъектами, расположенными на территории Иркутской области, а также возможностей и особенностей транспортной инфраструктуры Иркутской области.\n- Возможность получать результаты расчетов, оформленными в соответствии с существующими формами отчетов.\n- Обеспечение хранения исходных данных для расчетов и результатов расчетов в базе данных.\n', 'Знания: принципы работы защищенного автономного приложения, основы программирования, нотация Чена, стандарты описания UML, IDEF0, математические модели транспортных задач.\nУмения: читать и составлять техническую документацию с использованием стандартов UML, IDEF0, моделирование данных, составление SQL-запросов, \nНавыки: проведения предпроектного обследования, работа с СУБД PostgreSQL, администрирование Windows,  Linux, работа с пакетами программированияl\n', 'Бахвалов Сергей Владимирович , Маланова Татьяна Валерьевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(11, NULL, NULL, 'Разработка антивирусного программного обеспечения', 15, 'Разработка методики сравнительного тестирования антивирусных продуктов и разработке примитивного антивирусного программного обеспечения (антивирусного сканера).', 'Знакомство со средой разработки и работа над проектом.\nВ проекте мы познакомимся с использованием электронных ресурсов компании Microsoft (выбор версии Visual Studio, создание учетной записи, работа с установочным файлом, запустить программы). \n Начало работы над проектом (запустить Visual Studio), выбрать тип проекта Windows Form С#.\n Размещение элементов форм, указать необходимые свойства.\n Знакомство с сигнатурами, анализ вирусных сигнатур (работа над созданием таблиц в которой содержатся: название вируса, вирусные сигнатуры, краткое описание вируса).\n Написание программного кода. Загрузка вирусных сигнатур в коллекцию, обработка событий.\n', 2, '2022-09-01', '2023-05-30', '', 'Курсы для специалистов ИБ «Доктор Веб»\nhttps://training.drweb.ru/courses/admins/\n\nОбучение KasperskyOS\nhttps://os.kaspersky.ru/development/education\n', NULL, 'Написание программного кода. Загрузка вирусных сигнатур в коллекцию, обработка событий.\nДальнейшая работа (более глубокая и детальная) над проектом предполагает  разработку компонентного базового программно-инструментального средства для построения антивирусных программных комплексов.\n', 'Знания: Виды уязвимостей информационной системы, согласно ГОСТ Р 56546-2015 (защита информации, уязвимости информационных систем).\nУмения: Возможность проводить работы с исследованиями (существующими методиками), формирование списка критериев, выбор продуктов тестирования, проведение эксперимента,  проверке  эффективности ПО в реальных условиях.\nНавыки: Работа с кодом вируса (или его часть), влияние на работу других программ. Работа с загрузочной записью (boot record) и системным загрузчиком (master boot record), драйверами.\n', 'Маринов Александр Андреевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(12, NULL, '2022-10-03 10:09:49', 'Программное обеспечение для автоматической оценки стабильности особо ответственных технологических процессов (ООТП) изготовления авиационных деталей', 15, 'Создание программного модуля, предназначенного для автоматической оценки стабильности ООТП на основе анализа объективных параметров, полученных при выполнении технологических операций', 'При контроле качественного выполнения ООТП используются нормативные параметры, заданные в определенном диапазоне. Повышения стабильности достигается сужением такого диапазона и требует непрерывного улучшения по результатам контроля. В процессе работы необходимо разработать математический аппарат и программное обеспечение для контроля стабильности.', 3, '2022-09-01', '2023-05-30', NULL, 'ИАЗ', NULL, 'Программный модуль', 'Знать: основы разработки и контроля технологической документации при изготовлении деталей на машиностроительных предприятиях\r\nУметь: использовать инструменты разработки ПО.\r\nВладеть: навыками программирования', 'Мироненко Владимир Витальевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(13, NULL, NULL, 'Поиск применения камеры с аппаратным распознавание государственных регистрационных номеров', 15, 'Создание комплексного решения для поддержки и реализации проекта дополнительного обучения «Академия ИТ»', 'В распоряжении ООО «ИНК» имеется несколько десятков Ethernet камер с аппаратный распознавание номер машин, данные камеры сняты с автоматических шлагбаумов. В результате реализации проекта необходимо определить места установки камер на объектах ООО «ИНК» и как использовать данные получаемые с камер для процессов цифровизации перемещения автотранспортных средств', 2, '2022-09-01', '2023-05-30', '', 'ООО «ИНК»', NULL, 'Определение мест установки камер, определение параметров необходимой инструкторы (питание, канал связи), реализации программного обеспечения для взаимодействия с камерами', 'Знания: принципы работы с Ethernet камерами, принципы запроса информации с камер, маршрутизация данных с использование различных протоколов.\nУмения: читать и составлять техническую документацию с использованием стандартов UML, работать с get и post запросами, работа с API и базами данных\nНавыки: работа  администрирование Linux, работа с IDE, разработка back и front\n', 'Кононенко Роман Владимирович ', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14, NULL, NULL, 'Разработка системы учета посещения занятий студентами', 15, 'Разработка и интеграция автоматической системы учета посещаемости студентами занятий', 'Разработка системы учета посещения занятий студентами, способной в автоматическом режиме согласно существующей БД используя карту-пропуск студента идентифицировать ФИО студента время входа и время выхода студента из аудитории, сопоставлять расписание с ФИО студента', 3, '2022-09-01', '2023-05-30', '', 'Дирекция института ИТиАД', NULL, 'Автономное устройство считывание карт-пропусков в возможность подключения к локальной сети ИРНИТУ и работой с сервером.', 'Знания: принципы работы с модулями RFID, Wi-FI, Bluetooth, принципы запроса информации с сервера, маршрутизация данных с использование различных протоколов.\nУмения: читать и составлять техническую документацию, работать с get и post запросами, работа с API и базами данных, работа с Arduino\nНавыки: работа администрирование Linux, работа с IDE, разработка принципиальной схемы устройства, пайка, коркусирование устройства\n', 'Кононенко Роман Владимирович ', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(15, NULL, NULL, 'Система трекинга руководства компаний на удаленных промышленных объектах', 15, 'Создание программно-аппаратного комплекса для отслеживания положения людей (10-15 человек) на удаленных промышленных объектах.', 'При посещении удаленных промышленных объектах (на объектах отсутствует покрытие сети сотовой связи) руководящим составом компании, необходимо отслеживать положение каждого участника группы на объекте. Так как между объектами группа перемещается на вертолете, то время сбора всех участников группы возле вертолета является критически важным, так как вертолет следует согласно полетному расписанию. Знание местонахождения каждого участника группы на промышленном объекте позволяет сопровождающему группы оперативно находить их на объекте', 2, '2022-09-01', '2023-05-30', '', 'ООО «ИНК»', NULL, 'Носимое устройства трекинга и мобильный пост отображение положения трекеров.', 'Знания: GPS, Bluetooth, Wi-Fi, LoRa, построение беспроводной сети передачи данных\nУмения: читать и составлять техническую документацию, проектирование и разработка печатных плат, разработка Android приложений.\nНавыки: работа администрирование Android, работа с IDE, программирование микроконтроллеров\n', 'Кононенко Роман Владимирович ', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16, NULL, NULL, 'Система, уменьшая очереди на заправочных пунктах ООО \"ИНК\"', 15, 'Создание цифрового продукта, который позволит уменьшит очереди на заправочных пунктах ООО «ИНК»', 'В результате не рационального распределения автотранспортных средств по времени заправки, на заправочных пунктах возникают очереди на заправку или отсутствие машин для заправки. Необходим спроектировать и создать цифровой продукт который позволит избежать пиков заправки и выровнять в течении дня нагрузку на заправочный пункт.', 2, '2022-09-01', '2023-05-30', '', 'ООО «ИНК»', NULL, 'Прототип программного продукта для выравнивания загрузки заправочного пункта.', 'Знания: GPS, Bluetooth, Wi-Fi, LoRa, построение беспроводной сети передачи данных\nУмения: читать и составлять техническую документацию, проектирование и разработка печатных плат, разработка Android приложений.\nНавыки: работа администрирование Android, работа с IDE, программирование микроконтроллеров\n', 'Кононенко Роман Владимирович ', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(17, NULL, '2022-08-30 04:50:53', 'Экосистема для клиентов IT-компании', 15, 'Разработка цифрового сервиса для клиентов IT-компании', 'Требуется создать единый цифровой сервис – экосистему - для взаимодействия клиентов с IT-компанией, с помощью которого будут реализованы внешний документооборот, учет наработки, доп. продажи, интеграция сторонних сервисов и систем', 3, '2022-09-01', '2023-05-30', NULL, 'Институт информационных технологий и анализа данных', NULL, 'Личный кабинет клиента на цифровом сервисе, SPA приложение', 'Знания: Языки программирования JavaScript, HTML, CSS, PHP \r\nУмения: Разработка fronend и backend \r\nНавыки: Тестирование цифрового продукта , его отладка и запуск', 'Шеленговский Артем Владимирович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(18, NULL, '2022-08-30 04:53:05', 'Автоматизация и цифровизация процесса учета выпущенной продукции мукомольного производства', 15, 'Подсчет количества выбоя муки и цифровизация процесса складского учета', 'Требуется автоматизировать процессы взвешивания и распределения сырья (зерно) на мукомольном производстве в г.Улан-Удэ (Бурятия), а также систему их контроля. Интегрировать систему складского учета с ПО установленного оборудования. С помощью цифровой технологии – интернет вещей – оптимизировать указанные процессы.', 3, '2022-09-01', '2023-05-30', NULL, 'Институт информационных технологий и анализа данных', NULL, 'ПО для подсчета количества выбоя муки', 'Знания: языки программирования JavaScript, HTML, CSS, PHP \r\nУмения: Разработка fronend и backend \r\nНавыки: Тестирование программного продукта , его отладка и запуск', 'Шеленговский Артем Владимирович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(19, NULL, NULL, 'Система учета активности абитуриентов ИРНИТУ', 15, 'Разработка программы сопровождения профориентационных активностей  школьников до потенциального абитуриента ИРНИТУ', 'Разработка БД школьников для приемной кампании ИРНИТУ получает и видит их выбор направлений подготовки по заинтересованности и активности участия. \n\nДанные на вход:\n1. При регистрации каждый школьник записывает:\n- ФИО;\n- контактные данные;\n- образовательную организацию;\n- класс;\n- школьник выбирает мероприятия/курсы/программы.\n\nНеобходимо получить на выходе:\n- Личный кабинет у каждого школьника;\n- Списки школьников, зарегистрированных на мероприятия/курсы/программы с возможностью выгрузки;\n- Список школьников, окончившие курсы/программы, посетившие мероприятия по направлениям подготовки с индивидуальными бонусами с возможностью выгрузки;\n- Рейтинг школьников с их бонусами по направлениям подготовки;\n- Создание/добавление новых мероприятий в течение года;\n- Школьник и администратор в любой момент могут видеть список пройденных мероприятий/курсов/программ с полученными бонусами;\n- Афиша предстоящих мероприятий для школьников в хронологии с бонусами за их посещение;\n- Афиша предстоящих мероприятий для школьников по форматам работы (например, курсы, день открытых дверей, профессиональные пробы, летние школы)  и направлениям подготовки (траекториям) с бонусами за их посещение;\n- постоянно видимые ссылки на сайт ИРНИТУ, группу VK, телеграмм чат-бот, техподдержку.\n', 3, '2022-09-01', '2023-05-30', '', 'УМОУ и РОП, ЦПК', NULL, 'Программа - web-сайт и БД, в которой школьники регистрируются на разные профориентационные активности и программы довузовской подготовки ИРНИТУ и \"зарабатывают\" активностью бонусы. Бонусы переводятся в баллы индивидуальных достижений для поступления в наш университет по программе \"Успешный абитуриент\". ', '', 'Шведина Светлана Александровна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(20, NULL, NULL, 'Электронный учебный журнал образовательных курсов программы «Сетевой лицей ИРНИТУ', 15, 'Разработка программы сопровождения учебного процесса профильной сетевой образовательной программы ИРНИТУ и партнерских школ «Сетевой лицей ИРНИТУ»', 'Web-сайт и БД, в которой администратор вводит данные о школьниках и преподавателях с их предметами. У преподавателей есть доступ к журналам с учебными группами, в которых они имеют возможность проставлять посещение учеников и оценки за работу на занятии.\nАдминистратор должен иметь возможность получения журнала посещаемости по каждой школе по-отдельности.\nДанные на вход\nАдминистратор изначально заполняет данные по школьникам и преподавателям, в соответствии с таблицами:\nid ФИО Школа Класс Предмет по выбору №1 Предмет по выбору №2\n           \n \nid ФИО Наименование предмета Уровень Время Количество (человек в классе)\n           \nВыходные документы\nРешение должно иметь возможность формирования отчёта в приведённом виде:\nid ФИО учеников Наименование предмета Посещение/ Оценка Дата\n         \nТакже формирование ведомости, по успеваемости школьников, просмотр домашних заданий по нажатию на кнопку «Просмотреть ДЗ» с возможностью добавлять темы занятий и прикрепление файлов (ссылок) на материалы занятий.\nРаботать в программе могут преподаватели и администратор.\n', 3, '2022-09-01', '2023-05-30', '', 'УМОУ и РОП, Центр довузовской подготовки и профориентационной работы', NULL, 'Произвести разработку веб-сайта и БД для учета посещаемости школьников факультативных занятий по программе «Сетевой лицей ИРНИТУ», с возможностью получения отчётов посещаемости и успеваемости школьников по каждой школе и классу.', '', 'Шведина Светлана Александровна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(21, NULL, NULL, 'Система техподдержки сервисов ИРНИТУ', 15, 'Разработка модулей обработки заявок на работы специалистов по вопросам электропитания, тепло и водоснабжения на основе информационной системы «Кампус» по адресу https://int.istu.edu/', 'Разработка инструмента для формирования, обработки и контроля исполнения  заявок на работы специалистов по вопросам электропитания, тепло и водоснабжения. \n\nЗаказчик – все сотрудники ИРНИТУ, имеющие право на формирование  заявок для решения вопросов административно-хозяйственного характера:\nИсполнители:\nСлужба главного инженера ИРНИТУ\nСлужба главного энергетика ИРНИТУ\n', 3, '2022-09-01', '2023-05-30', '', 'Служба главного инженера, Служба главного энергетика ИРНИТУ', NULL, 'Программа – подразделы модуля информационной системы «Кампус» по формированию заявок.', 'Знания: язык программирования PHP\nУмения: Формирование модуля на платформе «Битрикс»\nНавыки: \n', 'Жуков А.В.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(22, NULL, NULL, 'Разработка веб форм для Центра Карьеры ', 15, 'Повышение управляемости и контроля изменений ИТ-инфраструктуры ИРНИТУ', 'Использование единой системы баз данных автоматизированной информационной системы ИРНИТУ позволит органично встроить информационную систему «Центра карьеры ИРНИТУ» в существующий комплекс автоматизированных систем подразделений и автоматизирует изменения взаимосвязанных используемых полей и таблиц. \nЧто в свою очередь позволит автоматически контролировать:  \n• Учет и изменение статуса заключенного договора с внешней организацией, обеспечивающей прохождение производственной и преддипломной практики; \n• прикрепления к нему перечня студентов \n• прикрепления к нему преподавателя – руководителя практики; \n• учет учебной нагрузки на преподавателя по руководству производственной/преддипломной практики;\nдополнение рейтинга студента параметрами прохождения производственной и преддипломной практики.\n', 3, '2022-09-01', '2023-05-30', '', 'Управление информатизации ИРНИТУ', NULL, 'Автоматический  контроль:  \n• Учета и изменения статуса заключенного договора с внешней организацией, обеспечивающей прохождение производственной и преддипломной практики; \n• прикрепления к нему перечня студентов \n• прикрепления к нему преподавателя – руководителя практики; \n• учет учебной нагрузки на преподавателя по руководству производственной/преддипломной практики;\n', 'Повышение уровня практических знаний по направлению «Вычислительные машины, комплексы, системы и сети».', 'Аношко Алексей Федорович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(23, NULL, NULL, 'Академия IT', 100, 'Обеспечить компании высококвалифицированными молодыми кадрами ИТ-направлений за счёт развития уникальных компетенций в соответствии с потребностью бизнеса в отрасли металлургии и энергетики', '«Академия IT» нацелена на подготовку IT-специалистов для энергетических и металлургических предприятий РУСАЛ и En+Group. Программа предполагает три этапа по проектным блокам Web, 1C, информационная безопасность или сетевая инфраструктура.\n\nВ первом туре (март-июнь) второкурсники узнают о деятельности компании, прослушают курс лекций, посетят мастер-классы, решат реальные производственные задачи. Студенты познакомятся с наставниками и менторами, которые в будущем могут стать коллегами.\n\nВо втором этапе политеховцам предлагается заключить целевой договор с ежемесячной выплатой стипендии в размере пяти тысяч рублей. В течение двух месяцев студентам предстоит пройти производственную практику на базе предприятий.\n\nВ финальном туре эксперты оценят деятельность участников и отберут 30 четверокурсников. Студенты разработают проект, который будет засчитан как выпускная квалификационная работа. Кроме того, студенты могут совмещать учёбу и работу в компании.\n\nПолитеховцы, успешно окончившие курсы, получат сертификат и удостоверение международного образца. Компания гарантирует официальное трудоустройство в подразделения РУСАЛ и En+Group, достойную заработную плату и карьерный рост.', 2, '2022-09-01', '2023-05-30', '', 'En+ digital', NULL, ' ', ' ', 'Говорков А.С.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(24, NULL, NULL, 'Проект \"Форсайт\"', 100, 'Возможность реализации тем проектов, предложенных студентами в инициативном порядке в рамках проектной форсайт-игры ', 'Центр проектного обучения проводит проектную форсайт-игру в целях выявить инициативные темы проектов студентов или тематики, предложенные наставниками, и вовлечь активных студентов и наставников в их реализацию в рамках «Проектной деятельности» в 2022 - 2023 учебном году. Реализация проекта позволит поддержать студенческие проектные инициативы и активных студентов, а также способствует развитию образовательных форматов, направленных преимущественно на формирование soft skills у студентов в проектной деятельности.\nКонтакт для связи по проекту https://t.me/tuymada ', 2, '2022-09-01', '2023-05-30', '', 'Центр проектного обучения', NULL, ' ', ' ', 'Чимитов П.Е.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(25, NULL, NULL, 'Разработка проекта мониторинга транспортного поведения населения на примере г. Иркутска', 15, 'Повышение качества транспортного обслуживания населения на основе учета количественных и качественных параметров транспортного поведения населения', 'Транспортное поведение — это совокупность сценариев подвижности, характеризующихся способом передвижения и величинами, которые могут быть измерены количественно: длительность поездки (корреспонденции), пройденное расстояние и др. Изменение транспортного поведения, свойственного городским сообществам, происходит под влиянием многих факторов: демографических сдвигов, смены экономических условий, эволюции городской формы и транспортного обеспечения.\nУдовлетворить спрос на перемещение от одной точки города до другой можно с помощью личного автотранспорта, общественного транспорта, велосипеда или пешком. Однако при значительном расстоянии между пунктом возникновения потребности в перемещении и пунктом назначения наибольшая часть потребности будет реализована с помощью транспорта\n', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Рекомендации для управления и методологического сопровождения процессов администрирования транспортного комплекса для муниципальных властей', 'Знания характеристик транспортного поведения населения г. Иркутска, инструментария мониторинга транспортного поведения населения. Умения анализировать количественные параметры транспортного поведения населения. Навыки обработки результатов исследования', 'Бутузова А.Б.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(26, NULL, NULL, 'Разработка проекта введения на улично-дорожной сети приоритетного движения городского маршрутного пассажирского транспорта общего пользования на примере г. Иркутска', 15, 'Повышение качества транспортных услуг для населения города за счет приоритетного комплексного развития транспорта общего пользования (снижение затрат времени на совершение ежедневных регулярных поездок пассажиров маршрутного транспорта за счет предоставления ему приоритета при движении по улично-дорожной сети и стимулирования отказа от использования индивидуальных автомобилей)', 'Высокий в настоящее время и продолжающий увеличиваться уровень автомобилизации (количество автомобилей на 1 тысячу жителей) приводит к возникновению транспортных проблем для жителей и гостей крупных городов. Это прежде всего возникновение заторов (пробок), что приводит к увеличению времени и затрат на поездки, транспортной усталости, снижает безопасность дорожного движения, обуславливает повышенные выбросы вредных веществ. Это усугубляется еще и отставанием развития транспортной инфраструктуры: улицы, дороги, остановочные пункты, транспортно-пересадочные узлы и т.п. В этих условиях в крупных городах необходимо разработать мероприятия по решению вышеуказанных проблем. Среди большого комплекса мер важнейшее значение будет иметь предоставление приоритета на улицах городов для маршрутного пассажирского транспорта общего пользования. Очень важно проводить это в сочетании с политикой стимулирования отказа от использования индивидуального транспорта для ежедневных поездок прежде всего по трудовым целям', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Предложения для городских властей по введению приоритетного движения на улично-дорожной сети для маршрутного пассажирского транспорта общего пользования, основанные на исследовании характеристик транспортных и пассажирских потоков', 'Знания: инструменты поиска информации по теме исследования; основные требования к представлению результатов проекта; особенности основных и смежных ролевых позиций.\nУмения: формулировать цели и задачи исследования; планировать и организовывать свою деятельность на основе приоритетов и поставленных целей; использовать инструменты поиска информации; выделить из массива информации ключевые моменты; решать задачи в соответствии с ролевой позицией, переключиться на свою смежную ролевую позицию.\nНавыки: формулирования запроса на поиск новых знаний и информации; анализа информации с целью выделения требуемого знания и формирования комплексного понимания предмета изучения; выполнения системного анализа информации по теме проекта, выделения «дефицитов» знаний и формулирования запроса на поиск новой информации; презентации результатов проекта; самоанализа и оценки личного вклада в достигнутые результаты; социального взаимодействия как с членами команды, так и с внешними стейкхолдерами\n', 'Колганов С.В.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(27, NULL, NULL, 'Разработка цифровых моделей транспортной инфраструктуры города и агломерации', 15, 'Повышение качества транспортного планирования городских агломераций на основе разработки цифровых моделей транспортной инфраструктуры', 'Одной из основных проблем формирования устойчивых городов и их агломераций является отсутствие качественного транспортного планирования в связке с территориальным планированием. В связи с этим необходимо решение ряда комплексных задач, связанных с освоением современных инструментов в области транспортного планирования и технологий учета влияния характеристик использования городских территорий на формирование транспортного спроса. Рассматриваемый проект на целен на разработку подходов по повышению скорости и качества задач интегрированного территориального и транспортного планирования с применением транспортного моделирования', 2, '2022-09-01', '2023-05-30', '', 'Разработка транспортной модели Иркутска и Иркутской агломерации (хоз. договорные работы в области транспортного планирования и организации дорожного движения)', NULL, 'Предложения по развитию подходов к оценке транспортного моделирования и оценке транспортного спроса', 'Знания: инструменты поиска информации по теме исследования; основные требования к представлению результатов проекта; особенности основных и смежных ролевых позиций.\nУмения: формулировать цели и задачи исследования; планировать и организовывать свою деятельность на основе приоритетов и поставленных целей; использовать инструменты поиска информации; выделить из массива информации ключевые моменты; решать задачи в соответствии с ролевой позицией, переключиться на свою смежную ролевую позицию.\nНавыки: формулирования запроса на поиск новых знаний и информации; анализа информации с целью выделения требуемого знания и формирования комплексного понимания предмета изучения; выполнения системного анализа информации по теме проекта, выделения «дефицитов» знаний и формулирования запроса на поиск новой информации; презентации результатов проекта; самоанализа и оценки личного вклада в достигнутые результаты; социального взаимодействия как с членами команды, так и с внешними стейкхолдерами\n', 'Левашев А.Г.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(28, NULL, NULL, 'Разработка проекта совершенствования методики расчета цены муниципального контракта при осуществлении закупок в сфере регулярных перевозок пассажиров на примере г. Иркутска', 15, 'Совершенствование методики расчета начальной (максимальной) цены контракта (НМЦК), а также цены контракта, заключаемого с единственным поставщиком (подрядчиком, исполнителем), для закупок в сфере регулярных перевозок пассажиров на основе учета технико-эксплуатационных параметров маршрутов перевозчика, а также создание соответствующего программного продукта', 'Начальная (максимальная) цена контракта (НМЦК) — это предельное значение цены, которое указывается в извещении и документации о проведении закупки с приглашением принять в ней участие. Заказчик обязан в полной мере обосновать цену, чтобы провести закупку. Менять условия уже заключенного контракта в большинстве случаев нельзя. Но очень часто при проведении расчета НМЦК возникают проблемы. Первое, цена может быть занижена. Это может привести к тому, что процедура закупки просто не состоится, так как никто не будет заключать контракт себе в убыток. Если такой контракт все-таки будет заключен, то это будет недобросовестный перевозчик, который не выполнит условия контракта по заявленной цене, либо будет занижено качество поставляемого товара, или предоставляемых услуг. Второе, может возникнуть ситуация, когда НМЦК, наоборот, будет завышена. Это в свою очередь приведет к неэффективному расходу средств бюджета. Третье, стоимость устанавливается некорректно, из-за технических проблем (ошибок в расчетах; неправильном использовании положений методических рекомендаций; ошибок при анализе рынка, когда он проанализирован не полностью; использовании некорректных исходных данных)', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Отчет и программный продукт с исходными данными по регулярным маршрутам для муниципальных властей по расчету начальной (максимальной) цены контракта, а также цены контракта, заключаемого с единственным поставщиком, для закупок в сфере регулярных перевозок пассажиров', 'Знания: характеристик подвижного состава и методики расчета и технико-эксплуатационных показателей на регулярных маршрутах.\nНавыки: проведения обследования пассажиропотоков и расчёта технико-эксплуатационных показателей на регулярных маршрутах; владения методикой обработки результатов исследования; составления базы данных по результатам обследования пассажиропотоков и разработки программного продукт; владения методикой расчёта НМЦК\n', 'Яценко С.А.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(29, NULL, NULL, 'Повышение углеродной нейтральности автомобилей с дизельными двигателями и их эксплуатационные свойства', 15, 'Снижение выбросов вредных веществ и диоксида углерода с выбросами автомобильных двигателей', 'Снижение выбросов вредных веществ и диоксида углерода с отработавшими газами является серьезной проблемой современности. Переход на электротранспорт в целом в настоящий момент не решает проблему снижения выбросов диоксида углерода, т.к. многие станции по выработке электроэнергии являются тепловыми, работающими на углеводородном топливе или каменном угле. Одним из путей снижения техногенной нагрузки в переходном периоде является применение возобновляемых топлив, которые могут быть растительного происхождения, а также являются продуктом утилизации бытовых отходов и др. При этом углеродный баланс нарушается меньше, а экологическая составляющая повышается.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Топливные композиции (состав возобновляемых топлив); экспериментальные данные в виде отчета и статьи с полученными результатами ', 'Знания: методики выполнения расчетов двигателей внутреннего сгорания; влияния рабочих процессов на динамику двигателя и на технико-экономические показатели работы\nУмения: проводить испытания двигателей и автомобилей; проводить экспериментальные исследования\nНавыки: расчета параметров технического состояния транспортных средств и сравнение их с требованиями нормативных правовых документов в отношении технического состояния транспортных средств; определения качества технологических жидкостей и эксплуатационных материалов\n', 'Кривцов Сергей Николаевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(30, NULL, NULL, 'Разработка конструкции стенда для исследования характеристик шин в дорожных условиях', 15, 'Разработка конструкции стенда для исследования характеристик шин в дорожных условиях для создания алгоритма управления антиблокировочной системой (АБС) колёсных транспортных средств (КТС).', 'Безопасность КТС во многом определяется сложными электронными и мехатронными системами, которые широко используются в современных автомобилях. Одной из таких систем является АБС, принцип работы которой построен на поддержании допустимого скольжения колеса в области максимального коэффициента сцепления шины автомобильного колеса с поверхностью дороги без его снижения в область неустойчивости КТС. Изменение коэффициента сцепления шины с опорной поверхностью от изменения проскальзывания колеса является основной зависимостью, в соответствии с которой осуществляется управления АБС. Однако, эта зависимость в значительной степени меняется от типа опорной поверхности, формы протектора шины, её материала и т.п. Применение аналитических методов для синтеза алгоритма управления АБС весьма проблематично, в связи с тем, что объект управления в точке экстремума теряет устойчивость, таким образом правее максимума управление в обычном смысле становится невозможным. В процессе движения КТС невозможно точно определить линейную скорость его кузова, а соответственно и проскальзывание колёс, что затрудняет определение коэффициента сцепления. Если довести колесо до момента предблокирования, возникнет существенное снижение бокового коэффициента сцепления, и, как следствие, потеря устойчивости КТС. Особенно это опасно на покрытии с различным коэффициентом сцепления по боковым колёсам КТС. Всё это приводит к тому, что возникает необходимость разработки алгоритма распознавания типа опорной поверхности под каждым колесом КТС и его управления. Компания Bosch, являющаяся лидером в разработке мехатронных систем, ведут работы по созданию алгоритма действий по калибровке систем АБС без изучения непосредственно взаимодействия шины, используя какие-то пороговые коэффициенты. Отечественными компаниями, такими, как Группа ГАЗ, АвтоВАЗ, и научными организациями ведутся работы по исследовании процесса взаимодействия автомобильного колеса с эластичной шиной на различных опорных поверхностях (сухой асфальт, мокрый, лед, снег и т.п). Результаты этих исследований позволят построить математический аппарат алгоритма адаптивного управления АБС с поддержанием удовлетворительной управляемости КТС. Для решения этой задачи необходимо разработать стенд для исследования характеристик шин в дорожных условиях.', 2, '2022-09-01', '2023-05-30', '', 'Ориентировочно грант РНФ, заявка № 22-79-00166, зарегистрирована: 09.03.2022 г.; электронный документ подписан: 10.03.2022 г. Совместно с кафедрой «Автомобили и тракторы» Института Транспортных систем, НГТУ им. Р.Е. Алексеева', NULL, 'Комплект конструкторской документации для создания опытного образца стенда для исследования характеристик шин в дорожных условиях', 'Знания: устройства и принципа работы современных мехатронных систем активной безопасности КТС; устройства и принципов работы дополнительного технологического и испытательного оборудования;\nрациональных методов эффективной эксплуатации, а также технологических процессов поддержания и восстановления работоспособности подвижного состава автотранспортных средств, их агрегатов, механизмов, узлов.\nУмения: разрабатывать структурные и кинематические схемы систем технологического и испытательного оборудования; проводить диагностирование и контроль технического состояния мехатронных систем подвижного состава автотранспортных средств.\nНавыки: проведения испытаний электронных систем КТС; проведения контроля технического состояния и диагностики подвижного состава автотранспортных средств, их агрегатов, механизмов, узлов.\n', 'Яньков Олег Сергеевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(31, NULL, NULL, 'Разработка программного комплекса для управления диагностическим гибридным стендом с беговыми барабанами', 15, 'Разработка программного комплекса (ПК) для регистрации, контроля, обработки и сохранения диагностической информации, полученной при испытании колёсных транспортных средств(КТС) на стенде с беговыми барабанами, а также для управления электронными системами стенда.', 'В настоящее время диагностику и контроль технического состояния как традиционных, так и беспилотных КТС, в том числе с электрическими и гибридными силовыми установками, с автоматизированными агрегатами и интеллектуальными системами осуществляют при помощи сканеров и, как правило, в дорожных условиях. Однако, исследования, проведённые ранее, убедительно показывает наличие системных проблем при определении их технического состояния. Обусловлено это во многом тем, что уровень конструктивной сложности традиционных и беспилотных КТС непрерывно растет. При этом требования к безопасности КТС постоянно ужесточаются. Поэтому качество контроля технического состояния КТС во многом определяет безопасность автомобильного транспорта. Для контроля технического состояния КТС давно уже недостаточно применения электронных сканеров, поскольку они не дают полного объема необходимой информации: о безопасности, о техническом состоянии их агрегатов и систем, о мощностных характеристиках, о техническом состоянии ходовой части и подвески, а также об эффективности работы их интеллектуальных систем.\nДля эффективного контроля современных КТС требуется наукоемкое оборудование, способное обеспечивать контролируемым КТС заданные тестовые режимы – «разгон», «торможение», «боковой занос», «движение под нагрузкой» и пр. Использовать для этих целей современные стенды нет возможности по причине того, что они морально устарели, либо имеют очень высокую стоимость. К тому же практически все современные стенды являются зарубежными. Существующие стенды для контроля КТС имеют ограниченный функционал. Для качественного контроля КТС измерение силовых и кинематических параметров необходимо проводить индивидуально на каждом колесе колёсных транспортных средств с достаточной точностью. Для этого необходимо создать корректные тестовые воздействия, при которых колёсное транспортное средство на стенде будет функционировать как в реальных дорожных условиях. Для решения вышеперечисленных проблем на кафедре Автомобильного транспорта был разработан и изготовлен опытный образец стенда, представляющий собой диагностическое стендовое оборудование, которое способно реализовать высокоэффективные методы контроля технического состояния современных КТС. Опытный образец имеет сложные механические, электрические и пневматические системы, электронные системы измерения контролируемых параметров и системы управления стендом. Функционирование стенда сопровождается большим количеством контролируемых, измеряемых и управляющих параметров процесса испытания автомобиля, которые должны быть обработаны одновременно. Поэтому для его полноценной эксплуатации остро стоит вопрос о разработке ПК, способного управлять стендом, а также регистрировать, контролировать, обрабатывать и сохранять диагностическую и контрольную информацию, полученную при испытании КТС.\n', 2, '2022-09-01', '2023-05-30', '', 'Ориентировочно грант РНФ, заявка № 22-79-00166, зарегистрирована: 09.03.2022 г.; электронный документ подписан: 10.03.2022 г.', NULL, 'Комплекс программ (ПК), входящий в состав диагностического оборудования.', 'Знания: устройства и принципа работы средств технического диагностирования; устройства и принципов работы дополнительного технологического оборудования; рациональных методов эффективной эксплуатации, а также технологических процессов поддержания и восстановления работоспособности подвижного состава автотранспортных средств, их агрегатов, механизмов, узлов.\nУмения: разрабатывать структурные, электрические и кинематические схемы систем технологического оборудования; проводить диагностирование и контроль технического состояния подвижного состава автотранспортных средств.\nНавыки: проведения испытаний электронных систем технологического оборудования; проведения контроля технического состояния и диагностики подвижного состава автотранспортных средств, их агрегатов, механизмов, узлов.\n', 'Яньков Олег Сергеевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(32, NULL, NULL, 'Разработка стенда и методики для исследования смазывающих свойств нефтепродуктов', 15, 'Изучение смазывающих свойств нефтепродуктов и разработка методики исследования смазывающих свойств нефтепродуктов', 'Все знают, что смазочные материалы изменяют свои характеристики в процессе работы, так как оно подвергается высокому давлению, температуре и многим другим факторам. На сегодняшний день производство смазочных материалов происходит одновременно с совершенствованием машин. В связи с современной тенденцией понижения выбросов вредных веществ в окружающую среду, а также экономии смазочных материалов выдвигают жесткие требования к качеству смазочных материалов.\nСмазочные материалы в машинах выполняют множество ролей: уменьшение и защиту от сухого трения, защита от возникновения коррозии, за счет антикоррозионных присадок, охлаждение трущихся деталей и вывод продуктов износа.\nВ наше время, существует множество различных брендов смазочных материалов, обладающих различными противозадирными и противоизносными свойствами. Поэтому для различных типов машин с различными свойствами среды, подходят разные виды смазочных материалов с разными присадками.\nПоэтому существует проблема – снижение износа поверхностей, подвергающихся трению и нагрузкам. Это позволит продлить срок эксплуатации деталей механизмов, сделает их более долговечными и надежными. В ряде случаев смазки применяются не только для снижения износа, но  и для предотвращения трения и заклинивания смежных поверхностей. Благодаря своей пластичности и составу эти мазки защищают от проникновения агрессивных веществ, газов и паров. Также практически все консистентные смазки отличаются антикоррозионными свойствами и т.д. Необходимо расширять сырьевую базу и увеличивать рабочий диапазон применения пластичных смазок.\n', 2, '2022-09-01', '2023-05-30', '', 'ООО «ПолитехГидравлика»', NULL, 'Масла, пластичные смазки, топлива с заданными смазывающими свойствами. Позволит расширить характеристики данных нефтепродуктов.', 'Знания: методология исследования\nУмения: исследовать свойства нефтепродуктов\nНавыки: правильно подходить к выбору гсм\n', 'Стрельников Александр Николаевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(33, NULL, NULL, 'Изучение свойств  материалов масляных фильтров\nИзучение свойств  фильтрующих материалов применяемых в масляных фильтрах\n', 15, 'Разработка методики исследования свойств материалов и определение (Изучение) качеств материалов масляных фильтров', 'В рамках международных стандартов к масляным фильтрам предъявляется немало требований: Фильтрующие элементы к ним должны соответствовать требованиям настоящего стандарта и конструкторской документации (КД), утвержденной в установленном порядке. Полнота отсевов фильтров и фильтрующих элементов должна быть не менее 25 %. Зависимость тонкости отсева от полноты ГОСТ Р 53844—2010 4.3 Ресурс фильтрующего элемента до замены (для 1 категории условий эксплуатации) по ГОСТ 21624 устанавливают в руководстве (инструкции) по эксплуатации автомобиля, при этом он должен быть не менее 250 ч работы двигателя. Гидравлическое сопротивление фильтрующего элемента и перепускного клапана, определяемое из их гидравлических характеристик при заданном расходе масла, должно быть не больше значения, указанного в КД. Фильтрующий элемент должен выдерживать без разрушения повышенный перепад давления (АР), равный не менее 2,0 АР начала открытия перепускного клапана фильтра. Фильтры должны выдерживать без нарушения давление не менее 3 Рном. Давление начала открытия перепускного клапана должно находиться в пределах, установленных требованиями КД. Фильтрующие элементы должны быть вибростойкими к пульсации давления и сохранять работоспособность при температурах от минус 50 °С до плюс 135 °С. Фильтрующие элементы, их уплотнения и другие детали должны быть масло-, бензо-, водостойкими. Материалы, используемые для изготовления фильтров и их элементов, не должны выделять в поток фильтруемого масла составляющих компонентов. \nВ наше время, существует множество различных брендов фильтрующих материалов, обладающих различными свойствами, но не все отвечающие определенным требованиям. Поэтому для различных типов машин работающих в различными средах и на различных режимах, требуются фильтрующие элементы отвечающие определенным требованиям\nПоэтому существует проблема- подбор фильтрующего элемента отвечающего определенным требованиям\n', 2, '2022-09-01', '2023-05-30', '', 'ООО «Тимбермаш Байкал»', NULL, 'Полученные результаты исследования позволят правильно подбирать фильтрующий элемент для определенного вида оборудования', 'Знания: методология исследования\nУмения: исследовать совйства фильтрующего материала\nНавыки: правильно подходить к выбору фильтрующего элемента\n', 'Стрельников Александр Николаевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(34, NULL, NULL, 'Разработка резонансного виброгрохота', 15, 'Повышение энергоэффективности виброгрохота', 'В сырьевых и перерабатывающих отраслях промышленности для транспортирования и переработки различных сыпучих и кусковых материалов широко применяются вибрационные транспортно-технологические машины (ВТТМ). Самой представительной группой ВТТМ являются вибрационные грохоты. Традиционные виброгрохоты с дебалансным, кинематическим и электромагнитным приводами имеют невысокие технические и эксплуатационные показатели. Значительная часть вибрационного оборудования, выполняющего данные технологические операции, требует больших затрат энергии. Кроме этого имеется ряд проблем с самой обработкой материалов, в частности разделение и сортировка труднопросеиваемых материалов, самоочистка сит, дезинтеграция агломератов.\nБольшинство конструкций современных вибрационных грохотов для возбуждения колебаний используют дебалансные вибраторы и зарезонансный режим работы. В колебательной системе таких машин циркулирует большая реактивная мощность, необходимая для преодоления инерционных сил, что снижает их энергетическую эффективность.\n Повышение производительности и снижения энергетических затрат вибрационного грохота возможно благодаря явлению резонанса. В резонансном режиме работы вибрационной машины упругие и инерционные силы взаимно уравновешиваются, при этом энергия вибровозбудителя расходуется только на преодоление диссипативных сил, а рабочий орган совершает движение, близкое к собственному. \nОсновной трудностью практического использования резонансных вибрационных машин является высокая чувствительность к изменению технологической нагрузки и параметров колебательной системы. Нелинейность технологической нагрузки препятствует решению проблемы стабилизации резонансного режима работы машин при вынужденных колебаниях даже при помощи средств автоматической подстройки. \n', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Физическая модель резонансного виброгрохота. Результаты экспериментальных исследований. Методики расчета резонансного виброгрохота. ', 'Знания: расширенные знания в области вибрационной техники\nУмения: умение реализовать теоретические знания в конкретном проекте\nНавыки: навыки работы в творческом коллективе \n', 'Зедгенизов В.Г.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(35, NULL, NULL, 'Исследование проблем прочности деталей, изготовленных с применением цифровых производственных технологий', 15, '1)Разработать образцы для исследования проблем прочности деталей, выполненных с помощью 3D – печати. 2)Сформировать корректные расчётные схемы авиационного узла в цифровом формате, позволяющие получить достоверную оценку параметров прочности и жёсткости узла ', 'Передовые технологии производственных процессов невозможны без их цифровизации. Это актуально для авиастроения, автомобилестроения, энергетической отрасли, приборостроения, медицины и др. Многие задачи в этих случаях позволяют решить аддитивные технологии (3d-печать). Они позволяют получать детали практически любой геометрической формы и габаритов. Появилась возможность трансформации сборочной единицы в деталь. В противовес традиционным вычитающим и формообразующим технологиям с помощью 3d-печати деталь «выращивают». Весь этот процесс определяется цифровой моделью изготавливаемой детали. Одной из наиболее привлекательных технологий 3d-печати является FDM-печать. Она применяется как в прототипировании, так и при изготовлении рабочих деталей. Однако, чтобы получить несущую деталь с помощью FDM-печати, нужно суметь рассчитать её на прочность. А для этого необходимо знать как на прочность влияют свойства материала печати, параметры печати, шаблон печати, процент заполнения детали и т.д. Ответы на эти вопросы можно получить, научившись работать на 3D-принтере; изучив поведение деталей, изготовленных на нём, под действием нагрузок. Для изучения поведения деталей нужны натурные и численные эксперименты. Натурные эксперименты, как правило, проводят на образцах. Значит надо изготовить с помощью FDM-печати образцы и провести их испытание на специальном оборудовании. Как правило, в качестве материала для FDM-печати применяют термопластики, композитные термопластики. Поскольку, требований к форме таких образцов пока нет, их надо разработать. Численные эксперименты требуют формирования адекватных моделей в CAD/CAE – системах (Femap, ANSYS, FIDESYS, Siemens NX, КОМПАС-3D, и др.). Под «адекватными моделями» понимаются модели, которые достоверно отображают в цифровой среде поведение реальной детали под действием реальной нагрузки. В частности, необходимо построить в цифровой среде модель натурных испытаний FDM-образцов.\nОднако, исследование прочности деталей, изготовленных с помощью традиционных технологий, не утратило своей актуальности. Основная часть конструкции самолёта образована деталями, изготовленными с помощью таких технологий. Конструкция самолёта представляет собой весьма сложную и многокомпонентную структуру, взаимное влияние между её элементами (деталями) непростое и меняется в зависимости от изменения режима работы конструкции (режима полёта, наземного режима). При этом должна обеспечиваться их прочность. Случаев нагружения одной и той же детали несколько и не все они являются явными. Следовательно, без применения цифровизации процессов исследования в сочетании с натурными испытаниями получить ответы на вопросы о причинах разрушения такой детали и разработке рекомендаций для её оптимизации очень сложно или невозможно. Под цифровизацией процессов исследования понимается применение CAD/CAE – систем. В частности, необходимо построить в цифровой среде достоверную модель реального объекта исследования; на основе её анализа сделать заключение о причинах потери прочности и дать рекомендации об устранении этих причин.\n', 2, '2022-09-01', '2023-05-30', '', 'Иркутский авиационный завод', NULL, '1. Образцы для экспериментальных исследований характеристик прочности и жёсткости деталей, изготовленных с применением FDM-печати. 2. Формирование электронной модели узла, позволяющей системно оценить параметры прочности и жёсткости с целью оптимизации конструкции узла. Фиксация материала осуществляется в форме электронной модели, сформированной в автоматизированной среде инженерного анализа и соответствующей пояснительной записке с соответствующими описаниями', 'Знания: об аддитивных технологиях применительно к изготовлению несущих деталей, с заданными механическими характеристиками; о методах расчёта авиационных деталей на прочность\nУмения: работать на 3d-принтере; определять значения параметров напряжённо-деформированного состояния реальных деталей\nНавыки: проведения натурных экспериментов для определения характеристик прочности и жёсткости; построения цифровых моделей исследуемых деталей\n', 'Распопина Вера Борисовна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(36, NULL, NULL, 'Анализ инноваций проектирования и производства беспилотных систем.', 15, 'Проектирование и анализ технологических процессов производства БПЛА', 'В настоящее время в мире в различные производства внедряется большое количество инноваций. В России внедрение осложняется необходимостью импортозамещения. К различным российским компаниям, в основном связанным с оборонным и ресурсодобывающим секторами применяются санкции, причем по продуктам, на которых в компаниях реализованы различные технологические процессы основной деятельности, В частности, это касается систем инженерного анализа и технически сложного оборудования и комплектующих. На все это накладывается  необходимость завершения текущих проектов в приемлемые сроки.\nК подобным инновациям можно отнести:\nНовые производственные технологии, к которым, например можно отнести моделирование, аддитивные технологии, которые  позволяют сократить время от идеи до реального моделирования, сократить стоимости изготовление деталей.\nВнедрение новых материалов (композиционные материалы) которые зачастую требуют создания новых специфических технологических процессов и уникального оборудования.\nВнедрение элементов искусственного интеллекта, работы с большими данными и облачные сервисы влекут за собой повышение эффективности эксплуатации изделий и производственного оборудования, повышение производительности труда, сокращение времени на поиск нужных решений\nВиртуальная и дополненная реальность позволяет на этапе электронного моделирования улучшить структурирование и качество производственных операций, сократить количество \nдефектов за счет предварительной проработки производственных процессов\nРобототехника, сенсорика и автоматизация проектирования и проведения технологических процессов  позволяют сократить, временя производства изделий, получать стабильные результаты выполняемых операций без присутствия человека.\nТаким образом, в  рамках проекта, в зависимости от состава команды и ее возможностей будут реализовываться следующие направления:\nбеспилотные системы;\nаддитивные технологии;\nоборудование инновационных технологических процессов;\nтехнология композиционных материалов;\nробототехника;\nавтоматизированные системы;\nконтроллеры и их программирование. \n', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Подготовленная заявка участия в конкурсе на получение финансирования. ', 'Знать: основы  принципов построения технологических процессов основных производств и изделий и тенденции их развития; основные программные продукты подготовки и разработки технологических процессов и изделий. \nУметь: проводить анализ перспективных технологических процессов и изделий\nВладеть навыками работы в программных продуктах, достаточных для проведения работ по анализу и подготовке технологических процессов и разработке изделий. \n', 'Дебердеев Евгений Масутович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(37, NULL, NULL, 'Разработка воздухо-воздушного теплообменника СКВ современного самолета', 15, 'Разработка рекомендаций по совершенствованию конструкции воздухо-воздушных теплообменников СКВ на основе инженерных расчетов теплообменных аппаратов с целью повышения их  эффективности,  надежности и эксплуатационного ресурса', 'В настоящее время вопросам теплообмена и его интенсификации в теплообменниках посвящены многие теоретические и экспериментальные работы. Однако усовершенствованные конструкции новых поколений авиационных турбин требуют поиска новейших более конструктивных решений, которые обеспечивали бы увеличение ресурса существующих двигателей и улучшение характеристик перспективных двигателей новых поколений.\nВ процессе проектирования рассчитывают массовые расходы теплоносителей, определяют температуры нагревающей и охлаждающей среды, коэффициенты теплопередачи и поверхность теплообмена и эффективность данного теплообменного аппарата, рассчитываются потери давления в аппарате. \n', 3, '2022-09-01', '2023-05-30', '', 'Иркутский авиационный завод', NULL, 'Проект воздухо-воздушного теплообменника СКВ на основе инженерных расчетов теплообменных аппаратов', 'Знать: основные понятия и определения тепломассообмена; методы проведения инженерных расчётов теплообменных аппаратов.\nУметь: формулировать математические задачи для теплообменных аппаратов в дифференциальной и интегральной формах.\nВладеть навыками и методами расчетов теплообменных аппаратов.\n', 'Молокова Светлана Васильевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(38, NULL, NULL, 'Прогнозирование времени задержки прибытия авиационных рейсов с помощью машинного обучения', 15, 'Разработка математической, обучаемой предиктивной модели, позволяющей по различным данным о текущей погоде, состоянию и загруженности аэропорта, и др. предсказать возможную задержку прибытия авиационного рейса и причины ее возникновения. ', 'В настоящее время ведутся активные работы по части применения методов машинного обучения и искусственного интеллекта для различных задач предсказательной аналитики. Крупный международный аэропорт в год может принять до 15 миллионов пассажиров, обслужить до 160 тысяч взлетно-посадочных операций. В таких условиях особенно остро стоит вопрос автоматизации процессов распределения воздушного и наземного трафика, регламентных работ и прочих функций с целью повышения эффективности и снижения аварийности. Генерирующиеся в процессе работы аэропорта массивы данных могут стать базой для построения различных предиктивных моделей, которые обладают высокой предсказательной силой. Результаты работы этих моделей могут быть в свою очередь использованы для информирования персонала аэропорта о возможных проблемах, пассажиров о возможных неудобствах и для понимания необходимых путей для решения данных проблем', 3, '2022-09-01', '2023-05-30', '', 'Международный Аэропорт Иркутск', NULL, 'Математическая модель прогнозирования времени задержки прибытия авиационных рейсов ', 'Знать: основные модели машинного обучения, методы их построения и валидации результатов\nУметь: работать с большими данными (Big Data) и применять полученную в ходе анализа информацию для решения прикладных инженерных задач\nВладеть навыками и методами создания и тренировки различных моделей машинного обучения \n', 'Груздев Александр Сергеевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(39, NULL, '2022-06-17 10:50:13', 'Оборудование для наземной эксплуатации авиационной техники', 15, 'Разработка аванпроекта оборудования для наземной эксплуатации авиационной техники (авиационных систем) с применением методов и средств инженерного анализа', 'Данный проект направлен на совершенствование технологии эксплуатации авиационной техники. частности, предполагается разработка проекта средств наземной эксплуатации (гидростендового и иного оборудования) с улучшенными характеристиками. Наземное оборудование – неотъемлемая часть комплекса для эксплуатации любого воздушного судна. От того, насколько наземное оборудование будет соответствовать современным требованиям по функциональности, эргономике, стоимости, и ряду других параметров, зависит в конечном счёте и стоимость эксплуатации самой авиационной техники, и, как следствие, её конкурентность на авиационном рынке.', 3, '2022-09-01', '2023-05-30', NULL, 'АО «Авиакомпания «Ангара»', NULL, 'Модель или схема наземного оборудования (гидростенда или иного оборудования).', 'Знания: о методах анализа систем по различным критериям\r\nНавыки: выполнения схем  и моделей систем.', 'Бобарика Игорь Олегович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(40, NULL, NULL, 'Оптимизация авиационных гидросистем с учётом технологии их обслуживания при эксплуатации', 15, 'Обоснование необходимости и определение путей модернизации авиационных систем с учётом эксплуатационной истории с применением современных средств инженерного анализа и предиктивной аналитики', 'Данный проект направлен на совершенствование авиационной техники, характеристик её бортовых систем. В частности, рассматривается возможность оптимизации разветвлённых трубопроводных систем, а это все гидравлические, топливные, пневматические системы, без которых не может существовать ни один современный самолёт. Все системы тесно сплетены между собой, а их характеристики обеспечивают характеристики всего самолёта в целом. Знать бортовые системы, принципы их работы, видеть возможности для их совершенствования и модернизации, разрабатывать и предлагать конкретные решения – значит быть настоящим авиационным инженером!', 2, '2022-09-01', '2023-05-30', '', 'АО «Авиакомпания «Ангара»', NULL, 'Модель бортовой системы с элементами многофакторной оптимизации.', 'Знания: о методах анализа систем по различным критериям\nНавыки: выполнения многофакторной оптимизации систем.\n', 'Бобарика Игорь Олегович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(41, NULL, NULL, 'Цифровой двойник цеха агрегатно-сборочных работ', 15, 'Создание твердотельных 3D моделей, предназначенных для создания виртуальной модели цеха агрегатно-сборочных работ, используемых для изготовления авиационных деталей', 'Создание цифрового двойника производственного помещения в образовательном сегменте позволит обеспечить доступные инструменты для пользователей и дополнить обучающие программы интерактивным визуальным контентом. Погружение студентов в производственную атмосферу, без физического присутствия на производстве.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Электронные модели авиационных узлов собираемые в сборочных приспособлениях, которые в дальнейшем будут интегрированы в программный модуль цифрового двойника', 'Знать основные технологические процессы изготовления авиационных деталей\nУметь составлять технологические процессы\nЗнание основ конструкции сборочных приспособлений\n\nЗнать основные инструменты создания 3D моделей в системе NX\nУметь использовать инструменты моделирования с заданием физико-механических свойств материала \n', 'Фокин Игорь Владимирович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(42, NULL, NULL, 'Конструкция и система управления навесными модулями настольного станка с ЧПУ', 15, 'Разработка навесного модуля для работы тангенциальным ножом илт терморезака/нихромового ножа резки композитных материалов и системы управления ими при реализации программы импортозамещения', 'Разработанный проект должен предполагать получение новых возможностей для существующего средства технологического оснащения - настольного станка. Это возможность установить новый инструмент, разработать систему для его управления.', 3, '2022-09-01', '2023-05-30', '', 'Проект \"Твой ход\", направление \"Двигаю прогресс\"', NULL, 'Модель, макет', 'Знания: основы проектирования типовых узлов и систем для станков с ЧПУ\nУмения: выполнять конструирование узлов механических приводов и электрических плат, в том числе и с помощью ЭВМ\nНавыки: прототипирования и моделирования\n', 'Казимиров Денис Юрьевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(43, NULL, NULL, 'Предварительная оценка машинного времени обработки заготовительно-штамповочной оснастки', 15, 'Создание классификатора изделий по геометрическим особенностям, влияющим на машинное время обработки заготовительно-штамповочной оснастки, и вычисление соответствующих поправочных коэффициентов', 'Заготовительно-штамповочное производство в авиационной промышленности имеет немаловажное значение, так как листовая штамповка используется для изготовления многих деталей. Оснастка заготовительно-штамповочного производства уникальная для каждого изделия. Внесение изменений в конструкцию детали требует изменения модели оснастки и изготовления нового образца, часто в кратчайшие сроки. Внесение нового приоритетного изделия в цеховое расписание требует его перестроения, для чего необходимо знать машинное время. Традиционно, машинное время вычисляется при помощи встроенных функций Unigraphics NX, но для этого требуется написание управляющей программы, что занимает значительное время. Для повышения гибкости производства целесообразно применить метод предварительной оценки машинного времени на основе скорости удаления материала. Для более точного приближения результата к реальному необходимо ввести коэффициенты, учитывающие геометрические особенности изделия и динамические характеристики оборудования, что требует проведения экспериментальных исследований.', 2, '2022-09-01', '2023-05-30', '', 'Конкурс «Твой Ход», направление «Двигаю прогресс».\nhttps://tvoyhod.online/\n', NULL, 'Методика оценки машинного времени на основе классификатора изделий и скорости удаления материала, позволяющая в краткие сроки позволить предоставить данные по машинному времени для перестроения цехового расписания', 'Знания: виды продукции, выпускаемой в цехах изготовления заготовительно-штамповочной оснастки, методики оценки машинного времени.\nУмения: работа в среде Unigraphics NX, анализ геометрической информации.\nНавыки: поиск информации, анализ информации с целью выделения требуемого знания, формирование комплексного понимания предмета изучения на основе полученной информации, системный анализ полученной информации, выделение «дефицитов» знаний и формулирование запроса на поиск новой информации.\n', 'Исаченко Алексей Сергеевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(44, NULL, NULL, 'Лопасти воздушного винта из композиционного материала', 15, 'Разработка технологии изготовления лопасти воздушного винта из композиционного материала для водной техники (аэролодка)', 'Исследование и анализ существующих геометрий лопастей для водной техники (аэролодка). Разработка геометрии лопасти в программной среде Siemens NX. Проектирование специализированной оснастки для изготовления прототипа лопасти из композиционных материалов методом вакуумной инфузии. Изготовление и подготовка оснастки. Создание прототипа лопасти из композиционного материала.', 2, '2022-09-01', '2023-05-30', '', 'ООО «ИРКУТ – АЭРО»', NULL, 'Прототип лопасти воздушного винта из композиционного материала', 'Знания: основы проектирования типовых узлов и деталей машин; основы проектирования типовых узлов и деталей машин\nУмения: выполнять конструирование типовых узлов и деталей машин, в том числе и с помощью CAD-технологий\nНавыки: выполнения инженерных и компьютерных расчётов, способами представления и анализа результатов; \n', 'Чащин Николай Сергеевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(45, NULL, NULL, 'Разработка и изготовление лабораторного комплекса и исследование процесса комбинированного формообразования подкреплённых панелей самолётов', 15, 'Опытная отработка импортонезависимой технологии формообразования крупногабаритных панелей сложной формы  ', 'Панели крыла представляют собой обводообразующие детали с гладкой наружной (аэродинамической) поверхностью. Внутренний набор деталей типа панелей содержит такие конструктивные элементы как карманы, люки с окантовками и подкрепляющие рёбра различных сечений, расположенные в продольном или в поперечном направлениях. \nПо геометрической форме панели и обшивки представляют собой совокупность линейчатых поверхностей с направляющими переменной кривизны, участков двойной и знакопеременной кривизны (зон перегиба) с закруткой сечений.\nОсновными технологическими операциями получения требуемой формы деталей является дробеударное формообразование с последующей зачисткой, а так же раскатка и посадка ребер.\nВ рамках проектных работ будет разработано, изготовлено и испытано следующее оборудование:\n- лабораторная установка для обработки методами раскатки роликами и посадки;\n- лабораторная установка для дробеударного формообразования и зачистки абразивными лепестковыми кругами.\nТакже планируется проведение опытных работ на образцах с целью отработки технологии формообразования подкреплённых панелей\n', 3, '2022-09-01', '2023-05-30', '', 'ПАО «Электромеханика»', NULL, 'Лабораторные стенды для отработки технологии формообразования деталей пита подкреплённых панелей из алюминиевых сплавов', 'Знать: основные технологические процессы формообразования и правки крупногабаритных маложестких деталей.\nУметь: проектировать специальное оборудование для реализации технологии формообразования и правки крупногабаритных маложестких деталей.\nНавыки: проектирование в Siemens NX; слесарные и сборочные работы.\n', 'Пашков Александр Андреевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(46, NULL, NULL, 'Изготовление корпусных деталей беспилотных летательных аппаратов', 15, 'Разработка технологии изготовления корпусных деталей беспилотных летательных аппаратов', 'Исследование и анализ существующих корпусных деталей беспилотных летательных аппаратов. Разработка модели корпуса в программной среде Siemens NX. Проектирование специализированной оснастки для изготовления прототипа деталей корпуса из композиционных материалов методом вакуумной инфузии. Изготовление и подготовка оснастки. Создание прототипа детали корпуса.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Прототип детали корпуса беспилотных летательных аппаратов', 'Знания: основы проектирования типовых узлов и деталей машин; основы проектирования типовых узлов и деталей машин\nУмения: выполнять конструирование типовых узлов и деталей машин, в том числе и с помощью CAD-технологий\nНавыки: выполнения инженерных и компьютерных расчётов, способами представления и анализа результатов; \n', 'Иванов Юрий Николаевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(47, NULL, NULL, 'Разработка оптимальных характеристик конструкции механизма перемещения садовых и строительных грузов весом до 250 кг. ', 15, 'Разработка работающего устройства перемещения грузов', 'Изготовленное устройство перемещения грузов должно облегчить труд пожилого контингента на дачном участке или строителей при ремонтных и строительных работах с небольшими объёмами работ. Изготовлению должно предшествовать комплекс расчетных и технологических задач, позволяющие обеспечить точное воспроизведение в действующем образце всех заложенных параметров. В рамках проекта будут освоены CAD системы, позволяющие обеспечить точное воспроизведение рассчитанного изделия. Полученные чертежи, с трёхмерной модели, позволят изготовить в металле детали на станках токарно-фрезерной группы. Для этого будет изучен инструмент и станки, подобран материал для изготовления деталей. Изучены критерии и приборы для оценки качества деталей ( шероховатость, размерных допусков и погрешностей формы, определение твёрдости, методы закалки и т.д.).', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Готовое изделие для перемещения грузов', 'Знания: Изучение CAD системы трёхмерного моделирования. Систему допусков и посадок. Методы определения твёрдости материалов и пути их достижения. Знать устройство и возможности металлорежущих станков, методы обработки материалов.\nУмения :Работать в CAD системе трёхмерного моделирования, уметь создавать детали и сборочные единицы. На основе 3D модели создавать чертежи деталей. Для изготовления деталей подбирать необходимое оборудование, инструмент и режимы резания.\nНавыки: Рациональная работа CAD системе. Работа на металлорежущих станках. Работа с приборами оценивающие  качество поверхности.\n', 'Дрожжин Сергей Николаевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(48, NULL, NULL, 'Разработка и изготовление  опытной партии многофункциональных пильных станков на модульном принципе', 15, 'Разработка рабочей и эксплуатационной документации многофункциональных пильных станков,  организация производства ', 'Многофункциональность станков обеспечивается за счет быстрой смены режущего инструмента (пильные диски для разных материалов), изменение режимов резания, наличие  сменных контейнеров для сбора разных отходов и использования специальных сменных модулей. Модульный принцип реализован в разделении конструкции станка на отдельные модули по технологическим и конструктивным свойствам. Разделение на модули является важной задачей и решается синтезом сложных систем, определения числа оптимальных функций каждого модуля. \nПроизводство пильных станков не требует сложных технологий и дорогостоящего оборудования, высокой квалификации рабочих, что подтверждается изготовлением 4х станков силами студентов в рамках выпускной работы. Модульный принцип позволяет распределить изготовление модулей на небольших предприятиях и среди индивидуальных предпринимателей, а общую сборку и испытание проводить на базе лабораторий ИрНИТУ. Расчетная стоимость производства пильного станка составляет на 2021г. 16363руб., что позволяет говорить об возможном получении прибыли при условии стоимости подобных станков на рынке 20-40тыс. руб.. Потребителями станка на рынке в первую очередь являются индивидуальные предприниматели, строительные фирмы, малые предприятия и др.. Для повышения качества, производительности и обеспечения взаимозаменяемости модулей в лаборатории спроектированы и изготовлены специальные сборочные приспособления для каждого модуля.\nТехнические решения заложенные в конструкции пильного станка имеют большой потенциал при его использовании и совершенствовании конструкции самого станка\n', 2, '2022-09-01', '2023-05-30', '', 'Патент ИрНИТУ на изобретение №2709064 «Модульный многофункциональный пильный станок» 2019г', NULL, 'Рабочая конструкторская документация, технология изготовления и готовые станки для реализации', 'Знать: основы проектирования станочного оборудования на модульном принципе, технологические процессы изготовления деталей, сборки узлов( модулей) и общей сборки станков.\nУметь: проектировать станочное оборудование, приспособлений разного назначения.\nНавыки: проектирование в Siemens NX; слесарные и сборочные работы.\n', 'Москвитин Виктор Николаевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(49, NULL, NULL, 'Разработка эскизного проекта СВП «Марс 7000», проектирование отдельных узлов и элементов ', 15, 'Создание судов на воздушной подушке для использования в условиях крайнего Севера для нужд нефтегазовой добывающей отрасли ', 'В ОКБ имени Алексеева г.Нижний Новгород разработаны и изготовлены суда на воздушной подушке разных типов и грузоподъемности. Наиболее эффективным является «Марс2000и3000» Данные аппараты рассчитаны на перевозку 20 или 30 человек. Аппараты в теплое время эксплуатируют на водных акваториях, а в зимнее время на льду и снежном покрове. Они оснащены двумя дизельными двигателями, которые обеспечивают скорость движения 50- 70 км/час.\nДля повышения грузоподъемности и скорости необходимо снижение массы конструкции корпуса и двигателей, а также повышение мощности привода. Важным фактором эффективного использования в условиях крайнего севера возможность эксплуатации при температурах минус 40-50град. Требования заказчика иметь разные модификации аппаратов: пассажирский, грузовой и грузо-пассажирский с грузовой нагрузкой более 5-10Тс.\nВ 2021-2022г. автором разработаны два проекта в виде технического предложения «Марс300» и «Марс7000» с турбо вальными газотурбинными двигателями, которые позволяют в два раза увеличить мощности привода, уменьшить массу конструкции, увеличить скорость до 90 км/час, поднять грузоподъемность до 7000кг. Важным достоинством ГТД малый вес, долговечность и высокая надежность при эксплуатации при низких температурах. Конструкция аппаратов относится к сложными ответственным транспортным средствам, включает в себя множество уникальных устройств(редукторы, силовые передачи, системы управления и т.д.). \n', 3, '2022-09-01', '2023-05-30', '', 'ОКБ имени Алексеева г.Нижний Новгород', NULL, 'Рабочая конструкторская документация, технология изготовления элементов конструкций и систем', 'Знать: основы проектирования сложных и ответственных конструкций транспортных систем, технологические процессы изготовления деталей, сборки узлов( модулей) и общей сборки.\nУметь: Разрабатывать  сборочные и деталиировочные чертежи, строить КЭМ \nНавыки: проектирование в Siemens NX;.\n', 'Москвитин Виктор Николаевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(50, NULL, NULL, 'Снежный 3Д принтер', 15, 'Разработка и сборка 3Д принтера способного печатать снегом', 'В зимний период в Иркутской области выпадает много снега, разработка устройства которое позволит печатать из снега различные объекты практического и художественного смысла', 2, '2022-09-01', '2023-05-30', '', 'ИРНИТУ ректорат', NULL, 'Прототип 3Д принтера, печатающего снегом', 'Знания: системы ЧПУ, шаговые двигателя\nУмения: Конфигурация систем с ЧПУ\nНавыки: подготовка моделей к 3Д печати, физика процесса 3Д печати\n', 'Кононенко Роман Владимирович ', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(51, NULL, NULL, 'Разработка бобинной технологии сварки с перемешиванием', 15, 'Опытная отработка технологии сварки трением с перемешиванием с использованием бобинного инструмента (инструмента с двумя заплечиками)  ', 'Традиционные технологические процессы сварки обладают целым рядом недостатков, которые в свою очередь отсутствует при использовании сварки с трением с перемешиванием (СТП). Особый интерес вызывают современные способы СТП, которые позволяют повысить качество соединений, получаемых с применением этой технологии. Одним из таких способов расширения технологических возможностей СТП является сварка с использованием бобинного инструмента (инструмента с двумя заплечиками).  \nВ рамках проектных работ будет спроектированы, изготовлены и испытаны средства технологического оснащения процесса: сварочные приспособления, сварочный инструмент.\nВ рамках проекта также планируется проведение опытных работ на образцах с целью отработки технологии бобинной сварки трением с перемешиванием.\n', 1, '2022-09-01', '2023-05-30', '', '', NULL, 'Приспособления и инструмент для реализации исследуемой технологии бобинной сварки трением с перемешиванием', 'Знать: основные технологические особенности сварки трением с перемешиванием\nУметь: проектировать специальное технологическое оборудование для реализации технологии СТП.\nНавыки: проектирование с использованием программных продуктов САD, CAE; слесарные и сборочные работы.\n', 'Тютрин Николай Орестович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(52, NULL, NULL, 'Разработка технологии изготовления алюминиевых труб с внутренним антифрикционным покрытием', 15, 'Опытная отработка импортозамещающей технологии производства алюминиевых труб для производства гильз пневмоцилиндров с повышенными эксплуатационными свойствами рабочей поверхности   ', 'Алюминиевые трубы для производства гильз пневмоцилиндров используются российскими производителями пневмооборудования, а также приобретаются эксплуатирующими организациями в ремонтных целях. При этом в Российской Федерации такая продукция не производится и приобретается за рубежом (производители – предприятия европейских стран и КНР). Традиционная технология изготовления труб для изготовления гильз пневмоцилиндров – прессование. Она отличается высокой себестоимостью, приводящей к завышенной цене готового продукта. Кроме того, изготовленные таким способом гильзы не имеют износостойкого слоя. В этой связи проект, направленный на создание технологии производства импортозамещающей продукции с повышенным ресурсом путём её изготовления центробежным литьём, является актуальным.\nВ рамках работ будет спроектированы, изготовлены и испытаны средства технологического оснащения процесса: вращающаяся изложница, плавильно-разливочный модуль.\nВ рамках проекта также планируется производство опытных образцов и испытание их эксплуатационных свойств.\n', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Опытная технологическая оснастка для реализации технологии производства алюминиевых труб методом центробежного литья с нанесением антифрикционных покрытий', 'Знать: основные технологические особенности литейных и сварочно-наплавочных технологий\nУметь: проектировать специальное технологическое оборудование для реализации технологии СТП.\nНавыки: проектирование с использованием программных продуктов САD, CAE; слесарные и сборочные работы.\n', 'Тютрин Николай Орестович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(53, NULL, NULL, 'Определение показателей качества металлоконструкций, изготавливаемых аддитивными комбинированными технологиями ', 15, 'Опытная отработка  методик и технологий определения показателей качества изделий, изготавливаемых аддитивными методами', 'Изготовленные с применением аддитивных технологий металлические детали и изделия  могут обеспечить значительное снижение веса и повышение производительности в различных отраслях промышленности. Внедрению аддитивных технологий в производство должно предшествовать решение комплекса технологических задач, позволяющих обеспечить точные и воспроизводимые характеристики изделий. В рамках проекта будут освоены различные методики определения характеристик изделий, а также  основы технологии  их аддитивного производства', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Методики оценки качества изделий при послойном аддитивном выращивании', 'Знать: показатели качества металлоконструкций, изготавливаемых аддитивными технологиями и методы их определения\nУметь: проводить комплекс необходимых исследований для  определения основных характеристик  изделий, полученных \nНавыки: работ с использованием САПР, приборами и оборудованием для исследований \n', 'Астафьева Наталья Анатольевна ', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(54, NULL, NULL, 'Обработка поверхности изделий из конструкционных материалов концентрированными источниками нагрева ', 15, 'Получение особых свойств поверхностных слоёв изделий из конструкционных материалов при воздействии концентрированными источниками нагрева', 'Проблема совершенствования технологических методов упрочнения конструкционных материалов является  актуальной  на сегодняшний день. Данный проект направлен на исследование фазовых и структурных превращений в конструкционных материалах после воздействия концентрированных источников нагрева и разработка комбинированных технологий поверхностного упрочнения с использованием плазменного и лазерного источника, обеспечивающих высокий уровень физико-механических свойств поверхностного слоя. Для этого необходимо провести комплексные исследования взаимосвязи структуры и свойств исследуемых материалов  с различной исходной микроструктурой в зонах лазерного и плазменного воздействия, сформированных при различных вариантах, условиях и энергетических параметрах непрерывного излучения, используемого с целью достижения термического упрочнения, легирования и наплавки.', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Комбинированная технология поверхностного упрочнения ( легирования, наплавки)', 'Знать: методы обработки поверхности изделий из конструкционных материалов концентрированными источниками нагрев, методы исследования структуры и свойств матеоиалов;\nУметь: проводить комплекс необходимых исследований для  установления взаимосвязей структуры и свойств исследуемых материалов  с различной исходной микроструктурой в зонах лазерного и плазменного воздействия, сформированных при различных вариантах, условиях и энергетических параметрах непрерывного излучения;\nНавыки: работы с  приборами и оборудованием для исследований, оборудованием для упрочнения, легирования и наплавки .\n', 'Астафьева Наталья Анатольевна ', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(55, NULL, '2022-08-31 10:44:08', 'Разработка методологии реверс- инжиниринга деталей', 15, 'Создание методологии разработки электронных моделей изделий методом обратного (реверсного) инжиниринга.', 'Под реверс-инжинирингом понимают процесс создания конструкторской документации на основе снятия данных с реального изделия.  В отличие от традиционных методов, метод обратного сканирования позволяет значительно сократить сроки разработки и удешевить процесс. \r\nВ условиях, когда предприятия столкнулись с необходимостью импортозамещения, разработка электронных моделей изделий, полностью подходящих под требования заказчика, весьма актуальна. \r\nВ настоящее время в ИрНИТУ поступают заказы от предприятий различного профиля на создание графического пакета документации на детали. \r\nОбучающиеся, решившие принять участие в данном проекте,  на реальных заказах от АО «АНХК» пройдут весь путь от трехмерного сканирования деталей  до создания  рабочей документации.', 2, '2022-09-01', '2023-05-30', NULL, 'АО «АНХК»', NULL, 'Создание электронных моделей деталей методом реверс-инжиниринга', 'Знания: методов снятия  и обработки графической информации с образца изделия\r\nУмения: продумывать последовательность обработки графической информации об объекте с целью максимально эффективного создания его модели\r\nНавыки: работы с 3d сканером, обработки результатов сканирования, работы с графическим ПО для создания электронной модели изделия', 'Клименкова Светлана Богдановна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(56, NULL, NULL, 'Проектирование кулисно-рычажных механизмов убирающегося шасси самолета.', 15, 'Разработать методику расчета механизма с качающимся гидроцилиндром.', 'Механизмы убирающегося шасси самолета представлены структурными схемами в сборнике механизмов Артоболевского И.И. «Механизмы в современной технике» , 1352-1375, в количестве 23 вариантов. Данные схемы включают в свою конструкцию гидроцилиндры, что классифицирует их как механизмы второго типа. Механизм качающегося гидроцилиндра должен быть адаптирован к различным видам расчета через преобразование его в кулисно-рычажный механизм. \nСтруктурный, кинематический и кинетостатический расчет таких механизмов отличается от исследования рычажных механизмов первого типа. Рабочие учебные программы по дисциплинам «Механика», «Теория механизмов и машин» охватывают изучение только механизмов первого типа, что не позволяет углубиться в изучение механизмов, использующихся в конкретном направлении подготовки специалистов в области конструирования и проектирования машин и механизмов. Данный проект является логическим продолжением изучения механики, устанавливающим взаимосвязь между общетехническими и  специальными дисциплинами. \n', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Методические рекомендации расчета механизмов второго типа. Комплект конструкторской документации.', 'Знания: конструкций убирающихся шасси самолета; ЕСКД.\nУмения: проводить проектировочные расчеты; анализировать конструкцию механизма;  выбора рациональной структурной схемы механизма для возможности использования его в проектируемом сборочном узле, агрегате. \nНавыки: конструирования, проектирования, выполнения чертежей и расчетных схем с использованием CAD/CAM/CAE систем проектирования; систематизирования и анализа информации для дальнейшего продвижения, реализации полученных результатов  в конкретных методиках расчета.\n', 'Шматкова Анна Викторовна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(58, NULL, NULL, 'Разработка автоматизированной «дорожной карты» подготовки и проведения мероприятий в ИРНИТУ', 15, 'Автоматизированная «дорожная карта» подготовки и проведения мероприятий в ИРНИТУ', 'Проводимые в ИРНИТУ мероприятия различаются продолжительностью времени, необходимого для их подготовки, и пакетом оформляемых документов. На этапе подготовки мероприятия организаторы иногда упускают из вида некоторые факторы, значимые при составлении сметы и формирования других документов, необходимых для беспроблемного проведения мероприятия. Разработанная «дорожная карта» должна давать организаторам исчерпывающую информацию о каждом шаге подготовки мероприятия', 2, '2022-09-01', '2023-05-30', '', 'Институт информационных технологий и анализа данных', NULL, 'Автоматизированная «дорожная карта» подготовки и проведения мероприятий в ИРНИТУ, адаптированная под разные их виды', 'Знания: эффективное делопроизводства в современных условиях функционирования организации\nУмения: отладка процессов эффективного движения документов внутри организации\nНавыки: грамотного распределения времени и ресурсов для нормального функционирования организации\n', 'Чернышенко Марина Сергеевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(59, NULL, NULL, 'Профиль потребителя энергоресурсов.', 15, 'На основе данных ИЭСБК создать профиль потребителя энергоресурсов', 'проанализировать базу данных параметров потребителя, которую собирает ИЭСБК, оценить, какими данными еще стоит ее наполнить и из каких источников (внешних/внутренних); разработать методику формирования профиля потребителя; сформировать типы профилей и их характеристики; провести сегментацию всех потребителей по профилям; разработать методику/набор инструментов для взаимодействия (в части контроля и взыскания задолженности) с потребителем в зависимости от его профиля', 3, '2022-09-01', '2023-05-30', '', 'ООО «Эн+ Диджитал»', NULL, 'разработан набор характеристик каждого профиля, алгоритм дополнения БД недостающими характеристиками, критерии кластеризации потребителей по профилям', 'Знать: особенности потребителя энергетической продукции, причины недополучения платы за энергоуслуги.\nУметь: анализировать базы данных, синтезировать информацию\nВладеть навыками командной работы при решении проблемных ситуаций \n', 'Осипова Ирина Михайловна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(60, NULL, NULL, 'Создание корпоративной программы благополучия сотрудников «Well-being» (мобильная версия)', 15, 'Применение знаний и получение навыков в организации работы предприятия', 'Забота о благополучии сотрудников – это выгодные инвестиции в управление производительностью, повышение конкурентоспособности и корпоративной культуры компании. Подобные стратегии полезны для крупного, малого и среднего бизнеса, который нацелен привлекать и удерживать ценные кадры, а также максимально раскрывать их потенциал в работе на благо компании.', 3, '2022-09-01', '2023-05-30', '', 'АО «ЭнСер»', NULL, 'Создание мобильного приложения по Well-being в стиле Agile, с возможностью дополнения инициатив в виде конструктора', 'Знания: знать методы сбора, анализа, систематизации, хранения информации предприятия\nУмения: уметь, в соответствии с поставленной задачей, выявлять критерии оценки и отбора информации\nНавыки: владеть способами получения информации из различных источников\n', 'Наумова Татьяна Александровна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(61, NULL, '2022-06-24 08:13:17', 'Модель управления стратегическими научными проектами. Компетентностная модель  ключевого исследователя (PI). Предпринимательские качества у научных работников', 15, 'Разработка модели управления стратегическими проектами исследовательской политики.  Исследование влияния предпринимательских качеств на профессиональные достижения, научных работников.', 'Проблема заключается в противоречии между возрастающим значением инновационных технологий и сохраняющейся слабостью механизмов коммерциализации знаний и инновационных разработок в России. Образовательные и научные организации чаще всего сталкиваются с низким уровнем обладания предпринимательскими способностями, которые к тому же неравномерно распределены среди научных работников. В этих условиях важно оценить влияние качеств ключевых исследователей на  научные результаты. Выстроить работающую  модель управления научными проектами.', 2, '2022-09-01', '2023-05-30', NULL, 'Проректор по научной работе Кононов А.М.', NULL, 'Апробированная модель управления стратегическими проектами в рамках исследовательской политики. Практические рекомендации по развитию определённых soft skills у различных категорий научных работников (ключевых исследователей).', 'Знания: методов проведения исследований, понятий предмета и объекта исследования\r\nУмения: постановка цели и задач исследования, определение предмета и объекта, актуальности темы исследования, выдвижение и проверка гипотезы исследования\r\nНавыки: подбор и изучение источников, обработка и анализ полученной информации, формирование результата исследования', 'Чернышенко Марина Сергеевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(62, NULL, NULL, 'Стратегическое управление ключевыми потенциалами развития территориальных социально-экономических систем ', 15, 'Стратегическое управление ключевыми потенциалами развития территориальных социально-экономических систем ', 'Стратегия необходима, поскольку будущее в основном непредсказуемо, абсолютной определенности относительно будущего нет. Современный темп изменений во внешней среде, увеличение количества знаний и информационных потоков настолько велики, что планирование стратегии представляется единственным способом формального прогнозирования будущих проблем и возможностей. \nОсновой развития территориальной социально-экономической системы выступает ее потенциал, представляющий собой совокупные возможности, способности, скрытые не реализованные резервы экономической системы. При этом стратегическое управление предполагает выбор из всей совокупности структурных составляющих потенциала развития территориальной социально-экономической системы ключевых, концентрация на которых позволит достичь максимальных долгосрочных результатов с учетом ограниченных ресурсов территории\n', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Стратегия развития территориальной социально-экономической системы', 'Знания: знать основные цели, задачи и функции стратегического планирования и управления.\nУмения: сопоставлять потенциальные возможности развития территориальных социально-экономических систем.\nНавыки: навыки использования методов разработки и принятия управленческих решений.\n', 'Баяскаланова Туяна Александровна ', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(63, NULL, NULL, '«Продвижение ИРНИТУ в социальных сетях»', 15, 'Продвижение социальных сетей ИРНИТУ среди потенциальной (абитуриентов) и существующей (студентов) целевой аудитории', 'Разработка развлекательных, познавательных и научных материалов в социальных сетях ИРНИТУ. ', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Короткометражные повторяющиеся и не повторяющиеся видеопередачи (выпуски), юмористического и познавательного содержания, призванные привлекать внимание целевых и потенциальных целевых групп. ', 'Знания: получает новые знания о сути и ходе реализации проекта, о его специфических свойствах и способах работы с видеоматериалом. \nУмения: использовать полученные навыки в ходе обучения для создания качественного видеоконтента;\nНавыки: Способен создавать  качественный развлекательный или образовательный продукт, востребованный обществом и индустрией. \n', 'Другова Елена Сергеевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(64, NULL, NULL, 'Зеленый университет', 15, '', 'Путем информирования, практических действий, журналистских расследований, других форм привлечения внимания к экологическим проблемам и практикам экоповедения, формировать у студентов и преподавателей осознанные действия, направленные на сохранение окружающей среды', 2, '2022-09-01', '2023-05-30', '', 'Министерство по молодежной политике в Иркутской области', NULL, 'Проведение 1 флэшмоба, 1 экологической акции, не менее 5 освещений в СМИ, 3 показов кинопрограмм, 2 расследования экологических практик', 'Знания: практическое освоение предметных дисциплин по основам журналистской деятельности, операторского мастерства,  сценарного и режиссерского мастерства и др.; новые знания о сути и ходе реализации проекта, о его специфических свойствах и способах работы с видеоматериалом. \nУмения: использовать полученные навыки в ходе обучения для создания журналистских продуктов:\nспециальное событие для СМИ; проведение пресс-конференций, круглых столов; создание  видеосюжетов и роликов.\nНавыки: способность формировать образ и осознанно внедрять его в реальную жизнь с помощью медийных инструментов. \n', 'Бельская Ольга Герасимовна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(65, NULL, NULL, 'Создание периодического еженедельного студенческого видеоконтента «InfoHours» в соцсетях', 15, '', 'Сформулировать взгляд молодежи на актуальные события/явления и представить его ьв виде регулярных еженедельных выпусков коротких видео в соцсетях', 2, '2022-09-01', '2023-05-30', '', 'Министерство по молодежной политике в Иркутской области', NULL, 'Размещение студенческого видеоконтента в соцсетях не менее 2 выпусков в неделю с количеством подписчиков не менее 300 человек и количеством просмотров каждого ролика не менее 50. ', 'Знания: практическое освоение предметных дисциплин по основам журналистской деятельности, операторского мастерства,  сценарного и режиссерского мастерства и др.; новые знания о сути и ходе реализации проекта, о его специфических свойствах и способах работы с видеоматериалом. \nУмения: использовать полученные навыки в ходе обучения для создания качественного видеоконтента.\nНавыки: способность создавать качественный содержательный и развлекательный продукт, востребованный обществом и индустрией. \n', 'Бельская Ольга Герасимовна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(66, NULL, NULL, 'Создание лонгрида', 15, 'Научить студентов работать в формате лонгридов, создавать объемные тексты с использованием «сквозных технологий».', 'Знания: практическое освоение предметных дисциплин по основам журналистской деятельности, операторского мастерства,  сценарного и режиссерского мастерства и др.; новые знания о сути и ходе реализации проекта, о его специфических свойствах и способах работы с видеоматериалом. \nУмения: использовать полученные навыки в ходе обучения для создания журналистских продуктов:\nспециальное событие для СМИ; проведение пресс-конференций, круглых столов; создание  видеосюжетов и роликов.\nНавыки: способность формировать образ и осознанно внедрять его в реальную жизнь с помощью медийных инструментов\n', 2, '2022-09-01', '2023-05-30', '', 'Министерство по молодежной политике в Иркутской области', NULL, 'Создание 3 лонгридов с темами определенными вместе с партнерами проекта.', 'Знания: практическое освоение предметных дисциплин по основам журналистской деятельности, операторского мастерства,  сценарного и режиссерского мастерства и др.; новые знания о сути и ходе реализации проекта, о его специфических свойствах и способах работы с видеоматериалом. \nУмения: использовать полученные навыки в ходе обучения для создания журналистских продуктов:\nспециальное событие для СМИ; проведение пресс-конференций, круглых столов; создание  видеосюжетов и роликов.\nНавыки: способность формировать образ и осознанно внедрять его в реальную жизнь с помощью медийных инструментов. \n', 'Бельская Ольга Герасимовна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(67, NULL, NULL, 'Социальный студенческий проект «Вам не стыдно?»', 15, 'Привлечение внимания представителей общественности (молодежи и взрослой аудитории) к актуальным проблемам общества.', 'Создание короткометражных видеосюжетов посвященных острым социальным проблемам современного общества всех возрастов.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Короткометражные  выпуски на социальную тему, призванные привлекать внимание целевых и потенциальных целевых групп. ', 'Знания: получает новые знания о сути и ходе реализации проекта, о его специфических свойствах и способах работы с видеоматериалом. \nУмения: использовать полученные навыки в ходе обучения для создания качественного видеоконтента;\nНавыки: Способен создавать  качественный развлекательный или образовательный продукт, востребованный обществом и индустрией. \n', 'Другова Елена Сергеевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(68, NULL, NULL, 'Современное уголовное судопроизводство: проблемы и перспективы развития', 15, 'Целью проекта является: привлечь внимание к уголовному судопроизводству, установить проблемы уголовно-процессуального права и предложить пути решения, проанализировать деятельность по расследованию и разрешению уголовных дел в современных условиях, в том числе в условиях цифровизации', 'Проект «Современное уголовное судопроизводство: проблемы и перспективы развития» представляет собой углубленное изучение уголовного судопроизводства, проблем современного состояния норм уголовно-процессуального права, совершенствование правовой регламентации отдельных институтов уголовно-процессуального права в современных условиях, в том числе в условиях цифровизации', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Или статья (опубликованная или подготовленная к публикации), или тезисы конференции (защищенные на конференции, опубликованные или подготовленные к публикации) по теме проекта. ', 'Знания: \nВ ходе выполнения проекта студенты получат знания в сфере уголовно-процессуального права, расследования и разрешения уголовных дел по существу\nУмения:\nВ ходе работы над проектом студенты приобретут умения планирования и контроля личного времени, составления содержания научно-исследовательской работы, формулирования проблемы\nНавыки:\nВ ходе работы над проектом студенты приобретут навыки работы в команде, анализа и подбора научной литературы, анализа судебной практики\n', 'Днепровская Марина Анатольевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(69, NULL, NULL, 'Защита трудовых прав граждан', 15, 'Совместная реализация задач защиты трудовых прав и интересов работников организаций', 'В ходе проекта студенты будут участвовать в интервьюировании, консультировании граждан. В подготовке методических, информационных документов, в размещении их на сайте Государственной инспекции труда Иркутской области', 3, '2022-09-01', '2023-05-30', '', 'Государственная инспекция труда Иркутской области', NULL, 'Сайт Государственной инспекции труда Иркутской области, консультирование граждан', 'Знает инструменты поиска информации.\nУмеет использовать инструменты поиска информации.\nВладеет навыками поиска информации.\nУмеет выделить из массива информации ключевые моменты.\nВладеет навыками анализа информации с целью выделения требуемого знания.\nУмеет использовать различные инструменты поиска и анализа информации.\nВладеет навыками на основе полученной первичной информации сформировать комплексное понимание предмета изучения.\nВладеет навыками выполнения системного анализа полученной информации, выделения  «дефицитов» знаний  и формулирования  запроса   на поиск новой информации.\n', 'Красноярова Елена Викторовна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70, NULL, NULL, 'Подготовка хрестоматии по трудовому праву', 15, 'Подготовка учебного пособия в помощь студентам – бакалавров ', 'В ходе проекта студенты будут участвовать в сборе информации. В подготовке методических, учебных, информационных документов, в размещении их на сайте  электронного обучения', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Хрестоматия по курсу Трудовое право', 'Знает инструменты поиска информации.\nУмеет использовать инструменты поиска информации.\nВладеет навыками поиска информации.\nУмеет выделить из массива информации ключевые моменты.\nВладеет навыками анализа информации с целью выделения требуемого знания.\nУмеет использовать различные инструменты поиска и анализа информации.\nВладеет навыками на основе полученной первичной информации сформировать комплексное понимание предмета изучения.\nВладеет навыками выполнения системного анализа полученной информации, выделения  «дефицитов» знаний  и формулирования  запроса   на поиск новой информации.\n', 'Красноярова Елена Викторовна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(71, NULL, NULL, 'Совершенствование законодательства и юридической практики в сферах геологоразведки, добычи полезных ископаемых, вторичного использования ресурсов', 15, 'Обобщение правового регулирования и результатов правоприменительной деятельности, выработка научно-практических рекомендаций по совершенствованию законодательства и юридической практики в сферах геологоразведки, добычи полезных ископаемых, вторичного использования ресурсов, в том числе в интересах субъектов малого и среднего предпринимательства , осуществляющих (намеревающихся осуществлять) деятельность по разработке техногенных месторождений, вторичного использования ресурсов, а также юниорных компаний', 'Проект имеет междисциплинарный характер, направлен на формирование у обучаемых 3 и 4 курса навыков самостоятельного решения отдельной прикладной юридической задачи, выделенной в рамках общей обширной темы, над которой работает весь проектный коллектив. Тренируется умение правильно определять межпредметные связи, увязывать теоретические аспекты юриспруденции с потребностями правовой практики, работать в команде, ориентироваться в сложном комплексном массиве нормативных правовых актов для поиска путей совершенствования правового регулирования и правоприменения. Сопутствующее умение: формулировать полученный результат в тексте – а) нормативно-правовом; б) научном.\nПроект имеет смысловые и компетенционные связи со стратегическим проектом i.GeoDesign, реализуемым ИРНИТУ в рамках программы \"Приоритет 2030\" (юридическое обеспечение умной цифровой геологии, вторичного использования природных ресурсов, формирования юниорного бизнеса).\nМожно выделить следующие основные проблемы, задачи по разрешению которых ставятся перед участниками проектной группы:\n1) Проблема внесения изменений и дополнений в ФЗ «О недрах» и ряд смежных с ним нормативных правовых актов с целью создания правовых условий для разработки техногенных отложений;\n2) Проблема совершенствования законодательства, стимулирующего предпринимательскую активность в рассматриваемой сфере и создающего условия для вторичного использования ресурсов, в том числе добычи и использования мореной древесины, использования отходов горно-промышленного производства в качестве вторичных минеральных ресурсов, использования шлако-зольных отходов энергетики, использования отходов лесопереработки, использования вторичного сырья в производстве строительных материалов.\n3) Проблема развития правовой базы создания и деятельности юниорных компаний (малых геологоразведовательных компаний с элементом рискового бизнеса, работающих в сфере поиска и освоения малых месторождений полезных ископаемых).\n', 3, '2022-09-01', '2023-05-30', '', '', NULL, '1) Проекты федеральных законов и иных нормативных правовых актов – могут быть внесены в качестве законотворческих инициатив в соответствующие органы государственной власти. На первоначальном этапе могут быть представлены для участия в ежегодном конкурсе «Моя законотворческая инициатива», проводимом Государственной Думой ФС РФ совместно с НС «Интеграция». Решают практические задачи совершенствования законодательства в сферах геологоразведки, добычи полезных ископаемых, вторичного использования ресурсов, повышения эффективности правового регулирования, в том числе в интересах субъектов малого и среднего предпринимательства , осуществляющих (намеревающихся осуществлять) деятельность по разработке техногенных месторождений, использованию вторичных ресурсов, а также юниорных компаний.\n2) Научно-практические рекомендации по юридическому стимулированию предпринимательской активности, а также по совершенствованию правоприменительной  практики органов государственного управления. Могут быть представлены в виде: 1)  серии выступлений на научных форумах и научных публикаций студентов – участников проекта; 2) итогового обзора научно-практических  результатов проекта, направленного в заинтересованные органы исполнительной власти. Решают практические задачи поддержки малого и среднего предпринимательства, а также совершенствования правоприменительной (в том числе разрешительно-лицензионной и контрольно-надзорной) практики в сферах геологоразведки и добычи полезных ископаемых, повышения ее эффективности, в том числе в интересах субъектов малого и среднего предпринимательства , осуществляющих (намеревающихся осуществлять) деятельность по вторичному использованию ресурсов, разработке техногенных месторождений, юниорных компаний.\n', 'Знания: \n– современных инструментов поиска информации;\n– сущности проекта и его основных этапов;\n– основных требований  к представлению результатов проекта;\n– норм и способов осуществления социального взаимодействия;\n– основных принципов планирования и организации своей деятельности.\nУмения: \n– использовать инструменты поиска информации, прежде всего справочные правовые системы, базы судебных решений, базы статистических данных, системы геологической информации, официальные информационные системы органов государственного управления, каталоги научных библиотек; \n– выделить из массива информации ключевые моменты, необходимые для решения конкретной задачи, разрешения проблемы;\n– предварительно спланировать проект и заполнить паспорт, отражающий ключевые этапы жизненного цикла проекта;\n– спланировать и реализовать проект с учетом ресурсных ограничений и требований к результату  проекта;\n– подготовить результаты исследования, осуществленного в рамках проекта;\n– критически оценивать полученные результаты;\n– определять круг задач и решать их в соответствии с ролевой позицией в проектной группе;\n– формулировать личные цели;\n– осуществлять самооценку, выполнять критический анализ и формулировать перечень недостающих  знаний, необходимых для достижения целей.\n\nНавыки:\n– поиска необходимой для решения практических задач информации в справочных правовых системах, базах судебных решений, системах геологической информации, официальных информационных системах органов государственного управления; научных библиотеках; базах статистических данных и иных источниках;\n- анализа информации, обнаружения и использования ее элементов, необходимых для решения конкретной задачи, разрешения проблемы;\n– формирования комплексного понимания предмета изучения на основе полученной первичной информации;\n– системного анализа полученной информации, выделения и восполнения «дефицитов» знаний, формулирования  запросов  на поиск новой информации в соответствии с поставленной задачей;\n– презентации проекта и его результатов;\n– самоанализа, адекватной оценки личного вклада в достигнутые результаты;\n– определения и постановки задач, их решения в соответствии с ролевой позицией в проектной группе;\n– социального взаимодействия как с членами команды, так и с внешними стейкхолдерами;\n– рефлексии;\n– четкого формулирования запроса на поиск новых знаний;\n– итоговой оценки своего вклада в реализованный проект, работы над недостатками.\n', 'Мушинский Михаил Адеилович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(72, NULL, '2022-08-30 03:52:24', 'Проблемы применения гражданского законодательства', 15, 'Отработка практических навыков толкования и применения норм гражданского законодательства в области вещного, обязательственного и корпоративного права', 'Выработка навыков правовой оценки ситуаций и практического применения гражданского законодательства, а также использования материалов судебной практики;  выработка навыков составления гражданско-правовых документов; формирование навыков подготовки квалификационных и научных работ по цивилистической тематике', 3, '2022-09-01', '2023-05-30', NULL, NULL, NULL, 'Опубликование научных статей \r\nВыступление на научных конференциях\r\nРазработка практического пособия по актуальным вопросам применения гражданского законодательства', 'Знания: закономерностей гражданско-правового регулирования в Российской Федерации и в зарубежных странах; правил применения нормативных правовых актов и реализации норм материального права, правил подготовки юридических документов;\r\nУмения: правильно определять факты, события и обстоятельства с целью их квалификации; использовать различные способы толкования норм гражданского законодательства; анализировать и правильно применять гражданско-правовые нормативные акты;\r\nНавыки: владения юридической терминологией; методикой анализа правоприменительной практики; методикой разрешения правовых проблем и коллизий; самостоятельной научной работы и овладение методикой проведения исследований при решении правовых вопросов', 'Пахаруков Александр Анатольевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(73, NULL, '2022-08-30 09:43:40', 'Совершенствование уголовно-исполнительного законодательства', 15, 'Проведение индивидуальных углубленных сравнительных исследований цивилистической доктрины и законодательства о банкротстве стран ближнего зарубежья', 'без описания', 3, '2022-09-01', '2023-05-30', NULL, NULL, NULL, 'Опубликование научных статей \r\nВыступление на научных конференциях\r\nРазработка практического пособия по актуальным вопросам применения законодательства о банкротстве', 'Знания: основные направления и тенденции развития законодательства о банкротстве, учения и концепции в этой научной сфере, их преемственность и эволюцию, содержание работ наиболее известных юристов;  основные закономерности возникновения, функционирования и развития конкурсных правоотношений;\r\nУмения: оперативно разрешать правовые проблемы, возникающие при реализации процедур банкротства;\r\nНавыки:  методологией разрешения правовых коллизий и пробелов в нормах права и нормативно - правовых актах.', 'Степаненко Юрий Сергеевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(74, NULL, NULL, 'Правоохранительная деятельность в информационном пространстве ', 15, 'Выявление и анализ проблем правового регулирования в сфере использования информационных технологий, а также информационный сетей (Интернет, социальные сети и др.) правоохранительными органами при выявлении административных правонарушений и преступлений, а также иных нарушений законности  ', 'В деятельности правоохранительных органов актуальность приобретает мониторинг социальных сетей на предмет выявления преступлений и правонарушений в различных сферах жизнедеятельности общества. Данная деятельность может являться эффективной в области борьбы с преступлениями и правонарушениями. Однако большие вопросы вызывает законодательное закрепление такой деятельности. Федеральные законы и иные нормативные акты, регламентирующие деятельность правоохранительных органов, в частности, полиции, ФСБ России, Прокуратуры, не содержат норм, которые позволяли бы осуществлять мониторинг социальных сетей на предмет выявления преступлений и административных правонарушений. Необходимо подготовить предложения для законодателя по внесению изменений в Федеральные законы «О полиции», «О прокуратуре Российской Федерации», «О Федеральной службе безопасности» и др. Только внесение изменений в части применения информационных технологий в указанной сфере позволит на законных основаниях использовать мониторинг в социальных сетях в практической деятельности правоохранительных органов. Таким образом, необходимо чтобы такая деятельность осуществлялась в строгом соответствии законодательству', 2, '2022-09-01', '2023-05-30', '', 'ВС ЛУ МВД России на транспорте (консультации и оценка результата проекта), \nВсероссийский конкурс «Моя законотворческая инициатива», участие  в конкурс е, представление и защита промежуточных итогов проекта \n', NULL, 'Конкретные предложения, которые будут выработаны в процессе реализации проекта, направлены на эффективное осуществление деятельности правоохранительных органов в сфере мониторинга социальных сетей для выявления преступлений и административных правонарушений.', 'Знать: об имеющихся информационных ресурсах и  технологиях, которые используются в разных видах юридической деятельности;\nУметь:  работать с официальным интернет-порталом правовой информации pravo.gov.ru, с СПС «Гарант», СПС «Консультант Плюс», ГАС «Правосудие», с официальными сайтами органов государственной власти, с библиотечными юридическими ресурсами, пользоваться полученной с их помощью информацией;\nВладеть: навыками работы с различными информационными ресурсами.\n', 'Самусевич Алексей Геннадьевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(75, NULL, NULL, 'Защита прав потребителей', 15, 'Совершенствование законодательства в сфере защиты прав потребителей', 'Многочисленные цели государственной политики в сфере защиты прав потребителей определены Правительством Российской Федерации в Стратегии государственной политики РФ в области защиты прав потребителей на период до 2030 года и включают в себя помимо традиционных и инновационные направления, например, электронная торговля. Российская Федерация и другие страны усиливает правовое обеспечение прав потребителя, которое для бизнеса между тем выступает в качестве одного из серьезных пределов свободы профессиональной экономической деятельности. Потребительский договор коррелирует как с традиционной для коммерческого (торгового) права категорией «односторонней торговой сделкой», так и современным выделением b2c-договоров. Одновременно с этим отношения с участием потребителя подвержены сильному публичному регулированию, а устанавливаемые правила становятся неотъемлемой частью государственной регуляторной политики во всем мире, взаимодействующей не только с договорным правом, но и с антимонопольным законодательством и актами технического регулирования. В соответствии со Стратегией развития информационного общества в РФ на 2017 – 2030 гг., утвержденной Президентом страны и соответствующим распоряжением Правительства РФ от 28.07.2017 №1632-р, она затрагивает все сферы экономической жизни, в том числе и сферу потребления. В связи с вышеизложенным, отмечаются значительные пробелы в законодательстве в части правового регулирования отношений с участием потребителей.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Научная статья, рекомендации для потребителей', 'Знания: \nЗнает инструменты поиска информации. \nЗнает основные требования  к представлению результатов проекта.\nУмеет подготовить результаты.\nЗнает основные ресурсные ограничения проекта.\nЗнает нормы и способы социального взаимодействия.\nЗнает основные принципы планирования и организации своей деятельности. \n\nУмения:\nУмеет выделить из массива информации ключевые моменты.\nУмеет использовать различные инструменты поиска и анализа информации.\nУмеет использовать основные инструменты планирования и реализации проекта с учетом основных этапов  жизненного цикла проекта.\nУмеет спланировать и реализовать проект с учетом ресурсных ограничений и требований к результату  проекта.\nУмеет критически оценивать полученные результаты.\nУмеет решать задачи в соответствии с ролевой позицией.\nУмеет формулировать личные цели.\nУмеет планировать и организовывать свою деятельность на основе приоритетов и поставленных целей.\nУмеет выполнять критический анализ и сформулировать перечень недостающих  знаний, необходимых для достижения целей.\nУмеет пользоваться основными инструментами организации рефлексии.\n\nНавыки:\nВладеет навыками поиска информации.\nВладеет навыками анализа информации с целью выделения требуемого знания.\nВладеет навыками на основе полученной первичной информации сформировать комплексное понимание предмета изучения.\nВладеет навыками  выполнения системного анализа полученной информации, выделения  «дефицитов» знаний  и формулирования  запроса   на поиск новой информации.\nВладеет навыками презентации результатов проекта.\nВладеет навыками самоанализа и может оценить личный вклад в достигнутых результатах.\nВладеет навыками определения и постановки задач.\nВладеет навыками рефлексии.\nВладеет навыками четкого формулирования запроса на поиск новых знаний.\n', 'Степаненко О.Г', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(76, NULL, NULL, 'Цифровые криминалистические лаборатории', 15, 'Применение теоритических знаний в практической деятельности', 'Цифровая криминалистика широко используется в уголовном праве, уголовном процессе, криминалистике, гражданском процессе, судебной медицине и психиатрии, теории судебных экспертиз. Создание криминалистического полигона с минилабораториями, в которых, будет происходить моделирование преступной ситуации, проведение анализа места преступления, выявление фактов и обстоятельств, сбор доказательств, исследование доказательств и т.д. В том числе возможность ознакомления абитуриентов с направлением юриспруденции (профориентационная школа), проведение мастер-классов.', 3, '2022-09-01', '2023-05-30', '', 'грант ИРНИТУ', NULL, 'Криминалистическая лаборатория', 'Умеет выделить из массива информации ключевые моменты.\nВладеет навыками анализа информации с целью выделения требуемого знания.\n', 'Туркова Валентина Николаевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(77, NULL, NULL, 'Осуществление права государственной и муниципальной собственности  в условиях развития современного гражданского законодательства', 15, 'Повышение уровня профессиональной грамотности в  сфере осуществления права государственной и муниципальной собственности  в условиях современного гражданского законодательства', 'Проводимая реформа гражданского законодательства позволила выявить целый ряд проблем, как теоретического, так и  правоприменительного характера, непосредственно связанных с институтом публичной собственности. Наметившаяся трансформация вещных правоотношений является, в том числе  результатом развития и модернизации  экономических отношений с участием государства и муниципальных образований. Вступившие в силу изменения Гражданского Кодекса Российской Федерации   заметно актуализировали вопросы, связанные с осуществлением права публичной собственности: иначе сформулированы правила в отношении неделимых и сложных вещей, в гражданский оборот введен новый объект в виде единого недвижимого комплекса, который, обладая признаками непотребляемости и неделимости способен увеличить доходную часть государственных и муниципальных бюджетов. Появление новых механизмов призвано обеспечить провозглашенную законодателем самостоятельность муниципальных образований, и как следствие, эффективное осуществление права муниципальной собственности. Вместе с тем, изменение структурных элементов возникающих при этом вещных правоотношений, вызывает потребность в дальнейшем их исследовании с целью разработки теоретических предложений, направленных на совершенствование норм гражданского законодательства и правоприменительной практики. \nЯвляясь гражданско-правовым институтом, публичная собственность регулируется нормами различной отраслевой принадлежности, в совокупности составляющими комплексный законодательный институт. Особенность правовой регламентации неизбежно влечет за собой  возникновение коллизий, устранение которых требует теоретического осмысления и, как результата – научно обоснованных рекомендаций по совершенствованию действующего законодательства. При всей важности прочих отраслевых научных изысканий наиболее плодотворный результат исследования может быть получен путем изучения данных отношений через призму гражданского права в виду содержательного их наполнения и правовой природы.\nБолее того, ВУЗ, в котором обучаются студенты по своей организационно-правовой форме является учреждением, а это именно тот субъект имущественных отношений, который наделяется публичной собственностью. \n', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Учебное пособие, научная статья', 'Знания: Знать инструменты поиска информации. \nУмения: Уметь использовать инструменты поиска информации, выделить из массива информации ключевые моменты.\nНавыки: Владеть навыками анализа информации с целью выделения требуемого знания, навыками на основе полученной первичной информации сформировать комплексное понимание предмета изучения, навыками  выполнения системного анализа полученной информации, выделения  «дефицитов» знаний  и формулирования  запроса   на поиск новой информации\n', 'Чердакова Лариса Анатольевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(78, NULL, NULL, 'Оценка эффективности инвестиционного проекта для развития туристического бизнеса  в регионе(на примере строительства базы отдыха с агронаправленностью)', 15, 'Оценки эффективности инвестиционного проекта  в целях привлечения банковского кредитования для развития туристического бизнеса региона (на примере строительства базы отдыха  с агронаправленностью)', 'В условиях экономической нестабильности и недостаточности собственных финансовых ресурсов у многих экономических субъектов возникает необходимость увеличения объёмов банковского кредитования для развития туризма в Иркутской области. Со стороны бизнеса и кредитных организаций для развития   туристического бизнеса и привлечения кредитных ресурсов необходимо выявление особенностей расчёта эффективности инвестиций в туристическом бизнесе', 1, '2022-09-01', '2023-05-30', '', '', NULL, 'Продуктовым результатом проекта должен стать документ, содержащий  информационный обзор рынка туристических услуг и  оценки эффективности инвестиций с целью привлечения банковского кредитования для  развития туристической отрасли региона', 'Знания: понятие и основные этапы процесса инвестиционного банковского кредитования\nУмения: выявлять инвестиционные риски с учетом особенностей развития региона\nНавыки:  навыками анализа экономической эффективности инвестиционного проекта с учетом региональных рисков\n', 'Репинский Олег Дмитриевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(79, NULL, NULL, 'Сравнительный анализ деятельности страховых компаний на рынке страховых услуг', 15, 'Проведение анализа рынка страховых услуг с использованием комплекса показателей деятельности страховых компаний для определения результативности их деятельности.', 'В ходе осуществления проектной деятельности обучающиеся проводят мониторинг рынка страховых услуг; отбирают несколько страховых компаний для проведения сравнительного анализа; изучают и практически применяют систему показателей для выявления слабых и сильных сторон участников выборки; разрабатывают мероприятия для преодоления проблем и определения направлений дальнейшего развития страховых компаний.', 1, '2022-09-01', '2023-05-30', '', '', NULL, 'Продуктовым результатом проекта должен стать документ, содержащий характеристику страхового рынка региона; комплекс количественных и качественных показателей, используемых для сравнительного анализа нескольких страховых компаний, работающих на территории Иркутской области; мероприятия по преодолению возникших проблем и совершенствованию деятельности страховщиков на рынке страховых услуг. Документ может быть использован страховыми компаниями и их внутренними структурными подразделениями, предпринимательскими структурами и т.п.\nВ документе должны быть подробно изложены характеристики рынка страховых услуг в регионе; определены главные игроки; определены и представлены направления,  также система показателей, используемых при анализе; проведены расчеты на примере деятельности нескольких страховых компаний.\n', 'Знать: особенности страхового рынка; основные направления анализа страховой деятельности\nУметь: проводить мониторинг рынка страховых услуг; определять и рассчитывать основные показатели деятельности страховщиков  \nВладеть: приемами сравнительного; анализа основами принятия эффективных решений, направленных на развитие страхового бизнеса\n', 'Юшина Юлия Александровна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(80, NULL, NULL, 'Оценка эффективности инвестиционного проекта для развития туристического бизнеса  в регионе (на примере строительства горнолыжного курорта)', 15, 'Оценки эффективности инвестиционного проекта  в целях привлечения банковского кредитования для развития туристического бизнеса региона (на примере строительства горнолыжного курорта)', 'В условиях экономической нестабильности и недостаточности собственных финансовых ресурсов у многих экономических субъектов возникает необходимость увеличения объёмов банковского кредитования для развития туризма в Иркутской области. Со стороны бизнеса и кредитных организаций для развития   туристического бизнеса и привлечения кредитных ресурсов необходимо выявление особенностей расчёта эффективности инвестиций в туристическом бизнесе', 1, '2022-09-01', '2023-05-30', '', '', NULL, 'Продуктовым результатом проекта должен стать документ, содержащий  информационный обзор рынка туристических услуг и  оценки эффективности инвестиций с целью привлечения банковского кредитования для  развития туристической отрасли региона', 'Знания: понятие и основные этапы процесса инвестиционного банковского кредитования\nУмения: выявлять инвестиционные риски с учетом особенностей развития региона\nНавыки:  навыками анализа экономической эффективности инвестиционного проекта с учетом региональных рисков\n', 'Репинский Олег Дмитриевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(81, NULL, NULL, 'Разработка продуктовой линейки для страховой компании', 15, 'Проведение модернизации продуктового ряда страховых услуг для повышения конкурентоспособности и эффективности деятельности страховой компании', 'В ходе осуществления проектной деятельности обучающиеся проводят мониторинг и сегментацию рынка страховых услуг РФ и региона; изучают ассортиментные предложения страховых компаний; определяют достоинства и недостатки действующей системы маркетинга конкретной страховой компании; проводят модернизацию продуктового ряда и формируют ассортиментное предложение с целью повышения результирующих показателей деятельности страховщика', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Продуктовым результатом проекта должен стать документ, содержащий анализ рынка страховых продуктов и ассортиментных предложений страховщиков, а также  конкретные предложения по модернизации продуктового ряда страховой компании. Документ может быть использован страховыми компаниями и другими экономическими субъектами региона (банками, заемщиками, сопряженными предпринимательскими структурами).\nВ документе должна быть подробно изложена формализованная процедура реализации модернизированных страховых продуктов в виде базовых существенных условий (потенциальных клиентов, объектов страхования, страховых случаев, страховых сумм, тарифных условий и т.д.)\n', 'Знать: теоретические основы маркетинга; основные виды и характеристики страховых продуктов; основные условия страхового договора; показатели деятельности страховой компании и страховых операций;  \nУметь: проводить мониторинг страхового рынка и его составляющих; проводить анализ эффективности деятельности страховых компаний и страховых операций (по видам страхования); \nВладеть: приемами маркетинговых исследований; навыками составления страховых договоров и разработки практических рекомендаций для принятия эффективных решений на уровне страховой компании\n', 'Юшина Юлия Александровна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(82, NULL, NULL, 'Оценка делового климата Китайской Народной Республики', 15, 'Создание информационного контента о деловом климате КНР, с целью разработки рекомендаций для экспортеров по доступу на рынок Китая. ', 'Оценка возможностей и перспектив внешнеэкономических связей России с Китайской Народной Республикой во многом зависит от наличия и анализа информации об особенностях ведения бизнеса в стране, её рынков, товаров, услуг, обычаев, законодательства. Для эффективности внешнеэкономической деятельности, необходима характеристика делового климата Китая. Проблема состоит в том, что информация для анализа делового климата Китая находится в разных источниках и постоянно меняется в соответствии с современными условиями, требует знаний китайского языка для доступа к первичной информации.\nДанный проект направлен на создание информационного контента, включающего: обзор нормативно-правовой базы в области государственного регулирования внешнеэкономической и инвестиционной деятельности в КНР; информации о защите прав экспортеров;  рекомендации по доступу на рынок Китая; о возможностях проверки деловой репутации китайских компаний; специфические особенности ведения бизнеса в Китае, включая культурные аспекты и деловые обычаи. Анализ данной информации позволит оценить деловой климат Китайской Народной Республики, с целью принятия решений о возможностях и перспективах внешнеэкономической деятельности для российских контрагентов.\n', 1, '2022-09-01', '2023-05-30', '', '', NULL, 'Публикация статей о деловом климате Китайской Народной Республики.', 'Знания: основы внешнеэкономической деятельности, нормативные документы её регламентирующие и формы расчетов по международным сделкам;\nУмения: использовать нормативно-правовые акты для составления внешнеэкономических контрактов;\nНавыки: подбора в интересах клиентов условий договоров по внешнеэкономическим контрактам и обоснования форм расчетов по международным сделкам.\n', 'Гафарова Елена Владиславовна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(83, NULL, NULL, 'Деятельность банков и их структурных подразделений, действующих на территории Иркутской области, по привлечению вкладов населения в условиях стабилизации российской экономики', 15, 'Проанализировать стратегию работы кредитных организаций, действующих на территории Иркутской области, по привлечению вкладов населения в условиях санкций со стороны стран Запада после начала специальной военной операции российских вооруженных сил на территории Украины', 'При реализации студентами третьего курса, группы ФКБ-19-1 Института экономики, управления и права проекта «Модернизация продуктового ряда вкладов граждан, привлекаемых коммерческим банком (структурным подразделением) на территории Иркутской области» были собраны и проанализированы  данные по условиям привлечения вкладов на селения по состоянию на 1 октября 2021 года, на 1 января 2022 года и 1 апреля 2022 года. За указанный период процентные ставки в банках на территории Иркутской области выросли с 6-7 % до 20 % годовых. Столь резкий рост процентных ставок привел к значительному увеличению расходов коммерческих банков. В новом проекте нами предлагается проанализировать работу коммерческих банков по привлечению вкладов населения по мере нормализации ситуации в российской экономике', 3, '2022-09-01', '2023-05-30', '', 'Филиал «Иркутский» АО КБ «Солидарность». Управляющий филиалом Сергей Александрович Кошкин', NULL, 'Продуктовым результатом проекта должны стать три отчета о деятельности коммерческих банков и их структурных подразделений по привлечению вкладов населения на три отчетные даты: 1 октября 2022 года, 1 января 2023 года и 1 апреля 2023 года. Два отчета по состоянию на1 октября 2022 года, 1 января 2023 года будут носить промежуточный характер, а в отчете по состоянию на 1 апреля 2023 года будут подведены итоги работы проектной группы в течение года. Предполагается, что участники проекта в ходе его реализации будут участвовать в научно-практических конференциях, писать статьи в научные журналы. ', 'Знания: основные виды и характеристики банковских продуктов и услуг.\nУмения: рассчитывать основные показатели, характеризующие эффективность депозитных и кредитных операций, проводить мониторинг банковских продуктов и услуг.\nНавыки: владеть приемами маркетинговых исследований и принятия эффективных решений, направленных на развитие коммерческого банка, овладеть навыками установления конструктивных отношений со специалистами и руководителями курируемых членами проектной группы банков или их структурных подразделений.\n', 'Шаламов Георгий Александрович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(84, NULL, NULL, 'Анализ реализации внешнеэкономической деятельности России в условиях санкций и перспективы её развития.', 15, 'Исследовать состояние и перспективы развития внешнеэкономической деятельности Российской Федерации в период после введения экономических санкций ЕС и США.', 'Одним из самых жестких видов контрмер, применяемых во внешнеэкономической деятельности, являются экономические санкции. Они являются огромной угрозой безопасности станы, поскольку при их введении, сокращаются объемы экспортных и импортных поставок, рушатся логистические цепочки, закрываются производства, сужаются транспортные коридоры для международных грузов. Всё это приводит к снижению притока валютной выручки в страну и сокращению её экономического потенциала. Ограничения во внешней торговле приводят к поиску альтернативных решений во внешнеэкономической деятельности, так как внутренний межсубъектный обмен товарами и услугами не способен обеспечить оптимальных экономических показателей. Принципиально важной становится адекватная оценка разрывов спроса, производства и потенциальные способности российского бизнеса реагировать на изменение конъюнктуры отечественного и внешнего рынков. Различия в технологиях производства, структуре промежуточного и конечного потребления ресурсов, объемах создания добавленной стоимости, разветвленности и длине производственных цепочек становятся значимыми факторами как скорости выхода конкретных видов экономической деятельности на внешние рынки, так и формирования целевой поддержки конкретных видов внешнеэкономической деятельности со стороны государства. Данный проект направлен на формирование комплексного понимания современных реалий, происходящих во внешнеэкономической деятельности России в условиях санкций.', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Публикация статей о перспективах внешнеэкономической деятельности России в условиях санкций.', 'Знания: организацию и технику внешнеэкономических операций, показатели оценки экономической деятельности контрагентов, их продукции на внешнем рынке.\nУмения: анализировать экономическую деятельность контрагентов, учитывая базы данных внешних рынков\nНавыки: владеть методами оценки состояния товарно-сырьевых и финансовых рынков.\n', 'Гафарова Елена Владиславовна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(85, NULL, NULL, 'Оценка бюджетной самостоятельности муниципальных образований Иркутской области', 15, 'Разработка предложений по повышению бюджетной самостоятельности муниципальных образований Иркутской области', 'На современном этапе значительная часть муниципальных бюджетов, образующих финансовую основу местного самоуправления не располагают достаточным для полноценного финансирования предусмотренных расходов объемом финансовых ресурсов. Основными причинами являются неравномерное распределение источников бюджетных поступлений по уровням власти, диспропорции межбюджетных отношений в стране. В то же время местные бюджеты являются одним из главных каналов доведения конечных результатов производства до населения. Через них осуществляется распределение общественных фондов между отдельными группами населения, финансирование непроизводственной и производственной сфер. Все эти мероприятия можно реализовывать лишь при  достаточном объеме финансовых средств.', 1, '2022-09-01', '2023-05-30', '', '', NULL, 'Информационный отчет, презентация', 'Знания:\nтенденции и проблемы формирования доходов и расходов муниципальных бюджетов\nУмения:\nрассчитывать основные экономические показатели,   характеризующие исполнение бюджетов по доходам и расходам                              \nНавыки: \nвладеть приемами  анализа  основных экономических показателей бюджетов с точки зрения достижения целевых показателей\n', 'Антипин Дмитрий Алексеевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(87, NULL, NULL, 'Формирование и развитие системы оценки эффективности управления местными бюджетами', 15, 'Развитие теоретических и методических основ оценки эффективности управления бюджетами муниципальных образований для разработки комплексной системы оценки, имеющей существенное значение для развития механизма управления местными бюджетами', 'Проект нацелен на разработку системного подхода к формированию оценки эффективности управления местными бюджетами, основанного на уточненных теоретических положениях, учитывающих особенности управления бюджетами муниципальных образований и методического инструментария оценки эффективности управления местными бюджетами', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Разработка методики оценки эффективности управления бюджетами муниципальных образований, системы показателей оценки эффективности, предложений по совершенствованию системы оценки эффективности управления местными бюджетами, направленных на повышение эффективности управления местными бюджетами', 'Знания: \nЗнать основные ресурсные ограничения проекта\nЗнать основные требования к представлению результатов проекта\nУмения: \nУметь выполнять критический анализ и сформулировать перечень недостающих знаний, необходимых для достижения целей\nУметь использовать различные инструменты поиска и анализа информации\nУметь критически оценивать полученные результаты\nУметь определять внутренний и внешний круг стейкхолдеров для проектной команды\nУметь определять круг задач и решать их в соответствии со своей ролевой позицией\nУметь подготовить результаты\nУметь пользоваться основными инструментами организации рефлексии\nУметь спланировать и реализовать проект с учетом ресурсных ограничений и требований к результату проекта\nНавыки: \nВладеть навыками на основе полученной первичной информации сформировать комплексное понимание предмета изучения\nВладеть навыками презентации результатов проекта\nВладеть навыками определения задач и соотнесения их с ролевыми позициями\nВладеть навыками четкого формулирования запроса на поиск новых знаний.\nВладеть навыками выполнения системного анализа полученной информации, выделения «дефицитов» знаний и формулирования запроса на поиск новой информации\nВладеть навыками самоанализа и может оценить личный вклад в достигнутых результатах\nВладеть навыками социального взаимодействия как с членами команды, так и с внешними стейкхолдерами\n', 'Бацюн Наталья Владимировна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(88, NULL, NULL, 'Государственные программы как инструмент стратегического управления региональным развитием', 15, 'Диагностика причин низкой результативности программно-целевого стратегического управления региональным развитием и разработка соответствующих практических рекомендаций', 'Проект нацелен на анализ основных подходов государственного программно-целевого стратегического управления региональным развитием и оценку  качественного содержания и роли действующих и принимаемых расходных обязательств в системе межбюджетных отношений «центр – регионы». ', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Разработка методического подход к оценке структурной сбалансированности государственных программ регионального развития. Указанное исследование является определенным вкладом в развитие теории государственного управления экономикой региона', 'Знания: \nЗнать основные ресурсные ограничения проекта\nЗнать основные требования к представлению результатов проекта\nУмения: \nУметь выполнять критический анализ и сформулировать перечень недостающих знаний, необходимых для достижения целей\nУметь использовать различные инструменты поиска и анализа информации\nУметь критически оценивать полученные результаты\nУметь определять внутренний и внешний круг стейкхолдеров для проектной команды\nУметь определять круг задач и решать их в соответствии со своей ролевой позицией\nУметь подготовить результаты\nУметь пользоваться основными инструментами организации рефлексии\nУметь спланировать и реализовать проект с учетом ресурсных ограничений и требований к результату проекта\nНавыки: \nВладеть навыками на основе полученной первичной информации сформировать комплексное понимание предмета изучения\nВладеть навыками презентации результатов проекта\nВладеть навыками определения задач и соотнесения их с ролевыми позициями\nВладеть навыками четкого формулирования запроса на поиск новых знаний.\nВладеть навыками выполнения системного анализа полученной информации, выделения «дефицитов» знаний и формулирования запроса на поиск новой информации\nВладеть навыками самоанализа и может оценить личный вклад в достигнутых результатах\nВладеть навыками социального взаимодействия как с членами команды, так и с внешними стейкхолдерами\n', 'Богатырева Марина Валерьевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(89, NULL, NULL, 'Влияние энергетического перехода на эффективность работы предприятий ТЭК', 15, 'Разработка и практическое освоение методики оценки эффективности работы предприятий ТЭК в условиях энергетического перехода', 'Проект включает в себя теоретические и практические занятия, посвящённые энергетическому переходу и его влиянию на эффективность предприятий в сфере традиционного ТЭК', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Методика определения количественного влияния энергетического перехода на эффективность работы предприятий ТЭК', 'Знания: \nЗнать основные ресурсные ограничения проекта\nЗнать основные требования к представлению результатов проекта\nУмения: \nУметь выполнять критический анализ и сформулировать перечень недостающих знаний, необходимых для достижения целей\nУметь использовать различные инструменты поиска и анализа информации\nУметь критически оценивать полученные результаты\nУметь определять внутренний и внешний круг стейкхолдеров для проектной команды\nУметь определять круг задач и решать их в соответствии со своей ролевой позицией\nУметь подготовить результаты\nУметь пользоваться основными инструментами организации рефлексии\nУметь спланировать и реализовать проект с учетом ресурсных ограничений и требований к результату проекта\nНавыки: \nВладеть навыками на основе полученной первичной информации сформировать комплексное понимание предмета изучения\nВладеть навыками презентации результатов проекта\nВладеть навыками определения задач и соотнесения их с ролевыми позициями\nВладеть навыками четкого формулирования запроса на поиск новых знаний.\nВладеть навыками выполнения системного анализа полученной информации, выделения «дефицитов» знаний и формулирования запроса на поиск новой информации\nВладеть навыками самоанализа и может оценить личный вклад в достигнутых результатах\nВладеть навыками социального взаимодействия как с членами команды, так и с внешними стейкхолдерами\n', 'Колмаков Александр Евгеньевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(90, NULL, NULL, 'Формирование системы стратегического партнёрства России и Китая.', 15, 'Проведение исследования по выявлению основных целей и направлений  формирования стратегического партнерства Российской Федерации и Китайской Народной республики в различных сферах', 'Экономическое положение любой страну мира во многом определяется объемом и структурой ее внешнеэкономических связей. Развитие независимой России объективно требует вхождения ее в мировое хозяйство на принципах равноправия и взаимной выгоды в сотрудничестве. Ее современное положение в современном экономическом мировом пространстве требует немедленного улучшения ситуации. Одним из основных направлений решения этой проблемы является расширение и укрепление внешнеэкономических связей с другими странами. \nВ качестве одного из ключевых партнеров для России является Китай, который в сложной современной экономической ситуации проявляет стремление к укреплению сотрудничества. К факторам, определяющим заинтересованность Китая в России, является укрепление его позиций в мировой экономике. Формирование стратегического партнёрства с Россией позволит сформировать баланс сил для выстраивания отношений с США и другими ведущими мировыми державами. Кроме того, Россия располагает значительными природными ресурсами. Это естественное преимущество, которое через механизмы эффективной финансовой и инвестиционной политики может быть использовано для модернизации российской экономики и укрепления   экономических отношений с Китаем.\n', 1, '2022-09-01', '2023-05-30', '', '', NULL, 'Научная публикация, аналитический обзор.', 'Знания: основных методов сбора и обработки информации с использованием современных информационных технологий.\nУмения: выполнять поиск, критический анализ и синтез информации.\nНавыки: выполнение системного анализа полученной информации, определение задач и соотнесение их с ролевыми позициями.\n', 'Литвинцев Алексей Вячеславович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(91, NULL, NULL, 'Анализ политики импортозамещения в России в современных условиях.', 15, 'Проведение исследования по выявлению возможности создания импортозамещающих производств в различных отраслях экономики России с целью снижения технологической и товарной зависимости от импорта', '', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Научная публикация, аналитический обзор.', 'Знания: основных методов сбора и обработки информации с использованием современных информационных технологий.\nУмения: выполнять поиск, критический анализ и синтез информации.\nНавыки: выполнение системного анализа полученной информации, определение задач и соотнесение их с ролевыми позициями\n', 'Литвинцев Алексей Вячеславович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(92, NULL, NULL, 'Система автоматизированного модуля для САПР предназначенного для построения технологических схем работы драглайнов', 15, 'Создание программного модуля для САПР предназначенного для построения технологической схемы работы экскаваторов драглайнов с учетом конкретных горно-геологических условий.', 'При проектировании и разработке месторождений открытым способом применяется бестранспортная технология ведения вскрышных и добычных работ с использование экскаваторов драглайнов. Особенностью применения бестранспортной технологии является построение технологических схем работы экскаваторов драглайнов в конкретных горно-геологических условиях. В настоящее время построения технологических схем осуществляется в основном с применением программного продукта AutoCAD, при этом пользователь производит построение в ручном режиме, затрачивая на это существенное количество рабочего времени.\nТаким образом, для ускорения процесса проектирования и разработки технологических схем при бестранспортной технологии рациональнее перенести большую часть операций при проектировании и моделировании технологической схемы в среду автоматизированной системы, с возможностью использования в учебном процессе и на производстве.\n', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Программный модуль для САПР предназначенный для построения технологической схемы работы экскаваторов драглайнов с учетом конкретных горно-геологических условий.', 'Знания: теоретические основы при планировании проектов с учетом ограничений ресурсов.\nУмения: реализовывать проект с учётом ограничений ресурсов и представить полученные результаты проекта.\nНавыки: Владеть методами и способами планирования проектов с учетом ограничений ресурсов, а также вариантами представления результатов проекта.\n', 'Нечаев Константин Борисович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(93, NULL, NULL, 'Решение проектных задач недропользования', 15, 'Умение решать реальные проблемы горного предприятия в сфере недропользования', 'Решение реальных проблем горного предприятия с учетом специфики организации работ при разработке твердых месторождений полезных ископаемых.', 2, '2022-09-01', '2023-05-30', '', 'CASE-IN', NULL, 'Развитие компетенций проектной деятельности в недропользовании с возможностью обосновывать и принимать самостоятельное решение в области добычи твердых полезных ископаемых в недропользовании', 'Знает: особенности хозяйственной деятельности предприятий горного производства и сущность их производства, основные  модели доступа к базам данных в сети Internet, технологию автоматизации проектных работ,  административной  и  управленческой деятельности недропользования.\nУмеет: применять основные информационные технологии для проектирования, управления, связи,  поиска информации для решения прикладных задач. \nВладеет:  основными приемами  применения стандартных  программных  комплексов,  составляющих  основу  информационных технологий, в том числе самостоятельно создавать техническую документацию по решению проектных задач, с учетом всех нормативных и законодательных документов\n', 'Васильев Денис Сергеевич, Гущенко Виталий Викторович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(94, NULL, NULL, 'Разработка бизнес-планов для недропользования', 15, 'Умение определять возможности малых предприятий сферы недропользования в существующих региональных социально-экономических условиях.', 'Создание бизнес-плана с учетом специфики организации работ при разработке месторождений твердых полезных ископаемых для получения внешнего финансирования: кредит в банке, государственные гранты и субсидии, инвесторы', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Возможность обосновать и получить внешнее финансирование (кредит в банке, государственные гранты и субсидии, инвесторы) недропользователю или помочь принять решение об инвестировании (покупке лицензий) в недропользование', 'знает формы предпринимательского дела в сфере недропользования и основы маркетинга и ценообразования продукции горного производства;\nумеет использовать информацию по правовым вопросам недропользования;\nимеет представление о возможности реализации прав гражданина РФ в формировании экономического потенциала государства, а также методику оценки эффективности работы малого предприятия.\n', 'Рославцева Юлия Геннадьевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(95, NULL, NULL, 'Разработка типовых технологических схем горных работ', 15, 'Умение разрабатывать технологические схемы горных работ для различных горно-геологических условиях.', 'Создание типовых технологических схем ведения горных работ, позволяющих повысить эффективность использования горной и транспортной техники на открытых горных работах и оптимизации режимов ее работы в период эксплуатации.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Пояснительная записка с разработанными технологическими схемами для различных горногеологических условий , позволяющая  повысить эффективность использования горной и транспортной техники и оптимизировать режимы ее работы в период эксплуатации.', 'знает основные типы, характеристики и условия применения горного оборудования на разных видах работ;\nумеет устанавливать нормы выработки выемочного, транспортирующего и отвального оборудования; разрабатывать технологические схемы работы горного оборудования на основе требований правил безопасности и технической эксплуатации;\nвладеет принципами обоснования применения горного оборудования для вскрышных, добычных работ и переработки полезного ископаемого.\n', 'Рославцева Юлия Геннадьевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(96, NULL, NULL, 'Исследования Глазковского некрополя различными методами съемки и создание трехмерной модели', 15, 'На основе использования различных методов дистанционного зондирования, геофизики и наземной геодезической съемки составить трехмерную модель Глазковского некрополя.', 'Проект будет реализован в несколько этапов: съемка поверхностей некрополя, анализ полученных результатов, геофизическая съемка с использованием электроразведки, создание трехмерной модели.', 2, '2022-09-01', '2023-05-30', '', '', NULL, '3D модель Глазковского некрополя', 'Знать.\nМетоды наземной и дистанционной геодезической съемки.\nУметь. \nАнализировать полученные данные различных типов съемок местности\nВладеть. \nСпособами обработки полевых измерений\nЗнать.\nМетоды геофизической съемки\nУметь.\nПроводить геофизическую съемку (электроразведку)\nВладеть.\nМетодами интерпретации данных геофизической съемки и создания трехмерных моделей объекта\n', 'Рупосов В.Л.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(97, NULL, NULL, 'Построение алгоритмов определения объемов горных работ с применением методов цифрового моделирования', 15, 'Разработка математического аппарата для моделирования подсчета запасов и геометризации недр, составление алгоритмов решения данных задач.', 'Подсчет запасов может содержать высокую ошибку, связанную с интерпретацией данных, для снижения разброса нужно проводить моделирование, которое позволит проводить сложные расчеты в цифровом виде.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Программное обеспечение', 'Знать.\nМетоды подсчета запасов полезны ископаемых.\nУметь. \nАнализировать геометрические составляющие расположения рудных залежей\nВладеть. \nАлгоритмами анализа горно-геологических условий\nЗнать.\nМетоды определения геометрии залегания\nУметь.\nОпределить геометрические параметры рудных залежей\nВладеть.\nМатематическим методами расчета геометрических параметров месторождений\n', 'Рупосов В.Л.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(98, NULL, NULL, 'Картографо-геодезическое сопровождение проектирования объектов социальной инфраструктуры г. Иркутска', 15, 'Подготовка топографо-геодезической и картографической основы для проектирования объектов социальной инфраструктуры г. Иркутска. Визуализация пространственных данных на завершающей стадии проектирования объекта.', 'При разработке проектов размещения объектов социальной инфраструктуры необходим сбор и анализ имеющихся картографических материалов, кадастровой и градостроительной информации на территорию планируемого строительства. Для этого проводится комплекс дорогостоящих инженерно-геодезических изысканий, средства на который, должны быть запланированы в бюджете города заранее. Таким образом, начало работы над проектом может отодвинуться на 2-3 года. Выполнение данных работ силами студенческой проектной команды при формировании земельных участков и проведении изысканий под строительство детской и взрослой поликлиник в Свердловском округе г. Иркутска значительно ускорит начало работ по проектированию и сэкономит средства городского бюджета.', 2, '2022-09-01', '2023-05-30', '', 'ОГБУЗ «Иркутская городская больница № 5»', NULL, 'Картографическая основа (топографический план, план поверхности), на которой при проектировании будет фиксироваться геопространственная информация.', 'Знания: процедура формирования земельных участков под строительство; программные средства для обработки инженерно-геодезических данных\nУмения: работа с градостроительной и кадастровой документацией; составление топографических планов и тематических карт-схем\nНавыки: разработка схем вертикальной планировки и проектов организации рельефа застраиваемых территорий; подсчет объемов земляных работ.\n', 'Клевцов Евгений Валерьевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(99, NULL, NULL, 'Картографо-аэрокосмическое обеспечение проектов по землеустройству городских территорий (на примере территорий г. Иркутска)', 15, 'Разработка проекта землеустройства городской территории (микрорайона) по данным беспилотной аэросъемки, космического мониторинга и топографического картографирования. ', 'Методы аэрокосмического мониторинга и цифровой картографии применяются в земельно-кадастровых съемках. Аэрокосмические снимки позволяют определить границы территорий и произвести учет имущества. Благодаря сверхвысокому разрешению снимков можно произвести инвентаризацию небольших объектов: оборудования, инженерных сооружений и т.д. На основе полученных данных можно создать геоинформационную систему для управления земельно-кадастровыми  работами. Регулярный аэрокосмический мониторинг позволяет контролировать процесс освоения и обустройства территорий на всех этапах.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Цифровые землеустроительные карты городских территорий.', 'Знания: методика и технология создания ГИС в решении земельно-кадастровых задач, \nУмения: методы обработки аэрокосмических снимков в среде ГИС-программ.\nНавыки: работа в профессиональных ГИС-программах.\n', 'Олзоев Борис Николаевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(100, NULL, NULL, 'Дистанционное картографирование снежного покрова в горных районах (на примере хребта Кодар)', 15, 'Разработка и апробация алгоритмов автоматизированного дешифрирования снежного покрова на космических снимках различного пространственного разрешения', 'Снежный покров является важной частью климатической системы Земли, оказывая существенное влияние на её тепловой и водный баланс. Снег в горных районах средних и высоких широт имеет важное гидрологическое значение, определяя характеристики речного стока и их зависимость от метеорологических условий конкретного года. В наиболее снежные годы весенне-летнее таяние снежного покрова в горах может вызывать катастрофические паводки на предгорных и равнинных территориях, где, как правило, сосредоточены населенные пункты и важные объекты инфраструктуры. В аридных областях (например, в Средней Азии) снег в горах является важнейшим источником пресной воды для населения и развития орошаемого земледелия.  Поэтому ежегодный мониторинг снежного покрова в горах является актуальной задачей, стоящей перед многими заинтересованными организациями федерального и регионального уровня (Росгидромет, МЧС, Минприроды и др.).\nВ последнее время, с развитием спутниковых и компьютерных технологий задача мониторинга снежного покрова сводится к его автоматическому распознаванию (дешифрированию) на космических снимках и картированию. Для этого часто используются многоканальные спутниковые изображения с различным пространственным и временным разрешением (например, MODIS, Landsat TM, Landsat +ETM, Sentinel-2). Однако картографирование снежного покрова в горных районах с использованием многоканальных космических снимков требует разработки надежных алгоритмов его идентификации (дешифрирования), включая выявление ложных, но визуально и оптически схожих объектов (например, облачный покров, выходы определенных типов горных пород и др.),  которые могут приводить к ошибочному картированию. Кроме того, здесь необходимо учитывать влияние факторов существенно затрудняющих автоматическое картирование, но которые являются характерными для горных территорий (крутые склоны, затенённость, горные озера и др.).\nПроект направлен на разработку оптимального алгоритма картографирования снежного покрова в горах с использованием многоканальных космических изображений и ГИС-технологий на примере хребта Кодар. Хребет Кодар является наиболее высоким хребтом, расположенным на северо-восточном фланге Байкальской рифтовой зоны.  С южной стороны Кодар граничит с суходольной Чарской впадиной, вдоль которой проходит железнодорожная трасса Байкало-Амурской магистрали (БАМ). В последние годы БАМ активно используется для грузоперевозок и модернизируется (например, строится второй путь). Для безопасной эксплуатации участка БАМ в пределах Чарской впадины необходимо уметь прогнозировать паводковые явления, вызванные резким таянием снега в горах Кодара. Таким образом,  картирование снежного покрова Кодарского хребта в рамках данного проекта является не только актуальной методической задачей, но и имеет большую практическую значимость для развития крупных инфраструктурных проектов Российской Федерации.\n', 3, '2022-09-01', '2023-05-30', '', 'Федеральное государственное бюджетное учреждение науки Лимнологический институт Сибирского отделения Российской академии наук', NULL, 'Методика автоматического мониторинга снежного покрова на космических изображениях. Карты многолетних изменений снежного покрова хребта Кодар.', 'Знания: Основные характеристики снежного покрова, характеристики многоканальных космических снимков, методы и технологии автоматического дешифрирования снежного покрова на многоканальных снимках;\nУмения: Выполнение комплекса работ по анализу растров и автоматическому дешифрированию космических снимков;\nНавыки: Дешифрирование снежного покрова, владение методами ГИС-технологий по созданию и оформлению карт снежного покрова.\n', 'Осипов Эдуард Юрьевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(101, NULL, NULL, 'Разработка методов распознавания топографических образов на аэрофотоснимках сделанных с небольших высот с помощью БПЛА для создания цифровых карт', 15, 'Разработка программного продукта для распознавания топографических образов на аэрофотоснимках сделанных с небольших высот с помощью БПЛА для создания цифровых карт', 'Аэрофотосъемка проводится, на данный момент, постоянно и является основным инструментом съемки местности с высокой детализацией. Обработка снимков является более трудоемкий процесс, чем сама съемка. Наибольшее внимание уделяется оцифровки зданий и сооружений. Данный проект направлен на автоматизацию процесса оцифровки жилых и нежилых объектов. В результате будут получатся объекты в цифровой векторной карты.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Программное обеспечение для распознавания объектов.', 'Знать.\nМетоды создания, обучения и верификации искусственных нейронных сетей.\nУметь. \nСоздавать алгоритм обработки полученных результатов после работы искусственных нейронных сетей.\nВладеть. \nМетодами алгоритмизации процессов и методов программирования сложных программных кодов.\n', 'Рупосов В.Л.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(102, NULL, NULL, 'Ранняя диагностика возникновения критического дисбаланса вала электроагрегата для предотвращения\nкритического изгиба.\n', 15, 'Раннее оповещение машиниста экскаватора о предельном значении вибрации вала (якоря) электроагрегатов главных приводов (механизм тяги, подъёма, поворота), остановка экскаватора и предаварийное обслуживание оборудования в целях снижения затрат.', 'Входе работы необходимо разработать самописец для регистрации параметров электрической цепи электроагрегатов главных приводов. Самописец изготавливается на базе программируемого логического контроллера. Самописец совместим с картой памяти и регистрирует данные в текстовый файл. Перед отказом электроагрегата осциллограммы токов и напряжений должны принципиально менять форму. Для анализа формы сигнала разрабатывается алгоритм управления предупредительной звуковой сигнализацией.', 3, '2022-09-01', '2023-05-30', '', 'Список кейсов акселерационной программы «Лаборатория энергетики 2022»\nООО \"Компания \"Востсибуголь\". Тема №35.\n', NULL, 'Разработаны:\n1. Расчёт экономической эффективности разработки и внедрения системы онлайн диагностики вибрации вала (якоря) и оповещения оператора.\n2. Система работает с минимальной погрешностью.\n3. Оборудование системы износостойкое,\nударопрочное, адаптировано к работе в жёсткой среде,\nдиапазон температуры от +40 до -50С, сильная\nвибрация.\n', 'Знания: проблем эксплуатации горных машин с электрическим приводом. \nУмения: анализировать информацию полученную в ходе промышленного эксперимента.\nНавыки: программирования логических контроллеров и изготовления на их базе измерительных устройств.\n', 'Долгих Евгений Сергеевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(103, NULL, NULL, 'Точное определение веса загруженного угля в полувагон железнодорожного состава экскаватором \nЭКГ-5А, исключение недогруза/перегруза, увеличение грузооборота полувагонов ООО \"Разрез\n\"Черемховуголь\".\n', 15, 'Исключить недогруз/перегруз полувагонов при погрузке угля экскаватором ЭКГ-5А со штабелей участка горных работ No1 ООО \"Разрез \"Черемховуголь\", сократить время на маневровые работы локомотивами связанных с дозированием угля.', 'Входе работы необходимо выполнить моделирование электромеханической системы привода подъема карьерного экскаватора. Получить характеристику зависимости тока якорной цепи от веса груза. Разработка экспериментального макета для оценки эффективности и достоверности устройства взвешивания. Разработать электронное устройство бортового взвешивания горной массы в ковше экскаватора ЭКГ-5А. Выполнить экспериментальную проверку разработанного устройства. ', 3, '2022-09-01', '2023-05-30', '', 'Список кейсов акселерационной программы «Лаборатория энергетики 2022»\nООО \"Компания \"Востсибуголь\". Тема №34.\n', NULL, 'Разработаны:\n1. Расчёт экономической эффективности разработки и внедрения системы бортового взвешивания горной массы в ковше экскаватора ЭКГ-5А.\n2. Система работает с погрешностью не более (+/-100кг).\n3. Оборудование системы износостойкое, ударопрочное, адаптировано к работе в жёсткой среде, диапазон температуры от +40 до -50С, сильная вибрация.\n', 'Знания: проблем эксплуатации горных машин с электрическим приводом. \nУмения: анализировать информацию полученную в ходе промышленного эксперимента.\nНавыки: программирования логических контроллеров и изготовления на их базе измерительных устройств.\n', 'Долгих Евгений Сергеевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(104, NULL, NULL, 'Разработка эффективных средств защиты поверхностей емкостей транспортного и перегрузочного оборудования от прилипания и примерзания горной массы', 15, 'Примерзание пород вскрыши и угля к поверхностям транспортных сосудов (ковш экскаватора, кузов автосамосвала, ж.д. полувагон) является серьёзной проблемой для большинства горнодобывающих предприятий. Целью проекта является проведение анализа существующей ситуации: период действия проблемы, характеристики грузов и поверхностей. Предложить практические способы, позволяющие исключить примерзание вскрышных пород и угля к поверхностям транспортных сосудов.', 'В зимний период года происходит примерзание вскрышных пород к ковшам экскаваторов и кузовам автосамосвалов, что снижает производительность оборудования и приводит к простоям высокопроизводительного оборудования. Также, в указанный период происходит примерзание готовой продукции (угля) к стенкам и днищу ж.д. полувагонов. Данный фактор приводит к необходимости привлечения дополнительных ресурсов на очистку ж.д. полувагонов, увеличивает время оборота ж.д. полувагонов.', 3, '2022-09-01', '2023-05-30', '', 'ООО \"Компания \"Востсибуголь \"', NULL, 'Предложить не менее трех способов/методов решения проблемы. Провести технико-экономическое сравнение предложенных вариантов.', 'Знания: формирование у будущих электромехаников теоретических знаний по процедурным и организационным аспектам выполнения проектов в горной сфере деятельности.\nУмения: способность осуществлять критический анализ проблемных ситуаций на основе системного подхода, вырабатывать стратегию действий; управлять проектом на всех этапах его жизненного цикла, вырабатывая командную стратегию для достижения поставленной цели.\nНавыки: приобретение участниками проекта практических навыков по анализу и синтезу поиска информации; предлагать варианты альтернативных решений поставленной задачи и оценивать их достоинства и недостатки.\n', 'Храмовских Виталий Александрович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(105, NULL, NULL, 'Организация ремонта техники в зимнее время непосредственно на горных работах.', 15, 'Улучшение качества проводимых ремонтов. Улучшение культуры производства и условий труда. Обеспечить минимальны капитальные затраты. Разработать пошаговое выполнение операций по организации ремонтного места (возведение, использование, демонтаж, хранение). Произвести технико-экономическое сравнение на рынке предлагаемых укрытий и тепловых источников. Основные требования: Создать приемлемые условия для персонала при проведении ремонта. Обеспечить оптимальный температурный режим для возможности проведения сварочных, монтажных и демонтажных работ. Обеспечить мобильность и быстровозводимость ремонтных шатров. Обеспечить оптимальную вместимость шатров для техники.', 'В связи с отсутствием вместительных боксов на предприятии компании, в том числе и приближенных к горным работам, самоходную технику при проведении аварийных ремонтов приходится ремонтировать на пром. площадках под открытым небом.', 3, '2022-09-01', '2023-05-30', '', 'ООО \"Компания \"Востсибуголь \"', NULL, 'Предложены, конкретные решения с учетом перечисленных целевых показателей.\nОпределена стоимость решения.\n', 'Знания: формирование у будущих электромехаников теоретических знаний по процедурным и организационным аспектам выполнения проектов в горной сфере деятельности.\nУмения: способность осуществлять критический анализ проблемных ситуаций на основе системного подхода, вырабатывать стратегию действий; управлять проектом на всех этапах его жизненного цикла, вырабатывая командную стратегию для достижения поставленной цели.\nНавыки: приобретение участниками проекта практических навыков по анализу и синтезу поиска информации; предлагать варианты альтернативных решений поставленной задачи и оценивать их достоинства и недостатки.\n', 'Храмовских Виталий Александрович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(106, NULL, NULL, 'Проекты Сибирской школы геонаук \n1 - Моделирование и интерпретация данных магнитных съемок\n2 - Построение трехмерных геоэлектрических моделей на основе данных импульсной электроразведки', 15, '1. Разработка элементов компьютерных интерактивных технологий интерпретации данных наземных, беспилотных и аэромагнитных съемок.\n2. Выделение рудных структур по данным трехмерного моделирования нестационарных электромагнитных полей в комплексе с априорной геологической информацией.', '1. Использование детальных наземных, беспилотных и аэромагнитных съемок при поисках различных полезных ископаемых, решении задач геологического картирования и изучении археологических объектов приводит к получению больших массивов данных, характеризующих магнитные поля на участке съемки. По этим данным необходимо уметь выделять магнитные аномалии различного ранга, определять геометрические и магнитные параметры магнитных объектов, обусловливающих эти аномалии, и визуализировать результаты с использованием современных возможностей компьютерной 3D графики. Совокупность этих приемов определяет существо геологической интерпретации данных магнитных съемок, каждый этап которой требует совершенствования существующих приемов и элементов, их адаптации к геолого-геофизическим особенностям изучаемого объекта.\nИнтерпретация магнитных данных является высокотехнологичным процессом, основанным на использовании возможностей компьютерного моделирования, математического аппарата решения прямых (определение магнитных эффектов по заданным параметрам объектов) и обратных (определение параметров объектов по зарегистрированными над ними магнитными эффектами) задач магниторазведки.\nУчастие в проекте подразумевает: освоение современных программных продуктов для визуализации данных и результатов интерпретации магнитных съемок; формирование синтетических моделей и исследование на них возможностей тех или иных элементов решения обратных задач; освоение и разработка способов получения и учета априорной информации, позволяющей снизить неоднозначность решения обратной задач магниторазведки\n2. Построение трехмерных геоэлектрических моделей по параметрам удельного электрического сопротивления и поляризуемости. \nРеализуется конечноэлементное 3D моделирование геоэлектромагнитных полей с учетом разномасштабных, контрастных и, при необходимости, криволинейных (рельеф дневной поверхности) структурных частей геоэлектрической модели и геометрическую 3D инверсию, которая в ходе решения трехмерной обратной задачи позволяет определять электрофизические параметры (проводимость, поляризуемость) структурных частей геоэлектрической модели и размеры этих структурных частей. Данные для расчетов берутся из реальных производственных проектов, выполняемых сотрудниками и студентами ИРНИТУ в рамках хоз. договорных работ. \nУчастие в проекте подразумевает: освоение современного программного обеспечения для расчета трехмерной инверсии и построения геоэлектрических моделей; освоение способов учета априорной информации, позволяющей снизить неоднозначность решения обратной задачи электроразведки; получение квалификации обработчика и интерпретатора данных импульсной электроразведки современного уровня.\n\n', 3, '2022-09-01', '2023-05-30', '', 'Сибирская школа Геонаук ', NULL, '1. Обоснование, разработка и реализация законченного фрагмента технологической цепочки интерпретации данных магнитной съемки\n2. Построение трехмерных геоэлектрических моделей по реальным данных производственных проектов', 'Знать основы теории и практики интерпретации данных магнитных съемок;\nУметь использовать программные продукты и методические приемы при решении задач моделирования и интерпретации данных магнитных съемок;\nВладеть способами визуализации данных и результатов интерпретации, основами программирования и использования программных продуктов при интерпретации данных магниторазведки. \nЗнания: теоретико-методологические основы импульсной электроразведки, основы теории и практики интерпретации данных импульсной электроразведки\nУмения: использование современных программных продуктов для расчета трехмерной инверсии\nНавыки: владение приемами обработки и анализа электроразведочных данных, приемами обработки и анализа геологической и геофизической информации.\n\n', 'Давыденко Александр Юрьевич, Шкиря Михаил Сергеевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(107, NULL, NULL, 'Анализ палеогеографических условий осадконакопления с целью оценки возможности обнаружения вторичных коллекторов алмазов', 15, 'Провести анализ палеогеографических условий осадконакопления с целью оценки возможности обнаружения вторичных коллекторов алмазов для заданной территории', 'По оценкам многих производственников (АЛРОСА, РОСГЕО) и исследователей, в частности научного руководителя Института геологии и минералогии им. В.С. Соболева СО РАН академика Н.П. Похиленко (Новосибирск) добыча алмазов в России к 2040 году сократится в разы. При этом разработка россыпных месторождений полностью прекратится к 2026 году. Оценка перспектив открытия крупных месторождений алмазов в коренном залегании на территории Иркутской области пока дает отрицательные результаты (ревизионные работы института Земной коры СО РАН. ИРКУТСК 2020-2021 гг.).\nВ то же время остается возможность нахождения алмазоносных россыпей за счет формирования переотложенных коллекторов, сложенных продуктами разрушения кимберлитовых тел в пределах южной и центральной частей Сибирской платформы. Традиционно россыпные месторождения считаются более легкими и рентабельными с точки зрения их эксплуатации.\nДля оценки возможности обнаружения таких коллекторов необходимо создание базы данных по имеющимся стратиграфическим разрезам с последующим их анализом и построение палеографических карт на определенные отрезки геологического времени. \nДля реализации проекта предусматривается использование традиционных методик палеогеографического анализа. В то же время необходимо провести комплексирование, и использовать не только геологические, но и геохимические данные, которые на сегодняшний день эффективно позволяют проводить разбраковку минералов из группы спутников алмазов\n', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Верифицированные экспериментальные данные анализа палеогеографической обстановки (с фиксацией в формате пояснительной записки и графических приложение - палеогеографических схем)', 'Знания: Методики и основных приемов анализа палеографической обстановки\nУмения: Составления базы данных для проведения палеотектонического анализа\nНавыки: Составление и анализ палеографических схем\n', 'Иванова Раиса Николаевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(108, NULL, NULL, 'Инженерная геофизика', 15, 'Проведение инженерно-геофизических работ между корпусами Б и В', 'Получение геолого-геофизической информации по распределению физических свойств верхней части геологического разреза. Построение на ее основе цифровой модели изучаемого участка.', 2, '2022-09-01', '2023-05-30', '', 'Распоряжение по ИРНИТУ №5 от 18.02.2022г', NULL, 'Цифровая геолого-геофизическая модель участка исследований', 'Знания: методов получения и обработки геофизических данных \nУмения: применения геофизических методов для изучения геологического разреза\nНавыки: работы с геофизической аппаратурой и программными средствами обработки\n', 'Мироманов Андрей Викторович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(109, NULL, NULL, 'Обработка данных эколого- геохимических исследований в ГИС-приложениях', 15, 'Создание цифровых карт, необходимых для информационного обеспечения и прогнозирования экологического состояния урбанизированной территории на основе данных  эколого-геохимических исследований.', 'Идеология использования геохимических методов исследования для выявления и картирования очагов и источников техногенного загрязнения окружающей среды возникла в середине 1970-х годов на основе опыта поисковой геохимии.\nДля получения целостной картины состояния, функционирования, динамики и эволюции окружающей среды эти исследования должны носить системный характер.\nРезультатом этих исследований обычно является оценка совместимости или несовместимости природных условий и техногенных геохимических потоков, степени изменчивости и устойчивости природных систем к техногенезу. Следует отметить, что в техногенно измененных ландшафтах, особенно в промышленных и урбанизированных зонах, применение традиционных ландшафтно-геохимических подходов сталкивается со значительными методическими трудностями.\nЗа последние десятилетия накоплены огромные массивы эколого-геохимических данных, характеризующих состояние окружающей среды. По разным причинам эти данные разобщены. Использование геоинформационных технологий для обработки эколого-геохимических данных позволяет создать единое информационное пространство. Интеграционный характер геоинформационных систем (ГИС) позволяет создать на их основе мощный инструмент для сбора, хранения, систематизации, анализа и представления эколого-геохимической информации\n', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Создание с применением ГИС цифровых карт, необходимых для оценки экологического состояния урбанизированных территорий на основе данных эколого-геохимических исследований', 'Знать теоретико-методологические основы создания и использования цифровых геоизображений в региональных эколого-геохимических исследованиях;\nУметь использовать инструментарий ГИС- приложений для обработки полевых, картографических, дистанционных материалов и данных эколого - геохимических исследований и представления их в виде  цифровых тематических карт природных условии и геохимического загрязнения территорий;\nВладеть приемами обработки и анализа геоэкологической и картографической информации, включая рекомендации по средствам и практическим способам создания цифровых оценочных эколого-геохимических  карт. \n', 'Ланько Анна Викторовна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(110, NULL, NULL, 'Проекты сибирской школы Геонаук. \n1. Разработка методики геоархеологических исследований и решение археологических задач с помощью методов разведочной геофизики.', 15, '1. Разработать и апробировать методику решения археологических задач с помощью методов разведочной геофизики.\n2. Апробирование методики измерения поляризационных свойств образцов горных пород необходимой для классификации аномалиеобразующих объектов изучаемой среды', '1. Археологические исследования являются основным способом изучения древней истории человечества, выявления памятников древней истории, составляющих историко-культурное наследие государства. Современная археология базируется на широком использовании естественно-научных методов. Одними из таких методов являются методы разведочной геофизики, которые позволяют не только намного быстрее и эффективнее выявлять археологические памятники, но и изучать их особенности и характеристики. Способность геофизических методов выявлять и локализовать археологические объекты без проведения раскопочных работ делают эти методы обязательным элементом комплексных археологических исследований.\nГлавной проблемой применения методов разведочной геофизики является их адаптация для изучения самой верхней части геологического разреза и поиск эффективного по информативности и быстродействию комплекса методов. Кроме того, геофизические исследования должны носить системный характер решения археологических задач в совокупности с геолого-геохимическими и петрофизическими исследованиями.\nЗа последние десятилетия накоплен большой опыт применения геофизики археологических исследованиям, который свидетельствует о том, что не может существовать единого комплекса методов, а требуется его методическая адаптация для конкретных археологических памятников для определенных территорий. Планируемые в рамках данного проекта исследования направлены на поиск эффективного комплекса геофизических методов при изучении археологических памятников Прибайкалья.\n2. При решении задачи интерпретации геоэлектрических моделей с целью локализации рудных объектов, представленных обычно вкрапленной сульфидизацией, необходимо провести классификацию рудопроявлений и получаемых в ходе измерений характеристик.\nКачественная классификация руд строится на петрофизических исследованиях образцов горных пород, отобранных с изучаемой среды.\nЛабораторные исследования поляризационных свойств образцов горных пород в решении задач для рудной геофизики могут существенно улучшить качество прогноза и формирования более точной ФГМ.\nОднако сейчас несмотря на большой объём литературы, публикаций и общей истории методики исследования поляризационных свойств пород – в производственных работах почти не используется.\nИспользование модифицированной поляризационной модели Cole-Cole позволяет увеличить количество петрофизических параметров среды двух (УЭС и поляризуемость) до четырех: УЭС, стационарная поляризуемость, время релаксации и показатель степени. Полученные параметры необходимы для построения ФГМ, анализа трехмерных поляризующихся моделей и заложения скважин разведочного бурения.\nРазработанная лабораторная установка и методика измерений поляризационных свойств образцов горных пород нуждается в апробации результатов.', 3, '2022-09-01', '2023-05-30', '', 'Лаборатории археологии, полеоэкологии и систем жизнедеятельности ИрНИТУ, Геоархеологические исследования лаборатории геоархеологии ИГУ, Всероссийская научная конференция с международным участием имени В.В. Зайкова «Геоархеология и археологическая минералогия» г.Миасс \nСибирская школа геонаук', NULL, '1) Разработка эффективного комплекса геофизических методов при изучении археологических памятников Прибайкалья.\n2) Выявление и изучение объектов историко-культурного наследия в Прибайкалье.\n', 'Знать методы формирования комплекса геофизических исследований при решении нетрадиционных задач;\nУметь использовать геофизические методы при решении сложных, нетрадиционных задач;\nВладеть приемами обработки и анализа геологической, петрофизической и геофизической информации. \nЗнания в области петрофизических исследованиях, многомерном анализе данных.\nУмения Построение ФГМ на основе полученных данных\nНавыки работы в программах обработки сигналов, построения графиков и анализа исходных данных\n', 'Снопков Сергей Викторович, Бухалов Сергей Владимирович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(111, NULL, '2022-08-30 03:55:27', 'Методика прогноза изменения уровня подземных вод при строительстве инженерных сооружений с перезаглубленными фундаментами', 15, 'Разработка методики оперативного прогноза изменения гидродинамического режима грунтовых вод в результате барражного эффекта, создаваемого сооружениями с фундаментами глубокого заложения для принятия инженерных решений на начальных стадиях разработки архитектурно-строительных проектов.', 'На территориях с незначительной глубиной положения уровня грунтовых вод (УГВ) строительство зданий, имеющих фундаменты глубокого заложения, в результате «барражного» эффекта приводит к повышению риска подтопления смежных участков с находящимися на них сооружениями. Барражный эффект – это подъем УГВ перед преградой по потоку и его снижение за ней вследствие перекрытия фильтрационного потока подземных вод (ПВ). В зависимости от гидрогеологических характеристик перекрытого водоносного горизонта и габаритов инженерного сооружения величина подпора может изменяться от нескольких сантиметров до метров и может приводить к деформациям грунтового массива, подтоплению территории и расположенных рядом зданий и сооружений, а также другим неблагоприятным последствиям. \r\nПодтопление, связанное с барражным эффектом, широко развито на территориях современных городов, где застраиваются не только окраинные площади, но и историко-культурные зоны, от чего страдают фундаменты старых зданий и часто разрушаются исторические постройки.\r\nПроект направлен на выделение основных причин изменения гидрогеологических условий городских территорий (на примере центральной части г.Иркутска), а также факторов, определяющих формирование техногенного гидродинамического режима.\r\nСложность геолого-гидрогеологических условий и разноплановость задачи предопределяет необходимость использования современных технологий хранения и обработки информации', 2, '2022-09-01', '2023-05-30', NULL, NULL, NULL, 'Методика прогноза подтопления, базирующаяся на использовании методов цифровой обработки исходных данных, позволит при минимальных затратах осуществлять оперативный прогноз подъема уровня подземных вод на участках сооружения фундаментов глубокого заложения', 'Знать теоретические основы геофильтрации подземных вод\r\nУметь использовать основные приемы схематизации фильтрационных потоков\r\nВладеть навыками  решения задач, работы с учебной, нормативной и справочной литературой\r\nЗнать задачи и специфику методов математической обработки гидрогеологических данных\r\nУметь использовать первичные методы цифровой обработки гидрогеологической информации\r\nВладеть первичными методами цифровой обработки информации', 'Аузина Л.И.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(112, NULL, NULL, 'Моделирование гидродинамической системы пласт-скважина', 15, 'Создание программного модуля IPR-VLP, используемого для оптимизации работы нефтяных скважин ', 'Для определения оптимальной рабочей точки нефтяных скважин сопоставляют работу нефтеносного коллектора с используемым скважинным оборудованием. Известно, что приток к скважине должен соответствовать отбору жидкости из скважины.  Учитывая, что скин-эффект величина переменная, она значительное влияет на смещение рабочей точки а, следовательно, требует регулирования рабочих уставок УЭЦН.  Таким образом, рабочая зона IPR-VLP требует постоянного контроля и регулирования.  Предлагается автоматизировать процесс оптимизации технологических параметров работы УЭЦН, в частности создать предпосылки для создания интеллектуальной СУ.', 3, '2022-09-01', '2023-05-30', '', 'Иркутская нефтяная компания', NULL, 'Приложение (программный модуль) ', 'Знания: основные гидродинамические процессы, сопровождающие приток жидкости к скважине; \nУмения: моделировать работу системы приток-отток \nНавыки: навыками применения Simulink\n', 'Лагерев Роман Юрьевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(113, NULL, NULL, 'Оптимизация технологии строительства скважин в сложных горно-геологических условиях (3 курс)', 15, 'Целью проекта является повышение технико-экономической эффективности строительства разведочных и эксплуатационных скважин на месторождениях углеводородов', 'В результате составления проекта планируется решить следующие актуальные проблемы строительства скважин на месторождениях углеводородов:\nстроительство скважин в условиях прихватов колонн бурильных и обсадных труб вследствие различных геологических, технических и технологических причин;\nстроительство скважин в условиях возможности возникновения газонефтеводопроявлений;\nстроительство скважин в интервалах многолетнемерзлых горных пород;\nстроительство скважин в условиях вероятности полного и катастрофического поглощения бурового раствора;\nстроительство скважин в интервалах трапповых отложений;\nстроительство скважин в интервалах соленосных (рапоносных) горизонтов.\n', 1, '2022-09-01', '2023-05-30', '', '', NULL, 'Формой продуктового результата является проект, содержащий рекомендации по оптимизации технологии бурения глубоких скважин в сложных горно-геологических условиях.', 'Знать: особенности технологии бурения глубоких скважин в сложных горно-геологических условиях.\nУметь: подобрать соответствующие технико-технологические решения для конкретных горно-геологических условий.\nВладеть: методиками проектирования технологии бурения глубоких скважин в условиях возможных осложнений и аварий.\n', 'Пушмин Павел Сергеевич, Романов Григорий Радионович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(114, NULL, NULL, 'Методы увеличения нефтеотдачи МУН', 15, 'Целью проекта является повышение технико-экономической эффективности добычи\nУглеводородов\n', 'В процессе выполнения проекта , будет предложен и обоснован выбор методов увеличения нефтеизвлечения МУН (выбор агента вытеснения, способ доставки, метод закачивания, оптимальная схема размещения скважин для реализации воздействия)', 2, '2022-09-01', '2023-05-30', '', 'Case-in ', NULL, 'Разработка МУН с оптимальными характеристиками', 'Знания: будут получены знания в области разработки и эксплуатации нефтяных месторождений\nУмения: получены умения поиска реализуемых на практике способов повышения эффективности МУН\nНавыки: в области управления добычей углеводородов на завершающих стадиях эксплуатации с применением современных технологий\n', 'Четверикова Валентина Валерьевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(115, NULL, NULL, 'Сибирская нефть', 15, 'Сформировать группу лидеров в создании нового научного знания, технологий и разработок для внедрения в промышленность нефтегазового сектора.  Приобретение компетенций в области системы сбора и подготовки скважинной продукции, нефтепромысловой химии. Достижение научно-технического превосходства в научных и образовательных школах. Изучение ESG принципов и методик в нефтегазовой отрасли.', 'Проект «Сибирская нефть» направлен на изучение нефтей  месторождений Восточной Сибири, на исследование имеющихся методик лабораторных работ, изучение особенностей месторождений региона. Решение актуальных задач нефтегазовой отрасли по ESG принципам. ', 3, '2022-09-01', '2023-05-30', '', 'Договор №758/91-02/22 на проведение лабораторных исследований проб нефти\nCase-in , Международный нефтегазовый, кейс ESG \n', NULL, 'Изучены физико-химические свойства нефтей региона, разработаны рекомендации по применению нефтепромысловой химии для конкретных месторождений региона. Предложены свои технические решения. Решение кейсов по тематикам ESG для нефтегазовых компаний.', 'Знания: будут получены знания в области сбора и подготовки нефтяных месторождений;\nУмения: подбирать нефтепромысловую химию под конкретную задачу;\nНавыки: умение работать на лабораторном оборудовании и подбирать методики для исследований и их проводить.\n', 'Шакирова Эльвира Венеровна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(116, NULL, NULL, 'Разработка автоматических способов ликвидации аварий в скважине в период её бурения', 15, 'Создание методики автоматических действий ликвидации аварий в скважине в период её бурения', 'В период бурения скважины возможны многочисленные аварии, которые ликвидируются специальной службой. На ликвидацию аварии уходит много времени и средств. Иногда приходится бросать скважину и забуривать новую. Очень важно быстро остановить развитие осложнения. Поэтому разработка способов ликвидации аварии и восстановление скважины является важной задачей.', 1, '2022-09-01', '2023-05-30', '', '', NULL, 'Разработка методики действий при авариях при бурении скважины', 'Знать: технологические процессы при бурении скважин.                                                                                   Уметь: использовать оборудование для ликвидации аварий.                                                                        Владеть: владеть математическим аппаратом для аналитических расчётов', 'Зайцев Виталий Иванович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(117, NULL, NULL, 'Разработка автоматизированного метода ликвидации гидроразрыва пласта при бурении скважин на шельфе', 15, 'Создание методики автоматической ликвидации гидроразрыва стенки скважины при бурении на шельфе', 'В процессе бурения гидроразрыв скважины нежелателен, т.к. это приводит к потере бурового раствора, иногда катастрофическому. Поэтому разработка метода определения давления гидроразрыва скважины прибурении на шельфе аналитическим способом является важной задачей.', 1, '2022-09-01', '2023-05-30', '', '', NULL, 'Предварительное определение давления гидроразрыва стенки скважины аналитическим методом.\nМетодика действий при ликвидации гидроразрыва\n', 'Знания: технологических процессов бурения скважин на шельфе.\nУмения: использовать оборудование для ликвидации гидроразрыва пласта.\nНавыки: владения математическим аппаратом для аналитических расчётов\n', 'Зайцев Виталий Иванович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(118, NULL, NULL, 'Оценка стоимости трубопровода по ГИС параметрам', 15, 'Создание методики оценки стоимости трубопровода в зависимости от рельефа местности', 'Предварительная оценка инвестиционной привлекательности разработки месторождений нефти и газа.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Развитие компетенций проектной деятельности в нефтегазовой и транспортной отраслях', 'Знает - состав и принципы работы  автоматизированных информационных систем, применяемых в  нефтегазовом деле, как для проектирования, так и для эксплуатации,  основные  модели \nдоступа к базам данных в сети Internet, технологию автоматизации проектных работ,  административной  и  управленческой деятельности.\nпрограммное  обеспечение  применяемой в нефтегазовом  производстве; \nУмеет: применять основные информационные технологии для проектирования, управления, связи,  поиска информации для решения прикладных задач. \nВладеет:  основными приемами  применения стандартных  программных  комплексов,  составляющих  основу  информационных технологий в том числе для целей ГИС и ГДИС\n', 'Зедгенизов Антон Викторович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(119, NULL, NULL, 'Оценка стоимости строительства трубопровода по критериям логистических издержек', 15, 'Создание методики оценки стоимости трубопровода в зависимости от рельефа местности', 'Предварительная оценка инвестиционной привлекательности разработки месторождений нефти и газа.', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Развитие компетенций проектной деятельности в нефтегазовой и транспортной отраслях', 'Знает - состав и принципы работы автоматизированных информационных систем, применяемых в нефтегазовом деле, основные схемы доставки грузов и расходных материалов, требуемых при строительстве трубопроводного транспорта.\nУмеет: применять основные информационные технологии для проектирования, управления, связи, поиска информации для решения прикладных задач в области логистических решений доставки грузов в районы строительства трубопроводного транспорта.\nВладеет: основными приемами применения стандартных программных комплексов, составляющих основу информационных технологий в том числе для целей ГИС и ГДИС.\n', 'Зедгенизов Антон Викторович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(120, NULL, NULL, 'Математическое моделирование параметров промывочной жидкости для условий наклонно направленного бурения скважин', 15, 'Создание математических моделей потока промывочной жидкости для условий наклонно направленного бурения скважин', 'Предварительная оценка существующих моделей потоков промывочной жидкости с учетом ее свойств в условиях направленного бурения скважин.', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Развитие компетенций проектной деятельности в бурении нефтегазовых скважин ', 'Знает –назначение и условия применения промывочных жидкостей для бурения наклонно направленных скважин, математический аппарат составления  моделей, теоретические положения реологии жидкостей.\nУмеет: применять основные информационные технологии для проектирования, управления, связи,  поиска информации для решения прикладных задач. \nВладеет:  основными приемами  применения стандартных  программных  комплексов,  составляющих  основу  информационных технологий в том числе для целей бурения\n', 'Ламбин Анатолий Иванович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(121, NULL, NULL, 'Усовершенствование исследовательского бурового стенда', 15, 'Модернизация учебно-исследовательского стенда в буровой лаборатории для решения современных задач на более высоком с точки зрения качества уровне', 'Существует потребность в испытании буровых долот и другого породоразрушающего инструмента в стендовых условиях, прежде чем запускать полевые испытания и массовое производство. В 2016 году сотрудниками ИРНИТУ [https://www.istu.edu/news/22230/] были разработаны буровые долота, способные повысить эффективность проведения буровых работ. Подобные работы ведутся регулярно. Имеющееся в ИРНИТУ оборудование обладает рядом недостатков, в том числе аналоговыми приборами контроля и измерения параметров режима бурения. Необходимо соответствовать современным тенденциям и требованиям. Актуальность поставленной проблемы обоснована потребностью в полигоне для испытаний инновационных технических средств – породоразрушающего инструмента (долот, коронок и др.).', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Буровой исследовательский стенд, способный на современном уровне проводить эксперименты с последующим подбором оптимальной технологии бурения скважин', 'Знания: Способы совершенствования исследовательских буровых стендов для обеспечения соответствия современному уровню развития науки и техники\nУмения: Оценивать текущее состояние буровых установок и предлагать варианты усовершенствования\nНавыки: Обеспечивать монтаж, испытание и обслуживание контрольно-измерительного оборудования на исследовательских установках\n', 'Романов Григорий Радионович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(122, NULL, NULL, 'Оптимизация технологии строительства скважин в сложных горно-геологических условиях (4 курс)', 15, 'Целью проекта является повышение технико-экономической эффективности строительства разведочных и эксплуатационных скважин на месторождениях углеводородов', 'В результате составления проекта планируется решить следующие актуальные проблемы строительства скважин на месторождениях углеводородов:\nстроительство скважин в условиях прихватов колонн бурильных и обсадных труб вследствие различных геологических, технических и технологических причин;\nстроительство скважин в условиях возможности возникновения газонефтеводопроявлений;\nстроительство скважин в интервалах многолетнемерзлых горных пород;\nстроительство скважин в условиях вероятности полного и катастрофического поглощения бурового раствора;\nстроительство скважин в интервалах трапповых отложений;\nстроительство скважин в интервалах соленосных (рапоносных) горизонтов.\n', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Формой продуктового результата является проект, содержащий рекомендации по оптимизации технологии бурения глубоких скважин в сложных горно-геологических условиях.', 'Знать: особенности технологии бурения глубоких скважин в сложных горно-геологических условиях.\nУметь: подобрать соответствующие технико-технологические решения для конкретных горно-геологических условий.\nВладеть: методиками проектирования технологии бурения глубоких скважин в условиях возможных осложнений и аварий.\n', 'Пушмин Павел Сергеевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(123, NULL, NULL, 'Исследование влияния свойств и состава бурового раствора на процесс разрушения горных пород в буровой лаборатории ИРНИТУ', 15, 'Повысить эффективность бурения твердых горных пород путем подбора оптимальных составов буровых растворов', 'Траппы Сибирской платформы, при условии их монолитности, являются серьезным осложнением с точки зрения бурения. Необходимо подбирать такие буровые растворы, которые будут способствовать повышению производительности бурения и снижать затраты энергии и ресурсов на строительство скважин в условиях трапповых интрузий. ', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Рецептуры буровых растворов, предназначенных для бурения траппов Сибирской платформы', 'Знания: Способы совершенствования технологии бурения нефтяных и газовых скважин путем подбора оптимальных рецептур буровых растворов\nУмения: Оценивать влияние определенных реагентов на производительность и ресурсоемкость буровых работ\nНавыки: Подбирать рецептуру и приготавливать на их основе буровые растворы для бурения твердых горных пород\n', 'Романов Григорий Радионович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(124, NULL, NULL, 'Технология рудоподготовки и обогащения апатит-нефелиновых руд', 15, 'Разработка технологии обогащения апатит-нефелиновых руд', 'Апатит-нефелиновые руды являются основным источником получения минеральных удобрений. Мировые запасы и ресурсы апатитовых руд на 60% сосредоточены в России, при этом две трети сконцентрированы на Кольском полуострове. Исходное содержание минерала апатита и нефелина 30,67 и 30,88% соответственно. Для получения готового продукта руда из карьера должна пройти стадии дезинтеграции  классификации и обогащения для получения готового продукта. Для понимания данного процесса, требуется провести натурные лабораторные испытания. Проект направлен на получение обучающимися компетенций в области профессиональной деятельности, а именно в рудоподготовки и основных методов обогащения. В процессе реализации проекта обучающиеся получат навыки проведения экспериментов по пробоподготовке, изучению физико-механических свойств проб руды, разработке технологии дробления, измельчения и классификации руд и исследований на обогатимость различными методами.', 2, '2022-09-01', '2023-05-30', '', 'ПАО «Ковдорский горно-обогатительный комбинат»  ', NULL, 'Научно-исследовательская работа по разработке технологии обогащения апатит-нефелиновых руд', 'Знать: методы обогащения и переработки апатит-нефелиновых руд;\nУметь: проводить инженерный анализ существующей и разрабатываемой проектной документации  строительства и  эксплуатации горно-обогатительного комплекса;\nВладеть: методами обогащения и переработки технологического и техногенного сырья.\n', 'Бурдонов Александр Евгеньевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(125, NULL, NULL, 'Переработка крупнотоннажного техногенного сырья с получением композиционных материалов', 15, 'Переработка промышленных крупнотоннажных минеральных тонкодисперсных отходов с получением товарной продукции – полимерных композиционных материалов для различного применения', 'Разрабатываются рецептуры новых огнестойких\nи высокопрочных, изготовленных из промышленных отходов\n(золошлаковой смеси - ЗШС ТЭЦ, ГОСТ 25818-91- наполнитель, пыль газоочистки металлургии, пыль горнодобывающих предприятяий и др. ) и термопластичных полимеров.\nНа базе ИРНИТУ имеется цех по производству инновационных строительных материалов, а также термопластавтомат для литья изделий из пластических масс.\nРазрабатываемый материал будет превосходить аналоги из других полимерных композитов и натуральную древесину по химической стойкости, биологической стойкости, огнестойкости и долговечности. Кроме того, материал абсолютно гидрофобен. \nПрименение нового материала -  строительные и конструкционные материалы, детали машин и механизмов, корпуса электроники, др.\n', 3, '2022-09-01', '2023-05-30', '', 'ООО «Байкальская энергетическая компания», АО «Кремний»', NULL, 'Композиционные материалы с набором свойств для различного применения', 'Знания: способы переработки полимерных материалов\nУмения: подбора технологических параметров для переработки определенного вида термопласта\nНавыки: работы на оборудовании по переработке пластических масс в изделия\n', 'Барахтенко Вячеслав Валерьевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(126, NULL, NULL, 'Технология извлечения редких металлов из литиевых рассолов Сибирской платформы', 15, 'Выбор и обоснование технологии извлечения редких металлов из высококонцентрированных рассолов ', 'Подземные высокоминерализованные воды (рассолы), вскрывающиеся при отработке месторождений твердых полезных ископаемых, нефти и газа, насыщенные различными микро- и макроэлементами, представляют собой потенциальное гидроминеральное сырье и являются крупнейшим источником товарных продуктов, таких как соли лития, бромиды, йод и др. Фактически же они превращаются в отходы- сбрасываются на поверхность либо закачиваются в подземные горизонты, что требует дополнительных затрат, а также наносит огромный ущерб окружающей среде. Задача проекта заключается в обосновании выбора и разработке эффективных технологических схем селективного выделения промышленно ценных компонентов из природных рассолов. На основании полученных результатов можно обосновывать и разрабатывать комплексные технологические схемы извлечения ценных компонентов, которые возможно реализовать в Иркутской области и соседних с ней регионах (Якутия, Бурятия)', 3, '2022-09-01', '2023-05-30', '', 'НОЦ «Байкал»', NULL, 'Технология для извлечения солей лития и стронция ', 'Знания: особенности свойств высококонцентрированных рассолов, технологии извлечения ценных компонентов\nУмения: проводить исследования свойств высококонцентрированных растворов, выбирать технологические решения\nНавыки: обоснование технологии, расчеты эффективности, доказательство перспективности проекта \n', 'Зелинская Елена Валентиновна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(127, NULL, NULL, 'Исследование эффективности расслоения суспензии продуктов обогащения минерального сырья', 15, 'Проведение комплекса исследований по установлению скорости осаждения твердых частиц в жидкой среде с учетом концентрации твердых частиц и влияния флокулянтов', 'В настоящее время сгущение является неотъемлемым процессом в технологической цепи обогащения полезных ископаемых, который требует постоянного изучения и совершенствования технологии по подбору и применению различных реагентов для увеличения эффективности процесса сгущения.\nПроект направлен на получение обучающимися компетенций в области профессиональной деятельности, а именно в области сгущения и обезвоживания продуктов обогащения. В процессе реализации проекта обучающиеся получат навыки проведения экспериментов по определению скорости осаждения частиц в жидкой среде, научатся проводить подбор органических и неорганических флокулянтов, для повышения эффективности разделения пульп, а так же производить расчет удельной поверхности осаждения твердых части и конструкционных параметров сгустительного оборудования.\n', 2, '2022-09-01', '2023-05-30', '', 'ООО «ИЗТМ-Инжиниринг»  ', NULL, 'Методика проведения исследований в области сгущения пульп и осветления технологических сливов.\nКонструкционные параметры сгустительного оборудования.\n', 'Знания: \n- методики расчета основного и вспомогательного оборудования для обезвоживанияи сгущения пульп на обогатительных фабриках;\n- конструкции и принцип действия сгустителя и осветлителя;\n- методы очистки сточных вод обогатительных фабрик.\nУмения: \n- расчёт параметров работы сгустителя;\n- расчет показателей водношламовой схемы;\nНавыки: \nВладение технической терминологией в области производства работ по обезвоживанию, пылеулавливанию и очистке сточных вод;\nВладение методами расчета схем по обезвоживанию.\n', 'Бурдонов Александр Евгеньевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(128, NULL, NULL, 'Разработка технологий биоремедиации объектов окружающей среды и нормализации санитарно-гигиенических условий в производственных и административных помещениях', 15, 'Разработка технологий и технических устройств для очистки объектов окружающей среды от загрязнений', 'Масштабы загрязнения антибиотиками, используемыми в сельском хозяйстве весьма значительны, что приводит к возникновению антибиотикорезистентности у бактерий и вирусов. Данной проблеме не уделяется должного внимания ни со стороны властей, ни со стороны производителей, поэтому поиск новых и адаптация традиционных методик очистки объектов окружающей среды от антибиотиков является инновационным решением для проблемы ', 2, '2022-09-01', '2023-05-30', '', 'Грант ИРНИТУ', NULL, 'Создание установок биоочистки почв и водных объектов от антибиотиков (пятый / шестой семестр). Создание фитокомплексов для очистки воздуха в помещениях (шестой семестр)', 'Знания: основные показатели качества окружающей среды и современные экологические проблемы Байкальского региона\nУмения: анализировать и интерпретировать информацию о количественных и качественных показателях окружающей среды\nНавыки: создания рабочих прототипов оборудования для очистки окружающей среды\n', 'Тимофеева Светлана Семёновна, Тюкалова Ольга Васильевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(129, NULL, '2022-08-30 12:59:31', 'Профессиональные риски на объектах экономики Иркутской областиПрофессиональные риски в структурных подразделениях  ИРНИТУ', 15, 'Управление профессиональными  рисками в структурных подразделениях ИРНИТУ', 'Создание безопасных и благоприятных условий труда, является одной из основных задач  для работодателя. Трудовой кодекс РФ предусматривает наличие в организации системы  управления охраной труда, создание и функционирование системы оценки профессиональных рисков. Для этого необходимо провести процедуру оценки профессиональных рисков на каждом рабочем месте, территории предприятия, местах общего использования и в других зонах ответственности работодателя за безопасность сотрудников.', 3, '2022-09-01', '2023-05-30', NULL, 'Управление по работе с персоналом и обучающимися, служба охраны труда', NULL, 'Карты оценки профессиональных рисков; комплекс мероприятий по устранению рисков или снижению их уровня', 'Знания: методик оценки профессиональных рисков\r\nУмения: выявлять и идентифицировать опасности, выполнять инструментальные измерения\r\nНавыки: работы с нормативно-правовыми актами в области безопасности и охраны труда; локальными актами организации', 'Никитина О.И., Тимофеев Семен Сергеевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(130, NULL, NULL, 'Снижение углеродного следа на предприятиях по добыче и обогащению рудных полезных ископаемых', 15, 'Создать углеродного следа добывающего предприятия', 'Недропользователи заинтересованы в оценке и снижении углеродного следа своей продукции. Нам предстоит исследовать источники образования оксидов углерода на всех этапах жизненного цикла добывающего предприятия. Предложить решения для его снижения.', 2, '2022-09-01', '2023-05-30', '', 'Форсайтная группа НТИ по рынку EcoNet', NULL, 'Визуализация (в формате презентации) углеродного следа добывающего предприятия (пятый семестр). Поиск решений для его снижения (шестой семестр)', 'Знания: экологического законодательства; основ ESG – управления рисками\nУмения: представления сложной мультидисциплинарной информации в доступном виде\nНавыки: анализа жизненного цикла предприятия\n', 'Шевченко Елена Ивановна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(131, NULL, NULL, 'Эргодизайн рабочих помещений', 15, 'Приобретение навыков практического применения нормативно-правовой документации в области эргономики при проектировании рабочих мест для улучшения условий труда работающих в конкретном помещении', 'В настоящее время в ИРНИТУ существуют учебные и рабочие помещения, не отвечающие нормативным эргономическим требованиям (например, количество рабочих мест в помещении превышает допустимое количество, а их организация неэффективна). Эта ситуация делает некомфортными условия работы студентов и ППС в таких помещениях, что опосредовано может сказываться на качестве образовательного процесса. ', 2, '2022-09-01', '2023-05-30', '', 'ИРНИТУ', NULL, 'Разработка электронной модели (возможно - плана-схемы) эргодизайна отдельных рабочих помещений (учебных аудиторий)  с пояснительной запиской', 'Знания: знать нормативно-правовую документацию в области эргономических требований организации рабочих мест. \nУмения: уметь собирать, анализировать и оценивать информацию об условиях организации рабочего пространства  в рабочих помещениях различного назначения. \nНавыки: владение навыками проектирования рабочего пространства и рабочих мест в помещении с учетом требований действующей нормативно-правовой базы\n', 'Иванова Светлана Владимировна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(132, NULL, '2022-08-30 12:59:56', 'Профессиональные риски на объектах экономики Иркутской областиКультура безопасности как элемент снижения уровня профессиональных рисков', 15, 'Разработка практических процедур, которые помогут сформировать осознанное и ответственное отношение к вопросам безопасности и охраны труда', 'Культура безопасного труда – это часть общей организационной культуры, такой набор характеристик и особенностей деятельности организации и поведения отдельных лиц, который устанавливает, что проблемы безопасности являются высшим приоритетом. Для формирования ответственного и осознанного отношения к вопросам безопасности и охраны труда необходимо повысить мотивацию и вовлеченность сотрудников в формирование культуры безопасности, что в конечном итоге приведет к снижению уровней профессиональных рисков.', 3, '2022-09-01', '2023-05-30', NULL, 'Управление по работе с персоналом и обучающимися, служба охраны труда', NULL, 'Проект локального нормативного акта «Положение о культуре безопасности в ИРНИТУ»', 'Знания: требований безопасности и охраны труда при выполнении работ\r\nУмения: заинтересовать работников, мотивировать их на безопасное выполнение работ; использовать современные формы предоставления информации по охране труда \r\nНавыки: работы с инструкциями, нормативно-правовыми актами в области безопасности и охраны труда; локальными актами организации', 'Никитина О.И., Тимофеев Семен Сергеевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(133, NULL, NULL, 'Исследование возможностей использования долерита в ювелирном и камнерезном дизайне', 15, 'Расширить сферы применения долерита в ювелирном и камнерезной дизайне', 'Изготовление художественных изделий из долерита расширит сферы сбыта и повысит рентабельность производства, а разработка актуального современного дизайна повысит спрос на подобную продукцию', 2, '2022-09-01', '2023-05-30', '', 'ОБЩЕСТВО С ОГРАНИЧЕННОЙ ОТВЕТСТВЕННОСТЬЮ \"СПЕЦКАМЕНЬСИБИРИ\"', NULL, 'Дизайн-проект коллекции из долерита', 'Знания: основные принципы планирования и организации своей деятельности\nУмения: формулировать личные цели; планировать и организовывать свою деятельность на основе приоритетов и поставленных целей\nНавыки: навыки рефлексии\n', 'Буйволова М.А., Бирюкова И.П', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(134, NULL, NULL, 'Идентификация турмалинов и оценка их состава методом конфокальной Рамановской спектроскопии', 15, 'Создание базы данных Рамановских спектров минералов группы турмалина для эталонной коллекции', 'Наиболее эффективные в настоящее время методы диагностики ювелирных камней основаны на использовании наукоемкого оборудования в условиях современной лаборатории. Одним из таких методов недеструктивного локального микроанализа минералов является конфокальная Рамановская спектроскопия, объединяющая конфокальный микроскоп и метод Рамановской спектроскопии в одной системе. Для этого метода нет необходимости в специальной пробоподготовке и ювелирные камни могут быть диагностированы в изделиях. Спектрометр оснащен программным обеспечением, позволяющим производить экспрессную идентификацию минералов путем автоматического сравнения полученного спектра образца со спектрами в базе данных. Однако существующая библиотека спектров нуждается в пополнении данными о российских минералах, в том числе о турмалинах Восточно-Сибирского региона.', 3, '2022-09-01', '2023-05-30', '', 'Институт земной коры СО РАН', NULL, 'Создание библиотеки спектров турмалинов Восточно-Сибирского региона для пополнения базы данных конфокального Рамановского спектрометра WITec alpha 300R', 'Знания: теоретических основ метода конфокальной Рамановской спектроскопии\nУметь: проводить пробоподготовку, анализ образцов и интерпретировать полученные результаты\nВладеть: навыками работы с конфокальным Рамановским спектрометром WITec alpha 300R\n', 'Анисимова Александра Алексеевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(135, NULL, NULL, 'Разработка камнерезного цеха по обработке долерита для получения готового художественного продукта', 15, 'Разработать современный камнерезный цех для художественной обработки долерита', 'Правильно организованный камнерезный цех позволит изготавливать современную актуальную художественную продукцию из долерита без значительных потерь материала', 3, '2022-09-01', '2023-05-30', '', 'ОБЩЕСТВО С ОГРАНИЧЕННОЙ ОТВЕТСТВЕННОСТЬЮ \"СПЕЦКАМЕНЬСИБИРИ\"', NULL, 'Проект камнерезного цеха', 'Знания: основные принципы планирования и организации своей деятельности\nУмения: формулировать личные цели; планировать и организовывать свою деятельность на основе приоритетов и поставленных целей\nНавыки: навыки рефлексии\n', 'Буйволова М.А, Бирюкова И.П.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(136, NULL, '2022-08-30 13:01:37', 'Разработка коллекции ювелирных изделий на основе оберегов народов Сибири', 15, 'Разработать современный дизайн коллекции ювелирных изделий на тему оберегов', 'Современный рынок ювелирной продукции перенасыщен однообразными изделиями не привлекательными для современного покупателя. Одним из решений этой проблемы является разработка актуального дизайна ювелирных на основе оберегов народов Сибири. Их использование в дизайне ювелирной продукции повысит ее привлекательность.', 3, '2022-09-01', '2023-05-30', NULL, 'АО «Алмаз»', NULL, 'Дизайн-проект коллекции ювелирных изделий', 'Знания: основные принципы планирования и организации своей деятельности\r\nУмения: формулировать личные цели; планировать и организовывать свою деятельность на основе приоритетов и поставленных целей.\r\nНавыки: навыки рефлексии', 'Берман Елена Александровна, Сорокина Вера Евгеньевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(137, NULL, NULL, 'Разработка сувенирной продукции на основе уникальных особенностей флоры и фауны Байкальского региона', 15, 'Разработать современный дизайн сувенирной продукции на основе уникальных особенностей флоры и фауны Байкальского региона', 'Современный рынок ювелирной и камнерезной продукции Байкальского региона перенасыщен однообразными изделиями не привлекательными для современного покупателя. Одним из решений этой проблемы является разработка актуального дизайна сувенирных изделий на основе особенностей природы Байкальского региона с учетом географического положения и уникальной флоры и фауны Байкала. Их использование в дизайне сувенирной продукции повысит ее привлекательность.', 2, '2022-09-01', '2023-05-30', '', 'АО \"Байкалкварцсамоцветы»', NULL, 'Дизайн-проект коллекции изделий', 'Знания: основные принципы планирования и организации своей деятельности\nУмения: формулировать личные цели; планировать и организовывать свою деятельность на основе приоритетов и поставленных целей.\nНавыки: навыки рефлексии\n', 'Войтюк Алена Александровна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(138, NULL, '2022-08-30 13:02:21', 'Вовлечение техногенного сырья в производство цветных металлов', 15, 'Разработать технологические рекомендации и стратегию переработки техногенного сырья и расширения сырьевой базы металлургического производства за счет разработки новых месторождений', 'На территории России сосредоточено почти 30% мировых разведанных запасов никеля, 28% – железа, 10% – меди, по запасам других видов металлов, страна входит в число ведущих горнодобывающих государств. Ресурсная обеспеченность России определяется исходя из необходимости удовлетворения текущих и перспективных потребностей экономики, в соответствии с уровнем экономического развития страны. Однако Россия отстает от большинства стран мира по уровню вовлечения минерально-сырьевой базы в экономический оборот, по уровню обеспечения народнохозяйственных потребностей в ресурсах и по темпам роста горноперерабатывающей и металлургической промышленности. Отставание от среднемирового уровня свидетельствует о проблемах вовлечения природных ресурсов в производство, о трудностях с воспроизводством материально-технической базы страны.\r\nВместе с тем металлургические предприятия являются одним из основных источников загрязнения окружающей среды. Выбросы вредных веществ на конкретных промышленных предприятиях зависят от объема производства, структуры предприятия, оснащенности газоочистным оборудованием, технологических особенностей и других причин. В связи со всевозрастающим негативным воздействием производственной деятельности металлургических предприятий на состояние окружающей среды наибольшую важность приобретают технологии, обеспечивающие устойчивое развитие за счет повышения энергоэффективности, комплексного использования сырья, снижения экологической нагрузки и производственных издержек. Как показывает практика, переработка многих видов отходов металлургического производства экономически выгодно и технически осуществимо.\r\nОсновными направлениями расширения сырьевой базы являются разработка новых месторождений и переработка уже накопленных и вновь образующихся отходов.', 1, '2022-09-01', '2023-05-30', NULL, NULL, NULL, 'Технологические рекомендации, включающие анализ образующихся отходов металлургических предприятий и существующих запасов минерального сырья, а также конкретные технологические решения по вовлечению и переработке минерального и техногенного сырья', 'Знания:\r\nПринципы рационального природопользования в области металлургии.\r\nУмения:\r\nУметь применять принципы рационального природопользования для энерго- и ресурсосбережения технологических процессов в металлургии \r\nНавыки:\r\nВладеть навыками использования принципов рационального природопользования для энерго- и ресурсосбережения технологических процессов в металлургии.', 'Фёдоров Сергей Николаевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(139, NULL, NULL, 'Оптимизация процесса переработки техногенного и минерального сырья', 15, 'Разработать технологические рекомендации по переработки отходов вторичной металлургии свинца и оптимизации процесса производства первичного алюминия', 'Проблема накопления отходов в процессе переработки свинцовых аккумуляторных батарей встречается на большинстве заводов данной отрасли. Самым ярким примером являются накопленные отходы в г. Свирске, объем которых составляет 3500-4500 т. Данный отход относится к третьему классу опасности, но также представляет собой ценный продукт для доизвлечения свинца, которого в отходах содержится до 30 мас. %. Разработанное технологическое решение может быть использовано и на других предприятиях перерабатывающих аккумуляторные батареи.\nПри производстве алюминия электролизом криолит-глиноземного расплава возникает ряд проблем. При повышении амперной нагрузки повышается температура электролита, поэтому необходимо организовать эффективный отвод тепла от поверхностей электролизера и уменьшить потери тепла. Увеличение засыпки и размеров электролизера способствуют уменьшению тепловых потерь за счет снижения отношения их поверхности к объему. \nУвеличение силы тока на электролизной серии выше нормативного значения приводит к ряду расстройств на электролизере: увеличению сопротивления токопроводящих элементов ванны, нарушению теплового баланса, повышению выбросов газообразных веществ. Поэтому проработка инновационных решений для компенсации амперной нагрузки является не простой и важной задачей.\nПотери анодного напряжения связаны в первую очередь с конструкцией анодного узла, составом и качеством материала анода. Важную роль в перепаде напряжения в анодном массиве играет токораспределение по анодам. Известно, что оно может быть крайне неравномерно, в результате чего возникают конусы, приводящие к замыканию электродов.\n', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Технологические рекомендации, включающие анализ образующихся отходов вторичной металлургии свинца, а также конкретные технологические решения по вовлечению и переработке техногенного сырья. \nТехнологические рекомендации, включающие анализ проблем возникающих при производстве первичного алюминия, а также конкретные технологические решения по их решению\n', 'Знания:\nПринципы рационального природопользования в области металлургии.\nКонструкция электролизеров для получения алюминия; основные параметры, оказывающие влияние на эффективность металлургических процессов производства алюминия электролитическим способом и диапазоны их оптимальных значений.\nУмения:\nУметь применять, совершенствовать или разрабатывать методы переработки отходов металлургического производства.\nУметь применять полученные знания о строении криолит-глиноземных расплавов на практике; уметь проводить анализ влияния различных факторов на основные показатели электролиза\nНавыки:\nВладеть навыками разработки предложений по переработке отходов металлургического производства и оптимизации процесса производства алюминия. \n', 'Тютрин Андрей Александрович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(140, NULL, '2022-08-30 13:02:53', 'Расширение сырьевой базы металлургического производства', 15, 'Разработать технологические рекомендации и стратегию расширения сырьевой базы металлургического производства за счет разработки новых месторождений и переработки техногенного сырья', 'На территории России сосредоточено почти 30% мировых разведанных запасов никеля, 28% – железа, 10% – меди, по запасам других видов металлов, страна входит в число ведущих горнодобывающих государств. Ресурсная обеспеченность России определяется исходя из необходимости удовлетворения текущих и перспективных потребностей экономики, в соответствии с уровнем экономического развития страны. Однако Россия отстает от большинства стран мира по уровню вовлечения минерально-сырьевой базы в экономический оборот, по уровню обеспечения народнохозяйственных потребностей в ресурсах и по темпам роста горноперерабатывающей и металлургической промышленности. Отставание от среднемирового уровня свидетельствует о проблемах вовлечения природных ресурсов в производство, о трудностях с воспроизводством материально-технической базы страны.\r\nВместе с тем металлургические предприятия являются одним из основных источников загрязнения окружающей среды. Выбросы вредных веществ на конкретных промышленных предприятиях зависят от объема производства, структуры предприятия, оснащенности газоочистным оборудованием, технологических особенностей и других причин. В связи со всевозрастающим негативным воздействием производственной деятельности металлургических предприятий на состояние окружающей среды наибольшую важность приобретают технологии, обеспечивающие устойчивое развитие за счет повышения энергоэффективности, комплексного использования сырья, снижения экологической нагрузки и производственных издержек. Как показывает практика, переработка многих видов отходов металлургического производства экономически выгодно и технически осуществимо.\r\nОсновными направлениями расширения сырьевой базы являются разработка новых месторождений и переработка уже накопленных и вновь образующихся отходов.', 1, '2022-09-01', '2023-05-30', NULL, NULL, NULL, 'Технологические рекомендации, включающие анализ образующихся отходов металлургических предприятий и существующих запасов минерального сырья, а также конкретные технологические решения по вовлечению и переработке минерального и техногенного сырья', 'Знания:\r\nПринципы рационального природопользования в области металлургии.\r\nУмения:\r\nУметь применять принципы рационального природопользования для энерго- и ресурсосбережения технологических процессов в металлургии \r\nНавыки:\r\nВладеть навыками использования принципов рационального природопользования для энерго- и ресурсосбережения технологических процессов в металлургии.', 'Зайцева Анна Александровна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(141, NULL, NULL, 'Разработка технологии переработки золотосодержащих руд', 15, 'Разработать технологию по переработке золотосодержащего сырья и расширить сырьевую базу путем вовлечения в переработку упорного, бедного, забалансового, комплексного сырья', 'В России в золотых рудах коренных месторождений заключено 61,1% разведанных запасов. В комплексных рудах – 25,5%, в россыпях – 13,4%. Прогнозные ресурсы коренных месторождений 38,8 тыс. т, россыпей 2,8 тыс. т. Однако Россия отстает от большинства стран мира по уровню вовлечения минерально-сырьевой базы в экономический оборот, по уровню обеспечения народнохозяйственных потребностей в ресурсах и по темпам роста горноперерабатывающей и металлургической промышленности. На сегодняшний день Россия занимает третье место по добыче золота (282-300 тонн/год). Лидерами являются Китай (400 тонн/год) и Австралия (315 тонн/год). Легких для переработки руд в России и мире осталось крайне мало. Все чаще золотодобытчикам приходится работать с упорным рудами. Традиционного цианирования в условиях переработки упорных руд недостаточно. Такие руды требуют обогатительных процессов прежде, чем их будет целесообразно подвергать цианированию. Так же следует отметить, что в настоящее время особый интерес представляют и комплексные руды, содержащие благородные металлы. Переработка комплексных руд позволяет повысить экономические показатели производства. \nОсновным направлением в золотодобыче является выбор наиболее рентабельной технологии по переработке золотосодержащих руд. \n', 1, '2022-09-01', '2023-05-30', '', '', NULL, 'Технологические рекомендации, включающие анализ существующих схем переработки золотосодержащих руд, а также конкретные технологические решения по расширению сырьевой базы путем вовлечения в переработку упорного, бедного, забалансового, комплексного сырья', 'Знания:\nПринципы рационального природопользования в области металлургии.\nУмения:\nУметь применять принципы рационального природопользования для энерго- и ресурсосбережения технологических процессов в металлургии \nНавыки:\nВладеть навыками использования принципов рационального природопользования для энерго- и ресурсосбережения технологических процессов в металлургии.\n', 'Шипнигов Антон Андреевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(142, NULL, NULL, 'Проектирование, монтаж и наладка учебно-исследовательских стендов на базе оборудования для автоматизации ПГ ОВЕН (3й курс)', 15, 'Дать обучающимся возможность приобрести практические знания, умения, навыки работы с оборудованием для автоматизации в процессе проектирования, монтажа, наладки учебно-исследовательских стендов и исследования систем автоматического регулирования.', 'Основной задачей учебных стендов является обучение студентов основам автоматизации технологических процессов, демонстрация работы средств автоматического управления и регулирования. Внедрение в процесс обучения стендов поможет учащимся детально изучать процессы автоматического управления и регулирования, а разработка методических пособий по работе с ними, получать практические навыки в проектировании систем автоматизации. Работа на стендах знакомит будущих специалистов в области автоматизации с условиями максимально приближенными к производственным. \nВследствие этого, задачи разработки устройств данного класса являются актуальными\n', 1, '2022-09-01', '2023-05-30', '', 'Институт высоких технологий ИРНИТУ\nРегиональный учебный центр «ОВЕН-ИРНИТУ»\n', NULL, '1.Проект учебно-исследовательских стендов.\n2.Разработка технической документации:\n-схема электрическая принципиальная;\n-схема внешних проводок;\n-схема питания;\n-монтажная схема;\n-методические указания к лабораторным и практическим работам;\n-программное обеспечение и т.д.\n3. Изготовленный учебно-исследовательский стенд.\n', 'Знания: знать основные принципы организации своей работы, требования к представлению результатов, инструменты поиска информации,  нормы и способы социального взаимодействия.\nУмения: формулировать цели и задачи; творчески и критически мыслить, решать задачи в соответствии с ролевой позицией.\nНавыки: работа в команде, получение первичной информации, навыками определения и постановки задач.\n', 'Ершов П.Р., Подкорытов А.А.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(143, NULL, NULL, 'Проектирование, монтаж и наладка учебно-исследовательских стендов на базе оборудования для автоматизации ПГ ОВЕН (4й курс)', 15, 'Дать обучающимся возможность приобрести практические знания, умения, навыки работы с оборудованием для автоматизации в процессе проектирования, монтажа, наладки учебно-исследовательских стендов и исследования систем автоматического регулирования', 'Основной задачей учебных стендов является обучение студентов основам автоматизации технологических процессов, демонстрация работы средств автоматического управления и регулирования. Внедрение в процесс обучения стендов поможет учащимся детально изучать процессы автоматического управления и регулирования, а разработка методических пособий по работе с ними, получать практические навыки в проектировании систем автоматизации. Работа на стендах знакомит будущих специалистов в области автоматизации с условиями максимально приближенными к производственным. \nВследствие этого, задачи разработки устройств данного класса являются актуальными\n', 3, '2022-09-01', '2023-05-30', '', 'Институт высоких технологий ИРНИТУ\nРегиональный учебный центр «ОВЕН-ИРНИТУ\n', NULL, '1.Проект учебно-исследовательских стендов.\n2.Разработка технической документации:\n-схема электрическая принципиальная;\n-схема внешних проводок;\n-схема питания;\n-монтажная схема;\n-методические указания к лабораторным и практическим работам;\n-программное обеспечение и т.д.\n3. Изготовленный учебно-исследовательский стенд.\n\n', 'Знания: знать основные принципы организации своей работы, требования к представлению результатов, инструменты поиска информации,  нормы и способы социального взаимодействия.\nУмения: формулировать цели и задачи; творчески и критически мыслить, решать задачи в соответствии с ролевой позицией.\nНавыки: работа в команде, получение первичной информации, навыками определения и постановки задач.\n', 'Ершов П.Р.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(144, NULL, NULL, 'Разработка элементов  автоматических устройств контроля физико-химических параметров гидрометаллургических процессов переработки минерального сырья', 15, 'Разработка технических и программных составляющих устройств автоматического контроля таких параметров как: концентрация растворенного золота, цианида натрия  в технологических растворах гидрометаллургических отделений при переработке минерального сырья', 'Аналитический контроль играет важную роль  для успешного ведения технологических процессов. В большинстве случаев измерения проводятся либо в лабораторных условиях и соответственно данные  могут потерять свою актуальность из-за достаточно большого времени проведения анализов, либо существующие устройства  имеют высокую стоимость. Вследствие этого, задачи разработки устройств данного класса являются актуальными. В рамках данного проекта  предлагается рассматривать отдельные задачи для достижения общей цели проекта, такие как разработка отдельных алгоритмов,  разработка  отдельных технических узлов.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Алгоритмы реализации отдельных подсистем\nСтруктурные схемы отдельных технических решений\n', 'Знать: метрологические и эксплуатационные характеристики, особенности монтажа, погрешности, состояние и перспективы и тенденции современного приборостроения, классификацию, назначение, особенности применения, устройство и принцип действия приборов и устройств качественного анализа (газоанализаторов, рН- метров, концентратомеров и пр.).\nУметь: проводить декомпозицию общей задачи измерения, с выделением отдельных подсистем \nВладеть: навыками работы с анализаторами: подготовки проб, проведения измерений, оценки и обработки    результатов, в том числе с применением специализированного программного обеспечения\n', 'Овсюков Александр Евгеньевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(145, NULL, NULL, 'Разработка системы управления лабораторной информацией', 15, 'Разработка структуры', 'Система управления лабораторной информацией – программное обеспечение, предназначенное для управления лабораторными потоками работ и документов. Позволяет оптимизировать сбор, анализ, возврат и отчетность лабораторных данных. Часто применяется вместе с MES-системами. Задачами данного проекта является рассмотрение существующих систем данного класса, рассмотрение направления движения потоков информации, выделение основных функций которые реализуются, разработка структуры, описание функций, составление алгоритмов обработки информации.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Структура программного комплекса\nОписание функций реализуемых данным комплексом\nОписание графического интерфейса\nАлгоритмы обработки  информации\n', 'Знать: международную систему единиц физических величин, методы измерений, метрологические показатели средств измерений, метрологические характеристики средств измерения, погрешности  измерений, причины возникновения погрешностей,  методику обработки результатов наблюдений и оценивание погрешностей измерений, поверку и калибровку средств измерений, методы поверки (калибровки) \nУметь: обоснованно применять методы метрологии и стандартизации,  проводить простейшую обработку результатов многократных измерений.\nВладеть: методами метрологии и стандартизации, достаточным творческим мышлением и способностью самостоятельно принимать решения.\n', 'Овсюков Александр Евгеньевич, Колодин Алексей Александрович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(146, NULL, '2022-08-30 13:08:34', 'Формирование компетенции персонала высокотехнологичного предприятия как инструмент обеспечения его конкурентоспособности. Разработка веб-приложения «Система адаптации персонала».   3-й КУРС', 15, 'Разработать веб-приложение, построенного по типу «Электронное обучение» на базе CMS Wordpress, с применением стека технологий HTML/CSS/JS', 'Актуальной задачей обеспечения конкурентоспособности высокотехнологичного предприятия является формирование компетенции персонала. Одним из важнейших ресурсов достижения результативности процессов является подготовка компетентного персонала. При найме новых сотрудников в штат организации происходит процесс их адаптации. В рамках адаптационного периода новоприбывший сотрудник ознакамливается с необходимой нормативно-правовой документацией и внутренними регламентами компании. К таким регламентам могут относиться как требования федерального уровня, например инструктаж о соблюдении мер по защите и охране труда, так и внутренние условия нахождения на режимных объектах, правила пожарной безопасности, и иные требования.\r\nСоздание веб-приложения по типу «Электронное обучение» позволит не только собрать все необходимые для адаптации сотрудников документы на единой площадке, но и даст возможность сотрудникам удаленно проходить адаптационные мероприятия в части ознакомления и прохождения тестирования в рамках тех или иных требований, заявленных руководством. Кроме того, введение системы электронного обучения позволит унифицировать процесс управления обучающими материалами, необходимых для адаптации персонала', 2, '2022-09-01', '2023-05-30', NULL, 'Иркутская Нефтяная Компания. \r\nГазпром добыча Иркутск.\r\nВСЖД – филиал РЖД', NULL, 'Веб-приложение, запускаемое на сервере организации, дающее возможность организации электронного обучения в рамках процесса адаптации персонала', 'Знать: основные понятия и методы риск-менеджмента; правовые, нормативно-технические и организационно-правовые основы обеспечения безопасности и менеджмента риска на\r\nпредприятиях;\r\nУметь: выявлять риски и оценивать степень риска при управлении качеством; вести документацию по разработке и внедрению систем менеджмента риска;\r\nВладеть: навыками применения инструментов и методов риск-менеджмента по снижению степени риска в системах качества', 'Кокшаров А.В', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(147, NULL, '2022-08-30 13:09:09', 'Формирование компетенции персонала высокотехнологичного предприятия как инструмент обеспечения его конкурентоспособности.  Проектирование UX (пользовательского опыта) и UI (интерфейса) для web-приложения «Система адаптации персонала».     4-Й КУРС', 15, 'Спроектировать интерфейс web-приложения, построенного по типу «электронное обучение» на основе CJM', 'Актуальной задачей обеспечения конкурентоспособности высокотехнологичного предприятия является формирование компетенции персонала. Проблема конкурентоспособности предприятия определяется его ресурсами, и, прежде всего, компетентностью персонала. Это требует формирования СМК, выявление бизнес-процессов, оценку рис-ориентированной деятельности и разработку мер по совершенствованию и улучшению результативности процессов.  Предварительное UX/UI проектирование web-приложения необходимо для сокращения временных издержек при внедрении системы адаптации новых сотрудников высокотехнологичного предприятия и повысит качество разрабатываемого web-приложения. Проектирование интерфейса в соответствии с картой пользовательского пути и учетом достоинств/недостатков аналогичных систем.', 2, '2022-09-01', '2023-05-30', NULL, 'Иркутская Нефтяная Компания. \r\nГазпром добыча Иркутск.\r\nВСЖД – филиал РЖД', NULL, 'Интерфейс web-приложения, готовый для передачи в разработку. Спроектирован с помощью методологии CJM, обоснованы возможные пользовательские цели и пути их решения.', 'Знать: основные понятия и методы риск-менеджмента; правовые, нормативно-технические и организационно-правовые основы обеспечения безопасности и менеджмента риска на\r\nпредприятиях;\r\nУметь: выявлять риски и оценивать степень риска при управлении качеством; вести документацию по разработке и внедрению систем менеджмента риска;\r\nВладеть: навыками применения инструментов и методов риск-менеджмента по снижению степени риска в системах качества', 'Гулов А.Е', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(148, NULL, NULL, 'Информационная система Байкальского региона', 15, 'Создание информационной системы Байкальского региона', 'Целью проекта является создание прототипа интернет-сервиса с картой по Байкалу для российских и иностранных туристов, отличительными особенностями которого будут:\n• Контент для туриста – предоставление информации для планирования отдыха по виду, времени, месту, стоимости и способу проезда.\n• Единая автоматизированная площадка для турбизнеса – возможность для продвижения своих услуг.\n• Интерактивная карта\nСоздание подобного ресурса создаст возможности для увеличения известности и доступности региона  для туристов, привлечет туристов, сделает местный туристический рынок более открытым, гибким, конкурентным.\n', 3, '2022-09-01', '2023-05-30', '', 'Администрация п.Хужир', NULL, 'Прототип информационной системы Байкальского региона', 'Уметь: анализировать и обобщать информацию в сфере маркетинга при управлении проектом;\nВладеть: навыками анализа и обобщения информацию в сфере маркетинга при управлении проектом.\nУметь: использовать современные информационные технологии для сбора, анализа и обобщения информации; \nВладеть: Навыками использования современных информационных технологий для сбора, анализа и обобщения информации\n', 'Куклина Мария Владимировна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(149, NULL, NULL, 'Разработка 3D моделей для рынка Healthnet', 15, '1) Совершенствование оказания медицинской помощи онкологическим пациентам. \n2) Улучшение качества обучения специалистов эндоскопии.\n', 'Злокачественные новообразования (ЗНО) стоят на третьем месте по причинам смерти населения в Российской Федерации, после заболеваний сердечно-сосудистой системы и внешних причин.\nВ ходе проекта будет разработана 3D-модель, созданная на основе механических свойств нормальной и опухолевой тканей, а также программа, благодаря которой улучшится визуализация слабо-контактируемых злокачественных опухолей по МРТ/МСКТ-снимкам. \nПроект позволит с помощью данных технологий воспроизводить высокоточные трехмерные модели человеческих органов в реальном времени.  К аддитивным технологиям относится биомоделирование — создание точной виртуальной или реальной модели интересующей области человеческого организма на основе данных лучевой диагностики, как правило, компьютерной томографии (КТ). Также позволит усовершенствовать диагностику и планирование лечения онкологических пациентов, в том числе хирургическое, злокачественных опухолей.\n3D-печать имеет огромный потенциал в медицине. С помощью этих технологий можно воспроизводить высокоточные трехмерные модели человеческих органов, а также некоторые имплантаты. Разработчики подобных технологий стремятся к созданию органов в реальном времени.\n', 3, '2022-09-01', '2023-05-30', '', 'ГБУЗ Иркутский областной онкологический диспансер', NULL, 'Главная ценность продукта заключатся снизить риски для здоровья пациента. 3D-печать в медицине позволяет с высокой точностью моделировать и создавать стоматологические имплантаты, протезы, прототипы органов. Также 3D-печать помогает уже работающим специалистам и медикам эффективнее учиться и повышать квалификацию, практиковаться и составлять точные планы хирургических операций', 'В результате реализации проекта у студентов должна быть сформирована способность обеспечения практического применения результатов научного исследования:\nПКР-4. Способность определять стоимостную оценку основных ресурсов и затрат по реализации проекта ПКР-5. Способность организовать работу исполнителей в коллективе, находить и принимать управленческие решения в области организации работ по проекту и нормированию труда\nПКР-7. Способность обеспечить практическое применение результатов научного исследования\nПКР-11. Способность спланировать необходимый эксперимент, получить адекватную модель и исследовать ее \n', 'Конюхов Владимир Юрьевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(150, NULL, NULL, 'Разработка модели коммерциализации результатов проекта «Исследование противокоррозионных свойств эпоксидных композиций, допированных ингибиторами коррозии', 15, 'Создание эффективной модели продвижения на рынок результатов НИОКР ВУЗа на примере проекта «Исследование противокоррозионных свойств эпоксидных композиций, допированных ингибиторами коррозии»', '    При реализации НИОКР в рамках ВУЗов одной из основных задач является продвижение их результатов на рынок, а именно: поиск схем и возможностей коммерциализации, привлечение инвесторов, организация высокотехнологичного бизнеса, создание конкурентной среды технологического предпринимательства. Именно при разработке инновационного проекта, решающее значение имеют возможности коммерциализации результатов НИОКР, основанные на проведенных маркетинговых исследованиях. В рамках данного проекта (техническая аспект) исследуются способы защиты металлических конструкций от коррозийных процессов и разрабатывается модель продвижения на рынок результатов исследования (предпринимательский аспект).\n      Коррозия металлов наносит значительный ущерб народному хозяйству нашей страны. Потери от коррозии металлов весомы, они складываются из стоимости изготовления металлических конструкций, пришедших в негодность вследствие коррозии, из безвозвратных потерь в виде продуктов коррозии и из косвенных убытков. В настоящее время большая часть нефтегазовых месторождений находится в поздней стадии разработки, когда снижается добыча и резко возрастает обводненность нефти. Такие месторождения характеризуются значительными осложнениями в процессах добычи, сбора и подготовки нефти, связанными с образованием стойких нефтяных эмульсий, отложениями АСПО, неорганических солей, наличием механических примесей, коррозионным разрушением оборудования и нефтепроводов.Увеличение коррозионной активности, добываемой совместно с нефтью воды на данном этапе является серьезной проблемой. Наиболее эффективным и технологически несложным защитным мероприятием является ингибиторная защита. \n     Именно поэтому исследования способов защиты металлических конструкций от коррозийных процессов и создание эффективной модели бизнеса на основе этих исследований являются крайне актуальными. \n', 2, '2022-09-01', '2023-05-30', '', 'соискатель ИрНИТУ (сотрудник ИАЗ)', NULL, 'Практические рекомендации (алгоритм) по продвижению на рынок результатов НИОКР, осуществляемых в ИрНИТУ', 'В результате реализации проекта у студентов должна быть сформирована способность обеспечения практического применения результатов научного исследования (ПКР-7, в части ПКР-7.3, ПКР-7.4) и: \nзнания основных способов коммерциализации результатов НИОКР;\nумения обеспечения практического применения результатов научного исследования;\nнавыки осуществления деятельности по продвижению на рынок результатов НИОКР. \n', 'Уразова Нина Геннадьевна ', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(151, NULL, NULL, 'Разработка рецептур продуктов питания функционального назначения на основе плодоовощного растительного сырья Иркутской области и организация их безопасного производства ', 15, 'Дать обучающимся возможность приобрести востребованные практико-ориентированные знания, умения, навыки в экспериментальной отработке рецептур функциональных пищевых продуктов и подготовки документации для обеспечения качества, и безопасности их производства.  ', 'Продукты функционального питания и их компоненты могут модифицировать метаболизм в организме человека и играть важную роль в предотвращении возникновения различных заболеваний. При создании безопасного производства продуктов функционального питания необходимо знать химический состав сырья, пищевую ценность, специальные приемы технологической обработки.\nДля обеспечения качества и безопасности продуктов питания необходимо знать и уметь определять факторы, оказывающие негативное влияние на безопасность готовой продукции, зависимость этих факторов от применяемого сырья, технологии, оборудования и упаковки. Применение специальных систем качества и безопасности пищевой продукции позволяет управлять рисками внутри производства и обеспечивать сохранение здоровья потребителя. \n', 1, '2022-09-01', '2023-05-30', '', '', NULL, '1.Разработана рецептура функционального пищевого продукта, проведены эксперименты применения рецептуры с отработкой параметров процесса производства, получен лабораторный образец. \n2.Определены этапы построения системы безопасности пищевой продукции, разработаны обязательные мероприятия для обеспечения безопасности производства, определены возможные риски пищевой безопасности для готовой продукции\n3. Проведены исследования на соответствие показателей качества лабораторного образца требованиям ГОСТ, подтверждено функциональное назначение. Разработана технологическая документация и рекомендации по применению.\n', 'Знания: знать основные принципы организации своей работы, требования к представлению результатов, инструменты поиска информации\nУмения: формулировать цели и задачи; творчески и критически мыслить\nНавыки: работа в команде, получение первичной информации\n', 'Куприна О.В.       , Евстафьева О.А.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(152, NULL, NULL, 'Разработка рецептур продуктов питания функционального назначения на основе растительного сырья Иркутской области и организация их безопасного производства ', 15, 'Дать обучающимся возможность приобрести востребованные практико-ориентированные знания, умения, навыки в экспериментальной отработке рецептур функциональных пищевых продуктов и подготовки документации для обеспечения качества, и безопасности их производства', 'Продукты функционального питания и их компоненты могут модифицировать метаболизм в организме человека и играть важную роль в предотвращении возникновения различных заболеваний. При создании безопасного производства продуктов функционального питания необходимо знать химический состав сырья, пищевую ценность, специальные приемы технологической обработки.\nДля обеспечения качества и безопасности продуктов питания необходимо знать и уметь определять факторы, оказывающие негативное влияние на безопасность готовой продукции, зависимость этих факторов от применяемого сырья, технологии, оборудования и упаковки. Применение специальных систем качества и безопасности пищевой продукции позволяет управлять рисками внутри производства и обеспечивать сохранение здоровья потребителя. \n', 1, '2022-09-01', '2023-05-30', '', '', NULL, '1.Разработана рецептура функционального пищевого продукта, проведены эксперименты применения рецептуры с отработкой параметров процесса производства, получен лабораторный образец. \n2.Определены этапы построения системы безопасности пищевой продукции, разработаны обязательные мероприятия для обеспечения безопасности производства, определены возможные риски пищевой безопасности для готовой продукции\n3. Проведены исследования на соответствие показателей качества лабораторного образца требованиям ГОСТ, подтверждено функциональное назначение. Разработана технологическая документация и рекомендации по применению.\n', 'Знания: знать основные принципы организации своей работы, требования к представлению результатов, инструменты поиска информации\nУмения: формулировать цели и задачи; творчески и критически мыслить\nНавыки: работа в команде, получение первичной информации\n', 'Гусакова Г.С., Евстафьева О.А.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(153, NULL, NULL, 'Организация безопасного производства экологически чистых продуктов питания на основе растительного сырья Иркутской области', 15, 'Дать обучающимся возможность приобрести востребованные практико-ориентированные знания, умения, навыки в подготовки документации для обеспечения качества, и безопасности их производства', 'Для обеспечения качества и безопасности продуктов питания необходимо знать и уметь определять факторы, оказывающие негативное влияние на безопасность готовой продукции, зависимость этих факторов от применяемого сырья, технологии, оборудования и упаковки. Применение специальных систем качества и безопасности пищевой продукции позволяет управлять рисками внутри производства и обеспечивать сохранение здоровья потребителя. ', 3, '2022-09-01', '2023-05-30', '', '', NULL, '1.Определены этапы построения системы безопасности пищевой продукции, разработаны обязательные мероприятия для обеспечения безопасности производства, определены возможные риски пищевой безопасности для готовой продукции', 'Знания: знать основные принципы организации своей работы, требования к представлению результатов, инструменты поиска информации\nУмения: формулировать цели и задачи; творчески и критически мыслить\nНавыки: работа в команде, получение первичной информации\n', 'Евстафьева О.А.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(154, NULL, NULL, 'Спортивные напитки на основе растительного сырья Иркутской области', 15, 'Дать обучающимся возможность приобрести востребованные практико-ориентированные знания, умения, навыки в подготовки документации для обеспечения качества, и безопасности их производства', 'Продукты функционального питания и их компоненты могут модифицировать метаболизм в организме человека и играть важную роль в предотвращении возникновения различных заболеваний. При создании безопасного производства продуктов функционального питания необходимо знать химический состав сырья, пищевую ценность, специальные приемы технологической обработки', 3, '2022-09-01', '2023-05-30', '', '', NULL, '1.Разработана рецептура функционального пищевого продукта, проведены эксперименты применения рецептуры с отработкой параметров процесса производства, получен лабораторный образец. ', 'Знания: знать основные принципы организации своей работы, требования к представлению результатов, инструменты поиска информации\nУмения: формулировать цели и задачи; творчески и критически мыслить\nНавыки: работа в команде, получение первичной информации\n', 'Гусакова Г.С.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(155, NULL, NULL, 'Разработка технологии получения пектинового экстракта на основе растительного сырья Иркутской области и организация их безопасного производства', 15, 'Дать обучающимся возможность приобрести востребованные практико-ориентированные знания, умения, навыки в подготовки документации для обеспечения качества, и безопасности их производства.  ', 'Продукты функционального питания и их компоненты могут модифицировать метаболизм в организме человека и играть важную роль в предотвращении возникновения различных заболеваний. При создании безопасного производства продуктов функционального питания необходимо знать химический состав сырья, пищевую ценность, специальные приемы технологической обработки.', 3, '2022-09-01', '2023-05-30', '', '', NULL, '1.Разработана ТИ функционального пищевого продукта, проведены эксперименты применения с отработкой параметров процесса производства, получен лабораторный образец. \n2.Определены этапы построения системы безопасности пищевой продукции, разработаны обязательные мероприятия для обеспечения безопасности производства, определены возможные риски пищевой безопасности для готовой продукции\n3. Проведены исследования на соответствие показателей качества лабораторного образца требованиям ГОСТ, подтверждено функциональное назначение. Разработана технологическая документация и рекомендации по применению.\n', 'Знания: знать основные принципы организации своей работы, требования к представлению результатов, инструменты поиска информации\nУмения: формулировать цели и задачи; творчески и критически мыслить\nНавыки: работа в команде, получение первичной информации\n', 'Гусакова Г.С.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(156, NULL, NULL, 'Переработка пластиковых отходов.', 15, 'Исследовать возможности переработки бытовых пластиковых отходов.', 'В рамках проекта изучить существующие способы переработки пластиковых отходов, определить наиболее перспективный  способ, провести эксперимент с разными видами пластиков. Исследовать полученные материалы.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Получение синтетического  топлива и определение его свойств. ', 'Знания: способы переработки различных видов пластика,  и методики определения свойств готовых продуктов.\nУмения: подбирать технологию переработки к определенному сырью.\nНавыки: работы с сырьем в лаборатории.\n', 'Оборина М.А.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(157, NULL, NULL, 'Масла  ', 15, 'Изучение свойств масел разной основы и разного состава', 'При производстве товарных масел, разной масляной основы, необходимо введение различных групп присадок (депрессорных, смазывающих, диспергирующих и др.). отвечающих за эксплуатационные характеристики качества товарной продукции. Базы данных на содержание и состав присадок по маслам закрыты, поэтому введение присадок в базовую нефтяную основу и анализ изменения свойств, а также сравнение с товарными производителями, для учебного процесса является актуальной задачей.', 3, '2022-09-01', '2023-05-30', '', 'Кафедра СДМ (получение образцов для дальнейшего исследования)', NULL, 'Получение масляной основы с заданными свойствами в соответствие с нормативной документацией и существующими аналогами товарной продукции.  ', 'Знания: технологических процессов и основного оборудования производства нефтяных масел; основных параметров химмотологии смазочных материалов\nУмения: выявления возможных причин, вызывающих отклонения от норм качества готовой продукции\nНавыки: работы с маслами, а также технических требований к нефтяным маслам и их примения\n', 'Подгорбунская Татьяна Анатольевна, Белозерова Ольга Викторовна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(158, NULL, NULL, 'Пластичные смазки', 15, 'Получение пластичных смазок ', 'В настоящее время промышленность стремительно развивается и характеризуется созданием высокопроизводительных машин и механизмов, генерирующих и передающих большие мощности. По мере распространения технического прогресса усиливается энергонапряженность множественных узлов трения и, соответственно, возрастает роль смазочного материала как наиболее значимого элемента техники, повышаются и становятся разнообразнее требования к его качеству. Работоспособность техники, развитие автомобилестроения и других видов транспортного машиностроения, а, следовательно, и эффективность функционирования народного хозяйства серьезно зависят от их обеспеченности высокоэффективными смазочными материалами – пластичными смазками.\nПроблема – снизить износ поверхностей, подвергающихся трению и нагрузкам. Это позволит продлить срок эксплуатации деталей механизмов, сделает их более долговечными и надежными. В ряде случаев смазки применяются не только для снижения износа, но и для предотвращения трения и заклинивания смежных поверхностей. Благодаря своей пластичности и составу эти мазки защищают от проникновения агрессивных веществ, газов и паров. Также практически все консистентные смазки отличаются антикоррозионными свойствами и т.д. Необходимо расширять сырьевую базу и увеличивать рабочий диапазон применения пластичных смазок\n', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Пластичные смазки с заданными свойствами. Позволит расширить ассортимент данных нефтепродуктов.', 'Знать: основные параметры химмотологии смазочных материалов, технологические процессы и основное оборудование производства масел\nУметь: обосновывать технические требования к пластичным смазкам для обеспечения их рационального применения в современной технике \nВладеть основными требованиями предъявляемые к пластичным смазкам, и научными и практическими достижениями в области химмотологии смазок. \n', 'Белозерова Ольга Викторовна, Подгорбунская Татьяна Анатольевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(159, NULL, NULL, 'Малотоннажная химия', 15, 'Разработать технологическую концепцию переработки пластиковых отходов', 'Самые распространенные способы переработки пластика – это механический и термический. При механическом способе пластиковые отходы подвергают дроблению, измельчению и перетиранию до получения порошка, который далее добавляют в расплав при получении нового материала. А самый распространенный термический способ – это сжигание, при котором происходят выбросы оксида углерода в атмосферу. Данный проект посвящен переработке пластиковых отходов с целью получения исходных мономеров, продуктов имеющих высокую стоимость и востребованность на рынке химических продуктов.', 2, '2022-09-01', '2023-05-30', '', 'Ангара-Реактив, ООО зарегистрирована по адресу 665809, Иркутская обл., г. Ангарск, тер. Первый промышленный массив, кв-л 7, стр. 22, ОФИС 20. Директор организации ООО \"Ангара-Реактив\" Шатохина Валентина Александровна. Основным видом деятельности компании является Производство прочих химических продуктов, не включенных в другие группировки. Также Ангара-Реактив, ООО работает еще по 25 направлениям.\nООО \"Ангара-Реактив\" присвоен ИНН 3801059241, КПП 380101001, ОГРН 1023800520501, ОКПО 55573556\nДействует с 10.07.2001\n', NULL, 'Удобный, безопасный и дешевый способ переработки пластиковых отходов', 'Знать сырье органического синтеза, основные процессы органического синтеза, способы оценки качества целевого продукта, достоверные источники информации и базы данных в области химии.\nУметь искать информацию о химических соединениях по формульным указателям и ключевым словам, составлять химическую схему получения целевого продукта из доступного сырья.\nВладеть критериями выбора оптимальной схемы химической схемы синтеза целевого продукта\n', 'Боженков Георгий Викторович, Чайка анна Анатольевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(160, NULL, NULL, 'Изучение влияния углеводородного состава высокооктановых бензинов на его эксплуатационные характеристики', 15, 'Изучить влияние углеводородного состава высокооктановых бензинов  производства АО «АНХК» на его эксплуатационные характеристики.', 'Важной задачей российской нефтепереработки, повышающей ее конкурентоспособность, является доведение эксплуатационных и экологических свойств автомобильных бензинов до требований мирового уровня. Растет потребность в моторных топливах с октановым числом 95 и выше.  Использование в составе бензинов различного рода добавок и присадок, обеспечивает повышение октанового числа, но при этом необходимо знать какое влияние они окажут на углеводородный состав и как следствие на эксплуатационные характеристики топлива. Поэтому изучение влияния углеводородного состава высокооктановых бензинов  производства АО «АНХК» на его эксплуатационные характеристики является актуальной задаей.', 2, '2022-09-01', '2023-05-30', '', 'АО «АНХК»', NULL, 'Изучено влияние углеводородного состава высокооктановых бензинов  производства АО «АНХК» на его эксплуатационные характеристики.', 'Знания: основные постулаты эффективности добавок и присадок, применяемых для улучшения эксплуатационных характеристик автобензинов\nУмения: на основании теории объяснить эффективность действия октаноповышающих добавок и присадок\nНавыки: владеть навыками оценки влияния углеводородного состава высокооктановых бензинов на его эксплуатационные характеристики.\n', 'Ганина Анна Александровна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(162, NULL, NULL, 'Полифункциональные (нано)композиты – молекулярный дизайн, структурные особенности, фундаментальные свойства.', 15, 'Создание  новых полифункциональных композитов с целенаправленно формируемой структурой и свойствами для водородной энергетики.', 'Полимерные композиты, сформированные в результате комбинации компонентов различной химической природы, представляют собой новый класс композиционных материалов с характеристиками, превосходящими аналогичные показатели отдельно взятых составляющих. В результате композиционного эффекта они проявляют уникальные механические, магнитные, оптоэлектронные и др. свойства, обладают высокой химической и термической стабильностью, а также устойчивостью к УФ-излучению. Существенное влияние на свойства таких композитов оказывает переход к нанометровому диапазону размеров индивидуальных компонентов системы. Обширную группу органо-неорганических композитов составляют структуры на основе диоксида кремния, полученные в результате золь-гель процесса с участием тетралкоксисиланов в присутствии высокомолекулярных соединений. Основная роль кремнийорганического прекурсора в таких системах сводится к регулированию процесса структурообразования композита, возможности управления размерами наночастиц и физико-техническими характеристиками материала. При этом кремниевый компонент композита - диоксид кремния, не содержит функциональных групп. В качестве носителя химически-активных фрагментов выступают функциональные высокомолекулярные соединения. Строение функциональных групп предшественников композитов позволит регулировать особенности их структуры и комплекс физико-химических свойств. В результате проведенных исследований будет установлена принципиальная возможность использования предлагаемых полифункциональных композитов при конструировании топливных элементов.', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Полимерные мембраны для топливных элементов, обладающие протонной проводимостью. Физический прототип.', 'Знания: Способы и лабораторные методы получения полимерных мембран.\nУмения: Выбирать рациональную схему получения полимерной мембраны для топливных элементов с заданными эксплуатационными свойствами.\nНавыки: Синтезировать полимерной мембраны для топливных элементов с заданными эксплуатационными свойствами\n', 'Шаглаева Нина Савельевна, Баяндин Виктор Владимирович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(163, NULL, '2022-08-30 13:09:56', 'Статистическая обработка эксперимента', 15, 'Анализ экспериментальных данных, способность обсуждать полученные результаты и предвидеть течение эксперимента в перспективе', 'Проведение эксперимента - это только часть научной задачи. Главная роль исследователя планирование процесса заранее (предвидеть разные направления) и умение интерпретировать полученные данные, которые в дальнейшем должны реализоваться в научной публикации.', 1, '2022-09-01', '2023-05-30', NULL, NULL, NULL, 'не указан', 'Знать принципы измерения и аппаратурное оформление, возможности и ограничения каждого метода\r\nУметь обобщать полученные результаты Владеть методами планирования и проведения эксперимента и оценки полученных результатов', 'Айзина Юлия Александровна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(164, NULL, NULL, 'Браслеты с GPS-трекерами для контроля за состоянием здоровья, подключением техники безопасности и улучшением производственного травматизма.', 15, 'оснащение производственных рабочих браслетами с GPS-трекерами для контроля за состоянием здоровья, подключением техники безопасности и улучшением производственного травматизма.', 'ввиду удаленности большинства ремонтных участков Группы Компаний от специалистов по охране труда существует потребность в удаленном мониторинге соблюдения техники безопасности и состояния здоровья рабочих. В рамках проекта предлагается разработать прототип, основанный на измерении показателей состояния сотрудников с возможностью геопозиционирования и разграничения рабочих и опасных зон.', 3, '2022-09-01', '2023-05-30', '', 'Лаборатория энергетики Акселерационная программа, реализуемая ГК «ЕвроСибЭнерго» на базе ИРНИТУ\n\n\n\nконкурс научно-исследовательских проектов \"Авангард науки\"\n\nЛаборатория энергетики:\n“Оснащение производственных рабочих браслетами с GPS-трекерами для контроля за состоянием здоровья, подключением техники безопасности и улучшением производственного травматизма.”\n', NULL, 'Определен оптимальный функционал, заданы ключевые параметры отслеживания.\nРазработано техническое решение. Проработаны возможные поставщики оборудования, программного обеспечения.\n', 'Знать виды, функциональное назначение, свойства беспроводных персональных сетей \nУметь составлять алгоритм работы устройства для конкретного назначения.\nВладеть навыками использования программных продуктов, предназначенных для программирования миниатюрных вычислительных устройств\n', 'Губин Никита Андреевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(165, NULL, NULL, 'Наблюдение измеряемых параметров физических сред и предметов с использованием  децентрализованных самоорганизующихся сетей', 15, 'Формирование знаний о структуре сети, основных протоколах и порядке передачи данных, удаленном мониторинге и измерении физических величин, перспективных способах измерений и передачи данных нового поколения.', 'Глобализация рынков, конкуренция, стремительное развитие технологий и наукоемких инноваций, появление сверхсложных научно-технических проблем требует от промышленности гораздо более быстрых темпов развития, предельно коротких циклов контроля и измерения физических характеристик в процессе разработки и производства продукции высокого качества. \nСпрос на сложные многофункциональные инженерные изделия стимулирует процесс постоянных модификаций как самих устройств так и способов их взаимодействия.\nПерспективным трендом является создание беспроводных децентрализованных самоорганизующихся сенсорных сетей, состоящих из беспроводных сенсоров и управляющих устройств способных к самоорганизации с помощью интеллектуальных алгоритмов,\nВ рамках проекта студентам предлагается провести анализ новых способов удаленного мониторинга и контроля, получить общие навыки по измерениям и мониторингу состояния  здоровья человека, окружающей среды, функционирования производственных и транспортных систем, учета различных ресурсов и др. \nЗнания, которые будут получены учащимися в ходе проектной работы, могут быть применены в их дальнейшей научно-исследовательской деятельности.   \n', 2, '2022-09-01', '2023-05-30', '', 'Лаборатория энергетики Акселерационная программа, реализуемая ГК «ЕвроСибЭнерго» на базе ИРНИТУ\n\n\n\nконкурс научно-исследовательских проектов \"Авангард науки\"\n\nЛаборатория энергетики:\n1)интеллектуальная система смазки подшипников электромашин постоянного тока.\n2)система централизованной смазки стрелы и находящейся на ней элементов.\n', NULL, 'Разработка лабораторного стенда, с сетью взаимосвязанных заменяемых беспроводных датчиков.', 'Знать виды, функциональное назначение, свойства беспроводных персональных сетей \nУметь составлять алгоритм работы устройства для конкретного назначения.\nВладеть навыками использования программных продуктов, предназначенных для программирования миниатюрных вычислительных устройств\n', 'Губин Никита Андреевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(166, NULL, NULL, 'Система контроля целостности металлоконструкции стрелы экскаватора марки ЭШ', 15, 'Разработка системы контроля целостности металлоконструкции стрелы экскаватора марки ЭШ', 'Измерение целостности металлоконструкции стрелы эксковатора', 3, '2022-09-01', '2023-05-30', '', 'Лаборатория энергетики Акселерационная программа, реализуемая ГК «ЕвроСибЭнерго» на базе ИРНИТУ\n\n\n\nконкурс научно-исследовательских проектов \"Авангард науки\"\n\nЛаборатория энергетики:\n“ Система контроля целостности металлоконструкции стрелы экскаватора марки ЭШ.”\n', NULL, 'Система контроля целостности металлоконструкции стрелы экскаватора марки ЭШ', 'Знать виды, функциональное назначение, свойства датчиков угла наклона \nУметь составлять алгоритм работы программы. \nВладеть навыками использования программных продуктов, предназначенных для программирования микроконтроллеров\n', 'Ченский Дмитрий Александрович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(167, NULL, NULL, 'Вибродиагностика сороудерживающих решеток', 15, 'Разработка системы мониторинга уровня вибрации сороудерживающих решёток братской ГЭС с целью выявления предельных нагрузок.', 'Вибродиагностика сороудерживающих решёток братской ГЭС с целью выявления предельных нагрузок.', 3, '2022-09-01', '2023-05-30', '', 'Лаборатория энергетики Акселерационная программа, реализуемая ГК «ЕвроСибЭнерго» на базе ИРНИТУ\n\n\n\nконкурс научно-исследовательских проектов \"Авангард науки\"\n\nЛаборатория энергетики:\n“ Вибродиагностика сороудерживающих решеток.”\n', NULL, 'Система мониторинга уровня вибрации сороудерживающих решёток', 'Знать виды, функциональное назначение, свойства датчиков вибрации  \nУметь составлять алгоритм работы устройства для конкретного назначения.\nВладеть навыками использования программных продуктов, предназначенных для программирования микроконтроллеров\n', 'Ченский Дмитрий Александрович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(168, NULL, NULL, 'влияние  пористых  алюмосиликатных  матриц  на свойства протон-проводящих мембран  для топливных элементов', 15, 'Изучить влияние различных пористых алюмосиликатных матриц, в частности, цеолитов разных структурных типов на характеристики протон-проводящих мембран для топливных элементов.', 'Ионообменные мембраны на основе поливинилового спирта (ПВС) представляют собой перспективную группу материалов для применения в тведополимерных топливных элементах (ТПТЭ) благодаря высокой гидрофильности, способности к пленкообразованию, низкой стоимости, хорошим механическим свойствам и возможности сшивания ПВС различными химическими реагентами. Для улучшения технических характеристик таких мембран, используют керамические материалы на основе оксидов алюминия, кремния, титана, олова, циркония и др., которые способные повысить ионную проводимость, химическую и термическую стабильность, а также механическую прочность мембран. В настоящее время   большое внимание уделяется  получению новых биоразлагаемых протонообменных мембран для ТПТЭ, полученных на основе сшитого сульфоянтарной кислотой поливинилового спирта с добавлением в качестве кислотного компонента – цеолитов. В работе предлагается для получения таких мембран использовать цеолиты различных структурных типов и изучить влияние не только структурного типа цеолита, но и его содержания на характеристики мембран. ', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Предполагается получение протон-проводящих мембран на основе цеолитов разных структурных типов и изучение их характеристик. ', 'Знания: углубленные знания золь-гель технологии; технологии синтеза цеолитных материалов, методов тестирования характеристик мембран для ТПТЭ; \nУмения: выбрать соответствующие методы и подходы для синтеза мембран для ТПТЭ;\nНавыки: использования методов синтеза протон-проводящих мембран и тестирования их рабочих характеристик.\n', 'Скорникова Светлана Афанасьевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(169, NULL, NULL, 'влияние  модифицирования  алюмосиликатов  на  их  физико-химические характеристики', 15, 'Исследовать влияние различных способов модифицирования синтетических алюмосиликатов, в том числе цеолитов, на их физико-химические характеристики. ', 'Цеолиты находят широкое применение в нефтехимии и нефтепереработке. Кроме этого в последнее время возрос интерес к цеолитам и в качестве уникальных адсорбентов, которые нашли применение и в медицине. С этой целью возрос интерес исследователей к разработке нетрадиционных способов их модифицирования для получения новых характеристик, таких как микро-мезопористая структура, магнитные характеристики, кислотные свойства и др. В связи с этим целью данного проекта является  изучение влияние различных способов модифицирования цеолитов на их физико-химические свойства.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Получены модифицированные образцы цеолитов, изучены их характеристики. ', 'Знания: получены углубленные знания в области поверхностных явлений в дисперсных системах и физико-химии наноразмерных систем; \nУмения: выбрать оптимальные способы модифицирования цеолитов; \nНавыки: использовать их для получения соответствующих характеристик цеолитов\n', 'Скорникова Светлана Афанасьевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(170, NULL, NULL, 'синтез  магнитоуправляемых композитов на основе цеолитов и магнитных наночастиц', 15, 'Целью проекта является создание наноразмерных магнитных цеолитов путем добавления магнитных F3O4 частиц в процессе кристаллизации, для получения кристаллов цеолита с магнитным ядром внутри структуры.', 'Получение магнитных нанокомпозитов на основе пористых носителей является одним из возможных способов разработки систем адресной магнитоуправляемой доставки лекарственных препаратов. Определенный интерес вызывает получение композитных материалов на основе цеолитов и наночастиц магнетита. Цеолиты - это микропористые кристаллические вещества. Кристалличность обеспечивает механическую и химическую стабильность цеолитов, одинаковый и контролируемый размер пор, каналов, полостей. Это свойство определяет использование цеолитов в качестве молекулярных сит, адсорбентов, детергентов. Благодаря своим ионообменным и сорбционным свойствам, широко применяются для химической, нефтехимической и нефтеперерабатывающей промышленности, экологии и медицины.  Цеолиты благодаря особенностям своей структуры являются уникальными сорбентами, позволяющими осуществлять эффективную адсорбцию и высвобождение лекарственных препаратов в физиологической среде организма, при этом они являются нетоксичными и биоразлагаемыми материалами. Модифицирование цеолитов магнитными наночастицами позволяет придать им магнитные свойства', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Планируется получить магнитоуправляемый композитов на основе цеолитов и магнитных наночастиц. Данный нанокомпозит будет иметь уникальные свойства цеолита и обладать магнитными свойствами, что позволит увеличить области возможного его применения.  ', 'Знания: дополнительные знания в области нанохимии магнитных материалов;\nУмения: применять методы соосаждения, золь-гель методы и гидротермальный синтез для получения магнитных композитов на основе цеолитов;\nНавыки: гидротермального синтеза цеолитов с магнитным ядром, позволяющие получить материалы с магнитными свойствами и высокой адсорбционной способностью.\n', 'Скорникова Светлана Афанасьевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(171, NULL, NULL, 'Выполнение планировочного раздела проектной документации', 15, 'разработка раздела проектной документации - Генеральный План', 'Ознакомление с функциями архитектора,  главного архитектора проекта и главного инженера проекта, организация процесса проектирования.\nСостав проектной документации «П» и объем выполнения рабочей документации «Р»\n', 1, '2022-09-01', '2023-05-30', '', '', NULL, 'Комплект чертежей', 'Знания: основные требования к выполнению раздела проектной документации. \nУмения: обосновывать принятые проектные решения\nНавыки: оформления проекта\n', 'Иванова Анастасия Сергеевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(172, NULL, NULL, 'Малоэтажный жилой дом', 15, 'Создание эскизного концептуального проекта малоэтажного жилого дома', 'Определения понятия предмета проектирования - (малоэтажный жилой дом: типология, эволюция, современные тенденции).  Определение композиционно-образного решения жилого дома;  анализ градостроительных условий, определение функциональной структуры и объемно - планировочной композиции жилого дома:  (план фундамента, поэтажные планы, план крыши, узлы, детали, разрезы, спецификации). Эскизы фрагментов, планировка, этажей и уровней. ', 1, '2022-09-01', '2023-05-30', '', '', NULL, 'Эскизный концептуальный проекта малоэтажного жилого дома', 'Знания: Основы взаимодействия со специалистами смежных областей. Основа архитектурно-строительного проектирования\nУмения: Взаимодействовать со специалистами смежных областей входе разработки жилых объектов. Участвовать в разработке проектной документации. Грамотно представлять проектный замысел, передавать идеи средствами компьютерной графики\nНавыки: Работы в творческом коллективе; Навыки участия в разработки проектной документации\n', 'Дайнеко Виктория Владимировна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(173, NULL, NULL, 'Реновация общественного здания', 15, 'Цель продукта: Усовершенствование дизайна городской архитектурной среды, профессиональное применение современных материалов.\nОбразовательная цель:  формирование у студентов соответствующих  знаний, навыков, мотивации  и ответственности\n', 'Предполагаемая организация делает запрос на выполнение реновации с возможной с архитектурной реконструкцией общественного здания, включая интерьер, экстерьер и благоустройство', 1, '2022-09-01', '2023-05-30', '', 'Предприятие, сторонняя организация', NULL, 'Стильное современное общественное пространство здания и его окружения с индивидуальной концепцией, с разработанными эксклюзивными авторскими предметами и малыми архитектурными формами.', 'Знания:    принимать объемно-пространственные, конструктивные, художественные, инженерные решения, понимать эксплуатационные качества объектов проектирования\nУмения:  учитывать взаимосвязь всех этих компонентов - объемно-пространственных, художественных, конструктивных, инженерных, эксплуатационных качеств объектов проектирования\nНавыки:  формировать объемно-пространственную среду, учитывая ее художественные, конструктивные, инженерные и эксплуатационные особенности\n', 'Глебова Наталья Моисеевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(174, NULL, NULL, 'Интерьер музея. «Концепция Школьного музея МБОУ «Буретская СОШ».', 15, 'Реализовать умение выполнять поиск, критический анализ и синтез информации, применять системный подход для решения задач, разработать проект на основе оценки требований, ресурсов и ограничений, работать в команде, управлять своим временем, выстраивать и реализовывать траекторию создания целостного, насыщенного многофункциональной инфраструктурой пространства', 'Проект музея направлен на сохранение исторической памяти и наследия; развитие интереса к истории, углубление знаний по истории и формирование на конкретном историческом материале гражданско – патриотических чувств и убеждений, утверждение значимости таких ценностей. Воспитание у учащихся стремления к овладению глубокими знаниями, высоконравственными качествами в процессе изучения истории, культуры родного края. Основные  задачи программы-проекта: Через краеведческий материал осуществлять связь с окружающей обстановкой, воспитания патриотического чувства, любви к Родине, к родному городу, своему поселку. Для архитектурно-дизайнерской классификации существенное значение имеет комплексный характер экспозиции; развитый состав помещений, включающий зоны для постоянной экспозиции, временных выставок и лекций, фондохранилища, мастерские и лаборатории, административные, подсобные и хозяйственные помещения. представляющие сочетание новых пространств с существующими. Общепринятое понимание музея как хранителя подлинных экспонатов и место их показа уходит на второй план: на первое место выделяется не показ музейными средствами, а создание пространства архитектурно-художественными средствами. Важную роль в архитектурно-пространственном формировании интерьера имеет существующее окружение, сохраняемая или создаваемая среда, в которую включается комплекс. Учитывая ярко выраженную специфику, музеи школ могут быть выделены по пространственным решениям в самостоятельную группу.', 3, '2022-09-01', '2023-05-30', '', 'МБОУ «Буретская СОШ», Иркутская обл., директор Серова С.В.', NULL, '«Концепция Школьного музея» (альбом чертежей)', 'Знания: основные принципы планирования и организации своей деятельности, инструменты поиска информации, основные стратегии поиска информации, требования и ресурсные ограничения  к представлению результатов проекта, основные приемы управления.\nУмения: использовать различные инструменты поиска и анализа информации, критически оценивать и подготовить полученные результаты, выполнять критический анализ и сформулировать перечень недостающих  знаний, организовывать работы команды (коллектива) для достижения поставленных целей.\nНавыки: поиска и анализа информации, определения и постановки задач,  организации работы команды, четкого формулирования запроса на поиск новых знаний, на основе полученной первичной информации сформировать комплексное понимание предмета изучения, разработки стратегии разработки проекта  на основе сформулированного запроса, презентации результатов проекта,навыками командной работы и управления коллективом.\n', 'Хохрин Евгений Викторович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(175, NULL, NULL, 'Интерьер музея. «Разработка интерьера Школьного музея МБОУ «Буретская СОШ».', 15, 'Реализовать умение выполнять поиск, критический анализ и синтез информации, применять системный подход для решения задач, разработать проект на основе оценки требований, ресурсов и ограничений, работать в команде, управлять своим временем, выстраивать и реализовывать траекторию создания целостного, насыщенного многофункциональной инфраструктурой пространства.', 'Категория музея определяется величиной фондов и количеством посещений. Музеи подразделяются по организационному признаку на центральные, осуществляющие научно-методическое руководство своей группой; появились музеи, представляющие собой концептуальный литературный художественный образ. Изменилась стилевая характеристика зданий, вызванная свободным решением разверток стен  и планов. Как и другие типы пространств, музеи проектируются вразличных стилях. Стилевая направленность часто совпадает с профилем музея. Известны такие как: краеведческие, региональные, мемориальные, в память исторических событий, современного искусства, промышленности и техники, частных коллекций, города и др. Музей характеризуется для городов и населённых мест с учётом различных концепций развития комфортной социальной среды. Поиск архитектурно-художественного образа музейного здания является одной из первостепенных задач проектирования. Специальное внимание уделяется художественному, эмоциональному, выразительному решениюпространства музея.\nИнтерьер музея проектируется из расчёта единовременного пребывания в нём 15 и более посетителей\n', 3, '2022-09-01', '2023-05-30', '', 'МБОУ «Буретская СОШ», Иркутская обл.,\nдиректор Серова С.В\n', NULL, '«Интерьер Школьного музея» (альбом чертежей)', 'Знания: принципы формирования командной стратегии, нормы и способы социального взаимодействия, различные инструменты поиска и анализа информации, основные способы выражения авторского архитектурного замысла, технологии архитектурно-строительного проектирования, \nУмения: на основе синтеза и анализа информации получить представление о связях между составляющими предмета изучения, учитывать взаимосвязь объемно-пространственных, конструктивных, инженерных решений и эксплуатационных качеств объектов проектирования,\nНавыки: уметь спланировать и реализовать проект с учетом ресурсных ограничений и требований к результату  проекта; презентации результатов проекта,\n', 'Смольков Сергей Александрович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(176, NULL, NULL, 'Выполнение архитектурного раздела проектной документации', 15, 'разработка раздела проектной документации марки «АР» - архитектурные решения', 'Создание проектной документации в соответствии с  действующими стандартами, комплекта чертежей ПЗУ (ГП) на основе предложенного объекта с посадкой его на топографической съёмке участка в составе: План благоустройства территории, План организации рельефа, План и конструкции дорожных одежд (покрытий)\nСоздание проектной документации в соответствии с действующими стандартами комплекта чертежей АР на основе предложенного проекта здания в составе: Планы, Разрезы, Фасады, Необходимые узлы и детали\n', 3, '2022-09-01', '2023-05-30', '', 'Проектные институты, \nчастные проектные предприятия и фирмы\n', NULL, 'Комплект чертежей марки «АР»', 'Знания: Ознакомление и изучение действующих требований к комплектам проектных документов на различные здания и сооружения\nУмения: Создание комплектов  рабочей документации для различных объектов\nНавыки: Освоение профессионального языка и взаимоотношение со смежными специальностями\n', 'Жуковский Николай Леонидович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(177, NULL, NULL, 'Многоэтажный общественный административный корпус ИРНИТУ', 15, 'Улучшение пространственно - планировочных, эксплуатационных, функциональных, эстетических характеристик университета, значительное увеличение полезной рабочей площади, создание образа современного высокотехнологичного вуза и кампуса ИРНИТУ.', 'Многоэтажный общественный административный корпус ИРНИТУ предполагается разместить со стороны существующего главного входа в университет по ул. Лермонтова. В отдельно стоящем монолитно - каркасном блоке – многоэтажной башне помимо необходимых помещений для ректората и сопутствующих административных служб должны разместиться представительские помещения для переговоров, совещаний, конференций, просторные холлы, выставочные пространства с витринами для демонстраций ярких студенческих разработок: проектов и моделей. Башня соединяется с существующим зданием двухэтажным блоком, где возможно размещение просторного светлого входного вестибюля с гардеробом (в цоколе), кафе, второго спортзала, других общественных пространств и помещений. Башня должна быть доминантой в окружающей застройке, архитектура нового корпуса решается в современной стилистике, гармоничной и выразительной, и отражающей современные технологии и достижения в строительстве, технике и науке', 3, '2022-09-01', '2023-05-30', '', 'Ректорат ИРНИТУ ', NULL, 'Рабочий проект многоэтажного общественного административного корпуса ИРНИТУ, встроенно – пристроенного к существующему зданию', 'Знания: современные тенденции в архитектуре, современные строительные конструкции и технологии строительства, инженерные коммуникации\nУмения: проектировать общественное здание - образовательное учреждение со сложными функциональными зонами и связями между ними, передать молодежную атмосферу.\nНавыки: разработка архитектурных, конструктивных, инженерных рабочих чертежей зданий, в том числе разделов ОВ, ВК, слаботочных и электрики, чертежей раздела генерального плана участка.\n', 'Дагданова Цыредарь Баторовна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(178, NULL, NULL, 'Проектирование многоквартирного жилого здания (группы зданий) малой или средней этажности', 15, 'Создание эскизного концептуального проекта жилого здания (группы зданий) малой или средней этажности', 'Проектирование жилого здания (группы зданий) малой или средней этажности имеет ряд требований: природно-климатические условия площадки проектирования, социально-демографические, градостроительные и экологические факторы, учет особенностей существующей застройки, в том числе исторически сложившейся среды (контекст среды), уклад жизни и национальные особенности людей. Для формирования уникального образа жилого здания (группы домов) малой или средней этажности необходимо знать особенности конструктивных решений жилых зданий, владеть знаниями о типологии квартир зданий малой или средней этажности, видах застройки и типах жилых зданий. Любое жилое здание оснащается инженерным оборудованием, имеющее свои особенности, требования и характеристики, которое может быть проработано в случае участия в проекте студентов смежных специальностей. \nПроект выполняется в два этапа (два семестра). На предварительной стадии анализируются примеры жилых зданий, изучается их типология, проводится поиск оригинальных решений планировок и образа жилого здания (группы домов) малой или средней этажности. Могут быть выполнены предварительные эскизы, черновые макеты и применены другие графические поиски в ручном исполнении или с помощью ПК. На следующем этапе командой студентов прорабатываются чертежи раздела АР и других при участии студентов других направлений. \nТаким образом, может быть выполнен комплексный концептуальный проект жилого здания (группы домов) на свободной от застройки площадке или с учетом контекста исторически сложившейся среды\n', 1, '2022-09-01', '2023-05-30', '', 'Проектные мастерские, администрация города/ области, застройщики', NULL, 'Оформление поиска объемно-планировочных решений на планшет(ы), ПЗ и/ или альбом чертежей проекта жилого здания (группы зданий) малой или средней этажности', 'Знания: основные требования  к представлению результатов проекта\nУмения: обосновывать принятые проектные решения\nНавыки: презентации результатов проекта\n', 'Дружинина Инна Евгеньевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(179, NULL, NULL, 'Проектирование общественного здания', 15, 'Создание эскизного концептуального проекта общественного здания', 'Проектирование общественного здания имеет ряд требований: знание типологии общественных зданий, особенности их функционального зонирования и технологических процессов, размещение объектов общественного назначения в градостроительной ситуации, учет контекста среды, в том числе и исторической, а также природно-климатические условия, экологические факторы и многое другое. В зависимости от назначения общественного здания, формируется его объемно-планировочное решение и в целом архитектурный образ. \nЛюбое общественное здание имеет свою классификацию и в соответствии с типологическим рангом является второстепенным или доминирующим в градостроительной среде. Для создания уникального образа общественного здания необходимо знать особенности конструктивных решений, владеть знаниями о технологических процессах внутренней организации. Любое общественное здание оснащается инженерным оборудованием, имеющее свои особенности, требования и характеристики, которое может быть учтено в случае работы над проектом студентов смежных специальностей.\nНа предварительной стадии выполняется анализ примеров общественных зданий, изучается их типология, проводится поиск оригинальных решений планировок и образа здания общественного назначения. Могут быть выполнены предварительные эскизы, черновые макеты и применены другие графические поиски в ручном исполнении или с помощью ПК. \nТаким образом, может быть выполнен комплексный концептуальный проект общественного здания на свободной от застройки площадке или с учетом контекста исторически сложившейся среды.\n', 3, '2022-09-01', '2023-05-30', '', 'Союз архитекторов РФ', NULL, 'Планировка общественного здания с проработкой функционального зонирования здания, поиск образа, объемного решения', 'Знания: Знать основные требования  к представлению результатов проекта\nУмения: Уметь  обосновывать принятые проектные решения\nНавыки: Владеть навыками презентации результатов проекта\n', 'Селиванов Роман Александрович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(180, NULL, NULL, 'Конструктивные и технологические решения проектов реставрации объектов культурного наследия (памятников архитектуры)', 15, 'Разработка проектов реставрации объектов культурного наследия и чертежей проектной документации, а также расчет строительных конструкций в программно-вычислительном комплексе.', 'Обзор и анализ имеющихся программных продуктов по моделированию и расчету зданий и сооружений. Изучение программных комплексов по моделированию и расчету строительных конструкций. Подбор и разработка оптимальных методик моделирования и расчета. Реализация практических расчетов и моделирования конструктивных систем. Подготовка и оформление разделов проектной документации в соответствии с действующей нормативно-правовой базой.', 3, '2022-09-01', '2023-05-30', '', 'Иркутский областной историко-мемориальный музей декабристов', NULL, 'Информационные модели зданий (сооружений); методики и технологии реставрационно-восстановительных работ; Отчет по результатам расчетов в программно-вычислительном комплексе.', 'Знания: Знать нормативно-правовую базу в строительстве. Знать основные принципы и особенности расчета конструкций в особых условиях работы.\n\nУмения: Уметь применять на практике полученные знания. Уметь учитывать специфику особых условий в составлении расчетных схем несущих и ограждающих конструкций. \n\nНавыки: Владеть современными информационными технологиями проектирования. Владеть навыками моделирования, расчета и конструирования строительных узлов, систем и деталей.\n', 'Пинайкин Игорь Петрович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(181, NULL, NULL, 'Современные технологии исследования и проектирования объектов деревянного зодчества', 15, 'Разработка проектной документации объектов деревянного зодчества, которая включает в себя текстовые и графических материалы, определяющие архитектурные, функционально-технологические, конструктивные и инженерно-технические решения. ', 'Проектная документация необходима для оценки соответствия принятых решений требованиям законодательства и нормативным правовым актам. В ходе прохождения курса необходимо выполнить подбор и разработку оптимальных методик моделирования и проектирования; подготовку и оформление разделов проектной документации в соответствии с действующей нормативно-правовой базой; обзор и анализ имеющихся программных продуктов по моделированию зданий и сооружений. ', 3, '2022-09-01', '2023-05-30', '', 'Экопарк \"Озера на снежной\"', NULL, 'Информационные модели зданий (сооружений); методики и технологии реставрационно-восстановительных работ объектов деревянного зодчества; Текстовая и графическая часть проектной документации.', 'Знания: Знать нормативно-правовую базу в строительстве. Знать основные принципы проектирования конструкций в особых условиях работы.\nУмения: Уметь применять на практике полученные знания. \nНавыки: Владеть современными информационными технологиями проектирования. Владеть навыками моделирования и конструирования строительных узлов, систем и деталей.\n', 'Пинайкин Игорь Петрович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(182, NULL, NULL, 'Методологические и экономические аспекты информационного моделирования объекта капитального строительства', 15, 'Отработка процесса проектирования с использованием BIM-технологий на различных этапах жизненного цикла зданий и сооружений.', 'Создание информационной модели объекта капитального строительства (технопарк ИРНИТУ).', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Электронная модель сооружения', 'Знания: структура процесса информационного моделирования, состав проекта\nУмения: работа в команде, проектное мышление\nНавыки: моделирование в BIM программах\n', 'Созонов Павел Сергеевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(183, NULL, '2022-08-30 09:34:49', 'Конструктивные и технологические особенности проектирования, строительства, реконструкции, капитального ремонта объектов, эксплуатируемых в экстремальных природно-климатических и техногенных условиях и находящихся в аварийном состоянии', 15, 'Отработка процесса моделирования строительных процессов с использованием BIM-технологий на различных этапах жизненного цикла зданий и сооружений.', 'нет описания', 3, '2022-09-01', '2023-05-30', NULL, NULL, NULL, 'Электронная модель сооружения', 'Знания: структура процесса информационного моделирования, состав процесса строительства\r\nУмения: работа в команде, проектное мышление\r\nНавыки: моделирование в BIM программах', 'Петров Александр Владимирович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(184, NULL, NULL, 'Прогрессивные технологии возведения зданий', 15, 'Разработка новых конструктивных и технологических решений быстровозводимых зданий.', 'Обеспечение высоких технико-экономических показателей возводимых зданий.\n\n• Обеспечение технологичности при строительстве быстровозводимых зданий;\n\n• оптимизация конструктивных и технологических решений при строительстве быстровозводимых зданий\n', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'электронной модели изделия (сооружения)', '', 'Петунин Александр Геннадьевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(185, NULL, NULL, 'Проектирование процессов восстановления работоспособности зданий и сооружений, отдельных элементов, конструкций, узлов по результатам обследования их технического состояния', 15, 'Ознакомление с методикой и приобретение практических навыков при визуально-инструментальном обследовании технического состояния зданий и сооружений, систематизации фактического материала, анализа полученных результатов, формирования выводов, поиска технических решений проблемы и участия в проектировании ремонтно-восстановительных работ', 'Исключение аварийности зданий и сооружений и приведение объектов капитального строительства находящихся в неисправном или ограниченно-работоспособном состоянии в исправное техническое состояние.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'База данных полученных в составе коллектива исполнителей на реальных объектах капитального строительства, статистическая обработка, поверочные расчеты, формирование выводов, проектные решения.', 'Знать\nИзучение методики и методов проведения обследования технического состояния зданий и сооружений, причин возникновения дефектов и деформации, назначение и порядок использования приборов и оборудования. Изучение нормативных документов регламентирующих требования к проведению обследований строительных объектов и работам по контролю за уровнем безопасности зданий и сооружений\nУметь\nПрименять на практике различные методики и методы обследования зданий и сооружений, используя действующие нормативные документы; выявлять, фиксировать дефекты и повреждения, анализировать причины их появления, оценивать техническое состояние объектов.\nВладеть\nОбщими организационными вопросами обследования технического состояния зданий и сооружений, сбора материалов и необходимой технической информации для реализации проекта ремонтно-восстановительных работ.\nЗнать\nСостав, содержание и требования к полноте разделов комплексной программы обследования технического состояния зданий и сооружений; требования к корректности и обоснованности выводов.\nУметь\nПод руководством научного руководителя разрабатывать отдельные темы программы комплексных обследований конструкции зданий и сооружений; проводить обработку полученных данных.\nВладеть\nНавыками составления программ комплексного обследования зданий и сооружений; под руководством научного руководителя определять категорию технического состояния конструкций и сооружений; оценивать необходимый объем работ для включения в техническое задание для программы. \n', 'Комаров Константин Андреевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(186, NULL, NULL, 'Разработка проекта капитального ремонта жилого дома с применением цифровых технологий', 15, 'Создание проекта капитального ремонта жилого дома на основе визуального обследования и обмера с применением различных проектных программ', 'Капитальный ремонт жилых многоквартирных домов является острой проблемой, для решения которой в нашей стране были созданы фонды капитального ремонта многоквартирных домов. Для более качественного выполнения ремонтных работ и расчета сметной стоимости возникает необходимость в создание проектно-сметной документации. Студенты могут на основе реальных объектов выполнить ряд практических задач: визуальный осмотр, выявления дефектов, обмер здания, создание графических чертежей в цифровой среде, расчет объемов работ, описание технологии производства работ. По окончанию работы студенты представляют готовый проект', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Проект капитального ремонта многоквартирного жилого дома', 'Знать перечень работ входящих в состав капитального ремонта и технологию их выполнения уметь выполнять создавать проектную документацию в цифровой среде', 'Ефременко Антон Сергеевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(187, NULL, NULL, 'Информационные технологии в дорожном строительстве', 15, 'Разработка методических основ и прикладного инструментария по совершенствованию информационных технологий по проектированию, строительству, эксплуатации, мониторингу автомобильных дорог и искусственных сооружений.', ' Проект направлен на усовершенствование и систематизацию средств информационных систем, предназначенные для решения задач дорожного строительства.', 3, '2022-09-01', '2023-05-30', '', 'Администрация города Иркутска', NULL, 'Разработка  методических основ, механизмов, моделей и практических рекомендаций по применению эффективных инструментов для информационных систем, применимых в дорожном строительстве.', 'Знания: в области информационных технологий дорожного строительства.\nУмения: использовать инструментарий информационных систем для достижения конкретных целей.\nНавыки: осуществлять сбор и обработку исходной информации для определения использования информационных технологий\nУправление проектом и моделирование строительного производства', 'Мартьянов Владимир Иванович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(188, NULL, NULL, 'Проектирование инженерного комплекса горячего водоснабжения (ГВС) для рекреационных зон с использованием возобновляемых источников энергии', 15, 'Обеспечение устойчивого горячего водоснабжения в рекреационных зонах на основе альтернативных источников энергии и очистка стоков с использованием энергосберегающих технологий', 'Получение устойчивых характеристик систем жизнеобеспечения (горячего водоснабжения, освещения, очистки сточных и природных вод) за счет оптимизации энергоэффективных параметров с использованием альтернативных источников энергии для удаленных селитебных территорий и рекреационных зон. \nПрименение солнечных коллекторов для получения горячего водоснабжения, использование солнечных панелей для получения электрической энергии, применение энергоэффективных технологий для очистки природных и сточных вод позволит создать мобильный энергоконтейнер (комплекс из основных систем жизнеобеспечения) для удаленных селитебных территорий и рекреационных зон.\n', 3, '2022-09-01', '2023-05-30', '', 'Тематика предприятия ООО «Инженерный  центр» в рамках корпоративного акселератора в 2019 году. Имеется опыт сотрудничества в проектной деятельности (приказ № 905-П от 03.12.2019 г.)', NULL, 'Проект приводит алгоритм подбора энергоэффективности систем и оборудования жизнеобеспечения, выполнение архитектурно-строительных и компоновочных решений', 'Знания: знать инновационные направления в области энергосбережения объектов строительства и их эксплуатации\nУмения: уметь подбирать новейшие методы, сооружения и технологий для энергоэффективных объектов\nНавыки: владеть основами подготовки документации для создания системы менеджмента качества на период жизненного цикла объектов строительства\n', 'Толстой Михаил Юрьевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(189, NULL, NULL, 'Проект энергоэффективности и оптимизации систем жизнеобеспечения населённого пункта', 15, 'Повышение надежности, проектирование и расчет систем жизнеобеспечения для селитебных зон и промышленных предприятий на основе системного подхода.', 'Формирование оптимальных систем жизнеобеспечения селитебной зоны.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Спроектированный полный набор систем жизнеобеспечения жилых и общественных зданий селитебной зоны  - наружные и внутридомовые сети.', 'Знания: правил проектирования энергоэффективных систем жизнеобеспечения, принципов их оптимизации.\nУмения: использование теоретических знаний при проектировании сетей в конкретных условиях\nНавыки: применения оптимизационных технологий к спроектированным системам\n', 'Айзенберг И.И.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(190, NULL, NULL, 'Разработка проекта систем водоснабжения и водоотведения здания', 15, 'Формирование компетенции в области систем водоснабжения и водоотведения зданий и сооружений.', 'Системы жизнеобеспечения, обеспечивающие благоустройство и комфортность жилых, общественных и производственных зданий, представляют собой комплекс трубопроводов, сооружений, технических устройств, предназначенных для обеспечения комфортных условий быта и трудовой деятельности населения, коммунальных и промышленных предприятий.\nРазработка проекта систем водоснабжения и водоотведения здания способствует подготовке специалистов в области проектирования, монтажа и эксплуатации внутренних систем холодного и горячего водоснабжения, а также систем канализации зданий различного назначения.\n', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Проект', 'Знания: нормативная база в области проектирования зданий, элементы и схемы систем водоснабжения и водоотведения зданий, методы проектирования систем.\nУмения: использовать нормативные документы в своей деятельности; проводить выбор и расчетное обоснование решения при проектировании внутренних систем водоснабжения и водоотведения.\nНавыки: проектирования систем внутреннего водоснабжения и водоотведения.\n', 'Макотрина Людмила Викторовна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(191, NULL, NULL, 'Глубокая очистка сточных вод промышленного предприятия', 15, 'Минимизировать антропогенную нагрузку на поверхностные водные источники.', 'Предлагает и обосновывает варианты наилучших доступных технологий и очистных сооружений для обеспечения инженерно-технической и экологической безопасности на промышленном предприятии и в регионе расположения предприятия.', 2, '2022-09-01', '2023-05-30', '', 'Тематика сторонних организаций  - Сибирского проектного института. Г. Иркутск. ', NULL, 'Проект приводит алгоритм и технологию углублённой очистки промышленных стоков ', 'Знания:  инновационные направления в очистке сточных вод и особенности организации производств такого уровня. \nУмения:  подбирать новейшие методы, сооружения и технологии очистки сточных вод \nНавыки:  по основами подготовки документации для создания системы менеджмента качества производственного подразделения очистки сточных вод\n', 'Кульков Виктор Николаевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(192, NULL, NULL, 'Разработка проектов межевания для Байкальского района Иркутской области.', 15, 'Актуализировать данные о земле и исправить выявленные ошибки для дальнейшего планирования территорий.', 'Проект предусматривает сбор первоначальных данных, анализ и актуализация материала о земельных ресурсах территорий.', 3, '2022-09-01', '2023-05-30', '', 'По заказу Администрации Иркутской области', NULL, 'Актуализированные проекты межевания кадастровых кварталов территорий.', 'Знания: принципов и метод работы с проектами межевания.\nУмения: формировать проекты межевания.\nНавыки: осуществлять сбор и обработку исходной информации для формирования проектов межевания, применять знания нормативно-правовой базы при работе с территориями. Навыки работы с ПО «ГИС Панорама».\n', 'Бунеева Евгения Юрьевна, Безруких Ольга Андреевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(193, NULL, NULL, 'Разработка проектов межевания для Слюдянского Иркутской области.', 15, 'Актуализировать данные о земле и исправить выявленные ошибки для дальнейшего планирования территорий.', 'Проект предусматривает сбор первоначальных данных, анализ и актуализация материала о земельных ресурсах территорий.', 1, '2022-09-01', '2023-05-30', '', 'По заказу Администрации Иркутской области', NULL, 'Актуализированные проекты межевания кадастровых кварталов территорий.', 'Знания: принципов и метод работы с проектами межевания.\nУмения: формировать проекты межевания.\nНавыки: осуществлять сбор и обработку исходной информации для формирования проектов межевания, применять знания нормативно-правовой базы при работе с территориями. Навыки работы с ПО «ГИС Панорама».\n', 'Бунеева Евгения Юрьевна, Безруких Ольга Андреевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(194, NULL, NULL, 'Оценка инвестиционной привлекательности проекта сетевых домостроительных комбинатов', 15, 'Оценка инвестиционной привлекательности проекта сетевого ДСК с целью повышения уровня заводской готовности домокомплектов и модулей для снижения себестоимости и сроков строительства ', 'Проект направлен на создание на территории РФ сети мобильных гибких роботизированных производств строительных конструкций и компонентов для реализации градостроительных и инфраструктурных решений любой сложности на всей территории Российской Федерации. Переход на новый технологический уровень в области индустриального домостроения позволит улучшить качественные параметры архитектурно-планировочных и технических решений, снизить стоимость продукции и повысить производительность труда с использованием отечественного и мирового опыта', 3, '2022-09-01', '2023-05-30', '', 'ООО \"ПОБЕДА\"', NULL, 'Инвестиционный проект «Сетевые домостроительные комбинаты»', 'Знания: \n состава, структуры и назначения бизне-сплана инвестиционного проекта;\n методов оценки эффективности вложений в реальные и финансовые инвестиции;\n новых форм финансирования инвестиционных проектов в РФ;\n индустриальных методов возведения зданий и сооружений.\nУмения: \n проводить необходимые финансовые вычисления по оценке доходности инвестиций, рыночной стоимости финансовых инструментов;\n работать с законодательными и другими нормативными документами, статистическими материалами, технической и экономической литературой;\n применять методы математического анализа и моделирования, теоретического и экспериментального исследования для решения экономических задач.\nНавыки: \n методологии и методики экономического исследования; методами и приемами анализа экономических явлений и процессов;\n расчета основных критериев оценки инвестиционных проектов;\n оценки риска инвестиционной деятельности;\n составления бизнес-планов инвестиционных проектов.\n', 'Безруких Ольга Андреевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(195, NULL, NULL, 'Новые форматы недвижимости: направления для стартапов ', 15, 'Развитие теоретических и методических подходов к формированию и развитию рынка новых форматов недвижимости. ', 'Определение ключевых особенностей организации  рынка институционного арендного жилья и механизмы его функционирования, а также выявить особенности субъектов строительной отрасли заинтересованных в строительстве арендного жилья, в результате чего появляется возможность усовершенствовать организационно-экономический механизм развития и функционирования рынка арендного жилья.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Модель развития рынка арендного жилья с учетом современных организационных форм (на примере г. Иркутск)', 'Знания: \n новых форматов недвижимости;\n методов финансирования строительства арендного жилья.\nУмения: \n проводить оценку и выявлять проблемные области жилищного строительства с использованием различных методик;\nНавыки: \n определения капиталоемкости, эффективности вложений, срока окупаемости, механизмов финансирования, возможных рисков.\n проектирования модели развития рынка арендного жилья с учетом современных организационных форм.\n', 'Безруких Ольга Андреевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(196, NULL, NULL, 'Управление городскими агломерациями в рамках стандарта  комплексного развития территорий ', 15, 'Разработка методических основ и прикладного инструментария по совершенствованию механизма управления реализацией индустриальных проектов малоэтажного жилищного строительства в системе городской агломерации с учетом стандарта комплексного развития территорий', 'Проект направлен на решение проблемы эффективности использования земель посредством реализации проектов комплексного развития территорий в разрезе городской агломерации. А также в процессе проведения исследований изучаются: \n- существующие проблемы комплексного развития территорий на примере г. Иркутск;\n- подходы к формированию и реализации проектов комплексного развития территорий;\n- формирование мероприятий по улучшению реализации комплексного развития пригородных территорий Иркутска за счет применения наиболее энергоэффективной, экологичной и доступной технологии малоэтажного домостроения. \n', 3, '2022-09-01', '2023-05-30', '', 'Администрация города Иркутска', NULL, 'Разработка  методических основ, механизмов, моделей и практических рекомендаций по эффективному воспроизводству объектов малоэтажного строительства направленного на стимулирование рынка малоэтажного жилья в агломерационной системе', 'Знания: процесса развития агломераций муниципальных образований региона; технологий малоэтажного строительства.\nУмения: Определить внешние региональные условия и внутренние закономерности функционально-пространственного развития городских агломераций.\nНавыки: осуществлять сбор и обработку исходной информации для определения приоритетной технологии малоэтажного строительства отвечающую требованиям Национальных проектов, Стратегий РФ и стандартам КРТ. \n', 'Безруких Ольга Андреевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(197, NULL, NULL, 'Мультиформатные загородные поселки, как тренд загородной недвижимости ', 15, 'Разработка организационно-технологического программы развития мультиформатных загородных поселков', 'Проект направлен на разработку мероприятий для реализации целевых показателей паспорта федерального проекта «Жилье» до 2024 г., а также стимулирует развитие строительной отрасли региона, обеспечивая население комфортным и доступным жильем за счет реализации проектов мультиформатных загородных поселков', 3, '2022-09-01', '2023-05-30', '', 'ООО \"ПОБЕДА\"', NULL, 'Программа развития (дорожная карта) мультиформатных загородных поселков в регионе', 'Знания: \n технологических процессов строительного производства мультиформатной застройки с учётом требований производственной и экологической безопасности;\n видов комплексной мультиформатной загородной застройки по 214 ФЗ;\n видов инфраструктурных вложений при комплексной загородной застройке.\nУмения: организовать, планировать и управлять строительным производством на всех этапах жизненного цикла при реализации инвестиционно-строительных проектов мультиформатной застройки;\nНавыки: \n формирование дорожной карты по внедрению мультиформатной застройки;\n расчёта экономической эффективности.\n', 'Безруких Ольга Андреевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(198, NULL, NULL, 'Цифровые технологии для управления рисками и финансовым контролем строительного холдинга', 15, 'Разработка методического аппарата для управления рисками и финансовым контролем строительного холдинга', 'Проект направлен на повышение экономической эффективности финансово-хозяйственной деятельности строительных организаций за счет внедрения цифровых технологий. Направлен на оценку целесообразности использования цифровых технологий в финансово-хозяйственной деятельности строительной организации и в процессах управления рисками. ', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Организационно-экономический механизм функционирования строительной организации при внедрении цифровых технологий в процессы управления рисками и финансовым контролем строительного холдинга', 'Знания: технологий цифровой трансформации для процессов управления рисками и финансовым контролем строительного холдинга.\nУмения: анализировать  финансовую, бухгалтерскую и иную информацию, использовать методы сравнения и группировки влияния факторов, четко формулировать выводы  и предложения для разработки вариантов управленческих решений с учетом рисков и возможных социально-экономических последствий.\nНавыки:  анализа адаптивности строительных организаций к реалиям цифровой экономики.\n', 'Безруких Ольга Андреевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(199, NULL, NULL, 'Разработка мероприятий по совершенствованию функционирования предприятия на основе анализа финансово-хозяйственной деятельности', 15, 'Разработка рекомендаций по совершенствованию финансово-хозяйственной деятельности и оценка эффективности предлагаемых мероприятий по совершенствованию финансово-хозяйственной деятельности', 'В современных условиях развития экономики страны наиболее важную роль играют предприятия различных отраслей, которые поддерживают экономическую стабильность всего государства. При том, важную роль в данной системе занимают предприятия строительной отрасли. После перехода России в условия рыночной экономики появилось множество предприятий, которые не зависят от государственного регулирования и должны уметь самостоятельно проводить анализ своей деятельности, в первую очередь финансово-хозяйственной. Анализ финансово-хозяйственной деятельности является основным инструментом, позволяющим оценить финансово-хозяйственное положение предприятия. Наличие достаточного количества финансово-хозяйственных ресурсов и рациональное их использование позволяют предприятию функционировать и успешно осуществлять свою деятельность. \nПо результатам анализа деятельности в динамике становится понятно, по каким направлениям необходимо проводить изменения. Также анализ позволяет определить слабые и сильные стороны предприятия. Совершенствование финансово-хозяйственной деятельности предприятия подразумевает под собой поиск новых путей развития предприятия посредством увеличения финансово-хозяйственных резервов и оптимизацию их использования. Предшествующими этапами совершенствования деятельности являются: анализ текущего состояния предприятия, разработка мероприятий по совершенствованию, оценка рисков внедрения мероприятий и прогноз развития предприятия. Разработка мероприятий по совершенствованию функционирования предприятия на основе анализа финансово-хозяйственной деятельности является неотъемлемой частью нормального функционирования предприятия, в условиях изменяющейся внутренней и внешней среды\n', 2, '2022-09-01', '2023-05-30', '', 'АО «Иркутскгипродорнии»', NULL, 'Комплексная оценка финансово-хозяйственного состояния в динамике, позволяющая осуществлять анализ и совершенствование деятельности предприятия с целью поиска новых путей развития предприятия посредством увеличения финансово-хозяйственных резервов и оптимизации их использования', 'Проведение оценки эффективности хозяйственной деятельности, на основании которой разрабатываются мероприятия по совершенствованию финансово-хозяйственной деятельности и дается оценка эффективности предлагаемых мероприятий', 'Кудрявцева Вера Александровна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(200, NULL, NULL, 'Разработка сметной документации на капитальный ремонт зданий и сооружений', 15, 'Разработать сметную документацию на капитальный ремонт зданий и сооружений с применением современной сметно-нормативной базы на основе данных обследования текущего технического состояния объекта', 'В настоящее время значительное внимание уделяется капитальному ремонту зданий и сооружений, который производится при необходимости восстановления характеристик объекта до текущих нормативов, с восстановлением и (или) заменой любых частей объекта. Грамотно проведенная оценка технического состояния зданий и сооружений позволяет установить необходимость капитального ремонта, виды и объемы работ, проводимых при капитальном ремонте. Для качественного выполнения работ необходимо определить требуемый объем финансирования, который определяется путем разработки сметной документации и подтверждается сметной стоимостью, которая определяется сметой на реконструкцию, капитальный ремонт объекта капитального строительства, на работы по сохранению объектов культурного наследия, разрабатываемой в составе проектной документации. Особенно остро вопрос качественного определения стоимости строительно-монтажных работ стоит в период реформирования системы сметного ценообразования в целом. Оптимизация затрат на техническое обслуживание зданий во многом обусловлена рациональным планированием системы текущих и капитальных ремонтов. Качественное проведение капитального ремонта продлевает срок службы здания в несколько раз, а его своевременность снижает затраты непосредственно на ремонтные работы и последующие эксплуатационные затраты по зданию. Все это позволяет повысить надежность, безопасность и комфортность зданий и сооружений', 2, '2022-09-01', '2023-05-30', '', 'АО «Иркутскгипродорнии»', NULL, 'Оценка технического состояния и разработка сметной документации на капитальный ремонт объектов', 'Концептуальная (содержательная) проработка вопросов определения стоимости строительно-монтажных работ по капитальному ремонту на основе данных о техническом состоянии зданий и сооружений', 'Кудрявцева Вера Александровна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(201, NULL, NULL, 'Разработка мероприятий по совершенствованию функционирования предприятия на основе анализа финансово-хозяйственной деятельности', 15, 'Разработка рекомендаций по совершенствованию финансово-хозяйственной деятельности и оценка эффективности предлагаемых мероприятий по совершенствованию финансово-хозяйственной деятельности', 'В современных условиях развития экономики страны наиболее важную роль играют предприятия различных отраслей, которые поддерживают экономическую стабильность всего государства. При том, важную роль в данной системе занимают предприятия строительной отрасли. После перехода России в условия рыночной экономики появилось множество предприятий, которые не зависят от государственного регулирования и должны уметь самостоятельно проводить анализ своей деятельности, в первую очередь финансово-хозяйственной. Анализ финансово-хозяйственной деятельности является основным инструментом, позволяющим оценить финансово-хозяйственное положение предприятия. Наличие достаточного количества финансово-хозяйственных ресурсов и рациональное их использование позволяют предприятию функционировать и успешно осуществлять свою деятельность. \nПо результатам анализа деятельности в динамике становится понятно, по каким направлениям необходимо проводить изменения. Также анализ позволяет определить слабые и сильные стороны предприятия. Совершенствование финансово-хозяйственной деятельности предприятия подразумевает под собой поиск новых путей развития предприятия посредством увеличения финансово-хозяйственных резервов и оптимизацию их использования. Предшествующими этапами совершенствования деятельности являются: анализ текущего состояния предприятия, разработка мероприятий по совершенствованию, оценка рисков внедрения мероприятий и прогноз развития предприятия. Разработка мероприятий по совершенствованию функционирования предприятия на основе анализа финансово-хозяйственной деятельности является неотъемлемой частью нормального функционирования предприятия, в условиях изменяющейся внутренней и внешней среды\n', 2, '2022-09-01', '2023-05-30', '', 'АО «Иркутскгипродорнии»', NULL, 'Комплексная оценка финансово-хозяйственного состояния в динамике, позволяющая осуществлять анализ и совершенствование деятельности предприятия с целью поиска новых путей развития предприятия посредством увеличения финансово-хозяйственных резервов и оптимизации их использования', 'Проведение оценки эффективности хозяйственной деятельности, на основании которой разрабатываются мероприятия по совершенствованию финансово-хозяйственной деятельности и дается оценка эффективности предлагаемых мероприятий', 'Кудрявцева Вера Александровна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(202, NULL, NULL, 'Техническая экспертиза объектов недвижимости:\n1. Капитальный ремонт  крупнопанельного жилого дома по адресу: г. Иркутск, мкр. Первомай-ский, 23\n1. Капитальный ремонт крупнопанельного  жилого дома  по адресу: г. Иркутск, мкр. Первомай-ский, 55\n', 15, 'Проведение технической экспертизы и оценка технического состояния объекта недвижимости, разработка комплекса ремонтно-восстановительных мероприятий', 'В процессе эксплуатации объектов недвижимости вследствие различных причин происходят физический износ строительных конструкций, возникновение и накопление повреждений,  снижение и потеря их несущей способности, деформации как отдельных элементов, так и здания в целом. Для разработки мероприятий по восстановлению эксплуатационных качеств конструкций, необходимо проведение их обследования (технической экспертизы) с целью выявления причин преждевременного износа и снижения их несущей способности. По результатам технической экспертизы выполняется оценка технического состояния, условий и возможности дальнейшей эксплуатации, разрабатывается комплекс требуемых ремонтно-восстановительных мероприятий.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Отчет по результатам обследования и оценки технического состояния объекта недвижимости', 'знать:\n требования современ-ных строительных норм и правил;\n методические особенности диагностики  и оценки технического состояния строительных кон-струкций.\n характеристики приме-няемых в регионе типо-вых проектов каменных и крупнопанельных зда-ний;\n основные конструктив-ные решения несущих и ограждающих конструк-ций;\nуметь:\n выполнять диагностику технического состояния строительных конструк-ций;\n составлять отчеты по ре-зультатам исследований.\n выполнять анализ (экс-пертизу) проектного ре-шения.\nвладеть:\n методами   и средствами дефектоскопии   строи-тельных конструкций, контроля физико-механических свойств.\n', 'Журавлев Евгений Геннадьевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(203, NULL, NULL, 'Повышение безопасности высотных объектов строительства за счет создания эффективных методов эвакуации и совершенствования систем вентиляции', 15, 'Для стратегического развития отрасли Строительства и Жилищно-коммунального хозяйства необходимо изыскать возможности при требуемом уровне застройки наилучшим образом обеспечить устойчивый рост комфорта и безопасности среды жизнедеятельности (благоустройство, дороги, расположение объектов Строительства и т.д.). Исследование таких возможностей и выработка рекомендаций является целью данного проекта.', 'Согласно Стратегии развития строительной отрасли и жилищно-коммунального хозяйства Российской Федерации до 2035 года создание безопасной среды является важной задачей. Достижение соответствующего уровня безопасности может  достигаться засчет: разработки оптимальных путей эвакуации, своевременной эвакуации жителей с верхних этажей, совершенствовании систем вентиляции (возможность исключить перемещение воздуха из одного помещения в другое) при возникновении чрезвычайных ситуаций. Рассмотреть все представленные аспекты, проанализировать их влияние на среду жизнедеятельности человека, сделать соответствующие выводы и разработать рекомендации – основа представленного проекта.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Разработка соответствующих рекомендаций.', 'Знания: нормативно-законодательные аспекты отрасли Строительства, методы планирования, оптимизации, принятия решений\nУмения: анализа нормативно-законодательной литературы в сфере Строительства, разработки и принятия решений\nНавыки: исследования, анализа, планирования, оптимизации\n', 'Гребнева Оксана Александровна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(204, NULL, NULL, 'Исследование задач развития комфортной и безопасной среды при осуществлении требуемых объемов застройки', 15, 'Для стратегического развития отрасли Строительства и Жилищно-коммунального хозяйства необходимо изыскать возможности при требуемом уровне застройки наилучшим образом обеспечить устойчивый рост комфорта и безопасности среды жизнедеятельности (благоустройство, дороги, расположение объектов Строительства и т.д.). Исследование таких возможностей и выработка рекомендаций является целью данного проекта.', 'Согласно Стратегии развития строительной отрасли и жилищно-коммунального хозяйства Российской Федерации до 2035 года создание безопасной и комфортной среды жизнедеятельности человека является важной задачей при обеспечении соответствующего уровня развития Строительства. Достижение соответствующего уровня комфортности и безопасности может  достигаться засчет: разумной подготовки территорий Строительства, рационального размещения объектов общественного питания, парковок, парковых зон и т.д., создания удобной и безопасной дорожной инфраструктуры и т.д. Рассмотреть все представленные аспекты, проанализировать их влияние на среду жизнедеятельности человека, сделать соответствующие выводы и разработать рекомендации – основа представленного проекта.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Рекомендации по увеличению уровня комфортности при требуемом уровне застройки.', 'Знания: нормативно-законодательные аспекты отрасли Строительства, методы планирования, оптимизации, принятия решений\nУмения: анализа нормативно-законодательной литературы в сфере Строительства, разработки и принятия решений при решении задач Строительства с учетом всех ограничений и требований\nНавыки: исследования, анализа, планирования\n', 'Гребнева Оксана Александровна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(205, NULL, NULL, 'Информационное моделирование инженерных систем и теплового узла объектов недвижимости с применения BIM-технологий при проведении капитального ремонта на примере нежилого здания по адресу Иркутская область, г. Иркутск, Игошина, 6-а.', 15, 'Создание 3D-модели (виртуальной модели) инженерных систем здания: систем отопления, горячего и холодного водоснабжения, водоотведения, которая в дальнейшем позволяла бы получить визуализацию расположения систем внутри объекта капитального ремонта, информацию по элементам, оборудованию и их характеристикам, а также при необходимости вносить изменения и коррективы в процессе его жизненного цикла.', 'В результате выполнения проекта с использованием BIM-технологий на основе существующей проектной документации и результатов обследования будет выполнена визуализация систем отопления, горячего и холодного водоснабжения, водоотведения объекта капитального ремонта, расположенного по адресу Иркутская область, г. Иркутск, ул. Игошина, 6-а. Созданная информационная модель позволит осуществить планирование и координацию работ по замене элементов и оборудования инженерных систем, обеспечит сопровождение, расчет объемов,  составление смет, сроков, BIM-координацию различных этапов выполнения работ, контроль и обеспечение качества, выявление конфликтов, составление документации и т. д.', 3, '2022-09-01', '2023-05-30', '', 'Фонд капитального ремонта ', NULL, '3D-модель инженерных систем нежилого здания, расположенного по адресу Иркутская область, г. Иркутск, Игошина, 6-а.', 'Знания: по методам информационного моделирования и проектирования жизненного цикла инженерных систем и сооружений объектов недвижимости. \nУмения: владение системами 3d-моделирования и создание 3d-моделей инженерных систем объектов недвижимости.\nНавыки: проектирования и моделирования.\n', 'Гребнева Оксана Александровна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(206, NULL, NULL, 'Информационное моделирование объектов недвижимости с применения BIM-технологий при проведении капитального ремонта на примере нежилого здания по адресу Иркутская область, г. Иркутск, Игошина, 6-а.', 15, 'Создание 3D-модели (виртуальной модели), которая в дальнейшем позволяла бы получить графический вид объекта, информацию по дизайну, размерам, материалам и другим характеристикам объекта капитального ремонта, а также при необходимости вносить изменения и коррективы в процессе его жизненного цикла.', 'В результате выполнения проекта с использованием BIM-технологий на основе существующей проектной документации и результатов обследования конструкций здания будет выполнена визуализация объекта капитального ремонта, расположенного по адресу Иркутская область, г. Иркутск, ул. Игошина, 6-а (возможно с разработкой дизайн-проекта). Созданная информационная модель позволит осуществить планирование и координацию работ, обеспечит сопровождение, расчет объемов,  составление смет, сроков, BIM-координацию различных этапов выполнения работ, контроль и обеспечение качества, выявление конфликтов, составление документации и т. д.', 3, '2022-09-01', '2023-05-30', '', 'Фонд капитального ремонта ', NULL, '3D-модель нежилого здания, расположенного по адресу Иркутская область, г. Иркутск, Игошина, 6-а.', 'Знания: по методам информационного моделирования и проектирования жизненного цикла зданий. \nУмения: владение системами 3d-моделирования и создание 3d-моделей объектов недвижимости.\nНавыки: проектирования и моделирования.\n', 'Гребнева Оксана Александровна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(207, NULL, NULL, 'Создание художественного произведения/творческой работы для участия в выставочных проектах Всероссийской творческой организации «Союз художников России»', 15, 'Освоение методики последовательного ведения работы над созданием проекта. Создание художественно-выразительного произведения для последующего участия в выставочных и конкурсных проектах, организованных Всероссийской творческой организацией «Союз художников России»/Молодежным объединением ИРО ВТОО «Союз художников России»', 'Разработка концепции творческого проекта (художественной работы) под руководством преподавателя, с учетом данных обучающегося. Выполнение эскизов на тему, предложенную преподавателем, либо самим обучающимся, актуальную для тематики текущих выставок  Всероссийской творческой организации «Союз художников России»/Молодежного объединения ИРО ВТОО «Союз художников России». Проработка концепции графического/цветового решения, выбор техники исполнения произведения. Выполнение работы в материале.', 2, '2022-09-01', '2023-05-30', '', 'Всероссийская творческая организация «Союз художников России», Молодежное объединение ИРО ВТОО «Союз художников России»', NULL, 'Творческий вывод - художественное произведение: картина/ графический лист/ проект digital art  (печать)/ работа в любой из техник монументально-декоративного искусства (мозаика, витраж, панно из ткани, гобелен и т.д.)', 'Знания:\nСпецифика проектной работы над созданием художественного произведения;\nОсобенности создания эскиза произведения, как составной части проекта; \nОсновы композиционного, графического, цветового проектирования;\nОсновы академического рисунка и живописи.\nУмения:\nОрганизация поэтапной работы над созданием художественного произведения;\nРабота с различными художественными материалами;\nИдея и реализация творческого замысла;\nНавыки: \nВладение  техниками и материалами изобразительного искусства;\nВладение методами изобразительного языка\n', 'Довнич Наталья Анатольевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(208, NULL, NULL, 'Визуальное решение театральных и культурно массовых мероприятий (организация среды и систем айдентики)', 15, 'Создание проектов сценографического решения мероприятий разного функционального назначения', 'Цель проекта: формирование компетенции в сценографии как объекта дизайн проектирования; исследование традиционного и современных подходов к визуальному оформлению культурно-массовых мероприятий; изучение способов воплощения художественного замысла средствами объемно пространственного моделирования.', 3, '2022-09-01', '2023-05-30', '', 'Театры, коммерческие структуры г. Иркутска', NULL, 'Проекты организации среды и систем айдентики театральных и культурно массовых мероприятий разного функционального назначения.', 'Знать: типологию композиционных средств и их взаимодействие; основные приемы сценарного-проектирования среды и систем айдентики мероприятий разного функционального назначения\nУметь: решать основные типы проектных задач создания театральных и культурно-массовых мероприятий; учитывать при разработке художественного замысла особенности материалов и их формообразующих свойств;\nВладеть приемами объемного и графического моделирования формы объекта, и соответствующей организацией проектного материала для передачи творческого художественного замысла;\nкомпьютерным обеспечением дизайн-проектирования;\nвыполнением проекта в материале.\n', 'Шолохов Андрей Викторович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(209, NULL, NULL, 'Проектирование мебели и оборудования как системы формирования комфортной среды', 15, 'Создание проектов мебели и оборудования для сред разного функционального назначения: формообразование, конструирование и формулирование концепций рекламного продвижения', 'В современной ситуации становиться актуальным наличие на рынке функциональной, качественной, не дорогой мебели и оборудования, созданными с использованием современных отечественных материалов на актуальной производственной базе. Результатом данного курса будут проекты мебели и оборудования, на которые возможно получение патентов на промышленные образцы с дальнейшей возможной реализацией в материале, концепции формирования рекламно-информационных систем продвижения продуктов/изделий.', 3, '2022-09-01', '2023-05-30', '', 'Мебельные фирмы г.Иркутска', NULL, 'Проекты мягкой и корпусной мебели и оборудования; концепции продвижения созданных изделий', 'Знать: основные способы дизайн-проектирования, специфику создания дизайна современной мебели и оборудования; базовые технологические процессы в мебельной промышленности\nУметь: разрабатывать обоснованную проектную идею с учетом формообразования и основ конструирования; проектировать системы визуальной информации, идентификации и коммуникации \nВладеть навыками проектирования мебели: конструирования предметов, товаров, промышленных образцов с учетом технологий изготовления; формирования рекламно-информационных комплексов \n', 'Шолохов Андрей Викторович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(210, NULL, NULL, 'Создание художественного произведения/творческой работы для участия в ежегодной выставке-конкурсе, проходящей в рамках областного фестиваля «Студенческая весна в ИрНИТУ»', 15, 'Освоение методики последовательного ведения работы над созданием проекта. Создание художественно-выразительного произведения для последующего участия в выставке-конкурсе областного фестиваля «Студенческая весна в ИрНИТУ», организованного  Центром  культурно-массовой и воспитательной работы ИРНИТУ (с возможностью дальнейшего участия произведения в других выставках /конкурсах).', 'Разработка концепции творческого проекта (художественной работы) под руководством преподавателя, с учетом данных обучающегося. Выполнение эскизов на тему, предложенную преподавателем, либо самим обучающимся, актуальную для общей тематики выставки. Проработка концепции графического/цветового решения, выбор техники исполнения произведения. Выполнение работы в материале.', 2, '2022-09-01', '2023-05-30', '', 'Центр культурно-массовой и воспитательной работы ИРНИТУ. Дирекция ИАСиД. ', NULL, 'Творческий вывод - художественное произведение: картина/ графический лист/ проект digital art  (печать)/ работа в любой из техник монументально-декоративного искусства (мозаика, витраж, панно из ткани, гобелен и т.д.)', 'Знания:\nСпецифика проектной работы над созданием художественного произведения;\nОсобенности создания эскиза произведения, как составной части проекта; \nОсновы композиционного, графического, цветового проектирования;\nОсновы академического рисунка и живописи.\nУмения:\nОрганизация поэтапной работы над созданием художественного произведения;\nРабота с различными художественными материалами;\nИдея и реализация творческого замысла;\nНавыки: \nВладение  техниками и материалами изобразительного искусства;\nВладение методами изобразительного языка.\n', 'Свердлов Григорий Викторович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(211, NULL, NULL, 'Создание художественного произведения/творческой работы для участия в ежегодной выставке-конкурсе, проходящей в рамках  Всероссийского фестиваля «Дни русской духовности и культуры «Сияние России».', 15, 'Освоение методики последовательного ведения работы над созданием проекта. Создание художественно-выразительного произведения для последующего участия в выставке-конкурсе, проходящей в рамках Всероссийского фестиваля «Дни русской духовности и культуры «Сияние России» в ИрНИТУ, с возможностью дальнейшего участия произведения в других выставках /конкурсах.', 'Разработка концепции творческого проекта (художественной работы) под руководством преподавателя, с учетом данных обучающегося. Выполнение эскизов на тему, предложенную преподавателем, либо самим обучающимся, актуальную для общей тематики выставки. Проработка концепции графического/цветового решения, выбор техники исполнения произведения. Выполнение работы в материале.', 2, '2022-09-01', '2023-05-30', '', 'Центр культурно-массовой и воспитательной работы ИРНИТУ. Дирекция ИАСиД.', NULL, 'Творческий вывод - художественное произведение: картина/ графический лист/ проект digital art  (печать)/ работа в любой из техник монументально-декоративного искусства (мозаика, витраж, панно из ткани, гобелен и т.д.)', 'Знания:\nСпецифика проектной работы над созданием художественного произведения;\nОсобенности создания эскиза произведения, как составной части проекта; \nОсновы композиционного, графического, цветового проектирования;\nОсновы академического рисунка и живописи.\nУмения:\nОрганизация поэтапной работы над созданием художественного произведения;\nРабота с различными художественными материалами;\nИдея и реализация творческого замысла;\nНавыки: \nВладение  техниками и материалами изобразительного искусства;\nВладение методами изобразительного языка.\n', 'Ижганайтене Анастасия Николаевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(212, NULL, NULL, '\"Виртуальный тур по промышленным объектам Иркутской области. Памятники промышленного зодчества»', 15, 'Создание виртуального тура с описанием объектов', 'В связи с возможностью обследования промышленных зданий и сооружений индустриального освоения Восточной Сибири, в том числе, заброшенных и исчезающих, существует необходимость провести 3d съемку объектов, собрать историческую справку и создать 3d тур. В проекте должно быть подробное описание, озвучивание и возможность рассмотрения объектов в деталях. Объект предназначен для сохранения информации об объектах, изучения конструкций и архитектуры зданий, истории объекта.', 3, '2022-09-01', '2023-05-30', '', 'Ассоциация индустриального туризма, Благотворительный фонд Владимира Потанина\n', NULL, 'Виртуальный тур, имеющий историческую значимость ', 'Знания: в области истории архитектуры и конструкций промышленных объектов Восточной Сибири на территории Иркутской области\nУмения: создавать 3d съемки, делать описание конструкций и создавать виртуальный тур.\nНавыки: работа с ГЕО программным обеспечением\n', 'Черниговская Виктория Вячеславовна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(213, NULL, NULL, 'Оценка эффективности инвестиционного проекта', 15, 'Постановка задач и их решение, необходимые содержательные и математические обоснования, изучение, разъяснение типовых ошибок, встречающиеся в практике расчёта. Изучение методов приспособленных как к стационарной рыночной, так и к современной нестационарной российской экономике. ', '1.Теоретические основы оценки инвестиционных проектов. 1.1. Что такое инвестиционный проект и зачем его оценивать. 1.2. Принципы и схема оценки инвестиционных проектов. 1.3. Система цен и налогов. 1.4. Измерение, планирование и проектирование затрат и результатов. 1.5. Оценка эффективности проекта в целом. 1.6. Оценка эффективности участия в проекте. 1.7. Неопределённость и риск: общие понятия и приближенные методы учета. 1.8. Расчёты ожидаемой эффективности проекта. 1.9. Оптимизация и рациональный отбор проектов. 2. Методические проблемы практической оценки инвестиционных проектов. 2.1. Оценка эффективности проектов при специфических условиях их реализации. 3. Примеры оценки инвестиционных проектов. 3.1. Предварительная аналитическая оценка проекта. 3.2. Пример полного расчета показателей эффективности инвестиционного проекта', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Участие в конференции и написание статей по материалам  исследования.', 'Знать: основные понятия, общие положения, особенности расчётов.\nУметь: решать сложные методические и практические проблемы инвестиционных проектов.\nВладеть навыками последовательного построения расчётов.\n', 'Рябченкова Антонина Васильевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(214, NULL, NULL, 'Контейнерное озеленение для зимнего города', 15, 'Разработка методических рекомендаций по агротехнике и ассортименту растений для контейнерного озеленения (пристановочной культуры) зимнего города на примере Иркутска, проектирование архитектурно-технического оснащения для контейнерного растениеводства в зимнем городе.', 'С развитием технологий и прогрессом городских инженерных систем очень сложно вписать в озеленение исторических и деловых центров и жилых районов города растения с крупной корневой системой. Для зимних городов ситуация с подбором растений осложняется коротким вегетационным периодом и низкой суммой активных температур. Для формирования озеленения на территориях с плотной застройкой и расширения ассортимента растений перспективно контейнерное озеленение. Контейнеры для пристановочной культуры подразумевают возможность автономного выращивания (автополив, дренаж, защита от перегрева, аккумуляция тепла, возможность притенения), необходимы архитектурные элементы зданий для размещения контейнеров с растениями, малые архитектурные формы и т.д.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Методические рекомендации по агротехнике и ассортименту растений для контейнерного озеленения зимнего города на примере Иркутска, проект архитектурно-технического оснащения для контейнерного растениеводства в зимнем городе.', 'Знать: ассортимент растений для озеленения зимнего города, требования безопасного размещения контейнеров.\nУметь: проектировать элементы архитектурно-технического оснащения контейнерного озеленения.\nВладеть: навыками проектирования в  Autodesk 3ds Max или программах-аналогах\n', 'Баяндина Елена Викторовна, Черниговская Виктория Вячеславовна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(215, NULL, NULL, 'Цифровой демонстрационно-исследовательский макет города с элементами дополненной реальности', 15, 'Создание цифрового демонстрационно-исследовательского макета города с элементами дополненной реальности (далее - Проект), направленного на решение самых актуальных проблем и задач городского развития за счет возможности (наглядного) поведения проектных и исследовательских работ целого ряда специальностей ИРНИТУ задействованных в городском планировании.  ', 'На данный момент ИРНИТУ не достаточно участвует и тем более влияет на принятие важных решений городского развития в качестве одного из ключевых федеральных центров Знаний и исследований.\nПроект направлен на решение следующих проблем:\nВ городе не создавался Макет для выполнения широко спектра городских задач для проектной и исследовательской деятельности, начиная от стратегического территориально планирования, заканчивая размещение рекламы.\nПо-сути, создание такого рода Макета позиционируется как базовая платформа для выполнения проектных и исследовательских работ различных специальностей ИРНИТУ, связанным с анализом функционирования существующей ситуации (систем), вопросами планирования объектов городской инфраструктуры и мн. др. Кроме того, макет должен выполнять демонстративные функции, поэтому должен выполняться из качественных материалов (пластик ПВХ и др.), по специальной технологии будет осуществляться технология дополненной реальности, кроме того параллельно будет выполняться цифровизация городской территории, с последующей возможностью 3D печати любого фрагмента Макета.\nУчитывая различный спектр задач и функции Макета, ИРНИТУ как современный, исследовательский и инновационный ВУЗ может быть в постоянной повестке городского развития. \nВот лишь некоторые проблемы, которые могут быть решены в проектной, исследовательской деятельности:\n- стратегическое, территориальное планирования;\n- документация по планировке территории;\n- градостроительное зонирование;\n- системы коммунального, транспортного и социального планирования;\n- сохранение и развитие объектов культурного наследия;\n- развитие систем рекреационного назначения;\n-  размещение рекламы;\n- размещение нестационарных торговых объектов и др.\nКаждый из данных направлений представляет отдельный проект, спектр которых не ограничивается данным перечнем. \nДемонстрационные функции Макета, также выгодны для презентации деятельности ВУЗа, в частности: Возможность выгодно презентовать город на высоком, качественном уровне \n представителям федеральных органов власти, министерствам и ведомствам, представителям бизнеса, зарубежным гостям и конечно жителям и обычным гостям города.\nВ частности, на данной платформе, можно очень наглядно проводить публичные и общественные слушания в рамках реальной подготовки одно из видов градостроительной документации.\n', 2, '2022-09-01', '2023-05-30', '', 'Администрация города Иркутска', NULL, 'Построение макета для отражения современного состояния, построение базовой основы для последующего проектирования и исследовании', 'Знания: Методы и способы создания макета\nУмения: самостоятельно выполнять задачи по макетированию в цифровом, а также использую специальные материалы такие как пеноплекс, возможности 3D - печати\nНавыки: макетного проектирования с использованием традиционных и передовых цифровых технологий.\n', 'Александров Сергей Анатольевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(216, NULL, NULL, 'Транспортное планирование исторического центра города Иркутска ', 15, 'Сбор, анализ и обобщение данных о пешеходно-транспортных потоках, характере функционального использования объектов и территории, выполнение предпроектных исследований по классификации улично-дорожной сети исторического центра, необходимых для совершенствования действующих нормативных документов и подготовки проектной документации.', 'Действующие нормативные документы, разработанные на федеральном уровне, классифицирует улично-дорожную сеть улиц и дорог в населенных пунктах. Действующее законодательство также позволяет уточнять классификацию данных улиц и дорог с учетом местных особенностей. Прежде всего, на основе вышеуказанных документов подготавливается градостроительная документация городских и сельских поселений, например, подготовка генеральных планов и проектов планировки. На основе градостроительных документов подготавливается проектно-сметная документация улиц и дорог, а также проекты благоустройства общественных пространств. \nНа данный момент, (на федеральном уровне) подготавливают соответствующие стандарты в отношении городов федерального значения таких как Москва, а также подготавливаются стандарты благоустройства, которую пытаются адаптировать как основополагающие на местном уровнях. Однако, практика показывает, что данные нормативы не могут учитывать в полной мере:\n- природно-климатические;\n- историко-культурные;\n- функционально-планировочные и иные особенности конкретных населенных пунктов и территории.\nПроект содержит критический анализ нормативов транспортного планирования различных уровней регулирования, данные о местных особенностях использования исторического центра города Иркутска, а также данные о наблюдениях различных участков улично-дорожной сети, характере их использования, а также предложения по совершенствованию нормативов градостроительного проектирования.\nМестные нормативы градостроительного проектирования позволят проектировать улицы и дороги более дифференцировано, учитывать функционально-планировочные и иные особенности города делая их более безопасными и комфортными для жизни.\n', 2, '2022-09-01', '2023-05-30', '', 'Администрация города Иркутска, Публичное акционерное общество «Сбербанк России»\n', NULL, '1. Подготовка предложений по внесению изменений в:\n- Местные нормативы градостроительного проектирования города Иркутска;\n- Региональные нормативы градостроительного проектирования;\n2. Подготовка предпроектных исследований по развитию и классификации улично-дорожной сети на основе которых могут быть внесены изменения в:\n- проект планировки центральной исторической части города Иркутска;\n3. Подготовка предпроектных исследований по развитию и классификации улично-дорожной сети на основе которых могут быть разработаны;\n- новые стандарты благоустройства улиц и дорог города Иркутска, в части исторического центра;\n- проекты благоустройства общественных пространств;\n- проекты ремонта или реконструкции центральных исторических улиц;\n- схемы размещения нестационарных торговых объектов, расположенных на территории общего пользования;\n- схемы развития пешеходной и велосипедной инфраструктуры исторического центра;\n- схемы развития платной парковочной политики;\n- схемы озеленения исторического центра;\n- схемы размещения рекламных конструкции;\n- схемы размещения объектов информации и навигации.\n\n*- Ожидаемый продуктовый результат в рамках работы учебного года, касается пункта 1, указанный в данном разделе. Пункты 2 и 3 касаются потенциала развития данного проекта.\n', 'Знания: Норм и особенностей регулирования объектов транспортной инфраструктуры на федеральном, региональном и местном уровнях в нормативах градостроительного проектирования\nУмения: анализировать существующее состояние объектов транспортной инфраструктуры с точки зрения безопасности, комфорта использования и способности предлагать новые концептуальные решения\nНавыки: критического мышления, способность выявлять сильные и слабые сторон объекта рассмотрения необходимые для формулирования запроса на новые знания и новые нормативы, в частности\n', 'Александров Сергей Анатольевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(217, NULL, NULL, '\"Сибирский тракт. Иркутская губерния».', 15, 'Проведение анализа территорий поселений Иркутской области, исторически находившихся на пути Почтамтского тракта. Картирование территории. Создание информационной базы для дальнейшей реализации проекта', 'В процессе реализации проекта - восстановления верстовых столбов Почтамтского тракта в Иркутской области, возникают задачи по сбору информации исторических данных поселений, градостроительному анализу территории, а так же современной ситуации по культуре и быту населения. Для этого необходимо проведение научного исследования, итогом которого, станет информационная база по поселениям, картирование территорий', 3, '2022-09-01', '2023-05-30', '', 'ВСОРГО, «Фонд Тимченко», Культура гранты России\n', NULL, 'Информационная база. Картирование территорий.', 'Знания: основные способы выполнения градостроительного анализа территорий\nУмения: систематизировать и обобщать информацию по территориям исторических поселений\nНавыки: работы с архивами, электронными ресурсами, а так же работа в команде и с потенциальными потребителями продукта\n', 'Пуляевская Евгения Владимировна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(218, NULL, NULL, 'Реновация архитектурно-градостроительной среды выхода ул. Нагорной к набережной р. Ангары\nв п. Никола\n', 15, 'Создание комплексного проекта архитектурно-градостроительной организации и благоустройства регионального рекреационного и туристического объекта « Байкал-Никола»', ' Проектом необходимо предусмотреть:\n- градостроительное зонирование реконструируемой территории; функциональное и технико-экономическое обоснование предлагаемых решений\n- транспортно-пешеходную организацию движения, парковки и благоустройство общественных пространств: внешнее (дороги, набережная с общей прибрежной зоной  спорта и отдыха) и внутриквартальное благоустройство\n- архитектурные решения планировки и застройки (гостинично - оздоровительный  комплекс) на участке по адресу: ул.Нагорная, 2;\n- стилевые и колористические решения по объединению разрозненных существующих  объемно-архитектурных элементов застройки и спортивного корта и новых   проектируемых зданий и общественных зон в целостный средовой градостроительный  комплекс;\n Проектный коллектив: студенты старших курсов специальностей Гр, Ар, ДАС, ЭУН с  реализацией работы в:\n - учебная задача: специальный курсовой и дипломные проекты, разрабатываемые в  творческом коллективе специалистов (мастерской);\n- участие в ежегодных творческих областных и межрегиональных конкурсах, Зимнем ГУ -  представление ИрНИТУ на общественных площадках и в социальных программах/сетях;\n публикации в межвузовских и профессиональных специализированных изданиях, на ТВ \n- практический результат: инициативные эскизные проработки (1 этап) с последующим  вхождением в областную программу благоустройства архитектурной среды Прибайкалья  и платной (гранты, участие в госпрограммах) разработкой проектной и рабочей  документации отдельных элементов среды и/или комплекса в целом  (заинтересованные стороны: собственники прилегающих усадебных участков и  туристических объектов; администрация поселка, МО и Иркутской области);\n Время и график выполнения работы - учебный год:\n Сентябрь-октябрь – комплектация коллектива, сбор исходных данных, социологические  исследования, форэскизы, предварительная работа с потенциальными заказчиками и \n интересантами, прессой, административными и общественными структурами;  Ноябрь-декабрь – разработка концептуальных решений по площадке и  эскизных решений по различным фрагментам среды и разделам проекта; консультации  и предварительные обсуждения хода и направлений работы \n Январь-февраль – сборка и оформление презентационных материалов проекта,  подготовка публикаций, показ промежуточных результатов, сбор замечаний,  предложений, рекомендаций; Март-апрель – доработка проекта и отдельных разделов до кондиционных показателей,\n Разработка нескольких вариантов презентационных материалов под специфику  представления и решения учебных и практических задач; Май-июнь – завершение 1-го этапа работы, организационные итоги, дипломы и заявки \n', 3, '2022-09-01', '2023-05-30', '', 'Администрация п. Никола, частные собственники земельных участков, \nВсероссийский федеральный  конкурс создания лучших проектов комфортной городской среды', NULL, 'Профессиональный проектный продукт (комплексный проект комфортной архитектурной среды), пригодный для практической реализации, конкурсного представления и поэтапной публикации процесса и результатов в профессиональных и общественно-политических изданиях и сетях', 'Знать: состав и содержание профессиональной проектной документации в соответствии с нормативными требованиями ПП РФ №87 и особенности разработки конкурсной архитектурно-проектной документации \nУметь: комплексно реализовывать проектные идеи и решения в составе междисциплинарного творческого коллектива ; использовать профессиональные графические (компьютерные и ручные) инструменты, точно и адресно формулировать предпроектные задачи и описания результатов (ПЗ) \nВладеть навыками современного проектирования и оформления проектной документации:\n', 'Ашихмин Александр Викторович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(219, NULL, NULL, 'Благоустройство территорий для маломобильных групп населения (МГН) в г. Иркутске', 15, 'Проектирование объектов безбарьерной городской среды в г. Иркутске для МГН', 'Необходимо выполнить проектирование объектов городской среды для маломобильных групп населения (МГН) в соответствии с нормативными документами и правилами благоустройства территории. ', 3, '2022-09-01', '2023-05-30', '', 'Управление социальной защиты населения по г. Иркутску', NULL, 'Проекты благоустройства городской среды для маломобильных групп населения в г. Иркутске', 'Знания: о составе проектной и рабочей документации при проектировании объектов благоустройства городской среды для МГН \nУмения: составлять ТЗ, анализировать территорию, проводить оценку и обоснование обследований территории с позиции приспособленности среды к МГН, выполнять дизайн-проект, а так же рабочую документацию\nНавыки: переговоров с заказчиком, с потребителями среды; проведения общественных слушаний, работы в графических редакторах и программах 3d моделирования, работы со смежными специалистами.\n', 'Черниговская В.В. ', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(220, NULL, NULL, 'Цифровая модель объекта культурного наследия', 15, 'Создание цифровой модели объекта культурного наследия', 'Для повышения качества реставрационно-реконструктивного проектирования и обеспечения сохранности объектов культурного наследия необходимо создание цифровой модели зданий.\nЗадачи:\n1. Изучение программ для цифрового и информационного моделирования зданий\n2. Разработка типовой цифровой модели здания\n3. Сбор информации по конкретному ОКН (чертежи, фотофиксация, замеры)\n4. Разработка цифровой модели конкретного ОКН, на основе собранных данных\n5. Детальная проработка декоративных элементов ОКН\n', 3, '2022-09-01', '2023-05-30', '', 'Служба по охране объектов культурного наследия Иркутской области', NULL, 'Цифровая модель объекта культурного наследия', 'Знать специфику ОКН; основные инструменты программ цифрового и информационного моделирования (BIM)\nУметь проектировать в программах цифрового и информационного моделирования зданий\nВладеть технологиями цифрового и информационного моделирования зданий\n', 'Ларионов Никита Андреевич, Низамутдинова Зиля Фаритовна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(221, NULL, NULL, 'Пространственная база данных ценной застройки г. Иркутска советского периода', 15, 'Формирование базы данных  для поиска текстовой и графической информации об объектах архитектуры', 'При архитектурном проектировании в исторически сложившейся городской среде необходимы сведения о застройке различного характера. Информация может находиться в источниках, доступ к которым не всегда возможен и требует временных и прочих затрат. Кроме того, есть архивный материал, представленный только на бумажном носителе. Как проектировщикам, так и студентам архитектурного направления, для эффективного решения производственных и учебных задач нужен систематизированный оцифрованный материал в одном источнике.', 3, '2022-09-01', '2023-05-30', '', 'Служба по охране объектов культурного наследия Иркутской области', NULL, 'Пространственная база данных исторической застройки Иркутска, разработанная в программе QGIS', 'Знать особенности застройки советского периода; инструменты оцифровки\nУметь систематизировать данные о застройке, выявлять критерии, оформлять результаты анализа\nВладеть навыками работы в QGIS\n', 'Прокудин Александр Николаевич, Сыроежкина Мария Александровна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(222, NULL, NULL, 'Пространственная база данных исторической застройки Иркутска', 15, 'Формирование базы данных  для поиска текстовой и графической информации об объектах архитектуры', 'При архитектурном проектировании в исторически сложившейся городской среде необходимы сведения о застройке различного характера. Информация может находиться в источниках, доступ к которым не всегда возможен и требует временных и прочих затрат. Кроме того, есть архивный материал, представленный только на бумажном носителе. Как проектировщикам, так и студентам архитектурного направления, для эффективного решения производственных и учебных задач нужен систематизированный оцифрованный материал в одном источнике.', 3, '2022-09-01', '2023-05-30', '', 'Служба по охране объектов культурного наследия Иркутской области', NULL, 'Пространственная база данных исторической застройки Иркутска, разработанная в программе QGIS', 'Знать специфику исторической застройки; инструменты оцифровки\nУметь систематизировать данные о застройке, выявлять критерии, оформлять результаты анализа\nВладеть навыками работы в QGIS\n', 'Сыроежкина Мария Александровна, Шишканов Владимир Сергеевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(223, NULL, NULL, 'расчетное обоснование в проектировании высотных зданий с диафрагмами жесткости', 15, 'Получение навыков расчетов высотных знаний с диафрагмами жесткости на статические и динамические воздействия с использованием специализированных программных средств', 'Проектирование высотных зданий сопряжено с рядом проблем, связанных с обеспечением требуемой жесткости и прочности конструкций, что приводит к неизбежному использованию диафрагм жесткости, которые в большинстве случаев должны иметь внутренние проемы (дверные, оконные и пр.) Наличие таких проемов, выполненных с применением традиционных для строительства прямоугольных форм, сопровождается возникновением особых точек, что в свою очередь порождает значительные затруднения в расчетах и проектировании конструктивных элементов.  Сочленения разнородных конструктивных элементов должно сопровождаться обеспечением их корректными расчетными обоснованиями в условиях нерегулярных граничных условий. Обеспечение таких расчетных мероприятий возможно только с использованием численных методов (например, методов конечного элемента) на основе специализированных программных комплексов, реализующих соответствующие алгоритмы.  \nТрадиционные для расчета строительных конструкций методы конечного элемента (КЭ), основанные на законах линейной теории упругости, не позволяют решать задачи получения корректных решений в окрестности точек, являющихся концентраторами напряжений и локализацией развития трещин, особенно при интенсивных воздействиях. По этой причине необходимы выполнения конструктивных мероприятий и их проектное обеспечение, связанное с уменьшением напряженного состояния в окрестности особых точек. Перечисленные обстоятельства создают необходимость формирования специализированного курса обучения\n', 2, '2022-09-01', '2023-05-30', '', 'тематики предприятий, выполняющий расчетные обоснования проектов', NULL, 'Создание полноценных проектов высотных знаний с диафрагмами жесткости на статические и динамические воздействия в автоматизированных системах проектирования ', 'Знания: Получение компетенций в области проектирования высотных зданий со стволами и дифрагмами жесткости с использованием цифровых и численных технологий.\nУмения: выполнять расчетное обоснование проектов высотных знаний с диафрагмами жесткости на статические и динамические воздействия\nНавыки: работа в специализированных программных комплексах\n', 'Соболев Владимир Иванович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(224, NULL, NULL, 'Использование солнечной энергии для отопления и горячего водоснабжения потребителей в индивидуальном жилищном строительстве, на децентрализованных территориях ', 15, 'Разработка проекта использования солнечной энергии для отопления и горячего водоснабжения зданий в удаленных территориях, а также создание программы для расчета параметров системы, использующей солнечные коллекторы', 'Проводится литературный обзор  и сравнение существующих видов солнечных коллекторов, применительно к рассматриваемой территории. Расчет экономической эффективности солнечной уста-\nновки основан на оценке средних значений солнечной радиации в месте установки системы, а также на правильном определении требуемой производительности, схемно-структурного состава установки, и стоимости отдельных элементов в данной местности. Проводится расчет систем горячего водоснабжения и отопления с использованием солнечной энергии. Осваивается работа в программном комплексе Matlab (SimInTech) и других онлайн ресурсов для расчетов ВИЭ. Формируются универсальные математические модели и программы для расчета системы, использующей солнечные коллекторы. Анализируется экономическая эффективность применяемой системы солнечного теплоснабжения  и ГВС потребителя\n', 2, '2022-09-01', '2023-05-30', '', 'Прогноз топливно-энергетического комплекса от Фонда «Надежная смена», научная молодежная школа «Возобновляемые источники энергии и приоритеты научно-технологического развития»', NULL, 'Повышение  эффективности энергообеспечения удаленных территорий, снижение платы за отопление и ГВС у потребителя, универсальные математические модели и программы для расчета солнечных коллекторов', 'Знания: нетрадиционные возобновляемые источники энергии, виды солнечных коллекторов\nУмения: выполнять расчеты солнечных коллекторов, моделировать объекты в программных комплексах, работать в команде\nНавыки: основы программирования в Matlab (SimInTech), защита результатов выполненной работы в виде публичного доклада\n', 'Петрова Анастасия Николаевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(225, NULL, '2022-08-30 05:21:53', 'Создание системы мониторинга и накопительной базы данных для контроля и прогнозирования состояния теплоэнергетического оборудования на основе интерфейса, составленного на базе 3D модели узлов и агрегатов.', 15, 'Улучшить эксплуатационные характеристики узлов и агрегатов теплоэнергетического оборудования, на основе накопленных сведений полученных в течении длительного периода времени, а также текущих параметров состоянии системы.', 'В настоящий момент для проведения эксплуатационного контроля металла и технического диагностирования, составляется значительный объем документации, связанной с ремонтами, контролем металла, инцидентами, а также заменами на техническом устройстве по отдельным разрозненным формулярам и документам. Для ускорения проведения данных работ, а также в целях исключения ошибок при формировании объемов, предлагается консолидировать исполнительную документацию по техническому состоянию оборудования и привязать полученную информацию к 3D модели технического устройства. В дополнении на 3D модель оборудования для улучшения эксплуатационных характеристик предлагается вывести текущие параметры состояние оборудования, полученные от систем мониторинга, датчиков. Предложенные решения позволяют создать автоматизированный планировщик для составления расписание плановых ремонтных работ, капитальных ремонтов, замены узлов и агрегатов. Предлагается создать систему сквозного мониторинга для разных уровней инженерно-технического персонала, а также разделить полномочия по конфигурированию и настройке.', 2, '2022-09-01', '2023-05-30', NULL, 'Лаборатория энергетики\r\nАкселерационная программа, реализуемая ГК «ЕвроСибЭнерго» на базе ИРНИТУ.', NULL, 'Человеко-машинный интерфейс для взаимодействия накопительной базы данных и систем мониторинга отдельных элементов теплоэнергетического оборудования с его 3D моделью. Интерфейс должен отображать техническое состояние отдельных элементов оборудования с целью обеспечения реализации программы профилактического технического обслуживания различного оборудования, в частности, поверхностей нагрева котлоагрегатов, на основании обоснованной информации и экономически целесообразной базы для принятия решений', 'Знания: свойства металлов и сплавов; марки материалов, используемых для элементов основного и вспомогательного оборудования теплоэнергетических станций, основы моделирования процессов и объектов теплоэнергетики с применением компьютерных технологий.\r\nУмения:  подобрать марку металла для элементов котельных и турбинных установок; определить виды разрушения металла элемента оборудования в эксплуатации, применять методы математического моделирования при исследовании и проектировании теплотехнологических систем и их элементов; использовать пакеты прикладных программ для моделирования и оптимизации теплотехнологических процессов, установок и систем; выбирать эффективный численный метод для решения конкретной задачи, оценивать его точность и надежность.\r\nНавыки: владение методами неразрушающего и разрушающего контроля металла при диагностировании оборудования, методами и приемами компьютерного моделирования процессов, аппаратов и систем теплоэнергетики с помощью прикладных программ', 'Бублик Дмитрий Алексеевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(226, NULL, NULL, 'Повышение износо- и коррозионностойкости элементов систем пылеприготовления (СПП)', 15, 'Разработка мероприятий, позволяющих защитить элементы СПП от коррозионного и абразивного износа и увеличивающих межремонтный период в 2 раза', 'Абразивные свойства угольной пыли приводят к повышенному износу мелющих органов мельниц (бил, билодержателей молотковых мельниц и мелющих лопаток мельниц-вентиляторов), защитной брони, пылепроводов и других элементов СПП. Их приходится довольно часто менять, что влечёт за собой рост издержек. Эффективность применяемых на сегодня методов защиты рабочей поверхности низка', 2, '2022-09-01', '2023-05-30', '', 'Акселерационная программа «Лаборатория энергетики»\nООО «Байкальская энергетическая компания»\n', NULL, 'Методика повышения износо- и коррозионностойкости элементов систем пылеприготовления (СПП)', 'Знания: строение материалов и общие закономерности формирования их структуры, эксплуатационные свойства материалов и их зависимость от строения, группы материалов, используемые в промышленности, в частности в сфере энергетики и основные способы переработки материалов в изделия. Основные технические характеристики топлив; принципы подготовки топлива к сжиганию в котельных агрегатах на объектах профессиональной деятельности.\nУмения: оценка и прогнозирование поведения материалов и изменения их свойств в зависимости от обработки и эксплуатационных факторов. Проведение лабораторного анализа по определению технических характеристик топлива; планировать и выполнять виды работ по эксплуатации объектов теплоэнергетики.\nНавыки: выбор материалов и назначения технологических процессов их переработки в изделия. Работы по подготовке топлива к сжиганию в котельных агрегатах; организация ремонтов технологического оборудования, монтажных, наладочных и пусковых работ\n', 'Ощепков Василий Владимирович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(227, NULL, NULL, 'Использование низкопотенциальной теплоты системы оборотного водоснабжения ТЭЦ. ', 15, 'Разработка проекта использования низкопотенциальной теплоты в тепловой схеме ТЭЦ.', 'Обзор и поиск технических решений. Литературный обзор  и постановка задач. Выбор вариантов использования низкопотенциальной теплоты системы оборотного водоснабжения ТЭЦ. Технико-экономические расчеты принятых к рассмотрению вариантов использования низкопотенциальной теплоты системы оборотного водоснабжения ТЭЦ.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Повышение энергетической эффективности ТЭЦ.', 'Знания: Знает инструменты поиска информации. \nУмения: Умеет  выделить  из  массива  информации  ключевые  моменты; использовать инструменты поиска информации. \nНавыки: Планирует, выполняет, оформляет и представляет результаты проекта. \n', 'Картавская Вера Михайловна ', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(228, NULL, NULL, 'Снижение потерь напряжения и электроэнергии в распределительных электрических сетях 6-10 кВ', 15, 'Оценка эффективности мероприятий по снижению потерь напряжения и электроэнергии в распределительных электрических сетях 6-10 кВ электросетевой компании', 'На начальном этапе выполняется сбор информации о параметрах режима электрических сетей 6-10 кВ электросетевой компании. Составляются схемы замещения электрической сети, вводятся исходные данные в программу ПРРЭС, разработанную на кафедре электрических станций, сетей и систем. В программе выполняется расчёт максимальных режимов электрической сети, выявляются «очаги» потерь напряжения и электроэнергии. Проводится анализ структуры потерь в электрических сетях, оценка эффективности мероприятий по снижению потерь электроэнергии и напряжения.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Технический отчёт о работе с отражением всех основных этапов проекта', 'Знания: оборудование электрических сетей и систем: линии электропередачи, трансформаторы и др.; процессы, происходящие в электрических сетях\nУмения: применять математический аппарат для исследования потерь в электрических сетях\nНавыки: использование программного обеспечения для проведения расчётов установившихся режимов\n', 'Акишин Леонид Александрович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(229, NULL, NULL, 'Расширение функций интеллектуальной системы учета электроэнергии', 15, 'Расширение функций интеллектуальной системы учета электроэнергии для ее пользователей', 'В соответствии с постановлением Правительства Российской Федерации от 19.06.2020 г. № 890:\n• все приборы учета, вводимые в эксплуатацию энергоснабжающими организациями с 1 января 2022 г. в целях коммерческого учета электроэнергии на розничных рынках и предоставления коммунальных услуг, должны быть присоединены к интеллектуальной системе учета электроэнергии (ИСУЭ);\n• пользователям ИСУЭ предоставляется доступ к минимальному набору функций ИСУЭ. \nВ минимальном наборе функций ИСУЭ предусмотрен доступ к данным измерений интеллектуальных приборов, позволяющим расширить функции ИСУЭ для пользователей. Первоначально проектом предусматривается реализация следующих пяти функций:\nдля потребителей электроэнергии – 1) выбор экономически выгодного тарифа расчета за потребленную электроэнергию; 2) планирование энергоемких процессов хозяйствования с целью уменьшения размера платы за электроэнергию без снижения электропротребления;\nдля сетевых организаций – 3) определение топологии электрической сети; 4) выявление ненаблюдаемых отборов электроэнергии из электрических сетях, в том числе кражи электроэнергии; 5) балансировка нагрузки в распределительных сетях с целью снижения потерь электроэнергии. \nВ дальнейшем планируется расширение функций для пользователей ИСУЭ (потребителей электроэнергии, гарантирующих поставщиков, энергосбытовых организаций, сетевых организаций, производителей электрической энергии, системного оператора и субъектов оперативно-диспетчерского управления, организаций коммерческой инфраструктуры) в соответствии с их потребностями. \n', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Прототипы программных комплексов для пользователей с расширенными функциями ИСУЭ.', 'Знать: конструкции и характеристики интеллектуальных измерительных приборов и ИСУЭ; системы обмена данными между интеллектуальными приборами и ИСУЭ; методы обработки информации;  математическое моделирование и вычислительные методы.\nУметь: использовать методы обработки информации и вычислительные методы; интерпретировать информацию в виде схем, графов, диаграмм, графиков, таблиц.\nВладеть: навыками обработки информации и применения вычислительных методов,  реализации прототипов программ.\n', 'Болоев Евгений Викторович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(230, NULL, NULL, 'Энергетическая безопасность города Иркутска', 15, 'Решение проблемы обеспечения энергетической безопасности города Иркутска', 'Решение проблемы обеспечения энергетической безопасности города Иркутска требует: трактовку понятия энергетическая безопасность; выбор путей ее обеспечения; выбор средств обеспечения  энергетической безопасности города Иркутска.', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Альтернативные проекты обеспечения  энергетической безопасности города Иркутска.', 'Знания: знать основные причины снижения энергетической безопасности\nУмения: уметь выбирать средства повышения энергетической безопасности\nНавыки: владеть навыками оценки энергетической безопасности\n', 'Дубицкий Михаил Александрович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(231, NULL, NULL, 'Определение текущих значений параметров электрооборудования и электрических сетей в нормальном и аварийном режимах по мгновенным цифровым данным', 15, 'Разработка математических способов и алгоритмов определения текущих значений параметров электрооборудования и электрических сетей позволит создать комплекс программ и/или электронных блоков с целью их реализации на внутреннем и внешнем рынке для существующих и интеллектуальных энергосистем ближайшего будущего. Коммерческая реализация проекта требует наличия программистов и электронщиков.', 'Текущее значение параметров электрооборудования и энергосистемы в целом является случайным по целому ряду причин. К основным причинам относятся следующие:\n- переменные погодные условия эксплуатации, которые изменяют проводимость грунта, проводов и тросов заземления, диэлектрическую и магнитную проницаемость среды, распределённую ёмкость и индуктивность ЛЭП и др.;\n- постоянно изменяющийся характер нагрузки в процессе эксплуатации, что приводит к кратковременным перенапряжениям на линиях или к провалам напряжения, перегрузка ведёт к насыщению электротехнической стали магнитопроводов трансформаторов и изменению гармонического состава цепи и др.;\n- включения и отключения мощных потребителей приводят к постоянным переходным процессам на линии;\n- изменяющая со временем топология сети из-за подключения новых и/или отключения существующих потребителей электроэнергии.\nВ этой связи задача определения текущих значений параметров электрооборудования и сетей имеет существенное значение, так как наличие этих параметров позволяет установить место и причину возникновения аварийного режима\n', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Методика, с обязательной фиксацией в одном из форматов: публикация, выпускная квалификационная работа, пояснительная записка или инструкции, а при наличии человеческих ресурсов (программистов и электронщиков) и финансовых ресурсов для оплаты их труда, приобретения оборудования и комплектующих деталей – создание конкурентных электронных блоков, защищённых патентами РФ', 'Знания: физико-математический аппарат, методы анализа и моделирования, теоретического и экспериментального исследования для определения текущих значений параметров электрооборудования и сетей\nУмения: оформлять результаты научно-исследовательской работы в виде отчёта, реферата или публикации\nНавыки: навыки публичной защиты результатов научно-исследовательской работы\n', 'Муссонов Геннадий Петрович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(232, NULL, NULL, 'Разработка и исследование методик определения мест повреждения в  электрических сетях с изолированной нейтралью.', 15, 'Разработать и исследовать методику определения поврежденного присоединения при однофазном замыкании на землю (ОЗЗ) в электрических сетях с изолированной нейтралью. Исследовать методики определения места повреждения (ОМП) на поврежденной линии электропередачи.', 'Изучается методика расчета электрических режимов в  фазных координатах (ФК). Осваивается работа в программном комплексе «Расчет в ФК». Формируется модель электрической сети с изолированной нейтралью для проведения расчетов в ФК. Проводится серия расчетов режимов в ФК. Формируются рекомендации. ', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Будет разработана методика определения поврежденного присоединения при ОЗЗ в электрических  сетях с изолированной нейтралью. Будет разработана релейная защита для отключения поврежденного присоединения с ОЗЗ. Будет разработана лабораторная работа по методике определения поврежденного присоединения при ОЗЗ в электрических  сетях с изолированной нейтралью. ', 'Знания: По проблеме ОМП при ОЗЗ в сетях с изолированной нейтралью.  По расчету электрических режимов в ФК и работе в программном комплексе «Расчет в ФК»\nУмения: Формировать модель электрической сети с изолированной нейтралью для проведения расчетов в ФК\nНавыки: Расчета нормальных и аварийных режимов в ФК в сетях с изолированной нейтралью.\n', 'Тигунцев Степан Георгиевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(233, NULL, NULL, 'Разработка проектной документации и модернизация лабораторного оборудования кафедры электрических станций, сетей и систем', 15, 'Разработка документации, модернизация и монтаж оборудования учебных лабораторий кафедры электрических станций, сетей и систем: аудитория В-212, аудитория В-016, учебный полигон – подстанция 110 кВ', 'Проектная документация на оборудование учебной лаборатории релейной защиты и автоматики (ауд. В-212) не везде соответствует фактической сборке стенда, что усложняет проведение лабораторных работ. В учебно-исследовательской лаборатории «Электрическая часть электростанций и подстанций» (ауд. В-016) в 2021 году восстановлена ячейка комплектного распределительного устройства 10 кВ, документация на которую отсутствует. Имеются отдельные цифровые терминалы релейной защиты и автоматики серии MiCOM, которые необходимо подключить к оборудованию учебного полигона – подстанции 110 кВ между корпусами В и Г. Некоторые стенды лабораторий требуют специального профилактического обслуживания.\nПри выполнении проекта будет сформировано 3-4 бригады по 3-4 студента, каждая из которых будет выполнять проверку, прозвонку и составление реальной электрической схемы закреплённого за ней лабораторного оборудования, формировать электрические схемы лабораторных стендов в цифровом виде при помощи систем автоматизированного проектирования и/или редакторов схем (nanoCAD, Компас, Visio). Под руководством наставника студенты проведут модернизацию лабораторного оборудования, выполнят монтаж дополнительных узлов и элементов схем лабораторных стендов, проведут пусконаладочные работы.\n', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Документация к лабораторным стендам в виде исполнительных электронных схем, модернизированные лабораторные стенды.', 'Знания: принципы работы первичного и вторичного электрооборудования, схемы управления и блокировок первичного электрооборудования, принципы действия различных типов релейной защиты электрооборудования от коротких замыканий\nУмения: проверять электрические схемы, выполнять электромонтажные и профилактические работы электрооборудования, представлять результаты выполненной работы в виде пояснительной записки\nНавыки: чтение электрических схем первичного и вторичного электрооборудования, работа в системах автоматизированного проектирования и/или редакторах схем, выполнение пусконаладочных работ электрооборудования, защита результатов выполненной работы в виде доклада\n', 'Федосов Денис Сергеевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(234, NULL, NULL, 'Математическое моделирование фотоэлектрических систем и ветропарков большой мощности', 15, 'Создание программы для расчета режимных параметров фотоэлектрических систем и ветропарков большой мощности ', 'Современный этап развития энергетических систем характеризуется глубокой интеграцией возобновляемых источников энергии. Наличие экологически чистых комплексов генерации наблюдается на всех уровнях напряжений, начиная с крупных системообразующих объектов и заканчивая мини- и микроустановками, расположенными непосредственно у потребителя. Главной задачей, возникающей при использовании возобновляемых источников энергии, является оптимизация состава оборудования и установленных мощностей. При этом в качестве целевой функции могут выступать различные критерии эффективности применения возобновляемых источников энергии. Например, в автономных энергетических системах целевая функция, как правило, представлена нормированной стоимостью энергии (руб./кВт∙ч), в системах резервного и аварийного (в т.ч. комбинированного) питания – максимизация количества часов автономного снабжения и минимизация недоотпуска электроэнергии, в комплексах генерации, реализующихся в рамках энергосервисного контракта – количество сэкономленного органического топлива и прибыль инвестора. Представленные критерии могут быть объединены и расширены в зависимости от условий поставленной задачи.\nОпределение численных значений критериев эффективности напрямую связанно с моделированием режимов работы энергетических систем, состоящих из элементов генерации, передачи, распределения, аккумулирования и потребления энергии. Цель данного исследования состоит в формировании ряда требований к математической модели фотоэлектрических преобразователей и демонстрации подходов, позволяющих моделировать все необходимые режимные параметры фотоэлектрических систем и ветропарков с учётом изменения метеоусловий.\n', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Универсальные математические модели и программы для расчета режимов фотоэлектрических систем и ветропарков', 'Знания: теоретические основы электротехники, методы оптимизации, возобновляемые источники энергии\nУмения: выполнять расчеты, моделировать технические объекты, работать в команде\nНавыки: основы программирования в Matlab\n', 'Карамов Дмитрий Николаевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(235, NULL, NULL, 'Интеграция аккумулирующих устройств большой емкости в энергетические системы с возобновляемыми источниками энергии', 15, 'Создание расчетного модуля для решения задач обоснования интеграции аккумулирующих устройств большой емкости в энергетические системы', 'При исследовании энергетических систем с возобновляемыми источниками энергии и аккумуляторными батареями важно учитывать процессы деградации и замены энергетического оборудования в течение всего срока эксплуатации. Это необходимо для точного определения дополнительных издержек на замену, влияющих на показатели экономической эффективности рассматриваемого состава оборудования. \nАккумуляторные батареи являются стабилизирующим элементом автономной энергетической системы, работающий в циклическом режиме. Циклический режим характеризуется сменяющими друг друга процессы заряда и разряда в зависимости от генерации возобновляемых источников энергии и уровня электрической нагрузки. Стохастическая составляющая генерации существенно отражается на основных эксплуатационных показателях аккумуляторных батарей, таких как состояние заряда, падение напряжения, внутреннее сопротивление, а также химических процессах.\nАккумуляторные батареи имеют три важных показателя таких как максимальный срок службы, предельное количество циклов заряд/разряд в зависимости от глубины разряда и среднегодовое количество циклов заряд/разряд. \n', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Универсальные математические модели и программы для расчета режимов работы накопителей энергии и энергетических систем', 'Знания: теоретические основы электротехники, методы оптимизации, возобновляемые источники энергии, \nУмения: выполнять расчеты, моделировать технические объекты, работать в команде\nНавыки: основы программирования в Matlab\n', 'Суслов Константин Витальевич', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(236, NULL, NULL, 'Использование концепции энергетического хаба и потоковых методов в интегрированных энергетических системах ', 15, 'Определить с помощью потоковых методов уровень структурной надежности интегрированных систем.  ', 'Энергетика является важнейшей отраслью, охватывающей добычу энергоресурсов, производство, преобразование, транспортировку и использование энергии потребителями. Энергоснабжение потребителей обеспечивается различными видами энергоресурсов, которые мало взаимосвязаны между собой. В качестве объединяющей системы выступает топливно-энергетический комплекс (ТЭК) России. ТЭК включает в себя основные три подсистемы: топливоснабжающие системы; системы электро– и теплоснабжения; система ядерной энергетики. На этапе планирования развития ТЭК рассматриваются все отрасли энергетики, но вопросам комплексного использования различных видов энергии не уделяется должного внимания.\nПредлагается определить структурную надежность интегрированных систем энергоснабжения с использованием различных методов. \n', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Методика определения структурной надежности системы энергоснабжения.', 'Знания: \n– перспективы и возможности развития концепции интеллектуальных энергетических систем;\n– технологический базис интеллектуальных энергетических систем;\nУмения: \n– использовать методические, нормативные и руководящие материалы, касающиеся выполняемой работы;\n– формулировать и решать задачи, возникающие в ходе производственно-технологической и научно-исследовательской деятельности и требующих углубленных профессиональных знаний;\n– анализировать, структурировать и обобщать научно-исследовательские материалы\nНавыки: \n– владеть терминологией в области интегрированных энергетических систем; \n– владеть навыками определения структурной надежности методом поиска путей и сечений. \n', 'Сердюкова Екатерина Владимировна ', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(237, NULL, NULL, 'Создания кибер-физической модели изолированных систем электроснабжения с возобновляемыми источниками энергии', 15, 'Разработка и апробирование алгоритма создания цифровых двойников изолированных систем с ВИЭ на базе кибер-физической модели', 'Согласно концепции цифровой трансформации российской экономики и в частности трансформации российской ТЭК разработаны основные подходы для реализации данной программы. Один из элементов цифровой платформа является цифровой двойник энергетического объекта или системы. Существует два подхода для реализации  данного направления: цифровой двойник, в основе которого лежат нелинейные дифференциальные уравнения в частных производных; цифровая тень, в основе  которого лежат промышленный интернет вещей и большие данные.\nЦелью данных подходов является получение алгоритмов управления энергетическими объектами (системами) для которых невозможно реализовать типовые алгоритмы управления.\nДля этих целей создается кибер-физическая модель, состоящая из реальных элементов энергетических систем: трансформатора, источника питания, физические модели линии передач, физические модели нагрузок. В дальнейшем в системе имитационного моделирования создается имитационная модель данной физической модели энергетической системы. Проводится верификация различных режимов работы физической модели и имитационной модели, на этом этапе уточняются алгоритмы расчета параметра блоков имитационной модели по номинальным (каталожным) данным реальных электротехнических объектов. В дальнейшем имитационная модель используется для получения большого объема статистической информации по различным режимам работы физической модели (BIG DATA). Эти данные лежат в основе создания различных алгоритмов управления с использования элементов искусственного элемента. Полученные алгоритмы управления проверяются на кибер-физические  модели. \n', 2, '2022-09-01', '2023-05-30', '', '', NULL, 'Результатом проведенной работы являются различные алгоритмы и процедуры, позволяющие создать адекватную имитационную модель по параметрам реального энергетического объекта и будет проведена апробация различных алгоритмов управления на базе искусственного интеллекта с целью выбора наиболее оптимального варианта.   ', 'Знания: принципы работы основного электрооборудования, трансформатора, линии передачи, нагрузки, принципы работы основных систем имитационного моделирования энергетическими объектами \nУмения: выполнение электромонтажных работ, снятие рабочих характеристик с основных электротехнических объектов     \nНавыки:  чтение электрических схем первичного вторичного электрооборудования, работа в системах имитационного моделирования с защитой результатов выполненной работы\n', 'Шамарова Наталия Андреевна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(238, NULL, '2022-08-30 05:22:44', 'Разработка проектов систем автоматизации промышленных установок', 15, 'Разработка технорабочих проектов автоматизированных систем управления (АСУ) объектов промышленного и энергетического оборудования.', 'Выбор темы проекта и формулировка технических предложений по проекту. Изучение способов получения и обработки информации по проекту. За время обучения студенты получают опыт проектной работы по своей будущей профессии, лучше поймают взаимосвязь преподаваемых дисциплин с практикой и значимость командной работы, а также вырабатывают умение доводить дело до конца и в срок. Дополнительно к диплому каждый выпускник к окончанию университета может сформировать свое личное портфолио реализованных проектов с различными компаниями, что может помочь ему в трудоустройстве на более привлекательную работу и создаст предпосылки для образования в ИРНИТУ компаний-технологических стартапов, способных самостоятельно продолжать работу, начатую в рамках проектной деятельности в партнерстве с внешними заказчиками.', 3, '2022-09-01', '2023-05-30', NULL, 'ООО «Иркутский институт Гипрокоммунводоканал» \r\n664033, Россия, Иркутская область, г. Иркутск,\r\nул. Лермонтова, д. 257\r\nТел. +7(3952) 56-22-30\r\nwww.polyplastic.ru', NULL, 'Технический проект (ТП), Рабочий проект (РП). Обеспечение объекта проектной документацией, позволяющей реализовать автоматизированную систему управления.', 'Знания: основ разработки проектной и рабочей документации автоматизированных систем управления объектов промышленного и энергетического оборудования.\r\nУмения: рассчитывать необходимое количество средств измерений, управляющего и коммутационного оборудования, предлагаемого промышленностью.\r\nНавыки: выбора необходимого типа и номенклатуры оборудования, изделий, материалов.', 'Довудов Сарфароз Умедович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(239, NULL, NULL, 'Система инженерных электротехнических коммуникаций электрооборудования', 15, 'Разработка системы электротехнических коммуникаций, предназначенных для создания внутренних инженерных сетей, используемых для электроснабжения и управления электрооборудованием', 'Для электроснабжения и управления электрооборудованием используются сети внутренних инженерных коммуникаций. В ходе проектирования требуется точно определить структуру сети, ее геометрические и электрические параметры, включающие планы оборудования, их мощность, требования по размещению, управлению и электроснабжению. \nПри этом разрабатываемая система инженерных электротехнических коммуникаций электрооборудования уникальна для каждого объекта. Так же в случае внесения изменения в конструкторскую документацию системы требуется в кратчайшие сроки либо перепроектировать существующую, либо создать новую систему внутренних инженерных сетей. \nБольшая часть требований к системам электротехнических коммуникаций имеет формализованный вид и описана в научной литературе, а трудоемкость их проектирования связана, в первую очередь, с выполнением большого числа рутинных операций конструктором. \nТаким образом, для ускорения процесса проектирования наиболее рационально перенести большую часть рутинных операций проектирования в среду автоматизированной системы, а так как в России широко используется система AutoCad, то автоматизированные процедуры проектирования можно реализовать посредством использования ее последних версий.', 3, '2022-09-01', '2023-05-30', '', '', NULL, 'Проект внутреннего электроснабжения и электроосвещения заданных помещений', 'Знания: основ разработки проектной документации внутреннего электроснабжения и электроосвещения.\nУмения: рассчитывать необходимое количество осветительного и коммутационного электрооборудования.\nНавыки: выбора необходимого типа и номенклатуры кабельных изделий.\n', 'Дунаев Андрей Михайлович', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(240, NULL, NULL, 'Газпром Инвест', 15, 'Получение навыков проектной работы при постоянном взаимодействии с проектным офисом компании в процессе решения кейсов из реального производства  ', 'ООО «Газпром инвест» — единый технический заказчик по реализации инвестиционных проектов ПАО «Газпром», в том числе по геолого-разведочным работам, строительству, реконструкции, капитальному ремонту объектов добычи, транспорта, подземного хранения, переработки газа, объектов газификации и гражданского назначения.\n\nПроектная команда будет работать со специалистами компании в городе Иркутске.\nИз числа участников команды формируется «копия» проектной команды Филиала для решения актуальных задач компании в области  проектирования, строительства и ввода в эксплуатацию объектов газовой отрасли промышленного и гражданского назначения на Ковыктинском ГКМ. \nВ рамках работы над проектом вы получите навыки работы в реальной компании над актуальной проблемой отрасли', 3, '2022-09-01', '2023-05-30', '', 'Филиал ООО «Газпром инвест» Иркутск', '', 'Проектное предложение', 'Знания: матричной структуры управления, планирования и управления проектами. Предметные знания в области геолого-разведки, строительства, проектного управления, добычи и транспортировки газа. \nУмения: работы в команде, построенной по принципам матричного управления. Взаимодействия со специалистами  отрасли строительства и газодобычи\nНавыки: работы в кооперации с представителями реальной компании, междисциплинарного взаимодействия с целью решения реальных задач, навыки планирования и управления реальными проектам', '', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(241, NULL, '2022-06-16 08:18:20', 'Современная уголовная политика России', 15, 'Изучить различные направления уголовной политики современной России', 'Уголовная политика государства – это одно из направлений деятельности государства, так называемый основополагающий вектор в сфере борьбы с преступностью. На современном этапе уголовной политике уделяется особенное внимание, поскольку уголовная политика напрямую влияет на состояние и показатели преступности в стране, а также позволяет строить прогноз на последующее совершенствование уголовно-правовых норм, с целью снижения уровня преступности в целом. Состояние преступности в нашей стране требует постоянного внимания общества и государства. Определить в рамках темы проекта направление исследования; подготовить план исследования; подобрать научную, учебную литературу, судебную практику, статистические данные; подготовить научную статью в рамках определённой тематики, опубликовать статью в журнале ВАК', 2, '2022-09-01', '2023-05-30', NULL, NULL, NULL, 'Научно-исследовательская работа студента', 'Знания:\r\nЗнать основные инструменты поиска информации.\r\nЗнать основные требования к представлению результатов проекта.\r\nЗнать основные принципы планирования и организации своей деятельности.\r\nУмения:\r\nУметь использовать инструменты поиска и анализа информации.\r\nУметь выделить из массива информации ключевые моменты.\r\nУметь использовать основные инструменты планирования и реализации проекта.\r\nУметь подготовить результаты.\r\nНавыки:\r\nВладеть навыками поиска информации.\r\nВладеть навыками анализа информации с целью выделения требуемого знания.\r\nВладеть навыками на основе полученной первичной информации сформировать комплексное понимание предмета изучения.\r\nВладеть навыками презентации результатов проекта.\r\nВладеть навыками самоанализа и может оценить личный вклад в достигнутых результатах.\r\nВладеть навыками определения и постановки задач.', 'Герасимова Юлия Радиковна', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(300, NULL, NULL, 'Газпром Инвест', 15, 'Получение навыков проектной работы при постоянном взаимодействии с проектным офисом компании в процессе решения кейсов из реального производства  ', 'ООО «Газпром инвест» — единый технический заказчик по реализации инвестиционных проектов ПАО «Газпром», в том числе по геолого-разведочным работам, строительству, реконструкции, капитальному ремонту объектов добычи, транспорта, подземного хранения, переработки газа, объектов газификации и гражданского назначения.\n\nПроектная команда будет работать со специалистами компании в городе Иркутске.\nИз числа участников команды формируется «копия» проектной команды Филиала для решения актуальных задач компании в области  проектирования, строительства и ввода в эксплуатацию объектов газовой отрасли промышленного и гражданского назначения на Ковыктинском ГКМ. \nВ рамках работы над проектом вы получите навыки работы в реальной компании над актуальной проблемой отрасли', 3, '2022-09-01', '2023-05-30', '', 'Филиал ООО «Газпром инвест» Иркутск', '', 'Проектное предложение', 'Знания: матричной структуры управления, планирования и управления проектами. Предметные знания в области геолого-разведки, строительства, проектного управления, добычи и транспортировки газа. \nУмения: работы в команде, построенной по принципам матричного управления. Взаимодействия со специалистами  отрасли строительства и газодобычи\nНавыки: работы в кооперации с представителями реальной компании, междисциплинарного взаимодействия с целью решения реальных задач, навыки планирования и управления реальными проектам', '', 4, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL),
(301, NULL, NULL, 'Проект \"Форсайт\"', 100, 'Возможность реализации тем проектов, предложенных студентами в инициативном порядке в рамках проектной форсайт-игры', 'Центр проектного обучения проводит проектную форсайт-игру в целях выявить инициативные темы проектов студентов или тематики, предложенные наставниками, и вовлечь активных студентов и наставников в их реализацию в рамках «Проектной деятельности» в 2022 - 2023 учебном году. Реализация проекта позволит поддержать студенческие проектные инициативы и активных студентов, а также способствует развитию образовательных форматов, направленных преимущественно на формирование soft skills у студентов в проектной деятельности.\nКонтакт для связи по проекту https://t.me/tuymada', 2, '2022-01-09', '2023-05-30', '', 'Центр проектного обучения', NULL, '', '', 'Чимитов П.Е.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(302, NULL, NULL, 'Проект \"Форсайт\"', 100, 'Возможность реализации тем проектов, предложенных студентами в инициативном порядке в рамках проектной форсайт-игры', 'Центр проектного обучения проводит проектную форсайт-игру в целях выявить инициативные темы проектов студентов или тематики, предложенные наставниками, и вовлечь активных студентов и наставников в их реализацию в рамках «Проектной деятельности» в 2022 - 2023 учебном году. Реализация проекта позволит поддержать студенческие проектные инициативы и активных студентов, а также способствует развитию образовательных форматов, направленных преимущественно на формирование soft skills у студентов в проектной деятельности.\nКонтакт для связи по проекту https://t.me/tuymada', 2, '2022-01-09', '2023-05-30', '', 'Центр проектного обучения', NULL, '', '', 'Чимитов П.Е.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(303, NULL, NULL, 'Проект \"Форсайт\"', 100, 'Возможность реализации тем проектов, предложенных студентами в инициативном порядке в рамках проектной форсайт-игры', 'Центр проектного обучения проводит проектную форсайт-игру в целях выявить инициативные темы проектов студентов или тематики, предложенные наставниками, и вовлечь активных студентов и наставников в их реализацию в рамках «Проектной деятельности» в 2022 - 2023 учебном году. Реализация проекта позволит поддержать студенческие проектные инициативы и активных студентов, а также способствует развитию образовательных форматов, направленных преимущественно на формирование soft skills у студентов в проектной деятельности.\nКонтакт для связи по проекту https://t.me/tuymada', 2, '2022-01-09', '2023-05-30', '', 'Центр проектного обучения', NULL, '', '', 'Чимитов П.Е.', 4, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(304, NULL, '2023-02-27 19:06:29', 'Разработка цифрового двойника авиастроительного предприятия с применение VR (unity)', 15, 'Создание цифрового двойника производственного помещения в образовательном сегменте позволит обеспечить доступные инструменты для пользователей и дополнить обучающие программы интерактивным визуальным контентом. Погружение студентов в производственную атмосферу, без физического присутствия на производстве.', 'В настоящее время имеется следующий задел по проекту: разработано 1 станция виртуальной сборки, виртуализированы 3 лабораторных работ. \r\nВ рамках данного проекта планируется масштабировать виртуальные цеха авиастроительного предприятия, доработать имеющийся сценарий агрегатно-сборочных работ.', 2, '2023-02-06', '2023-06-25', NULL, 'Иркутский авиазавод, применение современных ИТ инструментов для цифровизации производств', NULL, 'Создан симулятор (тренажер), содержащий следующие функции:\r\n1. Знакомство с конструкцией авиационных узлов и агрегатов (членение агрегатов и узлов)\r\n2. Монтаж и ППР сборочного приспособления (доработка существующего функционала)', 'Знания: принципы работы с gamedev\r\nУмения: читать и составлять техническую документа. \r\nНавыки: работа с графическими редакторами, создание и реализация сценария', 'Говорков Алексей Сергеевич', 4, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL),
(305, NULL, NULL, 'Разработка цифрового следа обучающего ИРНИТУ (на примере студента института ИТиАД)', 15, 'Разработка решения для сбора цифрового следа обучающихся ИРНИТУ (на примере обучающихся Института информационных технологий и анализа данных)', 'Целью данного проекта является разработка концепции, модели и прототипа (макетная реализация) информационной системы для сбора данных, являющихся составляющими цифрового следа студентов, обучающихся в ИРНИТУ. Собираемые данные содержат информацию об активностях студентов и достигнутых результатах в рамках этих активностей. Под «активностью студента» в проекте понимается участие обучающегося в учебных, научных и общественных мероприятиях, проводимых в университете и за его пределами. \nВ настоящее время имеется следующий задел по проекту: в информационных системах университета фиксируются данные об успеваемости студентов, проводимых мероприятиях, победителях и призерах олимпиад и конференций.\nВ рамках данного проекта планируется разработка концепции (принципиальной модели сбора цифрового следа студентов), модели бизнес-процессов для сбора информации о деятельности студентов, проектирование хранилища данных и реализация прототипа информационной системы\n', 2, '2023-02-06', '2023-06-25', '', 'Управление по молодёжной политике, Учебно-методическое управление, Управление научной деятельности', NULL, 'Концепция системы для сбора данных о деятельности студентов, проект информационной системы для фиксации цифрового следа, реализация системы на уровне прототипа', 'Знания: принципы построения информационных систем, основы веб-программирования, принципы интеграции информационных систем, нотация Чена, стандарты описания UML, IDEF0.\nУмения: анализировать проблему и ставить задачу, читать и составлять техническую документацию с использованием стандартов UML, IDEF0, моделировать данные, составление SQL-запросов.\nНавыки: проектирования информационных систем, работа с реляционными СУБД, разработка JavaScript-скриптов, разработка php-скриптов.\n', 'Копайгородский Алексей Николаевич', 4, 1, 2, NULL, NULL, NULL, NULL, NULL, NULL),
(306, NULL, '2022-08-30 10:36:46', 'Применение фотограмметрии для построения 3D моделей объектов при проектировании', 15, 'Разработать и опробовать методику построения 3D модели ( dwg-формат) по массиву фотографий объекта', 'При выполнении предпроектных обследований действующего электрооборудования значительную часть времени занимают обмерные работы. Зачастую, по условиям безопасного выполнения работ, не все замеры можно выполнить.', 2, '2023-02-06', '2023-06-25', NULL, 'ГК «ЕвроСибЭнерго»', NULL, 'Разработана методика должна содержать последовательность действий, требования к исходному материалу (качество, количество и ракурс фотографий) и условия (освещенность и т.п).\r\nРазработанная методика позволяет выполнять работы (получение объемных планов/чертежей расположения оборудования) с меньшими трудозатратами по сравнению с натурными обмерами..\r\nСтоимость применяемого оборудования и ресурсов для обработки фотографий должна быть экономически выгодна по сравнению с классическими методами..\r\nПроведен эксперимент.', 'Знания: принципы работы с C#/Python/OpenCV\r\nУмения: читать и составлять техническую документа. \r\nНавыки: работа с графическими редакторами, создание и реализация алгоритма', 'Григорьев Станислав Валентинович', 4, 1, 3, NULL, NULL, NULL, NULL, NULL, NULL),
(307, NULL, '2023-04-04 11:12:56', 'Развитие веб-платформы «Ярмарка проектов ИРНИТУ»', 16, 'Создание решения для поддержки процесса распределения студентов ИРНИТУ в рамках проектной деятельности', 'Данный проект основывается на результатах проекта «Развитие веб-платформы “Ярмарка проектов” института ИТиАД»\r\nВ настоящее время имеется следующий задел по проекту: разработано веб-приложение позволяющее студентам просматривать карточки проектов, осуществлять сбор заявок от студентов на участие и автоматически распределять студентов по проектам с учетом их предпочтений и принадлежности к тому или иному направлению подготовки\r\nВ рамках данного проекта планируется доработать имеющуюся систему для поддержки процесса распределения студентов ИРНИТУ по проектам, для чего необходимо реализовать интерфейс руководителя центра проектного обучения, а также разработать механизмы дальнейшей интеграции с «АИС Университет»', 2, '2023-02-06', '2023-06-25', NULL, 'Центр проектного обучения', NULL, 'Реализация следующих функций: добавление отзыва руководителя на работу участника проекта,  интерфейс руководителя центра проектного обучения для загрузки аннотаций проектов в систему, ручного перераспределения студентов по проектам, запуска механизма автоматического распределения студентов, в том числе «молчунов» (не подавших заявки на проекты), выгрузки списков распределения студентов по проектам.', 'Знания: принципы работы веб-сайта, основы веб-программирования, ORM-фреймворки, нотация Чена, стандарты описания UML, IDEF0, RDF\r\nУмения: читать и составлять техническую документацию с использованием стандартов UML, IDEF0, RDF, моделирование данных, составление SQL-запросов, \r\nНавыки: работа с СУБД MySQL, администрирование Linux, работа с Figma, разработка JavaScript скриптов, разработка php-скриптов, работы с Laravel', 'Аршинский Вадим Леонидович, Серышева Ирина Анатольевна', 4, 1, 4, 63, NULL, NULL, NULL, NULL, NULL),
(308, NULL, NULL, 'Разработка методов и программного средства автоматического извлечения данных из таблиц', 15, 'Создание решения для поддержки процесса автоматического извлечения данных из таблиц', 'Данный проект связан с разработкой модуля семантической интерпретации таблиц в рамках веб-платформы TALISMAN, предназначенной для построения предметно-ориентированных интеллектуальных систем поиска и извлечения информации. Разработка проводиться совместно с Институтом системного программирования им. В.П. Иванникова РАН и Институтом динамики систем и теории управления им. В.М. Матросова СО РАН.\nОсновная задача модуля – извлечение знаний в виде набора фактов из реляционных таблиц, содержащихся в различных документах (PDF, DOCX, HTML и др.) и наполнение этими фактами целевого графа знаний (labeled property graph).\nВ настоящее время имеется следующий задел по проекту: разработан модуль для автоматизированного извлечения фактов из строк реляционных таблиц на основе специально подготовленной конфигурации в формате JSON (в этой конфигурации явно указывается, какие факты и откуда извлекать).\nВ рамках данного проекта планируется доработать имеющийся модуль, сделать его более универсальным, в том числе для случаев, когда в документе много таблиц и они разные по структуре. В частности, необходимо реализовать автоматическое распознавание типов таблиц (вертикальная, горизонтальная, матричная) и приведение их к реляционной форме, включая отдельные задачи по нормализации данных и определению заголовков таблиц.\nВ целом данный проект связан с крупной и актуальной на сегодняшний день научной проблемой – автоматического понимания табличной информации (table understanding). Проект соответствует мировому уровню.\n', 3, '2023-02-06', '2023-06-25', '', 'ИДСТУ СО РАН / ИСП РАН', NULL, 'Реализация следующих функций: автоматическое распознавание типов таблиц, автоматическое приведение распознанных таблиц к реляционной форме, автоматическая идентификация данных и метаданных (заголовков) в таблицах.', 'Знания: общее представление о научной проблеме понимания табличной информации, принципы интеграции и настройки готовых программных решений, объектно-ориентированное программирование, основы обработки естественного языка (NLP) и машинного обучения, в частности глубокие нейросетевые модели (DNN), CRF, SVM.\nУмения: программирование в объектно-ориентированном стиле на языке Python, формирование тестовых и обучающих выборок, проведение тестов производительности, взаимодействие в команде разработчиков, составление документации\nНавыки: работа с платформой TALISMAN, работа с форматом JSON, разработка py-скриптов, работа на ML-платформе TensorFlow, администрирование Linux, работа в системе контроля версий Git\n', 'Юрин Александр Юрьевич, Дородных Никита Олегович', 4, 1, 5, NULL, NULL, NULL, NULL, NULL, NULL),
(309, NULL, '2022-06-24 08:13:59', 'Развитие системы «Рейтинг студентов»', 15, 'Автоматизация процесса формирования списков студентов на получение повышенной стипендии', 'Данный проект основывается на результатах проекта «Рейтинг студентов». \r\nНа данный момент в рамках проекта выполнены следующие работы: анализ деятельности по начислению рейтинговой стипендии студентам ИрНИТУ; выделено пять модулей данного процесса; проведены подробный анализ и  проектирование модуля распределения стипендии; разрабатывается прототип версия модуля распределения стипендии.\r\nВ рамках данного проекта планируется выполнение дальнейших работ по разработке системы «Рейтинг студентов»:  выпустить первый релиз  модуля  распределения стипендии; выполнить детальный анализ и проектирование модуля формирования коллективов, разработать механизм интеграции проекта с  «АИС Университет»', 3, '2023-02-06', '2023-06-25', NULL, 'Управление информатизации ИРНИТУ', NULL, 'Результат данного проекта: проектная документация модуля формирования коллективов  и реализация модуля распределения стипендии.', 'Знания: нотаций URL,  IDEF0, DFD,  RDF, нотация Чена, основы веб-программирования, основы проектирования программ\r\nУмения:  применять методы проектирования программного продукта, работать  с инструментальными средствами, поддерживающими создание программного обеспечения; использовать методы организации работы в коллективах разработчиков программного обеспечения; \r\nНавыки:  работа с СУБД SQL, работа с Figma, разработка JavaScript скриптов, разработка php-скриптов, работы с Laravel и React, HTML, CSS', 'Бахвалова Зинаида Андреевна, Каташевцев Михаил Дмитриевич', 4, 1, 6, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(310, NULL, NULL, 'Создание интеллектуальной технологии цифрового материаловедения для анализа и прогнозирования свойств кристаллических кремниевых материалов для солнечной энергетики', 15, 'Разработка программно-инструментальных средств для автоматизированного анализа структурных, электрических и эксплуатационных свойств поликристаллических материалов с целью создания универсальных руководящих принципов получения высокопроизводительных материалов для солнечной энергетики. ', 'В рамках заявляемого проекта предполагается использовать мультикристаллический кремний в качестве модельного материала для разработки комплекса программ, реализующих следующие полезные модели:\n• усовершенствованная  нейронная сеть  для идентификации параметров ориентации монокристаллических зёрен в промышленных слитках мультикремния по их сканированным изображениям;\n• модель для  автоматизированного зонирования макроструктуры продольных пластин слитков мультикремния с целью поиска взаимосвязей между пространственным распределением зон на изображениях пластин и условиями направленной кристаллизации. \n', 3, '2023-02-06', '2023-06-25', '', 'Институт геохимии им. А.П. Виноградова СО РАН', NULL, '1. Усовершенствованная методика проведения автоматизированного статистического анализа сканированных изображений продольных и поперечных пластин мультикремния с применением кластерного анализа с целью поиска небольшого числа малых репрезентативных областей для сканирования с помощью выборочного ориентационного метода анализа дифракции обратно-рассеянных электронов (ДОРЭ);\n2. Нейронная сеть, улавливающая взаимосвязи оттенков серого цвета отдельных точек сканированного изображения и исходных данных ДОРЭ (матрица значений углов Эйлера) соответствующего образца и на основе этого идентифицирующая  параметры ориентации зёрен (на макроуровне) на всей площади сканированной пластины;\n3. Нейронная сеть, способная решать указанные задачи на разных пластинах мультикремния;\n4. Модель, с помощью которой будут выявлены зоны макроструктуры на сканированных изображениях продольных пластин слитков мультикремния;\n5.  Прототип программного комплекса для автоматизированного анализа структурных, электрических и эксплуатационных свойств поликристаллических материалов\n', 'Знания: математические и алгоритмические  основы моделей  машинного обучения, основы программирования на языке Python, стандарты описания UML, IDEF0.\nУмения: применить  знания основ высшей математики и математической статистики на практике, создавать модели  машинного обучения для решения научно-исследовательских и промышленных  задач, читать и составлять техническую документацию с использованием стандартов UML, IDEF0.\nНавыки: реализация нейронных сетей и других алгоритмов машинного обучения  с помощью языка Python,  создание GUI –приложений на языке Python\n', 'Осипова Елизавета Алексеевна', 4, 1, 7, NULL, NULL, NULL, NULL, NULL, NULL),
(311, NULL, NULL, 'Разработка концепции Ситуационно-аналитического центра энергетической компании', 15, 'Разработка концепции Ситуационно-аналитического центра энергетической компании', 'В компании создан САЦ, но нет стратегии по наполнению данными и анализу этих данных. Необходимо выполнить ряд задач: 1) Сократить время реагирования и ликвидации аварий и нештатных ситуаций. 2) Найти способы снижение аварийности основного и вспомогательного оборудования, за счет оперативного оповещения о внештатных ситуациях. 3) Найти способ сокращения затрат на ТОиР. 4) Сформировать предложения, направленных на увеличение надежности работы оборудования энергетического оборудования. 5) Повысить достоверность и оперативности доставки и обработки информации об авариях, чрезвычайных и нештатных ситуациях, связанных с производственной деятельностью объектов управления, а также ЧС природного и техногенного характера. 6) Снизить трудоемкость процессов отслеживания текущей ситуации и подготовки оперативных сводок, справок и отчетов.', 2, '2023-02-06', '2023-06-25', '', 'ООО \"Эн+ Диджитал\"', NULL, 'Концепция с детальным описанием бизнес-процессов, систем целевой модели; информационных потоков, методов их обработки. Выделение целей использования  и групп пользователей.', 'Знания: понятие ситуационно-аналитических центров, основы программирования на языках высокого уровня, знакомство с методами визуальной аналитики, нотация Чена, стандарты описания UML, IDEF0, BPMN\nУмения: читать и составлять техническую документацию с использованием стандартов UML, IDEF0, BPMN\nНавыки: администрирование, работа с СУБД, работа с Dashboard  разработка JavaScript скриптов, разработка php-скриптов, работы\n', 'Массель Алексей Геннадьевич', 4, 1, 8, NULL, NULL, NULL, NULL, NULL, NULL),
(312, NULL, NULL, 'Инструментальные средства для моделирования интеллектуальных интегрированных энергетических систем на основе мультиагентного подхода', 15, '', 'Разработка средств для моделирования интеллектуальных интегрированных энергетических систем', 2, '2023-02-06', '2023-06-25', '', 'ИСЭМ СО РАН, возможно участие в грантах и публикация научных статей', NULL, 'Мультиагентная система для моделирования интеллектуальных интегрированных энергетических систем при решении задач их управления', 'Знания: принципы проведения мультиагентного моделирования, обучение с подкреплением \nУмения: применение машинного обучения, моделирование энергетических систем, их подсистем и элементов. \nНавыки: работа в программной среде AnyLogic, разработка моделей в MatLab, работа с программными библиотеками, реализующими обучение с подкреплением\n', 'Барахтенко Евгений Алексеевич', 4, 1, 9, NULL, NULL, NULL, NULL, NULL, NULL),
(313, NULL, NULL, 'Разработка программы \"Информационно-аналитическая платформа по решению транспортно-логистической задачи”', 15, 'Создание программного решения для поддержки процесса распределения сырья и товаров для нормированного снабжения населения.', 'Информационно-аналитическая платформа предназначена для решения транспортно-логистической задачи, целью которой является расчет наиболее оптимальных маршрутов доставки (поставки) сырья и товаров (далее – грузы) для нормированного снабжения населения (далее – НСН) продовольственными и непродовольственными товарами в период мобилизации, период действия военного положения и военное время. Расчет стоимости перевозок (с учетом их объемов и периодичности доставки) с точки зрения минимизации между хозяйствующими субъектами, расположенными на территории Иркутской области (от поставщика до получателя) в объемах необходимой потребности для обеспечения бесперебойного НСН товарами первой необходимости (по заданной номенклатуре товаров) при минимально возможных сроках доставки и затратах на перевозку. Получать возможность анализа ритмичности поставок, наличия минимально необходимого остатка товаров, каждого вида, у конечного получателя и оперативное перераспределение поставок при возникновении угрозы снижения минимально необходимого остатка товаров для обеспечения бесперебойного НСН товарами первой необходимости (по заданной номенклатуре товаров), а также возможностей и особенностей транспортной инфраструктуры Иркутской области.', 3, '2023-02-06', '2023-06-25', '', 'Администрация Иркутской области', NULL, 'Программа должна обеспечивать возможность выполнения перечисленных ниже функций.\n- Разделение прав пользователей, использующих программу:\n- Возможность корректировки баз данных с условно постоянной информацией (сведения о субъектах региона, транспортной доступности, нормах обеспечения регионов).\n- Возможность диалогового ввода и корректировки исходных данных для расчета планов поставок.\n- Возможность расчета оптимальных маршрутов доставки грузов с точки зрения минимизации стоимости перевозок (с учетом их объемов и периодичности доставки) между хозяйствующими субъектами, расположенными на территории Иркутской области, а также возможностей и особенностей транспортной инфраструктуры Иркутской области.\n- Возможность получать результаты расчетов, оформленными в соответствии с существующими формами отчетов.\n- Обеспечение хранения исходных данных для расчетов и результатов расчетов в базе данных.\n', 'Знания: принципы работы защищенного автономного приложения, основы программирования, нотация Чена, стандарты описания UML, IDEF0, математические модели транспортных задач.\nУмения: читать и составлять техническую документацию с использованием стандартов UML, IDEF0, моделирование данных, составление SQL-запросов, \nНавыки: проведения предпроектного обследования, работа с СУБД PostgreSQL, администрирование Windows,  Linux, работа с пакетами программированияl\n', 'Бахвалов Сергей Владимирович , Маланова Татьяна Валерьевна', 4, 1, 10, NULL, NULL, NULL, NULL, NULL, NULL),
(314, NULL, NULL, 'Разработка антивирусного программного обеспечения', 15, 'Разработка методики сравнительного тестирования антивирусных продуктов и разработке примитивного антивирусного программного обеспечения (антивирусного сканера).', 'Знакомство со средой разработки и работа над проектом.\nВ проекте мы познакомимся с использованием электронных ресурсов компании Microsoft (выбор версии Visual Studio, создание учетной записи, работа с установочным файлом, запустить программы). \n Начало работы над проектом (запустить Visual Studio), выбрать тип проекта Windows Form С#.\n Размещение элементов форм, указать необходимые свойства.\n Знакомство с сигнатурами, анализ вирусных сигнатур (работа над созданием таблиц в которой содержатся: название вируса, вирусные сигнатуры, краткое описание вируса).\n Написание программного кода. Загрузка вирусных сигнатур в коллекцию, обработка событий.\n', 2, '2023-02-06', '2023-06-25', '', 'Курсы для специалистов ИБ «Доктор Веб»\nhttps://training.drweb.ru/courses/admins/\n\nОбучение KasperskyOS\nhttps://os.kaspersky.ru/development/education\n', NULL, 'Написание программного кода. Загрузка вирусных сигнатур в коллекцию, обработка событий.\nДальнейшая работа (более глубокая и детальная) над проектом предполагает  разработку компонентного базового программно-инструментального средства для построения антивирусных программных комплексов.\n', 'Знания: Виды уязвимостей информационной системы, согласно ГОСТ Р 56546-2015 (защита информации, уязвимости информационных систем).\nУмения: Возможность проводить работы с исследованиями (существующими методиками), формирование списка критериев, выбор продуктов тестирования, проведение эксперимента,  проверке  эффективности ПО в реальных условиях.\nНавыки: Работа с кодом вируса (или его часть), влияние на работу других программ. Работа с загрузочной записью (boot record) и системным загрузчиком (master boot record), драйверами.\n', 'Маринов Александр Андреевич', 4, 1, 11, NULL, NULL, NULL, NULL, NULL, NULL),
(315, NULL, NULL, 'Поиск применения камеры с аппаратным распознавание государственных регистрационных номеров', 15, 'Создание комплексного решения для поддержки и реализации проекта дополнительного обучения «Академия ИТ»', 'В распоряжении ООО «ИНК» имеется несколько десятков Ethernet камер с аппаратный распознавание номер машин, данные камеры сняты с автоматических шлагбаумов. В результате реализации проекта необходимо определить места установки камер на объектах ООО «ИНК» и как использовать данные получаемые с камер для процессов цифровизации перемещения автотранспортных средств', 2, '2023-02-06', '2023-06-25', '', 'ООО «ИНК»', NULL, 'Определение мест установки камер, определение параметров необходимой инструкторы (питание, канал связи), реализации программного обеспечения для взаимодействия с камерами', 'Знания: принципы работы с Ethernet камерами, принципы запроса информации с камер, маршрутизация данных с использование различных протоколов.\nУмения: читать и составлять техническую документацию с использованием стандартов UML, работать с get и post запросами, работа с API и базами данных\nНавыки: работа  администрирование Linux, работа с IDE, разработка back и front\n', 'Кононенко Роман Владимирович ', 4, 1, 13, NULL, NULL, NULL, NULL, NULL, NULL),
(316, NULL, NULL, 'Разработка системы учета посещения занятий студентами', 15, 'Разработка и интеграция автоматической системы учета посещаемости студентами занятий', 'Разработка системы учета посещения занятий студентами, способной в автоматическом режиме согласно существующей БД используя карту-пропуск студента идентифицировать ФИО студента время входа и время выхода студента из аудитории, сопоставлять расписание с ФИО студента', 3, '2023-02-06', '2023-06-25', '', 'Дирекция института ИТиАД', NULL, 'Автономное устройство считывание карт-пропусков в возможность подключения к локальной сети ИРНИТУ и работой с сервером.', 'Знания: принципы работы с модулями RFID, Wi-FI, Bluetooth, принципы запроса информации с сервера, маршрутизация данных с использование различных протоколов.\nУмения: читать и составлять техническую документацию, работать с get и post запросами, работа с API и базами данных, работа с Arduino\nНавыки: работа администрирование Linux, работа с IDE, разработка принципиальной схемы устройства, пайка, коркусирование устройства\n', 'Кононенко Роман Владимирович ', 4, 1, 14, NULL, NULL, NULL, NULL, NULL, NULL),
(317, NULL, NULL, 'Система трекинга руководства компаний на удаленных промышленных объектах', 15, 'Создание программно-аппаратного комплекса для отслеживания положения людей (10-15 человек) на удаленных промышленных объектах.', 'При посещении удаленных промышленных объектах (на объектах отсутствует покрытие сети сотовой связи) руководящим составом компании, необходимо отслеживать положение каждого участника группы на объекте. Так как между объектами группа перемещается на вертолете, то время сбора всех участников группы возле вертолета является критически важным, так как вертолет следует согласно полетному расписанию. Знание местонахождения каждого участника группы на промышленном объекте позволяет сопровождающему группы оперативно находить их на объекте', 2, '2023-02-06', '2023-06-25', '', 'ООО «ИНК»', NULL, 'Носимое устройства трекинга и мобильный пост отображение положения трекеров.', 'Знания: GPS, Bluetooth, Wi-Fi, LoRa, построение беспроводной сети передачи данных\nУмения: читать и составлять техническую документацию, проектирование и разработка печатных плат, разработка Android приложений.\nНавыки: работа администрирование Android, работа с IDE, программирование микроконтроллеров\n', 'Кононенко Роман Владимирович ', 4, 1, 15, NULL, NULL, NULL, NULL, NULL, NULL),
(318, NULL, NULL, 'Система, уменьшая очереди на заправочных пунктах ООО \"ИНК\"', 15, 'Создание цифрового продукта, который позволит уменьшит очереди на заправочных пунктах ООО «ИНК»', 'В результате не рационального распределения автотранспортных средств по времени заправки, на заправочных пунктах возникают очереди на заправку или отсутствие машин для заправки. Необходим спроектировать и создать цифровой продукт который позволит избежать пиков заправки и выровнять в течении дня нагрузку на заправочный пункт.', 2, '2023-02-06', '2023-06-25', '', 'ООО «ИНК»', NULL, 'Прототип программного продукта для выравнивания загрузки заправочного пункта.', 'Знания: GPS, Bluetooth, Wi-Fi, LoRa, построение беспроводной сети передачи данных\nУмения: читать и составлять техническую документацию, проектирование и разработка печатных плат, разработка Android приложений.\nНавыки: работа администрирование Android, работа с IDE, программирование микроконтроллеров\n', 'Кононенко Роман Владимирович ', 4, 1, 16, NULL, NULL, NULL, NULL, NULL, NULL),
(319, NULL, '2023-03-29 09:52:00', 'Экосистема для клиентов IT-компании', 15, 'Разработка цифрового сервиса для клиентов IT-компании', 'Требуется создать единый цифровой сервис – экосистему - для взаимодействия клиентов с IT-компанией, с помощью которого будут реализованы внешний документооборот, учет наработки, доп. продажи, интеграция сторонних сервисов и систем', 3, '2023-02-06', '2023-06-25', NULL, 'Институт информационных технологий и анализа данных', NULL, 'Личный кабинет клиента на цифровом сервисе, SPA приложение', 'Знания: Языки программирования JavaScript, HTML, CSS, PHP \r\nУмения: Разработка fronend и backend \r\nНавыки: Тестирование цифрового продукта , его отладка и запуск', 'Бакшеева Елизавета Николаевна', 4, 1, 17, NULL, NULL, NULL, NULL, NULL, NULL),
(320, NULL, '2023-03-29 09:52:26', 'Автоматизация и цифровизация процесса учета выпущенной продукции мукомольного производства', 15, 'Подсчет количества выбоя муки и цифровизация процесса складского учета', 'Требуется автоматизировать процессы взвешивания и распределения сырья (зерно) на мукомольном производстве в г.Улан-Удэ (Бурятия), а также систему их контроля. Интегрировать систему складского учета с ПО установленного оборудования. С помощью цифровой технологии – интернет вещей – оптимизировать указанные процессы.', 3, '2023-02-06', '2023-06-25', NULL, 'Институт информационных технологий и анализа данных', NULL, 'ПО для подсчета количества выбоя муки', 'Знания: языки программирования JavaScript, HTML, CSS, PHP \r\nУмения: Разработка fronend и backend \r\nНавыки: Тестирование программного продукта , его отладка и запуск', 'Бакшеева Елизавета Николаевна', 4, 1, 18, NULL, NULL, NULL, NULL, NULL, NULL),
(321, NULL, NULL, 'Система учета активности абитуриентов ИРНИТУ', 15, 'Разработка программы сопровождения профориентационных активностей  школьников до потенциального абитуриента ИРНИТУ', 'Разработка БД школьников для приемной кампании ИРНИТУ получает и видит их выбор направлений подготовки по заинтересованности и активности участия. \n\nДанные на вход:\n1. При регистрации каждый школьник записывает:\n- ФИО;\n- контактные данные;\n- образовательную организацию;\n- класс;\n- школьник выбирает мероприятия/курсы/программы.\n\nНеобходимо получить на выходе:\n- Личный кабинет у каждого школьника;\n- Списки школьников, зарегистрированных на мероприятия/курсы/программы с возможностью выгрузки;\n- Список школьников, окончившие курсы/программы, посетившие мероприятия по направлениям подготовки с индивидуальными бонусами с возможностью выгрузки;\n- Рейтинг школьников с их бонусами по направлениям подготовки;\n- Создание/добавление новых мероприятий в течение года;\n- Школьник и администратор в любой момент могут видеть список пройденных мероприятий/курсов/программ с полученными бонусами;\n- Афиша предстоящих мероприятий для школьников в хронологии с бонусами за их посещение;\n- Афиша предстоящих мероприятий для школьников по форматам работы (например, курсы, день открытых дверей, профессиональные пробы, летние школы)  и направлениям подготовки (траекториям) с бонусами за их посещение;\n- постоянно видимые ссылки на сайт ИРНИТУ, группу VK, телеграмм чат-бот, техподдержку.\n', 3, '2023-02-06', '2023-06-25', '', 'УМОУ и РОП, ЦПК', NULL, 'Программа - web-сайт и БД, в которой школьники регистрируются на разные профориентационные активности и программы довузовской подготовки ИРНИТУ и \"зарабатывают\" активностью бонусы. Бонусы переводятся в баллы индивидуальных достижений для поступления в наш университет по программе \"Успешный абитуриент\". ', '', 'Шведина Светлана Александровна', 4, 1, 19, NULL, NULL, NULL, NULL, NULL, NULL),
(322, NULL, NULL, 'Электронный учебный журнал образовательных курсов программы «Сетевой лицей ИРНИТУ', 15, 'Разработка программы сопровождения учебного процесса профильной сетевой образовательной программы ИРНИТУ и партнерских школ «Сетевой лицей ИРНИТУ»', 'Web-сайт и БД, в которой администратор вводит данные о школьниках и преподавателях с их предметами. У преподавателей есть доступ к журналам с учебными группами, в которых они имеют возможность проставлять посещение учеников и оценки за работу на занятии.\nАдминистратор должен иметь возможность получения журнала посещаемости по каждой школе по-отдельности.\nДанные на вход\nАдминистратор изначально заполняет данные по школьникам и преподавателям, в соответствии с таблицами:\nid ФИО Школа Класс Предмет по выбору №1 Предмет по выбору №2\n           \n \nid ФИО Наименование предмета Уровень Время Количество (человек в классе)\n           \nВыходные документы\nРешение должно иметь возможность формирования отчёта в приведённом виде:\nid ФИО учеников Наименование предмета Посещение/ Оценка Дата\n         \nТакже формирование ведомости, по успеваемости школьников, просмотр домашних заданий по нажатию на кнопку «Просмотреть ДЗ» с возможностью добавлять темы занятий и прикрепление файлов (ссылок) на материалы занятий.\nРаботать в программе могут преподаватели и администратор.\n', 3, '2023-02-06', '2023-06-25', '', 'УМОУ и РОП, Центр довузовской подготовки и профориентационной работы', NULL, 'Произвести разработку веб-сайта и БД для учета посещаемости школьников факультативных занятий по программе «Сетевой лицей ИРНИТУ», с возможностью получения отчётов посещаемости и успеваемости школьников по каждой школе и классу.', '', 'Шведина Светлана Александровна', 4, 1, 20, NULL, NULL, NULL, NULL, NULL, NULL),
(323, NULL, NULL, 'Система техподдержки сервисов ИРНИТУ', 15, 'Разработка модулей обработки заявок на работы специалистов по вопросам электропитания, тепло и водоснабжения на основе информационной системы «Кампус» по адресу https://int.istu.edu/', 'Разработка инструмента для формирования, обработки и контроля исполнения  заявок на работы специалистов по вопросам электропитания, тепло и водоснабжения. \n\nЗаказчик – все сотрудники ИРНИТУ, имеющие право на формирование  заявок для решения вопросов административно-хозяйственного характера:\nИсполнители:\nСлужба главного инженера ИРНИТУ\nСлужба главного энергетика ИРНИТУ\n', 3, '2023-02-06', '2023-06-25', '', 'Служба главного инженера, Служба главного энергетика ИРНИТУ', NULL, 'Программа – подразделы модуля информационной системы «Кампус» по формированию заявок.', 'Знания: язык программирования PHP\nУмения: Формирование модуля на платформе «Битрикс»\nНавыки: \n', 'Жуков А.В.', 4, 1, 21, NULL, NULL, NULL, NULL, NULL, NULL),
(324, NULL, NULL, 'Разработка веб форм для Центра Карьеры ', 15, 'Повышение управляемости и контроля изменений ИТ-инфраструктуры ИРНИТУ', 'Использование единой системы баз данных автоматизированной информационной системы ИРНИТУ позволит органично встроить информационную систему «Центра карьеры ИРНИТУ» в существующий комплекс автоматизированных систем подразделений и автоматизирует изменения взаимосвязанных используемых полей и таблиц. \nЧто в свою очередь позволит автоматически контролировать:  \n• Учет и изменение статуса заключенного договора с внешней организацией, обеспечивающей прохождение производственной и преддипломной практики; \n• прикрепления к нему перечня студентов \n• прикрепления к нему преподавателя – руководителя практики; \n• учет учебной нагрузки на преподавателя по руководству производственной/преддипломной практики;\nдополнение рейтинга студента параметрами прохождения производственной и преддипломной практики.\n', 3, '2023-02-06', '2023-06-25', '', 'Управление информатизации ИРНИТУ', NULL, 'Автоматический  контроль:  \n• Учета и изменения статуса заключенного договора с внешней организацией, обеспечивающей прохождение производственной и преддипломной практики; \n• прикрепления к нему перечня студентов \n• прикрепления к нему преподавателя – руководителя практики; \n• учет учебной нагрузки на преподавателя по руководству производственной/преддипломной практики;\n', 'Повышение уровня практических знаний по направлению «Вычислительные машины, комплексы, системы и сети».', 'Аношко Алексей Федорович', 4, 1, 22, NULL, NULL, NULL, NULL, NULL, NULL),
(325, NULL, NULL, 'Академия IT', 100, 'Обеспечить компании высококвалифицированными молодыми кадрами ИТ-направлений за счёт развития уникальных компетенций в соответствии с потребностью бизнеса в отрасли металлургии и энергетики', '«Академия IT» нацелена на подготовку IT-специалистов для энергетических и металлургических предприятий РУСАЛ и En+Group. Программа предполагает три этапа по проектным блокам Web, 1C, информационная безопасность или сетевая инфраструктура.\n\nВ первом туре (март-июнь) второкурсники узнают о деятельности компании, прослушают курс лекций, посетят мастер-классы, решат реальные производственные задачи. Студенты познакомятся с наставниками и менторами, которые в будущем могут стать коллегами.\n\nВо втором этапе политеховцам предлагается заключить целевой договор с ежемесячной выплатой стипендии в размере пяти тысяч рублей. В течение двух месяцев студентам предстоит пройти производственную практику на базе предприятий.\n\nВ финальном туре эксперты оценят деятельность участников и отберут 30 четверокурсников. Студенты разработают проект, который будет засчитан как выпускная квалификационная работа. Кроме того, студенты могут совмещать учёбу и работу в компании.\n\nПолитеховцы, успешно окончившие курсы, получат сертификат и удостоверение международного образца. Компания гарантирует официальное трудоустройство в подразделения РУСАЛ и En+Group, достойную заработную плату и карьерный рост.', 2, '2023-02-06', '2023-06-25', '', 'En+ digital', NULL, ' ', ' ', 'Говорков А.С.', 4, 1, 23, 0, NULL, NULL, NULL, NULL, NULL),
(326, NULL, NULL, 'Формула студент / развитие кампуса университета', 100, 'Возможность реализации тем проектов, предложенных студентами в инициативном порядке в рамках проектной форсайт-игры', 'Центр проектного обучения проводит проектную форсайт-игру в целях выявить инициативные темы проектов студентов или тематики, предложенные наставниками, и вовлечь активных студентов и наставников в их реализацию в рамках «Проектной деятельности» в 2022 - 2023 учебном году. Реализация проекта позволит поддержать студенческие проектные инициативы и активных студентов, а также способствует развитию образовательных форматов, направленных преимущественно на формирование soft skills у студентов в проектной деятельности.\nКонтакт для связи по проекту https://t.me/tuymada', 2, '2023-02-06', '2023-06-25', '', 'Центр проектного обучения', NULL, '', '', 'Бережных Мария Валерьевна', 4, 1, 301, 0, NULL, NULL, NULL, NULL, NULL),
(327, NULL, NULL, 'Смарт-Форма', 100, 'Возможность реализации тем проектов, предложенных студентами в инициативном порядке в рамках проектной форсайт-игры', 'Центр проектного обучения проводит проектную форсайт-игру в целях выявить инициативные темы проектов студентов или тематики, предложенные наставниками, и вовлечь активных студентов и наставников в их реализацию в рамках «Проектной деятельности» в 2022 - 2023 учебном году. Реализация проекта позволит поддержать студенческие проектные инициативы и активных студентов, а также способствует развитию образовательных форматов, направленных преимущественно на формирование soft skills у студентов в проектной деятельности.\nКонтакт для связи по проекту https://t.me/tuymada', 2, '2023-02-06', '2023-06-25', '', 'Центр проектного обучения', NULL, '', '', 'Кузьмина Ольга Ивановна', 4, 1, 302, 0, NULL, NULL, NULL, NULL, NULL),
(328, NULL, NULL, 'Проектирование измельчителя пластика/Благоустройство городов и поселений', 100, 'Возможность реализации тем проектов, предложенных студентами в инициативном порядке в рамках проектной форсайт-игры', 'Центр проектного обучения проводит проектную форсайт-игру в целях выявить инициативные темы проектов студентов или тематики, предложенные наставниками, и вовлечь активных студентов и наставников в их реализацию в рамках «Проектной деятельности» в 2022 - 2023 учебном году. Реализация проекта позволит поддержать студенческие проектные инициативы и активных студентов, а также способствует развитию образовательных форматов, направленных преимущественно на формирование soft skills у студентов в проектной деятельности.\nКонтакт для связи по проекту https://t.me/tuymada', 2, '2023-02-06', '2023-06-25', '', 'Центр проектного обучения', NULL, '', '', 'Уразова Нина Геннадьевна', 4, 1, 303, 0, NULL, NULL, NULL, NULL, NULL),
(329, NULL, NULL, 'Разработка проекта мониторинга транспортного поведения населения на примере г. Иркутска', 15, 'Повышение качества транспортного обслуживания населения на основе учета количественных и качественных параметров транспортного поведения населения', 'Транспортное поведение — это совокупность сценариев подвижности, характеризующихся способом передвижения и величинами, которые могут быть измерены количественно: длительность поездки (корреспонденции), пройденное расстояние и др. Изменение транспортного поведения, свойственного городским сообществам, происходит под влиянием многих факторов: демографических сдвигов, смены экономических условий, эволюции городской формы и транспортного обеспечения.\nУдовлетворить спрос на перемещение от одной точки города до другой можно с помощью личного автотранспорта, общественного транспорта, велосипеда или пешком. Однако при значительном расстоянии между пунктом возникновения потребности в перемещении и пунктом назначения наибольшая часть потребности будет реализована с помощью транспорта\n', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Рекомендации для управления и методологического сопровождения процессов администрирования транспортного комплекса для муниципальных властей', 'Знания характеристик транспортного поведения населения г. Иркутска, инструментария мониторинга транспортного поведения населения. Умения анализировать количественные параметры транспортного поведения населения. Навыки обработки результатов исследования', 'Бутузова А.Б.', 4, 1, 25, NULL, NULL, NULL, NULL, NULL, NULL),
(330, NULL, NULL, 'Разработка проекта введения на улично-дорожной сети приоритетного движения городского маршрутного пассажирского транспорта общего пользования на примере г. Иркутска', 15, 'Повышение качества транспортных услуг для населения города за счет приоритетного комплексного развития транспорта общего пользования (снижение затрат времени на совершение ежедневных регулярных поездок пассажиров маршрутного транспорта за счет предоставления ему приоритета при движении по улично-дорожной сети и стимулирования отказа от использования индивидуальных автомобилей)', 'Высокий в настоящее время и продолжающий увеличиваться уровень автомобилизации (количество автомобилей на 1 тысячу жителей) приводит к возникновению транспортных проблем для жителей и гостей крупных городов. Это прежде всего возникновение заторов (пробок), что приводит к увеличению времени и затрат на поездки, транспортной усталости, снижает безопасность дорожного движения, обуславливает повышенные выбросы вредных веществ. Это усугубляется еще и отставанием развития транспортной инфраструктуры: улицы, дороги, остановочные пункты, транспортно-пересадочные узлы и т.п. В этих условиях в крупных городах необходимо разработать мероприятия по решению вышеуказанных проблем. Среди большого комплекса мер важнейшее значение будет иметь предоставление приоритета на улицах городов для маршрутного пассажирского транспорта общего пользования. Очень важно проводить это в сочетании с политикой стимулирования отказа от использования индивидуального транспорта для ежедневных поездок прежде всего по трудовым целям', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Предложения для городских властей по введению приоритетного движения на улично-дорожной сети для маршрутного пассажирского транспорта общего пользования, основанные на исследовании характеристик транспортных и пассажирских потоков', 'Знания: инструменты поиска информации по теме исследования; основные требования к представлению результатов проекта; особенности основных и смежных ролевых позиций.\nУмения: формулировать цели и задачи исследования; планировать и организовывать свою деятельность на основе приоритетов и поставленных целей; использовать инструменты поиска информации; выделить из массива информации ключевые моменты; решать задачи в соответствии с ролевой позицией, переключиться на свою смежную ролевую позицию.\nНавыки: формулирования запроса на поиск новых знаний и информации; анализа информации с целью выделения требуемого знания и формирования комплексного понимания предмета изучения; выполнения системного анализа информации по теме проекта, выделения «дефицитов» знаний и формулирования запроса на поиск новой информации; презентации результатов проекта; самоанализа и оценки личного вклада в достигнутые результаты; социального взаимодействия как с членами команды, так и с внешними стейкхолдерами\n', 'Колганов С.В.', 4, 1, 26, NULL, NULL, NULL, NULL, NULL, NULL),
(331, NULL, NULL, 'Разработка цифровых моделей транспортной инфраструктуры города и агломерации', 15, 'Повышение качества транспортного планирования городских агломераций на основе разработки цифровых моделей транспортной инфраструктуры', 'Одной из основных проблем формирования устойчивых городов и их агломераций является отсутствие качественного транспортного планирования в связке с территориальным планированием. В связи с этим необходимо решение ряда комплексных задач, связанных с освоением современных инструментов в области транспортного планирования и технологий учета влияния характеристик использования городских территорий на формирование транспортного спроса. Рассматриваемый проект на целен на разработку подходов по повышению скорости и качества задач интегрированного территориального и транспортного планирования с применением транспортного моделирования', 2, '2023-02-06', '2023-06-25', '', 'Разработка транспортной модели Иркутска и Иркутской агломерации (хоз. договорные работы в области транспортного планирования и организации дорожного движения)', NULL, 'Предложения по развитию подходов к оценке транспортного моделирования и оценке транспортного спроса', 'Знания: инструменты поиска информации по теме исследования; основные требования к представлению результатов проекта; особенности основных и смежных ролевых позиций.\nУмения: формулировать цели и задачи исследования; планировать и организовывать свою деятельность на основе приоритетов и поставленных целей; использовать инструменты поиска информации; выделить из массива информации ключевые моменты; решать задачи в соответствии с ролевой позицией, переключиться на свою смежную ролевую позицию.\nНавыки: формулирования запроса на поиск новых знаний и информации; анализа информации с целью выделения требуемого знания и формирования комплексного понимания предмета изучения; выполнения системного анализа информации по теме проекта, выделения «дефицитов» знаний и формулирования запроса на поиск новой информации; презентации результатов проекта; самоанализа и оценки личного вклада в достигнутые результаты; социального взаимодействия как с членами команды, так и с внешними стейкхолдерами\n', 'Левашев А.Г.', 4, 1, 27, NULL, NULL, NULL, NULL, NULL, NULL),
(332, NULL, NULL, 'Разработка проекта совершенствования методики расчета цены муниципального контракта при осуществлении закупок в сфере регулярных перевозок пассажиров на примере г. Иркутска', 15, 'Совершенствование методики расчета начальной (максимальной) цены контракта (НМЦК), а также цены контракта, заключаемого с единственным поставщиком (подрядчиком, исполнителем), для закупок в сфере регулярных перевозок пассажиров на основе учета технико-эксплуатационных параметров маршрутов перевозчика, а также создание соответствующего программного продукта', 'Начальная (максимальная) цена контракта (НМЦК) — это предельное значение цены, которое указывается в извещении и документации о проведении закупки с приглашением принять в ней участие. Заказчик обязан в полной мере обосновать цену, чтобы провести закупку. Менять условия уже заключенного контракта в большинстве случаев нельзя. Но очень часто при проведении расчета НМЦК возникают проблемы. Первое, цена может быть занижена. Это может привести к тому, что процедура закупки просто не состоится, так как никто не будет заключать контракт себе в убыток. Если такой контракт все-таки будет заключен, то это будет недобросовестный перевозчик, который не выполнит условия контракта по заявленной цене, либо будет занижено качество поставляемого товара, или предоставляемых услуг. Второе, может возникнуть ситуация, когда НМЦК, наоборот, будет завышена. Это в свою очередь приведет к неэффективному расходу средств бюджета. Третье, стоимость устанавливается некорректно, из-за технических проблем (ошибок в расчетах; неправильном использовании положений методических рекомендаций; ошибок при анализе рынка, когда он проанализирован не полностью; использовании некорректных исходных данных)', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Отчет и программный продукт с исходными данными по регулярным маршрутам для муниципальных властей по расчету начальной (максимальной) цены контракта, а также цены контракта, заключаемого с единственным поставщиком, для закупок в сфере регулярных перевозок пассажиров', 'Знания: характеристик подвижного состава и методики расчета и технико-эксплуатационных показателей на регулярных маршрутах.\nНавыки: проведения обследования пассажиропотоков и расчёта технико-эксплуатационных показателей на регулярных маршрутах; владения методикой обработки результатов исследования; составления базы данных по результатам обследования пассажиропотоков и разработки программного продукт; владения методикой расчёта НМЦК\n', 'Яценко С.А.', 4, 1, 28, NULL, NULL, NULL, NULL, NULL, NULL),
(333, NULL, NULL, 'Повышение углеродной нейтральности автомобилей с дизельными двигателями и их эксплуатационные свойства', 15, 'Снижение выбросов вредных веществ и диоксида углерода с выбросами автомобильных двигателей', 'Снижение выбросов вредных веществ и диоксида углерода с отработавшими газами является серьезной проблемой современности. Переход на электротранспорт в целом в настоящий момент не решает проблему снижения выбросов диоксида углерода, т.к. многие станции по выработке электроэнергии являются тепловыми, работающими на углеводородном топливе или каменном угле. Одним из путей снижения техногенной нагрузки в переходном периоде является применение возобновляемых топлив, которые могут быть растительного происхождения, а также являются продуктом утилизации бытовых отходов и др. При этом углеродный баланс нарушается меньше, а экологическая составляющая повышается.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Топливные композиции (состав возобновляемых топлив); экспериментальные данные в виде отчета и статьи с полученными результатами ', 'Знания: методики выполнения расчетов двигателей внутреннего сгорания; влияния рабочих процессов на динамику двигателя и на технико-экономические показатели работы\nУмения: проводить испытания двигателей и автомобилей; проводить экспериментальные исследования\nНавыки: расчета параметров технического состояния транспортных средств и сравнение их с требованиями нормативных правовых документов в отношении технического состояния транспортных средств; определения качества технологических жидкостей и эксплуатационных материалов\n', 'Кривцов Сергей Николаевич', 4, 1, 29, NULL, NULL, NULL, NULL, NULL, NULL),
(334, NULL, NULL, 'Разработка конструкции стенда для исследования характеристик шин в дорожных условиях', 15, 'Разработка конструкции стенда для исследования характеристик шин в дорожных условиях для создания алгоритма управления антиблокировочной системой (АБС) колёсных транспортных средств (КТС).', 'Безопасность КТС во многом определяется сложными электронными и мехатронными системами, которые широко используются в современных автомобилях. Одной из таких систем является АБС, принцип работы которой построен на поддержании допустимого скольжения колеса в области максимального коэффициента сцепления шины автомобильного колеса с поверхностью дороги без его снижения в область неустойчивости КТС. Изменение коэффициента сцепления шины с опорной поверхностью от изменения проскальзывания колеса является основной зависимостью, в соответствии с которой осуществляется управления АБС. Однако, эта зависимость в значительной степени меняется от типа опорной поверхности, формы протектора шины, её материала и т.п. Применение аналитических методов для синтеза алгоритма управления АБС весьма проблематично, в связи с тем, что объект управления в точке экстремума теряет устойчивость, таким образом правее максимума управление в обычном смысле становится невозможным. В процессе движения КТС невозможно точно определить линейную скорость его кузова, а соответственно и проскальзывание колёс, что затрудняет определение коэффициента сцепления. Если довести колесо до момента предблокирования, возникнет существенное снижение бокового коэффициента сцепления, и, как следствие, потеря устойчивости КТС. Особенно это опасно на покрытии с различным коэффициентом сцепления по боковым колёсам КТС. Всё это приводит к тому, что возникает необходимость разработки алгоритма распознавания типа опорной поверхности под каждым колесом КТС и его управления. Компания Bosch, являющаяся лидером в разработке мехатронных систем, ведут работы по созданию алгоритма действий по калибровке систем АБС без изучения непосредственно взаимодействия шины, используя какие-то пороговые коэффициенты. Отечественными компаниями, такими, как Группа ГАЗ, АвтоВАЗ, и научными организациями ведутся работы по исследовании процесса взаимодействия автомобильного колеса с эластичной шиной на различных опорных поверхностях (сухой асфальт, мокрый, лед, снег и т.п). Результаты этих исследований позволят построить математический аппарат алгоритма адаптивного управления АБС с поддержанием удовлетворительной управляемости КТС. Для решения этой задачи необходимо разработать стенд для исследования характеристик шин в дорожных условиях.', 2, '2023-02-06', '2023-06-25', '', 'Ориентировочно грант РНФ, заявка № 22-79-00166, зарегистрирована: 09.03.2022 г.; электронный документ подписан: 10.03.2022 г. Совместно с кафедрой «Автомобили и тракторы» Института Транспортных систем, НГТУ им. Р.Е. Алексеева', NULL, 'Комплект конструкторской документации для создания опытного образца стенда для исследования характеристик шин в дорожных условиях', 'Знания: устройства и принципа работы современных мехатронных систем активной безопасности КТС; устройства и принципов работы дополнительного технологического и испытательного оборудования;\nрациональных методов эффективной эксплуатации, а также технологических процессов поддержания и восстановления работоспособности подвижного состава автотранспортных средств, их агрегатов, механизмов, узлов.\nУмения: разрабатывать структурные и кинематические схемы систем технологического и испытательного оборудования; проводить диагностирование и контроль технического состояния мехатронных систем подвижного состава автотранспортных средств.\nНавыки: проведения испытаний электронных систем КТС; проведения контроля технического состояния и диагностики подвижного состава автотранспортных средств, их агрегатов, механизмов, узлов.\n', 'Яньков Олег Сергеевич', 4, 1, 30, NULL, NULL, NULL, NULL, NULL, NULL),
(335, NULL, NULL, 'Разработка программного комплекса для управления диагностическим гибридным стендом с беговыми барабанами', 15, 'Разработка программного комплекса (ПК) для регистрации, контроля, обработки и сохранения диагностической информации, полученной при испытании колёсных транспортных средств(КТС) на стенде с беговыми барабанами, а также для управления электронными системами стенда.', 'В настоящее время диагностику и контроль технического состояния как традиционных, так и беспилотных КТС, в том числе с электрическими и гибридными силовыми установками, с автоматизированными агрегатами и интеллектуальными системами осуществляют при помощи сканеров и, как правило, в дорожных условиях. Однако, исследования, проведённые ранее, убедительно показывает наличие системных проблем при определении их технического состояния. Обусловлено это во многом тем, что уровень конструктивной сложности традиционных и беспилотных КТС непрерывно растет. При этом требования к безопасности КТС постоянно ужесточаются. Поэтому качество контроля технического состояния КТС во многом определяет безопасность автомобильного транспорта. Для контроля технического состояния КТС давно уже недостаточно применения электронных сканеров, поскольку они не дают полного объема необходимой информации: о безопасности, о техническом состоянии их агрегатов и систем, о мощностных характеристиках, о техническом состоянии ходовой части и подвески, а также об эффективности работы их интеллектуальных систем.\nДля эффективного контроля современных КТС требуется наукоемкое оборудование, способное обеспечивать контролируемым КТС заданные тестовые режимы – «разгон», «торможение», «боковой занос», «движение под нагрузкой» и пр. Использовать для этих целей современные стенды нет возможности по причине того, что они морально устарели, либо имеют очень высокую стоимость. К тому же практически все современные стенды являются зарубежными. Существующие стенды для контроля КТС имеют ограниченный функционал. Для качественного контроля КТС измерение силовых и кинематических параметров необходимо проводить индивидуально на каждом колесе колёсных транспортных средств с достаточной точностью. Для этого необходимо создать корректные тестовые воздействия, при которых колёсное транспортное средство на стенде будет функционировать как в реальных дорожных условиях. Для решения вышеперечисленных проблем на кафедре Автомобильного транспорта был разработан и изготовлен опытный образец стенда, представляющий собой диагностическое стендовое оборудование, которое способно реализовать высокоэффективные методы контроля технического состояния современных КТС. Опытный образец имеет сложные механические, электрические и пневматические системы, электронные системы измерения контролируемых параметров и системы управления стендом. Функционирование стенда сопровождается большим количеством контролируемых, измеряемых и управляющих параметров процесса испытания автомобиля, которые должны быть обработаны одновременно. Поэтому для его полноценной эксплуатации остро стоит вопрос о разработке ПК, способного управлять стендом, а также регистрировать, контролировать, обрабатывать и сохранять диагностическую и контрольную информацию, полученную при испытании КТС.\n', 2, '2023-02-06', '2023-06-25', '', 'Ориентировочно грант РНФ, заявка № 22-79-00166, зарегистрирована: 09.03.2022 г.; электронный документ подписан: 10.03.2022 г.', NULL, 'Комплекс программ (ПК), входящий в состав диагностического оборудования.', 'Знания: устройства и принципа работы средств технического диагностирования; устройства и принципов работы дополнительного технологического оборудования; рациональных методов эффективной эксплуатации, а также технологических процессов поддержания и восстановления работоспособности подвижного состава автотранспортных средств, их агрегатов, механизмов, узлов.\nУмения: разрабатывать структурные, электрические и кинематические схемы систем технологического оборудования; проводить диагностирование и контроль технического состояния подвижного состава автотранспортных средств.\nНавыки: проведения испытаний электронных систем технологического оборудования; проведения контроля технического состояния и диагностики подвижного состава автотранспортных средств, их агрегатов, механизмов, узлов.\n', 'Яньков Олег Сергеевич', 4, 1, 31, NULL, NULL, NULL, NULL, NULL, NULL),
(336, NULL, NULL, 'Разработка стенда и методики для исследования смазывающих свойств нефтепродуктов', 15, 'Изучение смазывающих свойств нефтепродуктов и разработка методики исследования смазывающих свойств нефтепродуктов', 'Все знают, что смазочные материалы изменяют свои характеристики в процессе работы, так как оно подвергается высокому давлению, температуре и многим другим факторам. На сегодняшний день производство смазочных материалов происходит одновременно с совершенствованием машин. В связи с современной тенденцией понижения выбросов вредных веществ в окружающую среду, а также экономии смазочных материалов выдвигают жесткие требования к качеству смазочных материалов.\nСмазочные материалы в машинах выполняют множество ролей: уменьшение и защиту от сухого трения, защита от возникновения коррозии, за счет антикоррозионных присадок, охлаждение трущихся деталей и вывод продуктов износа.\nВ наше время, существует множество различных брендов смазочных материалов, обладающих различными противозадирными и противоизносными свойствами. Поэтому для различных типов машин с различными свойствами среды, подходят разные виды смазочных материалов с разными присадками.\nПоэтому существует проблема – снижение износа поверхностей, подвергающихся трению и нагрузкам. Это позволит продлить срок эксплуатации деталей механизмов, сделает их более долговечными и надежными. В ряде случаев смазки применяются не только для снижения износа, но  и для предотвращения трения и заклинивания смежных поверхностей. Благодаря своей пластичности и составу эти мазки защищают от проникновения агрессивных веществ, газов и паров. Также практически все консистентные смазки отличаются антикоррозионными свойствами и т.д. Необходимо расширять сырьевую базу и увеличивать рабочий диапазон применения пластичных смазок.\n', 2, '2023-02-06', '2023-06-25', '', 'ООО «ПолитехГидравлика»', NULL, 'Масла, пластичные смазки, топлива с заданными смазывающими свойствами. Позволит расширить характеристики данных нефтепродуктов.', 'Знания: методология исследования\nУмения: исследовать свойства нефтепродуктов\nНавыки: правильно подходить к выбору гсм\n', 'Стрельников Александр Николаевич', 4, 1, 32, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(337, NULL, '2023-04-05 11:00:50', 'Изучение свойств  материалов масляных фильтров', 15, 'Разработка методики исследования свойств материалов и определение (Изучение) качеств материалов масляных фильтров', 'В рамках международных стандартов к масляным фильтрам предъявляется немало требований: Фильтрующие элементы к ним должны соответствовать требованиям настоящего стандарта и конструкторской документации (КД), утвержденной в установленном порядке. Полнота отсевов фильтров и фильтрующих элементов должна быть не менее 25 %. Зависимость тонкости отсева от полноты ГОСТ Р 53844—2010 4.3 Ресурс фильтрующего элемента до замены (для 1 категории условий эксплуатации) по ГОСТ 21624 устанавливают в руководстве (инструкции) по эксплуатации автомобиля, при этом он должен быть не менее 250 ч работы двигателя. Гидравлическое сопротивление фильтрующего элемента и перепускного клапана, определяемое из их гидравлических характеристик при заданном расходе масла, должно быть не больше значения, указанного в КД. Фильтрующий элемент должен выдерживать без разрушения повышенный перепад давления (АР), равный не менее 2,0 АР начала открытия перепускного клапана фильтра. Фильтры должны выдерживать без нарушения давление не менее 3 Рном. Давление начала открытия перепускного клапана должно находиться в пределах, установленных требованиями КД. Фильтрующие элементы должны быть вибростойкими к пульсации давления и сохранять работоспособность при температурах от минус 50 °С до плюс 135 °С. Фильтрующие элементы, их уплотнения и другие детали должны быть масло-, бензо-, водостойкими. Материалы, используемые для изготовления фильтров и их элементов, не должны выделять в поток фильтруемого масла составляющих компонентов. \r\nВ наше время, существует множество различных брендов фильтрующих материалов, обладающих различными свойствами, но не все отвечающие определенным требованиям. Поэтому для различных типов машин работающих в различными средах и на различных режимах, требуются фильтрующие элементы отвечающие определенным требованиям\r\nПоэтому существует проблема- подбор фильтрующего элемента отвечающего определенным требованиям', 2, '2023-02-06', '2023-06-25', NULL, 'ООО «Тимбермаш Байкал»', NULL, 'Полученные результаты исследования позволят правильно подбирать фильтрующий элемент для определенного вида оборудования', 'Знания: методология исследования\r\nУмения: исследовать совйства фильтрующего материала\r\nНавыки: правильно подходить к выбору фильтрующего элемента', 'Стрельников Александр Николаевич', 4, 1, 33, NULL, NULL, NULL, NULL, NULL, NULL),
(338, NULL, NULL, 'Разработка резонансного виброгрохота', 15, 'Повышение энергоэффективности виброгрохота', 'В сырьевых и перерабатывающих отраслях промышленности для транспортирования и переработки различных сыпучих и кусковых материалов широко применяются вибрационные транспортно-технологические машины (ВТТМ). Самой представительной группой ВТТМ являются вибрационные грохоты. Традиционные виброгрохоты с дебалансным, кинематическим и электромагнитным приводами имеют невысокие технические и эксплуатационные показатели. Значительная часть вибрационного оборудования, выполняющего данные технологические операции, требует больших затрат энергии. Кроме этого имеется ряд проблем с самой обработкой материалов, в частности разделение и сортировка труднопросеиваемых материалов, самоочистка сит, дезинтеграция агломератов.\nБольшинство конструкций современных вибрационных грохотов для возбуждения колебаний используют дебалансные вибраторы и зарезонансный режим работы. В колебательной системе таких машин циркулирует большая реактивная мощность, необходимая для преодоления инерционных сил, что снижает их энергетическую эффективность.\n Повышение производительности и снижения энергетических затрат вибрационного грохота возможно благодаря явлению резонанса. В резонансном режиме работы вибрационной машины упругие и инерционные силы взаимно уравновешиваются, при этом энергия вибровозбудителя расходуется только на преодоление диссипативных сил, а рабочий орган совершает движение, близкое к собственному. \nОсновной трудностью практического использования резонансных вибрационных машин является высокая чувствительность к изменению технологической нагрузки и параметров колебательной системы. Нелинейность технологической нагрузки препятствует решению проблемы стабилизации резонансного режима работы машин при вынужденных колебаниях даже при помощи средств автоматической подстройки. \n', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Физическая модель резонансного виброгрохота. Результаты экспериментальных исследований. Методики расчета резонансного виброгрохота. ', 'Знания: расширенные знания в области вибрационной техники\nУмения: умение реализовать теоретические знания в конкретном проекте\nНавыки: навыки работы в творческом коллективе \n', 'Зедгенизов В.Г.', 4, 1, 34, NULL, NULL, NULL, NULL, NULL, NULL),
(339, NULL, NULL, 'Исследование проблем прочности деталей, изготовленных с применением цифровых производственных технологий', 15, '1)Разработать образцы для исследования проблем прочности деталей, выполненных с помощью 3D – печати. 2)Сформировать корректные расчётные схемы авиационного узла в цифровом формате, позволяющие получить достоверную оценку параметров прочности и жёсткости узла ', 'Передовые технологии производственных процессов невозможны без их цифровизации. Это актуально для авиастроения, автомобилестроения, энергетической отрасли, приборостроения, медицины и др. Многие задачи в этих случаях позволяют решить аддитивные технологии (3d-печать). Они позволяют получать детали практически любой геометрической формы и габаритов. Появилась возможность трансформации сборочной единицы в деталь. В противовес традиционным вычитающим и формообразующим технологиям с помощью 3d-печати деталь «выращивают». Весь этот процесс определяется цифровой моделью изготавливаемой детали. Одной из наиболее привлекательных технологий 3d-печати является FDM-печать. Она применяется как в прототипировании, так и при изготовлении рабочих деталей. Однако, чтобы получить несущую деталь с помощью FDM-печати, нужно суметь рассчитать её на прочность. А для этого необходимо знать как на прочность влияют свойства материала печати, параметры печати, шаблон печати, процент заполнения детали и т.д. Ответы на эти вопросы можно получить, научившись работать на 3D-принтере; изучив поведение деталей, изготовленных на нём, под действием нагрузок. Для изучения поведения деталей нужны натурные и численные эксперименты. Натурные эксперименты, как правило, проводят на образцах. Значит надо изготовить с помощью FDM-печати образцы и провести их испытание на специальном оборудовании. Как правило, в качестве материала для FDM-печати применяют термопластики, композитные термопластики. Поскольку, требований к форме таких образцов пока нет, их надо разработать. Численные эксперименты требуют формирования адекватных моделей в CAD/CAE – системах (Femap, ANSYS, FIDESYS, Siemens NX, КОМПАС-3D, и др.). Под «адекватными моделями» понимаются модели, которые достоверно отображают в цифровой среде поведение реальной детали под действием реальной нагрузки. В частности, необходимо построить в цифровой среде модель натурных испытаний FDM-образцов.\nОднако, исследование прочности деталей, изготовленных с помощью традиционных технологий, не утратило своей актуальности. Основная часть конструкции самолёта образована деталями, изготовленными с помощью таких технологий. Конструкция самолёта представляет собой весьма сложную и многокомпонентную структуру, взаимное влияние между её элементами (деталями) непростое и меняется в зависимости от изменения режима работы конструкции (режима полёта, наземного режима). При этом должна обеспечиваться их прочность. Случаев нагружения одной и той же детали несколько и не все они являются явными. Следовательно, без применения цифровизации процессов исследования в сочетании с натурными испытаниями получить ответы на вопросы о причинах разрушения такой детали и разработке рекомендаций для её оптимизации очень сложно или невозможно. Под цифровизацией процессов исследования понимается применение CAD/CAE – систем. В частности, необходимо построить в цифровой среде достоверную модель реального объекта исследования; на основе её анализа сделать заключение о причинах потери прочности и дать рекомендации об устранении этих причин.\n', 2, '2023-02-06', '2023-06-25', '', 'Иркутский авиационный завод', NULL, '1. Образцы для экспериментальных исследований характеристик прочности и жёсткости деталей, изготовленных с применением FDM-печати. 2. Формирование электронной модели узла, позволяющей системно оценить параметры прочности и жёсткости с целью оптимизации конструкции узла. Фиксация материала осуществляется в форме электронной модели, сформированной в автоматизированной среде инженерного анализа и соответствующей пояснительной записке с соответствующими описаниями', 'Знания: об аддитивных технологиях применительно к изготовлению несущих деталей, с заданными механическими характеристиками; о методах расчёта авиационных деталей на прочность\nУмения: работать на 3d-принтере; определять значения параметров напряжённо-деформированного состояния реальных деталей\nНавыки: проведения натурных экспериментов для определения характеристик прочности и жёсткости; построения цифровых моделей исследуемых деталей\n', 'Распопина Вера Борисовна', 4, 1, 35, NULL, NULL, NULL, NULL, NULL, NULL),
(340, NULL, NULL, 'Анализ инноваций проектирования и производства беспилотных систем.', 15, 'Проектирование и анализ технологических процессов производства БПЛА', 'В настоящее время в мире в различные производства внедряется большое количество инноваций. В России внедрение осложняется необходимостью импортозамещения. К различным российским компаниям, в основном связанным с оборонным и ресурсодобывающим секторами применяются санкции, причем по продуктам, на которых в компаниях реализованы различные технологические процессы основной деятельности, В частности, это касается систем инженерного анализа и технически сложного оборудования и комплектующих. На все это накладывается  необходимость завершения текущих проектов в приемлемые сроки.\nК подобным инновациям можно отнести:\nНовые производственные технологии, к которым, например можно отнести моделирование, аддитивные технологии, которые  позволяют сократить время от идеи до реального моделирования, сократить стоимости изготовление деталей.\nВнедрение новых материалов (композиционные материалы) которые зачастую требуют создания новых специфических технологических процессов и уникального оборудования.\nВнедрение элементов искусственного интеллекта, работы с большими данными и облачные сервисы влекут за собой повышение эффективности эксплуатации изделий и производственного оборудования, повышение производительности труда, сокращение времени на поиск нужных решений\nВиртуальная и дополненная реальность позволяет на этапе электронного моделирования улучшить структурирование и качество производственных операций, сократить количество \nдефектов за счет предварительной проработки производственных процессов\nРобототехника, сенсорика и автоматизация проектирования и проведения технологических процессов  позволяют сократить, временя производства изделий, получать стабильные результаты выполняемых операций без присутствия человека.\nТаким образом, в  рамках проекта, в зависимости от состава команды и ее возможностей будут реализовываться следующие направления:\nбеспилотные системы;\nаддитивные технологии;\nоборудование инновационных технологических процессов;\nтехнология композиционных материалов;\nробототехника;\nавтоматизированные системы;\nконтроллеры и их программирование. \n', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Подготовленная заявка участия в конкурсе на получение финансирования. ', 'Знать: основы  принципов построения технологических процессов основных производств и изделий и тенденции их развития; основные программные продукты подготовки и разработки технологических процессов и изделий. \nУметь: проводить анализ перспективных технологических процессов и изделий\nВладеть навыками работы в программных продуктах, достаточных для проведения работ по анализу и подготовке технологических процессов и разработке изделий. \n', 'Дебердеев Евгений Масутович', 4, 1, 36, NULL, NULL, NULL, NULL, NULL, NULL),
(341, NULL, NULL, 'Разработка воздухо-воздушного теплообменника СКВ современного самолета', 15, 'Разработка рекомендаций по совершенствованию конструкции воздухо-воздушных теплообменников СКВ на основе инженерных расчетов теплообменных аппаратов с целью повышения их  эффективности,  надежности и эксплуатационного ресурса', 'В настоящее время вопросам теплообмена и его интенсификации в теплообменниках посвящены многие теоретические и экспериментальные работы. Однако усовершенствованные конструкции новых поколений авиационных турбин требуют поиска новейших более конструктивных решений, которые обеспечивали бы увеличение ресурса существующих двигателей и улучшение характеристик перспективных двигателей новых поколений.\nВ процессе проектирования рассчитывают массовые расходы теплоносителей, определяют температуры нагревающей и охлаждающей среды, коэффициенты теплопередачи и поверхность теплообмена и эффективность данного теплообменного аппарата, рассчитываются потери давления в аппарате. \n', 3, '2023-02-06', '2023-06-25', '', 'Иркутский авиационный завод', NULL, 'Проект воздухо-воздушного теплообменника СКВ на основе инженерных расчетов теплообменных аппаратов', 'Знать: основные понятия и определения тепломассообмена; методы проведения инженерных расчётов теплообменных аппаратов.\nУметь: формулировать математические задачи для теплообменных аппаратов в дифференциальной и интегральной формах.\nВладеть навыками и методами расчетов теплообменных аппаратов.\n', 'Молокова Светлана Васильевна', 4, 1, 37, NULL, NULL, NULL, NULL, NULL, NULL),
(342, NULL, NULL, 'Прогнозирование времени задержки прибытия авиационных рейсов с помощью машинного обучения', 15, 'Разработка математической, обучаемой предиктивной модели, позволяющей по различным данным о текущей погоде, состоянию и загруженности аэропорта, и др. предсказать возможную задержку прибытия авиационного рейса и причины ее возникновения. ', 'В настоящее время ведутся активные работы по части применения методов машинного обучения и искусственного интеллекта для различных задач предсказательной аналитики. Крупный международный аэропорт в год может принять до 15 миллионов пассажиров, обслужить до 160 тысяч взлетно-посадочных операций. В таких условиях особенно остро стоит вопрос автоматизации процессов распределения воздушного и наземного трафика, регламентных работ и прочих функций с целью повышения эффективности и снижения аварийности. Генерирующиеся в процессе работы аэропорта массивы данных могут стать базой для построения различных предиктивных моделей, которые обладают высокой предсказательной силой. Результаты работы этих моделей могут быть в свою очередь использованы для информирования персонала аэропорта о возможных проблемах, пассажиров о возможных неудобствах и для понимания необходимых путей для решения данных проблем', 3, '2023-02-06', '2023-06-25', '', 'Международный Аэропорт Иркутск', NULL, 'Математическая модель прогнозирования времени задержки прибытия авиационных рейсов ', 'Знать: основные модели машинного обучения, методы их построения и валидации результатов\nУметь: работать с большими данными (Big Data) и применять полученную в ходе анализа информацию для решения прикладных инженерных задач\nВладеть навыками и методами создания и тренировки различных моделей машинного обучения \n', 'Груздев Александр Сергеевич', 4, 1, 38, NULL, NULL, NULL, NULL, NULL, NULL),
(343, NULL, '2022-06-17 10:50:13', 'Оборудование для наземной эксплуатации авиационной техники', 15, 'Разработка аванпроекта оборудования для наземной эксплуатации авиационной техники (авиационных систем) с применением методов и средств инженерного анализа', 'Данный проект направлен на совершенствование технологии эксплуатации авиационной техники. частности, предполагается разработка проекта средств наземной эксплуатации (гидростендового и иного оборудования) с улучшенными характеристиками. Наземное оборудование – неотъемлемая часть комплекса для эксплуатации любого воздушного судна. От того, насколько наземное оборудование будет соответствовать современным требованиям по функциональности, эргономике, стоимости, и ряду других параметров, зависит в конечном счёте и стоимость эксплуатации самой авиационной техники, и, как следствие, её конкурентность на авиационном рынке.', 3, '2023-02-06', '2023-06-25', NULL, 'АО «Авиакомпания «Ангара»', NULL, 'Модель или схема наземного оборудования (гидростенда или иного оборудования).', 'Знания: о методах анализа систем по различным критериям\r\nНавыки: выполнения схем  и моделей систем.', 'Бобарика Игорь Олегович', 4, 1, 39, NULL, NULL, NULL, NULL, NULL, NULL),
(344, NULL, NULL, 'Оптимизация авиационных гидросистем с учётом технологии их обслуживания при эксплуатации', 15, 'Обоснование необходимости и определение путей модернизации авиационных систем с учётом эксплуатационной истории с применением современных средств инженерного анализа и предиктивной аналитики', 'Данный проект направлен на совершенствование авиационной техники, характеристик её бортовых систем. В частности, рассматривается возможность оптимизации разветвлённых трубопроводных систем, а это все гидравлические, топливные, пневматические системы, без которых не может существовать ни один современный самолёт. Все системы тесно сплетены между собой, а их характеристики обеспечивают характеристики всего самолёта в целом. Знать бортовые системы, принципы их работы, видеть возможности для их совершенствования и модернизации, разрабатывать и предлагать конкретные решения – значит быть настоящим авиационным инженером!', 2, '2023-02-06', '2023-06-25', '', 'АО «Авиакомпания «Ангара»', NULL, 'Модель бортовой системы с элементами многофакторной оптимизации.', 'Знания: о методах анализа систем по различным критериям\nНавыки: выполнения многофакторной оптимизации систем.\n', 'Бобарика Игорь Олегович', 4, 1, 40, NULL, NULL, NULL, NULL, NULL, NULL),
(345, NULL, NULL, 'Цифровой двойник цеха агрегатно-сборочных работ', 15, 'Создание твердотельных 3D моделей, предназначенных для создания виртуальной модели цеха агрегатно-сборочных работ, используемых для изготовления авиационных деталей', 'Создание цифрового двойника производственного помещения в образовательном сегменте позволит обеспечить доступные инструменты для пользователей и дополнить обучающие программы интерактивным визуальным контентом. Погружение студентов в производственную атмосферу, без физического присутствия на производстве.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Электронные модели авиационных узлов собираемые в сборочных приспособлениях, которые в дальнейшем будут интегрированы в программный модуль цифрового двойника', 'Знать основные технологические процессы изготовления авиационных деталей\nУметь составлять технологические процессы\nЗнание основ конструкции сборочных приспособлений\n\nЗнать основные инструменты создания 3D моделей в системе NX\nУметь использовать инструменты моделирования с заданием физико-механических свойств материала \n', 'Фокин Игорь Владимирович', 4, 1, 41, NULL, NULL, NULL, NULL, NULL, NULL),
(346, NULL, NULL, 'Конструкция и система управления навесными модулями настольного станка с ЧПУ', 15, 'Разработка навесного модуля для работы тангенциальным ножом илт терморезака/нихромового ножа резки композитных материалов и системы управления ими при реализации программы импортозамещения', 'Разработанный проект должен предполагать получение новых возможностей для существующего средства технологического оснащения - настольного станка. Это возможность установить новый инструмент, разработать систему для его управления.', 3, '2023-02-06', '2023-06-25', '', 'Проект \"Твой ход\", направление \"Двигаю прогресс\"', NULL, 'Модель, макет', 'Знания: основы проектирования типовых узлов и систем для станков с ЧПУ\nУмения: выполнять конструирование узлов механических приводов и электрических плат, в том числе и с помощью ЭВМ\nНавыки: прототипирования и моделирования\n', 'Казимиров Денис Юрьевич', 4, 1, 42, NULL, NULL, NULL, NULL, NULL, NULL),
(347, NULL, NULL, 'Предварительная оценка машинного времени обработки заготовительно-штамповочной оснастки', 15, 'Создание классификатора изделий по геометрическим особенностям, влияющим на машинное время обработки заготовительно-штамповочной оснастки, и вычисление соответствующих поправочных коэффициентов', 'Заготовительно-штамповочное производство в авиационной промышленности имеет немаловажное значение, так как листовая штамповка используется для изготовления многих деталей. Оснастка заготовительно-штамповочного производства уникальная для каждого изделия. Внесение изменений в конструкцию детали требует изменения модели оснастки и изготовления нового образца, часто в кратчайшие сроки. Внесение нового приоритетного изделия в цеховое расписание требует его перестроения, для чего необходимо знать машинное время. Традиционно, машинное время вычисляется при помощи встроенных функций Unigraphics NX, но для этого требуется написание управляющей программы, что занимает значительное время. Для повышения гибкости производства целесообразно применить метод предварительной оценки машинного времени на основе скорости удаления материала. Для более точного приближения результата к реальному необходимо ввести коэффициенты, учитывающие геометрические особенности изделия и динамические характеристики оборудования, что требует проведения экспериментальных исследований.', 2, '2023-02-06', '2023-06-25', '', 'Конкурс «Твой Ход», направление «Двигаю прогресс».\nhttps://tvoyhod.online/\n', NULL, 'Методика оценки машинного времени на основе классификатора изделий и скорости удаления материала, позволяющая в краткие сроки позволить предоставить данные по машинному времени для перестроения цехового расписания', 'Знания: виды продукции, выпускаемой в цехах изготовления заготовительно-штамповочной оснастки, методики оценки машинного времени.\nУмения: работа в среде Unigraphics NX, анализ геометрической информации.\nНавыки: поиск информации, анализ информации с целью выделения требуемого знания, формирование комплексного понимания предмета изучения на основе полученной информации, системный анализ полученной информации, выделение «дефицитов» знаний и формулирование запроса на поиск новой информации.\n', 'Исаченко Алексей Сергеевич', 4, 1, 43, NULL, NULL, NULL, NULL, NULL, NULL),
(348, NULL, NULL, 'Лопасти воздушного винта из композиционного материала', 15, 'Разработка технологии изготовления лопасти воздушного винта из композиционного материала для водной техники (аэролодка)', 'Исследование и анализ существующих геометрий лопастей для водной техники (аэролодка). Разработка геометрии лопасти в программной среде Siemens NX. Проектирование специализированной оснастки для изготовления прототипа лопасти из композиционных материалов методом вакуумной инфузии. Изготовление и подготовка оснастки. Создание прототипа лопасти из композиционного материала.', 2, '2023-02-06', '2023-06-25', '', 'ООО «ИРКУТ – АЭРО»', NULL, 'Прототип лопасти воздушного винта из композиционного материала', 'Знания: основы проектирования типовых узлов и деталей машин; основы проектирования типовых узлов и деталей машин\nУмения: выполнять конструирование типовых узлов и деталей машин, в том числе и с помощью CAD-технологий\nНавыки: выполнения инженерных и компьютерных расчётов, способами представления и анализа результатов; \n', 'Чащин Николай Сергеевич', 4, 1, 44, NULL, NULL, NULL, NULL, NULL, NULL),
(349, NULL, NULL, 'Разработка и изготовление лабораторного комплекса и исследование процесса комбинированного формообразования подкреплённых панелей самолётов', 15, 'Опытная отработка импортонезависимой технологии формообразования крупногабаритных панелей сложной формы  ', 'Панели крыла представляют собой обводообразующие детали с гладкой наружной (аэродинамической) поверхностью. Внутренний набор деталей типа панелей содержит такие конструктивные элементы как карманы, люки с окантовками и подкрепляющие рёбра различных сечений, расположенные в продольном или в поперечном направлениях. \nПо геометрической форме панели и обшивки представляют собой совокупность линейчатых поверхностей с направляющими переменной кривизны, участков двойной и знакопеременной кривизны (зон перегиба) с закруткой сечений.\nОсновными технологическими операциями получения требуемой формы деталей является дробеударное формообразование с последующей зачисткой, а так же раскатка и посадка ребер.\nВ рамках проектных работ будет разработано, изготовлено и испытано следующее оборудование:\n- лабораторная установка для обработки методами раскатки роликами и посадки;\n- лабораторная установка для дробеударного формообразования и зачистки абразивными лепестковыми кругами.\nТакже планируется проведение опытных работ на образцах с целью отработки технологии формообразования подкреплённых панелей\n', 3, '2023-02-06', '2023-06-25', '', 'ПАО «Электромеханика»', NULL, 'Лабораторные стенды для отработки технологии формообразования деталей пита подкреплённых панелей из алюминиевых сплавов', 'Знать: основные технологические процессы формообразования и правки крупногабаритных маложестких деталей.\nУметь: проектировать специальное оборудование для реализации технологии формообразования и правки крупногабаритных маложестких деталей.\nНавыки: проектирование в Siemens NX; слесарные и сборочные работы.\n', 'Пашков Александр Андреевич', 4, 1, 45, NULL, NULL, NULL, NULL, NULL, NULL),
(350, NULL, NULL, 'Изготовление корпусных деталей беспилотных летательных аппаратов', 15, 'Разработка технологии изготовления корпусных деталей беспилотных летательных аппаратов', 'Исследование и анализ существующих корпусных деталей беспилотных летательных аппаратов. Разработка модели корпуса в программной среде Siemens NX. Проектирование специализированной оснастки для изготовления прототипа деталей корпуса из композиционных материалов методом вакуумной инфузии. Изготовление и подготовка оснастки. Создание прототипа детали корпуса.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Прототип детали корпуса беспилотных летательных аппаратов', 'Знания: основы проектирования типовых узлов и деталей машин; основы проектирования типовых узлов и деталей машин\nУмения: выполнять конструирование типовых узлов и деталей машин, в том числе и с помощью CAD-технологий\nНавыки: выполнения инженерных и компьютерных расчётов, способами представления и анализа результатов; \n', 'Иванов Юрий Николаевич', 4, 1, 46, NULL, NULL, NULL, NULL, NULL, NULL),
(351, NULL, NULL, 'Разработка оптимальных характеристик конструкции механизма перемещения садовых и строительных грузов весом до 250 кг. ', 15, 'Разработка работающего устройства перемещения грузов', 'Изготовленное устройство перемещения грузов должно облегчить труд пожилого контингента на дачном участке или строителей при ремонтных и строительных работах с небольшими объёмами работ. Изготовлению должно предшествовать комплекс расчетных и технологических задач, позволяющие обеспечить точное воспроизведение в действующем образце всех заложенных параметров. В рамках проекта будут освоены CAD системы, позволяющие обеспечить точное воспроизведение рассчитанного изделия. Полученные чертежи, с трёхмерной модели, позволят изготовить в металле детали на станках токарно-фрезерной группы. Для этого будет изучен инструмент и станки, подобран материал для изготовления деталей. Изучены критерии и приборы для оценки качества деталей ( шероховатость, размерных допусков и погрешностей формы, определение твёрдости, методы закалки и т.д.).', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Готовое изделие для перемещения грузов', 'Знания: Изучение CAD системы трёхмерного моделирования. Систему допусков и посадок. Методы определения твёрдости материалов и пути их достижения. Знать устройство и возможности металлорежущих станков, методы обработки материалов.\nУмения :Работать в CAD системе трёхмерного моделирования, уметь создавать детали и сборочные единицы. На основе 3D модели создавать чертежи деталей. Для изготовления деталей подбирать необходимое оборудование, инструмент и режимы резания.\nНавыки: Рациональная работа CAD системе. Работа на металлорежущих станках. Работа с приборами оценивающие  качество поверхности.\n', 'Дрожжин Сергей Николаевич', 4, 1, 47, NULL, NULL, NULL, NULL, NULL, NULL),
(352, NULL, NULL, 'Разработка и изготовление  опытной партии многофункциональных пильных станков на модульном принципе', 15, 'Разработка рабочей и эксплуатационной документации многофункциональных пильных станков,  организация производства ', 'Многофункциональность станков обеспечивается за счет быстрой смены режущего инструмента (пильные диски для разных материалов), изменение режимов резания, наличие  сменных контейнеров для сбора разных отходов и использования специальных сменных модулей. Модульный принцип реализован в разделении конструкции станка на отдельные модули по технологическим и конструктивным свойствам. Разделение на модули является важной задачей и решается синтезом сложных систем, определения числа оптимальных функций каждого модуля. \nПроизводство пильных станков не требует сложных технологий и дорогостоящего оборудования, высокой квалификации рабочих, что подтверждается изготовлением 4х станков силами студентов в рамках выпускной работы. Модульный принцип позволяет распределить изготовление модулей на небольших предприятиях и среди индивидуальных предпринимателей, а общую сборку и испытание проводить на базе лабораторий ИрНИТУ. Расчетная стоимость производства пильного станка составляет на 2021г. 16363руб., что позволяет говорить об возможном получении прибыли при условии стоимости подобных станков на рынке 20-40тыс. руб.. Потребителями станка на рынке в первую очередь являются индивидуальные предприниматели, строительные фирмы, малые предприятия и др.. Для повышения качества, производительности и обеспечения взаимозаменяемости модулей в лаборатории спроектированы и изготовлены специальные сборочные приспособления для каждого модуля.\nТехнические решения заложенные в конструкции пильного станка имеют большой потенциал при его использовании и совершенствовании конструкции самого станка\n', 2, '2023-02-06', '2023-06-25', '', 'Патент ИрНИТУ на изобретение №2709064 «Модульный многофункциональный пильный станок» 2019г', NULL, 'Рабочая конструкторская документация, технология изготовления и готовые станки для реализации', 'Знать: основы проектирования станочного оборудования на модульном принципе, технологические процессы изготовления деталей, сборки узлов( модулей) и общей сборки станков.\nУметь: проектировать станочное оборудование, приспособлений разного назначения.\nНавыки: проектирование в Siemens NX; слесарные и сборочные работы.\n', 'Москвитин Виктор Николаевич', 4, 1, 48, NULL, NULL, NULL, NULL, NULL, NULL),
(353, NULL, NULL, 'Разработка эскизного проекта СВП «Марс 7000», проектирование отдельных узлов и элементов ', 15, 'Создание судов на воздушной подушке для использования в условиях крайнего Севера для нужд нефтегазовой добывающей отрасли ', 'В ОКБ имени Алексеева г.Нижний Новгород разработаны и изготовлены суда на воздушной подушке разных типов и грузоподъемности. Наиболее эффективным является «Марс2000и3000» Данные аппараты рассчитаны на перевозку 20 или 30 человек. Аппараты в теплое время эксплуатируют на водных акваториях, а в зимнее время на льду и снежном покрове. Они оснащены двумя дизельными двигателями, которые обеспечивают скорость движения 50- 70 км/час.\nДля повышения грузоподъемности и скорости необходимо снижение массы конструкции корпуса и двигателей, а также повышение мощности привода. Важным фактором эффективного использования в условиях крайнего севера возможность эксплуатации при температурах минус 40-50град. Требования заказчика иметь разные модификации аппаратов: пассажирский, грузовой и грузо-пассажирский с грузовой нагрузкой более 5-10Тс.\nВ 2021-2022г. автором разработаны два проекта в виде технического предложения «Марс300» и «Марс7000» с турбо вальными газотурбинными двигателями, которые позволяют в два раза увеличить мощности привода, уменьшить массу конструкции, увеличить скорость до 90 км/час, поднять грузоподъемность до 7000кг. Важным достоинством ГТД малый вес, долговечность и высокая надежность при эксплуатации при низких температурах. Конструкция аппаратов относится к сложными ответственным транспортным средствам, включает в себя множество уникальных устройств(редукторы, силовые передачи, системы управления и т.д.). \n', 3, '2023-02-06', '2023-06-25', '', 'ОКБ имени Алексеева г.Нижний Новгород', NULL, 'Рабочая конструкторская документация, технология изготовления элементов конструкций и систем', 'Знать: основы проектирования сложных и ответственных конструкций транспортных систем, технологические процессы изготовления деталей, сборки узлов( модулей) и общей сборки.\nУметь: Разрабатывать  сборочные и деталиировочные чертежи, строить КЭМ \nНавыки: проектирование в Siemens NX;.\n', 'Москвитин Виктор Николаевич', 4, 1, 49, NULL, NULL, NULL, NULL, NULL, NULL),
(354, NULL, NULL, 'Снежный 3Д принтер', 15, 'Разработка и сборка 3Д принтера способного печатать снегом', 'В зимний период в Иркутской области выпадает много снега, разработка устройства которое позволит печатать из снега различные объекты практического и художественного смысла', 2, '2023-02-06', '2023-06-25', '', 'ИРНИТУ ректорат', NULL, 'Прототип 3Д принтера, печатающего снегом', 'Знания: системы ЧПУ, шаговые двигателя\nУмения: Конфигурация систем с ЧПУ\nНавыки: подготовка моделей к 3Д печати, физика процесса 3Д печати\n', 'Кононенко Роман Владимирович ', 4, 1, 50, NULL, NULL, NULL, NULL, NULL, NULL),
(355, NULL, NULL, 'Разработка бобинной технологии сварки с перемешиванием', 15, 'Опытная отработка технологии сварки трением с перемешиванием с использованием бобинного инструмента (инструмента с двумя заплечиками)  ', 'Традиционные технологические процессы сварки обладают целым рядом недостатков, которые в свою очередь отсутствует при использовании сварки с трением с перемешиванием (СТП). Особый интерес вызывают современные способы СТП, которые позволяют повысить качество соединений, получаемых с применением этой технологии. Одним из таких способов расширения технологических возможностей СТП является сварка с использованием бобинного инструмента (инструмента с двумя заплечиками).  \nВ рамках проектных работ будет спроектированы, изготовлены и испытаны средства технологического оснащения процесса: сварочные приспособления, сварочный инструмент.\nВ рамках проекта также планируется проведение опытных работ на образцах с целью отработки технологии бобинной сварки трением с перемешиванием.\n', 1, '2023-02-06', '2023-06-25', '', '', NULL, 'Приспособления и инструмент для реализации исследуемой технологии бобинной сварки трением с перемешиванием', 'Знать: основные технологические особенности сварки трением с перемешиванием\nУметь: проектировать специальное технологическое оборудование для реализации технологии СТП.\nНавыки: проектирование с использованием программных продуктов САD, CAE; слесарные и сборочные работы.\n', 'Тютрин Николай Орестович', 4, 1, 51, NULL, NULL, NULL, NULL, NULL, NULL),
(356, NULL, NULL, 'Разработка технологии изготовления алюминиевых труб с внутренним антифрикционным покрытием', 15, 'Опытная отработка импортозамещающей технологии производства алюминиевых труб для производства гильз пневмоцилиндров с повышенными эксплуатационными свойствами рабочей поверхности   ', 'Алюминиевые трубы для производства гильз пневмоцилиндров используются российскими производителями пневмооборудования, а также приобретаются эксплуатирующими организациями в ремонтных целях. При этом в Российской Федерации такая продукция не производится и приобретается за рубежом (производители – предприятия европейских стран и КНР). Традиционная технология изготовления труб для изготовления гильз пневмоцилиндров – прессование. Она отличается высокой себестоимостью, приводящей к завышенной цене готового продукта. Кроме того, изготовленные таким способом гильзы не имеют износостойкого слоя. В этой связи проект, направленный на создание технологии производства импортозамещающей продукции с повышенным ресурсом путём её изготовления центробежным литьём, является актуальным.\nВ рамках работ будет спроектированы, изготовлены и испытаны средства технологического оснащения процесса: вращающаяся изложница, плавильно-разливочный модуль.\nВ рамках проекта также планируется производство опытных образцов и испытание их эксплуатационных свойств.\n', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Опытная технологическая оснастка для реализации технологии производства алюминиевых труб методом центробежного литья с нанесением антифрикционных покрытий', 'Знать: основные технологические особенности литейных и сварочно-наплавочных технологий\nУметь: проектировать специальное технологическое оборудование для реализации технологии СТП.\nНавыки: проектирование с использованием программных продуктов САD, CAE; слесарные и сборочные работы.\n', 'Тютрин Николай Орестович', 4, 1, 52, NULL, NULL, NULL, NULL, NULL, NULL),
(357, NULL, NULL, 'Определение показателей качества металлоконструкций, изготавливаемых аддитивными комбинированными технологиями ', 15, 'Опытная отработка  методик и технологий определения показателей качества изделий, изготавливаемых аддитивными методами', 'Изготовленные с применением аддитивных технологий металлические детали и изделия  могут обеспечить значительное снижение веса и повышение производительности в различных отраслях промышленности. Внедрению аддитивных технологий в производство должно предшествовать решение комплекса технологических задач, позволяющих обеспечить точные и воспроизводимые характеристики изделий. В рамках проекта будут освоены различные методики определения характеристик изделий, а также  основы технологии  их аддитивного производства', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Методики оценки качества изделий при послойном аддитивном выращивании', 'Знать: показатели качества металлоконструкций, изготавливаемых аддитивными технологиями и методы их определения\nУметь: проводить комплекс необходимых исследований для  определения основных характеристик  изделий, полученных \nНавыки: работ с использованием САПР, приборами и оборудованием для исследований \n', 'Астафьева Наталья Анатольевна ', 4, 1, 53, NULL, NULL, NULL, NULL, NULL, NULL),
(358, NULL, NULL, 'Обработка поверхности изделий из конструкционных материалов концентрированными источниками нагрева ', 15, 'Получение особых свойств поверхностных слоёв изделий из конструкционных материалов при воздействии концентрированными источниками нагрева', 'Проблема совершенствования технологических методов упрочнения конструкционных материалов является  актуальной  на сегодняшний день. Данный проект направлен на исследование фазовых и структурных превращений в конструкционных материалах после воздействия концентрированных источников нагрева и разработка комбинированных технологий поверхностного упрочнения с использованием плазменного и лазерного источника, обеспечивающих высокий уровень физико-механических свойств поверхностного слоя. Для этого необходимо провести комплексные исследования взаимосвязи структуры и свойств исследуемых материалов  с различной исходной микроструктурой в зонах лазерного и плазменного воздействия, сформированных при различных вариантах, условиях и энергетических параметрах непрерывного излучения, используемого с целью достижения термического упрочнения, легирования и наплавки.', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Комбинированная технология поверхностного упрочнения ( легирования, наплавки)', 'Знать: методы обработки поверхности изделий из конструкционных материалов концентрированными источниками нагрев, методы исследования структуры и свойств матеоиалов;\nУметь: проводить комплекс необходимых исследований для  установления взаимосвязей структуры и свойств исследуемых материалов  с различной исходной микроструктурой в зонах лазерного и плазменного воздействия, сформированных при различных вариантах, условиях и энергетических параметрах непрерывного излучения;\nНавыки: работы с  приборами и оборудованием для исследований, оборудованием для упрочнения, легирования и наплавки .\n', 'Астафьева Наталья Анатольевна ', 4, 1, 54, NULL, NULL, NULL, NULL, NULL, NULL),
(359, NULL, '2022-08-31 10:44:08', 'Разработка методологии реверс- инжиниринга деталей', 15, 'Создание методологии разработки электронных моделей изделий методом обратного (реверсного) инжиниринга.', 'Под реверс-инжинирингом понимают процесс создания конструкторской документации на основе снятия данных с реального изделия.  В отличие от традиционных методов, метод обратного сканирования позволяет значительно сократить сроки разработки и удешевить процесс. \r\nВ условиях, когда предприятия столкнулись с необходимостью импортозамещения, разработка электронных моделей изделий, полностью подходящих под требования заказчика, весьма актуальна. \r\nВ настоящее время в ИрНИТУ поступают заказы от предприятий различного профиля на создание графического пакета документации на детали. \r\nОбучающиеся, решившие принять участие в данном проекте,  на реальных заказах от АО «АНХК» пройдут весь путь от трехмерного сканирования деталей  до создания  рабочей документации.', 2, '2023-02-06', '2023-06-25', NULL, 'АО «АНХК»', NULL, 'Создание электронных моделей деталей методом реверс-инжиниринга', 'Знания: методов снятия  и обработки графической информации с образца изделия\r\nУмения: продумывать последовательность обработки графической информации об объекте с целью максимально эффективного создания его модели\r\nНавыки: работы с 3d сканером, обработки результатов сканирования, работы с графическим ПО для создания электронной модели изделия', 'Клименкова Светлана Богдановна', 4, 1, 55, NULL, NULL, NULL, NULL, NULL, NULL),
(360, NULL, NULL, 'Проектирование кулисно-рычажных механизмов убирающегося шасси самолета.', 15, 'Разработать методику расчета механизма с качающимся гидроцилиндром.', 'Механизмы убирающегося шасси самолета представлены структурными схемами в сборнике механизмов Артоболевского И.И. «Механизмы в современной технике» , 1352-1375, в количестве 23 вариантов. Данные схемы включают в свою конструкцию гидроцилиндры, что классифицирует их как механизмы второго типа. Механизм качающегося гидроцилиндра должен быть адаптирован к различным видам расчета через преобразование его в кулисно-рычажный механизм. \nСтруктурный, кинематический и кинетостатический расчет таких механизмов отличается от исследования рычажных механизмов первого типа. Рабочие учебные программы по дисциплинам «Механика», «Теория механизмов и машин» охватывают изучение только механизмов первого типа, что не позволяет углубиться в изучение механизмов, использующихся в конкретном направлении подготовки специалистов в области конструирования и проектирования машин и механизмов. Данный проект является логическим продолжением изучения механики, устанавливающим взаимосвязь между общетехническими и  специальными дисциплинами. \n', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Методические рекомендации расчета механизмов второго типа. Комплект конструкторской документации.', 'Знания: конструкций убирающихся шасси самолета; ЕСКД.\nУмения: проводить проектировочные расчеты; анализировать конструкцию механизма;  выбора рациональной структурной схемы механизма для возможности использования его в проектируемом сборочном узле, агрегате. \nНавыки: конструирования, проектирования, выполнения чертежей и расчетных схем с использованием CAD/CAM/CAE систем проектирования; систематизирования и анализа информации для дальнейшего продвижения, реализации полученных результатов  в конкретных методиках расчета.\n', 'Шматкова Анна Викторовна', 4, 1, 56, NULL, NULL, NULL, NULL, NULL, NULL),
(361, NULL, NULL, 'Разработка автоматизированной «дорожной карты» подготовки и проведения мероприятий в ИРНИТУ', 15, 'Автоматизированная «дорожная карта» подготовки и проведения мероприятий в ИРНИТУ', 'Проводимые в ИРНИТУ мероприятия различаются продолжительностью времени, необходимого для их подготовки, и пакетом оформляемых документов. На этапе подготовки мероприятия организаторы иногда упускают из вида некоторые факторы, значимые при составлении сметы и формирования других документов, необходимых для беспроблемного проведения мероприятия. Разработанная «дорожная карта» должна давать организаторам исчерпывающую информацию о каждом шаге подготовки мероприятия', 2, '2023-02-06', '2023-06-25', '', 'Институт информационных технологий и анализа данных', NULL, 'Автоматизированная «дорожная карта» подготовки и проведения мероприятий в ИРНИТУ, адаптированная под разные их виды', 'Знания: эффективное делопроизводства в современных условиях функционирования организации\nУмения: отладка процессов эффективного движения документов внутри организации\nНавыки: грамотного распределения времени и ресурсов для нормального функционирования организации\n', 'Чернышенко Марина Сергеевна', 4, 1, 58, NULL, NULL, NULL, NULL, NULL, NULL),
(362, NULL, NULL, 'Профиль потребителя энергоресурсов.', 15, 'На основе данных ИЭСБК создать профиль потребителя энергоресурсов', 'проанализировать базу данных параметров потребителя, которую собирает ИЭСБК, оценить, какими данными еще стоит ее наполнить и из каких источников (внешних/внутренних); разработать методику формирования профиля потребителя; сформировать типы профилей и их характеристики; провести сегментацию всех потребителей по профилям; разработать методику/набор инструментов для взаимодействия (в части контроля и взыскания задолженности) с потребителем в зависимости от его профиля', 3, '2023-02-06', '2023-06-25', '', 'ООО «Эн+ Диджитал»', NULL, 'разработан набор характеристик каждого профиля, алгоритм дополнения БД недостающими характеристиками, критерии кластеризации потребителей по профилям', 'Знать: особенности потребителя энергетической продукции, причины недополучения платы за энергоуслуги.\nУметь: анализировать базы данных, синтезировать информацию\nВладеть навыками командной работы при решении проблемных ситуаций \n', 'Осипова Ирина Михайловна', 4, 1, 59, NULL, NULL, NULL, NULL, NULL, NULL),
(363, NULL, NULL, 'Создание корпоративной программы благополучия сотрудников «Well-being» (мобильная версия)', 15, 'Применение знаний и получение навыков в организации работы предприятия', 'Забота о благополучии сотрудников – это выгодные инвестиции в управление производительностью, повышение конкурентоспособности и корпоративной культуры компании. Подобные стратегии полезны для крупного, малого и среднего бизнеса, который нацелен привлекать и удерживать ценные кадры, а также максимально раскрывать их потенциал в работе на благо компании.', 3, '2023-02-06', '2023-06-25', '', 'АО «ЭнСер»', NULL, 'Создание мобильного приложения по Well-being в стиле Agile, с возможностью дополнения инициатив в виде конструктора', 'Знания: знать методы сбора, анализа, систематизации, хранения информации предприятия\nУмения: уметь, в соответствии с поставленной задачей, выявлять критерии оценки и отбора информации\nНавыки: владеть способами получения информации из различных источников\n', 'Наумова Татьяна Александровна', 4, 1, 60, NULL, NULL, NULL, NULL, NULL, NULL),
(364, NULL, '2022-06-24 08:13:17', 'Модель управления стратегическими научными проектами. Компетентностная модель  ключевого исследователя (PI). Предпринимательские качества у научных работников', 15, 'Разработка модели управления стратегическими проектами исследовательской политики.  Исследование влияния предпринимательских качеств на профессиональные достижения, научных работников.', 'Проблема заключается в противоречии между возрастающим значением инновационных технологий и сохраняющейся слабостью механизмов коммерциализации знаний и инновационных разработок в России. Образовательные и научные организации чаще всего сталкиваются с низким уровнем обладания предпринимательскими способностями, которые к тому же неравномерно распределены среди научных работников. В этих условиях важно оценить влияние качеств ключевых исследователей на  научные результаты. Выстроить работающую  модель управления научными проектами.', 2, '2023-02-06', '2023-06-25', NULL, 'Проректор по научной работе Кононов А.М.', NULL, 'Апробированная модель управления стратегическими проектами в рамках исследовательской политики. Практические рекомендации по развитию определённых soft skills у различных категорий научных работников (ключевых исследователей).', 'Знания: методов проведения исследований, понятий предмета и объекта исследования\r\nУмения: постановка цели и задач исследования, определение предмета и объекта, актуальности темы исследования, выдвижение и проверка гипотезы исследования\r\nНавыки: подбор и изучение источников, обработка и анализ полученной информации, формирование результата исследования', 'Чернышенко Марина Сергеевна', 4, 1, 61, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(365, NULL, NULL, 'Стратегическое управление ключевыми потенциалами развития территориальных социально-экономических систем ', 15, 'Стратегическое управление ключевыми потенциалами развития территориальных социально-экономических систем ', 'Стратегия необходима, поскольку будущее в основном непредсказуемо, абсолютной определенности относительно будущего нет. Современный темп изменений во внешней среде, увеличение количества знаний и информационных потоков настолько велики, что планирование стратегии представляется единственным способом формального прогнозирования будущих проблем и возможностей. \nОсновой развития территориальной социально-экономической системы выступает ее потенциал, представляющий собой совокупные возможности, способности, скрытые не реализованные резервы экономической системы. При этом стратегическое управление предполагает выбор из всей совокупности структурных составляющих потенциала развития территориальной социально-экономической системы ключевых, концентрация на которых позволит достичь максимальных долгосрочных результатов с учетом ограниченных ресурсов территории\n', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Стратегия развития территориальной социально-экономической системы', 'Знания: знать основные цели, задачи и функции стратегического планирования и управления.\nУмения: сопоставлять потенциальные возможности развития территориальных социально-экономических систем.\nНавыки: навыки использования методов разработки и принятия управленческих решений.\n', 'Баяскаланова Туяна Александровна ', 4, 1, 62, NULL, NULL, NULL, NULL, NULL, NULL),
(366, NULL, NULL, '«Продвижение ИРНИТУ в социальных сетях»', 15, 'Продвижение социальных сетей ИРНИТУ среди потенциальной (абитуриентов) и существующей (студентов) целевой аудитории', 'Разработка развлекательных, познавательных и научных материалов в социальных сетях ИРНИТУ. ', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Короткометражные повторяющиеся и не повторяющиеся видеопередачи (выпуски), юмористического и познавательного содержания, призванные привлекать внимание целевых и потенциальных целевых групп. ', 'Знания: получает новые знания о сути и ходе реализации проекта, о его специфических свойствах и способах работы с видеоматериалом. \nУмения: использовать полученные навыки в ходе обучения для создания качественного видеоконтента;\nНавыки: Способен создавать  качественный развлекательный или образовательный продукт, востребованный обществом и индустрией. \n', 'Другова Елена Сергеевна', 4, 1, 63, NULL, NULL, NULL, NULL, NULL, NULL),
(367, NULL, NULL, 'Зеленый университет', 15, '', 'Путем информирования, практических действий, журналистских расследований, других форм привлечения внимания к экологическим проблемам и практикам экоповедения, формировать у студентов и преподавателей осознанные действия, направленные на сохранение окружающей среды', 2, '2023-02-06', '2023-06-25', '', 'Министерство по молодежной политике в Иркутской области', NULL, 'Проведение 1 флэшмоба, 1 экологической акции, не менее 5 освещений в СМИ, 3 показов кинопрограмм, 2 расследования экологических практик', 'Знания: практическое освоение предметных дисциплин по основам журналистской деятельности, операторского мастерства,  сценарного и режиссерского мастерства и др.; новые знания о сути и ходе реализации проекта, о его специфических свойствах и способах работы с видеоматериалом. \nУмения: использовать полученные навыки в ходе обучения для создания журналистских продуктов:\nспециальное событие для СМИ; проведение пресс-конференций, круглых столов; создание  видеосюжетов и роликов.\nНавыки: способность формировать образ и осознанно внедрять его в реальную жизнь с помощью медийных инструментов. \n', 'Бельская Ольга Герасимовна', 4, 1, 64, NULL, NULL, NULL, NULL, NULL, NULL),
(368, NULL, NULL, 'Создание периодического еженедельного студенческого видеоконтента «InfoHours» в соцсетях', 15, '', 'Сформулировать взгляд молодежи на актуальные события/явления и представить его ьв виде регулярных еженедельных выпусков коротких видео в соцсетях', 2, '2023-02-06', '2023-06-25', '', 'Министерство по молодежной политике в Иркутской области', NULL, 'Размещение студенческого видеоконтента в соцсетях не менее 2 выпусков в неделю с количеством подписчиков не менее 300 человек и количеством просмотров каждого ролика не менее 50. ', 'Знания: практическое освоение предметных дисциплин по основам журналистской деятельности, операторского мастерства,  сценарного и режиссерского мастерства и др.; новые знания о сути и ходе реализации проекта, о его специфических свойствах и способах работы с видеоматериалом. \nУмения: использовать полученные навыки в ходе обучения для создания качественного видеоконтента.\nНавыки: способность создавать качественный содержательный и развлекательный продукт, востребованный обществом и индустрией. \n', 'Бельская Ольга Герасимовна', 4, 1, 65, NULL, NULL, NULL, NULL, NULL, NULL),
(369, NULL, NULL, 'Социальный студенческий проект «Вам не стыдно?»', 15, 'Привлечение внимания представителей общественности (молодежи и взрослой аудитории) к актуальным проблемам общества.', 'Создание короткометражных видеосюжетов посвященных острым социальным проблемам современного общества всех возрастов.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Короткометражные  выпуски на социальную тему, призванные привлекать внимание целевых и потенциальных целевых групп. ', 'Знания: получает новые знания о сути и ходе реализации проекта, о его специфических свойствах и способах работы с видеоматериалом. \nУмения: использовать полученные навыки в ходе обучения для создания качественного видеоконтента;\nНавыки: Способен создавать  качественный развлекательный или образовательный продукт, востребованный обществом и индустрией. \n', 'Другова Елена Сергеевна', 4, 1, 67, NULL, NULL, NULL, NULL, NULL, NULL),
(370, NULL, NULL, 'Современное уголовное судопроизводство: проблемы и перспективы развития', 15, 'Целью проекта является: привлечь внимание к уголовному судопроизводству, установить проблемы уголовно-процессуального права и предложить пути решения, проанализировать деятельность по расследованию и разрешению уголовных дел в современных условиях, в том числе в условиях цифровизации', 'Проект «Современное уголовное судопроизводство: проблемы и перспективы развития» представляет собой углубленное изучение уголовного судопроизводства, проблем современного состояния норм уголовно-процессуального права, совершенствование правовой регламентации отдельных институтов уголовно-процессуального права в современных условиях, в том числе в условиях цифровизации', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Или статья (опубликованная или подготовленная к публикации), или тезисы конференции (защищенные на конференции, опубликованные или подготовленные к публикации) по теме проекта. ', 'Знания: \nВ ходе выполнения проекта студенты получат знания в сфере уголовно-процессуального права, расследования и разрешения уголовных дел по существу\nУмения:\nВ ходе работы над проектом студенты приобретут умения планирования и контроля личного времени, составления содержания научно-исследовательской работы, формулирования проблемы\nНавыки:\nВ ходе работы над проектом студенты приобретут навыки работы в команде, анализа и подбора научной литературы, анализа судебной практики\n', 'Днепровская Марина Анатольевна', 4, 1, 68, NULL, NULL, NULL, NULL, NULL, NULL),
(371, NULL, NULL, 'Защита трудовых прав граждан', 15, 'Совместная реализация задач защиты трудовых прав и интересов работников организаций', 'В ходе проекта студенты будут участвовать в интервьюировании, консультировании граждан. В подготовке методических, информационных документов, в размещении их на сайте Государственной инспекции труда Иркутской области', 3, '2023-02-06', '2023-06-25', '', 'Государственная инспекция труда Иркутской области', NULL, 'Сайт Государственной инспекции труда Иркутской области, консультирование граждан', 'Знает инструменты поиска информации.\nУмеет использовать инструменты поиска информации.\nВладеет навыками поиска информации.\nУмеет выделить из массива информации ключевые моменты.\nВладеет навыками анализа информации с целью выделения требуемого знания.\nУмеет использовать различные инструменты поиска и анализа информации.\nВладеет навыками на основе полученной первичной информации сформировать комплексное понимание предмета изучения.\nВладеет навыками выполнения системного анализа полученной информации, выделения  «дефицитов» знаний  и формулирования  запроса   на поиск новой информации.\n', 'Красноярова Елена Викторовна', 4, 1, 69, NULL, NULL, NULL, NULL, NULL, NULL),
(372, NULL, NULL, 'Совершенствование законодательства и юридической практики в сферах геологоразведки, добычи полезных ископаемых, вторичного использования ресурсов', 15, 'Обобщение правового регулирования и результатов правоприменительной деятельности, выработка научно-практических рекомендаций по совершенствованию законодательства и юридической практики в сферах геологоразведки, добычи полезных ископаемых, вторичного использования ресурсов, в том числе в интересах субъектов малого и среднего предпринимательства , осуществляющих (намеревающихся осуществлять) деятельность по разработке техногенных месторождений, вторичного использования ресурсов, а также юниорных компаний', 'Проект имеет междисциплинарный характер, направлен на формирование у обучаемых 3 и 4 курса навыков самостоятельного решения отдельной прикладной юридической задачи, выделенной в рамках общей обширной темы, над которой работает весь проектный коллектив. Тренируется умение правильно определять межпредметные связи, увязывать теоретические аспекты юриспруденции с потребностями правовой практики, работать в команде, ориентироваться в сложном комплексном массиве нормативных правовых актов для поиска путей совершенствования правового регулирования и правоприменения. Сопутствующее умение: формулировать полученный результат в тексте – а) нормативно-правовом; б) научном.\nПроект имеет смысловые и компетенционные связи со стратегическим проектом i.GeoDesign, реализуемым ИРНИТУ в рамках программы \"Приоритет 2030\" (юридическое обеспечение умной цифровой геологии, вторичного использования природных ресурсов, формирования юниорного бизнеса).\nМожно выделить следующие основные проблемы, задачи по разрешению которых ставятся перед участниками проектной группы:\n1) Проблема внесения изменений и дополнений в ФЗ «О недрах» и ряд смежных с ним нормативных правовых актов с целью создания правовых условий для разработки техногенных отложений;\n2) Проблема совершенствования законодательства, стимулирующего предпринимательскую активность в рассматриваемой сфере и создающего условия для вторичного использования ресурсов, в том числе добычи и использования мореной древесины, использования отходов горно-промышленного производства в качестве вторичных минеральных ресурсов, использования шлако-зольных отходов энергетики, использования отходов лесопереработки, использования вторичного сырья в производстве строительных материалов.\n3) Проблема развития правовой базы создания и деятельности юниорных компаний (малых геологоразведовательных компаний с элементом рискового бизнеса, работающих в сфере поиска и освоения малых месторождений полезных ископаемых).\n', 3, '2023-02-06', '2023-06-25', '', '', NULL, '1) Проекты федеральных законов и иных нормативных правовых актов – могут быть внесены в качестве законотворческих инициатив в соответствующие органы государственной власти. На первоначальном этапе могут быть представлены для участия в ежегодном конкурсе «Моя законотворческая инициатива», проводимом Государственной Думой ФС РФ совместно с НС «Интеграция». Решают практические задачи совершенствования законодательства в сферах геологоразведки, добычи полезных ископаемых, вторичного использования ресурсов, повышения эффективности правового регулирования, в том числе в интересах субъектов малого и среднего предпринимательства , осуществляющих (намеревающихся осуществлять) деятельность по разработке техногенных месторождений, использованию вторичных ресурсов, а также юниорных компаний.\n2) Научно-практические рекомендации по юридическому стимулированию предпринимательской активности, а также по совершенствованию правоприменительной  практики органов государственного управления. Могут быть представлены в виде: 1)  серии выступлений на научных форумах и научных публикаций студентов – участников проекта; 2) итогового обзора научно-практических  результатов проекта, направленного в заинтересованные органы исполнительной власти. Решают практические задачи поддержки малого и среднего предпринимательства, а также совершенствования правоприменительной (в том числе разрешительно-лицензионной и контрольно-надзорной) практики в сферах геологоразведки и добычи полезных ископаемых, повышения ее эффективности, в том числе в интересах субъектов малого и среднего предпринимательства , осуществляющих (намеревающихся осуществлять) деятельность по вторичному использованию ресурсов, разработке техногенных месторождений, юниорных компаний.\n', 'Знания: \n– современных инструментов поиска информации;\n– сущности проекта и его основных этапов;\n– основных требований  к представлению результатов проекта;\n– норм и способов осуществления социального взаимодействия;\n– основных принципов планирования и организации своей деятельности.\nУмения: \n– использовать инструменты поиска информации, прежде всего справочные правовые системы, базы судебных решений, базы статистических данных, системы геологической информации, официальные информационные системы органов государственного управления, каталоги научных библиотек; \n– выделить из массива информации ключевые моменты, необходимые для решения конкретной задачи, разрешения проблемы;\n– предварительно спланировать проект и заполнить паспорт, отражающий ключевые этапы жизненного цикла проекта;\n– спланировать и реализовать проект с учетом ресурсных ограничений и требований к результату  проекта;\n– подготовить результаты исследования, осуществленного в рамках проекта;\n– критически оценивать полученные результаты;\n– определять круг задач и решать их в соответствии с ролевой позицией в проектной группе;\n– формулировать личные цели;\n– осуществлять самооценку, выполнять критический анализ и формулировать перечень недостающих  знаний, необходимых для достижения целей.\n\nНавыки:\n– поиска необходимой для решения практических задач информации в справочных правовых системах, базах судебных решений, системах геологической информации, официальных информационных системах органов государственного управления; научных библиотеках; базах статистических данных и иных источниках;\n- анализа информации, обнаружения и использования ее элементов, необходимых для решения конкретной задачи, разрешения проблемы;\n– формирования комплексного понимания предмета изучения на основе полученной первичной информации;\n– системного анализа полученной информации, выделения и восполнения «дефицитов» знаний, формулирования  запросов  на поиск новой информации в соответствии с поставленной задачей;\n– презентации проекта и его результатов;\n– самоанализа, адекватной оценки личного вклада в достигнутые результаты;\n– определения и постановки задач, их решения в соответствии с ролевой позицией в проектной группе;\n– социального взаимодействия как с членами команды, так и с внешними стейкхолдерами;\n– рефлексии;\n– четкого формулирования запроса на поиск новых знаний;\n– итоговой оценки своего вклада в реализованный проект, работы над недостатками.\n', 'Мушинский Михаил Адеилович', 4, 1, 71, NULL, NULL, NULL, NULL, NULL, NULL),
(373, NULL, '2022-08-30 03:52:24', 'Проблемы применения гражданского законодательства', 15, 'Отработка практических навыков толкования и применения норм гражданского законодательства в области вещного, обязательственного и корпоративного права', 'Выработка навыков правовой оценки ситуаций и практического применения гражданского законодательства, а также использования материалов судебной практики;  выработка навыков составления гражданско-правовых документов; формирование навыков подготовки квалификационных и научных работ по цивилистической тематике', 3, '2023-02-06', '2023-06-25', NULL, NULL, NULL, 'Опубликование научных статей \r\nВыступление на научных конференциях\r\nРазработка практического пособия по актуальным вопросам применения гражданского законодательства', 'Знания: закономерностей гражданско-правового регулирования в Российской Федерации и в зарубежных странах; правил применения нормативных правовых актов и реализации норм материального права, правил подготовки юридических документов;\r\nУмения: правильно определять факты, события и обстоятельства с целью их квалификации; использовать различные способы толкования норм гражданского законодательства; анализировать и правильно применять гражданско-правовые нормативные акты;\r\nНавыки: владения юридической терминологией; методикой анализа правоприменительной практики; методикой разрешения правовых проблем и коллизий; самостоятельной научной работы и овладение методикой проведения исследований при решении правовых вопросов', 'Пахаруков Александр Анатольевич', 4, 1, 72, NULL, NULL, NULL, NULL, NULL, NULL),
(374, NULL, '2022-08-30 09:43:40', 'Совершенствование уголовно-исполнительного законодательства', 15, 'Проведение индивидуальных углубленных сравнительных исследований цивилистической доктрины и законодательства о банкротстве стран ближнего зарубежья', 'без описания', 3, '2023-02-06', '2023-06-25', NULL, NULL, NULL, 'Опубликование научных статей \r\nВыступление на научных конференциях\r\nРазработка практического пособия по актуальным вопросам применения законодательства о банкротстве', 'Знания: основные направления и тенденции развития законодательства о банкротстве, учения и концепции в этой научной сфере, их преемственность и эволюцию, содержание работ наиболее известных юристов;  основные закономерности возникновения, функционирования и развития конкурсных правоотношений;\r\nУмения: оперативно разрешать правовые проблемы, возникающие при реализации процедур банкротства;\r\nНавыки:  методологией разрешения правовых коллизий и пробелов в нормах права и нормативно - правовых актах.', 'Степаненко Юрий Сергеевич', 4, 1, 73, NULL, NULL, NULL, NULL, NULL, NULL),
(375, NULL, NULL, 'Правоохранительная деятельность в информационном пространстве ', 15, 'Выявление и анализ проблем правового регулирования в сфере использования информационных технологий, а также информационный сетей (Интернет, социальные сети и др.) правоохранительными органами при выявлении административных правонарушений и преступлений, а также иных нарушений законности  ', 'В деятельности правоохранительных органов актуальность приобретает мониторинг социальных сетей на предмет выявления преступлений и правонарушений в различных сферах жизнедеятельности общества. Данная деятельность может являться эффективной в области борьбы с преступлениями и правонарушениями. Однако большие вопросы вызывает законодательное закрепление такой деятельности. Федеральные законы и иные нормативные акты, регламентирующие деятельность правоохранительных органов, в частности, полиции, ФСБ России, Прокуратуры, не содержат норм, которые позволяли бы осуществлять мониторинг социальных сетей на предмет выявления преступлений и административных правонарушений. Необходимо подготовить предложения для законодателя по внесению изменений в Федеральные законы «О полиции», «О прокуратуре Российской Федерации», «О Федеральной службе безопасности» и др. Только внесение изменений в части применения информационных технологий в указанной сфере позволит на законных основаниях использовать мониторинг в социальных сетях в практической деятельности правоохранительных органов. Таким образом, необходимо чтобы такая деятельность осуществлялась в строгом соответствии законодательству', 2, '2023-02-06', '2023-06-25', '', 'ВС ЛУ МВД России на транспорте (консультации и оценка результата проекта), \nВсероссийский конкурс «Моя законотворческая инициатива», участие  в конкурс е, представление и защита промежуточных итогов проекта \n', NULL, 'Конкретные предложения, которые будут выработаны в процессе реализации проекта, направлены на эффективное осуществление деятельности правоохранительных органов в сфере мониторинга социальных сетей для выявления преступлений и административных правонарушений.', 'Знать: об имеющихся информационных ресурсах и  технологиях, которые используются в разных видах юридической деятельности;\nУметь:  работать с официальным интернет-порталом правовой информации pravo.gov.ru, с СПС «Гарант», СПС «Консультант Плюс», ГАС «Правосудие», с официальными сайтами органов государственной власти, с библиотечными юридическими ресурсами, пользоваться полученной с их помощью информацией;\nВладеть: навыками работы с различными информационными ресурсами.\n', 'Самусевич Алексей Геннадьевич', 4, 1, 74, NULL, NULL, NULL, NULL, NULL, NULL),
(376, NULL, NULL, 'Защита прав потребителей', 15, 'Совершенствование законодательства в сфере защиты прав потребителей', 'Многочисленные цели государственной политики в сфере защиты прав потребителей определены Правительством Российской Федерации в Стратегии государственной политики РФ в области защиты прав потребителей на период до 2030 года и включают в себя помимо традиционных и инновационные направления, например, электронная торговля. Российская Федерация и другие страны усиливает правовое обеспечение прав потребителя, которое для бизнеса между тем выступает в качестве одного из серьезных пределов свободы профессиональной экономической деятельности. Потребительский договор коррелирует как с традиционной для коммерческого (торгового) права категорией «односторонней торговой сделкой», так и современным выделением b2c-договоров. Одновременно с этим отношения с участием потребителя подвержены сильному публичному регулированию, а устанавливаемые правила становятся неотъемлемой частью государственной регуляторной политики во всем мире, взаимодействующей не только с договорным правом, но и с антимонопольным законодательством и актами технического регулирования. В соответствии со Стратегией развития информационного общества в РФ на 2017 – 2030 гг., утвержденной Президентом страны и соответствующим распоряжением Правительства РФ от 28.07.2017 №1632-р, она затрагивает все сферы экономической жизни, в том числе и сферу потребления. В связи с вышеизложенным, отмечаются значительные пробелы в законодательстве в части правового регулирования отношений с участием потребителей.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Научная статья, рекомендации для потребителей', 'Знания: \nЗнает инструменты поиска информации. \nЗнает основные требования  к представлению результатов проекта.\nУмеет подготовить результаты.\nЗнает основные ресурсные ограничения проекта.\nЗнает нормы и способы социального взаимодействия.\nЗнает основные принципы планирования и организации своей деятельности. \n\nУмения:\nУмеет выделить из массива информации ключевые моменты.\nУмеет использовать различные инструменты поиска и анализа информации.\nУмеет использовать основные инструменты планирования и реализации проекта с учетом основных этапов  жизненного цикла проекта.\nУмеет спланировать и реализовать проект с учетом ресурсных ограничений и требований к результату  проекта.\nУмеет критически оценивать полученные результаты.\nУмеет решать задачи в соответствии с ролевой позицией.\nУмеет формулировать личные цели.\nУмеет планировать и организовывать свою деятельность на основе приоритетов и поставленных целей.\nУмеет выполнять критический анализ и сформулировать перечень недостающих  знаний, необходимых для достижения целей.\nУмеет пользоваться основными инструментами организации рефлексии.\n\nНавыки:\nВладеет навыками поиска информации.\nВладеет навыками анализа информации с целью выделения требуемого знания.\nВладеет навыками на основе полученной первичной информации сформировать комплексное понимание предмета изучения.\nВладеет навыками  выполнения системного анализа полученной информации, выделения  «дефицитов» знаний  и формулирования  запроса   на поиск новой информации.\nВладеет навыками презентации результатов проекта.\nВладеет навыками самоанализа и может оценить личный вклад в достигнутых результатах.\nВладеет навыками определения и постановки задач.\nВладеет навыками рефлексии.\nВладеет навыками четкого формулирования запроса на поиск новых знаний.\n', 'Степаненко О.Г', 4, 1, 75, NULL, NULL, NULL, NULL, NULL, NULL),
(377, NULL, NULL, 'Цифровые криминалистические лаборатории', 15, 'Применение теоритических знаний в практической деятельности', 'Цифровая криминалистика широко используется в уголовном праве, уголовном процессе, криминалистике, гражданском процессе, судебной медицине и психиатрии, теории судебных экспертиз. Создание криминалистического полигона с минилабораториями, в которых, будет происходить моделирование преступной ситуации, проведение анализа места преступления, выявление фактов и обстоятельств, сбор доказательств, исследование доказательств и т.д. В том числе возможность ознакомления абитуриентов с направлением юриспруденции (профориентационная школа), проведение мастер-классов.', 3, '2023-02-06', '2023-06-25', '', 'грант ИРНИТУ', NULL, 'Криминалистическая лаборатория', 'Умеет выделить из массива информации ключевые моменты.\nВладеет навыками анализа информации с целью выделения требуемого знания.\n', 'Туркова Валентина Николаевна', 4, 1, 76, NULL, NULL, NULL, NULL, NULL, NULL),
(378, NULL, NULL, 'Осуществление права государственной и муниципальной собственности  в условиях развития современного гражданского законодательства', 15, 'Повышение уровня профессиональной грамотности в  сфере осуществления права государственной и муниципальной собственности  в условиях современного гражданского законодательства', 'Проводимая реформа гражданского законодательства позволила выявить целый ряд проблем, как теоретического, так и  правоприменительного характера, непосредственно связанных с институтом публичной собственности. Наметившаяся трансформация вещных правоотношений является, в том числе  результатом развития и модернизации  экономических отношений с участием государства и муниципальных образований. Вступившие в силу изменения Гражданского Кодекса Российской Федерации   заметно актуализировали вопросы, связанные с осуществлением права публичной собственности: иначе сформулированы правила в отношении неделимых и сложных вещей, в гражданский оборот введен новый объект в виде единого недвижимого комплекса, который, обладая признаками непотребляемости и неделимости способен увеличить доходную часть государственных и муниципальных бюджетов. Появление новых механизмов призвано обеспечить провозглашенную законодателем самостоятельность муниципальных образований, и как следствие, эффективное осуществление права муниципальной собственности. Вместе с тем, изменение структурных элементов возникающих при этом вещных правоотношений, вызывает потребность в дальнейшем их исследовании с целью разработки теоретических предложений, направленных на совершенствование норм гражданского законодательства и правоприменительной практики. \nЯвляясь гражданско-правовым институтом, публичная собственность регулируется нормами различной отраслевой принадлежности, в совокупности составляющими комплексный законодательный институт. Особенность правовой регламентации неизбежно влечет за собой  возникновение коллизий, устранение которых требует теоретического осмысления и, как результата – научно обоснованных рекомендаций по совершенствованию действующего законодательства. При всей важности прочих отраслевых научных изысканий наиболее плодотворный результат исследования может быть получен путем изучения данных отношений через призму гражданского права в виду содержательного их наполнения и правовой природы.\nБолее того, ВУЗ, в котором обучаются студенты по своей организационно-правовой форме является учреждением, а это именно тот субъект имущественных отношений, который наделяется публичной собственностью. \n', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Учебное пособие, научная статья', 'Знания: Знать инструменты поиска информации. \nУмения: Уметь использовать инструменты поиска информации, выделить из массива информации ключевые моменты.\nНавыки: Владеть навыками анализа информации с целью выделения требуемого знания, навыками на основе полученной первичной информации сформировать комплексное понимание предмета изучения, навыками  выполнения системного анализа полученной информации, выделения  «дефицитов» знаний  и формулирования  запроса   на поиск новой информации\n', 'Чердакова Лариса Анатольевна', 4, 1, 77, NULL, NULL, NULL, NULL, NULL, NULL),
(379, NULL, NULL, 'Оценка эффективности инвестиционного проекта для развития туристического бизнеса  в регионе(на примере строительства базы отдыха с агронаправленностью)', 15, 'Оценки эффективности инвестиционного проекта  в целях привлечения банковского кредитования для развития туристического бизнеса региона (на примере строительства базы отдыха  с агронаправленностью)', 'В условиях экономической нестабильности и недостаточности собственных финансовых ресурсов у многих экономических субъектов возникает необходимость увеличения объёмов банковского кредитования для развития туризма в Иркутской области. Со стороны бизнеса и кредитных организаций для развития   туристического бизнеса и привлечения кредитных ресурсов необходимо выявление особенностей расчёта эффективности инвестиций в туристическом бизнесе', 1, '2023-02-06', '2023-06-25', '', '', NULL, 'Продуктовым результатом проекта должен стать документ, содержащий  информационный обзор рынка туристических услуг и  оценки эффективности инвестиций с целью привлечения банковского кредитования для  развития туристической отрасли региона', 'Знания: понятие и основные этапы процесса инвестиционного банковского кредитования\nУмения: выявлять инвестиционные риски с учетом особенностей развития региона\nНавыки:  навыками анализа экономической эффективности инвестиционного проекта с учетом региональных рисков\n', 'Репинский Олег Дмитриевич', 4, 1, 78, NULL, NULL, NULL, NULL, NULL, NULL),
(380, NULL, NULL, 'Сравнительный анализ деятельности страховых компаний на рынке страховых услуг', 15, 'Проведение анализа рынка страховых услуг с использованием комплекса показателей деятельности страховых компаний для определения результативности их деятельности.', 'В ходе осуществления проектной деятельности обучающиеся проводят мониторинг рынка страховых услуг; отбирают несколько страховых компаний для проведения сравнительного анализа; изучают и практически применяют систему показателей для выявления слабых и сильных сторон участников выборки; разрабатывают мероприятия для преодоления проблем и определения направлений дальнейшего развития страховых компаний.', 1, '2023-02-06', '2023-06-25', '', '', NULL, 'Продуктовым результатом проекта должен стать документ, содержащий характеристику страхового рынка региона; комплекс количественных и качественных показателей, используемых для сравнительного анализа нескольких страховых компаний, работающих на территории Иркутской области; мероприятия по преодолению возникших проблем и совершенствованию деятельности страховщиков на рынке страховых услуг. Документ может быть использован страховыми компаниями и их внутренними структурными подразделениями, предпринимательскими структурами и т.п.\nВ документе должны быть подробно изложены характеристики рынка страховых услуг в регионе; определены главные игроки; определены и представлены направления,  также система показателей, используемых при анализе; проведены расчеты на примере деятельности нескольких страховых компаний.\n', 'Знать: особенности страхового рынка; основные направления анализа страховой деятельности\nУметь: проводить мониторинг рынка страховых услуг; определять и рассчитывать основные показатели деятельности страховщиков  \nВладеть: приемами сравнительного; анализа основами принятия эффективных решений, направленных на развитие страхового бизнеса\n', 'Юшина Юлия Александровна', 4, 1, 79, NULL, NULL, NULL, NULL, NULL, NULL),
(381, NULL, NULL, 'Оценка эффективности инвестиционного проекта для развития туристического бизнеса  в регионе (на примере строительства горнолыжного курорта)', 15, 'Оценки эффективности инвестиционного проекта  в целях привлечения банковского кредитования для развития туристического бизнеса региона (на примере строительства горнолыжного курорта)', 'В условиях экономической нестабильности и недостаточности собственных финансовых ресурсов у многих экономических субъектов возникает необходимость увеличения объёмов банковского кредитования для развития туризма в Иркутской области. Со стороны бизнеса и кредитных организаций для развития   туристического бизнеса и привлечения кредитных ресурсов необходимо выявление особенностей расчёта эффективности инвестиций в туристическом бизнесе', 1, '2023-02-06', '2023-06-25', '', '', NULL, 'Продуктовым результатом проекта должен стать документ, содержащий  информационный обзор рынка туристических услуг и  оценки эффективности инвестиций с целью привлечения банковского кредитования для  развития туристической отрасли региона', 'Знания: понятие и основные этапы процесса инвестиционного банковского кредитования\nУмения: выявлять инвестиционные риски с учетом особенностей развития региона\nНавыки:  навыками анализа экономической эффективности инвестиционного проекта с учетом региональных рисков\n', 'Репинский Олег Дмитриевич', 4, 1, 80, NULL, NULL, NULL, NULL, NULL, NULL),
(382, NULL, NULL, 'Разработка продуктовой линейки для страховой компании', 15, 'Проведение модернизации продуктового ряда страховых услуг для повышения конкурентоспособности и эффективности деятельности страховой компании', 'В ходе осуществления проектной деятельности обучающиеся проводят мониторинг и сегментацию рынка страховых услуг РФ и региона; изучают ассортиментные предложения страховых компаний; определяют достоинства и недостатки действующей системы маркетинга конкретной страховой компании; проводят модернизацию продуктового ряда и формируют ассортиментное предложение с целью повышения результирующих показателей деятельности страховщика', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Продуктовым результатом проекта должен стать документ, содержащий анализ рынка страховых продуктов и ассортиментных предложений страховщиков, а также  конкретные предложения по модернизации продуктового ряда страховой компании. Документ может быть использован страховыми компаниями и другими экономическими субъектами региона (банками, заемщиками, сопряженными предпринимательскими структурами).\nВ документе должна быть подробно изложена формализованная процедура реализации модернизированных страховых продуктов в виде базовых существенных условий (потенциальных клиентов, объектов страхования, страховых случаев, страховых сумм, тарифных условий и т.д.)\n', 'Знать: теоретические основы маркетинга; основные виды и характеристики страховых продуктов; основные условия страхового договора; показатели деятельности страховой компании и страховых операций;  \nУметь: проводить мониторинг страхового рынка и его составляющих; проводить анализ эффективности деятельности страховых компаний и страховых операций (по видам страхования); \nВладеть: приемами маркетинговых исследований; навыками составления страховых договоров и разработки практических рекомендаций для принятия эффективных решений на уровне страховой компании\n', 'Юшина Юлия Александровна', 4, 1, 81, NULL, NULL, NULL, NULL, NULL, NULL),
(383, NULL, NULL, 'Оценка делового климата Китайской Народной Республики', 15, 'Создание информационного контента о деловом климате КНР, с целью разработки рекомендаций для экспортеров по доступу на рынок Китая. ', 'Оценка возможностей и перспектив внешнеэкономических связей России с Китайской Народной Республикой во многом зависит от наличия и анализа информации об особенностях ведения бизнеса в стране, её рынков, товаров, услуг, обычаев, законодательства. Для эффективности внешнеэкономической деятельности, необходима характеристика делового климата Китая. Проблема состоит в том, что информация для анализа делового климата Китая находится в разных источниках и постоянно меняется в соответствии с современными условиями, требует знаний китайского языка для доступа к первичной информации.\nДанный проект направлен на создание информационного контента, включающего: обзор нормативно-правовой базы в области государственного регулирования внешнеэкономической и инвестиционной деятельности в КНР; информации о защите прав экспортеров;  рекомендации по доступу на рынок Китая; о возможностях проверки деловой репутации китайских компаний; специфические особенности ведения бизнеса в Китае, включая культурные аспекты и деловые обычаи. Анализ данной информации позволит оценить деловой климат Китайской Народной Республики, с целью принятия решений о возможностях и перспективах внешнеэкономической деятельности для российских контрагентов.\n', 1, '2023-02-06', '2023-06-25', '', '', NULL, 'Публикация статей о деловом климате Китайской Народной Республики.', 'Знания: основы внешнеэкономической деятельности, нормативные документы её регламентирующие и формы расчетов по международным сделкам;\nУмения: использовать нормативно-правовые акты для составления внешнеэкономических контрактов;\nНавыки: подбора в интересах клиентов условий договоров по внешнеэкономическим контрактам и обоснования форм расчетов по международным сделкам.\n', 'Гафарова Елена Владиславовна', 4, 1, 82, NULL, NULL, NULL, NULL, NULL, NULL),
(384, NULL, NULL, 'Деятельность банков и их структурных подразделений, действующих на территории Иркутской области, по привлечению вкладов населения в условиях стабилизации российской экономики', 15, 'Проанализировать стратегию работы кредитных организаций, действующих на территории Иркутской области, по привлечению вкладов населения в условиях санкций со стороны стран Запада после начала специальной военной операции российских вооруженных сил на территории Украины', 'При реализации студентами третьего курса, группы ФКБ-19-1 Института экономики, управления и права проекта «Модернизация продуктового ряда вкладов граждан, привлекаемых коммерческим банком (структурным подразделением) на территории Иркутской области» были собраны и проанализированы  данные по условиям привлечения вкладов на селения по состоянию на 1 октября 2021 года, на 1 января 2022 года и 1 апреля 2022 года. За указанный период процентные ставки в банках на территории Иркутской области выросли с 6-7 % до 20 % годовых. Столь резкий рост процентных ставок привел к значительному увеличению расходов коммерческих банков. В новом проекте нами предлагается проанализировать работу коммерческих банков по привлечению вкладов населения по мере нормализации ситуации в российской экономике', 3, '2023-02-06', '2023-06-25', '', 'Филиал «Иркутский» АО КБ «Солидарность». Управляющий филиалом Сергей Александрович Кошкин', NULL, 'Продуктовым результатом проекта должны стать три отчета о деятельности коммерческих банков и их структурных подразделений по привлечению вкладов населения на три отчетные даты: 1 октября 2022 года, 1 января 2023 года и 1 апреля 2023 года. Два отчета по состоянию на1 октября 2022 года, 1 января 2023 года будут носить промежуточный характер, а в отчете по состоянию на 1 апреля 2023 года будут подведены итоги работы проектной группы в течение года. Предполагается, что участники проекта в ходе его реализации будут участвовать в научно-практических конференциях, писать статьи в научные журналы. ', 'Знания: основные виды и характеристики банковских продуктов и услуг.\nУмения: рассчитывать основные показатели, характеризующие эффективность депозитных и кредитных операций, проводить мониторинг банковских продуктов и услуг.\nНавыки: владеть приемами маркетинговых исследований и принятия эффективных решений, направленных на развитие коммерческого банка, овладеть навыками установления конструктивных отношений со специалистами и руководителями курируемых членами проектной группы банков или их структурных подразделений.\n', 'Шаламов Георгий Александрович', 4, 1, 83, NULL, NULL, NULL, NULL, NULL, NULL),
(385, NULL, NULL, 'Анализ реализации внешнеэкономической деятельности России в условиях санкций и перспективы её развития.', 15, 'Исследовать состояние и перспективы развития внешнеэкономической деятельности Российской Федерации в период после введения экономических санкций ЕС и США.', 'Одним из самых жестких видов контрмер, применяемых во внешнеэкономической деятельности, являются экономические санкции. Они являются огромной угрозой безопасности станы, поскольку при их введении, сокращаются объемы экспортных и импортных поставок, рушатся логистические цепочки, закрываются производства, сужаются транспортные коридоры для международных грузов. Всё это приводит к снижению притока валютной выручки в страну и сокращению её экономического потенциала. Ограничения во внешней торговле приводят к поиску альтернативных решений во внешнеэкономической деятельности, так как внутренний межсубъектный обмен товарами и услугами не способен обеспечить оптимальных экономических показателей. Принципиально важной становится адекватная оценка разрывов спроса, производства и потенциальные способности российского бизнеса реагировать на изменение конъюнктуры отечественного и внешнего рынков. Различия в технологиях производства, структуре промежуточного и конечного потребления ресурсов, объемах создания добавленной стоимости, разветвленности и длине производственных цепочек становятся значимыми факторами как скорости выхода конкретных видов экономической деятельности на внешние рынки, так и формирования целевой поддержки конкретных видов внешнеэкономической деятельности со стороны государства. Данный проект направлен на формирование комплексного понимания современных реалий, происходящих во внешнеэкономической деятельности России в условиях санкций.', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Публикация статей о перспективах внешнеэкономической деятельности России в условиях санкций.', 'Знания: организацию и технику внешнеэкономических операций, показатели оценки экономической деятельности контрагентов, их продукции на внешнем рынке.\nУмения: анализировать экономическую деятельность контрагентов, учитывая базы данных внешних рынков\nНавыки: владеть методами оценки состояния товарно-сырьевых и финансовых рынков.\n', 'Гафарова Елена Владиславовна', 4, 1, 84, NULL, NULL, NULL, NULL, NULL, NULL),
(386, NULL, NULL, 'Оценка бюджетной самостоятельности муниципальных образований Иркутской области', 15, 'Разработка предложений по повышению бюджетной самостоятельности муниципальных образований Иркутской области', 'На современном этапе значительная часть муниципальных бюджетов, образующих финансовую основу местного самоуправления не располагают достаточным для полноценного финансирования предусмотренных расходов объемом финансовых ресурсов. Основными причинами являются неравномерное распределение источников бюджетных поступлений по уровням власти, диспропорции межбюджетных отношений в стране. В то же время местные бюджеты являются одним из главных каналов доведения конечных результатов производства до населения. Через них осуществляется распределение общественных фондов между отдельными группами населения, финансирование непроизводственной и производственной сфер. Все эти мероприятия можно реализовывать лишь при  достаточном объеме финансовых средств.', 1, '2023-02-06', '2023-06-25', '', '', NULL, 'Информационный отчет, презентация', 'Знания:\nтенденции и проблемы формирования доходов и расходов муниципальных бюджетов\nУмения:\nрассчитывать основные экономические показатели,   характеризующие исполнение бюджетов по доходам и расходам                              \nНавыки: \nвладеть приемами  анализа  основных экономических показателей бюджетов с точки зрения достижения целевых показателей\n', 'Антипин Дмитрий Алексеевич', 4, 1, 85, NULL, NULL, NULL, NULL, NULL, NULL),
(387, NULL, NULL, 'Формирование и развитие системы оценки эффективности управления местными бюджетами', 15, 'Развитие теоретических и методических основ оценки эффективности управления бюджетами муниципальных образований для разработки комплексной системы оценки, имеющей существенное значение для развития механизма управления местными бюджетами', 'Проект нацелен на разработку системного подхода к формированию оценки эффективности управления местными бюджетами, основанного на уточненных теоретических положениях, учитывающих особенности управления бюджетами муниципальных образований и методического инструментария оценки эффективности управления местными бюджетами', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Разработка методики оценки эффективности управления бюджетами муниципальных образований, системы показателей оценки эффективности, предложений по совершенствованию системы оценки эффективности управления местными бюджетами, направленных на повышение эффективности управления местными бюджетами', 'Знания: \nЗнать основные ресурсные ограничения проекта\nЗнать основные требования к представлению результатов проекта\nУмения: \nУметь выполнять критический анализ и сформулировать перечень недостающих знаний, необходимых для достижения целей\nУметь использовать различные инструменты поиска и анализа информации\nУметь критически оценивать полученные результаты\nУметь определять внутренний и внешний круг стейкхолдеров для проектной команды\nУметь определять круг задач и решать их в соответствии со своей ролевой позицией\nУметь подготовить результаты\nУметь пользоваться основными инструментами организации рефлексии\nУметь спланировать и реализовать проект с учетом ресурсных ограничений и требований к результату проекта\nНавыки: \nВладеть навыками на основе полученной первичной информации сформировать комплексное понимание предмета изучения\nВладеть навыками презентации результатов проекта\nВладеть навыками определения задач и соотнесения их с ролевыми позициями\nВладеть навыками четкого формулирования запроса на поиск новых знаний.\nВладеть навыками выполнения системного анализа полученной информации, выделения «дефицитов» знаний и формулирования запроса на поиск новой информации\nВладеть навыками самоанализа и может оценить личный вклад в достигнутых результатах\nВладеть навыками социального взаимодействия как с членами команды, так и с внешними стейкхолдерами\n', 'Бацюн Наталья Владимировна', 4, 1, 87, NULL, NULL, NULL, NULL, NULL, NULL),
(388, NULL, NULL, 'Государственные программы как инструмент стратегического управления региональным развитием', 15, 'Диагностика причин низкой результативности программно-целевого стратегического управления региональным развитием и разработка соответствующих практических рекомендаций', 'Проект нацелен на анализ основных подходов государственного программно-целевого стратегического управления региональным развитием и оценку  качественного содержания и роли действующих и принимаемых расходных обязательств в системе межбюджетных отношений «центр – регионы». ', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Разработка методического подход к оценке структурной сбалансированности государственных программ регионального развития. Указанное исследование является определенным вкладом в развитие теории государственного управления экономикой региона', 'Знания: \nЗнать основные ресурсные ограничения проекта\nЗнать основные требования к представлению результатов проекта\nУмения: \nУметь выполнять критический анализ и сформулировать перечень недостающих знаний, необходимых для достижения целей\nУметь использовать различные инструменты поиска и анализа информации\nУметь критически оценивать полученные результаты\nУметь определять внутренний и внешний круг стейкхолдеров для проектной команды\nУметь определять круг задач и решать их в соответствии со своей ролевой позицией\nУметь подготовить результаты\nУметь пользоваться основными инструментами организации рефлексии\nУметь спланировать и реализовать проект с учетом ресурсных ограничений и требований к результату проекта\nНавыки: \nВладеть навыками на основе полученной первичной информации сформировать комплексное понимание предмета изучения\nВладеть навыками презентации результатов проекта\nВладеть навыками определения задач и соотнесения их с ролевыми позициями\nВладеть навыками четкого формулирования запроса на поиск новых знаний.\nВладеть навыками выполнения системного анализа полученной информации, выделения «дефицитов» знаний и формулирования запроса на поиск новой информации\nВладеть навыками самоанализа и может оценить личный вклад в достигнутых результатах\nВладеть навыками социального взаимодействия как с членами команды, так и с внешними стейкхолдерами\n', 'Богатырева Марина Валерьевна', 4, 1, 88, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(389, NULL, NULL, 'Влияние энергетического перехода на эффективность работы предприятий ТЭК', 15, 'Разработка и практическое освоение методики оценки эффективности работы предприятий ТЭК в условиях энергетического перехода', 'Проект включает в себя теоретические и практические занятия, посвящённые энергетическому переходу и его влиянию на эффективность предприятий в сфере традиционного ТЭК', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Методика определения количественного влияния энергетического перехода на эффективность работы предприятий ТЭК', 'Знания: \nЗнать основные ресурсные ограничения проекта\nЗнать основные требования к представлению результатов проекта\nУмения: \nУметь выполнять критический анализ и сформулировать перечень недостающих знаний, необходимых для достижения целей\nУметь использовать различные инструменты поиска и анализа информации\nУметь критически оценивать полученные результаты\nУметь определять внутренний и внешний круг стейкхолдеров для проектной команды\nУметь определять круг задач и решать их в соответствии со своей ролевой позицией\nУметь подготовить результаты\nУметь пользоваться основными инструментами организации рефлексии\nУметь спланировать и реализовать проект с учетом ресурсных ограничений и требований к результату проекта\nНавыки: \nВладеть навыками на основе полученной первичной информации сформировать комплексное понимание предмета изучения\nВладеть навыками презентации результатов проекта\nВладеть навыками определения задач и соотнесения их с ролевыми позициями\nВладеть навыками четкого формулирования запроса на поиск новых знаний.\nВладеть навыками выполнения системного анализа полученной информации, выделения «дефицитов» знаний и формулирования запроса на поиск новой информации\nВладеть навыками самоанализа и может оценить личный вклад в достигнутых результатах\nВладеть навыками социального взаимодействия как с членами команды, так и с внешними стейкхолдерами\n', 'Колмаков Александр Евгеньевич', 4, 1, 89, NULL, NULL, NULL, NULL, NULL, NULL),
(390, NULL, NULL, 'Формирование системы стратегического партнёрства России и Китая.', 15, 'Проведение исследования по выявлению основных целей и направлений  формирования стратегического партнерства Российской Федерации и Китайской Народной республики в различных сферах', 'Экономическое положение любой страну мира во многом определяется объемом и структурой ее внешнеэкономических связей. Развитие независимой России объективно требует вхождения ее в мировое хозяйство на принципах равноправия и взаимной выгоды в сотрудничестве. Ее современное положение в современном экономическом мировом пространстве требует немедленного улучшения ситуации. Одним из основных направлений решения этой проблемы является расширение и укрепление внешнеэкономических связей с другими странами. \nВ качестве одного из ключевых партнеров для России является Китай, который в сложной современной экономической ситуации проявляет стремление к укреплению сотрудничества. К факторам, определяющим заинтересованность Китая в России, является укрепление его позиций в мировой экономике. Формирование стратегического партнёрства с Россией позволит сформировать баланс сил для выстраивания отношений с США и другими ведущими мировыми державами. Кроме того, Россия располагает значительными природными ресурсами. Это естественное преимущество, которое через механизмы эффективной финансовой и инвестиционной политики может быть использовано для модернизации российской экономики и укрепления   экономических отношений с Китаем.\n', 1, '2023-02-06', '2023-06-25', '', '', NULL, 'Научная публикация, аналитический обзор.', 'Знания: основных методов сбора и обработки информации с использованием современных информационных технологий.\nУмения: выполнять поиск, критический анализ и синтез информации.\nНавыки: выполнение системного анализа полученной информации, определение задач и соотнесение их с ролевыми позициями.\n', 'Литвинцев Алексей Вячеславович', 4, 1, 90, NULL, NULL, NULL, NULL, NULL, NULL),
(391, NULL, NULL, 'Анализ политики импортозамещения в России в современных условиях.', 15, 'Проведение исследования по выявлению возможности создания импортозамещающих производств в различных отраслях экономики России с целью снижения технологической и товарной зависимости от импорта', '', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Научная публикация, аналитический обзор.', 'Знания: основных методов сбора и обработки информации с использованием современных информационных технологий.\nУмения: выполнять поиск, критический анализ и синтез информации.\nНавыки: выполнение системного анализа полученной информации, определение задач и соотнесение их с ролевыми позициями\n', 'Литвинцев Алексей Вячеславович', 4, 1, 91, NULL, NULL, NULL, NULL, NULL, NULL),
(392, NULL, NULL, 'Система автоматизированного модуля для САПР предназначенного для построения технологических схем работы драглайнов', 15, 'Создание программного модуля для САПР предназначенного для построения технологической схемы работы экскаваторов драглайнов с учетом конкретных горно-геологических условий.', 'При проектировании и разработке месторождений открытым способом применяется бестранспортная технология ведения вскрышных и добычных работ с использование экскаваторов драглайнов. Особенностью применения бестранспортной технологии является построение технологических схем работы экскаваторов драглайнов в конкретных горно-геологических условиях. В настоящее время построения технологических схем осуществляется в основном с применением программного продукта AutoCAD, при этом пользователь производит построение в ручном режиме, затрачивая на это существенное количество рабочего времени.\nТаким образом, для ускорения процесса проектирования и разработки технологических схем при бестранспортной технологии рациональнее перенести большую часть операций при проектировании и моделировании технологической схемы в среду автоматизированной системы, с возможностью использования в учебном процессе и на производстве.\n', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Программный модуль для САПР предназначенный для построения технологической схемы работы экскаваторов драглайнов с учетом конкретных горно-геологических условий.', 'Знания: теоретические основы при планировании проектов с учетом ограничений ресурсов.\nУмения: реализовывать проект с учётом ограничений ресурсов и представить полученные результаты проекта.\nНавыки: Владеть методами и способами планирования проектов с учетом ограничений ресурсов, а также вариантами представления результатов проекта.\n', 'Нечаев Константин Борисович', 4, 1, 92, NULL, NULL, NULL, NULL, NULL, NULL),
(393, NULL, NULL, 'Решение проектных задач недропользования', 15, 'Умение решать реальные проблемы горного предприятия в сфере недропользования', 'Решение реальных проблем горного предприятия с учетом специфики организации работ при разработке твердых месторождений полезных ископаемых.', 2, '2023-02-06', '2023-06-25', '', 'CASE-IN', NULL, 'Развитие компетенций проектной деятельности в недропользовании с возможностью обосновывать и принимать самостоятельное решение в области добычи твердых полезных ископаемых в недропользовании', 'Знает: особенности хозяйственной деятельности предприятий горного производства и сущность их производства, основные  модели доступа к базам данных в сети Internet, технологию автоматизации проектных работ,  административной  и  управленческой деятельности недропользования.\nУмеет: применять основные информационные технологии для проектирования, управления, связи,  поиска информации для решения прикладных задач. \nВладеет:  основными приемами  применения стандартных  программных  комплексов,  составляющих  основу  информационных технологий, в том числе самостоятельно создавать техническую документацию по решению проектных задач, с учетом всех нормативных и законодательных документов\n', 'Васильев Денис Сергеевич, Гущенко Виталий Викторович', 4, 1, 93, NULL, NULL, NULL, NULL, NULL, NULL),
(394, NULL, NULL, 'Разработка бизнес-планов для недропользования', 15, 'Умение определять возможности малых предприятий сферы недропользования в существующих региональных социально-экономических условиях.', 'Создание бизнес-плана с учетом специфики организации работ при разработке месторождений твердых полезных ископаемых для получения внешнего финансирования: кредит в банке, государственные гранты и субсидии, инвесторы', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Возможность обосновать и получить внешнее финансирование (кредит в банке, государственные гранты и субсидии, инвесторы) недропользователю или помочь принять решение об инвестировании (покупке лицензий) в недропользование', 'знает формы предпринимательского дела в сфере недропользования и основы маркетинга и ценообразования продукции горного производства;\nумеет использовать информацию по правовым вопросам недропользования;\nимеет представление о возможности реализации прав гражданина РФ в формировании экономического потенциала государства, а также методику оценки эффективности работы малого предприятия.\n', 'Рославцева Юлия Геннадьевна', 4, 1, 94, NULL, NULL, NULL, NULL, NULL, NULL),
(395, NULL, NULL, 'Разработка типовых технологических схем горных работ', 15, 'Умение разрабатывать технологические схемы горных работ для различных горно-геологических условиях.', 'Создание типовых технологических схем ведения горных работ, позволяющих повысить эффективность использования горной и транспортной техники на открытых горных работах и оптимизации режимов ее работы в период эксплуатации.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Пояснительная записка с разработанными технологическими схемами для различных горногеологических условий , позволяющая  повысить эффективность использования горной и транспортной техники и оптимизировать режимы ее работы в период эксплуатации.', 'знает основные типы, характеристики и условия применения горного оборудования на разных видах работ;\nумеет устанавливать нормы выработки выемочного, транспортирующего и отвального оборудования; разрабатывать технологические схемы работы горного оборудования на основе требований правил безопасности и технической эксплуатации;\nвладеет принципами обоснования применения горного оборудования для вскрышных, добычных работ и переработки полезного ископаемого.\n', 'Рославцева Юлия Геннадьевна', 4, 1, 95, NULL, NULL, NULL, NULL, NULL, NULL),
(396, NULL, NULL, 'Исследования Глазковского некрополя различными методами съемки и создание трехмерной модели', 15, 'На основе использования различных методов дистанционного зондирования, геофизики и наземной геодезической съемки составить трехмерную модель Глазковского некрополя.', 'Проект будет реализован в несколько этапов: съемка поверхностей некрополя, анализ полученных результатов, геофизическая съемка с использованием электроразведки, создание трехмерной модели.', 2, '2023-02-06', '2023-06-25', '', '', NULL, '3D модель Глазковского некрополя', 'Знать.\nМетоды наземной и дистанционной геодезической съемки.\nУметь. \nАнализировать полученные данные различных типов съемок местности\nВладеть. \nСпособами обработки полевых измерений\nЗнать.\nМетоды геофизической съемки\nУметь.\nПроводить геофизическую съемку (электроразведку)\nВладеть.\nМетодами интерпретации данных геофизической съемки и создания трехмерных моделей объекта\n', 'Рупосов В.Л.', 4, 1, 96, NULL, NULL, NULL, NULL, NULL, NULL),
(397, NULL, NULL, 'Построение алгоритмов определения объемов горных работ с применением методов цифрового моделирования', 15, 'Разработка математического аппарата для моделирования подсчета запасов и геометризации недр, составление алгоритмов решения данных задач.', 'Подсчет запасов может содержать высокую ошибку, связанную с интерпретацией данных, для снижения разброса нужно проводить моделирование, которое позволит проводить сложные расчеты в цифровом виде.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Программное обеспечение', 'Знать.\nМетоды подсчета запасов полезны ископаемых.\nУметь. \nАнализировать геометрические составляющие расположения рудных залежей\nВладеть. \nАлгоритмами анализа горно-геологических условий\nЗнать.\nМетоды определения геометрии залегания\nУметь.\nОпределить геометрические параметры рудных залежей\nВладеть.\nМатематическим методами расчета геометрических параметров месторождений\n', 'Рупосов В.Л.', 4, 1, 97, NULL, NULL, NULL, NULL, NULL, NULL),
(398, NULL, NULL, 'Картографо-геодезическое сопровождение проектирования объектов социальной инфраструктуры г. Иркутска', 15, 'Подготовка топографо-геодезической и картографической основы для проектирования объектов социальной инфраструктуры г. Иркутска. Визуализация пространственных данных на завершающей стадии проектирования объекта.', 'При разработке проектов размещения объектов социальной инфраструктуры необходим сбор и анализ имеющихся картографических материалов, кадастровой и градостроительной информации на территорию планируемого строительства. Для этого проводится комплекс дорогостоящих инженерно-геодезических изысканий, средства на который, должны быть запланированы в бюджете города заранее. Таким образом, начало работы над проектом может отодвинуться на 2-3 года. Выполнение данных работ силами студенческой проектной команды при формировании земельных участков и проведении изысканий под строительство детской и взрослой поликлиник в Свердловском округе г. Иркутска значительно ускорит начало работ по проектированию и сэкономит средства городского бюджета.', 2, '2023-02-06', '2023-06-25', '', 'ОГБУЗ «Иркутская городская больница № 5»', NULL, 'Картографическая основа (топографический план, план поверхности), на которой при проектировании будет фиксироваться геопространственная информация.', 'Знания: процедура формирования земельных участков под строительство; программные средства для обработки инженерно-геодезических данных\nУмения: работа с градостроительной и кадастровой документацией; составление топографических планов и тематических карт-схем\nНавыки: разработка схем вертикальной планировки и проектов организации рельефа застраиваемых территорий; подсчет объемов земляных работ.\n', 'Клевцов Евгений Валерьевич', 4, 1, 98, NULL, NULL, NULL, NULL, NULL, NULL),
(399, NULL, NULL, 'Картографо-аэрокосмическое обеспечение проектов по землеустройству городских территорий (на примере территорий г. Иркутска)', 15, 'Разработка проекта землеустройства городской территории (микрорайона) по данным беспилотной аэросъемки, космического мониторинга и топографического картографирования. ', 'Методы аэрокосмического мониторинга и цифровой картографии применяются в земельно-кадастровых съемках. Аэрокосмические снимки позволяют определить границы территорий и произвести учет имущества. Благодаря сверхвысокому разрешению снимков можно произвести инвентаризацию небольших объектов: оборудования, инженерных сооружений и т.д. На основе полученных данных можно создать геоинформационную систему для управления земельно-кадастровыми  работами. Регулярный аэрокосмический мониторинг позволяет контролировать процесс освоения и обустройства территорий на всех этапах.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Цифровые землеустроительные карты городских территорий.', 'Знания: методика и технология создания ГИС в решении земельно-кадастровых задач, \nУмения: методы обработки аэрокосмических снимков в среде ГИС-программ.\nНавыки: работа в профессиональных ГИС-программах.\n', 'Олзоев Борис Николаевич', 4, 1, 99, NULL, NULL, NULL, NULL, NULL, NULL),
(400, NULL, NULL, 'Дистанционное картографирование снежного покрова в горных районах (на примере хребта Кодар)', 15, 'Разработка и апробация алгоритмов автоматизированного дешифрирования снежного покрова на космических снимках различного пространственного разрешения', 'Снежный покров является важной частью климатической системы Земли, оказывая существенное влияние на её тепловой и водный баланс. Снег в горных районах средних и высоких широт имеет важное гидрологическое значение, определяя характеристики речного стока и их зависимость от метеорологических условий конкретного года. В наиболее снежные годы весенне-летнее таяние снежного покрова в горах может вызывать катастрофические паводки на предгорных и равнинных территориях, где, как правило, сосредоточены населенные пункты и важные объекты инфраструктуры. В аридных областях (например, в Средней Азии) снег в горах является важнейшим источником пресной воды для населения и развития орошаемого земледелия.  Поэтому ежегодный мониторинг снежного покрова в горах является актуальной задачей, стоящей перед многими заинтересованными организациями федерального и регионального уровня (Росгидромет, МЧС, Минприроды и др.).\nВ последнее время, с развитием спутниковых и компьютерных технологий задача мониторинга снежного покрова сводится к его автоматическому распознаванию (дешифрированию) на космических снимках и картированию. Для этого часто используются многоканальные спутниковые изображения с различным пространственным и временным разрешением (например, MODIS, Landsat TM, Landsat +ETM, Sentinel-2). Однако картографирование снежного покрова в горных районах с использованием многоканальных космических снимков требует разработки надежных алгоритмов его идентификации (дешифрирования), включая выявление ложных, но визуально и оптически схожих объектов (например, облачный покров, выходы определенных типов горных пород и др.),  которые могут приводить к ошибочному картированию. Кроме того, здесь необходимо учитывать влияние факторов существенно затрудняющих автоматическое картирование, но которые являются характерными для горных территорий (крутые склоны, затенённость, горные озера и др.).\nПроект направлен на разработку оптимального алгоритма картографирования снежного покрова в горах с использованием многоканальных космических изображений и ГИС-технологий на примере хребта Кодар. Хребет Кодар является наиболее высоким хребтом, расположенным на северо-восточном фланге Байкальской рифтовой зоны.  С южной стороны Кодар граничит с суходольной Чарской впадиной, вдоль которой проходит железнодорожная трасса Байкало-Амурской магистрали (БАМ). В последние годы БАМ активно используется для грузоперевозок и модернизируется (например, строится второй путь). Для безопасной эксплуатации участка БАМ в пределах Чарской впадины необходимо уметь прогнозировать паводковые явления, вызванные резким таянием снега в горах Кодара. Таким образом,  картирование снежного покрова Кодарского хребта в рамках данного проекта является не только актуальной методической задачей, но и имеет большую практическую значимость для развития крупных инфраструктурных проектов Российской Федерации.\n', 3, '2023-02-06', '2023-06-25', '', 'Федеральное государственное бюджетное учреждение науки Лимнологический институт Сибирского отделения Российской академии наук', NULL, 'Методика автоматического мониторинга снежного покрова на космических изображениях. Карты многолетних изменений снежного покрова хребта Кодар.', 'Знания: Основные характеристики снежного покрова, характеристики многоканальных космических снимков, методы и технологии автоматического дешифрирования снежного покрова на многоканальных снимках;\nУмения: Выполнение комплекса работ по анализу растров и автоматическому дешифрированию космических снимков;\nНавыки: Дешифрирование снежного покрова, владение методами ГИС-технологий по созданию и оформлению карт снежного покрова.\n', 'Осипов Эдуард Юрьевич', 4, 1, 100, NULL, NULL, NULL, NULL, NULL, NULL),
(401, NULL, NULL, 'Разработка методов распознавания топографических образов на аэрофотоснимках сделанных с небольших высот с помощью БПЛА для создания цифровых карт', 15, 'Разработка программного продукта для распознавания топографических образов на аэрофотоснимках сделанных с небольших высот с помощью БПЛА для создания цифровых карт', 'Аэрофотосъемка проводится, на данный момент, постоянно и является основным инструментом съемки местности с высокой детализацией. Обработка снимков является более трудоемкий процесс, чем сама съемка. Наибольшее внимание уделяется оцифровки зданий и сооружений. Данный проект направлен на автоматизацию процесса оцифровки жилых и нежилых объектов. В результате будут получатся объекты в цифровой векторной карты.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Программное обеспечение для распознавания объектов.', 'Знать.\nМетоды создания, обучения и верификации искусственных нейронных сетей.\nУметь. \nСоздавать алгоритм обработки полученных результатов после работы искусственных нейронных сетей.\nВладеть. \nМетодами алгоритмизации процессов и методов программирования сложных программных кодов.\n', 'Рупосов В.Л.', 4, 1, 101, NULL, NULL, NULL, NULL, NULL, NULL),
(402, NULL, NULL, 'Ранняя диагностика возникновения критического дисбаланса вала электроагрегата для предотвращения\nкритического изгиба.\n', 15, 'Раннее оповещение машиниста экскаватора о предельном значении вибрации вала (якоря) электроагрегатов главных приводов (механизм тяги, подъёма, поворота), остановка экскаватора и предаварийное обслуживание оборудования в целях снижения затрат.', 'Входе работы необходимо разработать самописец для регистрации параметров электрической цепи электроагрегатов главных приводов. Самописец изготавливается на базе программируемого логического контроллера. Самописец совместим с картой памяти и регистрирует данные в текстовый файл. Перед отказом электроагрегата осциллограммы токов и напряжений должны принципиально менять форму. Для анализа формы сигнала разрабатывается алгоритм управления предупредительной звуковой сигнализацией.', 3, '2023-02-06', '2023-06-25', '', 'Список кейсов акселерационной программы «Лаборатория энергетики 2022»\nООО \"Компания \"Востсибуголь\". Тема №35.\n', NULL, 'Разработаны:\n1. Расчёт экономической эффективности разработки и внедрения системы онлайн диагностики вибрации вала (якоря) и оповещения оператора.\n2. Система работает с минимальной погрешностью.\n3. Оборудование системы износостойкое,\nударопрочное, адаптировано к работе в жёсткой среде,\nдиапазон температуры от +40 до -50С, сильная\nвибрация.\n', 'Знания: проблем эксплуатации горных машин с электрическим приводом. \nУмения: анализировать информацию полученную в ходе промышленного эксперимента.\nНавыки: программирования логических контроллеров и изготовления на их базе измерительных устройств.\n', 'Долгих Евгений Сергеевич', 4, 1, 102, NULL, NULL, NULL, NULL, NULL, NULL),
(403, NULL, NULL, 'Точное определение веса загруженного угля в полувагон железнодорожного состава экскаватором \nЭКГ-5А, исключение недогруза/перегруза, увеличение грузооборота полувагонов ООО \"Разрез\n\"Черемховуголь\".\n', 15, 'Исключить недогруз/перегруз полувагонов при погрузке угля экскаватором ЭКГ-5А со штабелей участка горных работ No1 ООО \"Разрез \"Черемховуголь\", сократить время на маневровые работы локомотивами связанных с дозированием угля.', 'Входе работы необходимо выполнить моделирование электромеханической системы привода подъема карьерного экскаватора. Получить характеристику зависимости тока якорной цепи от веса груза. Разработка экспериментального макета для оценки эффективности и достоверности устройства взвешивания. Разработать электронное устройство бортового взвешивания горной массы в ковше экскаватора ЭКГ-5А. Выполнить экспериментальную проверку разработанного устройства. ', 3, '2023-02-06', '2023-06-25', '', 'Список кейсов акселерационной программы «Лаборатория энергетики 2022»\nООО \"Компания \"Востсибуголь\". Тема №34.\n', NULL, 'Разработаны:\n1. Расчёт экономической эффективности разработки и внедрения системы бортового взвешивания горной массы в ковше экскаватора ЭКГ-5А.\n2. Система работает с погрешностью не более (+/-100кг).\n3. Оборудование системы износостойкое, ударопрочное, адаптировано к работе в жёсткой среде, диапазон температуры от +40 до -50С, сильная вибрация.\n', 'Знания: проблем эксплуатации горных машин с электрическим приводом. \nУмения: анализировать информацию полученную в ходе промышленного эксперимента.\nНавыки: программирования логических контроллеров и изготовления на их базе измерительных устройств.\n', 'Долгих Евгений Сергеевич', 4, 1, 103, NULL, NULL, NULL, NULL, NULL, NULL),
(404, NULL, NULL, 'Разработка эффективных средств защиты поверхностей емкостей транспортного и перегрузочного оборудования от прилипания и примерзания горной массы', 15, 'Примерзание пород вскрыши и угля к поверхностям транспортных сосудов (ковш экскаватора, кузов автосамосвала, ж.д. полувагон) является серьёзной проблемой для большинства горнодобывающих предприятий. Целью проекта является проведение анализа существующей ситуации: период действия проблемы, характеристики грузов и поверхностей. Предложить практические способы, позволяющие исключить примерзание вскрышных пород и угля к поверхностям транспортных сосудов.', 'В зимний период года происходит примерзание вскрышных пород к ковшам экскаваторов и кузовам автосамосвалов, что снижает производительность оборудования и приводит к простоям высокопроизводительного оборудования. Также, в указанный период происходит примерзание готовой продукции (угля) к стенкам и днищу ж.д. полувагонов. Данный фактор приводит к необходимости привлечения дополнительных ресурсов на очистку ж.д. полувагонов, увеличивает время оборота ж.д. полувагонов.', 3, '2023-02-06', '2023-06-25', '', 'ООО \"Компания \"Востсибуголь \"', NULL, 'Предложить не менее трех способов/методов решения проблемы. Провести технико-экономическое сравнение предложенных вариантов.', 'Знания: формирование у будущих электромехаников теоретических знаний по процедурным и организационным аспектам выполнения проектов в горной сфере деятельности.\nУмения: способность осуществлять критический анализ проблемных ситуаций на основе системного подхода, вырабатывать стратегию действий; управлять проектом на всех этапах его жизненного цикла, вырабатывая командную стратегию для достижения поставленной цели.\nНавыки: приобретение участниками проекта практических навыков по анализу и синтезу поиска информации; предлагать варианты альтернативных решений поставленной задачи и оценивать их достоинства и недостатки.\n', 'Храмовских Виталий Александрович', 4, 1, 104, NULL, NULL, NULL, NULL, NULL, NULL),
(405, NULL, NULL, 'Организация ремонта техники в зимнее время непосредственно на горных работах.', 15, 'Улучшение качества проводимых ремонтов. Улучшение культуры производства и условий труда. Обеспечить минимальны капитальные затраты. Разработать пошаговое выполнение операций по организации ремонтного места (возведение, использование, демонтаж, хранение). Произвести технико-экономическое сравнение на рынке предлагаемых укрытий и тепловых источников. Основные требования: Создать приемлемые условия для персонала при проведении ремонта. Обеспечить оптимальный температурный режим для возможности проведения сварочных, монтажных и демонтажных работ. Обеспечить мобильность и быстровозводимость ремонтных шатров. Обеспечить оптимальную вместимость шатров для техники.', 'В связи с отсутствием вместительных боксов на предприятии компании, в том числе и приближенных к горным работам, самоходную технику при проведении аварийных ремонтов приходится ремонтировать на пром. площадках под открытым небом.', 3, '2023-02-06', '2023-06-25', '', 'ООО \"Компания \"Востсибуголь \"', NULL, 'Предложены, конкретные решения с учетом перечисленных целевых показателей.\nОпределена стоимость решения.\n', 'Знания: формирование у будущих электромехаников теоретических знаний по процедурным и организационным аспектам выполнения проектов в горной сфере деятельности.\nУмения: способность осуществлять критический анализ проблемных ситуаций на основе системного подхода, вырабатывать стратегию действий; управлять проектом на всех этапах его жизненного цикла, вырабатывая командную стратегию для достижения поставленной цели.\nНавыки: приобретение участниками проекта практических навыков по анализу и синтезу поиска информации; предлагать варианты альтернативных решений поставленной задачи и оценивать их достоинства и недостатки.\n', 'Храмовских Виталий Александрович', 4, 1, 105, NULL, NULL, NULL, NULL, NULL, NULL),
(406, NULL, NULL, 'Проекты Сибирской школы геонаук \n1 - Моделирование и интерпретация данных магнитных съемок\n2 - Построение трехмерных геоэлектрических моделей на основе данных импульсной электроразведки', 15, '1. Разработка элементов компьютерных интерактивных технологий интерпретации данных наземных, беспилотных и аэромагнитных съемок.\n2. Выделение рудных структур по данным трехмерного моделирования нестационарных электромагнитных полей в комплексе с априорной геологической информацией.', '1. Использование детальных наземных, беспилотных и аэромагнитных съемок при поисках различных полезных ископаемых, решении задач геологического картирования и изучении археологических объектов приводит к получению больших массивов данных, характеризующих магнитные поля на участке съемки. По этим данным необходимо уметь выделять магнитные аномалии различного ранга, определять геометрические и магнитные параметры магнитных объектов, обусловливающих эти аномалии, и визуализировать результаты с использованием современных возможностей компьютерной 3D графики. Совокупность этих приемов определяет существо геологической интерпретации данных магнитных съемок, каждый этап которой требует совершенствования существующих приемов и элементов, их адаптации к геолого-геофизическим особенностям изучаемого объекта.\nИнтерпретация магнитных данных является высокотехнологичным процессом, основанным на использовании возможностей компьютерного моделирования, математического аппарата решения прямых (определение магнитных эффектов по заданным параметрам объектов) и обратных (определение параметров объектов по зарегистрированными над ними магнитными эффектами) задач магниторазведки.\nУчастие в проекте подразумевает: освоение современных программных продуктов для визуализации данных и результатов интерпретации магнитных съемок; формирование синтетических моделей и исследование на них возможностей тех или иных элементов решения обратных задач; освоение и разработка способов получения и учета априорной информации, позволяющей снизить неоднозначность решения обратной задач магниторазведки\n2. Построение трехмерных геоэлектрических моделей по параметрам удельного электрического сопротивления и поляризуемости. \nРеализуется конечноэлементное 3D моделирование геоэлектромагнитных полей с учетом разномасштабных, контрастных и, при необходимости, криволинейных (рельеф дневной поверхности) структурных частей геоэлектрической модели и геометрическую 3D инверсию, которая в ходе решения трехмерной обратной задачи позволяет определять электрофизические параметры (проводимость, поляризуемость) структурных частей геоэлектрической модели и размеры этих структурных частей. Данные для расчетов берутся из реальных производственных проектов, выполняемых сотрудниками и студентами ИРНИТУ в рамках хоз. договорных работ. \nУчастие в проекте подразумевает: освоение современного программного обеспечения для расчета трехмерной инверсии и построения геоэлектрических моделей; освоение способов учета априорной информации, позволяющей снизить неоднозначность решения обратной задачи электроразведки; получение квалификации обработчика и интерпретатора данных импульсной электроразведки современного уровня.\n\n', 3, '2023-02-06', '2023-06-25', '', 'Сибирская школа Геонаук ', NULL, '1. Обоснование, разработка и реализация законченного фрагмента технологической цепочки интерпретации данных магнитной съемки\n2. Построение трехмерных геоэлектрических моделей по реальным данных производственных проектов', 'Знать основы теории и практики интерпретации данных магнитных съемок;\nУметь использовать программные продукты и методические приемы при решении задач моделирования и интерпретации данных магнитных съемок;\nВладеть способами визуализации данных и результатов интерпретации, основами программирования и использования программных продуктов при интерпретации данных магниторазведки. \nЗнания: теоретико-методологические основы импульсной электроразведки, основы теории и практики интерпретации данных импульсной электроразведки\nУмения: использование современных программных продуктов для расчета трехмерной инверсии\nНавыки: владение приемами обработки и анализа электроразведочных данных, приемами обработки и анализа геологической и геофизической информации.\n\n', 'Давыденко Александр Юрьевич, Шкиря Михаил Сергеевич', 4, 1, 106, NULL, NULL, NULL, NULL, NULL, NULL),
(407, NULL, NULL, 'Анализ палеогеографических условий осадконакопления с целью оценки возможности обнаружения вторичных коллекторов алмазов', 15, 'Провести анализ палеогеографических условий осадконакопления с целью оценки возможности обнаружения вторичных коллекторов алмазов для заданной территории', 'По оценкам многих производственников (АЛРОСА, РОСГЕО) и исследователей, в частности научного руководителя Института геологии и минералогии им. В.С. Соболева СО РАН академика Н.П. Похиленко (Новосибирск) добыча алмазов в России к 2040 году сократится в разы. При этом разработка россыпных месторождений полностью прекратится к 2026 году. Оценка перспектив открытия крупных месторождений алмазов в коренном залегании на территории Иркутской области пока дает отрицательные результаты (ревизионные работы института Земной коры СО РАН. ИРКУТСК 2020-2021 гг.).\nВ то же время остается возможность нахождения алмазоносных россыпей за счет формирования переотложенных коллекторов, сложенных продуктами разрушения кимберлитовых тел в пределах южной и центральной частей Сибирской платформы. Традиционно россыпные месторождения считаются более легкими и рентабельными с точки зрения их эксплуатации.\nДля оценки возможности обнаружения таких коллекторов необходимо создание базы данных по имеющимся стратиграфическим разрезам с последующим их анализом и построение палеографических карт на определенные отрезки геологического времени. \nДля реализации проекта предусматривается использование традиционных методик палеогеографического анализа. В то же время необходимо провести комплексирование, и использовать не только геологические, но и геохимические данные, которые на сегодняшний день эффективно позволяют проводить разбраковку минералов из группы спутников алмазов\n', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Верифицированные экспериментальные данные анализа палеогеографической обстановки (с фиксацией в формате пояснительной записки и графических приложение - палеогеографических схем)', 'Знания: Методики и основных приемов анализа палеографической обстановки\nУмения: Составления базы данных для проведения палеотектонического анализа\nНавыки: Составление и анализ палеографических схем\n', 'Иванова Раиса Николаевна', 4, 1, 107, NULL, NULL, NULL, NULL, NULL, NULL),
(408, NULL, NULL, 'Инженерная геофизика', 15, 'Проведение инженерно-геофизических работ между корпусами Б и В', 'Получение геолого-геофизической информации по распределению физических свойств верхней части геологического разреза. Построение на ее основе цифровой модели изучаемого участка.', 2, '2023-02-06', '2023-06-25', '', 'Распоряжение по ИРНИТУ №5 от 18.02.2022г', NULL, 'Цифровая геолого-геофизическая модель участка исследований', 'Знания: методов получения и обработки геофизических данных \nУмения: применения геофизических методов для изучения геологического разреза\nНавыки: работы с геофизической аппаратурой и программными средствами обработки\n', 'Мироманов Андрей Викторович', 4, 1, 108, NULL, NULL, NULL, NULL, NULL, NULL),
(409, NULL, NULL, 'Обработка данных эколого- геохимических исследований в ГИС-приложениях', 15, 'Создание цифровых карт, необходимых для информационного обеспечения и прогнозирования экологического состояния урбанизированной территории на основе данных  эколого-геохимических исследований.', 'Идеология использования геохимических методов исследования для выявления и картирования очагов и источников техногенного загрязнения окружающей среды возникла в середине 1970-х годов на основе опыта поисковой геохимии.\nДля получения целостной картины состояния, функционирования, динамики и эволюции окружающей среды эти исследования должны носить системный характер.\nРезультатом этих исследований обычно является оценка совместимости или несовместимости природных условий и техногенных геохимических потоков, степени изменчивости и устойчивости природных систем к техногенезу. Следует отметить, что в техногенно измененных ландшафтах, особенно в промышленных и урбанизированных зонах, применение традиционных ландшафтно-геохимических подходов сталкивается со значительными методическими трудностями.\nЗа последние десятилетия накоплены огромные массивы эколого-геохимических данных, характеризующих состояние окружающей среды. По разным причинам эти данные разобщены. Использование геоинформационных технологий для обработки эколого-геохимических данных позволяет создать единое информационное пространство. Интеграционный характер геоинформационных систем (ГИС) позволяет создать на их основе мощный инструмент для сбора, хранения, систематизации, анализа и представления эколого-геохимической информации\n', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Создание с применением ГИС цифровых карт, необходимых для оценки экологического состояния урбанизированных территорий на основе данных эколого-геохимических исследований', 'Знать теоретико-методологические основы создания и использования цифровых геоизображений в региональных эколого-геохимических исследованиях;\nУметь использовать инструментарий ГИС- приложений для обработки полевых, картографических, дистанционных материалов и данных эколого - геохимических исследований и представления их в виде  цифровых тематических карт природных условии и геохимического загрязнения территорий;\nВладеть приемами обработки и анализа геоэкологической и картографической информации, включая рекомендации по средствам и практическим способам создания цифровых оценочных эколого-геохимических  карт. \n', 'Ланько Анна Викторовна', 4, 1, 109, NULL, NULL, NULL, NULL, NULL, NULL),
(410, NULL, NULL, 'Проекты сибирской школы Геонаук. \n1. Разработка методики геоархеологических исследований и решение археологических задач с помощью методов разведочной геофизики.', 15, '1. Разработать и апробировать методику решения археологических задач с помощью методов разведочной геофизики.\n2. Апробирование методики измерения поляризационных свойств образцов горных пород необходимой для классификации аномалиеобразующих объектов изучаемой среды', '1. Археологические исследования являются основным способом изучения древней истории человечества, выявления памятников древней истории, составляющих историко-культурное наследие государства. Современная археология базируется на широком использовании естественно-научных методов. Одними из таких методов являются методы разведочной геофизики, которые позволяют не только намного быстрее и эффективнее выявлять археологические памятники, но и изучать их особенности и характеристики. Способность геофизических методов выявлять и локализовать археологические объекты без проведения раскопочных работ делают эти методы обязательным элементом комплексных археологических исследований.\nГлавной проблемой применения методов разведочной геофизики является их адаптация для изучения самой верхней части геологического разреза и поиск эффективного по информативности и быстродействию комплекса методов. Кроме того, геофизические исследования должны носить системный характер решения археологических задач в совокупности с геолого-геохимическими и петрофизическими исследованиями.\nЗа последние десятилетия накоплен большой опыт применения геофизики археологических исследованиям, который свидетельствует о том, что не может существовать единого комплекса методов, а требуется его методическая адаптация для конкретных археологических памятников для определенных территорий. Планируемые в рамках данного проекта исследования направлены на поиск эффективного комплекса геофизических методов при изучении археологических памятников Прибайкалья.\n2. При решении задачи интерпретации геоэлектрических моделей с целью локализации рудных объектов, представленных обычно вкрапленной сульфидизацией, необходимо провести классификацию рудопроявлений и получаемых в ходе измерений характеристик.\nКачественная классификация руд строится на петрофизических исследованиях образцов горных пород, отобранных с изучаемой среды.\nЛабораторные исследования поляризационных свойств образцов горных пород в решении задач для рудной геофизики могут существенно улучшить качество прогноза и формирования более точной ФГМ.\nОднако сейчас несмотря на большой объём литературы, публикаций и общей истории методики исследования поляризационных свойств пород – в производственных работах почти не используется.\nИспользование модифицированной поляризационной модели Cole-Cole позволяет увеличить количество петрофизических параметров среды двух (УЭС и поляризуемость) до четырех: УЭС, стационарная поляризуемость, время релаксации и показатель степени. Полученные параметры необходимы для построения ФГМ, анализа трехмерных поляризующихся моделей и заложения скважин разведочного бурения.\nРазработанная лабораторная установка и методика измерений поляризационных свойств образцов горных пород нуждается в апробации результатов.', 3, '2023-02-06', '2023-06-25', '', 'Лаборатории археологии, полеоэкологии и систем жизнедеятельности ИрНИТУ, Геоархеологические исследования лаборатории геоархеологии ИГУ, Всероссийская научная конференция с международным участием имени В.В. Зайкова «Геоархеология и археологическая минералогия» г.Миасс \nСибирская школа геонаук', NULL, '1) Разработка эффективного комплекса геофизических методов при изучении археологических памятников Прибайкалья.\n2) Выявление и изучение объектов историко-культурного наследия в Прибайкалье.\n', 'Знать методы формирования комплекса геофизических исследований при решении нетрадиционных задач;\nУметь использовать геофизические методы при решении сложных, нетрадиционных задач;\nВладеть приемами обработки и анализа геологической, петрофизической и геофизической информации. \nЗнания в области петрофизических исследованиях, многомерном анализе данных.\nУмения Построение ФГМ на основе полученных данных\nНавыки работы в программах обработки сигналов, построения графиков и анализа исходных данных\n', 'Снопков Сергей Викторович, Бухалов Сергей Владимирович', 4, 1, 110, NULL, NULL, NULL, NULL, NULL, NULL),
(411, NULL, '2022-08-30 03:55:27', 'Методика прогноза изменения уровня подземных вод при строительстве инженерных сооружений с перезаглубленными фундаментами', 15, 'Разработка методики оперативного прогноза изменения гидродинамического режима грунтовых вод в результате барражного эффекта, создаваемого сооружениями с фундаментами глубокого заложения для принятия инженерных решений на начальных стадиях разработки архитектурно-строительных проектов.', 'На территориях с незначительной глубиной положения уровня грунтовых вод (УГВ) строительство зданий, имеющих фундаменты глубокого заложения, в результате «барражного» эффекта приводит к повышению риска подтопления смежных участков с находящимися на них сооружениями. Барражный эффект – это подъем УГВ перед преградой по потоку и его снижение за ней вследствие перекрытия фильтрационного потока подземных вод (ПВ). В зависимости от гидрогеологических характеристик перекрытого водоносного горизонта и габаритов инженерного сооружения величина подпора может изменяться от нескольких сантиметров до метров и может приводить к деформациям грунтового массива, подтоплению территории и расположенных рядом зданий и сооружений, а также другим неблагоприятным последствиям. \r\nПодтопление, связанное с барражным эффектом, широко развито на территориях современных городов, где застраиваются не только окраинные площади, но и историко-культурные зоны, от чего страдают фундаменты старых зданий и часто разрушаются исторические постройки.\r\nПроект направлен на выделение основных причин изменения гидрогеологических условий городских территорий (на примере центральной части г.Иркутска), а также факторов, определяющих формирование техногенного гидродинамического режима.\r\nСложность геолого-гидрогеологических условий и разноплановость задачи предопределяет необходимость использования современных технологий хранения и обработки информации', 2, '2023-02-06', '2023-06-25', NULL, NULL, NULL, 'Методика прогноза подтопления, базирующаяся на использовании методов цифровой обработки исходных данных, позволит при минимальных затратах осуществлять оперативный прогноз подъема уровня подземных вод на участках сооружения фундаментов глубокого заложения', 'Знать теоретические основы геофильтрации подземных вод\r\nУметь использовать основные приемы схематизации фильтрационных потоков\r\nВладеть навыками  решения задач, работы с учебной, нормативной и справочной литературой\r\nЗнать задачи и специфику методов математической обработки гидрогеологических данных\r\nУметь использовать первичные методы цифровой обработки гидрогеологической информации\r\nВладеть первичными методами цифровой обработки информации', 'Аузина Л.И.', 4, 1, 111, NULL, NULL, NULL, NULL, NULL, NULL),
(412, NULL, NULL, 'Моделирование гидродинамической системы пласт-скважина', 15, 'Создание программного модуля IPR-VLP, используемого для оптимизации работы нефтяных скважин ', 'Для определения оптимальной рабочей точки нефтяных скважин сопоставляют работу нефтеносного коллектора с используемым скважинным оборудованием. Известно, что приток к скважине должен соответствовать отбору жидкости из скважины.  Учитывая, что скин-эффект величина переменная, она значительное влияет на смещение рабочей точки а, следовательно, требует регулирования рабочих уставок УЭЦН.  Таким образом, рабочая зона IPR-VLP требует постоянного контроля и регулирования.  Предлагается автоматизировать процесс оптимизации технологических параметров работы УЭЦН, в частности создать предпосылки для создания интеллектуальной СУ.', 3, '2023-02-06', '2023-06-25', '', 'Иркутская нефтяная компания', NULL, 'Приложение (программный модуль) ', 'Знания: основные гидродинамические процессы, сопровождающие приток жидкости к скважине; \nУмения: моделировать работу системы приток-отток \nНавыки: навыками применения Simulink\n', 'Лагерев Роман Юрьевич', 4, 1, 112, NULL, NULL, NULL, NULL, NULL, NULL),
(413, NULL, NULL, 'Оптимизация технологии строительства скважин в сложных горно-геологических условиях (3 курс)', 15, 'Целью проекта является повышение технико-экономической эффективности строительства разведочных и эксплуатационных скважин на месторождениях углеводородов', 'В результате составления проекта планируется решить следующие актуальные проблемы строительства скважин на месторождениях углеводородов:\nстроительство скважин в условиях прихватов колонн бурильных и обсадных труб вследствие различных геологических, технических и технологических причин;\nстроительство скважин в условиях возможности возникновения газонефтеводопроявлений;\nстроительство скважин в интервалах многолетнемерзлых горных пород;\nстроительство скважин в условиях вероятности полного и катастрофического поглощения бурового раствора;\nстроительство скважин в интервалах трапповых отложений;\nстроительство скважин в интервалах соленосных (рапоносных) горизонтов.\n', 1, '2023-02-06', '2023-06-25', '', '', NULL, 'Формой продуктового результата является проект, содержащий рекомендации по оптимизации технологии бурения глубоких скважин в сложных горно-геологических условиях.', 'Знать: особенности технологии бурения глубоких скважин в сложных горно-геологических условиях.\nУметь: подобрать соответствующие технико-технологические решения для конкретных горно-геологических условий.\nВладеть: методиками проектирования технологии бурения глубоких скважин в условиях возможных осложнений и аварий.\n', 'Пушмин Павел Сергеевич, Романов Григорий Радионович', 4, 1, 113, NULL, NULL, NULL, NULL, NULL, NULL),
(414, NULL, NULL, 'Методы увеличения нефтеотдачи МУН', 15, 'Целью проекта является повышение технико-экономической эффективности добычи\nУглеводородов\n', 'В процессе выполнения проекта , будет предложен и обоснован выбор методов увеличения нефтеизвлечения МУН (выбор агента вытеснения, способ доставки, метод закачивания, оптимальная схема размещения скважин для реализации воздействия)', 2, '2023-02-06', '2023-06-25', '', 'Case-in ', NULL, 'Разработка МУН с оптимальными характеристиками', 'Знания: будут получены знания в области разработки и эксплуатации нефтяных месторождений\nУмения: получены умения поиска реализуемых на практике способов повышения эффективности МУН\nНавыки: в области управления добычей углеводородов на завершающих стадиях эксплуатации с применением современных технологий\n', 'Четверикова Валентина Валерьевна', 4, 1, 114, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(415, NULL, NULL, 'Сибирская нефть', 15, 'Сформировать группу лидеров в создании нового научного знания, технологий и разработок для внедрения в промышленность нефтегазового сектора.  Приобретение компетенций в области системы сбора и подготовки скважинной продукции, нефтепромысловой химии. Достижение научно-технического превосходства в научных и образовательных школах. Изучение ESG принципов и методик в нефтегазовой отрасли.', 'Проект «Сибирская нефть» направлен на изучение нефтей  месторождений Восточной Сибири, на исследование имеющихся методик лабораторных работ, изучение особенностей месторождений региона. Решение актуальных задач нефтегазовой отрасли по ESG принципам. ', 3, '2023-02-06', '2023-06-25', '', 'Договор №758/91-02/22 на проведение лабораторных исследований проб нефти\nCase-in , Международный нефтегазовый, кейс ESG \n', NULL, 'Изучены физико-химические свойства нефтей региона, разработаны рекомендации по применению нефтепромысловой химии для конкретных месторождений региона. Предложены свои технические решения. Решение кейсов по тематикам ESG для нефтегазовых компаний.', 'Знания: будут получены знания в области сбора и подготовки нефтяных месторождений;\nУмения: подбирать нефтепромысловую химию под конкретную задачу;\nНавыки: умение работать на лабораторном оборудовании и подбирать методики для исследований и их проводить.\n', 'Шакирова Эльвира Венеровна', 4, 1, 115, NULL, NULL, NULL, NULL, NULL, NULL),
(416, NULL, NULL, 'Разработка автоматических способов ликвидации аварий в скважине в период её бурения', 15, 'Создание методики автоматических действий ликвидации аварий в скважине в период её бурения', 'В период бурения скважины возможны многочисленные аварии, которые ликвидируются специальной службой. На ликвидацию аварии уходит много времени и средств. Иногда приходится бросать скважину и забуривать новую. Очень важно быстро остановить развитие осложнения. Поэтому разработка способов ликвидации аварии и восстановление скважины является важной задачей.', 1, '2023-02-06', '2023-06-25', '', '', NULL, 'Разработка методики действий при авариях при бурении скважины', 'Знать: технологические процессы при бурении скважин.                                                                                   Уметь: использовать оборудование для ликвидации аварий.                                                                        Владеть: владеть математическим аппаратом для аналитических расчётов', 'Зайцев Виталий Иванович', 4, 1, 116, NULL, NULL, NULL, NULL, NULL, NULL),
(417, NULL, NULL, 'Разработка автоматизированного метода ликвидации гидроразрыва пласта при бурении скважин на шельфе', 15, 'Создание методики автоматической ликвидации гидроразрыва стенки скважины при бурении на шельфе', 'В процессе бурения гидроразрыв скважины нежелателен, т.к. это приводит к потере бурового раствора, иногда катастрофическому. Поэтому разработка метода определения давления гидроразрыва скважины прибурении на шельфе аналитическим способом является важной задачей.', 1, '2023-02-06', '2023-06-25', '', '', NULL, 'Предварительное определение давления гидроразрыва стенки скважины аналитическим методом.\nМетодика действий при ликвидации гидроразрыва\n', 'Знания: технологических процессов бурения скважин на шельфе.\nУмения: использовать оборудование для ликвидации гидроразрыва пласта.\nНавыки: владения математическим аппаратом для аналитических расчётов\n', 'Зайцев Виталий Иванович', 4, 1, 117, NULL, NULL, NULL, NULL, NULL, NULL),
(418, NULL, NULL, 'Оценка стоимости трубопровода по ГИС параметрам', 15, 'Создание методики оценки стоимости трубопровода в зависимости от рельефа местности', 'Предварительная оценка инвестиционной привлекательности разработки месторождений нефти и газа.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Развитие компетенций проектной деятельности в нефтегазовой и транспортной отраслях', 'Знает - состав и принципы работы  автоматизированных информационных систем, применяемых в  нефтегазовом деле, как для проектирования, так и для эксплуатации,  основные  модели \nдоступа к базам данных в сети Internet, технологию автоматизации проектных работ,  административной  и  управленческой деятельности.\nпрограммное  обеспечение  применяемой в нефтегазовом  производстве; \nУмеет: применять основные информационные технологии для проектирования, управления, связи,  поиска информации для решения прикладных задач. \nВладеет:  основными приемами  применения стандартных  программных  комплексов,  составляющих  основу  информационных технологий в том числе для целей ГИС и ГДИС\n', 'Зедгенизов Антон Викторович', 4, 1, 118, NULL, NULL, NULL, NULL, NULL, NULL),
(419, NULL, NULL, 'Оценка стоимости строительства трубопровода по критериям логистических издержек', 15, 'Создание методики оценки стоимости трубопровода в зависимости от рельефа местности', 'Предварительная оценка инвестиционной привлекательности разработки месторождений нефти и газа.', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Развитие компетенций проектной деятельности в нефтегазовой и транспортной отраслях', 'Знает - состав и принципы работы автоматизированных информационных систем, применяемых в нефтегазовом деле, основные схемы доставки грузов и расходных материалов, требуемых при строительстве трубопроводного транспорта.\nУмеет: применять основные информационные технологии для проектирования, управления, связи, поиска информации для решения прикладных задач в области логистических решений доставки грузов в районы строительства трубопроводного транспорта.\nВладеет: основными приемами применения стандартных программных комплексов, составляющих основу информационных технологий в том числе для целей ГИС и ГДИС.\n', 'Зедгенизов Антон Викторович', 4, 1, 119, NULL, NULL, NULL, NULL, NULL, NULL),
(420, NULL, NULL, 'Математическое моделирование параметров промывочной жидкости для условий наклонно направленного бурения скважин', 15, 'Создание математических моделей потока промывочной жидкости для условий наклонно направленного бурения скважин', 'Предварительная оценка существующих моделей потоков промывочной жидкости с учетом ее свойств в условиях направленного бурения скважин.', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Развитие компетенций проектной деятельности в бурении нефтегазовых скважин ', 'Знает –назначение и условия применения промывочных жидкостей для бурения наклонно направленных скважин, математический аппарат составления  моделей, теоретические положения реологии жидкостей.\nУмеет: применять основные информационные технологии для проектирования, управления, связи,  поиска информации для решения прикладных задач. \nВладеет:  основными приемами  применения стандартных  программных  комплексов,  составляющих  основу  информационных технологий в том числе для целей бурения\n', 'Ламбин Анатолий Иванович', 4, 1, 120, NULL, NULL, NULL, NULL, NULL, NULL),
(421, NULL, NULL, 'Усовершенствование исследовательского бурового стенда', 15, 'Модернизация учебно-исследовательского стенда в буровой лаборатории для решения современных задач на более высоком с точки зрения качества уровне', 'Существует потребность в испытании буровых долот и другого породоразрушающего инструмента в стендовых условиях, прежде чем запускать полевые испытания и массовое производство. В 2016 году сотрудниками ИРНИТУ [https://www.istu.edu/news/22230/] были разработаны буровые долота, способные повысить эффективность проведения буровых работ. Подобные работы ведутся регулярно. Имеющееся в ИРНИТУ оборудование обладает рядом недостатков, в том числе аналоговыми приборами контроля и измерения параметров режима бурения. Необходимо соответствовать современным тенденциям и требованиям. Актуальность поставленной проблемы обоснована потребностью в полигоне для испытаний инновационных технических средств – породоразрушающего инструмента (долот, коронок и др.).', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Буровой исследовательский стенд, способный на современном уровне проводить эксперименты с последующим подбором оптимальной технологии бурения скважин', 'Знания: Способы совершенствования исследовательских буровых стендов для обеспечения соответствия современному уровню развития науки и техники\nУмения: Оценивать текущее состояние буровых установок и предлагать варианты усовершенствования\nНавыки: Обеспечивать монтаж, испытание и обслуживание контрольно-измерительного оборудования на исследовательских установках\n', 'Романов Григорий Радионович', 4, 1, 121, NULL, NULL, NULL, NULL, NULL, NULL),
(422, NULL, NULL, 'Оптимизация технологии строительства скважин в сложных горно-геологических условиях (4 курс)', 15, 'Целью проекта является повышение технико-экономической эффективности строительства разведочных и эксплуатационных скважин на месторождениях углеводородов', 'В результате составления проекта планируется решить следующие актуальные проблемы строительства скважин на месторождениях углеводородов:\nстроительство скважин в условиях прихватов колонн бурильных и обсадных труб вследствие различных геологических, технических и технологических причин;\nстроительство скважин в условиях возможности возникновения газонефтеводопроявлений;\nстроительство скважин в интервалах многолетнемерзлых горных пород;\nстроительство скважин в условиях вероятности полного и катастрофического поглощения бурового раствора;\nстроительство скважин в интервалах трапповых отложений;\nстроительство скважин в интервалах соленосных (рапоносных) горизонтов.\n', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Формой продуктового результата является проект, содержащий рекомендации по оптимизации технологии бурения глубоких скважин в сложных горно-геологических условиях.', 'Знать: особенности технологии бурения глубоких скважин в сложных горно-геологических условиях.\nУметь: подобрать соответствующие технико-технологические решения для конкретных горно-геологических условий.\nВладеть: методиками проектирования технологии бурения глубоких скважин в условиях возможных осложнений и аварий.\n', 'Пушмин Павел Сергеевич', 4, 1, 122, NULL, NULL, NULL, NULL, NULL, NULL),
(423, NULL, NULL, 'Исследование влияния свойств и состава бурового раствора на процесс разрушения горных пород в буровой лаборатории ИРНИТУ', 15, 'Повысить эффективность бурения твердых горных пород путем подбора оптимальных составов буровых растворов', 'Траппы Сибирской платформы, при условии их монолитности, являются серьезным осложнением с точки зрения бурения. Необходимо подбирать такие буровые растворы, которые будут способствовать повышению производительности бурения и снижать затраты энергии и ресурсов на строительство скважин в условиях трапповых интрузий. ', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Рецептуры буровых растворов, предназначенных для бурения траппов Сибирской платформы', 'Знания: Способы совершенствования технологии бурения нефтяных и газовых скважин путем подбора оптимальных рецептур буровых растворов\nУмения: Оценивать влияние определенных реагентов на производительность и ресурсоемкость буровых работ\nНавыки: Подбирать рецептуру и приготавливать на их основе буровые растворы для бурения твердых горных пород\n', 'Романов Григорий Радионович', 4, 1, 123, NULL, NULL, NULL, NULL, NULL, NULL),
(424, NULL, NULL, 'Технология рудоподготовки и обогащения апатит-нефелиновых руд', 15, 'Разработка технологии обогащения апатит-нефелиновых руд', 'Апатит-нефелиновые руды являются основным источником получения минеральных удобрений. Мировые запасы и ресурсы апатитовых руд на 60% сосредоточены в России, при этом две трети сконцентрированы на Кольском полуострове. Исходное содержание минерала апатита и нефелина 30,67 и 30,88% соответственно. Для получения готового продукта руда из карьера должна пройти стадии дезинтеграции  классификации и обогащения для получения готового продукта. Для понимания данного процесса, требуется провести натурные лабораторные испытания. Проект направлен на получение обучающимися компетенций в области профессиональной деятельности, а именно в рудоподготовки и основных методов обогащения. В процессе реализации проекта обучающиеся получат навыки проведения экспериментов по пробоподготовке, изучению физико-механических свойств проб руды, разработке технологии дробления, измельчения и классификации руд и исследований на обогатимость различными методами.', 2, '2023-02-06', '2023-06-25', '', 'ПАО «Ковдорский горно-обогатительный комбинат»  ', NULL, 'Научно-исследовательская работа по разработке технологии обогащения апатит-нефелиновых руд', 'Знать: методы обогащения и переработки апатит-нефелиновых руд;\nУметь: проводить инженерный анализ существующей и разрабатываемой проектной документации  строительства и  эксплуатации горно-обогатительного комплекса;\nВладеть: методами обогащения и переработки технологического и техногенного сырья.\n', 'Бурдонов Александр Евгеньевич', 4, 1, 124, NULL, NULL, NULL, NULL, NULL, NULL),
(425, NULL, NULL, 'Переработка крупнотоннажного техногенного сырья с получением композиционных материалов', 15, 'Переработка промышленных крупнотоннажных минеральных тонкодисперсных отходов с получением товарной продукции – полимерных композиционных материалов для различного применения', 'Разрабатываются рецептуры новых огнестойких\nи высокопрочных, изготовленных из промышленных отходов\n(золошлаковой смеси - ЗШС ТЭЦ, ГОСТ 25818-91- наполнитель, пыль газоочистки металлургии, пыль горнодобывающих предприятяий и др. ) и термопластичных полимеров.\nНа базе ИРНИТУ имеется цех по производству инновационных строительных материалов, а также термопластавтомат для литья изделий из пластических масс.\nРазрабатываемый материал будет превосходить аналоги из других полимерных композитов и натуральную древесину по химической стойкости, биологической стойкости, огнестойкости и долговечности. Кроме того, материал абсолютно гидрофобен. \nПрименение нового материала -  строительные и конструкционные материалы, детали машин и механизмов, корпуса электроники, др.\n', 3, '2023-02-06', '2023-06-25', '', 'ООО «Байкальская энергетическая компания», АО «Кремний»', NULL, 'Композиционные материалы с набором свойств для различного применения', 'Знания: способы переработки полимерных материалов\nУмения: подбора технологических параметров для переработки определенного вида термопласта\nНавыки: работы на оборудовании по переработке пластических масс в изделия\n', 'Барахтенко Вячеслав Валерьевич', 4, 1, 125, NULL, NULL, NULL, NULL, NULL, NULL),
(426, NULL, NULL, 'Технология извлечения редких металлов из литиевых рассолов Сибирской платформы', 15, 'Выбор и обоснование технологии извлечения редких металлов из высококонцентрированных рассолов ', 'Подземные высокоминерализованные воды (рассолы), вскрывающиеся при отработке месторождений твердых полезных ископаемых, нефти и газа, насыщенные различными микро- и макроэлементами, представляют собой потенциальное гидроминеральное сырье и являются крупнейшим источником товарных продуктов, таких как соли лития, бромиды, йод и др. Фактически же они превращаются в отходы- сбрасываются на поверхность либо закачиваются в подземные горизонты, что требует дополнительных затрат, а также наносит огромный ущерб окружающей среде. Задача проекта заключается в обосновании выбора и разработке эффективных технологических схем селективного выделения промышленно ценных компонентов из природных рассолов. На основании полученных результатов можно обосновывать и разрабатывать комплексные технологические схемы извлечения ценных компонентов, которые возможно реализовать в Иркутской области и соседних с ней регионах (Якутия, Бурятия)', 3, '2023-02-06', '2023-06-25', '', 'НОЦ «Байкал»', NULL, 'Технология для извлечения солей лития и стронция ', 'Знания: особенности свойств высококонцентрированных рассолов, технологии извлечения ценных компонентов\nУмения: проводить исследования свойств высококонцентрированных растворов, выбирать технологические решения\nНавыки: обоснование технологии, расчеты эффективности, доказательство перспективности проекта \n', 'Зелинская Елена Валентиновна', 4, 1, 126, NULL, NULL, NULL, NULL, NULL, NULL),
(427, NULL, NULL, 'Исследование эффективности расслоения суспензии продуктов обогащения минерального сырья', 15, 'Проведение комплекса исследований по установлению скорости осаждения твердых частиц в жидкой среде с учетом концентрации твердых частиц и влияния флокулянтов', 'В настоящее время сгущение является неотъемлемым процессом в технологической цепи обогащения полезных ископаемых, который требует постоянного изучения и совершенствования технологии по подбору и применению различных реагентов для увеличения эффективности процесса сгущения.\nПроект направлен на получение обучающимися компетенций в области профессиональной деятельности, а именно в области сгущения и обезвоживания продуктов обогащения. В процессе реализации проекта обучающиеся получат навыки проведения экспериментов по определению скорости осаждения частиц в жидкой среде, научатся проводить подбор органических и неорганических флокулянтов, для повышения эффективности разделения пульп, а так же производить расчет удельной поверхности осаждения твердых части и конструкционных параметров сгустительного оборудования.\n', 2, '2023-02-06', '2023-06-25', '', 'ООО «ИЗТМ-Инжиниринг»  ', NULL, 'Методика проведения исследований в области сгущения пульп и осветления технологических сливов.\nКонструкционные параметры сгустительного оборудования.\n', 'Знания: \n- методики расчета основного и вспомогательного оборудования для обезвоживанияи сгущения пульп на обогатительных фабриках;\n- конструкции и принцип действия сгустителя и осветлителя;\n- методы очистки сточных вод обогатительных фабрик.\nУмения: \n- расчёт параметров работы сгустителя;\n- расчет показателей водношламовой схемы;\nНавыки: \nВладение технической терминологией в области производства работ по обезвоживанию, пылеулавливанию и очистке сточных вод;\nВладение методами расчета схем по обезвоживанию.\n', 'Бурдонов Александр Евгеньевич', 4, 1, 127, NULL, NULL, NULL, NULL, NULL, NULL),
(428, NULL, NULL, 'Разработка технологий биоремедиации объектов окружающей среды и нормализации санитарно-гигиенических условий в производственных и административных помещениях', 15, 'Разработка технологий и технических устройств для очистки объектов окружающей среды от загрязнений', 'Масштабы загрязнения антибиотиками, используемыми в сельском хозяйстве весьма значительны, что приводит к возникновению антибиотикорезистентности у бактерий и вирусов. Данной проблеме не уделяется должного внимания ни со стороны властей, ни со стороны производителей, поэтому поиск новых и адаптация традиционных методик очистки объектов окружающей среды от антибиотиков является инновационным решением для проблемы ', 2, '2023-02-06', '2023-06-25', '', 'Грант ИРНИТУ', NULL, 'Создание установок биоочистки почв и водных объектов от антибиотиков (пятый / шестой семестр). Создание фитокомплексов для очистки воздуха в помещениях (шестой семестр)', 'Знания: основные показатели качества окружающей среды и современные экологические проблемы Байкальского региона\nУмения: анализировать и интерпретировать информацию о количественных и качественных показателях окружающей среды\nНавыки: создания рабочих прототипов оборудования для очистки окружающей среды\n', 'Тимофеева Светлана Семёновна, Тюкалова Ольга Васильевна', 4, 1, 128, NULL, NULL, NULL, NULL, NULL, NULL),
(429, NULL, '2022-08-30 12:59:31', 'Профессиональные риски на объектах экономики Иркутской областиПрофессиональные риски в структурных подразделениях  ИРНИТУ', 15, 'Управление профессиональными  рисками в структурных подразделениях ИРНИТУ', 'Создание безопасных и благоприятных условий труда, является одной из основных задач  для работодателя. Трудовой кодекс РФ предусматривает наличие в организации системы  управления охраной труда, создание и функционирование системы оценки профессиональных рисков. Для этого необходимо провести процедуру оценки профессиональных рисков на каждом рабочем месте, территории предприятия, местах общего использования и в других зонах ответственности работодателя за безопасность сотрудников.', 3, '2023-02-06', '2023-06-25', NULL, 'Управление по работе с персоналом и обучающимися, служба охраны труда', NULL, 'Карты оценки профессиональных рисков; комплекс мероприятий по устранению рисков или снижению их уровня', 'Знания: методик оценки профессиональных рисков\r\nУмения: выявлять и идентифицировать опасности, выполнять инструментальные измерения\r\nНавыки: работы с нормативно-правовыми актами в области безопасности и охраны труда; локальными актами организации', 'Никитина О.И., Тимофеев Семен Сергеевич', 4, 1, 129, NULL, NULL, NULL, NULL, NULL, NULL),
(430, NULL, NULL, 'Снижение углеродного следа на предприятиях по добыче и обогащению рудных полезных ископаемых', 15, 'Создать углеродного следа добывающего предприятия', 'Недропользователи заинтересованы в оценке и снижении углеродного следа своей продукции. Нам предстоит исследовать источники образования оксидов углерода на всех этапах жизненного цикла добывающего предприятия. Предложить решения для его снижения.', 2, '2023-02-06', '2023-06-25', '', 'Форсайтная группа НТИ по рынку EcoNet', NULL, 'Визуализация (в формате презентации) углеродного следа добывающего предприятия (пятый семестр). Поиск решений для его снижения (шестой семестр)', 'Знания: экологического законодательства; основ ESG – управления рисками\nУмения: представления сложной мультидисциплинарной информации в доступном виде\nНавыки: анализа жизненного цикла предприятия\n', 'Шевченко Елена Ивановна', 4, 1, 130, NULL, NULL, NULL, NULL, NULL, NULL),
(431, NULL, NULL, 'Эргодизайн рабочих помещений', 15, 'Приобретение навыков практического применения нормативно-правовой документации в области эргономики при проектировании рабочих мест для улучшения условий труда работающих в конкретном помещении', 'В настоящее время в ИРНИТУ существуют учебные и рабочие помещения, не отвечающие нормативным эргономическим требованиям (например, количество рабочих мест в помещении превышает допустимое количество, а их организация неэффективна). Эта ситуация делает некомфортными условия работы студентов и ППС в таких помещениях, что опосредовано может сказываться на качестве образовательного процесса. ', 2, '2023-02-06', '2023-06-25', '', 'ИРНИТУ', NULL, 'Разработка электронной модели (возможно - плана-схемы) эргодизайна отдельных рабочих помещений (учебных аудиторий)  с пояснительной запиской', 'Знания: знать нормативно-правовую документацию в области эргономических требований организации рабочих мест. \nУмения: уметь собирать, анализировать и оценивать информацию об условиях организации рабочего пространства  в рабочих помещениях различного назначения. \nНавыки: владение навыками проектирования рабочего пространства и рабочих мест в помещении с учетом требований действующей нормативно-правовой базы\n', 'Иванова Светлана Владимировна', 4, 1, 131, NULL, NULL, NULL, NULL, NULL, NULL),
(432, NULL, '2022-08-30 12:59:56', 'Профессиональные риски на объектах экономики Иркутской областиКультура безопасности как элемент снижения уровня профессиональных рисков', 15, 'Разработка практических процедур, которые помогут сформировать осознанное и ответственное отношение к вопросам безопасности и охраны труда', 'Культура безопасного труда – это часть общей организационной культуры, такой набор характеристик и особенностей деятельности организации и поведения отдельных лиц, который устанавливает, что проблемы безопасности являются высшим приоритетом. Для формирования ответственного и осознанного отношения к вопросам безопасности и охраны труда необходимо повысить мотивацию и вовлеченность сотрудников в формирование культуры безопасности, что в конечном итоге приведет к снижению уровней профессиональных рисков.', 3, '2023-02-06', '2023-06-25', NULL, 'Управление по работе с персоналом и обучающимися, служба охраны труда', NULL, 'Проект локального нормативного акта «Положение о культуре безопасности в ИРНИТУ»', 'Знания: требований безопасности и охраны труда при выполнении работ\r\nУмения: заинтересовать работников, мотивировать их на безопасное выполнение работ; использовать современные формы предоставления информации по охране труда \r\nНавыки: работы с инструкциями, нормативно-правовыми актами в области безопасности и охраны труда; локальными актами организации', 'Никитина О.И., Тимофеев Семен Сергеевич', 4, 1, 132, NULL, NULL, NULL, NULL, NULL, NULL),
(433, NULL, NULL, 'Исследование возможностей использования долерита в ювелирном и камнерезном дизайне', 15, 'Расширить сферы применения долерита в ювелирном и камнерезной дизайне', 'Изготовление художественных изделий из долерита расширит сферы сбыта и повысит рентабельность производства, а разработка актуального современного дизайна повысит спрос на подобную продукцию', 2, '2023-02-06', '2023-06-25', '', 'ОБЩЕСТВО С ОГРАНИЧЕННОЙ ОТВЕТСТВЕННОСТЬЮ \"СПЕЦКАМЕНЬСИБИРИ\"', NULL, 'Дизайн-проект коллекции из долерита', 'Знания: основные принципы планирования и организации своей деятельности\nУмения: формулировать личные цели; планировать и организовывать свою деятельность на основе приоритетов и поставленных целей\nНавыки: навыки рефлексии\n', 'Буйволова М.А., Бирюкова И.П', 4, 1, 133, NULL, NULL, NULL, NULL, NULL, NULL),
(434, NULL, NULL, 'Идентификация турмалинов и оценка их состава методом конфокальной Рамановской спектроскопии', 15, 'Создание базы данных Рамановских спектров минералов группы турмалина для эталонной коллекции', 'Наиболее эффективные в настоящее время методы диагностики ювелирных камней основаны на использовании наукоемкого оборудования в условиях современной лаборатории. Одним из таких методов недеструктивного локального микроанализа минералов является конфокальная Рамановская спектроскопия, объединяющая конфокальный микроскоп и метод Рамановской спектроскопии в одной системе. Для этого метода нет необходимости в специальной пробоподготовке и ювелирные камни могут быть диагностированы в изделиях. Спектрометр оснащен программным обеспечением, позволяющим производить экспрессную идентификацию минералов путем автоматического сравнения полученного спектра образца со спектрами в базе данных. Однако существующая библиотека спектров нуждается в пополнении данными о российских минералах, в том числе о турмалинах Восточно-Сибирского региона.', 3, '2023-02-06', '2023-06-25', '', 'Институт земной коры СО РАН', NULL, 'Создание библиотеки спектров турмалинов Восточно-Сибирского региона для пополнения базы данных конфокального Рамановского спектрометра WITec alpha 300R', 'Знания: теоретических основ метода конфокальной Рамановской спектроскопии\nУметь: проводить пробоподготовку, анализ образцов и интерпретировать полученные результаты\nВладеть: навыками работы с конфокальным Рамановским спектрометром WITec alpha 300R\n', 'Анисимова Александра Алексеевна', 4, 1, 134, NULL, NULL, NULL, NULL, NULL, NULL),
(435, NULL, NULL, 'Разработка камнерезного цеха по обработке долерита для получения готового художественного продукта', 15, 'Разработать современный камнерезный цех для художественной обработки долерита', 'Правильно организованный камнерезный цех позволит изготавливать современную актуальную художественную продукцию из долерита без значительных потерь материала', 3, '2023-02-06', '2023-06-25', '', 'ОБЩЕСТВО С ОГРАНИЧЕННОЙ ОТВЕТСТВЕННОСТЬЮ \"СПЕЦКАМЕНЬСИБИРИ\"', NULL, 'Проект камнерезного цеха', 'Знания: основные принципы планирования и организации своей деятельности\nУмения: формулировать личные цели; планировать и организовывать свою деятельность на основе приоритетов и поставленных целей\nНавыки: навыки рефлексии\n', 'Буйволова М.А, Бирюкова И.П.', 4, 1, 135, NULL, NULL, NULL, NULL, NULL, NULL),
(436, NULL, '2022-08-30 13:01:37', 'Разработка коллекции ювелирных изделий на основе оберегов народов Сибири', 15, 'Разработать современный дизайн коллекции ювелирных изделий на тему оберегов', 'Современный рынок ювелирной продукции перенасыщен однообразными изделиями не привлекательными для современного покупателя. Одним из решений этой проблемы является разработка актуального дизайна ювелирных на основе оберегов народов Сибири. Их использование в дизайне ювелирной продукции повысит ее привлекательность.', 3, '2023-02-06', '2023-06-25', NULL, 'АО «Алмаз»', NULL, 'Дизайн-проект коллекции ювелирных изделий', 'Знания: основные принципы планирования и организации своей деятельности\r\nУмения: формулировать личные цели; планировать и организовывать свою деятельность на основе приоритетов и поставленных целей.\r\nНавыки: навыки рефлексии', 'Берман Елена Александровна, Сорокина Вера Евгеньевна', 4, 1, 136, NULL, NULL, NULL, NULL, NULL, NULL),
(437, NULL, NULL, 'Разработка сувенирной продукции на основе уникальных особенностей флоры и фауны Байкальского региона', 15, 'Разработать современный дизайн сувенирной продукции на основе уникальных особенностей флоры и фауны Байкальского региона', 'Современный рынок ювелирной и камнерезной продукции Байкальского региона перенасыщен однообразными изделиями не привлекательными для современного покупателя. Одним из решений этой проблемы является разработка актуального дизайна сувенирных изделий на основе особенностей природы Байкальского региона с учетом географического положения и уникальной флоры и фауны Байкала. Их использование в дизайне сувенирной продукции повысит ее привлекательность.', 2, '2023-02-06', '2023-06-25', '', 'АО \"Байкалкварцсамоцветы»', NULL, 'Дизайн-проект коллекции изделий', 'Знания: основные принципы планирования и организации своей деятельности\nУмения: формулировать личные цели; планировать и организовывать свою деятельность на основе приоритетов и поставленных целей.\nНавыки: навыки рефлексии\n', 'Войтюк Алена Александровна', 4, 1, 137, NULL, NULL, NULL, NULL, NULL, NULL),
(438, NULL, '2022-08-30 13:02:21', 'Вовлечение техногенного сырья в производство цветных металлов', 15, 'Разработать технологические рекомендации и стратегию переработки техногенного сырья и расширения сырьевой базы металлургического производства за счет разработки новых месторождений', 'На территории России сосредоточено почти 30% мировых разведанных запасов никеля, 28% – железа, 10% – меди, по запасам других видов металлов, страна входит в число ведущих горнодобывающих государств. Ресурсная обеспеченность России определяется исходя из необходимости удовлетворения текущих и перспективных потребностей экономики, в соответствии с уровнем экономического развития страны. Однако Россия отстает от большинства стран мира по уровню вовлечения минерально-сырьевой базы в экономический оборот, по уровню обеспечения народнохозяйственных потребностей в ресурсах и по темпам роста горноперерабатывающей и металлургической промышленности. Отставание от среднемирового уровня свидетельствует о проблемах вовлечения природных ресурсов в производство, о трудностях с воспроизводством материально-технической базы страны.\r\nВместе с тем металлургические предприятия являются одним из основных источников загрязнения окружающей среды. Выбросы вредных веществ на конкретных промышленных предприятиях зависят от объема производства, структуры предприятия, оснащенности газоочистным оборудованием, технологических особенностей и других причин. В связи со всевозрастающим негативным воздействием производственной деятельности металлургических предприятий на состояние окружающей среды наибольшую важность приобретают технологии, обеспечивающие устойчивое развитие за счет повышения энергоэффективности, комплексного использования сырья, снижения экологической нагрузки и производственных издержек. Как показывает практика, переработка многих видов отходов металлургического производства экономически выгодно и технически осуществимо.\r\nОсновными направлениями расширения сырьевой базы являются разработка новых месторождений и переработка уже накопленных и вновь образующихся отходов.', 1, '2023-02-06', '2023-06-25', NULL, NULL, NULL, 'Технологические рекомендации, включающие анализ образующихся отходов металлургических предприятий и существующих запасов минерального сырья, а также конкретные технологические решения по вовлечению и переработке минерального и техногенного сырья', 'Знания:\r\nПринципы рационального природопользования в области металлургии.\r\nУмения:\r\nУметь применять принципы рационального природопользования для энерго- и ресурсосбережения технологических процессов в металлургии \r\nНавыки:\r\nВладеть навыками использования принципов рационального природопользования для энерго- и ресурсосбережения технологических процессов в металлургии.', 'Фёдоров Сергей Николаевич', 4, 1, 138, NULL, NULL, NULL, NULL, NULL, NULL),
(439, NULL, NULL, 'Оптимизация процесса переработки техногенного и минерального сырья', 15, 'Разработать технологические рекомендации по переработки отходов вторичной металлургии свинца и оптимизации процесса производства первичного алюминия', 'Проблема накопления отходов в процессе переработки свинцовых аккумуляторных батарей встречается на большинстве заводов данной отрасли. Самым ярким примером являются накопленные отходы в г. Свирске, объем которых составляет 3500-4500 т. Данный отход относится к третьему классу опасности, но также представляет собой ценный продукт для доизвлечения свинца, которого в отходах содержится до 30 мас. %. Разработанное технологическое решение может быть использовано и на других предприятиях перерабатывающих аккумуляторные батареи.\nПри производстве алюминия электролизом криолит-глиноземного расплава возникает ряд проблем. При повышении амперной нагрузки повышается температура электролита, поэтому необходимо организовать эффективный отвод тепла от поверхностей электролизера и уменьшить потери тепла. Увеличение засыпки и размеров электролизера способствуют уменьшению тепловых потерь за счет снижения отношения их поверхности к объему. \nУвеличение силы тока на электролизной серии выше нормативного значения приводит к ряду расстройств на электролизере: увеличению сопротивления токопроводящих элементов ванны, нарушению теплового баланса, повышению выбросов газообразных веществ. Поэтому проработка инновационных решений для компенсации амперной нагрузки является не простой и важной задачей.\nПотери анодного напряжения связаны в первую очередь с конструкцией анодного узла, составом и качеством материала анода. Важную роль в перепаде напряжения в анодном массиве играет токораспределение по анодам. Известно, что оно может быть крайне неравномерно, в результате чего возникают конусы, приводящие к замыканию электродов.\n', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Технологические рекомендации, включающие анализ образующихся отходов вторичной металлургии свинца, а также конкретные технологические решения по вовлечению и переработке техногенного сырья. \nТехнологические рекомендации, включающие анализ проблем возникающих при производстве первичного алюминия, а также конкретные технологические решения по их решению\n', 'Знания:\nПринципы рационального природопользования в области металлургии.\nКонструкция электролизеров для получения алюминия; основные параметры, оказывающие влияние на эффективность металлургических процессов производства алюминия электролитическим способом и диапазоны их оптимальных значений.\nУмения:\nУметь применять, совершенствовать или разрабатывать методы переработки отходов металлургического производства.\nУметь применять полученные знания о строении криолит-глиноземных расплавов на практике; уметь проводить анализ влияния различных факторов на основные показатели электролиза\nНавыки:\nВладеть навыками разработки предложений по переработке отходов металлургического производства и оптимизации процесса производства алюминия. \n', 'Тютрин Андрей Александрович', 4, 1, 139, NULL, NULL, NULL, NULL, NULL, NULL),
(440, NULL, '2022-08-30 13:02:53', 'Расширение сырьевой базы металлургического производства', 15, 'Разработать технологические рекомендации и стратегию расширения сырьевой базы металлургического производства за счет разработки новых месторождений и переработки техногенного сырья', 'На территории России сосредоточено почти 30% мировых разведанных запасов никеля, 28% – железа, 10% – меди, по запасам других видов металлов, страна входит в число ведущих горнодобывающих государств. Ресурсная обеспеченность России определяется исходя из необходимости удовлетворения текущих и перспективных потребностей экономики, в соответствии с уровнем экономического развития страны. Однако Россия отстает от большинства стран мира по уровню вовлечения минерально-сырьевой базы в экономический оборот, по уровню обеспечения народнохозяйственных потребностей в ресурсах и по темпам роста горноперерабатывающей и металлургической промышленности. Отставание от среднемирового уровня свидетельствует о проблемах вовлечения природных ресурсов в производство, о трудностях с воспроизводством материально-технической базы страны.\r\nВместе с тем металлургические предприятия являются одним из основных источников загрязнения окружающей среды. Выбросы вредных веществ на конкретных промышленных предприятиях зависят от объема производства, структуры предприятия, оснащенности газоочистным оборудованием, технологических особенностей и других причин. В связи со всевозрастающим негативным воздействием производственной деятельности металлургических предприятий на состояние окружающей среды наибольшую важность приобретают технологии, обеспечивающие устойчивое развитие за счет повышения энергоэффективности, комплексного использования сырья, снижения экологической нагрузки и производственных издержек. Как показывает практика, переработка многих видов отходов металлургического производства экономически выгодно и технически осуществимо.\r\nОсновными направлениями расширения сырьевой базы являются разработка новых месторождений и переработка уже накопленных и вновь образующихся отходов.', 1, '2023-02-06', '2023-06-25', NULL, NULL, NULL, 'Технологические рекомендации, включающие анализ образующихся отходов металлургических предприятий и существующих запасов минерального сырья, а также конкретные технологические решения по вовлечению и переработке минерального и техногенного сырья', 'Знания:\r\nПринципы рационального природопользования в области металлургии.\r\nУмения:\r\nУметь применять принципы рационального природопользования для энерго- и ресурсосбережения технологических процессов в металлургии \r\nНавыки:\r\nВладеть навыками использования принципов рационального природопользования для энерго- и ресурсосбережения технологических процессов в металлургии.', 'Зайцева Анна Александровна', 4, 1, 140, NULL, NULL, NULL, NULL, NULL, NULL),
(441, NULL, NULL, 'Разработка технологии переработки золотосодержащих руд', 15, 'Разработать технологию по переработке золотосодержащего сырья и расширить сырьевую базу путем вовлечения в переработку упорного, бедного, забалансового, комплексного сырья', 'В России в золотых рудах коренных месторождений заключено 61,1% разведанных запасов. В комплексных рудах – 25,5%, в россыпях – 13,4%. Прогнозные ресурсы коренных месторождений 38,8 тыс. т, россыпей 2,8 тыс. т. Однако Россия отстает от большинства стран мира по уровню вовлечения минерально-сырьевой базы в экономический оборот, по уровню обеспечения народнохозяйственных потребностей в ресурсах и по темпам роста горноперерабатывающей и металлургической промышленности. На сегодняшний день Россия занимает третье место по добыче золота (282-300 тонн/год). Лидерами являются Китай (400 тонн/год) и Австралия (315 тонн/год). Легких для переработки руд в России и мире осталось крайне мало. Все чаще золотодобытчикам приходится работать с упорным рудами. Традиционного цианирования в условиях переработки упорных руд недостаточно. Такие руды требуют обогатительных процессов прежде, чем их будет целесообразно подвергать цианированию. Так же следует отметить, что в настоящее время особый интерес представляют и комплексные руды, содержащие благородные металлы. Переработка комплексных руд позволяет повысить экономические показатели производства. \nОсновным направлением в золотодобыче является выбор наиболее рентабельной технологии по переработке золотосодержащих руд. \n', 1, '2023-02-06', '2023-06-25', '', '', NULL, 'Технологические рекомендации, включающие анализ существующих схем переработки золотосодержащих руд, а также конкретные технологические решения по расширению сырьевой базы путем вовлечения в переработку упорного, бедного, забалансового, комплексного сырья', 'Знания:\nПринципы рационального природопользования в области металлургии.\nУмения:\nУметь применять принципы рационального природопользования для энерго- и ресурсосбережения технологических процессов в металлургии \nНавыки:\nВладеть навыками использования принципов рационального природопользования для энерго- и ресурсосбережения технологических процессов в металлургии.\n', 'Шипнигов Антон Андреевич', 4, 1, 141, NULL, NULL, NULL, NULL, NULL, NULL),
(442, NULL, NULL, 'Проектирование, монтаж и наладка учебно-исследовательских стендов на базе оборудования для автоматизации ПГ ОВЕН (3й курс)', 15, 'Дать обучающимся возможность приобрести практические знания, умения, навыки работы с оборудованием для автоматизации в процессе проектирования, монтажа, наладки учебно-исследовательских стендов и исследования систем автоматического регулирования.', 'Основной задачей учебных стендов является обучение студентов основам автоматизации технологических процессов, демонстрация работы средств автоматического управления и регулирования. Внедрение в процесс обучения стендов поможет учащимся детально изучать процессы автоматического управления и регулирования, а разработка методических пособий по работе с ними, получать практические навыки в проектировании систем автоматизации. Работа на стендах знакомит будущих специалистов в области автоматизации с условиями максимально приближенными к производственным. \nВследствие этого, задачи разработки устройств данного класса являются актуальными\n', 1, '2023-02-06', '2023-06-25', '', 'Институт высоких технологий ИРНИТУ\nРегиональный учебный центр «ОВЕН-ИРНИТУ»\n', NULL, '1.Проект учебно-исследовательских стендов.\n2.Разработка технической документации:\n-схема электрическая принципиальная;\n-схема внешних проводок;\n-схема питания;\n-монтажная схема;\n-методические указания к лабораторным и практическим работам;\n-программное обеспечение и т.д.\n3. Изготовленный учебно-исследовательский стенд.\n', 'Знания: знать основные принципы организации своей работы, требования к представлению результатов, инструменты поиска информации,  нормы и способы социального взаимодействия.\nУмения: формулировать цели и задачи; творчески и критически мыслить, решать задачи в соответствии с ролевой позицией.\nНавыки: работа в команде, получение первичной информации, навыками определения и постановки задач.\n', 'Ершов П.Р., Подкорытов А.А.', 4, 1, 142, NULL, NULL, NULL, NULL, NULL, NULL),
(443, NULL, NULL, 'Проектирование, монтаж и наладка учебно-исследовательских стендов на базе оборудования для автоматизации ПГ ОВЕН (4й курс)', 15, 'Дать обучающимся возможность приобрести практические знания, умения, навыки работы с оборудованием для автоматизации в процессе проектирования, монтажа, наладки учебно-исследовательских стендов и исследования систем автоматического регулирования', 'Основной задачей учебных стендов является обучение студентов основам автоматизации технологических процессов, демонстрация работы средств автоматического управления и регулирования. Внедрение в процесс обучения стендов поможет учащимся детально изучать процессы автоматического управления и регулирования, а разработка методических пособий по работе с ними, получать практические навыки в проектировании систем автоматизации. Работа на стендах знакомит будущих специалистов в области автоматизации с условиями максимально приближенными к производственным. \nВследствие этого, задачи разработки устройств данного класса являются актуальными\n', 3, '2023-02-06', '2023-06-25', '', 'Институт высоких технологий ИРНИТУ\nРегиональный учебный центр «ОВЕН-ИРНИТУ\n', NULL, '1.Проект учебно-исследовательских стендов.\n2.Разработка технической документации:\n-схема электрическая принципиальная;\n-схема внешних проводок;\n-схема питания;\n-монтажная схема;\n-методические указания к лабораторным и практическим работам;\n-программное обеспечение и т.д.\n3. Изготовленный учебно-исследовательский стенд.\n\n', 'Знания: знать основные принципы организации своей работы, требования к представлению результатов, инструменты поиска информации,  нормы и способы социального взаимодействия.\nУмения: формулировать цели и задачи; творчески и критически мыслить, решать задачи в соответствии с ролевой позицией.\nНавыки: работа в команде, получение первичной информации, навыками определения и постановки задач.\n', 'Ершов П.Р.', 4, 1, 143, NULL, NULL, NULL, NULL, NULL, NULL),
(444, NULL, NULL, 'Разработка элементов  автоматических устройств контроля физико-химических параметров гидрометаллургических процессов переработки минерального сырья', 15, 'Разработка технических и программных составляющих устройств автоматического контроля таких параметров как: концентрация растворенного золота, цианида натрия  в технологических растворах гидрометаллургических отделений при переработке минерального сырья', 'Аналитический контроль играет важную роль  для успешного ведения технологических процессов. В большинстве случаев измерения проводятся либо в лабораторных условиях и соответственно данные  могут потерять свою актуальность из-за достаточно большого времени проведения анализов, либо существующие устройства  имеют высокую стоимость. Вследствие этого, задачи разработки устройств данного класса являются актуальными. В рамках данного проекта  предлагается рассматривать отдельные задачи для достижения общей цели проекта, такие как разработка отдельных алгоритмов,  разработка  отдельных технических узлов.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Алгоритмы реализации отдельных подсистем\nСтруктурные схемы отдельных технических решений\n', 'Знать: метрологические и эксплуатационные характеристики, особенности монтажа, погрешности, состояние и перспективы и тенденции современного приборостроения, классификацию, назначение, особенности применения, устройство и принцип действия приборов и устройств качественного анализа (газоанализаторов, рН- метров, концентратомеров и пр.).\nУметь: проводить декомпозицию общей задачи измерения, с выделением отдельных подсистем \nВладеть: навыками работы с анализаторами: подготовки проб, проведения измерений, оценки и обработки    результатов, в том числе с применением специализированного программного обеспечения\n', 'Овсюков Александр Евгеньевич', 4, 1, 144, NULL, NULL, NULL, NULL, NULL, NULL),
(445, NULL, NULL, 'Разработка системы управления лабораторной информацией', 15, 'Разработка структуры', 'Система управления лабораторной информацией – программное обеспечение, предназначенное для управления лабораторными потоками работ и документов. Позволяет оптимизировать сбор, анализ, возврат и отчетность лабораторных данных. Часто применяется вместе с MES-системами. Задачами данного проекта является рассмотрение существующих систем данного класса, рассмотрение направления движения потоков информации, выделение основных функций которые реализуются, разработка структуры, описание функций, составление алгоритмов обработки информации.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Структура программного комплекса\nОписание функций реализуемых данным комплексом\nОписание графического интерфейса\nАлгоритмы обработки  информации\n', 'Знать: международную систему единиц физических величин, методы измерений, метрологические показатели средств измерений, метрологические характеристики средств измерения, погрешности  измерений, причины возникновения погрешностей,  методику обработки результатов наблюдений и оценивание погрешностей измерений, поверку и калибровку средств измерений, методы поверки (калибровки) \nУметь: обоснованно применять методы метрологии и стандартизации,  проводить простейшую обработку результатов многократных измерений.\nВладеть: методами метрологии и стандартизации, достаточным творческим мышлением и способностью самостоятельно принимать решения.\n', 'Овсюков Александр Евгеньевич, Колодин Алексей Александрович', 4, 1, 145, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(446, NULL, '2022-08-30 13:08:34', 'Формирование компетенции персонала высокотехнологичного предприятия как инструмент обеспечения его конкурентоспособности. Разработка веб-приложения «Система адаптации персонала».   3-й КУРС', 15, 'Разработать веб-приложение, построенного по типу «Электронное обучение» на базе CMS Wordpress, с применением стека технологий HTML/CSS/JS', 'Актуальной задачей обеспечения конкурентоспособности высокотехнологичного предприятия является формирование компетенции персонала. Одним из важнейших ресурсов достижения результативности процессов является подготовка компетентного персонала. При найме новых сотрудников в штат организации происходит процесс их адаптации. В рамках адаптационного периода новоприбывший сотрудник ознакамливается с необходимой нормативно-правовой документацией и внутренними регламентами компании. К таким регламентам могут относиться как требования федерального уровня, например инструктаж о соблюдении мер по защите и охране труда, так и внутренние условия нахождения на режимных объектах, правила пожарной безопасности, и иные требования.\r\nСоздание веб-приложения по типу «Электронное обучение» позволит не только собрать все необходимые для адаптации сотрудников документы на единой площадке, но и даст возможность сотрудникам удаленно проходить адаптационные мероприятия в части ознакомления и прохождения тестирования в рамках тех или иных требований, заявленных руководством. Кроме того, введение системы электронного обучения позволит унифицировать процесс управления обучающими материалами, необходимых для адаптации персонала', 2, '2023-02-06', '2023-06-25', NULL, 'Иркутская Нефтяная Компания. \r\nГазпром добыча Иркутск.\r\nВСЖД – филиал РЖД', NULL, 'Веб-приложение, запускаемое на сервере организации, дающее возможность организации электронного обучения в рамках процесса адаптации персонала', 'Знать: основные понятия и методы риск-менеджмента; правовые, нормативно-технические и организационно-правовые основы обеспечения безопасности и менеджмента риска на\r\nпредприятиях;\r\nУметь: выявлять риски и оценивать степень риска при управлении качеством; вести документацию по разработке и внедрению систем менеджмента риска;\r\nВладеть: навыками применения инструментов и методов риск-менеджмента по снижению степени риска в системах качества', 'Кокшаров А.В', 4, 1, 146, NULL, NULL, NULL, NULL, NULL, NULL),
(447, NULL, '2022-08-30 13:09:09', 'Формирование компетенции персонала высокотехнологичного предприятия как инструмент обеспечения его конкурентоспособности.  Проектирование UX (пользовательского опыта) и UI (интерфейса) для web-приложения «Система адаптации персонала».     4-Й КУРС', 15, 'Спроектировать интерфейс web-приложения, построенного по типу «электронное обучение» на основе CJM', 'Актуальной задачей обеспечения конкурентоспособности высокотехнологичного предприятия является формирование компетенции персонала. Проблема конкурентоспособности предприятия определяется его ресурсами, и, прежде всего, компетентностью персонала. Это требует формирования СМК, выявление бизнес-процессов, оценку рис-ориентированной деятельности и разработку мер по совершенствованию и улучшению результативности процессов.  Предварительное UX/UI проектирование web-приложения необходимо для сокращения временных издержек при внедрении системы адаптации новых сотрудников высокотехнологичного предприятия и повысит качество разрабатываемого web-приложения. Проектирование интерфейса в соответствии с картой пользовательского пути и учетом достоинств/недостатков аналогичных систем.', 2, '2023-02-06', '2023-06-25', NULL, 'Иркутская Нефтяная Компания. \r\nГазпром добыча Иркутск.\r\nВСЖД – филиал РЖД', NULL, 'Интерфейс web-приложения, готовый для передачи в разработку. Спроектирован с помощью методологии CJM, обоснованы возможные пользовательские цели и пути их решения.', 'Знать: основные понятия и методы риск-менеджмента; правовые, нормативно-технические и организационно-правовые основы обеспечения безопасности и менеджмента риска на\r\nпредприятиях;\r\nУметь: выявлять риски и оценивать степень риска при управлении качеством; вести документацию по разработке и внедрению систем менеджмента риска;\r\nВладеть: навыками применения инструментов и методов риск-менеджмента по снижению степени риска в системах качества', 'Гулов А.Е', 4, 1, 147, NULL, NULL, NULL, NULL, NULL, NULL),
(448, NULL, NULL, 'Информационная система Байкальского региона', 15, 'Создание информационной системы Байкальского региона', 'Целью проекта является создание прототипа интернет-сервиса с картой по Байкалу для российских и иностранных туристов, отличительными особенностями которого будут:\n• Контент для туриста – предоставление информации для планирования отдыха по виду, времени, месту, стоимости и способу проезда.\n• Единая автоматизированная площадка для турбизнеса – возможность для продвижения своих услуг.\n• Интерактивная карта\nСоздание подобного ресурса создаст возможности для увеличения известности и доступности региона  для туристов, привлечет туристов, сделает местный туристический рынок более открытым, гибким, конкурентным.\n', 3, '2023-02-06', '2023-06-25', '', 'Администрация п.Хужир', NULL, 'Прототип информационной системы Байкальского региона', 'Уметь: анализировать и обобщать информацию в сфере маркетинга при управлении проектом;\nВладеть: навыками анализа и обобщения информацию в сфере маркетинга при управлении проектом.\nУметь: использовать современные информационные технологии для сбора, анализа и обобщения информации; \nВладеть: Навыками использования современных информационных технологий для сбора, анализа и обобщения информации\n', 'Куклина Мария Владимировна', 4, 1, 148, NULL, NULL, NULL, NULL, NULL, NULL),
(449, NULL, NULL, 'Разработка 3D моделей для рынка Healthnet', 15, '1) Совершенствование оказания медицинской помощи онкологическим пациентам. \n2) Улучшение качества обучения специалистов эндоскопии.\n', 'Злокачественные новообразования (ЗНО) стоят на третьем месте по причинам смерти населения в Российской Федерации, после заболеваний сердечно-сосудистой системы и внешних причин.\nВ ходе проекта будет разработана 3D-модель, созданная на основе механических свойств нормальной и опухолевой тканей, а также программа, благодаря которой улучшится визуализация слабо-контактируемых злокачественных опухолей по МРТ/МСКТ-снимкам. \nПроект позволит с помощью данных технологий воспроизводить высокоточные трехмерные модели человеческих органов в реальном времени.  К аддитивным технологиям относится биомоделирование — создание точной виртуальной или реальной модели интересующей области человеческого организма на основе данных лучевой диагностики, как правило, компьютерной томографии (КТ). Также позволит усовершенствовать диагностику и планирование лечения онкологических пациентов, в том числе хирургическое, злокачественных опухолей.\n3D-печать имеет огромный потенциал в медицине. С помощью этих технологий можно воспроизводить высокоточные трехмерные модели человеческих органов, а также некоторые имплантаты. Разработчики подобных технологий стремятся к созданию органов в реальном времени.\n', 3, '2023-02-06', '2023-06-25', '', 'ГБУЗ Иркутский областной онкологический диспансер', NULL, 'Главная ценность продукта заключатся снизить риски для здоровья пациента. 3D-печать в медицине позволяет с высокой точностью моделировать и создавать стоматологические имплантаты, протезы, прототипы органов. Также 3D-печать помогает уже работающим специалистам и медикам эффективнее учиться и повышать квалификацию, практиковаться и составлять точные планы хирургических операций', 'В результате реализации проекта у студентов должна быть сформирована способность обеспечения практического применения результатов научного исследования:\nПКР-4. Способность определять стоимостную оценку основных ресурсов и затрат по реализации проекта ПКР-5. Способность организовать работу исполнителей в коллективе, находить и принимать управленческие решения в области организации работ по проекту и нормированию труда\nПКР-7. Способность обеспечить практическое применение результатов научного исследования\nПКР-11. Способность спланировать необходимый эксперимент, получить адекватную модель и исследовать ее \n', 'Конюхов Владимир Юрьевич', 4, 1, 149, NULL, NULL, NULL, NULL, NULL, NULL),
(450, NULL, NULL, 'Разработка модели коммерциализации результатов проекта «Исследование противокоррозионных свойств эпоксидных композиций, допированных ингибиторами коррозии', 15, 'Создание эффективной модели продвижения на рынок результатов НИОКР ВУЗа на примере проекта «Исследование противокоррозионных свойств эпоксидных композиций, допированных ингибиторами коррозии»', '    При реализации НИОКР в рамках ВУЗов одной из основных задач является продвижение их результатов на рынок, а именно: поиск схем и возможностей коммерциализации, привлечение инвесторов, организация высокотехнологичного бизнеса, создание конкурентной среды технологического предпринимательства. Именно при разработке инновационного проекта, решающее значение имеют возможности коммерциализации результатов НИОКР, основанные на проведенных маркетинговых исследованиях. В рамках данного проекта (техническая аспект) исследуются способы защиты металлических конструкций от коррозийных процессов и разрабатывается модель продвижения на рынок результатов исследования (предпринимательский аспект).\n      Коррозия металлов наносит значительный ущерб народному хозяйству нашей страны. Потери от коррозии металлов весомы, они складываются из стоимости изготовления металлических конструкций, пришедших в негодность вследствие коррозии, из безвозвратных потерь в виде продуктов коррозии и из косвенных убытков. В настоящее время большая часть нефтегазовых месторождений находится в поздней стадии разработки, когда снижается добыча и резко возрастает обводненность нефти. Такие месторождения характеризуются значительными осложнениями в процессах добычи, сбора и подготовки нефти, связанными с образованием стойких нефтяных эмульсий, отложениями АСПО, неорганических солей, наличием механических примесей, коррозионным разрушением оборудования и нефтепроводов.Увеличение коррозионной активности, добываемой совместно с нефтью воды на данном этапе является серьезной проблемой. Наиболее эффективным и технологически несложным защитным мероприятием является ингибиторная защита. \n     Именно поэтому исследования способов защиты металлических конструкций от коррозийных процессов и создание эффективной модели бизнеса на основе этих исследований являются крайне актуальными. \n', 2, '2023-02-06', '2023-06-25', '', 'соискатель ИрНИТУ (сотрудник ИАЗ)', NULL, 'Практические рекомендации (алгоритм) по продвижению на рынок результатов НИОКР, осуществляемых в ИрНИТУ', 'В результате реализации проекта у студентов должна быть сформирована способность обеспечения практического применения результатов научного исследования (ПКР-7, в части ПКР-7.3, ПКР-7.4) и: \nзнания основных способов коммерциализации результатов НИОКР;\nумения обеспечения практического применения результатов научного исследования;\nнавыки осуществления деятельности по продвижению на рынок результатов НИОКР. \n', 'Уразова Нина Геннадьевна ', 4, 1, 150, NULL, NULL, NULL, NULL, NULL, NULL),
(451, NULL, NULL, 'Разработка рецептур продуктов питания функционального назначения на основе плодоовощного растительного сырья Иркутской области и организация их безопасного производства ', 15, 'Дать обучающимся возможность приобрести востребованные практико-ориентированные знания, умения, навыки в экспериментальной отработке рецептур функциональных пищевых продуктов и подготовки документации для обеспечения качества, и безопасности их производства.  ', 'Продукты функционального питания и их компоненты могут модифицировать метаболизм в организме человека и играть важную роль в предотвращении возникновения различных заболеваний. При создании безопасного производства продуктов функционального питания необходимо знать химический состав сырья, пищевую ценность, специальные приемы технологической обработки.\nДля обеспечения качества и безопасности продуктов питания необходимо знать и уметь определять факторы, оказывающие негативное влияние на безопасность готовой продукции, зависимость этих факторов от применяемого сырья, технологии, оборудования и упаковки. Применение специальных систем качества и безопасности пищевой продукции позволяет управлять рисками внутри производства и обеспечивать сохранение здоровья потребителя. \n', 1, '2023-02-06', '2023-06-25', '', '', NULL, '1.Разработана рецептура функционального пищевого продукта, проведены эксперименты применения рецептуры с отработкой параметров процесса производства, получен лабораторный образец. \n2.Определены этапы построения системы безопасности пищевой продукции, разработаны обязательные мероприятия для обеспечения безопасности производства, определены возможные риски пищевой безопасности для готовой продукции\n3. Проведены исследования на соответствие показателей качества лабораторного образца требованиям ГОСТ, подтверждено функциональное назначение. Разработана технологическая документация и рекомендации по применению.\n', 'Знания: знать основные принципы организации своей работы, требования к представлению результатов, инструменты поиска информации\nУмения: формулировать цели и задачи; творчески и критически мыслить\nНавыки: работа в команде, получение первичной информации\n', 'Куприна О.В.       , Евстафьева О.А.', 4, 1, 151, NULL, NULL, NULL, NULL, NULL, NULL),
(452, NULL, NULL, 'Разработка рецептур продуктов питания функционального назначения на основе растительного сырья Иркутской области и организация их безопасного производства ', 15, 'Дать обучающимся возможность приобрести востребованные практико-ориентированные знания, умения, навыки в экспериментальной отработке рецептур функциональных пищевых продуктов и подготовки документации для обеспечения качества, и безопасности их производства', 'Продукты функционального питания и их компоненты могут модифицировать метаболизм в организме человека и играть важную роль в предотвращении возникновения различных заболеваний. При создании безопасного производства продуктов функционального питания необходимо знать химический состав сырья, пищевую ценность, специальные приемы технологической обработки.\nДля обеспечения качества и безопасности продуктов питания необходимо знать и уметь определять факторы, оказывающие негативное влияние на безопасность готовой продукции, зависимость этих факторов от применяемого сырья, технологии, оборудования и упаковки. Применение специальных систем качества и безопасности пищевой продукции позволяет управлять рисками внутри производства и обеспечивать сохранение здоровья потребителя. \n', 1, '2023-02-06', '2023-06-25', '', '', NULL, '1.Разработана рецептура функционального пищевого продукта, проведены эксперименты применения рецептуры с отработкой параметров процесса производства, получен лабораторный образец. \n2.Определены этапы построения системы безопасности пищевой продукции, разработаны обязательные мероприятия для обеспечения безопасности производства, определены возможные риски пищевой безопасности для готовой продукции\n3. Проведены исследования на соответствие показателей качества лабораторного образца требованиям ГОСТ, подтверждено функциональное назначение. Разработана технологическая документация и рекомендации по применению.\n', 'Знания: знать основные принципы организации своей работы, требования к представлению результатов, инструменты поиска информации\nУмения: формулировать цели и задачи; творчески и критически мыслить\nНавыки: работа в команде, получение первичной информации\n', 'Гусакова Г.С., Евстафьева О.А.', 4, 1, 152, NULL, NULL, NULL, NULL, NULL, NULL),
(453, NULL, NULL, 'Организация безопасного производства экологически чистых продуктов питания на основе растительного сырья Иркутской области', 15, 'Дать обучающимся возможность приобрести востребованные практико-ориентированные знания, умения, навыки в подготовки документации для обеспечения качества, и безопасности их производства', 'Для обеспечения качества и безопасности продуктов питания необходимо знать и уметь определять факторы, оказывающие негативное влияние на безопасность готовой продукции, зависимость этих факторов от применяемого сырья, технологии, оборудования и упаковки. Применение специальных систем качества и безопасности пищевой продукции позволяет управлять рисками внутри производства и обеспечивать сохранение здоровья потребителя. ', 3, '2023-02-06', '2023-06-25', '', '', NULL, '1.Определены этапы построения системы безопасности пищевой продукции, разработаны обязательные мероприятия для обеспечения безопасности производства, определены возможные риски пищевой безопасности для готовой продукции', 'Знания: знать основные принципы организации своей работы, требования к представлению результатов, инструменты поиска информации\nУмения: формулировать цели и задачи; творчески и критически мыслить\nНавыки: работа в команде, получение первичной информации\n', 'Евстафьева О.А.', 4, 1, 153, NULL, NULL, NULL, NULL, NULL, NULL),
(454, NULL, NULL, 'Спортивные напитки на основе растительного сырья Иркутской области', 15, 'Дать обучающимся возможность приобрести востребованные практико-ориентированные знания, умения, навыки в подготовки документации для обеспечения качества, и безопасности их производства', 'Продукты функционального питания и их компоненты могут модифицировать метаболизм в организме человека и играть важную роль в предотвращении возникновения различных заболеваний. При создании безопасного производства продуктов функционального питания необходимо знать химический состав сырья, пищевую ценность, специальные приемы технологической обработки', 3, '2023-02-06', '2023-06-25', '', '', NULL, '1.Разработана рецептура функционального пищевого продукта, проведены эксперименты применения рецептуры с отработкой параметров процесса производства, получен лабораторный образец. ', 'Знания: знать основные принципы организации своей работы, требования к представлению результатов, инструменты поиска информации\nУмения: формулировать цели и задачи; творчески и критически мыслить\nНавыки: работа в команде, получение первичной информации\n', 'Гусакова Г.С.', 4, 1, 154, NULL, NULL, NULL, NULL, NULL, NULL),
(455, NULL, NULL, 'Переработка пластиковых отходов.', 15, 'Исследовать возможности переработки бытовых пластиковых отходов.', 'В рамках проекта изучить существующие способы переработки пластиковых отходов, определить наиболее перспективный  способ, провести эксперимент с разными видами пластиков. Исследовать полученные материалы.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Получение синтетического  топлива и определение его свойств. ', 'Знания: способы переработки различных видов пластика,  и методики определения свойств готовых продуктов.\nУмения: подбирать технологию переработки к определенному сырью.\nНавыки: работы с сырьем в лаборатории.\n', 'Оборина М.А.', 4, 1, 156, NULL, NULL, NULL, NULL, NULL, NULL),
(456, NULL, NULL, 'Масла  ', 15, 'Изучение свойств масел разной основы и разного состава', 'При производстве товарных масел, разной масляной основы, необходимо введение различных групп присадок (депрессорных, смазывающих, диспергирующих и др.). отвечающих за эксплуатационные характеристики качества товарной продукции. Базы данных на содержание и состав присадок по маслам закрыты, поэтому введение присадок в базовую нефтяную основу и анализ изменения свойств, а также сравнение с товарными производителями, для учебного процесса является актуальной задачей.', 3, '2023-02-06', '2023-06-25', '', 'Кафедра СДМ (получение образцов для дальнейшего исследования)', NULL, 'Получение масляной основы с заданными свойствами в соответствие с нормативной документацией и существующими аналогами товарной продукции.  ', 'Знания: технологических процессов и основного оборудования производства нефтяных масел; основных параметров химмотологии смазочных материалов\nУмения: выявления возможных причин, вызывающих отклонения от норм качества готовой продукции\nНавыки: работы с маслами, а также технических требований к нефтяным маслам и их примения\n', 'Подгорбунская Татьяна Анатольевна, Белозерова Ольга Викторовна', 4, 1, 157, NULL, NULL, NULL, NULL, NULL, NULL),
(457, NULL, NULL, 'Пластичные смазки', 15, 'Получение пластичных смазок ', 'В настоящее время промышленность стремительно развивается и характеризуется созданием высокопроизводительных машин и механизмов, генерирующих и передающих большие мощности. По мере распространения технического прогресса усиливается энергонапряженность множественных узлов трения и, соответственно, возрастает роль смазочного материала как наиболее значимого элемента техники, повышаются и становятся разнообразнее требования к его качеству. Работоспособность техники, развитие автомобилестроения и других видов транспортного машиностроения, а, следовательно, и эффективность функционирования народного хозяйства серьезно зависят от их обеспеченности высокоэффективными смазочными материалами – пластичными смазками.\nПроблема – снизить износ поверхностей, подвергающихся трению и нагрузкам. Это позволит продлить срок эксплуатации деталей механизмов, сделает их более долговечными и надежными. В ряде случаев смазки применяются не только для снижения износа, но и для предотвращения трения и заклинивания смежных поверхностей. Благодаря своей пластичности и составу эти мазки защищают от проникновения агрессивных веществ, газов и паров. Также практически все консистентные смазки отличаются антикоррозионными свойствами и т.д. Необходимо расширять сырьевую базу и увеличивать рабочий диапазон применения пластичных смазок\n', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Пластичные смазки с заданными свойствами. Позволит расширить ассортимент данных нефтепродуктов.', 'Знать: основные параметры химмотологии смазочных материалов, технологические процессы и основное оборудование производства масел\nУметь: обосновывать технические требования к пластичным смазкам для обеспечения их рационального применения в современной технике \nВладеть основными требованиями предъявляемые к пластичным смазкам, и научными и практическими достижениями в области химмотологии смазок. \n', 'Белозерова Ольга Викторовна, Подгорбунская Татьяна Анатольевна', 4, 1, 158, NULL, NULL, NULL, NULL, NULL, NULL),
(458, NULL, NULL, 'Малотоннажная химия', 15, 'Разработать технологическую концепцию переработки пластиковых отходов', 'Самые распространенные способы переработки пластика – это механический и термический. При механическом способе пластиковые отходы подвергают дроблению, измельчению и перетиранию до получения порошка, который далее добавляют в расплав при получении нового материала. А самый распространенный термический способ – это сжигание, при котором происходят выбросы оксида углерода в атмосферу. Данный проект посвящен переработке пластиковых отходов с целью получения исходных мономеров, продуктов имеющих высокую стоимость и востребованность на рынке химических продуктов.', 2, '2023-02-06', '2023-06-25', '', 'Ангара-Реактив, ООО зарегистрирована по адресу 665809, Иркутская обл., г. Ангарск, тер. Первый промышленный массив, кв-л 7, стр. 22, ОФИС 20. Директор организации ООО \"Ангара-Реактив\" Шатохина Валентина Александровна. Основным видом деятельности компании является Производство прочих химических продуктов, не включенных в другие группировки. Также Ангара-Реактив, ООО работает еще по 25 направлениям.\nООО \"Ангара-Реактив\" присвоен ИНН 3801059241, КПП 380101001, ОГРН 1023800520501, ОКПО 55573556\nДействует с 10.07.2001\n', NULL, 'Удобный, безопасный и дешевый способ переработки пластиковых отходов', 'Знать сырье органического синтеза, основные процессы органического синтеза, способы оценки качества целевого продукта, достоверные источники информации и базы данных в области химии.\nУметь искать информацию о химических соединениях по формульным указателям и ключевым словам, составлять химическую схему получения целевого продукта из доступного сырья.\nВладеть критериями выбора оптимальной схемы химической схемы синтеза целевого продукта\n', 'Боженков Георгий Викторович, Чайка анна Анатольевна', 4, 1, 159, NULL, NULL, NULL, NULL, NULL, NULL),
(459, NULL, NULL, 'Изучение влияния углеводородного состава высокооктановых бензинов на его эксплуатационные характеристики', 15, 'Изучить влияние углеводородного состава высокооктановых бензинов  производства АО «АНХК» на его эксплуатационные характеристики.', 'Важной задачей российской нефтепереработки, повышающей ее конкурентоспособность, является доведение эксплуатационных и экологических свойств автомобильных бензинов до требований мирового уровня. Растет потребность в моторных топливах с октановым числом 95 и выше.  Использование в составе бензинов различного рода добавок и присадок, обеспечивает повышение октанового числа, но при этом необходимо знать какое влияние они окажут на углеводородный состав и как следствие на эксплуатационные характеристики топлива. Поэтому изучение влияния углеводородного состава высокооктановых бензинов  производства АО «АНХК» на его эксплуатационные характеристики является актуальной задаей.', 2, '2023-02-06', '2023-06-25', '', 'АО «АНХК»', NULL, 'Изучено влияние углеводородного состава высокооктановых бензинов  производства АО «АНХК» на его эксплуатационные характеристики.', 'Знания: основные постулаты эффективности добавок и присадок, применяемых для улучшения эксплуатационных характеристик автобензинов\nУмения: на основании теории объяснить эффективность действия октаноповышающих добавок и присадок\nНавыки: владеть навыками оценки влияния углеводородного состава высокооктановых бензинов на его эксплуатационные характеристики.\n', 'Ганина Анна Александровна', 4, 1, 160, NULL, NULL, NULL, NULL, NULL, NULL),
(460, NULL, NULL, 'Полифункциональные (нано)композиты – молекулярный дизайн, структурные особенности, фундаментальные свойства.', 15, 'Создание  новых полифункциональных композитов с целенаправленно формируемой структурой и свойствами для водородной энергетики.', 'Полимерные композиты, сформированные в результате комбинации компонентов различной химической природы, представляют собой новый класс композиционных материалов с характеристиками, превосходящими аналогичные показатели отдельно взятых составляющих. В результате композиционного эффекта они проявляют уникальные механические, магнитные, оптоэлектронные и др. свойства, обладают высокой химической и термической стабильностью, а также устойчивостью к УФ-излучению. Существенное влияние на свойства таких композитов оказывает переход к нанометровому диапазону размеров индивидуальных компонентов системы. Обширную группу органо-неорганических композитов составляют структуры на основе диоксида кремния, полученные в результате золь-гель процесса с участием тетралкоксисиланов в присутствии высокомолекулярных соединений. Основная роль кремнийорганического прекурсора в таких системах сводится к регулированию процесса структурообразования композита, возможности управления размерами наночастиц и физико-техническими характеристиками материала. При этом кремниевый компонент композита - диоксид кремния, не содержит функциональных групп. В качестве носителя химически-активных фрагментов выступают функциональные высокомолекулярные соединения. Строение функциональных групп предшественников композитов позволит регулировать особенности их структуры и комплекс физико-химических свойств. В результате проведенных исследований будет установлена принципиальная возможность использования предлагаемых полифункциональных композитов при конструировании топливных элементов.', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Полимерные мембраны для топливных элементов, обладающие протонной проводимостью. Физический прототип.', 'Знания: Способы и лабораторные методы получения полимерных мембран.\nУмения: Выбирать рациональную схему получения полимерной мембраны для топливных элементов с заданными эксплуатационными свойствами.\nНавыки: Синтезировать полимерной мембраны для топливных элементов с заданными эксплуатационными свойствами\n', 'Шаглаева Нина Савельевна, Баяндин Виктор Владимирович', 4, 1, 162, NULL, NULL, NULL, NULL, NULL, NULL),
(461, NULL, '2022-08-30 13:09:56', 'Статистическая обработка эксперимента', 15, 'Анализ экспериментальных данных, способность обсуждать полученные результаты и предвидеть течение эксперимента в перспективе', 'Проведение эксперимента - это только часть научной задачи. Главная роль исследователя планирование процесса заранее (предвидеть разные направления) и умение интерпретировать полученные данные, которые в дальнейшем должны реализоваться в научной публикации.', 1, '2023-02-06', '2023-06-25', NULL, NULL, NULL, 'не указан', 'Знать принципы измерения и аппаратурное оформление, возможности и ограничения каждого метода\r\nУметь обобщать полученные результаты Владеть методами планирования и проведения эксперимента и оценки полученных результатов', 'Айзина Юлия Александровна', 4, 1, 163, NULL, NULL, NULL, NULL, NULL, NULL),
(462, NULL, NULL, 'Браслеты с GPS-трекерами для контроля за состоянием здоровья, подключением техники безопасности и улучшением производственного травматизма.', 15, 'оснащение производственных рабочих браслетами с GPS-трекерами для контроля за состоянием здоровья, подключением техники безопасности и улучшением производственного травматизма.', 'ввиду удаленности большинства ремонтных участков Группы Компаний от специалистов по охране труда существует потребность в удаленном мониторинге соблюдения техники безопасности и состояния здоровья рабочих. В рамках проекта предлагается разработать прототип, основанный на измерении показателей состояния сотрудников с возможностью геопозиционирования и разграничения рабочих и опасных зон.', 3, '2023-02-06', '2023-06-25', '', 'Лаборатория энергетики Акселерационная программа, реализуемая ГК «ЕвроСибЭнерго» на базе ИРНИТУ\n\n\n\nконкурс научно-исследовательских проектов \"Авангард науки\"\n\nЛаборатория энергетики:\n“Оснащение производственных рабочих браслетами с GPS-трекерами для контроля за состоянием здоровья, подключением техники безопасности и улучшением производственного травматизма.”\n', NULL, 'Определен оптимальный функционал, заданы ключевые параметры отслеживания.\nРазработано техническое решение. Проработаны возможные поставщики оборудования, программного обеспечения.\n', 'Знать виды, функциональное назначение, свойства беспроводных персональных сетей \nУметь составлять алгоритм работы устройства для конкретного назначения.\nВладеть навыками использования программных продуктов, предназначенных для программирования миниатюрных вычислительных устройств\n', 'Губин Никита Андреевич', 4, 1, 164, NULL, NULL, NULL, NULL, NULL, NULL),
(463, NULL, NULL, 'Наблюдение измеряемых параметров физических сред и предметов с использованием  децентрализованных самоорганизующихся сетей', 15, 'Формирование знаний о структуре сети, основных протоколах и порядке передачи данных, удаленном мониторинге и измерении физических величин, перспективных способах измерений и передачи данных нового поколения.', 'Глобализация рынков, конкуренция, стремительное развитие технологий и наукоемких инноваций, появление сверхсложных научно-технических проблем требует от промышленности гораздо более быстрых темпов развития, предельно коротких циклов контроля и измерения физических характеристик в процессе разработки и производства продукции высокого качества. \nСпрос на сложные многофункциональные инженерные изделия стимулирует процесс постоянных модификаций как самих устройств так и способов их взаимодействия.\nПерспективным трендом является создание беспроводных децентрализованных самоорганизующихся сенсорных сетей, состоящих из беспроводных сенсоров и управляющих устройств способных к самоорганизации с помощью интеллектуальных алгоритмов,\nВ рамках проекта студентам предлагается провести анализ новых способов удаленного мониторинга и контроля, получить общие навыки по измерениям и мониторингу состояния  здоровья человека, окружающей среды, функционирования производственных и транспортных систем, учета различных ресурсов и др. \nЗнания, которые будут получены учащимися в ходе проектной работы, могут быть применены в их дальнейшей научно-исследовательской деятельности.   \n', 2, '2023-02-06', '2023-06-25', '', 'Лаборатория энергетики Акселерационная программа, реализуемая ГК «ЕвроСибЭнерго» на базе ИРНИТУ\n\n\n\nконкурс научно-исследовательских проектов \"Авангард науки\"\n\nЛаборатория энергетики:\n1)интеллектуальная система смазки подшипников электромашин постоянного тока.\n2)система централизованной смазки стрелы и находящейся на ней элементов.\n', NULL, 'Разработка лабораторного стенда, с сетью взаимосвязанных заменяемых беспроводных датчиков.', 'Знать виды, функциональное назначение, свойства беспроводных персональных сетей \nУметь составлять алгоритм работы устройства для конкретного назначения.\nВладеть навыками использования программных продуктов, предназначенных для программирования миниатюрных вычислительных устройств\n', 'Губин Никита Андреевич', 4, 1, 165, NULL, NULL, NULL, NULL, NULL, NULL),
(464, NULL, NULL, 'Система контроля целостности металлоконструкции стрелы экскаватора марки ЭШ', 15, 'Разработка системы контроля целостности металлоконструкции стрелы экскаватора марки ЭШ', 'Измерение целостности металлоконструкции стрелы эксковатора', 3, '2023-02-06', '2023-06-25', '', 'Лаборатория энергетики Акселерационная программа, реализуемая ГК «ЕвроСибЭнерго» на базе ИРНИТУ\n\n\n\nконкурс научно-исследовательских проектов \"Авангард науки\"\n\nЛаборатория энергетики:\n“ Система контроля целостности металлоконструкции стрелы экскаватора марки ЭШ.”\n', NULL, 'Система контроля целостности металлоконструкции стрелы экскаватора марки ЭШ', 'Знать виды, функциональное назначение, свойства датчиков угла наклона \nУметь составлять алгоритм работы программы. \nВладеть навыками использования программных продуктов, предназначенных для программирования микроконтроллеров\n', 'Ченский Дмитрий Александрович', 4, 1, 166, NULL, NULL, NULL, NULL, NULL, NULL),
(465, NULL, NULL, 'Вибродиагностика сороудерживающих решеток', 15, 'Разработка системы мониторинга уровня вибрации сороудерживающих решёток братской ГЭС с целью выявления предельных нагрузок.', 'Вибродиагностика сороудерживающих решёток братской ГЭС с целью выявления предельных нагрузок.', 3, '2023-02-06', '2023-06-25', '', 'Лаборатория энергетики Акселерационная программа, реализуемая ГК «ЕвроСибЭнерго» на базе ИРНИТУ\n\n\n\nконкурс научно-исследовательских проектов \"Авангард науки\"\n\nЛаборатория энергетики:\n“ Вибродиагностика сороудерживающих решеток.”\n', NULL, 'Система мониторинга уровня вибрации сороудерживающих решёток', 'Знать виды, функциональное назначение, свойства датчиков вибрации  \nУметь составлять алгоритм работы устройства для конкретного назначения.\nВладеть навыками использования программных продуктов, предназначенных для программирования микроконтроллеров\n', 'Ченский Дмитрий Александрович', 4, 1, 167, NULL, NULL, NULL, NULL, NULL, NULL),
(466, NULL, NULL, 'влияние  пористых  алюмосиликатных  матриц  на свойства протон-проводящих мембран  для топливных элементов', 15, 'Изучить влияние различных пористых алюмосиликатных матриц, в частности, цеолитов разных структурных типов на характеристики протон-проводящих мембран для топливных элементов.', 'Ионообменные мембраны на основе поливинилового спирта (ПВС) представляют собой перспективную группу материалов для применения в тведополимерных топливных элементах (ТПТЭ) благодаря высокой гидрофильности, способности к пленкообразованию, низкой стоимости, хорошим механическим свойствам и возможности сшивания ПВС различными химическими реагентами. Для улучшения технических характеристик таких мембран, используют керамические материалы на основе оксидов алюминия, кремния, титана, олова, циркония и др., которые способные повысить ионную проводимость, химическую и термическую стабильность, а также механическую прочность мембран. В настоящее время   большое внимание уделяется  получению новых биоразлагаемых протонообменных мембран для ТПТЭ, полученных на основе сшитого сульфоянтарной кислотой поливинилового спирта с добавлением в качестве кислотного компонента – цеолитов. В работе предлагается для получения таких мембран использовать цеолиты различных структурных типов и изучить влияние не только структурного типа цеолита, но и его содержания на характеристики мембран. ', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Предполагается получение протон-проводящих мембран на основе цеолитов разных структурных типов и изучение их характеристик. ', 'Знания: углубленные знания золь-гель технологии; технологии синтеза цеолитных материалов, методов тестирования характеристик мембран для ТПТЭ; \nУмения: выбрать соответствующие методы и подходы для синтеза мембран для ТПТЭ;\nНавыки: использования методов синтеза протон-проводящих мембран и тестирования их рабочих характеристик.\n', 'Скорникова Светлана Афанасьевна', 4, 1, 168, NULL, NULL, NULL, NULL, NULL, NULL),
(467, NULL, NULL, 'влияние  модифицирования  алюмосиликатов  на  их  физико-химические характеристики', 15, 'Исследовать влияние различных способов модифицирования синтетических алюмосиликатов, в том числе цеолитов, на их физико-химические характеристики. ', 'Цеолиты находят широкое применение в нефтехимии и нефтепереработке. Кроме этого в последнее время возрос интерес к цеолитам и в качестве уникальных адсорбентов, которые нашли применение и в медицине. С этой целью возрос интерес исследователей к разработке нетрадиционных способов их модифицирования для получения новых характеристик, таких как микро-мезопористая структура, магнитные характеристики, кислотные свойства и др. В связи с этим целью данного проекта является  изучение влияние различных способов модифицирования цеолитов на их физико-химические свойства.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Получены модифицированные образцы цеолитов, изучены их характеристики. ', 'Знания: получены углубленные знания в области поверхностных явлений в дисперсных системах и физико-химии наноразмерных систем; \nУмения: выбрать оптимальные способы модифицирования цеолитов; \nНавыки: использовать их для получения соответствующих характеристик цеолитов\n', 'Скорникова Светлана Афанасьевна', 4, 1, 169, NULL, NULL, NULL, NULL, NULL, NULL),
(468, NULL, NULL, 'синтез  магнитоуправляемых композитов на основе цеолитов и магнитных наночастиц', 15, 'Целью проекта является создание наноразмерных магнитных цеолитов путем добавления магнитных F3O4 частиц в процессе кристаллизации, для получения кристаллов цеолита с магнитным ядром внутри структуры.', 'Получение магнитных нанокомпозитов на основе пористых носителей является одним из возможных способов разработки систем адресной магнитоуправляемой доставки лекарственных препаратов. Определенный интерес вызывает получение композитных материалов на основе цеолитов и наночастиц магнетита. Цеолиты - это микропористые кристаллические вещества. Кристалличность обеспечивает механическую и химическую стабильность цеолитов, одинаковый и контролируемый размер пор, каналов, полостей. Это свойство определяет использование цеолитов в качестве молекулярных сит, адсорбентов, детергентов. Благодаря своим ионообменным и сорбционным свойствам, широко применяются для химической, нефтехимической и нефтеперерабатывающей промышленности, экологии и медицины.  Цеолиты благодаря особенностям своей структуры являются уникальными сорбентами, позволяющими осуществлять эффективную адсорбцию и высвобождение лекарственных препаратов в физиологической среде организма, при этом они являются нетоксичными и биоразлагаемыми материалами. Модифицирование цеолитов магнитными наночастицами позволяет придать им магнитные свойства', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Планируется получить магнитоуправляемый композитов на основе цеолитов и магнитных наночастиц. Данный нанокомпозит будет иметь уникальные свойства цеолита и обладать магнитными свойствами, что позволит увеличить области возможного его применения.  ', 'Знания: дополнительные знания в области нанохимии магнитных материалов;\nУмения: применять методы соосаждения, золь-гель методы и гидротермальный синтез для получения магнитных композитов на основе цеолитов;\nНавыки: гидротермального синтеза цеолитов с магнитным ядром, позволяющие получить материалы с магнитными свойствами и высокой адсорбционной способностью.\n', 'Скорникова Светлана Афанасьевна', 4, 1, 170, NULL, NULL, NULL, NULL, NULL, NULL),
(469, NULL, NULL, 'Выполнение планировочного раздела проектной документации', 15, 'разработка раздела проектной документации - Генеральный План', 'Ознакомление с функциями архитектора,  главного архитектора проекта и главного инженера проекта, организация процесса проектирования.\nСостав проектной документации «П» и объем выполнения рабочей документации «Р»\n', 1, '2023-02-06', '2023-06-25', '', '', NULL, 'Комплект чертежей', 'Знания: основные требования к выполнению раздела проектной документации. \nУмения: обосновывать принятые проектные решения\nНавыки: оформления проекта\n', 'Иванова Анастасия Сергеевна', 4, 1, 171, NULL, NULL, NULL, NULL, NULL, NULL),
(470, NULL, NULL, 'Малоэтажный жилой дом', 15, 'Создание эскизного концептуального проекта малоэтажного жилого дома', 'Определения понятия предмета проектирования - (малоэтажный жилой дом: типология, эволюция, современные тенденции).  Определение композиционно-образного решения жилого дома;  анализ градостроительных условий, определение функциональной структуры и объемно - планировочной композиции жилого дома:  (план фундамента, поэтажные планы, план крыши, узлы, детали, разрезы, спецификации). Эскизы фрагментов, планировка, этажей и уровней. ', 1, '2023-02-06', '2023-06-25', '', '', NULL, 'Эскизный концептуальный проекта малоэтажного жилого дома', 'Знания: Основы взаимодействия со специалистами смежных областей. Основа архитектурно-строительного проектирования\nУмения: Взаимодействовать со специалистами смежных областей входе разработки жилых объектов. Участвовать в разработке проектной документации. Грамотно представлять проектный замысел, передавать идеи средствами компьютерной графики\nНавыки: Работы в творческом коллективе; Навыки участия в разработки проектной документации\n', 'Дайнеко Виктория Владимировна', 4, 1, 172, NULL, NULL, NULL, NULL, NULL, NULL),
(471, NULL, NULL, 'Реновация общественного здания', 15, 'Цель продукта: Усовершенствование дизайна городской архитектурной среды, профессиональное применение современных материалов.\nОбразовательная цель:  формирование у студентов соответствующих  знаний, навыков, мотивации  и ответственности\n', 'Предполагаемая организация делает запрос на выполнение реновации с возможной с архитектурной реконструкцией общественного здания, включая интерьер, экстерьер и благоустройство', 1, '2023-02-06', '2023-06-25', '', 'Предприятие, сторонняя организация', NULL, 'Стильное современное общественное пространство здания и его окружения с индивидуальной концепцией, с разработанными эксклюзивными авторскими предметами и малыми архитектурными формами.', 'Знания:    принимать объемно-пространственные, конструктивные, художественные, инженерные решения, понимать эксплуатационные качества объектов проектирования\nУмения:  учитывать взаимосвязь всех этих компонентов - объемно-пространственных, художественных, конструктивных, инженерных, эксплуатационных качеств объектов проектирования\nНавыки:  формировать объемно-пространственную среду, учитывая ее художественные, конструктивные, инженерные и эксплуатационные особенности\n', 'Глебова Наталья Моисеевна', 4, 1, 173, NULL, NULL, NULL, NULL, NULL, NULL),
(472, NULL, NULL, 'Интерьер музея. «Концепция Школьного музея МБОУ «Буретская СОШ».', 15, 'Реализовать умение выполнять поиск, критический анализ и синтез информации, применять системный подход для решения задач, разработать проект на основе оценки требований, ресурсов и ограничений, работать в команде, управлять своим временем, выстраивать и реализовывать траекторию создания целостного, насыщенного многофункциональной инфраструктурой пространства', 'Проект музея направлен на сохранение исторической памяти и наследия; развитие интереса к истории, углубление знаний по истории и формирование на конкретном историческом материале гражданско – патриотических чувств и убеждений, утверждение значимости таких ценностей. Воспитание у учащихся стремления к овладению глубокими знаниями, высоконравственными качествами в процессе изучения истории, культуры родного края. Основные  задачи программы-проекта: Через краеведческий материал осуществлять связь с окружающей обстановкой, воспитания патриотического чувства, любви к Родине, к родному городу, своему поселку. Для архитектурно-дизайнерской классификации существенное значение имеет комплексный характер экспозиции; развитый состав помещений, включающий зоны для постоянной экспозиции, временных выставок и лекций, фондохранилища, мастерские и лаборатории, административные, подсобные и хозяйственные помещения. представляющие сочетание новых пространств с существующими. Общепринятое понимание музея как хранителя подлинных экспонатов и место их показа уходит на второй план: на первое место выделяется не показ музейными средствами, а создание пространства архитектурно-художественными средствами. Важную роль в архитектурно-пространственном формировании интерьера имеет существующее окружение, сохраняемая или создаваемая среда, в которую включается комплекс. Учитывая ярко выраженную специфику, музеи школ могут быть выделены по пространственным решениям в самостоятельную группу.', 3, '2023-02-06', '2023-06-25', '', 'МБОУ «Буретская СОШ», Иркутская обл., директор Серова С.В.', NULL, '«Концепция Школьного музея» (альбом чертежей)', 'Знания: основные принципы планирования и организации своей деятельности, инструменты поиска информации, основные стратегии поиска информации, требования и ресурсные ограничения  к представлению результатов проекта, основные приемы управления.\nУмения: использовать различные инструменты поиска и анализа информации, критически оценивать и подготовить полученные результаты, выполнять критический анализ и сформулировать перечень недостающих  знаний, организовывать работы команды (коллектива) для достижения поставленных целей.\nНавыки: поиска и анализа информации, определения и постановки задач,  организации работы команды, четкого формулирования запроса на поиск новых знаний, на основе полученной первичной информации сформировать комплексное понимание предмета изучения, разработки стратегии разработки проекта  на основе сформулированного запроса, презентации результатов проекта,навыками командной работы и управления коллективом.\n', 'Хохрин Евгений Викторович', 4, 1, 174, NULL, NULL, NULL, NULL, NULL, NULL),
(473, NULL, NULL, 'Интерьер музея. «Разработка интерьера Школьного музея МБОУ «Буретская СОШ».', 15, 'Реализовать умение выполнять поиск, критический анализ и синтез информации, применять системный подход для решения задач, разработать проект на основе оценки требований, ресурсов и ограничений, работать в команде, управлять своим временем, выстраивать и реализовывать траекторию создания целостного, насыщенного многофункциональной инфраструктурой пространства.', 'Категория музея определяется величиной фондов и количеством посещений. Музеи подразделяются по организационному признаку на центральные, осуществляющие научно-методическое руководство своей группой; появились музеи, представляющие собой концептуальный литературный художественный образ. Изменилась стилевая характеристика зданий, вызванная свободным решением разверток стен  и планов. Как и другие типы пространств, музеи проектируются вразличных стилях. Стилевая направленность часто совпадает с профилем музея. Известны такие как: краеведческие, региональные, мемориальные, в память исторических событий, современного искусства, промышленности и техники, частных коллекций, города и др. Музей характеризуется для городов и населённых мест с учётом различных концепций развития комфортной социальной среды. Поиск архитектурно-художественного образа музейного здания является одной из первостепенных задач проектирования. Специальное внимание уделяется художественному, эмоциональному, выразительному решениюпространства музея.\nИнтерьер музея проектируется из расчёта единовременного пребывания в нём 15 и более посетителей\n', 3, '2023-02-06', '2023-06-25', '', 'МБОУ «Буретская СОШ», Иркутская обл.,\nдиректор Серова С.В\n', NULL, '«Интерьер Школьного музея» (альбом чертежей)', 'Знания: принципы формирования командной стратегии, нормы и способы социального взаимодействия, различные инструменты поиска и анализа информации, основные способы выражения авторского архитектурного замысла, технологии архитектурно-строительного проектирования, \nУмения: на основе синтеза и анализа информации получить представление о связях между составляющими предмета изучения, учитывать взаимосвязь объемно-пространственных, конструктивных, инженерных решений и эксплуатационных качеств объектов проектирования,\nНавыки: уметь спланировать и реализовать проект с учетом ресурсных ограничений и требований к результату  проекта; презентации результатов проекта,\n', 'Смольков Сергей Александрович', 4, 1, 175, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(474, NULL, NULL, 'Выполнение архитектурного раздела проектной документации', 15, 'разработка раздела проектной документации марки «АР» - архитектурные решения', 'Создание проектной документации в соответствии с  действующими стандартами, комплекта чертежей ПЗУ (ГП) на основе предложенного объекта с посадкой его на топографической съёмке участка в составе: План благоустройства территории, План организации рельефа, План и конструкции дорожных одежд (покрытий)\nСоздание проектной документации в соответствии с действующими стандартами комплекта чертежей АР на основе предложенного проекта здания в составе: Планы, Разрезы, Фасады, Необходимые узлы и детали\n', 3, '2023-02-06', '2023-06-25', '', 'Проектные институты, \nчастные проектные предприятия и фирмы\n', NULL, 'Комплект чертежей марки «АР»', 'Знания: Ознакомление и изучение действующих требований к комплектам проектных документов на различные здания и сооружения\nУмения: Создание комплектов  рабочей документации для различных объектов\nНавыки: Освоение профессионального языка и взаимоотношение со смежными специальностями\n', 'Жуковский Николай Леонидович', 4, 1, 176, NULL, NULL, NULL, NULL, NULL, NULL),
(475, NULL, NULL, 'Многоэтажный общественный административный корпус ИРНИТУ', 15, 'Улучшение пространственно - планировочных, эксплуатационных, функциональных, эстетических характеристик университета, значительное увеличение полезной рабочей площади, создание образа современного высокотехнологичного вуза и кампуса ИРНИТУ.', 'Многоэтажный общественный административный корпус ИРНИТУ предполагается разместить со стороны существующего главного входа в университет по ул. Лермонтова. В отдельно стоящем монолитно - каркасном блоке – многоэтажной башне помимо необходимых помещений для ректората и сопутствующих административных служб должны разместиться представительские помещения для переговоров, совещаний, конференций, просторные холлы, выставочные пространства с витринами для демонстраций ярких студенческих разработок: проектов и моделей. Башня соединяется с существующим зданием двухэтажным блоком, где возможно размещение просторного светлого входного вестибюля с гардеробом (в цоколе), кафе, второго спортзала, других общественных пространств и помещений. Башня должна быть доминантой в окружающей застройке, архитектура нового корпуса решается в современной стилистике, гармоничной и выразительной, и отражающей современные технологии и достижения в строительстве, технике и науке', 3, '2023-02-06', '2023-06-25', '', 'Ректорат ИРНИТУ ', NULL, 'Рабочий проект многоэтажного общественного административного корпуса ИРНИТУ, встроенно – пристроенного к существующему зданию', 'Знания: современные тенденции в архитектуре, современные строительные конструкции и технологии строительства, инженерные коммуникации\nУмения: проектировать общественное здание - образовательное учреждение со сложными функциональными зонами и связями между ними, передать молодежную атмосферу.\nНавыки: разработка архитектурных, конструктивных, инженерных рабочих чертежей зданий, в том числе разделов ОВ, ВК, слаботочных и электрики, чертежей раздела генерального плана участка.\n', 'Дагданова Цыредарь Баторовна', 4, 1, 177, NULL, NULL, NULL, NULL, NULL, NULL),
(476, NULL, NULL, 'Проектирование многоквартирного жилого здания (группы зданий) малой или средней этажности', 15, 'Создание эскизного концептуального проекта жилого здания (группы зданий) малой или средней этажности', 'Проектирование жилого здания (группы зданий) малой или средней этажности имеет ряд требований: природно-климатические условия площадки проектирования, социально-демографические, градостроительные и экологические факторы, учет особенностей существующей застройки, в том числе исторически сложившейся среды (контекст среды), уклад жизни и национальные особенности людей. Для формирования уникального образа жилого здания (группы домов) малой или средней этажности необходимо знать особенности конструктивных решений жилых зданий, владеть знаниями о типологии квартир зданий малой или средней этажности, видах застройки и типах жилых зданий. Любое жилое здание оснащается инженерным оборудованием, имеющее свои особенности, требования и характеристики, которое может быть проработано в случае участия в проекте студентов смежных специальностей. \nПроект выполняется в два этапа (два семестра). На предварительной стадии анализируются примеры жилых зданий, изучается их типология, проводится поиск оригинальных решений планировок и образа жилого здания (группы домов) малой или средней этажности. Могут быть выполнены предварительные эскизы, черновые макеты и применены другие графические поиски в ручном исполнении или с помощью ПК. На следующем этапе командой студентов прорабатываются чертежи раздела АР и других при участии студентов других направлений. \nТаким образом, может быть выполнен комплексный концептуальный проект жилого здания (группы домов) на свободной от застройки площадке или с учетом контекста исторически сложившейся среды\n', 1, '2023-02-06', '2023-06-25', '', 'Проектные мастерские, администрация города/ области, застройщики', NULL, 'Оформление поиска объемно-планировочных решений на планшет(ы), ПЗ и/ или альбом чертежей проекта жилого здания (группы зданий) малой или средней этажности', 'Знания: основные требования  к представлению результатов проекта\nУмения: обосновывать принятые проектные решения\nНавыки: презентации результатов проекта\n', 'Дружинина Инна Евгеньевна', 4, 1, 178, NULL, NULL, NULL, NULL, NULL, NULL),
(477, NULL, NULL, 'Проектирование общественного здания', 15, 'Создание эскизного концептуального проекта общественного здания', 'Проектирование общественного здания имеет ряд требований: знание типологии общественных зданий, особенности их функционального зонирования и технологических процессов, размещение объектов общественного назначения в градостроительной ситуации, учет контекста среды, в том числе и исторической, а также природно-климатические условия, экологические факторы и многое другое. В зависимости от назначения общественного здания, формируется его объемно-планировочное решение и в целом архитектурный образ. \nЛюбое общественное здание имеет свою классификацию и в соответствии с типологическим рангом является второстепенным или доминирующим в градостроительной среде. Для создания уникального образа общественного здания необходимо знать особенности конструктивных решений, владеть знаниями о технологических процессах внутренней организации. Любое общественное здание оснащается инженерным оборудованием, имеющее свои особенности, требования и характеристики, которое может быть учтено в случае работы над проектом студентов смежных специальностей.\nНа предварительной стадии выполняется анализ примеров общественных зданий, изучается их типология, проводится поиск оригинальных решений планировок и образа здания общественного назначения. Могут быть выполнены предварительные эскизы, черновые макеты и применены другие графические поиски в ручном исполнении или с помощью ПК. \nТаким образом, может быть выполнен комплексный концептуальный проект общественного здания на свободной от застройки площадке или с учетом контекста исторически сложившейся среды.\n', 3, '2023-02-06', '2023-06-25', '', 'Союз архитекторов РФ', NULL, 'Планировка общественного здания с проработкой функционального зонирования здания, поиск образа, объемного решения', 'Знания: Знать основные требования  к представлению результатов проекта\nУмения: Уметь  обосновывать принятые проектные решения\nНавыки: Владеть навыками презентации результатов проекта\n', 'Селиванов Роман Александрович', 4, 1, 179, NULL, NULL, NULL, NULL, NULL, NULL),
(478, NULL, NULL, 'Конструктивные и технологические решения проектов реставрации объектов культурного наследия (памятников архитектуры)', 15, 'Разработка проектов реставрации объектов культурного наследия и чертежей проектной документации, а также расчет строительных конструкций в программно-вычислительном комплексе.', 'Обзор и анализ имеющихся программных продуктов по моделированию и расчету зданий и сооружений. Изучение программных комплексов по моделированию и расчету строительных конструкций. Подбор и разработка оптимальных методик моделирования и расчета. Реализация практических расчетов и моделирования конструктивных систем. Подготовка и оформление разделов проектной документации в соответствии с действующей нормативно-правовой базой.', 3, '2023-02-06', '2023-06-25', '', 'Иркутский областной историко-мемориальный музей декабристов', NULL, 'Информационные модели зданий (сооружений); методики и технологии реставрационно-восстановительных работ; Отчет по результатам расчетов в программно-вычислительном комплексе.', 'Знания: Знать нормативно-правовую базу в строительстве. Знать основные принципы и особенности расчета конструкций в особых условиях работы.\n\nУмения: Уметь применять на практике полученные знания. Уметь учитывать специфику особых условий в составлении расчетных схем несущих и ограждающих конструкций. \n\nНавыки: Владеть современными информационными технологиями проектирования. Владеть навыками моделирования, расчета и конструирования строительных узлов, систем и деталей.\n', 'Пинайкин Игорь Петрович', 4, 1, 180, NULL, NULL, NULL, NULL, NULL, NULL),
(479, NULL, NULL, 'Современные технологии исследования и проектирования объектов деревянного зодчества', 15, 'Разработка проектной документации объектов деревянного зодчества, которая включает в себя текстовые и графических материалы, определяющие архитектурные, функционально-технологические, конструктивные и инженерно-технические решения. ', 'Проектная документация необходима для оценки соответствия принятых решений требованиям законодательства и нормативным правовым актам. В ходе прохождения курса необходимо выполнить подбор и разработку оптимальных методик моделирования и проектирования; подготовку и оформление разделов проектной документации в соответствии с действующей нормативно-правовой базой; обзор и анализ имеющихся программных продуктов по моделированию зданий и сооружений. ', 3, '2023-02-06', '2023-06-25', '', 'Экопарк \"Озера на снежной\"', NULL, 'Информационные модели зданий (сооружений); методики и технологии реставрационно-восстановительных работ объектов деревянного зодчества; Текстовая и графическая часть проектной документации.', 'Знания: Знать нормативно-правовую базу в строительстве. Знать основные принципы проектирования конструкций в особых условиях работы.\nУмения: Уметь применять на практике полученные знания. \nНавыки: Владеть современными информационными технологиями проектирования. Владеть навыками моделирования и конструирования строительных узлов, систем и деталей.\n', 'Пинайкин Игорь Петрович', 4, 1, 181, NULL, NULL, NULL, NULL, NULL, NULL),
(480, NULL, NULL, 'Методологические и экономические аспекты информационного моделирования объекта капитального строительства', 15, 'Отработка процесса проектирования с использованием BIM-технологий на различных этапах жизненного цикла зданий и сооружений.', 'Создание информационной модели объекта капитального строительства (технопарк ИРНИТУ).', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Электронная модель сооружения', 'Знания: структура процесса информационного моделирования, состав проекта\nУмения: работа в команде, проектное мышление\nНавыки: моделирование в BIM программах\n', 'Созонов Павел Сергеевич', 4, 1, 182, NULL, NULL, NULL, NULL, NULL, NULL),
(481, NULL, '2022-08-30 09:34:49', 'Конструктивные и технологические особенности проектирования, строительства, реконструкции, капитального ремонта объектов, эксплуатируемых в экстремальных природно-климатических и техногенных условиях и находящихся в аварийном состоянии', 15, 'Отработка процесса моделирования строительных процессов с использованием BIM-технологий на различных этапах жизненного цикла зданий и сооружений.', 'нет описания', 3, '2023-02-06', '2023-06-25', NULL, NULL, NULL, 'Электронная модель сооружения', 'Знания: структура процесса информационного моделирования, состав процесса строительства\r\nУмения: работа в команде, проектное мышление\r\nНавыки: моделирование в BIM программах', 'Петров Александр Владимирович', 4, 1, 183, NULL, NULL, NULL, NULL, NULL, NULL),
(482, NULL, NULL, 'Прогрессивные технологии возведения зданий', 15, 'Разработка новых конструктивных и технологических решений быстровозводимых зданий.', 'Обеспечение высоких технико-экономических показателей возводимых зданий.\n\n• Обеспечение технологичности при строительстве быстровозводимых зданий;\n\n• оптимизация конструктивных и технологических решений при строительстве быстровозводимых зданий\n', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'электронной модели изделия (сооружения)', '', 'Петунин Александр Геннадьевич', 4, 1, 184, NULL, NULL, NULL, NULL, NULL, NULL),
(483, NULL, NULL, 'Проектирование процессов восстановления работоспособности зданий и сооружений, отдельных элементов, конструкций, узлов по результатам обследования их технического состояния', 15, 'Ознакомление с методикой и приобретение практических навыков при визуально-инструментальном обследовании технического состояния зданий и сооружений, систематизации фактического материала, анализа полученных результатов, формирования выводов, поиска технических решений проблемы и участия в проектировании ремонтно-восстановительных работ', 'Исключение аварийности зданий и сооружений и приведение объектов капитального строительства находящихся в неисправном или ограниченно-работоспособном состоянии в исправное техническое состояние.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'База данных полученных в составе коллектива исполнителей на реальных объектах капитального строительства, статистическая обработка, поверочные расчеты, формирование выводов, проектные решения.', 'Знать\nИзучение методики и методов проведения обследования технического состояния зданий и сооружений, причин возникновения дефектов и деформации, назначение и порядок использования приборов и оборудования. Изучение нормативных документов регламентирующих требования к проведению обследований строительных объектов и работам по контролю за уровнем безопасности зданий и сооружений\nУметь\nПрименять на практике различные методики и методы обследования зданий и сооружений, используя действующие нормативные документы; выявлять, фиксировать дефекты и повреждения, анализировать причины их появления, оценивать техническое состояние объектов.\nВладеть\nОбщими организационными вопросами обследования технического состояния зданий и сооружений, сбора материалов и необходимой технической информации для реализации проекта ремонтно-восстановительных работ.\nЗнать\nСостав, содержание и требования к полноте разделов комплексной программы обследования технического состояния зданий и сооружений; требования к корректности и обоснованности выводов.\nУметь\nПод руководством научного руководителя разрабатывать отдельные темы программы комплексных обследований конструкции зданий и сооружений; проводить обработку полученных данных.\nВладеть\nНавыками составления программ комплексного обследования зданий и сооружений; под руководством научного руководителя определять категорию технического состояния конструкций и сооружений; оценивать необходимый объем работ для включения в техническое задание для программы. \n', 'Комаров Константин Андреевич', 4, 1, 185, NULL, NULL, NULL, NULL, NULL, NULL),
(484, NULL, NULL, 'Разработка проекта капитального ремонта жилого дома с применением цифровых технологий', 15, 'Создание проекта капитального ремонта жилого дома на основе визуального обследования и обмера с применением различных проектных программ', 'Капитальный ремонт жилых многоквартирных домов является острой проблемой, для решения которой в нашей стране были созданы фонды капитального ремонта многоквартирных домов. Для более качественного выполнения ремонтных работ и расчета сметной стоимости возникает необходимость в создание проектно-сметной документации. Студенты могут на основе реальных объектов выполнить ряд практических задач: визуальный осмотр, выявления дефектов, обмер здания, создание графических чертежей в цифровой среде, расчет объемов работ, описание технологии производства работ. По окончанию работы студенты представляют готовый проект', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Проект капитального ремонта многоквартирного жилого дома', 'Знать перечень работ входящих в состав капитального ремонта и технологию их выполнения уметь выполнять создавать проектную документацию в цифровой среде', 'Ефременко Антон Сергеевич', 4, 1, 186, NULL, NULL, NULL, NULL, NULL, NULL),
(485, NULL, NULL, 'Информационные технологии в дорожном строительстве', 15, 'Разработка методических основ и прикладного инструментария по совершенствованию информационных технологий по проектированию, строительству, эксплуатации, мониторингу автомобильных дорог и искусственных сооружений.', ' Проект направлен на усовершенствование и систематизацию средств информационных систем, предназначенные для решения задач дорожного строительства.', 3, '2023-02-06', '2023-06-25', '', 'Администрация города Иркутска', NULL, 'Разработка  методических основ, механизмов, моделей и практических рекомендаций по применению эффективных инструментов для информационных систем, применимых в дорожном строительстве.', 'Знания: в области информационных технологий дорожного строительства.\nУмения: использовать инструментарий информационных систем для достижения конкретных целей.\nНавыки: осуществлять сбор и обработку исходной информации для определения использования информационных технологий\nУправление проектом и моделирование строительного производства', 'Мартьянов Владимир Иванович', 4, 1, 187, NULL, NULL, NULL, NULL, NULL, NULL),
(486, NULL, NULL, 'Проектирование инженерного комплекса горячего водоснабжения (ГВС) для рекреационных зон с использованием возобновляемых источников энергии', 15, 'Обеспечение устойчивого горячего водоснабжения в рекреационных зонах на основе альтернативных источников энергии и очистка стоков с использованием энергосберегающих технологий', 'Получение устойчивых характеристик систем жизнеобеспечения (горячего водоснабжения, освещения, очистки сточных и природных вод) за счет оптимизации энергоэффективных параметров с использованием альтернативных источников энергии для удаленных селитебных территорий и рекреационных зон. \nПрименение солнечных коллекторов для получения горячего водоснабжения, использование солнечных панелей для получения электрической энергии, применение энергоэффективных технологий для очистки природных и сточных вод позволит создать мобильный энергоконтейнер (комплекс из основных систем жизнеобеспечения) для удаленных селитебных территорий и рекреационных зон.\n', 3, '2023-02-06', '2023-06-25', '', 'Тематика предприятия ООО «Инженерный  центр» в рамках корпоративного акселератора в 2019 году. Имеется опыт сотрудничества в проектной деятельности (приказ № 905-П от 03.12.2019 г.)', NULL, 'Проект приводит алгоритм подбора энергоэффективности систем и оборудования жизнеобеспечения, выполнение архитектурно-строительных и компоновочных решений', 'Знания: знать инновационные направления в области энергосбережения объектов строительства и их эксплуатации\nУмения: уметь подбирать новейшие методы, сооружения и технологий для энергоэффективных объектов\nНавыки: владеть основами подготовки документации для создания системы менеджмента качества на период жизненного цикла объектов строительства\n', 'Толстой Михаил Юрьевич', 4, 1, 188, NULL, NULL, NULL, NULL, NULL, NULL),
(487, NULL, NULL, 'Проект энергоэффективности и оптимизации систем жизнеобеспечения населённого пункта', 15, 'Повышение надежности, проектирование и расчет систем жизнеобеспечения для селитебных зон и промышленных предприятий на основе системного подхода.', 'Формирование оптимальных систем жизнеобеспечения селитебной зоны.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Спроектированный полный набор систем жизнеобеспечения жилых и общественных зданий селитебной зоны  - наружные и внутридомовые сети.', 'Знания: правил проектирования энергоэффективных систем жизнеобеспечения, принципов их оптимизации.\nУмения: использование теоретических знаний при проектировании сетей в конкретных условиях\nНавыки: применения оптимизационных технологий к спроектированным системам\n', 'Айзенберг И.И.', 4, 1, 189, NULL, NULL, NULL, NULL, NULL, NULL),
(488, NULL, NULL, 'Разработка проекта систем водоснабжения и водоотведения здания', 15, 'Формирование компетенции в области систем водоснабжения и водоотведения зданий и сооружений.', 'Системы жизнеобеспечения, обеспечивающие благоустройство и комфортность жилых, общественных и производственных зданий, представляют собой комплекс трубопроводов, сооружений, технических устройств, предназначенных для обеспечения комфортных условий быта и трудовой деятельности населения, коммунальных и промышленных предприятий.\nРазработка проекта систем водоснабжения и водоотведения здания способствует подготовке специалистов в области проектирования, монтажа и эксплуатации внутренних систем холодного и горячего водоснабжения, а также систем канализации зданий различного назначения.\n', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Проект', 'Знания: нормативная база в области проектирования зданий, элементы и схемы систем водоснабжения и водоотведения зданий, методы проектирования систем.\nУмения: использовать нормативные документы в своей деятельности; проводить выбор и расчетное обоснование решения при проектировании внутренних систем водоснабжения и водоотведения.\nНавыки: проектирования систем внутреннего водоснабжения и водоотведения.\n', 'Макотрина Людмила Викторовна', 4, 1, 190, NULL, NULL, NULL, NULL, NULL, NULL),
(489, NULL, NULL, 'Глубокая очистка сточных вод промышленного предприятия', 15, 'Минимизировать антропогенную нагрузку на поверхностные водные источники.', 'Предлагает и обосновывает варианты наилучших доступных технологий и очистных сооружений для обеспечения инженерно-технической и экологической безопасности на промышленном предприятии и в регионе расположения предприятия.', 2, '2023-02-06', '2023-06-25', '', 'Тематика сторонних организаций  - Сибирского проектного института. Г. Иркутск. ', NULL, 'Проект приводит алгоритм и технологию углублённой очистки промышленных стоков ', 'Знания:  инновационные направления в очистке сточных вод и особенности организации производств такого уровня. \nУмения:  подбирать новейшие методы, сооружения и технологии очистки сточных вод \nНавыки:  по основами подготовки документации для создания системы менеджмента качества производственного подразделения очистки сточных вод\n', 'Кульков Виктор Николаевич', 4, 1, 191, NULL, NULL, NULL, NULL, NULL, NULL),
(490, NULL, NULL, 'Разработка проектов межевания для Байкальского района Иркутской области.', 15, 'Актуализировать данные о земле и исправить выявленные ошибки для дальнейшего планирования территорий.', 'Проект предусматривает сбор первоначальных данных, анализ и актуализация материала о земельных ресурсах территорий.', 3, '2023-02-06', '2023-06-25', '', 'По заказу Администрации Иркутской области', NULL, 'Актуализированные проекты межевания кадастровых кварталов территорий.', 'Знания: принципов и метод работы с проектами межевания.\nУмения: формировать проекты межевания.\nНавыки: осуществлять сбор и обработку исходной информации для формирования проектов межевания, применять знания нормативно-правовой базы при работе с территориями. Навыки работы с ПО «ГИС Панорама».\n', 'Бунеева Евгения Юрьевна, Безруких Ольга Андреевна', 4, 1, 192, NULL, NULL, NULL, NULL, NULL, NULL),
(491, NULL, NULL, 'Разработка проектов межевания для Слюдянского Иркутской области.', 15, 'Актуализировать данные о земле и исправить выявленные ошибки для дальнейшего планирования территорий.', 'Проект предусматривает сбор первоначальных данных, анализ и актуализация материала о земельных ресурсах территорий.', 1, '2023-02-06', '2023-06-25', '', 'По заказу Администрации Иркутской области', NULL, 'Актуализированные проекты межевания кадастровых кварталов территорий.', 'Знания: принципов и метод работы с проектами межевания.\nУмения: формировать проекты межевания.\nНавыки: осуществлять сбор и обработку исходной информации для формирования проектов межевания, применять знания нормативно-правовой базы при работе с территориями. Навыки работы с ПО «ГИС Панорама».\n', 'Бунеева Евгения Юрьевна, Безруких Ольга Андреевна', 4, 1, 193, NULL, NULL, NULL, NULL, NULL, NULL),
(492, NULL, NULL, 'Оценка инвестиционной привлекательности проекта сетевых домостроительных комбинатов', 15, 'Оценка инвестиционной привлекательности проекта сетевого ДСК с целью повышения уровня заводской готовности домокомплектов и модулей для снижения себестоимости и сроков строительства ', 'Проект направлен на создание на территории РФ сети мобильных гибких роботизированных производств строительных конструкций и компонентов для реализации градостроительных и инфраструктурных решений любой сложности на всей территории Российской Федерации. Переход на новый технологический уровень в области индустриального домостроения позволит улучшить качественные параметры архитектурно-планировочных и технических решений, снизить стоимость продукции и повысить производительность труда с использованием отечественного и мирового опыта', 3, '2023-02-06', '2023-06-25', '', 'ООО \"ПОБЕДА\"', NULL, 'Инвестиционный проект «Сетевые домостроительные комбинаты»', 'Знания: \n состава, структуры и назначения бизне-сплана инвестиционного проекта;\n методов оценки эффективности вложений в реальные и финансовые инвестиции;\n новых форм финансирования инвестиционных проектов в РФ;\n индустриальных методов возведения зданий и сооружений.\nУмения: \n проводить необходимые финансовые вычисления по оценке доходности инвестиций, рыночной стоимости финансовых инструментов;\n работать с законодательными и другими нормативными документами, статистическими материалами, технической и экономической литературой;\n применять методы математического анализа и моделирования, теоретического и экспериментального исследования для решения экономических задач.\nНавыки: \n методологии и методики экономического исследования; методами и приемами анализа экономических явлений и процессов;\n расчета основных критериев оценки инвестиционных проектов;\n оценки риска инвестиционной деятельности;\n составления бизнес-планов инвестиционных проектов.\n', 'Безруких Ольга Андреевна', 4, 1, 194, NULL, NULL, NULL, NULL, NULL, NULL),
(493, NULL, NULL, 'Новые форматы недвижимости: направления для стартапов ', 15, 'Развитие теоретических и методических подходов к формированию и развитию рынка новых форматов недвижимости. ', 'Определение ключевых особенностей организации  рынка институционного арендного жилья и механизмы его функционирования, а также выявить особенности субъектов строительной отрасли заинтересованных в строительстве арендного жилья, в результате чего появляется возможность усовершенствовать организационно-экономический механизм развития и функционирования рынка арендного жилья.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Модель развития рынка арендного жилья с учетом современных организационных форм (на примере г. Иркутск)', 'Знания: \n новых форматов недвижимости;\n методов финансирования строительства арендного жилья.\nУмения: \n проводить оценку и выявлять проблемные области жилищного строительства с использованием различных методик;\nНавыки: \n определения капиталоемкости, эффективности вложений, срока окупаемости, механизмов финансирования, возможных рисков.\n проектирования модели развития рынка арендного жилья с учетом современных организационных форм.\n', 'Безруких Ольга Андреевна', 4, 1, 195, NULL, NULL, NULL, NULL, NULL, NULL),
(494, NULL, NULL, 'Управление городскими агломерациями в рамках стандарта  комплексного развития территорий ', 15, 'Разработка методических основ и прикладного инструментария по совершенствованию механизма управления реализацией индустриальных проектов малоэтажного жилищного строительства в системе городской агломерации с учетом стандарта комплексного развития территорий', 'Проект направлен на решение проблемы эффективности использования земель посредством реализации проектов комплексного развития территорий в разрезе городской агломерации. А также в процессе проведения исследований изучаются: \n- существующие проблемы комплексного развития территорий на примере г. Иркутск;\n- подходы к формированию и реализации проектов комплексного развития территорий;\n- формирование мероприятий по улучшению реализации комплексного развития пригородных территорий Иркутска за счет применения наиболее энергоэффективной, экологичной и доступной технологии малоэтажного домостроения. \n', 3, '2023-02-06', '2023-06-25', '', 'Администрация города Иркутска', NULL, 'Разработка  методических основ, механизмов, моделей и практических рекомендаций по эффективному воспроизводству объектов малоэтажного строительства направленного на стимулирование рынка малоэтажного жилья в агломерационной системе', 'Знания: процесса развития агломераций муниципальных образований региона; технологий малоэтажного строительства.\nУмения: Определить внешние региональные условия и внутренние закономерности функционально-пространственного развития городских агломераций.\nНавыки: осуществлять сбор и обработку исходной информации для определения приоритетной технологии малоэтажного строительства отвечающую требованиям Национальных проектов, Стратегий РФ и стандартам КРТ. \n', 'Безруких Ольга Андреевна', 4, 1, 196, NULL, NULL, NULL, NULL, NULL, NULL),
(495, NULL, NULL, 'Мультиформатные загородные поселки, как тренд загородной недвижимости ', 15, 'Разработка организационно-технологического программы развития мультиформатных загородных поселков', 'Проект направлен на разработку мероприятий для реализации целевых показателей паспорта федерального проекта «Жилье» до 2024 г., а также стимулирует развитие строительной отрасли региона, обеспечивая население комфортным и доступным жильем за счет реализации проектов мультиформатных загородных поселков', 3, '2023-02-06', '2023-06-25', '', 'ООО \"ПОБЕДА\"', NULL, 'Программа развития (дорожная карта) мультиформатных загородных поселков в регионе', 'Знания: \n технологических процессов строительного производства мультиформатной застройки с учётом требований производственной и экологической безопасности;\n видов комплексной мультиформатной загородной застройки по 214 ФЗ;\n видов инфраструктурных вложений при комплексной загородной застройке.\nУмения: организовать, планировать и управлять строительным производством на всех этапах жизненного цикла при реализации инвестиционно-строительных проектов мультиформатной застройки;\nНавыки: \n формирование дорожной карты по внедрению мультиформатной застройки;\n расчёта экономической эффективности.\n', 'Безруких Ольга Андреевна', 4, 1, 197, NULL, NULL, NULL, NULL, NULL, NULL),
(496, NULL, NULL, 'Разработка мероприятий по совершенствованию функционирования предприятия на основе анализа финансово-хозяйственной деятельности', 15, 'Разработка рекомендаций по совершенствованию финансово-хозяйственной деятельности и оценка эффективности предлагаемых мероприятий по совершенствованию финансово-хозяйственной деятельности', 'В современных условиях развития экономики страны наиболее важную роль играют предприятия различных отраслей, которые поддерживают экономическую стабильность всего государства. При том, важную роль в данной системе занимают предприятия строительной отрасли. После перехода России в условия рыночной экономики появилось множество предприятий, которые не зависят от государственного регулирования и должны уметь самостоятельно проводить анализ своей деятельности, в первую очередь финансово-хозяйственной. Анализ финансово-хозяйственной деятельности является основным инструментом, позволяющим оценить финансово-хозяйственное положение предприятия. Наличие достаточного количества финансово-хозяйственных ресурсов и рациональное их использование позволяют предприятию функционировать и успешно осуществлять свою деятельность. \nПо результатам анализа деятельности в динамике становится понятно, по каким направлениям необходимо проводить изменения. Также анализ позволяет определить слабые и сильные стороны предприятия. Совершенствование финансово-хозяйственной деятельности предприятия подразумевает под собой поиск новых путей развития предприятия посредством увеличения финансово-хозяйственных резервов и оптимизацию их использования. Предшествующими этапами совершенствования деятельности являются: анализ текущего состояния предприятия, разработка мероприятий по совершенствованию, оценка рисков внедрения мероприятий и прогноз развития предприятия. Разработка мероприятий по совершенствованию функционирования предприятия на основе анализа финансово-хозяйственной деятельности является неотъемлемой частью нормального функционирования предприятия, в условиях изменяющейся внутренней и внешней среды\n', 2, '2023-02-06', '2023-06-25', '', 'АО «Иркутскгипродорнии»', NULL, 'Комплексная оценка финансово-хозяйственного состояния в динамике, позволяющая осуществлять анализ и совершенствование деятельности предприятия с целью поиска новых путей развития предприятия посредством увеличения финансово-хозяйственных резервов и оптимизации их использования', 'Проведение оценки эффективности хозяйственной деятельности, на основании которой разрабатываются мероприятия по совершенствованию финансово-хозяйственной деятельности и дается оценка эффективности предлагаемых мероприятий', 'Кудрявцева Вера Александровна', 4, 1, 199, NULL, NULL, NULL, NULL, NULL, NULL),
(497, NULL, NULL, 'Разработка сметной документации на капитальный ремонт зданий и сооружений', 15, 'Разработать сметную документацию на капитальный ремонт зданий и сооружений с применением современной сметно-нормативной базы на основе данных обследования текущего технического состояния объекта', 'В настоящее время значительное внимание уделяется капитальному ремонту зданий и сооружений, который производится при необходимости восстановления характеристик объекта до текущих нормативов, с восстановлением и (или) заменой любых частей объекта. Грамотно проведенная оценка технического состояния зданий и сооружений позволяет установить необходимость капитального ремонта, виды и объемы работ, проводимых при капитальном ремонте. Для качественного выполнения работ необходимо определить требуемый объем финансирования, который определяется путем разработки сметной документации и подтверждается сметной стоимостью, которая определяется сметой на реконструкцию, капитальный ремонт объекта капитального строительства, на работы по сохранению объектов культурного наследия, разрабатываемой в составе проектной документации. Особенно остро вопрос качественного определения стоимости строительно-монтажных работ стоит в период реформирования системы сметного ценообразования в целом. Оптимизация затрат на техническое обслуживание зданий во многом обусловлена рациональным планированием системы текущих и капитальных ремонтов. Качественное проведение капитального ремонта продлевает срок службы здания в несколько раз, а его своевременность снижает затраты непосредственно на ремонтные работы и последующие эксплуатационные затраты по зданию. Все это позволяет повысить надежность, безопасность и комфортность зданий и сооружений', 2, '2023-02-06', '2023-06-25', '', 'АО «Иркутскгипродорнии»', NULL, 'Оценка технического состояния и разработка сметной документации на капитальный ремонт объектов', 'Концептуальная (содержательная) проработка вопросов определения стоимости строительно-монтажных работ по капитальному ремонту на основе данных о техническом состоянии зданий и сооружений', 'Кудрявцева Вера Александровна', 4, 1, 200, NULL, NULL, NULL, NULL, NULL, NULL),
(498, NULL, NULL, 'Разработка мероприятий по совершенствованию функционирования предприятия на основе анализа финансово-хозяйственной деятельности', 15, 'Разработка рекомендаций по совершенствованию финансово-хозяйственной деятельности и оценка эффективности предлагаемых мероприятий по совершенствованию финансово-хозяйственной деятельности', 'В современных условиях развития экономики страны наиболее важную роль играют предприятия различных отраслей, которые поддерживают экономическую стабильность всего государства. При том, важную роль в данной системе занимают предприятия строительной отрасли. После перехода России в условия рыночной экономики появилось множество предприятий, которые не зависят от государственного регулирования и должны уметь самостоятельно проводить анализ своей деятельности, в первую очередь финансово-хозяйственной. Анализ финансово-хозяйственной деятельности является основным инструментом, позволяющим оценить финансово-хозяйственное положение предприятия. Наличие достаточного количества финансово-хозяйственных ресурсов и рациональное их использование позволяют предприятию функционировать и успешно осуществлять свою деятельность. \nПо результатам анализа деятельности в динамике становится понятно, по каким направлениям необходимо проводить изменения. Также анализ позволяет определить слабые и сильные стороны предприятия. Совершенствование финансово-хозяйственной деятельности предприятия подразумевает под собой поиск новых путей развития предприятия посредством увеличения финансово-хозяйственных резервов и оптимизацию их использования. Предшествующими этапами совершенствования деятельности являются: анализ текущего состояния предприятия, разработка мероприятий по совершенствованию, оценка рисков внедрения мероприятий и прогноз развития предприятия. Разработка мероприятий по совершенствованию функционирования предприятия на основе анализа финансово-хозяйственной деятельности является неотъемлемой частью нормального функционирования предприятия, в условиях изменяющейся внутренней и внешней среды\n', 2, '2023-02-06', '2023-06-25', '', 'АО «Иркутскгипродорнии»', NULL, 'Комплексная оценка финансово-хозяйственного состояния в динамике, позволяющая осуществлять анализ и совершенствование деятельности предприятия с целью поиска новых путей развития предприятия посредством увеличения финансово-хозяйственных резервов и оптимизации их использования', 'Проведение оценки эффективности хозяйственной деятельности, на основании которой разрабатываются мероприятия по совершенствованию финансово-хозяйственной деятельности и дается оценка эффективности предлагаемых мероприятий', 'Кудрявцева Вера Александровна', 4, 1, 201, NULL, NULL, NULL, NULL, NULL, NULL),
(499, NULL, NULL, 'Техническая экспертиза объектов недвижимости:\n1. Капитальный ремонт  крупнопанельного жилого дома по адресу: г. Иркутск, мкр. Первомай-ский, 23\n1. Капитальный ремонт крупнопанельного  жилого дома  по адресу: г. Иркутск, мкр. Первомай-ский, 55\n', 15, 'Проведение технической экспертизы и оценка технического состояния объекта недвижимости, разработка комплекса ремонтно-восстановительных мероприятий', 'В процессе эксплуатации объектов недвижимости вследствие различных причин происходят физический износ строительных конструкций, возникновение и накопление повреждений,  снижение и потеря их несущей способности, деформации как отдельных элементов, так и здания в целом. Для разработки мероприятий по восстановлению эксплуатационных качеств конструкций, необходимо проведение их обследования (технической экспертизы) с целью выявления причин преждевременного износа и снижения их несущей способности. По результатам технической экспертизы выполняется оценка технического состояния, условий и возможности дальнейшей эксплуатации, разрабатывается комплекс требуемых ремонтно-восстановительных мероприятий.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Отчет по результатам обследования и оценки технического состояния объекта недвижимости', 'знать:\n требования современ-ных строительных норм и правил;\n методические особенности диагностики  и оценки технического состояния строительных кон-струкций.\n характеристики приме-няемых в регионе типо-вых проектов каменных и крупнопанельных зда-ний;\n основные конструктив-ные решения несущих и ограждающих конструк-ций;\nуметь:\n выполнять диагностику технического состояния строительных конструк-ций;\n составлять отчеты по ре-зультатам исследований.\n выполнять анализ (экс-пертизу) проектного ре-шения.\nвладеть:\n методами   и средствами дефектоскопии   строи-тельных конструкций, контроля физико-механических свойств.\n', 'Журавлев Евгений Геннадьевич', 4, 1, 202, NULL, NULL, NULL, NULL, NULL, NULL),
(500, NULL, NULL, 'Повышение безопасности высотных объектов строительства за счет создания эффективных методов эвакуации и совершенствования систем вентиляции', 15, 'Для стратегического развития отрасли Строительства и Жилищно-коммунального хозяйства необходимо изыскать возможности при требуемом уровне застройки наилучшим образом обеспечить устойчивый рост комфорта и безопасности среды жизнедеятельности (благоустройство, дороги, расположение объектов Строительства и т.д.). Исследование таких возможностей и выработка рекомендаций является целью данного проекта.', 'Согласно Стратегии развития строительной отрасли и жилищно-коммунального хозяйства Российской Федерации до 2035 года создание безопасной среды является важной задачей. Достижение соответствующего уровня безопасности может  достигаться засчет: разработки оптимальных путей эвакуации, своевременной эвакуации жителей с верхних этажей, совершенствовании систем вентиляции (возможность исключить перемещение воздуха из одного помещения в другое) при возникновении чрезвычайных ситуаций. Рассмотреть все представленные аспекты, проанализировать их влияние на среду жизнедеятельности человека, сделать соответствующие выводы и разработать рекомендации – основа представленного проекта.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Разработка соответствующих рекомендаций.', 'Знания: нормативно-законодательные аспекты отрасли Строительства, методы планирования, оптимизации, принятия решений\nУмения: анализа нормативно-законодательной литературы в сфере Строительства, разработки и принятия решений\nНавыки: исследования, анализа, планирования, оптимизации\n', 'Гребнева Оксана Александровна', 4, 1, 203, NULL, NULL, NULL, NULL, NULL, NULL),
(501, NULL, NULL, 'Исследование задач развития комфортной и безопасной среды при осуществлении требуемых объемов застройки', 15, 'Для стратегического развития отрасли Строительства и Жилищно-коммунального хозяйства необходимо изыскать возможности при требуемом уровне застройки наилучшим образом обеспечить устойчивый рост комфорта и безопасности среды жизнедеятельности (благоустройство, дороги, расположение объектов Строительства и т.д.). Исследование таких возможностей и выработка рекомендаций является целью данного проекта.', 'Согласно Стратегии развития строительной отрасли и жилищно-коммунального хозяйства Российской Федерации до 2035 года создание безопасной и комфортной среды жизнедеятельности человека является важной задачей при обеспечении соответствующего уровня развития Строительства. Достижение соответствующего уровня комфортности и безопасности может  достигаться засчет: разумной подготовки территорий Строительства, рационального размещения объектов общественного питания, парковок, парковых зон и т.д., создания удобной и безопасной дорожной инфраструктуры и т.д. Рассмотреть все представленные аспекты, проанализировать их влияние на среду жизнедеятельности человека, сделать соответствующие выводы и разработать рекомендации – основа представленного проекта.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Рекомендации по увеличению уровня комфортности при требуемом уровне застройки.', 'Знания: нормативно-законодательные аспекты отрасли Строительства, методы планирования, оптимизации, принятия решений\nУмения: анализа нормативно-законодательной литературы в сфере Строительства, разработки и принятия решений при решении задач Строительства с учетом всех ограничений и требований\nНавыки: исследования, анализа, планирования\n', 'Гребнева Оксана Александровна', 4, 1, 204, NULL, NULL, NULL, NULL, NULL, NULL),
(502, NULL, NULL, 'Информационное моделирование инженерных систем и теплового узла объектов недвижимости с применения BIM-технологий при проведении капитального ремонта на примере нежилого здания по адресу Иркутская область, г. Иркутск, Игошина, 6-а.', 15, 'Создание 3D-модели (виртуальной модели) инженерных систем здания: систем отопления, горячего и холодного водоснабжения, водоотведения, которая в дальнейшем позволяла бы получить визуализацию расположения систем внутри объекта капитального ремонта, информацию по элементам, оборудованию и их характеристикам, а также при необходимости вносить изменения и коррективы в процессе его жизненного цикла.', 'В результате выполнения проекта с использованием BIM-технологий на основе существующей проектной документации и результатов обследования будет выполнена визуализация систем отопления, горячего и холодного водоснабжения, водоотведения объекта капитального ремонта, расположенного по адресу Иркутская область, г. Иркутск, ул. Игошина, 6-а. Созданная информационная модель позволит осуществить планирование и координацию работ по замене элементов и оборудования инженерных систем, обеспечит сопровождение, расчет объемов,  составление смет, сроков, BIM-координацию различных этапов выполнения работ, контроль и обеспечение качества, выявление конфликтов, составление документации и т. д.', 3, '2023-02-06', '2023-06-25', '', 'Фонд капитального ремонта ', NULL, '3D-модель инженерных систем нежилого здания, расположенного по адресу Иркутская область, г. Иркутск, Игошина, 6-а.', 'Знания: по методам информационного моделирования и проектирования жизненного цикла инженерных систем и сооружений объектов недвижимости. \nУмения: владение системами 3d-моделирования и создание 3d-моделей инженерных систем объектов недвижимости.\nНавыки: проектирования и моделирования.\n', 'Гребнева Оксана Александровна', 4, 1, 205, NULL, NULL, NULL, NULL, NULL, NULL),
(503, NULL, NULL, 'Информационное моделирование объектов недвижимости с применения BIM-технологий при проведении капитального ремонта на примере нежилого здания по адресу Иркутская область, г. Иркутск, Игошина, 6-а.', 15, 'Создание 3D-модели (виртуальной модели), которая в дальнейшем позволяла бы получить графический вид объекта, информацию по дизайну, размерам, материалам и другим характеристикам объекта капитального ремонта, а также при необходимости вносить изменения и коррективы в процессе его жизненного цикла.', 'В результате выполнения проекта с использованием BIM-технологий на основе существующей проектной документации и результатов обследования конструкций здания будет выполнена визуализация объекта капитального ремонта, расположенного по адресу Иркутская область, г. Иркутск, ул. Игошина, 6-а (возможно с разработкой дизайн-проекта). Созданная информационная модель позволит осуществить планирование и координацию работ, обеспечит сопровождение, расчет объемов,  составление смет, сроков, BIM-координацию различных этапов выполнения работ, контроль и обеспечение качества, выявление конфликтов, составление документации и т. д.', 3, '2023-02-06', '2023-06-25', '', 'Фонд капитального ремонта ', NULL, '3D-модель нежилого здания, расположенного по адресу Иркутская область, г. Иркутск, Игошина, 6-а.', 'Знания: по методам информационного моделирования и проектирования жизненного цикла зданий. \nУмения: владение системами 3d-моделирования и создание 3d-моделей объектов недвижимости.\nНавыки: проектирования и моделирования.\n', 'Гребнева Оксана Александровна', 4, 1, 206, NULL, NULL, NULL, NULL, NULL, NULL),
(504, NULL, NULL, 'Создание художественного произведения/творческой работы для участия в выставочных проектах Всероссийской творческой организации «Союз художников России»', 15, 'Освоение методики последовательного ведения работы над созданием проекта. Создание художественно-выразительного произведения для последующего участия в выставочных и конкурсных проектах, организованных Всероссийской творческой организацией «Союз художников России»/Молодежным объединением ИРО ВТОО «Союз художников России»', 'Разработка концепции творческого проекта (художественной работы) под руководством преподавателя, с учетом данных обучающегося. Выполнение эскизов на тему, предложенную преподавателем, либо самим обучающимся, актуальную для тематики текущих выставок  Всероссийской творческой организации «Союз художников России»/Молодежного объединения ИРО ВТОО «Союз художников России». Проработка концепции графического/цветового решения, выбор техники исполнения произведения. Выполнение работы в материале.', 2, '2023-02-06', '2023-06-25', '', 'Всероссийская творческая организация «Союз художников России», Молодежное объединение ИРО ВТОО «Союз художников России»', NULL, 'Творческий вывод - художественное произведение: картина/ графический лист/ проект digital art  (печать)/ работа в любой из техник монументально-декоративного искусства (мозаика, витраж, панно из ткани, гобелен и т.д.)', 'Знания:\nСпецифика проектной работы над созданием художественного произведения;\nОсобенности создания эскиза произведения, как составной части проекта; \nОсновы композиционного, графического, цветового проектирования;\nОсновы академического рисунка и живописи.\nУмения:\nОрганизация поэтапной работы над созданием художественного произведения;\nРабота с различными художественными материалами;\nИдея и реализация творческого замысла;\nНавыки: \nВладение  техниками и материалами изобразительного искусства;\nВладение методами изобразительного языка\n', 'Довнич Наталья Анатольевна', 4, 1, 207, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(505, NULL, NULL, 'Визуальное решение театральных и культурно массовых мероприятий (организация среды и систем айдентики)', 15, 'Создание проектов сценографического решения мероприятий разного функционального назначения', 'Цель проекта: формирование компетенции в сценографии как объекта дизайн проектирования; исследование традиционного и современных подходов к визуальному оформлению культурно-массовых мероприятий; изучение способов воплощения художественного замысла средствами объемно пространственного моделирования.', 3, '2023-02-06', '2023-06-25', '', 'Театры, коммерческие структуры г. Иркутска', NULL, 'Проекты организации среды и систем айдентики театральных и культурно массовых мероприятий разного функционального назначения.', 'Знать: типологию композиционных средств и их взаимодействие; основные приемы сценарного-проектирования среды и систем айдентики мероприятий разного функционального назначения\nУметь: решать основные типы проектных задач создания театральных и культурно-массовых мероприятий; учитывать при разработке художественного замысла особенности материалов и их формообразующих свойств;\nВладеть приемами объемного и графического моделирования формы объекта, и соответствующей организацией проектного материала для передачи творческого художественного замысла;\nкомпьютерным обеспечением дизайн-проектирования;\nвыполнением проекта в материале.\n', 'Шолохов Андрей Викторович', 4, 1, 208, NULL, NULL, NULL, NULL, NULL, NULL),
(506, NULL, NULL, 'Проектирование мебели и оборудования как системы формирования комфортной среды', 15, 'Создание проектов мебели и оборудования для сред разного функционального назначения: формообразование, конструирование и формулирование концепций рекламного продвижения', 'В современной ситуации становиться актуальным наличие на рынке функциональной, качественной, не дорогой мебели и оборудования, созданными с использованием современных отечественных материалов на актуальной производственной базе. Результатом данного курса будут проекты мебели и оборудования, на которые возможно получение патентов на промышленные образцы с дальнейшей возможной реализацией в материале, концепции формирования рекламно-информационных систем продвижения продуктов/изделий.', 3, '2023-02-06', '2023-06-25', '', 'Мебельные фирмы г.Иркутска', NULL, 'Проекты мягкой и корпусной мебели и оборудования; концепции продвижения созданных изделий', 'Знать: основные способы дизайн-проектирования, специфику создания дизайна современной мебели и оборудования; базовые технологические процессы в мебельной промышленности\nУметь: разрабатывать обоснованную проектную идею с учетом формообразования и основ конструирования; проектировать системы визуальной информации, идентификации и коммуникации \nВладеть навыками проектирования мебели: конструирования предметов, товаров, промышленных образцов с учетом технологий изготовления; формирования рекламно-информационных комплексов \n', 'Шолохов Андрей Викторович', 4, 1, 209, NULL, NULL, NULL, NULL, NULL, NULL),
(507, NULL, NULL, 'Создание художественного произведения/творческой работы для участия в ежегодной выставке-конкурсе, проходящей в рамках областного фестиваля «Студенческая весна в ИрНИТУ»', 15, 'Освоение методики последовательного ведения работы над созданием проекта. Создание художественно-выразительного произведения для последующего участия в выставке-конкурсе областного фестиваля «Студенческая весна в ИрНИТУ», организованного  Центром  культурно-массовой и воспитательной работы ИРНИТУ (с возможностью дальнейшего участия произведения в других выставках /конкурсах).', 'Разработка концепции творческого проекта (художественной работы) под руководством преподавателя, с учетом данных обучающегося. Выполнение эскизов на тему, предложенную преподавателем, либо самим обучающимся, актуальную для общей тематики выставки. Проработка концепции графического/цветового решения, выбор техники исполнения произведения. Выполнение работы в материале.', 2, '2023-02-06', '2023-06-25', '', 'Центр культурно-массовой и воспитательной работы ИРНИТУ. Дирекция ИАСиД. ', NULL, 'Творческий вывод - художественное произведение: картина/ графический лист/ проект digital art  (печать)/ работа в любой из техник монументально-декоративного искусства (мозаика, витраж, панно из ткани, гобелен и т.д.)', 'Знания:\nСпецифика проектной работы над созданием художественного произведения;\nОсобенности создания эскиза произведения, как составной части проекта; \nОсновы композиционного, графического, цветового проектирования;\nОсновы академического рисунка и живописи.\nУмения:\nОрганизация поэтапной работы над созданием художественного произведения;\nРабота с различными художественными материалами;\nИдея и реализация творческого замысла;\nНавыки: \nВладение  техниками и материалами изобразительного искусства;\nВладение методами изобразительного языка.\n', 'Свердлов Григорий Викторович', 4, 1, 210, NULL, NULL, NULL, NULL, NULL, NULL),
(508, NULL, NULL, 'Создание художественного произведения/творческой работы для участия в ежегодной выставке-конкурсе, проходящей в рамках  Всероссийского фестиваля «Дни русской духовности и культуры «Сияние России».', 15, 'Освоение методики последовательного ведения работы над созданием проекта. Создание художественно-выразительного произведения для последующего участия в выставке-конкурсе, проходящей в рамках Всероссийского фестиваля «Дни русской духовности и культуры «Сияние России» в ИрНИТУ, с возможностью дальнейшего участия произведения в других выставках /конкурсах.', 'Разработка концепции творческого проекта (художественной работы) под руководством преподавателя, с учетом данных обучающегося. Выполнение эскизов на тему, предложенную преподавателем, либо самим обучающимся, актуальную для общей тематики выставки. Проработка концепции графического/цветового решения, выбор техники исполнения произведения. Выполнение работы в материале.', 2, '2023-02-06', '2023-06-25', '', 'Центр культурно-массовой и воспитательной работы ИРНИТУ. Дирекция ИАСиД.', NULL, 'Творческий вывод - художественное произведение: картина/ графический лист/ проект digital art  (печать)/ работа в любой из техник монументально-декоративного искусства (мозаика, витраж, панно из ткани, гобелен и т.д.)', 'Знания:\nСпецифика проектной работы над созданием художественного произведения;\nОсобенности создания эскиза произведения, как составной части проекта; \nОсновы композиционного, графического, цветового проектирования;\nОсновы академического рисунка и живописи.\nУмения:\nОрганизация поэтапной работы над созданием художественного произведения;\nРабота с различными художественными материалами;\nИдея и реализация творческого замысла;\nНавыки: \nВладение  техниками и материалами изобразительного искусства;\nВладение методами изобразительного языка.\n', 'Ижганайтене Анастасия Николаевна', 4, 1, 211, NULL, NULL, NULL, NULL, NULL, NULL),
(509, NULL, NULL, '\"Виртуальный тур по промышленным объектам Иркутской области. Памятники промышленного зодчества»', 15, 'Создание виртуального тура с описанием объектов', 'В связи с возможностью обследования промышленных зданий и сооружений индустриального освоения Восточной Сибири, в том числе, заброшенных и исчезающих, существует необходимость провести 3d съемку объектов, собрать историческую справку и создать 3d тур. В проекте должно быть подробное описание, озвучивание и возможность рассмотрения объектов в деталях. Объект предназначен для сохранения информации об объектах, изучения конструкций и архитектуры зданий, истории объекта.', 3, '2023-02-06', '2023-06-25', '', 'Ассоциация индустриального туризма, Благотворительный фонд Владимира Потанина\n', NULL, 'Виртуальный тур, имеющий историческую значимость ', 'Знания: в области истории архитектуры и конструкций промышленных объектов Восточной Сибири на территории Иркутской области\nУмения: создавать 3d съемки, делать описание конструкций и создавать виртуальный тур.\nНавыки: работа с ГЕО программным обеспечением\n', 'Черниговская Виктория Вячеславовна', 4, 1, 212, NULL, NULL, NULL, NULL, NULL, NULL),
(510, NULL, NULL, 'Оценка эффективности инвестиционного проекта', 15, 'Постановка задач и их решение, необходимые содержательные и математические обоснования, изучение, разъяснение типовых ошибок, встречающиеся в практике расчёта. Изучение методов приспособленных как к стационарной рыночной, так и к современной нестационарной российской экономике. ', '1.Теоретические основы оценки инвестиционных проектов. 1.1. Что такое инвестиционный проект и зачем его оценивать. 1.2. Принципы и схема оценки инвестиционных проектов. 1.3. Система цен и налогов. 1.4. Измерение, планирование и проектирование затрат и результатов. 1.5. Оценка эффективности проекта в целом. 1.6. Оценка эффективности участия в проекте. 1.7. Неопределённость и риск: общие понятия и приближенные методы учета. 1.8. Расчёты ожидаемой эффективности проекта. 1.9. Оптимизация и рациональный отбор проектов. 2. Методические проблемы практической оценки инвестиционных проектов. 2.1. Оценка эффективности проектов при специфических условиях их реализации. 3. Примеры оценки инвестиционных проектов. 3.1. Предварительная аналитическая оценка проекта. 3.2. Пример полного расчета показателей эффективности инвестиционного проекта', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Участие в конференции и написание статей по материалам  исследования.', 'Знать: основные понятия, общие положения, особенности расчётов.\nУметь: решать сложные методические и практические проблемы инвестиционных проектов.\nВладеть навыками последовательного построения расчётов.\n', 'Рябченкова Антонина Васильевна', 4, 1, 213, NULL, NULL, NULL, NULL, NULL, NULL),
(511, NULL, NULL, 'Контейнерное озеленение для зимнего города', 15, 'Разработка методических рекомендаций по агротехнике и ассортименту растений для контейнерного озеленения (пристановочной культуры) зимнего города на примере Иркутска, проектирование архитектурно-технического оснащения для контейнерного растениеводства в зимнем городе.', 'С развитием технологий и прогрессом городских инженерных систем очень сложно вписать в озеленение исторических и деловых центров и жилых районов города растения с крупной корневой системой. Для зимних городов ситуация с подбором растений осложняется коротким вегетационным периодом и низкой суммой активных температур. Для формирования озеленения на территориях с плотной застройкой и расширения ассортимента растений перспективно контейнерное озеленение. Контейнеры для пристановочной культуры подразумевают возможность автономного выращивания (автополив, дренаж, защита от перегрева, аккумуляция тепла, возможность притенения), необходимы архитектурные элементы зданий для размещения контейнеров с растениями, малые архитектурные формы и т.д.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Методические рекомендации по агротехнике и ассортименту растений для контейнерного озеленения зимнего города на примере Иркутска, проект архитектурно-технического оснащения для контейнерного растениеводства в зимнем городе.', 'Знать: ассортимент растений для озеленения зимнего города, требования безопасного размещения контейнеров.\nУметь: проектировать элементы архитектурно-технического оснащения контейнерного озеленения.\nВладеть: навыками проектирования в  Autodesk 3ds Max или программах-аналогах\n', 'Баяндина Елена Викторовна, Черниговская Виктория Вячеславовна', 4, 1, 214, NULL, NULL, NULL, NULL, NULL, NULL),
(512, NULL, NULL, 'Цифровой демонстрационно-исследовательский макет города с элементами дополненной реальности', 15, 'Создание цифрового демонстрационно-исследовательского макета города с элементами дополненной реальности (далее - Проект), направленного на решение самых актуальных проблем и задач городского развития за счет возможности (наглядного) поведения проектных и исследовательских работ целого ряда специальностей ИРНИТУ задействованных в городском планировании.  ', 'На данный момент ИРНИТУ не достаточно участвует и тем более влияет на принятие важных решений городского развития в качестве одного из ключевых федеральных центров Знаний и исследований.\nПроект направлен на решение следующих проблем:\nВ городе не создавался Макет для выполнения широко спектра городских задач для проектной и исследовательской деятельности, начиная от стратегического территориально планирования, заканчивая размещение рекламы.\nПо-сути, создание такого рода Макета позиционируется как базовая платформа для выполнения проектных и исследовательских работ различных специальностей ИРНИТУ, связанным с анализом функционирования существующей ситуации (систем), вопросами планирования объектов городской инфраструктуры и мн. др. Кроме того, макет должен выполнять демонстративные функции, поэтому должен выполняться из качественных материалов (пластик ПВХ и др.), по специальной технологии будет осуществляться технология дополненной реальности, кроме того параллельно будет выполняться цифровизация городской территории, с последующей возможностью 3D печати любого фрагмента Макета.\nУчитывая различный спектр задач и функции Макета, ИРНИТУ как современный, исследовательский и инновационный ВУЗ может быть в постоянной повестке городского развития. \nВот лишь некоторые проблемы, которые могут быть решены в проектной, исследовательской деятельности:\n- стратегическое, территориальное планирования;\n- документация по планировке территории;\n- градостроительное зонирование;\n- системы коммунального, транспортного и социального планирования;\n- сохранение и развитие объектов культурного наследия;\n- развитие систем рекреационного назначения;\n-  размещение рекламы;\n- размещение нестационарных торговых объектов и др.\nКаждый из данных направлений представляет отдельный проект, спектр которых не ограничивается данным перечнем. \nДемонстрационные функции Макета, также выгодны для презентации деятельности ВУЗа, в частности: Возможность выгодно презентовать город на высоком, качественном уровне \n представителям федеральных органов власти, министерствам и ведомствам, представителям бизнеса, зарубежным гостям и конечно жителям и обычным гостям города.\nВ частности, на данной платформе, можно очень наглядно проводить публичные и общественные слушания в рамках реальной подготовки одно из видов градостроительной документации.\n', 2, '2023-02-06', '2023-06-25', '', 'Администрация города Иркутска', NULL, 'Построение макета для отражения современного состояния, построение базовой основы для последующего проектирования и исследовании', 'Знания: Методы и способы создания макета\nУмения: самостоятельно выполнять задачи по макетированию в цифровом, а также использую специальные материалы такие как пеноплекс, возможности 3D - печати\nНавыки: макетного проектирования с использованием традиционных и передовых цифровых технологий.\n', 'Александров Сергей Анатольевич', 4, 1, 215, NULL, NULL, NULL, NULL, NULL, NULL),
(513, NULL, NULL, 'Транспортное планирование исторического центра города Иркутска ', 15, 'Сбор, анализ и обобщение данных о пешеходно-транспортных потоках, характере функционального использования объектов и территории, выполнение предпроектных исследований по классификации улично-дорожной сети исторического центра, необходимых для совершенствования действующих нормативных документов и подготовки проектной документации.', 'Действующие нормативные документы, разработанные на федеральном уровне, классифицирует улично-дорожную сеть улиц и дорог в населенных пунктах. Действующее законодательство также позволяет уточнять классификацию данных улиц и дорог с учетом местных особенностей. Прежде всего, на основе вышеуказанных документов подготавливается градостроительная документация городских и сельских поселений, например, подготовка генеральных планов и проектов планировки. На основе градостроительных документов подготавливается проектно-сметная документация улиц и дорог, а также проекты благоустройства общественных пространств. \nНа данный момент, (на федеральном уровне) подготавливают соответствующие стандарты в отношении городов федерального значения таких как Москва, а также подготавливаются стандарты благоустройства, которую пытаются адаптировать как основополагающие на местном уровнях. Однако, практика показывает, что данные нормативы не могут учитывать в полной мере:\n- природно-климатические;\n- историко-культурные;\n- функционально-планировочные и иные особенности конкретных населенных пунктов и территории.\nПроект содержит критический анализ нормативов транспортного планирования различных уровней регулирования, данные о местных особенностях использования исторического центра города Иркутска, а также данные о наблюдениях различных участков улично-дорожной сети, характере их использования, а также предложения по совершенствованию нормативов градостроительного проектирования.\nМестные нормативы градостроительного проектирования позволят проектировать улицы и дороги более дифференцировано, учитывать функционально-планировочные и иные особенности города делая их более безопасными и комфортными для жизни.\n', 2, '2023-02-06', '2023-06-25', '', 'Администрация города Иркутска, Публичное акционерное общество «Сбербанк России»\n', NULL, '1. Подготовка предложений по внесению изменений в:\n- Местные нормативы градостроительного проектирования города Иркутска;\n- Региональные нормативы градостроительного проектирования;\n2. Подготовка предпроектных исследований по развитию и классификации улично-дорожной сети на основе которых могут быть внесены изменения в:\n- проект планировки центральной исторической части города Иркутска;\n3. Подготовка предпроектных исследований по развитию и классификации улично-дорожной сети на основе которых могут быть разработаны;\n- новые стандарты благоустройства улиц и дорог города Иркутска, в части исторического центра;\n- проекты благоустройства общественных пространств;\n- проекты ремонта или реконструкции центральных исторических улиц;\n- схемы размещения нестационарных торговых объектов, расположенных на территории общего пользования;\n- схемы развития пешеходной и велосипедной инфраструктуры исторического центра;\n- схемы развития платной парковочной политики;\n- схемы озеленения исторического центра;\n- схемы размещения рекламных конструкции;\n- схемы размещения объектов информации и навигации.\n\n*- Ожидаемый продуктовый результат в рамках работы учебного года, касается пункта 1, указанный в данном разделе. Пункты 2 и 3 касаются потенциала развития данного проекта.\n', 'Знания: Норм и особенностей регулирования объектов транспортной инфраструктуры на федеральном, региональном и местном уровнях в нормативах градостроительного проектирования\nУмения: анализировать существующее состояние объектов транспортной инфраструктуры с точки зрения безопасности, комфорта использования и способности предлагать новые концептуальные решения\nНавыки: критического мышления, способность выявлять сильные и слабые сторон объекта рассмотрения необходимые для формулирования запроса на новые знания и новые нормативы, в частности\n', 'Александров Сергей Анатольевич', 4, 1, 216, NULL, NULL, NULL, NULL, NULL, NULL),
(514, NULL, NULL, '\"Сибирский тракт. Иркутская губерния».', 15, 'Проведение анализа территорий поселений Иркутской области, исторически находившихся на пути Почтамтского тракта. Картирование территории. Создание информационной базы для дальнейшей реализации проекта', 'В процессе реализации проекта - восстановления верстовых столбов Почтамтского тракта в Иркутской области, возникают задачи по сбору информации исторических данных поселений, градостроительному анализу территории, а так же современной ситуации по культуре и быту населения. Для этого необходимо проведение научного исследования, итогом которого, станет информационная база по поселениям, картирование территорий', 3, '2023-02-06', '2023-06-25', '', 'ВСОРГО, «Фонд Тимченко», Культура гранты России\n', NULL, 'Информационная база. Картирование территорий.', 'Знания: основные способы выполнения градостроительного анализа территорий\nУмения: систематизировать и обобщать информацию по территориям исторических поселений\nНавыки: работы с архивами, электронными ресурсами, а так же работа в команде и с потенциальными потребителями продукта\n', 'Пуляевская Евгения Владимировна', 4, 1, 217, NULL, NULL, NULL, NULL, NULL, NULL),
(515, NULL, NULL, 'Реновация архитектурно-градостроительной среды выхода ул. Нагорной к набережной р. Ангары\nв п. Никола\n', 15, 'Создание комплексного проекта архитектурно-градостроительной организации и благоустройства регионального рекреационного и туристического объекта « Байкал-Никола»', ' Проектом необходимо предусмотреть:\n- градостроительное зонирование реконструируемой территории; функциональное и технико-экономическое обоснование предлагаемых решений\n- транспортно-пешеходную организацию движения, парковки и благоустройство общественных пространств: внешнее (дороги, набережная с общей прибрежной зоной  спорта и отдыха) и внутриквартальное благоустройство\n- архитектурные решения планировки и застройки (гостинично - оздоровительный  комплекс) на участке по адресу: ул.Нагорная, 2;\n- стилевые и колористические решения по объединению разрозненных существующих  объемно-архитектурных элементов застройки и спортивного корта и новых   проектируемых зданий и общественных зон в целостный средовой градостроительный  комплекс;\n Проектный коллектив: студенты старших курсов специальностей Гр, Ар, ДАС, ЭУН с  реализацией работы в:\n - учебная задача: специальный курсовой и дипломные проекты, разрабатываемые в  творческом коллективе специалистов (мастерской);\n- участие в ежегодных творческих областных и межрегиональных конкурсах, Зимнем ГУ -  представление ИрНИТУ на общественных площадках и в социальных программах/сетях;\n публикации в межвузовских и профессиональных специализированных изданиях, на ТВ \n- практический результат: инициативные эскизные проработки (1 этап) с последующим  вхождением в областную программу благоустройства архитектурной среды Прибайкалья  и платной (гранты, участие в госпрограммах) разработкой проектной и рабочей  документации отдельных элементов среды и/или комплекса в целом  (заинтересованные стороны: собственники прилегающих усадебных участков и  туристических объектов; администрация поселка, МО и Иркутской области);\n Время и график выполнения работы - учебный год:\n Сентябрь-октябрь – комплектация коллектива, сбор исходных данных, социологические  исследования, форэскизы, предварительная работа с потенциальными заказчиками и \n интересантами, прессой, административными и общественными структурами;  Ноябрь-декабрь – разработка концептуальных решений по площадке и  эскизных решений по различным фрагментам среды и разделам проекта; консультации  и предварительные обсуждения хода и направлений работы \n Январь-февраль – сборка и оформление презентационных материалов проекта,  подготовка публикаций, показ промежуточных результатов, сбор замечаний,  предложений, рекомендаций; Март-апрель – доработка проекта и отдельных разделов до кондиционных показателей,\n Разработка нескольких вариантов презентационных материалов под специфику  представления и решения учебных и практических задач; Май-июнь – завершение 1-го этапа работы, организационные итоги, дипломы и заявки \n', 3, '2023-02-06', '2023-06-25', '', 'Администрация п. Никола, частные собственники земельных участков, \nВсероссийский федеральный  конкурс создания лучших проектов комфортной городской среды', NULL, 'Профессиональный проектный продукт (комплексный проект комфортной архитектурной среды), пригодный для практической реализации, конкурсного представления и поэтапной публикации процесса и результатов в профессиональных и общественно-политических изданиях и сетях', 'Знать: состав и содержание профессиональной проектной документации в соответствии с нормативными требованиями ПП РФ №87 и особенности разработки конкурсной архитектурно-проектной документации \nУметь: комплексно реализовывать проектные идеи и решения в составе междисциплинарного творческого коллектива ; использовать профессиональные графические (компьютерные и ручные) инструменты, точно и адресно формулировать предпроектные задачи и описания результатов (ПЗ) \nВладеть навыками современного проектирования и оформления проектной документации:\n', 'Ашихмин Александр Викторович', 4, 1, 218, NULL, NULL, NULL, NULL, NULL, NULL),
(516, NULL, NULL, 'Благоустройство территорий для маломобильных групп населения (МГН) в г. Иркутске', 15, 'Проектирование объектов безбарьерной городской среды в г. Иркутске для МГН', 'Необходимо выполнить проектирование объектов городской среды для маломобильных групп населения (МГН) в соответствии с нормативными документами и правилами благоустройства территории. ', 3, '2023-02-06', '2023-06-25', '', 'Управление социальной защиты населения по г. Иркутску', NULL, 'Проекты благоустройства городской среды для маломобильных групп населения в г. Иркутске', 'Знания: о составе проектной и рабочей документации при проектировании объектов благоустройства городской среды для МГН \nУмения: составлять ТЗ, анализировать территорию, проводить оценку и обоснование обследований территории с позиции приспособленности среды к МГН, выполнять дизайн-проект, а так же рабочую документацию\nНавыки: переговоров с заказчиком, с потребителями среды; проведения общественных слушаний, работы в графических редакторах и программах 3d моделирования, работы со смежными специалистами.\n', 'Черниговская В.В. ', 4, 1, 219, NULL, NULL, NULL, NULL, NULL, NULL),
(517, NULL, NULL, 'Цифровая модель объекта культурного наследия', 15, 'Создание цифровой модели объекта культурного наследия', 'Для повышения качества реставрационно-реконструктивного проектирования и обеспечения сохранности объектов культурного наследия необходимо создание цифровой модели зданий.\nЗадачи:\n1. Изучение программ для цифрового и информационного моделирования зданий\n2. Разработка типовой цифровой модели здания\n3. Сбор информации по конкретному ОКН (чертежи, фотофиксация, замеры)\n4. Разработка цифровой модели конкретного ОКН, на основе собранных данных\n5. Детальная проработка декоративных элементов ОКН\n', 3, '2023-02-06', '2023-06-25', '', 'Служба по охране объектов культурного наследия Иркутской области', NULL, 'Цифровая модель объекта культурного наследия', 'Знать специфику ОКН; основные инструменты программ цифрового и информационного моделирования (BIM)\nУметь проектировать в программах цифрового и информационного моделирования зданий\nВладеть технологиями цифрового и информационного моделирования зданий\n', 'Ларионов Никита Андреевич, Низамутдинова Зиля Фаритовна', 4, 1, 220, NULL, NULL, NULL, NULL, NULL, NULL),
(518, NULL, NULL, 'Пространственная база данных ценной застройки г. Иркутска советского периода', 15, 'Формирование базы данных  для поиска текстовой и графической информации об объектах архитектуры', 'При архитектурном проектировании в исторически сложившейся городской среде необходимы сведения о застройке различного характера. Информация может находиться в источниках, доступ к которым не всегда возможен и требует временных и прочих затрат. Кроме того, есть архивный материал, представленный только на бумажном носителе. Как проектировщикам, так и студентам архитектурного направления, для эффективного решения производственных и учебных задач нужен систематизированный оцифрованный материал в одном источнике.', 3, '2023-02-06', '2023-06-25', '', 'Служба по охране объектов культурного наследия Иркутской области', NULL, 'Пространственная база данных исторической застройки Иркутска, разработанная в программе QGIS', 'Знать особенности застройки советского периода; инструменты оцифровки\nУметь систематизировать данные о застройке, выявлять критерии, оформлять результаты анализа\nВладеть навыками работы в QGIS\n', 'Прокудин Александр Николаевич, Сыроежкина Мария Александровна', 4, 1, 221, NULL, NULL, NULL, NULL, NULL, NULL),
(519, NULL, NULL, 'Пространственная база данных исторической застройки Иркутска', 15, 'Формирование базы данных  для поиска текстовой и графической информации об объектах архитектуры', 'При архитектурном проектировании в исторически сложившейся городской среде необходимы сведения о застройке различного характера. Информация может находиться в источниках, доступ к которым не всегда возможен и требует временных и прочих затрат. Кроме того, есть архивный материал, представленный только на бумажном носителе. Как проектировщикам, так и студентам архитектурного направления, для эффективного решения производственных и учебных задач нужен систематизированный оцифрованный материал в одном источнике.', 3, '2023-02-06', '2023-06-25', '', 'Служба по охране объектов культурного наследия Иркутской области', NULL, 'Пространственная база данных исторической застройки Иркутска, разработанная в программе QGIS', 'Знать специфику исторической застройки; инструменты оцифровки\nУметь систематизировать данные о застройке, выявлять критерии, оформлять результаты анализа\nВладеть навыками работы в QGIS\n', 'Сыроежкина Мария Александровна, Шишканов Владимир Сергеевич', 4, 1, 222, NULL, NULL, NULL, NULL, NULL, NULL),
(520, NULL, '2023-03-31 05:53:16', 'Расчетное обоснование в проектировании инженерных сооружений транспортного строительства', 15, 'Получение навыков расчетов высотных знаний с диафрагмами жесткости на статические и динамические воздействия с использованием специализированных программных средств', 'Конструктивные элементы существующих и проектируемых сооружений транспортного строительства (несущие элементы мостовых сооружений, трубопроводных систем, зданий и сооружений и т.д.) в процессе эксплуатации испытывают спектр внешних нагрузок, что требует обеспечения их прочности и жесткости в условиях статического и динамического характера воздействия нагрузок. Широкое использование методов математического анализа для моделирования физических процессов и явлений, происходящих в сооружениях транспортного строительства, позволяет упростить выполнение их расчетной оценки прочности и жесткости, проводимой на основе аналитических методов теории балок, теории пластин и оболочек. Современные цифровые технологии, реализованные в специализированных программных комплекса инженерного анализа, дают возможность получить большой объем данных о напряженно-деформированном состоянии объекта исследования, что открывает широкие возможности для принятия рациональных конструктивных решений и выполнения расчетного обоснования при проектировании конструктивных элементов сооружений транспортного строительства. Перечисленные обстоятельства создают необходимость формирования специализированного курса обучения.', 2, '2023-02-06', '2023-06-25', NULL, 'тематики предприятий, выполняющий расчетные обоснования проектов', NULL, 'Владение методиками расчета и анализа конструктивных элементов сооружений транспортного строительства на статические и динамические воздействия с применением специализированного программного комплекса', 'Знания: Получение компетенций в области инженерных расчетов конструктивных элементов сооружений транспортного строительства на основе применения цифровых технологий;\r\nУмения: Выполнять расчетное обоснование проектов сооружений транспортного строительства на статические и динамические воздействия \r\nНавыки: работа в специализированных программных комплексах', 'Зеньков Евгений Вячеславович', 4, 1, 223, NULL, NULL, NULL, NULL, NULL, NULL),
(521, NULL, NULL, 'Использование солнечной энергии для отопления и горячего водоснабжения потребителей в индивидуальном жилищном строительстве, на децентрализованных территориях ', 15, 'Разработка проекта использования солнечной энергии для отопления и горячего водоснабжения зданий в удаленных территориях, а также создание программы для расчета параметров системы, использующей солнечные коллекторы', 'Проводится литературный обзор  и сравнение существующих видов солнечных коллекторов, применительно к рассматриваемой территории. Расчет экономической эффективности солнечной уста-\nновки основан на оценке средних значений солнечной радиации в месте установки системы, а также на правильном определении требуемой производительности, схемно-структурного состава установки, и стоимости отдельных элементов в данной местности. Проводится расчет систем горячего водоснабжения и отопления с использованием солнечной энергии. Осваивается работа в программном комплексе Matlab (SimInTech) и других онлайн ресурсов для расчетов ВИЭ. Формируются универсальные математические модели и программы для расчета системы, использующей солнечные коллекторы. Анализируется экономическая эффективность применяемой системы солнечного теплоснабжения  и ГВС потребителя\n', 2, '2023-02-06', '2023-06-25', '', 'Прогноз топливно-энергетического комплекса от Фонда «Надежная смена», научная молодежная школа «Возобновляемые источники энергии и приоритеты научно-технологического развития»', NULL, 'Повышение  эффективности энергообеспечения удаленных территорий, снижение платы за отопление и ГВС у потребителя, универсальные математические модели и программы для расчета солнечных коллекторов', 'Знания: нетрадиционные возобновляемые источники энергии, виды солнечных коллекторов\nУмения: выполнять расчеты солнечных коллекторов, моделировать объекты в программных комплексах, работать в команде\nНавыки: основы программирования в Matlab (SimInTech), защита результатов выполненной работы в виде публичного доклада\n', 'Петрова Анастасия Николаевна', 4, 1, 224, NULL, NULL, NULL, NULL, NULL, NULL),
(522, NULL, '2022-08-30 05:21:53', 'Создание системы мониторинга и накопительной базы данных для контроля и прогнозирования состояния теплоэнергетического оборудования на основе интерфейса, составленного на базе 3D модели узлов и агрегатов.', 15, 'Улучшить эксплуатационные характеристики узлов и агрегатов теплоэнергетического оборудования, на основе накопленных сведений полученных в течении длительного периода времени, а также текущих параметров состоянии системы.', 'В настоящий момент для проведения эксплуатационного контроля металла и технического диагностирования, составляется значительный объем документации, связанной с ремонтами, контролем металла, инцидентами, а также заменами на техническом устройстве по отдельным разрозненным формулярам и документам. Для ускорения проведения данных работ, а также в целях исключения ошибок при формировании объемов, предлагается консолидировать исполнительную документацию по техническому состоянию оборудования и привязать полученную информацию к 3D модели технического устройства. В дополнении на 3D модель оборудования для улучшения эксплуатационных характеристик предлагается вывести текущие параметры состояние оборудования, полученные от систем мониторинга, датчиков. Предложенные решения позволяют создать автоматизированный планировщик для составления расписание плановых ремонтных работ, капитальных ремонтов, замены узлов и агрегатов. Предлагается создать систему сквозного мониторинга для разных уровней инженерно-технического персонала, а также разделить полномочия по конфигурированию и настройке.', 2, '2023-02-06', '2023-06-25', NULL, 'Лаборатория энергетики\r\nАкселерационная программа, реализуемая ГК «ЕвроСибЭнерго» на базе ИРНИТУ.', NULL, 'Человеко-машинный интерфейс для взаимодействия накопительной базы данных и систем мониторинга отдельных элементов теплоэнергетического оборудования с его 3D моделью. Интерфейс должен отображать техническое состояние отдельных элементов оборудования с целью обеспечения реализации программы профилактического технического обслуживания различного оборудования, в частности, поверхностей нагрева котлоагрегатов, на основании обоснованной информации и экономически целесообразной базы для принятия решений', 'Знания: свойства металлов и сплавов; марки материалов, используемых для элементов основного и вспомогательного оборудования теплоэнергетических станций, основы моделирования процессов и объектов теплоэнергетики с применением компьютерных технологий.\r\nУмения:  подобрать марку металла для элементов котельных и турбинных установок; определить виды разрушения металла элемента оборудования в эксплуатации, применять методы математического моделирования при исследовании и проектировании теплотехнологических систем и их элементов; использовать пакеты прикладных программ для моделирования и оптимизации теплотехнологических процессов, установок и систем; выбирать эффективный численный метод для решения конкретной задачи, оценивать его точность и надежность.\r\nНавыки: владение методами неразрушающего и разрушающего контроля металла при диагностировании оборудования, методами и приемами компьютерного моделирования процессов, аппаратов и систем теплоэнергетики с помощью прикладных программ', 'Бублик Дмитрий Алексеевич', 4, 1, 225, NULL, NULL, NULL, NULL, NULL, NULL),
(523, NULL, NULL, 'Повышение износо- и коррозионностойкости элементов систем пылеприготовления (СПП)', 15, 'Разработка мероприятий, позволяющих защитить элементы СПП от коррозионного и абразивного износа и увеличивающих межремонтный период в 2 раза', 'Абразивные свойства угольной пыли приводят к повышенному износу мелющих органов мельниц (бил, билодержателей молотковых мельниц и мелющих лопаток мельниц-вентиляторов), защитной брони, пылепроводов и других элементов СПП. Их приходится довольно часто менять, что влечёт за собой рост издержек. Эффективность применяемых на сегодня методов защиты рабочей поверхности низка', 2, '2023-02-06', '2023-06-25', '', 'Акселерационная программа «Лаборатория энергетики»\nООО «Байкальская энергетическая компания»\n', NULL, 'Методика повышения износо- и коррозионностойкости элементов систем пылеприготовления (СПП)', 'Знания: строение материалов и общие закономерности формирования их структуры, эксплуатационные свойства материалов и их зависимость от строения, группы материалов, используемые в промышленности, в частности в сфере энергетики и основные способы переработки материалов в изделия. Основные технические характеристики топлив; принципы подготовки топлива к сжиганию в котельных агрегатах на объектах профессиональной деятельности.\nУмения: оценка и прогнозирование поведения материалов и изменения их свойств в зависимости от обработки и эксплуатационных факторов. Проведение лабораторного анализа по определению технических характеристик топлива; планировать и выполнять виды работ по эксплуатации объектов теплоэнергетики.\nНавыки: выбор материалов и назначения технологических процессов их переработки в изделия. Работы по подготовке топлива к сжиганию в котельных агрегатах; организация ремонтов технологического оборудования, монтажных, наладочных и пусковых работ\n', 'Ощепков Василий Владимирович', 4, 1, 226, NULL, NULL, NULL, NULL, NULL, NULL),
(524, NULL, NULL, 'Использование низкопотенциальной теплоты системы оборотного водоснабжения ТЭЦ. ', 15, 'Разработка проекта использования низкопотенциальной теплоты в тепловой схеме ТЭЦ.', 'Обзор и поиск технических решений. Литературный обзор  и постановка задач. Выбор вариантов использования низкопотенциальной теплоты системы оборотного водоснабжения ТЭЦ. Технико-экономические расчеты принятых к рассмотрению вариантов использования низкопотенциальной теплоты системы оборотного водоснабжения ТЭЦ.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Повышение энергетической эффективности ТЭЦ.', 'Знания: Знает инструменты поиска информации. \nУмения: Умеет  выделить  из  массива  информации  ключевые  моменты; использовать инструменты поиска информации. \nНавыки: Планирует, выполняет, оформляет и представляет результаты проекта. \n', 'Картавская Вера Михайловна ', 4, 1, 227, NULL, NULL, NULL, NULL, NULL, NULL),
(525, NULL, NULL, 'Снижение потерь напряжения и электроэнергии в распределительных электрических сетях 6-10 кВ', 15, 'Оценка эффективности мероприятий по снижению потерь напряжения и электроэнергии в распределительных электрических сетях 6-10 кВ электросетевой компании', 'На начальном этапе выполняется сбор информации о параметрах режима электрических сетей 6-10 кВ электросетевой компании. Составляются схемы замещения электрической сети, вводятся исходные данные в программу ПРРЭС, разработанную на кафедре электрических станций, сетей и систем. В программе выполняется расчёт максимальных режимов электрической сети, выявляются «очаги» потерь напряжения и электроэнергии. Проводится анализ структуры потерь в электрических сетях, оценка эффективности мероприятий по снижению потерь электроэнергии и напряжения.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Технический отчёт о работе с отражением всех основных этапов проекта', 'Знания: оборудование электрических сетей и систем: линии электропередачи, трансформаторы и др.; процессы, происходящие в электрических сетях\nУмения: применять математический аппарат для исследования потерь в электрических сетях\nНавыки: использование программного обеспечения для проведения расчётов установившихся режимов\n', 'Акишин Леонид Александрович', 4, 1, 228, NULL, NULL, NULL, NULL, NULL, NULL),
(526, NULL, NULL, 'Расширение функций интеллектуальной системы учета электроэнергии', 15, 'Расширение функций интеллектуальной системы учета электроэнергии для ее пользователей', 'В соответствии с постановлением Правительства Российской Федерации от 19.06.2020 г. № 890:\n• все приборы учета, вводимые в эксплуатацию энергоснабжающими организациями с 1 января 2022 г. в целях коммерческого учета электроэнергии на розничных рынках и предоставления коммунальных услуг, должны быть присоединены к интеллектуальной системе учета электроэнергии (ИСУЭ);\n• пользователям ИСУЭ предоставляется доступ к минимальному набору функций ИСУЭ. \nВ минимальном наборе функций ИСУЭ предусмотрен доступ к данным измерений интеллектуальных приборов, позволяющим расширить функции ИСУЭ для пользователей. Первоначально проектом предусматривается реализация следующих пяти функций:\nдля потребителей электроэнергии – 1) выбор экономически выгодного тарифа расчета за потребленную электроэнергию; 2) планирование энергоемких процессов хозяйствования с целью уменьшения размера платы за электроэнергию без снижения электропротребления;\nдля сетевых организаций – 3) определение топологии электрической сети; 4) выявление ненаблюдаемых отборов электроэнергии из электрических сетях, в том числе кражи электроэнергии; 5) балансировка нагрузки в распределительных сетях с целью снижения потерь электроэнергии. \nВ дальнейшем планируется расширение функций для пользователей ИСУЭ (потребителей электроэнергии, гарантирующих поставщиков, энергосбытовых организаций, сетевых организаций, производителей электрической энергии, системного оператора и субъектов оперативно-диспетчерского управления, организаций коммерческой инфраструктуры) в соответствии с их потребностями. \n', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Прототипы программных комплексов для пользователей с расширенными функциями ИСУЭ.', 'Знать: конструкции и характеристики интеллектуальных измерительных приборов и ИСУЭ; системы обмена данными между интеллектуальными приборами и ИСУЭ; методы обработки информации;  математическое моделирование и вычислительные методы.\nУметь: использовать методы обработки информации и вычислительные методы; интерпретировать информацию в виде схем, графов, диаграмм, графиков, таблиц.\nВладеть: навыками обработки информации и применения вычислительных методов,  реализации прототипов программ.\n', 'Болоев Евгений Викторович', 4, 1, 229, NULL, NULL, NULL, NULL, NULL, NULL),
(527, NULL, NULL, 'Энергетическая безопасность города Иркутска', 15, 'Решение проблемы обеспечения энергетической безопасности города Иркутска', 'Решение проблемы обеспечения энергетической безопасности города Иркутска требует: трактовку понятия энергетическая безопасность; выбор путей ее обеспечения; выбор средств обеспечения  энергетической безопасности города Иркутска.', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Альтернативные проекты обеспечения  энергетической безопасности города Иркутска.', 'Знания: знать основные причины снижения энергетической безопасности\nУмения: уметь выбирать средства повышения энергетической безопасности\nНавыки: владеть навыками оценки энергетической безопасности\n', 'Дубицкий Михаил Александрович', 4, 1, 230, NULL, NULL, NULL, NULL, NULL, NULL),
(528, NULL, NULL, 'Определение текущих значений параметров электрооборудования и электрических сетей в нормальном и аварийном режимах по мгновенным цифровым данным', 15, 'Разработка математических способов и алгоритмов определения текущих значений параметров электрооборудования и электрических сетей позволит создать комплекс программ и/или электронных блоков с целью их реализации на внутреннем и внешнем рынке для существующих и интеллектуальных энергосистем ближайшего будущего. Коммерческая реализация проекта требует наличия программистов и электронщиков.', 'Текущее значение параметров электрооборудования и энергосистемы в целом является случайным по целому ряду причин. К основным причинам относятся следующие:\n- переменные погодные условия эксплуатации, которые изменяют проводимость грунта, проводов и тросов заземления, диэлектрическую и магнитную проницаемость среды, распределённую ёмкость и индуктивность ЛЭП и др.;\n- постоянно изменяющийся характер нагрузки в процессе эксплуатации, что приводит к кратковременным перенапряжениям на линиях или к провалам напряжения, перегрузка ведёт к насыщению электротехнической стали магнитопроводов трансформаторов и изменению гармонического состава цепи и др.;\n- включения и отключения мощных потребителей приводят к постоянным переходным процессам на линии;\n- изменяющая со временем топология сети из-за подключения новых и/или отключения существующих потребителей электроэнергии.\nВ этой связи задача определения текущих значений параметров электрооборудования и сетей имеет существенное значение, так как наличие этих параметров позволяет установить место и причину возникновения аварийного режима\n', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Методика, с обязательной фиксацией в одном из форматов: публикация, выпускная квалификационная работа, пояснительная записка или инструкции, а при наличии человеческих ресурсов (программистов и электронщиков) и финансовых ресурсов для оплаты их труда, приобретения оборудования и комплектующих деталей – создание конкурентных электронных блоков, защищённых патентами РФ', 'Знания: физико-математический аппарат, методы анализа и моделирования, теоретического и экспериментального исследования для определения текущих значений параметров электрооборудования и сетей\nУмения: оформлять результаты научно-исследовательской работы в виде отчёта, реферата или публикации\nНавыки: навыки публичной защиты результатов научно-исследовательской работы\n', 'Муссонов Геннадий Петрович', 4, 1, 231, NULL, NULL, NULL, NULL, NULL, NULL),
(529, NULL, NULL, 'Разработка и исследование методик определения мест повреждения в  электрических сетях с изолированной нейтралью.', 15, 'Разработать и исследовать методику определения поврежденного присоединения при однофазном замыкании на землю (ОЗЗ) в электрических сетях с изолированной нейтралью. Исследовать методики определения места повреждения (ОМП) на поврежденной линии электропередачи.', 'Изучается методика расчета электрических режимов в  фазных координатах (ФК). Осваивается работа в программном комплексе «Расчет в ФК». Формируется модель электрической сети с изолированной нейтралью для проведения расчетов в ФК. Проводится серия расчетов режимов в ФК. Формируются рекомендации. ', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Будет разработана методика определения поврежденного присоединения при ОЗЗ в электрических  сетях с изолированной нейтралью. Будет разработана релейная защита для отключения поврежденного присоединения с ОЗЗ. Будет разработана лабораторная работа по методике определения поврежденного присоединения при ОЗЗ в электрических  сетях с изолированной нейтралью. ', 'Знания: По проблеме ОМП при ОЗЗ в сетях с изолированной нейтралью.  По расчету электрических режимов в ФК и работе в программном комплексе «Расчет в ФК»\nУмения: Формировать модель электрической сети с изолированной нейтралью для проведения расчетов в ФК\nНавыки: Расчета нормальных и аварийных режимов в ФК в сетях с изолированной нейтралью.\n', 'Тигунцев Степан Георгиевич', 4, 1, 232, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(530, NULL, NULL, 'Разработка проектной документации и модернизация лабораторного оборудования кафедры электрических станций, сетей и систем', 15, 'Разработка документации, модернизация и монтаж оборудования учебных лабораторий кафедры электрических станций, сетей и систем: аудитория В-212, аудитория В-016, учебный полигон – подстанция 110 кВ', 'Проектная документация на оборудование учебной лаборатории релейной защиты и автоматики (ауд. В-212) не везде соответствует фактической сборке стенда, что усложняет проведение лабораторных работ. В учебно-исследовательской лаборатории «Электрическая часть электростанций и подстанций» (ауд. В-016) в 2021 году восстановлена ячейка комплектного распределительного устройства 10 кВ, документация на которую отсутствует. Имеются отдельные цифровые терминалы релейной защиты и автоматики серии MiCOM, которые необходимо подключить к оборудованию учебного полигона – подстанции 110 кВ между корпусами В и Г. Некоторые стенды лабораторий требуют специального профилактического обслуживания.\nПри выполнении проекта будет сформировано 3-4 бригады по 3-4 студента, каждая из которых будет выполнять проверку, прозвонку и составление реальной электрической схемы закреплённого за ней лабораторного оборудования, формировать электрические схемы лабораторных стендов в цифровом виде при помощи систем автоматизированного проектирования и/или редакторов схем (nanoCAD, Компас, Visio). Под руководством наставника студенты проведут модернизацию лабораторного оборудования, выполнят монтаж дополнительных узлов и элементов схем лабораторных стендов, проведут пусконаладочные работы.\n', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Документация к лабораторным стендам в виде исполнительных электронных схем, модернизированные лабораторные стенды.', 'Знания: принципы работы первичного и вторичного электрооборудования, схемы управления и блокировок первичного электрооборудования, принципы действия различных типов релейной защиты электрооборудования от коротких замыканий\nУмения: проверять электрические схемы, выполнять электромонтажные и профилактические работы электрооборудования, представлять результаты выполненной работы в виде пояснительной записки\nНавыки: чтение электрических схем первичного и вторичного электрооборудования, работа в системах автоматизированного проектирования и/или редакторах схем, выполнение пусконаладочных работ электрооборудования, защита результатов выполненной работы в виде доклада\n', 'Федосов Денис Сергеевич', 4, 1, 233, NULL, NULL, NULL, NULL, NULL, NULL),
(531, NULL, NULL, 'Математическое моделирование фотоэлектрических систем и ветропарков большой мощности', 15, 'Создание программы для расчета режимных параметров фотоэлектрических систем и ветропарков большой мощности ', 'Современный этап развития энергетических систем характеризуется глубокой интеграцией возобновляемых источников энергии. Наличие экологически чистых комплексов генерации наблюдается на всех уровнях напряжений, начиная с крупных системообразующих объектов и заканчивая мини- и микроустановками, расположенными непосредственно у потребителя. Главной задачей, возникающей при использовании возобновляемых источников энергии, является оптимизация состава оборудования и установленных мощностей. При этом в качестве целевой функции могут выступать различные критерии эффективности применения возобновляемых источников энергии. Например, в автономных энергетических системах целевая функция, как правило, представлена нормированной стоимостью энергии (руб./кВт∙ч), в системах резервного и аварийного (в т.ч. комбинированного) питания – максимизация количества часов автономного снабжения и минимизация недоотпуска электроэнергии, в комплексах генерации, реализующихся в рамках энергосервисного контракта – количество сэкономленного органического топлива и прибыль инвестора. Представленные критерии могут быть объединены и расширены в зависимости от условий поставленной задачи.\nОпределение численных значений критериев эффективности напрямую связанно с моделированием режимов работы энергетических систем, состоящих из элементов генерации, передачи, распределения, аккумулирования и потребления энергии. Цель данного исследования состоит в формировании ряда требований к математической модели фотоэлектрических преобразователей и демонстрации подходов, позволяющих моделировать все необходимые режимные параметры фотоэлектрических систем и ветропарков с учётом изменения метеоусловий.\n', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Универсальные математические модели и программы для расчета режимов фотоэлектрических систем и ветропарков', 'Знания: теоретические основы электротехники, методы оптимизации, возобновляемые источники энергии\nУмения: выполнять расчеты, моделировать технические объекты, работать в команде\nНавыки: основы программирования в Matlab\n', 'Карамов Дмитрий Николаевич', 4, 1, 234, NULL, NULL, NULL, NULL, NULL, NULL),
(532, NULL, NULL, 'Интеграция аккумулирующих устройств большой емкости в энергетические системы с возобновляемыми источниками энергии', 15, 'Создание расчетного модуля для решения задач обоснования интеграции аккумулирующих устройств большой емкости в энергетические системы', 'При исследовании энергетических систем с возобновляемыми источниками энергии и аккумуляторными батареями важно учитывать процессы деградации и замены энергетического оборудования в течение всего срока эксплуатации. Это необходимо для точного определения дополнительных издержек на замену, влияющих на показатели экономической эффективности рассматриваемого состава оборудования. \nАккумуляторные батареи являются стабилизирующим элементом автономной энергетической системы, работающий в циклическом режиме. Циклический режим характеризуется сменяющими друг друга процессы заряда и разряда в зависимости от генерации возобновляемых источников энергии и уровня электрической нагрузки. Стохастическая составляющая генерации существенно отражается на основных эксплуатационных показателях аккумуляторных батарей, таких как состояние заряда, падение напряжения, внутреннее сопротивление, а также химических процессах.\nАккумуляторные батареи имеют три важных показателя таких как максимальный срок службы, предельное количество циклов заряд/разряд в зависимости от глубины разряда и среднегодовое количество циклов заряд/разряд. \n', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Универсальные математические модели и программы для расчета режимов работы накопителей энергии и энергетических систем', 'Знания: теоретические основы электротехники, методы оптимизации, возобновляемые источники энергии, \nУмения: выполнять расчеты, моделировать технические объекты, работать в команде\nНавыки: основы программирования в Matlab\n', 'Суслов Константин Витальевич', 4, 1, 235, NULL, NULL, NULL, NULL, NULL, NULL),
(533, NULL, NULL, 'Использование концепции энергетического хаба и потоковых методов в интегрированных энергетических системах ', 15, 'Определить с помощью потоковых методов уровень структурной надежности интегрированных систем.  ', 'Энергетика является важнейшей отраслью, охватывающей добычу энергоресурсов, производство, преобразование, транспортировку и использование энергии потребителями. Энергоснабжение потребителей обеспечивается различными видами энергоресурсов, которые мало взаимосвязаны между собой. В качестве объединяющей системы выступает топливно-энергетический комплекс (ТЭК) России. ТЭК включает в себя основные три подсистемы: топливоснабжающие системы; системы электро– и теплоснабжения; система ядерной энергетики. На этапе планирования развития ТЭК рассматриваются все отрасли энергетики, но вопросам комплексного использования различных видов энергии не уделяется должного внимания.\nПредлагается определить структурную надежность интегрированных систем энергоснабжения с использованием различных методов. \n', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Методика определения структурной надежности системы энергоснабжения.', 'Знания: \n– перспективы и возможности развития концепции интеллектуальных энергетических систем;\n– технологический базис интеллектуальных энергетических систем;\nУмения: \n– использовать методические, нормативные и руководящие материалы, касающиеся выполняемой работы;\n– формулировать и решать задачи, возникающие в ходе производственно-технологической и научно-исследовательской деятельности и требующих углубленных профессиональных знаний;\n– анализировать, структурировать и обобщать научно-исследовательские материалы\nНавыки: \n– владеть терминологией в области интегрированных энергетических систем; \n– владеть навыками определения структурной надежности методом поиска путей и сечений. \n', 'Сердюкова Екатерина Владимировна ', 4, 1, 236, NULL, NULL, NULL, NULL, NULL, NULL),
(534, NULL, NULL, 'Создания кибер-физической модели изолированных систем электроснабжения с возобновляемыми источниками энергии', 15, 'Разработка и апробирование алгоритма создания цифровых двойников изолированных систем с ВИЭ на базе кибер-физической модели', 'Согласно концепции цифровой трансформации российской экономики и в частности трансформации российской ТЭК разработаны основные подходы для реализации данной программы. Один из элементов цифровой платформа является цифровой двойник энергетического объекта или системы. Существует два подхода для реализации  данного направления: цифровой двойник, в основе которого лежат нелинейные дифференциальные уравнения в частных производных; цифровая тень, в основе  которого лежат промышленный интернет вещей и большие данные.\nЦелью данных подходов является получение алгоритмов управления энергетическими объектами (системами) для которых невозможно реализовать типовые алгоритмы управления.\nДля этих целей создается кибер-физическая модель, состоящая из реальных элементов энергетических систем: трансформатора, источника питания, физические модели линии передач, физические модели нагрузок. В дальнейшем в системе имитационного моделирования создается имитационная модель данной физической модели энергетической системы. Проводится верификация различных режимов работы физической модели и имитационной модели, на этом этапе уточняются алгоритмы расчета параметра блоков имитационной модели по номинальным (каталожным) данным реальных электротехнических объектов. В дальнейшем имитационная модель используется для получения большого объема статистической информации по различным режимам работы физической модели (BIG DATA). Эти данные лежат в основе создания различных алгоритмов управления с использования элементов искусственного элемента. Полученные алгоритмы управления проверяются на кибер-физические  модели. \n', 2, '2023-02-06', '2023-06-25', '', '', NULL, 'Результатом проведенной работы являются различные алгоритмы и процедуры, позволяющие создать адекватную имитационную модель по параметрам реального энергетического объекта и будет проведена апробация различных алгоритмов управления на базе искусственного интеллекта с целью выбора наиболее оптимального варианта.   ', 'Знания: принципы работы основного электрооборудования, трансформатора, линии передачи, нагрузки, принципы работы основных систем имитационного моделирования энергетическими объектами \nУмения: выполнение электромонтажных работ, снятие рабочих характеристик с основных электротехнических объектов     \nНавыки:  чтение электрических схем первичного вторичного электрооборудования, работа в системах имитационного моделирования с защитой результатов выполненной работы\n', 'Шамарова Наталия Андреевна', 4, 1, 237, NULL, NULL, NULL, NULL, NULL, NULL),
(535, NULL, '2023-07-06 08:46:01', 'Разработка проектов систем автоматизации промышленных установок', 15, 'Разработка технорабочих проектов автоматизированных систем управления (АСУ) объектов промышленного и энергетического оборудования.', 'Выбор темы проекта и формулировка технических предложений по проекту. Изучение способов получения и обработки информации по проекту. За время обучения студенты получают опыт проектной работы по своей будущей профессии, лучше поймают взаимосвязь преподаваемых дисциплин с практикой и значимость командной работы, а также вырабатывают умение доводить дело до конца и в срок. Дополнительно к диплому каждый выпускник к окончанию университета может сформировать свое личное портфолио реализованных проектов с различными компаниями, что может помочь ему в трудоустройстве на более привлекательную работу и создаст предпосылки для образования в ИРНИТУ компаний-технологических стартапов, способных самостоятельно продолжать работу, начатую в рамках проектной деятельности в партнерстве с внешними заказчиками.', 3, '2023-02-06', '2023-06-25', NULL, 'ООО «Иркутский институт Гипрокоммунводоканал» 664033, Россия, Иркутская область, г. Иркутск, ул. Лермонтова, д. 257 Тел. +7(3952) 56-22-30 www.polyplastic.ru', NULL, 'Технический проект (ТП), Рабочий проект (РП). Обеспечение объекта проектной документацией, позволяющей реализовать автоматизированную систему управления.', 'Знания: основ разработки проектной и рабочей документации автоматизированных систем управления объектов промышленного и энергетического оборудования.\r\nУмения: рассчитывать необходимое количество средств измерений, управляющего и коммутационного оборудования, предлагаемого промышленностью.\r\nНавыки: выбора необходимого типа и номенклатуры оборудования, изделий, материалов.', 'Довудов Сарфароз Умедович', 4, 1, 238, NULL, NULL, NULL, NULL, NULL, NULL),
(536, NULL, NULL, 'Система инженерных электротехнических коммуникаций электрооборудования', 15, 'Разработка системы электротехнических коммуникаций, предназначенных для создания внутренних инженерных сетей, используемых для электроснабжения и управления электрооборудованием', 'Для электроснабжения и управления электрооборудованием используются сети внутренних инженерных коммуникаций. В ходе проектирования требуется точно определить структуру сети, ее геометрические и электрические параметры, включающие планы оборудования, их мощность, требования по размещению, управлению и электроснабжению. \nПри этом разрабатываемая система инженерных электротехнических коммуникаций электрооборудования уникальна для каждого объекта. Так же в случае внесения изменения в конструкторскую документацию системы требуется в кратчайшие сроки либо перепроектировать существующую, либо создать новую систему внутренних инженерных сетей. \nБольшая часть требований к системам электротехнических коммуникаций имеет формализованный вид и описана в научной литературе, а трудоемкость их проектирования связана, в первую очередь, с выполнением большого числа рутинных операций конструктором. \nТаким образом, для ускорения процесса проектирования наиболее рационально перенести большую часть рутинных операций проектирования в среду автоматизированной системы, а так как в России широко используется система AutoCad, то автоматизированные процедуры проектирования можно реализовать посредством использования ее последних версий.', 3, '2023-02-06', '2023-06-25', '', '', NULL, 'Проект внутреннего электроснабжения и электроосвещения заданных помещений', 'Знания: основ разработки проектной документации внутреннего электроснабжения и электроосвещения.\nУмения: рассчитывать необходимое количество осветительного и коммутационного электрооборудования.\nНавыки: выбора необходимого типа и номенклатуры кабельных изделий.\n', 'Дунаев Андрей Михайлович', 4, 1, 239, NULL, NULL, NULL, NULL, NULL, NULL),
(537, NULL, NULL, 'Газпром Инвест', 15, 'Получение навыков проектной работы при постоянном взаимодействии с проектным офисом компании в процессе решения кейсов из реального производства  ', 'ООО «Газпром инвест» — единый технический заказчик по реализации инвестиционных проектов ПАО «Газпром», в том числе по геолого-разведочным работам, строительству, реконструкции, капитальному ремонту объектов добычи, транспорта, подземного хранения, переработки газа, объектов газификации и гражданского назначения.\n\nПроектная команда будет работать со специалистами компании в городе Иркутске.\nИз числа участников команды формируется «копия» проектной команды Филиала для решения актуальных задач компании в области  проектирования, строительства и ввода в эксплуатацию объектов газовой отрасли промышленного и гражданского назначения на Ковыктинском ГКМ. \nВ рамках работы над проектом вы получите навыки работы в реальной компании над актуальной проблемой отрасли', 3, '2023-02-06', '2023-06-25', '', 'Филиал ООО «Газпром инвест» Иркутск', '', 'Проектное предложение', 'Знания: матричной структуры управления, планирования и управления проектами. Предметные знания в области геолого-разведки, строительства, проектного управления, добычи и транспортировки газа. \nУмения: работы в команде, построенной по принципам матричного управления. Взаимодействия со специалистами  отрасли строительства и газодобычи\nНавыки: работы в кооперации с представителями реальной компании, междисциплинарного взаимодействия с целью решения реальных задач, навыки планирования и управления реальными проектам', '', 4, 1, 300, 0, NULL, NULL, NULL, NULL, NULL),
(538, NULL, '2022-06-16 08:18:20', 'Современная уголовная политика России', 15, 'Изучить различные направления уголовной политики современной России', 'Уголовная политика государства – это одно из направлений деятельности государства, так называемый основополагающий вектор в сфере борьбы с преступностью. На современном этапе уголовной политике уделяется особенное внимание, поскольку уголовная политика напрямую влияет на состояние и показатели преступности в стране, а также позволяет строить прогноз на последующее совершенствование уголовно-правовых норм, с целью снижения уровня преступности в целом. Состояние преступности в нашей стране требует постоянного внимания общества и государства. Определить в рамках темы проекта направление исследования; подготовить план исследования; подобрать научную, учебную литературу, судебную практику, статистические данные; подготовить научную статью в рамках определённой тематики, опубликовать статью в журнале ВАК', 2, '2023-02-06', '2023-06-25', NULL, NULL, NULL, 'Научно-исследовательская работа студента', 'Знания:\r\nЗнать основные инструменты поиска информации.\r\nЗнать основные требования к представлению результатов проекта.\r\nЗнать основные принципы планирования и организации своей деятельности.\r\nУмения:\r\nУметь использовать инструменты поиска и анализа информации.\r\nУметь выделить из массива информации ключевые моменты.\r\nУметь использовать основные инструменты планирования и реализации проекта.\r\nУметь подготовить результаты.\r\nНавыки:\r\nВладеть навыками поиска информации.\r\nВладеть навыками анализа информации с целью выделения требуемого знания.\r\nВладеть навыками на основе полученной первичной информации сформировать комплексное понимание предмета изучения.\r\nВладеть навыками презентации результатов проекта.\r\nВладеть навыками самоанализа и может оценить личный вклад в достигнутых результатах.\r\nВладеть навыками определения и постановки задач.', 'Герасимова Юлия Радиковна', 4, 1, 241, NULL, NULL, NULL, NULL, NULL, NULL),
(544, '2023-04-07 03:20:47', '2023-04-07 03:20:47', 'Платформа для подготовки статьи', 0, 'Создать платформу', 'В рамках заявляемого проекта предполагается использовать мультикристаллический кремний в качестве модельного материала для разработки комплекса программ, реализующих следующие полезные модели:\n• усовершенствованная  нейронная сеть  для идентификации параметров ориентации монокристаллических зёрен в промышленных слитках мультикремния по их сканированным изображениям;\n• модель для  автоматизированного зонирования макроструктуры продольных пластин слитков мультикремния с целью поиска взаимосвязей между пространственным распределением зон на изображениях пластин и условиями направленной кристаллизации.', 1, '2023-09-01', '2023-12-30', 'requirements', 'Интитут геохимии', 'additional_inf', 'Для написания научных статей', 'Цитирование статей', NULL, 7, 1, NULL, 63, 4, NULL, NULL, NULL, NULL),
(546, '2023-04-07 06:32:32', '2023-04-07 06:42:54', 'Разработка программного комплекса для оценивания состояния ЭВиЧ', 0, 'Разработать инструментарий для оценки состояния ЭВиЧ по рядам косвенных измерений, полученных в ходе функционирования атомных часов', 'Повышение точности оценивания состояния ЭВиЧ (т.е. показаний атомных часов, при формировании автономной шкалы времени) возможно, в том числе, за счет  снижения алгоритмической погрешности при обработке частотно-временной информаци, поступающей в ходе функционирования эталона.  Существенный выигрыш возможен за счет применения прогнозирующих моделей АРСС....\n\n\n!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!', 3, '2023-09-01', '2024-05-30', 'requirements', 'ВНИИФТРИ Иркутск', 'additional_inf', 'Разработать инструментарий для оценки состояния ЭВиЧ по рядам косвенных измерений, полученных в ходе функционирования атомных часов, в статическом и  динамическом режиме с применением адаптивных алгоритмов', 'анализ временных рядов,  фильтрация нестационарностей, имитационное моделирование, применение различных методов оптимизации, проектирование и реализация ПО на языке python, использование MathCad', NULL, 7, 1, NULL, 63, NULL, NULL, NULL, NULL, NULL),
(550, '2023-04-17 12:05:29', '2023-08-31 09:48:25', 'Развитие системы \"Ярмарка проектов\" (кабинет руководителя ЦПО)', 15, 'Создание решения для поддержки процесса сбора заявок на открытие проектов  от сотрудников и их обработки на сервисе \"Ярмарка проектов ИРНИТУ\"', 'Данный проект выполняется в рамках работ по созданию цифрового сервиса для поддержки процесса организации проектной деятельности  \"Ярмарка проектов ИРНИТУ\"\r\nВ настоящее время имеется следующий задел по проекту: \r\n- разработано и внедрено веб-приложение позволяющее студентам просматривать карточки проектов, осуществлять сбор заявок от студентов на участие в проектах;\r\n- реализован АРМ руководителя ЦПО предоставляющий возможность формирования списков проектных команд на основе алгоритма автоматического распределения студентов по проектам с учетом их предпочтений и принадлежности к тому или иному направлению подготовки;\r\n- реализована функциональность кабинета наставника: просмотр связанных с сотрудником проектов, подача заявки на открытие нового проекта;\r\n- спроектирован и частично реализован кабинет директора: возможность экспертизы заявок на открытие проектов по своему институту.\r\nВ рамках данного проекта планируется доработать имеющуюся систему для поддержки процесса организации проектной деятельности и дальнейшей интеграции с другими информационными системами и цифровыми сервисами ИРНИТУ.', 3, '2023-09-01', '2024-05-30', 'requirements', 'ЦПО, Чимитов П.Е.', 'additional_inf', 'Реализация функциональности кабинета руководителя центра проектного обучения для поддержки процессов сбора заявок на открытие проектов и их обработки, а также управления процессом сбора студенческих заявок на участие в проектах. Осуществление интеграции данных системы с Портфолио студента ИРНИТУ.', 'Знания: принципы работы веб-сайта, основы веб-программирования, ORM-фреймворки, нотация Чена, стандарты описания UML, IDEF0, RDF\r\nУмения: читать и составлять техническую документацию с использованием стандартов UML, IDEF0, RDF, моделирование данных, составление SQL-запросов, \r\nНавыки: работа с СУБД MySQL, администрирование Linux, работа с Figma, разработка JavaScript скриптов, разработка php-скриптов, работа с Laravel', NULL, 1, 1, 307, 59, 1, NULL, NULL, NULL, NULL),
(552, '2023-05-12 08:26:20', '2023-06-30 06:09:19', 'Эргодизайн рабочих помещений', 15, 'Формирование навыков практического применения нормативно-правовой документации в области эргономических аспектов безопасности при проектировании рабочих мест  и рабочего пространства', 'Постоянно в ИРНИТУ существует необходимость в ремонте и переоборудовании различных помещений - офисов, учебных аудиторий, производственных лабораторий и т.п.  Данный проект предусматривает возможность  эргономической оценки этих помещений и разработке предложений по их эргодизайну.  \n\nПроект нацелен на сбор информации об организации рабочего процесса в конкретном  помещении, предполагает расчет максимально возможного количества рабочих мест в нем, разработку вариантов их размещения и организации, а также разработку предложений по общему дизайну и оформлению рабочей среды с учетом эргономических требований и норм.', 2, '2023-09-01', '2024-05-30', 'requirements', 'Гринюк Роман Андреевич, начальник управления Кампусом ИРНИТУ', 'additional_inf', 'Разработка проекта размещения рабочих мест и эргодизайна рабочего помещения', 'Сбор, анализ и оценка информации об условиях организации рабочего пространства  в рабочих помещениях различного назначения. \nФормирование навыков проектирования рабочего пространства и рабочих мест с учетом требований действующей нормативно-правовой документации.', NULL, 1, 1, NULL, 19, 1, NULL, NULL, NULL, NULL),
(554, '2023-05-19 09:55:48', '2023-06-22 04:53:08', 'Внедрение сервиса для Центра Карьеры', 15, 'Оптимизация взаимодействия внутренних служб университета и обучающихся по направлению практической деятельности', 'Информационная система должна обеспечивать электронное взаимодействие обучающихся, сотрудников дирекции институтов, кураторов практики со стороны институтов и внутренних подразделений  университета с Центром карьеры.', 1, '2023-09-01', '2023-12-30', 'requirements', 'Копайгородский А.Н.', 'additional_inf', 'Создать информационную систему для автоматизации взаимодействия и отчетности по направлению практической деятельности обучающихся', 'Сопровождение Веб-сервисов на базе Битрикс', NULL, 1, 1, 324, 59, 1, NULL, NULL, NULL, NULL),
(556, '2023-05-24 04:48:51', '2023-05-24 04:49:01', 'Разработка цифрового двойника авиастроительного предприятия с применение VR (unity)', 15, 'Создание цифрового двойника производственного помещения в образовательном сегменте позволит обеспечить доступные инструменты для пользователей и дополнить обучающие программы интерактивным визуальным контентом. Погружение студентов в производственную атмосферу, без физического присутствия на производстве.', 'В настоящее время имеется следующий задел по проекту: разработано 1 станция виртуальной сборки, виртуализированы 3 лабораторных работ.\nВ рамках данного проекта планируется масштабировать виртуальные цеха авиастроительного предприятия, доработать имеющийся сценарий агрегатно-сборочных работ.', 3, '2023-09-01', '2024-05-30', 'requirements', 'ИАЗ, кафедра СМиЭАТ ИАМИТ', 'additional_inf', 'Создан симулятор (тренажер), содержащий следующие функции:\n1. Знакомство с конструкцией авиационных узлов и агрегатов (членение агрегатов и узлов)\n2. Монтаж и ППР сборочного приспособления (доработка существующего функционала)', 'Unity 3d\nBlender\nPHP\nC++\nПроектирование БД', NULL, 1, 1, 1, 59, 4, NULL, NULL, NULL, NULL),
(557, '2023-05-24 06:31:06', '2023-05-24 06:58:21', 'Академия ИТ', 15, '«Академия IT» нацелена на подготовку IT-специалистов для энергетических и металлургических предприятий РУСАЛ и En+Group. Программа предполагает три этапа по проектным блокам Web, 1C, информационная безопасность или сетевая инфраструктура.', '«Академия IT» нацелена на подготовку IT-специалистов для энергетических и металлургических предприятий РУСАЛ и En+Group. Программа предполагает три этапа по проектным блокам Web, 1C, информационная безопасность или сетевая инфраструктура.\n\nВ первом туре (март-июнь) второкурсники узнают о деятельности компании, прослушают курс лекций, посетят мастер-классы, решат реальные производственные задачи. Студенты познакомятся с наставниками и менторами, которые в будущем могут стать коллегами.\n\nВо втором этапе политеховцам предлагается заключить целевой договор с ежемесячной выплатой стипендии в размере пяти тысяч рублей. В течение двух месяцев студентам предстоит пройти производственную практику на базе предприятий.\n\nВ финальном туре эксперты оценят деятельность участников и отберут 30 четверокурсников. Студенты разработают проект, который будет засчитан как выпускная квалификационная работа. Кроме того, студенты могут совмещать учёбу и работу в компании.\n\nПолитеховцы, успешно окончившие курсы, получат сертификат и удостоверение международного образца. Компания гарантирует официальное трудоустройство в подразделения РУСАЛ и En+Group, достойную заработную плату и карьерный рост.', 1, '2023-09-01', '2024-05-30', 'requirements', 'Эн+ Диджитал', 'additional_inf', 'Будет', 'Будут', NULL, 1, 1, 23, 59, 4, NULL, NULL, NULL, NULL),
(558, '2023-05-24 13:36:41', '2023-05-25 04:07:29', 'Развитие системы \"Электронный учебный журнал образовательных курсов ИРНИТУ\"', 0, '-', 'В рамках развития системы \"Электронный учебный журнал образовательных курсов программы «Сетевой лицей ИРНИТУ\" необходимо решить следующие первоочередные задачи\n\n1. Адаптировать интерфейс под мобильные платформы\n2.', 3, '2023-09-01', '2024-05-30', 'requirements', 'Центр профессиональной ориентации и довузовской подготовки,  Хадкевич Н. А.', 'additional_inf', 'Веб версия электронного журнал адаптированная под работу Центра профессиональной ориентации и довузовской подготовки', 'Командная разработка, работа по agile, backend/frontend разработка, администрирование БД, работа с VPS', NULL, 7, 1, 322, 59, 1, NULL, NULL, NULL, NULL),
(559, '2023-05-25 00:57:59', '2023-06-01 17:44:02', 'Контроль и оценка стабильности параметров при производстве ООДСЕ изделий авиационной техники', 15, 'Разработать алгоритм слежения за стабильностью критических параметров в технологическом процессе для обработки Особо Ответственных Деталей/ Сборочных Единиц (ООДСЕ) самолета', 'Обучающиеся, решившие принять участие в данном проекте, на реальном заказе для Иркутского авиазавода пройдут путь от рабочей документации на технологический процесс до контроля деталей, полученных на производстве', 2, '2023-09-01', '2024-05-30', 'requirements', 'Иркутский Авиационный Завод', 'additional_inf', 'Алгоритм для контроля стабильности технологического процесса производства деталей авиационной техники, оценка и анализ показателей стабильности', 'Технология машиностроения, Технологический процесс, Технический контроль', NULL, 1, 1, NULL, 48, NULL, NULL, NULL, NULL, NULL),
(560, '2023-05-25 04:31:59', '2023-05-25 04:32:15', 'Развитие сервиса \"Абитуриент ИРНИТУ\" (интерактивная игра для приемной кампании)', 15, 'Реализация интерактивного представления об обучении в институте ИТиАД, создание положительного образа института в глазах целевой аудитории, привлечение заинтересованных в обучении абитуриентов.', 'Реализация интерактивного представления об обучении в институте ИТиАД, создание положительного образа института в глазах целевой аудитории, привлечение заинтересованных в обучении абитуриентов. Для повышения успешности приемной  PR-компании Университета. Для снижения времени адаптации первокурсников в стенах Университета, знакомство с виртуальным кампусом ИРНИТУ, а также дополнительными возможностями, которые предоставляются обучающимся в интересном для школьников и студентов в игровом формате - GameDev.\nВозможность масштабирования путем формализации и виртуализации основных процессов и программ обучения других институтов Университета (2-й в очереди институт АМиТ – 2024 год.).', 3, '2023-09-01', '2024-05-30', 'requirements', 'Управление по работе с абитуриентами', 'additional_inf', 'Видео игра для привлечения абитуриентов и  знакомство в игровой форме с Университетом', 'GameDev, unity, моб. разработка', NULL, 1, 1, NULL, 59, 1, NULL, NULL, NULL, NULL),
(561, '2023-05-30 14:41:26', '2023-07-11 08:44:22', 'Современные технологии исследования и проектирования объектов деревянного зодчества', 15, 'Разработка проектной документации объектов деревянного зодчества, которая включает в себя текстовые и графических материалы, определяющие архитектурные, функционально-технологические, конструктивные и инженерно-технические решения.', 'Проектная документация необходима для оценки соответствия принятых решений требованиям законодательства и нормативным правовым актам. В ходе выполнения данного проекта необходимо выполнить подбор и разработку оптимальных методик моделирования и проектирования; подготовку и оформление разделов проектной документации в соответствии с действующей нормативно-правовой базой; обзор, анализ и изучение имеющихся программных продуктов по моделированию и расчету зданий и сооружений.', 3, '2023-09-01', '2024-05-30', 'requirements', 'Экопарк \"Озера на снежной\"', 'additional_inf', 'Информационные модели зданий (сооружений); Текстовая и графическая часть проектной документации.', 'Знание расчетных и графических комплексов', NULL, 1, 1, NULL, 26, 4, NULL, NULL, NULL, NULL),
(563, '2023-06-01 11:07:54', '2023-07-06 08:59:00', 'Разработка модели коммерциализации результатов проекта «Исследование противокоррозионных свойств эпоксидных композиций, допированных ингибиторами коррозии»', 15, 'Создать эффективную модель коммерциализации инновационного проекта', 'При реализации НИОКР в рамках ВУЗов одной из основных задач является продвижение их результатов на рынок, а именно: поиск схем и возможностей коммерциализации, привлечение инвесторов, организация высокотехнологичного бизнеса, создание конкурентной среды технологического предпринимательства. Именно при разработке инновационного проекта, решающее значение имеют возможности коммерциализации результатов НИОКР, основанные на проведенных маркетинговых исследованиях. В рамках данного проекта (техническая аспект) исследуются способы защиты металлических конструкций от коррозийных процессов и разрабатывается модель продвижения на рынок результатов исследования (предпринимательский аспект).', 2, '2023-09-01', '2024-05-30', 'requirements', 'Полынский И.В., соискатель ИрНИТУ', 'additional_inf', 'Эффективный алгоритм продвижения на рынок результатов НИОКР, осуществляемых в ИрНИТУ', 'способность обеспечения практического применения результатов научного исследования', NULL, 1, 1, 150, 2, 4, NULL, NULL, NULL, NULL),
(564, '2023-06-01 23:53:48', '2023-06-19 10:17:08', 'Предварительная оценка машинного времени обработки заготовительно-штамповочной оснастки', 15, 'Создание классификатора изделий по геометрическим особенностям, влияющим на машинное время обработки заготовительно-штамповочной оснастки, и вычисление соответствующих поправочных коэффициентов', 'Заготовительно-штамповочное производство в авиационной промышленности имеет немаловажное значение, так как листовая штамповка используется для изготовления многих деталей. Оснастка заготовительно-штамповочного производства уникальная для каждого изделия. Внесение изменений в конструкцию детали требует изменения модели оснастки и изготовления нового образца, часто в кратчайшие сроки. Внесение нового приоритетного изделия в цеховое расписание требует его перестроения, для чего необходимо знать машинное время. Традиционно, машинное время вычисляется при помощи встроенных функций Unigraphics NX, но для этого требуется написание управляющей программы, что занимает значительное время. Для повышения гибкости производства целесообразно применить метод предварительной оценки машинного времени на основе скорости удаления материала. Для более точного приближения результата к реальному необходимо ввести коэффициенты, учитывающие геометрические особенности изделия и динамические характеристики оборудования, что требует проведения экспериментальных исследований.', 2, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'Методика оценки машинного времени на основе классификатора изделий и скорости удаления материала, позволяющая в краткие сроки позволить предоставить данные по машинному времени для перестроения цехового расписания', 'Знания: виды продукции, выпускаемой в цехах изготовления заготовительно-штамповочной оснастки, методики оценки машинного времени.\nУмения: работа в среде Unigraphics NX, анализ геометрической информации.\nНавыки: поиск информации, анализ информации с целью выделения требуемого знания, формирование комплексного понимания предмета изучения на основе полученной информации, системный анализ полученной информации, выделение «дефицитов» знаний и формулирование запроса на поиск новой информации.', NULL, 1, 1, 347, 48, NULL, NULL, NULL, NULL, NULL),
(565, '2023-06-02 02:06:12', '2023-06-19 10:10:01', 'Технологии изготовления изделий из препрегов', 15, 'Разработка технологии изготовления изделия с использованием препрегов', 'Исследование и анализ существующих изделий из композиционных материалов. Разработка 3д модели изделия. Проектирование оснастки. Изготовление оснастки. Создание прототипа изделия.', 2, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'Прототип изделия', 'Навыки работы с композиционными материалами', NULL, 1, 1, NULL, 48, NULL, NULL, NULL, NULL, NULL),
(566, '2023-06-02 02:39:41', '2023-07-03 13:33:15', 'Проектирование норм взаимозаменяемости при конструировании типовых изделий машиностроительных производств', 15, 'Разработать методику расчета и произвести аналитические расчеты норм взаимозаменяемости при конструировании типовых изделий машиностроительных производств', 'Важнейшим показателем качества изделия в приборостроении и машиностроении является точность всех его составных частей, при этом точность изготовления деталей существенно влияет на функционирование изделия, его выходные характеристики, долговечность, надежность и др. показатели. Кроме того, современное производство отличается высокой производительностью, отдельные детали и узлы могут изготавливаться на разных заводах и даже в разных городах и странах. Такие возможности обеспечиваются наличием соответствующей документации, позволяющей обеспечить взаимозаменяемость, как отдельных деталей, так и изделия в целом. \nРабочие программы по дисциплине «Метрология, стандартизация и сертификация» охватывают изучение только взаимозаменяемости гладких цилиндрических соединений, резьбовых соединений с зазором, шероховатости поверхности, что не позволяет углубиться в изучение соединений, использующихся в конкретном направлении подготовки специалистов в области конструирования и проектирования машин и механизмов. Данный проект является логическим продолжением изучения дисциплины «Метрология, стандартизация и сертификация», устанавливающим взаимосвязь между общетехническими и специальными дисциплинами', 2, '2023-09-01', '2024-05-30', 'requirements', 'ФБУ \"Государственный региональный центр стандартизации, метрологии и испытаний в Иркутской области\"', 'additional_inf', 'Методические рекомендации и результаты аналитических расчетов: допусков и посадок подшипников скольжения; допусков и посадок с натягом; размерных цепей при конструировании изделий машиностроения; контролируемых параметров цилиндрических зубчатых передач; допусков и посадок конических соединений, а также комплект конструкторской документации, выполненный с использованием CAD/CAM/CAE систем', 'Знания действующих систем допусков и посадок типовых соединений деталей машин; принципов их построения и методик применения; методов и средств контроля размеров; правил оформления конструкторской и технологической документации\nУмения пользоваться стандартами, регламентирующими правила оформления конструкторской и технологической документации; правильно выбирать посадки в соответствии с конструктивными и техническими требованиями к деталям, узлам, механизмам; рассчитывать характеристики посадок; рассчитывать допуски размеров, входящих в размерные цепи; нормировать и давать обозначение отклонений формы, расположения, шероховатости поверхностей деталей; читать и обозначать на чертеже номинальные размеры, предельные отклонения, поля допусков, посадки;\nНавыки конструирования, проектирования, выполнения чертежей и расчетных схем с использованием CAD/CAM/CAE систем проектирования; систематизирования и анализа информации для дальнейшего продвижения, реализации полученных результатов  в конкретных изделиях', NULL, 1, 1, NULL, 33, 4, NULL, NULL, NULL, NULL),
(567, '2023-06-02 02:44:54', '2023-08-24 06:44:10', 'Оценка показателей производительности процесса и качества кромок на вершинах и торцах зубьев зубчатых колес после обработки абразивными инструментами', 15, 'опытная отработка методик и технологий определения оптимального инструмента и режимов обработки острых кромок на вершинах и торцах зубьев зубчатых колес и шестерней', 'Зубчатые колеса и шестерни широко используются в конструкциях современных машин, механизмов и устройств. Например, в тяговых передачах тягового подвижного состава магистральных железных дорог данные изделия являются важнейшими элементами конструкции, работоспособность которых необходимо постоянно повышать. В процессе изготовления данных изделий на торцах зубьев образуются острые кромки и заусенцы, которые ухудшают качество зацепления, вызывают повышенный уровень шума, снижают срок службы в результате скола острых кромок на зубьях. Таким образом, после изготовления зубчатых колес и шестерней, с острых кромок на вершинах и торцах зубьев необходимо снять фаски или выполнить скругления. \nУстановлено, что вышеописанные операции, как правило, выполняется вручную, что приводит к существенному увеличению трудоемкости их изготовления. Таким образом, необходимо внедрение в производство и ремонт зубчатых колес и шестерней механизированных/автоматизированных технологий обработки заусенцев и острых кромок, которому должно предшествовать решение ряда технологических задач, позволяющих обеспечить высокую производительность процесса обработки, а также выполнение всех требований к размеру, точности формы и качеству обработанных кромок', 2, '2023-09-01', '2024-05-30', 'requirements', 'Улан-Удэнский локомотивовагоноремонтный завод – филиал АО ЖЕЛДОРРЕММАШ', 'additional_inf', 'Технологические рекомендации по выбору инструмента и режимов обработки, позволяющие вести обработку острых кромок на вершинах и торцах зубьев с высокой производительностью и обеспечениям всех требований к качеству обработки', 'Знания показателей производительности процесса обработки и качества поверхностного слоя деталей, обработанных методами абразивной обработки, а также методы и средства объективного контроля данных показателей;\nУмения проводить комплекс необходимых экспериментальных исследований для определения основных показателей производительности процесса механической обработки и качества поверхностного слоя деталей;\nНавыки работ с использованием приборов и оборудования, необходимых для проведения исследований, а также использования программных продуктов для проведения необходимых расчетов и статистической обработки результатов экспериментов', NULL, 1, 1, NULL, 33, 4, 'Снижение контингента обучающихся, по указанным направлениям. Не более одного проект на преподавателя.', NULL, NULL, NULL),
(568, '2023-06-02 05:57:02', '2023-07-11 08:45:32', 'Информационное моделирование здания и инженерных систем Иркутского Государственного Цирка с применения BIM-технологий при проведении реконструкции по адресу: Иркутская область, г. Иркутск, Пролетарская ул., 13.', 15, 'Создание 3D-модели, которая в дальнейшем позволяла бы получить графический вид объекта, информацию по дизайну, размерам, материалам и другим характеристикам здания Иркутского городского Цирка, а также при необходимости вносить изменения и коррективы в процессе его жизненного цикла.', 'В результате выполнения проекта с использованием BIM-технологий на основе существующей проектной документации и результатов обследования конструкций здания будет выполнена визуализация объекта реконструкции Иркутского государственного цирка, расположенного по адресу: Иркутская область, г. Иркутск, Пролетарская ул., 13. Созданная информационная модель позволит осуществить планирование и координацию работ, обеспечит сопровождение, расчет объемов,  составление смет, сроков, BIM-координацию различных этапов выполнения работ, контроль и обеспечение качества, выявление конфликтов, составление документации и т. д.', 3, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'В результате выполнения проекта с использованием BIM-технологий на основе существующей проектной документации и результатов обследования конструкций здания и инженерных коммуникаций будет выполнена визуализация объекта реконструкции, расположенного по адресу: Иркутская область, г. Иркутск, Пролетарская ул., 13', 'Знания: по методам информационного моделирования и проектирования жизненного цикла зданий и инженерных коммуникаций. \nУмения: владение системами 3d-моделирования и создание 3d-моделей объектов недвижимости.\nНавыки: проектирования и моделирования, работы в команде.', NULL, 1, 1, NULL, 28, 4, NULL, NULL, NULL, NULL),
(569, '2023-06-02 06:11:38', '2023-07-27 06:40:47', 'Благоустройство территории Иркутского Государственного Цирка по адресу Иркутская область, г. Иркутск, Пролетарская ул., 13', 15, 'Создание комфортной и безопасной среды на территории Иркутского государственного цирка для комфортного пребывания посетителей объекта культурного развития', 'Согласно Стратегии развития до 2035 года создание безопасной и комфортной среды жизнедеятельности человека является важной задачей. Достижение соответствующего уровня комфортности и безопасности может  обеспечиваться засчет: разумной подготовки территорий, рационального размещения объектов общественного питания, парковок, парковых зон и т.д., создания удобной и безопасной дорожной инфраструктуры, включающей подъездные пути, и т.д. Рассмотреть все представленные аспекты, проанализировать их и разработать соответствующие рекомендации по благоустройству выбранной территории – основа представленного проекта.', 2, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'Проект с рекомендациями по благоустройству территории Иркутского государственного цирка', 'Знания: нормативно-законодательные аспекты отрасли Строительства, методы планирования, оптимизации, принятия решений\r\nУмения: разработки и принятия решений при решении задач Строительства с учетом всех ограничений и требований\r\nНавыки: исследования, анализа, планирования', NULL, 1, 1, NULL, 28, 4, NULL, NULL, NULL, NULL),
(570, '2023-06-02 06:21:04', '2023-07-11 08:50:47', 'Исследование индекса городской среды г. Иркутска и разработка мероприятий по ее развитию', 15, 'Для стратегического развития отрасли Строительства и Жилищно-коммунального хозяйства необходимо изыскать возможности наилучшим образом обеспечить устойчивый рост комфорта и безопасности среды жизнедеятельности (благоустройство, дороги, расположение объектов Строительства и т.д.).', 'Согласно Стратегии развития строительной отрасли и жилищно-коммунального хозяйства Российской Федерации до 2035 года создание безопасной и комфортной среды жизнедеятельности человека является важной задачей. Соответствующий уровень комфортности может  достигаться засчет рационального размещения объектов общественного питания, парковок, парковых зон и т.д., создания удобной и безопасной дорожной инфраструктуры и т.д. Анализ приведённых выше аспектов и разработка на их основе рекомендаций является сутью представленного проекта.', 2, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'Рекомендации по развитию комфортной городской среды г. Иркутска', 'Знания: нормативно-законодательные аспекты отрасли Строительства, методы планирования, принятия решений\nУмения: анализа нормативно-законодательной литературы в сфере Строительства, разработки и принятия решений по задачам Строительства\nНавыки: исследования, анализа, планирования, оптимизации, работа в группе', NULL, 1, 1, NULL, 28, 5, NULL, NULL, NULL, NULL),
(571, '2023-06-02 06:39:45', '2023-07-11 08:49:28', 'Проект автономных систем водоотведения туристических объектов прибрежной зоны озера Байкал', 15, 'Разработать рекомендации по созданию автономных систем водоотведения для туристических объектов, находящихся в зоне береговой линии озера Байкал', 'Байкал - это уникальное озеро Земли с 20% мирового запаса пресной питьевой воды. Объект всемирного наследия ЮНЕСКО. Сохранение чистоты этого уникального объекта должно являться первоочередной задачей. В настоящее время человеческая деятельность на прибрежной территории Байкала привела к глобальным проблемам. Одна из них - системы водоотведения (канализационные стоки). К 2024 году в Иркутской области и Республике Бурятия по нацпроекту «Экология» планируется реконструировать и построить около 40 очистных сооружений, которые находятся на берегу самого Байкала или связаны с впадающими в него реками. Рассмотреть варианты автономных систем водоотведения для туристических объектов и выполнить анализ эффективности их применения является основой данного проекта.', 3, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'Проект автономной системы водоотведения', 'Навыки проектирования, анализа результатов, принятия решений, разработки рекомендаций.', NULL, 1, 1, NULL, 28, 5, NULL, NULL, NULL, NULL);
INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(572, '2023-06-02 12:29:41', '2023-06-03 14:23:27', 'Исследование проблем прочности деталей, изготовленных с применением цифровых производственных технологий', 15, 'Разработать и отладить методики экспериментальных исследований характеристик прочности и жёсткости деталей, «выращенных» с помощью 3D – печати, опираясь на натурные испытания и на цифровую среду', '3d-печать позволяет получать детали практически любой геометрической формы и габаритов. В противовес традиционным вычитающим и формообразующим технологиям с помощью 3d-печати деталь «выращивают». Однако при этом не ясно как рассчитывать на прочность такие детали. Потому что для этого необходимо знать, как на прочность влияют свойства материала печати, параметры печати, шаблон печати, процент заполнения материалом детали и т.д. Ответы на эти вопросы можно получить, научившись работать на 3D-принтере; изучив поведение напечатанных деталей под действием нагрузок. Для изучения поведения деталей нужны натурные и численные эксперименты, показывающие зависимость прочности и жёсткости детали от нагрузки. Для натурных экспериментов надо разработать и испытать на специальном оборудовании образцы. Численные эксперименты требуют формирования адекватных моделей в CAD/CAE – системах (Femap, ANSYS, FIDESYS, Siemens NX, КОМПАС-3D, и др.). Под «адекватными моделями» понимаются модели, которые достоверно отображают в цифровой среде поведение реальной детали под действием реальной нагрузки. В частности, необходимо построить в цифровой среде модель натурных испытаний напечатанных образцов.', 2, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', '1. Образцы для экспериментальных исследований характеристик прочности и жёсткости деталей, «выращенных» с применением 3D-печати. 2. Проанализированные результаты натурных испытаний образцов. 3. CAE модели для оценки в цифровой среде характеристик прочности и жёсткости исследуемых объектов.', 'проведение натурных экспериментов для определения характеристик прочности и жёсткости, обработка их результатов; построение цифровых моделей исследуемых деталей в CAD/CAE - системах', NULL, 1, 1, 339, 31, 4, NULL, NULL, NULL, NULL),
(573, '2023-06-02 13:34:51', '2023-07-11 08:41:49', 'Проект городской набережной', 15, 'Разработать проект набережной в структуре городской среды', 'Прибрежные зоны являются одними из наиболее востребованных территорий для формирования ландшафтно-рекреационного комплекса города. Проектирование набережных связано с решением целого ряда функциональных, планировочных, архитектурных, ландшафтно-экологических и инженерных аспектов проектирования.\nОсновными задачами проекта являются:\n- анализ теоретического и практического опыта ландшафтно-экологического проектирования и ландшафтного урбанизма на примере городских набережных;\n- разработка концепции развития набережной в структуре городской среды;\n- разработка архитектурно-планировочных приемов организации городской набережной с учетом функциональных, ландшафтно-экологических, эстетических и инженерных особенностей территории.', 3, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'Разработать проект городской набережной', 'знание  архитектурно-планировочных, ландшафтно-экологических и инженерных основ проектирования городских набережных', NULL, 1, 1, NULL, 23, NULL, NULL, NULL, NULL, NULL),
(574, '2023-06-02 13:48:43', '2023-06-06 09:41:44', '3D-печать: исследование и разработка процессов изготовления деталей машин с заданными характеристиками', 15, 'Разработать и отладить технологию 3d-печати машиностроительной детали таким образом, чтобы её механические и технические характеристики отвечали заданным требованиям.', 'В противовес традиционным вычитающим и формообразующим технологиям технология 3d-печати деталь «выращивает». Поэтому 3d-печать позволяет получать детали практически любой геометрической формы и габаритов. Появилась возможность трансформации сборочной единицы в деталь. Весь этот процесс определяется 3d-моделью изготавливаемой детали; программой, управляющей процессом печати детали (загрузка 3d-модели, управление настройками печати: температурный и скоростной режимы; шаблон печати; процент заполнения, направление печати, толщина слоя и т.д.); техническими характеристиками принтера; физико-механическими характеристиками материала печати. Всеми этими параметрами можно управлять, а значит можно получить деталь с заданными геометрическими и физико-механическими характеристиками. Для этого необходимо отработать широкий спектр значений данных параметров на конкретном 3d-принтере, то есть разработать оптимальную технологию изготовления детали.', 2, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'Деталь с заданными характеристиками, созданная по отработанной технологии 3d-печати', 'работать на 3d-принтере; настраивать параметры печати с помощью ПО 3d-принтера; формировать ТЗ на деталь; оценивать параметры полученной детали относительно установленных требований', NULL, 1, 1, NULL, 31, 4, NULL, NULL, NULL, NULL),
(575, '2023-06-05 00:23:19', '2023-06-22 04:53:21', 'Разработка сервиса для создания интеллектуальных систем поддержки принятия решений', 15, 'Создание веб-сервиса построения интеллектуальных систем поддержки принятия решений, использующих формализмы продукций и прецедентов', 'Проект посвящен разработке веб-ориентированного сервиса для создания интеллектуальных систем поддержки принятия решений, использующих классические формализмы представления знаний, такие как продукции и прецеденты. В рамках сервиса будут разработаны подсистемы: визуального моделирования продукций и прецедентов; модули трансформации (конвертации) концептуальных моделей; подсистемы интерпретации разработанных баз знаний; и создания интеллектуальных систем поддержки принятия решений в форме веб сервисов (с графическим и программным интерфейсом), чат-ботов и голосовых ассистентов.\nОсновная идея проекта – создание инструментария реализующего принципы модельно-ориентированного подхода и трансформаций в контексте разработки интеллектуального программного обеспечения.\nИмеется задел по проекту в форме отдельных веб-ориентированных и настольных редакторов и программ оболочек, разработанных в рамках научных проектов ИДСТУ СО РАН.', 2, '2023-09-01', '2024-05-30', 'requirements', '-', 'additional_inf', 'Веб сервис для создания интеллектуальных систем поддержки принятия решений, включающий отдельные модули для представления, конвертации и интерпретации концептуальных моделей и баз знаний.', 'Программирование на языке Python и PHP, формирование тестовых и обучающих выборок, проведение тестов производительности, взаимодействие в команде разработчиков, составление документации', NULL, 1, 1, NULL, 59, 4, NULL, NULL, NULL, NULL),
(576, '2023-06-05 01:16:22', '2023-06-19 03:18:18', 'Методы увеличения нефтеотдачи', 15, 'Целью проекта является повышение технико-экономической эффективности добычи\nУглеводородов', 'В процессе выполнения проекта , будет предложен и обоснован выбор методов увеличения нефтеизвлечения МУН (выбор агента вытеснения, способ доставки, метод закачивания, оптимальная схема размещения скважин для реализации воздействия)', 2, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'Разработка МУН с оптимальными характеристиками', 'будут получены знания в области разработки и эксплуатации нефтяных месторождений\nУмения: получены умения поиска реализуемых на практике способов повышения эффективности МУН\nНавыки: в области управления добычей углеводородов на завершающих стадиях эксплуатации с применением современных технологий', NULL, 1, 1, 414, 18, 5, NULL, NULL, NULL, NULL),
(577, '2023-06-05 04:08:38', '2023-06-06 09:43:06', '3D-печатная технологическая оснастка для выкладки композиционных материалов', 15, 'Разработать технологию и изготовить прототип 3D-печатнойтехнологической оснастки  для выкладки композиционных материалов (с использованием робот Kuka, шнековый экструдер F2 Pellet, фрезерный станок с ЧПУ Beaver)', 'В ходе проекта будет проведен анализ технологического оснащения для изготовления изделий из композиционных материалов, выявлены преимущества и недостатки такого оснащения из металлов и неметаллов. Будет выбран тип оснастки на которой технологические преимущества 3D-печатной оснастки наиболее выражены и экономически оправданы. Будет разработана модель технологической оснастки в программной среде Siemens NX. Изготовление оснастки будет произведено методом 3D-печати с использованием робота Kuka, высокопроизводительного шнекового экструдера  F2 Pellet для FDM печати и фрезерного ЧПУ станка Beaver для чистовой обработки. По результатам изготовления будут подготовлены технологические рекомендации. На полученной оснастке будет произведено изготовление пробной детали из композиционного материала.', 2, '2023-09-01', '2024-05-30', 'requirements', 'ООО «Инжиниринговый центр «Политех-Иркут»', 'additional_inf', 'Прототип 3D-печатной технологической оснастки  для выкладки композиционных материалов и технологические рекомендации по ее изготовлению', 'Командная работа, технология 3D печати методом FDM, технология фрезерной обработки на станке с ЧПУ, технология изготовления деталей из композиционных материалов', NULL, 1, 1, NULL, 48, 4, NULL, NULL, NULL, NULL),
(578, '2023-06-05 04:17:03', '2023-06-19 10:11:50', 'Изучение свойств  материалов масляных фильтров\nИзучение свойств  фильтрующих материалов применяемых в масляных фильтрах', 15, 'Разработка методики исследования свойств материалов и определение (Изучение) качеств материалов масляных фильтров', 'В рамках международных стандартов к масляным фильтрам предъявляется немало требований: Фильтрующие элементы к ним должны соответствовать требованиям настоящего стандарта и конструкторской документации (КД), утвержденной в установленном порядке. Полнота отсевов фильтров и фильтрующих элементов должна быть не менее 25 %. Зависимость тонкости отсева от полноты ГОСТ Р 53844—2010 4.3 Ресурс фильтрующего элемента до замены (для 1 категории условий эксплуатации) по ГОСТ 21624 устанавливают в руководстве (инструкции) по эксплуатации автомобиля, при этом он должен быть не менее 250 ч работы двигателя. Гидравлическое сопротивление фильтрующего элемента и перепускного клапана, определяемое из их гидравлических характеристик при заданном расходе масла, должно быть не больше значения, указанного в КД. Фильтрующий элемент должен выдерживать без разрушения повышенный перепад давления (АР), равный не менее 2,0 АР начала открытия перепускного клапана фильтра. Фильтры должны выдерживать без нарушения давление не менее 3 Рном. Давление начала открытия перепускного клапана должно находиться в пределах, установленных требованиями КД. Фильтрующие элементы должны быть вибростойкими к пульсации давления и сохранять работоспособность при температурах от минус 50 °С до плюс 135 °С. Фильтрующие элементы, их уплотнения и другие детали должны быть масло-, бензо-, водостойкими. Материалы, используемые для изготовления фильтров и их элементов, не должны выделять в поток фильтруемого масла составляющих компонентов. \nВ наше время, существует множество различных брендов фильтрующих материалов, обладающих различными свойствами, но не все отвечающие определенным требованиям. Поэтому для различных типов машин работающих в различными средах и на различных режимах, требуются фильтрующие элементы отвечающие определенным требованиям.\nПоэтому существует проблема- подбор фильтрующего элемента отвечающего определенным требованиям.', 2, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'Полученные результаты исследования позволят правильно подбирать фильтрующий элемент для определенного вида оборудования', 'Знания: методология исследования\nУмения: исследовать свойства фильтрующего материала\nНавыки: правильно подходить к выбору фильтрующего элемента', NULL, 1, 1, 33, 16, 4, NULL, NULL, NULL, NULL),
(579, '2023-06-05 04:22:56', '2023-06-14 06:30:53', 'Исследование смазывающих свойств нефтепродуктов', 15, 'Изучение смазывающих свойств нефтепродуктов и разработка методики исследования смазывающих свойств нефтепродуктов', 'Все знают, что смазочные материалы изменяют свои характеристики в процессе работы, так как оно подвергается высокому давлению, температуре и многим другим факторам. На сегодняшний день производство смазочных материалов происходит одновременно с совершенствованием машин. В связи с современной тенденцией понижения выбросов вредных веществ в окружающую среду, а также экономии смазочных материалов выдвигают жесткие требования к качеству смазочных материалов.\nСмазочные материалы в машинах выполняют множество ролей: уменьшение и защиту от сухого трения, защита от возникновения коррозии, за счет антикоррозионных присадок, охлаждение трущихся деталей и вывод продуктов износа.\nВ наше время, существует множество различных брендов смазочных материалов, обладающих различными противозадирными и противоизносными свойствами. Поэтому для различных типов машин с различными свойствами среды, подходят разные виды смазочных материалов с разными присадками.\nПоэтому существует проблема – снижение износа поверхностей, подвергающихся трению и нагрузкам. Это позволит продлить срок эксплуатации деталей механизмов, сделает их более долговечными и надежными. В ряде случаев смазки применяются не только для снижения износа, но  и для предотвращения трения и заклинивания смежных поверхностей. Благодаря своей пластичности и составу эти мазки защищают от проникновения агрессивных веществ, газов и паров. Также практически все консистентные смазки отличаются антикоррозионными свойствами и т.д. Необходимо расширять сырьевую базу и увеличивать рабочий диапазон применения пластичных смазок.', 2, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'Масла, пластичные смазки, топлива с заданными смазывающими свойствами. Позволит расширить характеристики данных нефтепродуктов.', 'Знания: методология исследования\nУмения: исследовать свойства нефтепродуктов\nНавыки: правильно подходить к выбору гсм', NULL, 1, 1, NULL, 16, 4, NULL, NULL, NULL, NULL),
(580, '2023-06-05 04:23:06', '2023-06-19 10:14:03', 'Совершенствование методики расчета цены муниципального контракта при осуществлении закупок в сфере регулярных перевозок пассажиров на примере г. Иркутска', 15, 'Совершенствование методики расчета начальной (максимальной) цены контракта (НМЦК), а также цены контракта, заключаемого с единственным поставщиком (подрядчиком, исполнителем), для закупок в сфере регулярных перевозок пассажиров на основе учета технико-эксплуатационных параметров маршрутов перевозчика, а также создание соответствующего программного продукта', 'Государственные закупки являются важным инструментом в регулировании экономики и социальной политики государства. В сфере закупок существует такое понятие как обеспечение, то есть ответственность за результат, это один из принципов 44-ФЗ. Заказчику нужны гарантии, т.е. он должен быть уверен, что победитель торгов подпишет контракт и самое главное выполнит его с соблюдением всех условий. Начальная (максимальная) цена контракта (НМЦК) — это предельное значение цены, которое указывается в извещении и документации о проведении закупки с приглашением принять в ней участие. Заказчик обязан в полной мере обосновать цену, чтобы провести закупку. Менять условия уже заключенного контракта в большинстве случаев нельзя. Но очень часто при проведении расчета НМЦК возникают проблемы. Первое, цена может быть занижена. Это может привести к тому, что процедура закупки просто не состоится, так как никто не будет заключать контракт себе в убыток. Если такой контракт все-таки будет заключен, то это будет недобросовестный перевозчик, который не выполнит условия контракта по заявленной цене, либо будет занижено качество поставляемого товара, или предоставляемых услуг. Второе, может возникнуть ситуация, когда НМЦК, наоборот, будет завышена. Это в свою очередь приведет к неэффективному расходу средств бюджета. Третье, стоимость устанавливается некорректно, из-за технических проблем (ошибок в расчетах; неправильном использовании положений методических рекомендаций; ошибок при анализе рынка, когда он проанализирован не полностью; использовании некорректных исходных данных). Из-за вышеперечисленных проблем для того, чтобы составить заказ, привлекаются эксперты или экспертные организации. Здесь стоит учесть, что ими не могут быть работники, которые работали на заказчика последние два года, или люди, которые заинтересованы в заключении контракта, и так же ими не могут быть физические или юридические лица, на решения которых могут повлиять заказчик или поставщик. Т.е. специалистов по расчету НМЦК найти сложно из-за большого количества исходных данных, громоздких расчетов и постоянно обновляющихся методик. \nВ ИРНИТУ на кафедре «Автомобильного транспорта», есть опыт в этом вопросе и соответственно работа над данным проектом позволит  студенту  стать экспертом в данном вопросе. Разработка  же методики, а также соответствующего программного обеспечения позволит быстро и качественно произвести расчет НМЦК для любого регулярного маршрута, выставленного на торги (со всей необходимой исчерпывающей документацией, справочной информацией и программным продуктом).', 3, '2023-09-01', '2024-05-30', 'requirements', 'ООО « ПАССАЖИРСКИЕ АВТОБУСНЫЕ ПЕРЕВОЗКИ»', 'additional_inf', 'Отчет и программный продукт с исходными данными по регулярным маршрутам для муниципальных властей по расчету начальной (максимальной) цены контракта, а также цены контракта, заключаемого с единственным поставщиком (подрядчиком, исполнителем), для закупок в сфере регулярных перевозок пассажиров', 'Знания: характеристик подвижного состава и методики расчета и технико-эксплуатационных показателей на регулярных маршрутах.\nНавыки: проведения обследования пассажиропотоков и расчёта технико-эксплуатационных показателей на регулярных маршрутах; владения методикой обработки результатов исследования; составления базы данных по результатам обследования пассажиропотоков и разработки программного продукт; владения методикой расчёта НМЦК', NULL, 1, 1, NULL, 30, 4, NULL, NULL, NULL, NULL),
(581, '2023-06-05 06:39:16', '2023-07-03 02:33:56', 'Виртуальная химическая лаборатория', 15, 'Разработка современной виртуальной лаборатории для дистанционного электронного обучения по дисциплине «Общая химическая технология»', 'Лабораторные работы являются обязательным разделом учебной дисциплины \"Общая химическая технология\" и предназначены для закрепления теоретических разделов, излагаемых в лекциях. Математическое моделирование химико-технологических процессов является научно-методической основой изучения курса, и потому лабораторные работы могут быть представлены как вычислительный (компьютерный) эксперимент, предназначенный для развития навыка исследования и анализа химико-технологического процесса. Для этой цели необходима разработка проблемно-ориентированной программы для автоматизации сложных вычислений, причем интеллектуальная нагрузка по постановке задачи и анализа результатов исследования процессов должна  быть перенесена на обучающегося. Лабораторные работы по данной дисциплине могут быть релизованы в результате с помощью дистанционных образовательных технологий', 2, '2023-09-01', '2023-12-30', 'requirements', NULL, 'additional_inf', 'Виртуальная лаборатория для выполнения лабораторных работ по дисциплине «Общая химическая технология» для дистанционного обучения', 'Знать основы языка программирования Phyton, закономерности протекания простых и сложных химических реакций\nУметь алгоритмизировать решение задач в области расчета химического равновесия\nВладеть программными средствами Phyton для реализации полученного расчетного алгоритма', NULL, 1, 1, NULL, 3, 3, NULL, NULL, NULL, NULL),
(582, '2023-06-05 07:54:58', '2023-06-19 10:15:15', 'Разработка проекта мониторинга транспортного поведения населения на примере г. Иркутска', 15, 'Разработка методики оценки качества транспортного обслуживания населения на основе количественных и качественных\nпараметров транспортного поведения населения', '1. Определение целей и задач проекта: определение основных вопросов, которые должен решать проект мониторинга, например, оценка потребности в транспорте, анализ проблем дорожного движения и т.д.\n\n2. Определение методов сбора данных: выбор методов сбора информации, которые будут использоваться в различных жизненных ситуациях, например, технологии GPS, камеры наблюдения, опросы и т.д.\n\n3. Проектирование системы хранения и обработки данных: создание структуры базы данных и выбор подходящего программного обеспечения для обработки и анализа данных.\n\n4. Планирование мероприятий по сбору данных: определение периодичности сбора данных, создание расписания мониторинга и выбор мест, где будут устанавливаться камеры или проводиться опросы.\n\n5. Анализ результатов: обработка данных, определение трендов и анализ изменений в транспортном поведении населения.\n\n6. Разработка рекомендаций: на основе полученных результатов проекта создаются рекомендации по улучшению транспортной системы и управления дорожным движением.\n\n7. Внедрение изменений: внедрение предложенных рекомендаций в работу транспортной системы.', 2, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'Методика оценки качества транспортного обслуживания населения на основе количественных и качественных\nпараметров транспортного поведения населения', 'Знания характеристик транспортного поведения населения г. Иркутска, инструментария\nмониторинга транспортного поведения населения. Умения анализировать количественные\nпараметры транспортного поведения населения. Навыки обработки результатов исследования', NULL, 1, 1, 329, 30, NULL, NULL, NULL, NULL, NULL),
(583, '2023-06-05 08:02:16', '2023-06-19 03:15:36', 'Горные инновации', 15, 'Создание адаптированных моделей горношахтного и карьерного оборудования и написание сценариев, пригодных для дальнейшей работы в среде VR Concept.', 'Технологии виртуальной и дополненной реальности сегодня могут быть успешно использованы не только в индустрии развлечений, где уже прочно закрепились, но и для обучения сотрудников в различных отраслях деятельности человека. Повсеместное внедрение виртуальных тренажеров в обучение персонала может сделать обучение более эффективным, а производство - экономнее, производительнее и точнее. \nРазвитие компетенций в области инновационных технологий позволит студентам-горнякам занять лидирующие позиции в современном мире технологичного производства.\nУчастникам проекта будет предложена технология создания тренажеров с настраиваемыми режимам и сценариями с использованием платформы VR Concept, которая позволяет ускорить процесс разработки цифрового двойника за счет наличия заранее реализованных общих модулей и визуального языка программирования. В ходе реализации проекта, студентам предстоит работа над детальной проработкой сценариев взаимодействия элементов горных машин и оборудования в виртуальной среде, что позволит пользователю VR тренажёра интерактивно взаимодействовать с объектом и в полной мере ощутить масштаб данного проекта при помощи VR технологий.', 3, '2023-09-01', '2023-12-30', 'requirements', 'ИИТиАД, Говорков А.С.', 'additional_inf', 'Созданы подробные модели ГМиО, написаны детальные сценарии логического взаимодействия элементов конструкций машин, пригодные для дальнейшей работы в среде VR Concept.', 'Знания процесса моделирования элементов горных машин при помощи пакетов специализированных  программ. Освоение возможностей инструмента VR технологий, для работы с виртуальными цифровыми прототипами .', NULL, 1, 1, NULL, 21, 1, NULL, NULL, NULL, NULL),
(584, '2023-06-05 08:27:22', '2023-09-05 03:52:00', 'Модель управления портфелем образовательных программ магистратуры ИРНИТУ', 15, 'Разработать модель управления портфелем образовательных  программ магистратуры в ИРНИТУ  с целью установления приоритетов, оптимального распределения ресурсов и достижения  университетом стратегических целей', 'Модель управления портфелем образовательных программ - это механизм, который позволит идентифицировать и категоризировать образовательные программы магистратуры, реализуемые университетом. Даст возможность расставлять приоритеты и балансировать портфель образовательных программ. Даст инструменты управления программами и возможность контроля выполнения поставленных задач, с целью достижения университетом стратегических целей.', 2, '2023-09-01', '2024-05-30', 'requirements', 'Центр образовательных программ магистратуры и аспирантуры ИРНИТУ, Ю.Ю.Помернюк', 'additional_inf', 'Механизм управления портфелем образовательных программ магистратуры ИРНИТУ', 'способность идентифицировать «жизнеспособные» группы образовательных программ в контексте  стратегических целей университета;\r\nумение находить и устранять противоречия между направлениями образовательных программ;\r\nумение устранять противоречия между ресурсами и приоритетами при формирования портфеля образовательных программ', NULL, 8, 1, NULL, 38, 1, 'Уменьшение количества проектов в институте на 2023-2024 уч. год', NULL, NULL, NULL),
(585, '2023-06-05 10:25:11', '2023-06-14 06:31:50', 'Разработка аппаратного комплекса для задания тестовых режимов при исследовании динамических характеристик автомобильных шин', 15, 'Создание аппаратного комплекса для задания тестовых режимов: угла увода шины, тормозного момента и нормальной нагрузки на испытуемое колесо при исследовании динамических характеристик автомобильных шин', 'Для верификации математических моделей автомобильных шин, а также обеспечения возможности проектирования перспективных конкурентоспособных шин с заданными эксплуатационными свойствами необходимы фактические данные их выходных динамических характеристик. Эти характеристики могут быть получены при помощи дорожных или стендовых испытаний, и отражают сцепные свойства шин, сопротивление уводу, сопротивление качению и прочие данные. Для получения информативного и оперативного результата испытания необходимо сформировать комплекс тестовых воздействий при проведении экспериментального исследования шин, а также спроектировать и изготовить задающее эти воздействия оборудование.', 3, '2023-09-01', '2024-05-30', 'requirements', 'ООО НТЦ \"Интайр\"', 'additional_inf', 'Трёхмерные модели механизмов комплекса; конструкторская документация; работоспособный опытный образец; результаты поискового эксперимента динамических характеристик шин, полученных стендовым методом.', 'Знания: устройства и принципа работы современных систем активной безопасности КТС; устройства и принципов работы дополнительного технологического и испытательного оборудования; рациональных методов эффективной эксплуатации, а также технологических процессов поддержания и восстановления работоспособности подвижного состава автотранспортных средств, их агрегатов, механизмов, узлов.\nУмения: разрабатывать структурные и кинематические схемы систем технологического и испытательного оборудования; проводить диагностирование и контроль технического состояния систем подвижного состава автотранспортных средств.\nНавыки: проведения испытаний электронных систем КТС; проведения контроля технического состояния и диагностики подвижного состава автотранспортных средств, их агрегатов, механизмов, узлов.', NULL, 1, 1, NULL, 30, 4, NULL, NULL, NULL, NULL),
(586, '2023-06-05 10:39:47', '2023-07-03 02:17:42', 'Разработка функциональных пищевых продуктов с использованием пектина соевой шелухи', 15, 'Разработка принципиальной схемы производства функциональных пищевых продуктов с использованием пектина соевой шелухи', 'При  получении соевого масла на Иркутском МЖК отходами производства являются семенные оболочки бобов. По литературным данным в них содержатся ценные пектиновые вещества ( до 10% ). В ходе работы над проектом планируется определить содержание пектина в семенной оболочке сои, подобрать эффективную технологию их выделения, предложить направления дальнейшего использования. Разработать рецептуру и получить лабораторный образец функциональных пищевых продуктов с использованием пектина соевой шелухи.', 1, '2023-09-01', '2023-12-30', 'requirements', 'Иркутский масложиркомбинат', 'additional_inf', 'Принципиальная схема производства,   рецептура и лабораторный образе', 'Умение ориентироваться в нормативной документации, работать с технической литературой, химической посудой, лабораторным оборудованием. Уметь определять круг задач и решать их в соответствии со своей ролевой позицией', NULL, 1, 1, NULL, 43, 6, NULL, NULL, NULL, NULL),
(587, '2023-06-06 01:45:41', '2023-06-19 03:18:16', 'МОДЕЛЬ РАБОТЫ НЕФТЯНОЙ СКВАЖИНЫ  НА ОСНОВЕ ТЕОРИИ МАССОВОГО ОБСЛУЖИВАНИЯ', 15, 'Создание  цифровой модели нефтяной скважины', 'Для определения оптимальной рабочей точки нефтяных скважин сопоставляют производительность  нефтеносного коллектора с производительностью скважинного оборудования. Таким образом, скважина может рассматривается как \"узел обслуживания\",  подобно  регулируемому перекрестку - где роль светофора будет выполнять станция управления УЭЦН. Таким образом, имеется возможность оптимизировать работу нефтяных скважин  опираясь на существующую теорию массового обслуживания и оптимизацию функционирования улично-дорожных сетей (УДС).', 3, '2023-09-01', '2023-12-30', 'requirements', 'ООО \"ИНК\"', 'additional_inf', 'Создание цифровой модели работы нефтяной скважины на основе узлового анализа.', 'Моделирование сложных гидродинамических систем.', NULL, 1, 1, NULL, 18, 5, NULL, NULL, NULL, NULL),
(588, '2023-06-06 03:59:59', '2023-07-03 13:28:03', 'Анализ технологичности детали-дроссель с использованием CAD/CAM/CAE систем проектирования.', 15, 'Разработать технологическую карту. Выявить причины выбраковки большого количества деталей при их изготовлении,провести анализ назначенных параметров контроля качества.', 'Предложенный к разработке проект позволит провести анализ существующего технологического процесса изготовления детали. При производстве и последующем прохождении детали нормоконтроля примерно из 10 штук  выбраковывается 8, необходимо выявить причины этой выбраковки. \nПроработка процесса технологической подготовки требует тщательного изучения геометрии детали, технологического оборудования, методов и способов контроля качества. Работа над этим проектом позволит реализовать свои имеющиеся профессиональные знания и приобрести новые умения и навыки в поиске решений поставленной задачи.', 1, '2023-09-01', '2024-05-30', 'requirements', 'ИАЗ-ПАО \"Корпорация\"Иркут\"', 'additional_inf', 'Технологическая карта.\n3-Д модель детали.\nМетодические рекомендации по назначению параметров контроля качества детали.', 'анализа технологичности детали, работы с контрольно измерительными приборами и инструментами, создания 3-Д модели детали с натурного образца.', NULL, 1, 1, NULL, 33, 4, NULL, NULL, NULL, NULL),
(589, '2023-06-06 04:34:20', '2023-07-03 02:27:30', 'Организация безопасного производства при переработке соевых бобов', 15, 'дать обучающимся возможность приобрести востребованные практико-ориентированные знания, умения, навыки в организации безопасного производства по переработке соевых бобов', 'Для обеспечения качества и безопасности продуктов питания необходимо знать и уметь определять факторы, оказывающие влияние на безопасность готовой продукции, зависимость этих факторов от применяемого сырья, технологии, оборудования и упаковки. Применение специальных систем качества и безопасности пищевой продукции позволяет управлять рисками пищевой безопасности внутри производства и обеспечивать сохранение здоровья потребителя.', 2, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'Разработаны мероприятия по внедрению системы ХАССП для технологического производства по переработке соевых бобов', 'навыки разработки мероприятий по организации безопасного производства для конкретного пищевого продукта', NULL, 1, 1, NULL, 43, NULL, NULL, NULL, NULL, NULL),
(590, '2023-06-06 04:51:18', '2023-07-03 02:27:27', 'Организация безопасного производства при переработке плодоовощного сырья', 15, 'Дать обучающимся возможность приобрести востребованные практико-ориентированные знания, умения, навыки в организации  безопасного производства по переработке плодоовощного сырья', 'Для обеспечения качества и безопасности продуктов питания необходимо знать и уметь определять факторы, оказывающие влияние на безопасность готовой продукции, зависимость этих факторов от применяемого сырья, технологии, оборудования и упаковки. Применение специальных систем качества и безопасности пищевой продукции позволяет управлять рисками пищевой безопасности внутри производства и обеспечивать сохранение здоровья потребителя', 2, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'Разработаны мероприятия по внедрению системы ХАССП для технологического производства по переработке плодоовощного сырья', 'Навыки организации безопасного технологического производства на примере конкретного пищевого продукта', NULL, 1, 1, 451, 43, NULL, NULL, NULL, NULL, NULL),
(591, '2023-06-06 05:14:55', '2023-06-30 07:35:42', 'Разработка, проектирование механизмов поворота планетарного типа.', 15, 'Разработать конструкторскую документацию механизма поворота планетарного типа.', 'Необходимость работы над темой данного проекта продиктована реальными заявками на разработку механизмов такого типа в рамках импортазамещения.  Механизмы поворота планетарного типа широко используются в строительно-дорожной технике, но имеют особенности проектирования на стадии проработки конструкторской документации. На сегодняшний день производителям нужны рабочие чертежи, в рамках учебного процесса у студентов появится возможность реализовать свои полученные профессиональные знания.', 2, '2023-09-01', '2024-05-30', 'requirements', 'АО \"Клинцовский автокрановый завод\"', 'additional_inf', 'Пакет конструкторской документации, рабочие и сборочные чертежи механизма поворота планетарного типа.', 'навыки проектирования кинематических схем планетарных зубчатых механизмов, навыки разработки 3Д-моделей с последующим оформлением технической документации.', NULL, 1, 1, NULL, 33, 4, NULL, NULL, NULL, NULL),
(592, '2023-06-06 08:59:27', '2023-08-30 07:21:42', 'Электро-путь: создание модели линии электропередач', 0, 'разработка и создание реальной модели линии электропередач, которая позволит проводить эксперименты, а также обучение специалистов в области энергетики.', 'Проект \"Электро-путь\" направлен на создание физической модели опоры линии электропередач. \nКоманда проектирует и моделирует систему передачи электроэнергии, используя различные материалы и инструменты. \nТакже разрабатывается описательная часть модели.  \nКоманда тестирует и анализирует результаты экспериментов, используя знания основ электротехники и энергетики.\nПроект \"Электро-путь\" имеет большое значение для образовательных и научных целей, так как он позволяет студентам и ученым изучать и понимать принципы работы линий электропередач и электроэнергетических систем в целом. Кроме того, результаты проекта могут быть использованы для разработки новых технологий и улучшения существующих систем передачи энергии.', 1, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'Физическая модель ЛЭП', '1. Навыки проектирования и моделирования ЛЭП.\n2. Умение работать с различными материалами и инструментами для создания физической модели.\n3. Опыт работы в команде и умение эффективно взаимодействовать с коллегами.\n4. Навыки тестирования и анализа результатов.\n5. Знание основ электротехники и энергетики.\n6. Навыки презентации и коммуникации для демонстрации результатов проекта.', NULL, 8, 1, NULL, 6, NULL, NULL, NULL, NULL, NULL),
(593, '2023-06-06 11:18:14', '2023-07-03 02:16:24', 'Разработка комплекса практических работ в области автоматизации технологических процессов на базе оборудования TREI', 15, 'Разработка комплекс практических работ для формирования компетенций в области автоматизации технологических процессов', 'Проект предназначен для  разработки комплекса практических работ, который будет включать в себя  как  техническую составляющую так и  программную по работе с оборудованием TREI. Студенты начнут формировать свои прикладные навыки в сфере автоматизации на более ранних стадиях.  Тfк же студенты позволят сформировать перечень работ, которые были бы интересны для им для рассмотрения и для реализации.', 2, '2023-09-01', '2024-05-30', 'requirements', 'ООО \"Газпром добыча Иркутск\"', 'additional_inf', 'Комплекс практических работ', '-Работа с техническими средствами  автоматизации TREI\n-Работа с программным обеспечением Unimod PRO\n-Оформление документации', NULL, 1, 1, NULL, 2, 4, NULL, NULL, NULL, NULL),
(594, '2023-06-07 03:03:11', '2023-07-02 04:22:08', 'Использование концепции энергетического хаба и потоковых методов в интегрированных энергетических системах', 15, 'Цель проекта заключается в разработке и реализации интегрированных энергетических систем, основанных на концепции энергетического хаба и потоковых методов.', 'В рамках проекта будет проведен анализ и оценка эффективности использования различных источников энергии в интегрированных энергетических системах, оптимизация использования энергии в различных отраслях экономики, а также управление и контроль работы интегрированных энергетических систем. \n\nТакже будет произведен анализ экологических показателей работы интегрированных энергетических систем, включая снижение выбросов парниковых газов и негативного воздействия на окружающую среду. \n\nВ рамках проекта будут использоваться новейшие технологии и оборудование для производства и распределения энергии, включая возобновляемые источники энергии. \n\nЦелью проекта является разработка интегрированной энергетической системы, которая будет обеспечивать эффективное использование различных источников энергии, снижение выбросов парниковых газов и негативного воздействия на окружающую среду, а также удовлетворение потребностей отраслей экономики и населения в энергии.', 2, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'описание существующих систем энергоснабжения в регионах. Разработанные варианты использования интегрированных систем энергоснабжения.', '1. Навыки проектирования и разработки интегрированных энергетических систем, используя концепцию энергетического хаба и потоковые методы.\n2. Навыки анализа и оценки эффективности использования различных источников энергии в интегрированных энергетических системах.\n3. Навыки оптимизации использования энергии в различных отраслях экономики, включая промышленность\n4. Навыки анализа и оценки экологических показателей работы интегрированных энергетических систем, включая снижение выбросов парниковых газов и негативного воздействия на окружающую среду.\n5. Навыки коммуникации и сотрудничества с различными заинтересованными сторонами, включая правительственные организации, бизнес-структуры и общественность.', NULL, 1, 1, 533, 6, NULL, NULL, NULL, NULL, NULL),
(595, '2023-06-07 04:23:20', '2023-06-20 06:21:28', 'Расстановка электрозаправок в населённом пункте.', 15, 'разработать алгоритм расстановки электрозаправочных станций в произвольном населённом пункте, с возможностью дальнейшего тиражирования решения. Критерий оптимальности размещения – максимальная утилизация станций.', 'Необходимо в течение семестра провести анализ особенностей расстановки электрозаправочных станций и разработать универсальный алгоритм, который можно тиражировать в любых населенных пунктах. При этом необходимо учесть основной критерий оптимальности размещения – максимальная утилизация станций.', 2, '2023-09-01', '2023-12-30', 'requirements', 'ООО «Эн+ Диджитал».', 'additional_inf', 'алгоритм расстановки электрозаправочных станций в произвольном населённом пункте', 'Знания: знать методы сбора, анализа, систематизации, хранения информации предприятия\nУмения: уметь, в соответствии с поставленной задачей, выявлять критерии оценки и отбора информации\nНавыки: владеть способами получения информации из различных источников', NULL, 1, 1, NULL, 38, 2, 'Добрый день Татьяна Александровна, у Вас тема проекта звучит не корректно', NULL, NULL, NULL),
(596, '2023-06-08 01:50:18', '2023-06-19 03:15:52', 'Разработка проектной документации на строительство линейных объектов электроснабжения', 15, 'Разработать проектную и рабочую документацию на строительство линейных объектов электроснабжения, расположенных в Иркутской области.', '1. Изучение нормативно-правовых основ проектирования. Градостроительная политика РФ. Федеральные законы и постановления правительства. СПДС: общие положения, основные требования к проектной и рабочей документации.\n2. Освоение автоматизированных технологий проектирования. Современные методы и способы выполнения проектных работ. Системы автоматизированного проектирования, применяемые при выполнении работ (AutoCAD, nanoCAD и др.). Современные технологии информационного моделирования. \n3. Разработка технологических и конструктивных решений линейного объекта. Учет при проектировании природно-климатических, грунтовых и гидрогеологических условий. Основные параметры линейного объекта. Выбор новейших технологий для обеспечения надежности, устойчивости и экономичности линейного объекта.', 2, '2023-09-01', '2024-05-30', 'requirements', 'ООО АтлантЭнерго', 'additional_inf', 'Проектная документация на строительство линейного объекта электроснабжения', 'Совершенствование имеющихся и формирование новых компетенций в рамках квалификации для ведения деятельности в области разработки проектной документации на строительство линейных объектов электроснабжения', NULL, 1, 1, NULL, 21, 4, NULL, NULL, NULL, NULL),
(597, '2023-06-08 02:38:01', '2023-07-03 02:17:18', 'Моделирование химических реакций с помощью квантово-химических расчетов', 15, 'Изучить методы моделирования химических реакций с помощью квантово-химических расчетов', 'В настоящее время распространены методы изучения строения веществ, их свойств и взаимодействия с другими веществами с помощью квантово-химических расчетов. Студенты ознакомятся с навыками моделирования химических реакций, обрабатывать полученные результаты', 2, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'Предполагается смоделировать каталитическую реакцию и сравнить с экспериментом', 'Знания: углубленные знания теории функционала плотности; \nУмения: выбрать соответствующие методы и подходы для моделирования процесса;\nНавыки: использования методов для моделирования химических процессов', NULL, 1, 1, NULL, 15, NULL, NULL, NULL, NULL, NULL),
(598, '2023-06-08 07:37:42', '2023-06-20 01:12:53', 'Расширение портфеля заказчиков НИОКР ИРНИТУ', 15, 'разработать стратегию расширения портфеля заказчиков НИОКР ИРНИТУ с учётом установления приоритетов, оптимального распределения ресурсов и достижения университетом стратегических целей', 'Стратегия расширения портфеля заказчиков НИОКР ИРНИТУ — это механизм, который позволит идентифицировать основных заказчиков НИОКР, выявить их особенности и сформировать инструменты, необходимы для привлечения новых заказчиков. Также даст возможность расставлять приоритеты и балансировать портфель. Даст инструменты управления портфелем и возможность контроля выполнения поставленных задач с целью достижения университетом стратегических целей.', 2, '2023-09-01', '2024-05-30', 'requirements', 'НИЧ, Калошин И. А.', 'additional_inf', 'стратегия расширения портфеля заказчиков НИОКР ИРНИТУ с учетом установления приоритетов, оптимального распределения ресурсов и достижения университетом стратегических целей', 'умение проводить патентный поиск;\nспособность устранять противоречия между ресурсами и приоритетами при формировании портфеля', NULL, 1, 1, NULL, 38, 1, 'Добрый день Марина Сергеевна, у вас не корректно написана тема проекта', NULL, NULL, NULL),
(599, '2023-06-08 08:05:30', '2023-07-03 02:33:52', 'Масла', 15, 'Изучение свойств масел разной основы', 'В настоящее время промышленность стремительно развивается и характеризуется созданием высокопроизводительных машин и механизмов, генерирующих и передающих большие мощности. По мере распространения технического прогресса усиливается энергонапряженность множественных узлов трения и, соответственно, возрастает роль смазочного материала как наиболее значимого элемента техники, повышаются и становятся разнообразнее требования к его качеству. Работоспособность техники, развитие автомобилестроения и других видов транспортного машиностроения, а, следовательно, и эффективность функционирования народного хозяйства серьезно зависят от их обеспеченности высокоэффективными  материалами – маслами.\nПроблема – снизить износ поверхностей, подвергающихся трению и нагрузкам. Это позволит продлить срок эксплуатации деталей механизмов, сделает их более долговечными и надежными. В ряде случаев масла применяются не только для снижения износа, но и для предотвращения трения и задира. Благодаря своим свойствам, которые достигаются введением присадок, масла, защищают поверхности машин и механизмов  от проникновения агрессивных веществ, газов и паров, проявляя тем самым антикоррозионные свойства. \nПри производстве товарных масел, разной масляной основы, необходимо введение различных групп присадок (депрессорных, смазывающих, диспергирующих и др.). отвечающих за эксплуатационные характеристики качества товарной продукции. Базы данных на содержание и состав присадок по маслам закрыты, поэтому введение присадок в базовую нефтяную основу и анализ изменения свойств, а также сравнение с товарными производителями', 2, '2023-09-01', '2024-05-30', 'requirements', 'письмо поддержки АО \"Нефтяная компания Дулисьма\"', 'additional_inf', 'Соответствие товарной продукции действующей нормативной документации. Определение содержания присадки в масляной основе и сопоставление с товарной продукцией.', 'Способен обеспечивать проведение технологического процесса в соответствии с регламентом, используя технические средства для контроля параметров технологического процесса, свойств сырья и готовой продукции, и осуществляя изменение параметров технологического процесса при изменении свойств сырья.\nСпособен проводить стандартные и сертификационные испытания материалов, изделий и технологических процессов.', NULL, 1, 1, 456, 3, 3, NULL, NULL, NULL, NULL),
(600, '2023-06-08 08:07:12', '2023-06-17 07:52:47', 'Оценка перспектив рынка изделий из модифицированной и пластифицированной древесины', 15, 'Формирование набора рыночных ниш на основе маркетинговых исследований для приложения усилий организации по их освоению и развитию', 'Рыночные ниши — это неформальные структуры, которые отличаются от сегментов размерами, количеством потребителей, сроками существования и привлекательностью для компаний. Реализация процедуры выбора рыночных ниш осуществляется путем отбора из выявленных существующих и потенциальных наиболее перспективных для осуществления работы в них, а также отсев малоперспективных. С помощью этого организация может разрабатывать и реализовывать рыночные стратегии, исходя из компромисса учета факторов, оказывающих влияние на работу компании на рыночных сегментах. Выбор сегмента или ниши для реализации стратегии определяется их текущими и потенциальными рыночными показателями.', 2, '2023-09-01', '2024-05-30', 'requirements', 'Управление по молодежной политике, Челпанова И. А.', 'additional_inf', 'Набор рыночных ниш на основе маркетинговых исследований', 'способность проводить маркетинговые исследования и отбирать рыночные ниши с целью формирования рыночной стратегии организации', NULL, 1, 1, NULL, 38, 1, 'Добрый день. Не корректно сформулирована тема', NULL, NULL, NULL),
(601, '2023-06-09 03:02:06', '2023-06-19 03:18:36', 'Оценка стоимости трубопровода по ГИС параметрам', 15, 'Создание методики оценки стоимости трубопровода в зависимости от рельефа местности', 'В настоящее время, разработка новых месторождений требует проектирования и строительства трубопроводного транспорта. Часто, их стоимость ставит под вопрос рентабельность разработки месторождения. Имеющийся современный инструментарий по проетированию траассы трубопровода на основе ГИС и спутникового мониторинга, позволяет выполнять этот процесс быстро дёшево с минимальной погрешностью.', 2, '2023-09-01', '2024-05-30', 'requirements', 'ИрНИТУ', 'additional_inf', 'Оценка стоимости трубопровода по ГИС парвметрам', 'Знание ГИС, проектирование в ГИС, гидравлический расчёт.', NULL, 1, 1, NULL, 18, NULL, NULL, NULL, NULL, NULL),
(602, '2023-06-09 03:32:27', '2023-06-19 03:18:13', 'Оценка себестоимости строительства трубопровода по критериям логистических издержек', 15, 'Создание методики оценки стоимости трубопровода в зависимости от технических параметров трубопровода', 'Часто трубопроводы приходиться строить в сложных горно-геологических условиях (вечной мерзлоты, крайнего севера, значительные перепады высот и др.), поэтому важно учитывать эти обстоятельства и уметь применять логистические методы расчёта, позволяющие оценивать реальную стоимость строительства с учётом оптимальных видов транспорта.', 2, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'Создание методики оценки стоимости трубопровода в зависимости от технических параметров трубопровода', 'Знание ГИС систем, логистических систем, мультимодальных перевозок.', NULL, 1, 1, 119, 18, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `projects` (`id`, `created_at`, `updated_at`, `title`, `places`, `goal`, `description`, `difficulty`, `date_start`, `date_end`, `requirements`, `customer`, `additional_inf`, `product_result`, `study_result`, `supervisorsNames`, `state_id`, `type_id`, `prev_project_id`, `department_id`, `theme_source_id`, `rejection_reason`, `rejection_date`, `project_review`, `project_goal`) VALUES
(603, '2023-06-10 14:00:43', '2023-07-11 08:48:50', 'Роспись в интерьере Городской Ивано-Матрёнинской детской клинической больницы.', 15, 'Освоение методики последовательного ведения работы над созданием росписи в интерьере общественного пространства. Создание художественно-выразительного произведения для интерьера Городской Ивано-Матрёнинской детской клинической больницы.', 'Разработка концепции творческого проекта (в технике художественной росписи стен) под руководством преподавателя, с учетом данных обучающегося. Выполнение эскизов на актуальную тему, связанную с функциональным назначением помещения.\nПроработка концепции графического/цветового решения, анализ архитектурного объекта. Выполнение работы в материале.', 2, '2023-09-01', '2023-12-30', 'requirements', 'ОГАУЗ ГИМДКБ, В.А. Новожилов', 'additional_inf', 'Творческий вывод - художественное произведение, роспись в интерьере Городской Ивано-Матрёнинской детской клинической больницы.', 'Знания:\nСпецифика проектной работы над созданием художественного произведения;\nОсобенности создания эскиза произведения, как составной части проекта; \nОсновы композиционного, графического, цветового проектирования;\nОсновы академического рисунка и живописи.\nУмения:\nОрганизация поэтапной работы над созданием художественного произведения;\nРабота с различными художественными материалами;\nИдея и реализация творческого замысла;\nНавыки: \nВладение  техниками и материалами изобразительного искусства;\nВладение методами изобразительного языка.', NULL, 1, 1, NULL, 49, 4, NULL, NULL, NULL, NULL),
(604, '2023-06-10 14:18:47', '2023-07-11 08:47:44', 'Создание художественного произведения/творческой работы для участия в выставочных проектах Всероссийской творческой организации «Союз художников России»', 15, 'Освоение методики последовательного ведения работы над созданием проекта. Создание художественно-выразительного произведения для последующего участия в выставочных и конкурсных проектах, организованных Всероссийской творческой организацией «Союз художников России»/Молодежным объединением ИРО ВТОО «Союз художников России»', 'Разработка концепции творческого проекта (художественной работы) под руководством преподавателя, с учетом данных обучающегося. Выполнение эскизов на тему, предложенную преподавателем, либо самим обучающимся, актуальную для тематики текущих выставок  Всероссийской творческой организации «Союз художников России»/Молодежного объединения ИРО ВТОО «Союз художников России». Проработка концепции графического/цветового решения, выбор техники исполнения произведения. Выполнение работы в материале.', 2, '2023-09-01', '2024-05-30', 'requirements', 'Выставочный отдел \"Музейная студия\" ГАУК Иркутского областного краеведческого музея им. Н.Н. Муравьева-Амурского, С.Г. Ступин', 'additional_inf', 'Творческий вывод - художественное произведение: картина/ графический лист/ проект digital art  (печать)/ работа в любой из техник монументально-декоративного искусства (мозаика, витраж, панно из ткани, гобелен и т.д.)', 'Знания:\nСпецифика проектной работы над созданием художественного произведения;\nОсобенности создания эскиза произведения, как составной части проекта; \nОсновы композиционного, графического, цветового проектирования;\nОсновы академического рисунка и живописи.\nУмения:\nОрганизация поэтапной работы над созданием художественного произведения;\nРабота с различными художественными материалами;\nИдея и реализация творческого замысла;\nНавыки: \nВладение  техниками и материалами изобразительного искусства;\nВладение методами изобразительного языка.', NULL, 1, 1, NULL, 49, 4, NULL, NULL, NULL, NULL),
(605, '2023-06-14 03:01:47', '2023-08-23 04:51:09', 'Правовые аспекты предоставления государственных и муниципальных услуг', 0, 'Выявление и анализ проблем правового регулирования и правоприменения в области предоставления государственных и муниципальных услуг в России, в том числе предоставления указанных услуг в электронной форме.', 'В России активно развиваются механизмы предоставления государственных и муниципальных услуг, в частности механизм электронного взаимодействия с органами государственной власти и органами местного самоуправления, используемый при предоставлении государственных и муниципальных услуг. Вместе с тем есть нерешенные вопросы, связанные с правовым регулированием отношений, возникающим в связи с предоставлением государственных и муниципальных услуг.', 2, '2023-09-01', '2023-12-30', 'requirements', NULL, 'additional_inf', 'Опубликование научной статьи. Выступление на научных конференциях', 'Знание основных инструментов поиска информации и требований к представлению результатов проекта.\nУмение использовать инструменты поиска информации, прежде всего справочно-правовые системы, и выделять из массива информации ключевые моменты, необходимые для решения конкретных задач. \nВладеть навыками поиска необходимой информации и ее анализа, формирования комплексного понимания предмета изучения, определения задач, их решения.', NULL, 8, 1, NULL, 58, NULL, 'превышение количества проектных команд', NULL, NULL, NULL),
(606, '2023-06-14 05:40:24', '2023-07-03 02:15:02', 'Переработка углеродсодержащей пыли алюминиевого производства', 15, 'Разработка технологии переработки мелкофракционной углеродсодержащей пыли алюминиевого производства', 'Производство алюминия является процессом, который связан с образованием большого количества углеродсодержащих отходов. Углеродсодержащие отходы могут образовываться при использовании анодных материалов в процессе электролиза. Анодные материалы, такие как кокс и нефтяной кокс, используются для обеспечения электропроводности в процессе электролиза. При этом образуется большое количество углеродсодержащих газов, которые также выделяются в атмосферу. В процессе прокаливания кокса, уголь нагревается до очень высокой температуры, около 1300 °С, в отсутствии воздуха. Это позволяет удалить из угля большую часть его содержимого, включая воду, дегазировать его и превратить в кокс. Однако мелкофракционная часть кокса выносится из печи до прокаливания и улавливается в системе газоочистки.  \nОбъектом исследования является углеродистая пыль, улавливаемая электрофильтрами при прокаливании нефтяного кокса с печи № 2 отделения производства анодной массы «РУСАЛ Братск» филиале в г. Шелехов. \nОсновные задачи исследования:\n1. Анализ проблемы образования отходов алюминиевого производства: пыли электрофильтров при прокалке кокса, пыли и мелочи печей обжига анодов.\n2. Обзор существующих способов переработки исследуемых отходов.\n3. Изучение состава и свойств объектов исследования.\n4. Разработка технологии окускования мелкодисперсных отходов. Определение оптимальных параметров окускования (содержание и состав связующего, влажность материала, давление пресса, температура и продолжительность сушки и др.).\n5. Экспериментальные исследования использования получаемых угольных брикетов для восстановления железа и кремния в высокотемпературной печи. \n6. Разработка аппаратурно-технологической схемы переработки исследуемых отходов.\n7. Расчет финансово-экономической модели предлагаемого способа переработки отходов.', 2, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'Технология/технологические рекомендации переработки мелкофракционной углеродсодержащей пыли алюминиевого производства', 'Навыки использования принципов рационального природопользования для энерго- и ресурсосбережения технологических процессов в металлургии алюминия', NULL, 1, 1, NULL, 1, NULL, NULL, NULL, NULL, NULL),
(607, '2023-06-14 05:45:12', '2023-06-30 07:25:38', 'Анализ и моделирование роботизированных систем.', 15, 'Разработка методик проектирования, подготовки к производству и изготовления отсутствующих отечественных и перспективных элементов роботизированных систем и их финансирования.', 'Проект базируется на ранее выполненных проектах и позиционируется как их продолжение.\n2020-2021 г. «Изготовление копий или действующих моделей летательных аппаратов». В тестовом варианте проекта была разработана 3д модель и на ее основе построена действующая модель самолета.\n2021-2022 г.  «Проектирование моделей летательных аппаратов». Отлаживались методики ускоренного получения необходимых знаний, на примере программы моделирования Siemens NX с целью летательных аппаратов, с совместным изучением других предметов, в частности аэродинамики. Были изготовлены детали и непосредственно сами копии летательных аппаратов по созданным электронным моделям.\n2022-2023 «Анализ инноваций проектирования и производства беспилотных систем». Проект был в основном посвящен сбору и структурированию материала по вопросам определенных на предыдущих проектах, и на его основе проводился анализ перспективности выбранных проектов. Разбирались возможные способы финансирования проектов и принципы составления заявок на получение финансирования в выбранный фонд.\nРабота в проектах велась исходя из трех основных принципов:\nработа должна быть интересной и позволяющей проявить свои способности и стремления;\nработа над проектом должна быть полезна для учебы (совмещение дисциплин и направленность на сбор материала могущего послужить основой для дипломного проекта);\nработа должна быть полезной для страны (в связи с необходимостью разработок как аналогов импортных товаров в рамках импортозамещения, так и создания новых перспективных товаров).\nРабота в предыдущих проектах велась в основном по направлению проектирование и изготовление моделей самолетов и  БПЛА (военного и гражданского назначения) с параллельным сбором, структурированием материала и созданием интеллектуальной и материальной баз по следующим направлениям:\nбеспилотные системы (библиотека, каталог БПЛА);\nоборудование инновационных технологических процессов (каталог 3d моделей оборудования и комплектующих, материалы и комплектующие для их изготовления);\nтрадиционные технологии и технология композиционных материалов (каталог материалов и нормативной документации, материалы и комплектующие для их изготовления);\nконтроллеры и их программирование (библиотека, начальный комплект комплектующих, достаточный для начала проведения работ).\nВ новом проекте, в зависимости от состава команды и ее возможностей будут реализовываться как старые направления с упором на их роботизацию:\nанализ и проектирование роботизированных беспилотных систем;\nпрограммные продукты проектирования и производства роботизированных систем; \nмодернизация традиционных и освоение современных технологий (композиционных материалов); \nперспективное технологическое роботизированное оборудование и оснастка технологических процессов.\nтак и новые направления, потребность в которых была выявлена в процессе работы над предыдущими проектами:\nробототехника, электроника роботизированных систем и их программирование;\nсовременные информационные системы (интернет технологии);\nмаркетинг и экономика инновационных направлений развития техники и технологии (так как для воплощения идей в жизнь помимо самой идеи нужны как для войны 3 вещи «во-первых — деньги, во-вторых — деньги и в-третьих — деньги «Джан Джакомо Тривульцио»). \nТаким образом, данный проект будет интересен в первую очередь тем студентам, которые имея определенные специфические знания и желания их приумножить, не привыкли просто сидеть на «заднице ровно» и хотят от проекта нечто большее, а не просто оценку.\nВ проекте, как консультанты будут принимать участие преподаватели кафедры СМиЭАТ: \nдоцент Молокова С.В.;\nдоцент Зотов И.Н.   \nПолная презентация проекта будет проводиться 04.09.2023 в аудитории Д-08 в 10:00. Предварительно более полную информацию по проекту можно получить, отправив интересующий вопрос на адрес электронной почты Istu.edu.d-08a@yandex.ru или подойти в аудиторию Д -08а, предварительно согласовав встречу по указанному адресу.', 2, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'В зависимости от квалификации участников электронная модель (по возможности действующая модель) роботизированной системы или ее части, или финансовая модель проекта или статья.', 'Получение основ знаний по проведению анализа перспективных технологических процессов и изделий, принципам построения технологических процессов и тенденциям их развития; моделированию, проектированию, с использованием программных продуктов, достаточных для проведения работ по анализу и подготовке технологических процессов и разработке изделий, экономическому обоснованию требуемого финансирования.', NULL, 1, 1, NULL, 31, NULL, 'Уточнить название', NULL, NULL, NULL),
(608, '2023-06-14 09:27:38', '2023-06-19 03:18:12', 'Профессиональные риски в структурных подразделениях  ИРНИТУ', 15, 'Оценить профессиональные риски в структурных подразделениях ИРНИТУ', 'Создание безопасных и благоприятных условий труда, является одной из приоритетных  задач  для эффективного  руководителя. Оценка профессиональных рисков это современный механизм направленный не только на сохранение жизни и здоровья персонала и соблюдение  требований законодательства, но и возможность достижения более высокого уровня функционирования  предприятия.\nДля этого необходимо провести процедуру оценки профессиональных рисков на каждом рабочем месте и в других зонах ответственности работодателя за безопасность сотрудников.', 2, '2023-09-01', '2024-05-30', 'requirements', 'Управление по работе с персоналом и обучающимися, служба охраны труда, Гуруленко Т.Ю., Ощепкова Л.В.', 'additional_inf', 'Карты оценки профессиональных рисков; комплекс мероприятий по устранению рисков или снижению их уровня', 'Умение выявлять и идентифицировать опасности, выполнять инструментальные измерения, разрабатывать мероприятия', NULL, 1, 1, 129, 19, 1, NULL, NULL, NULL, NULL),
(609, '2023-06-14 09:50:20', '2023-06-19 03:18:26', 'Культура безопасности как элемент снижения уровня профессиональных рисков', 15, 'Разработка практических процедур, которые помогут сформировать осознанное и ответственное отношение к вопросам безопасности и охраны труда', 'Культура безопасного труда – это часть общей организационной культуры, такой набор характеристик и особенностей деятельности организации и поведения отдельных лиц, который устанавливает, что проблемы безопасности являются высшим приоритетом.  Для формирования ответственного и осознанного отношения к вопросам безопасности и охраны труда необходимо повысить мотивацию и вовлеченность сотрудников в формирование культуры безопасности, что в конечном итоге приведет к снижению уровней профессиональных рисков.', 2, '2023-09-01', '2024-05-30', 'requirements', 'Управление по работе с персоналом и обучающимися, служба охраны труда, Гуруленко Т.Ю., Ощепкова Л.В.', 'additional_inf', 'Новые формы предоставления информации по охране труда и безопасности для сотрудников структурных подразделений ИРНИТУ. Задания для смотра-конкурса на лучшее подразделение ИРНИТУ по культуре безопасности.', 'Умение использовать современные формы предоставления информации по охране труда для мотивации работников на безопасный труд; работать с инструкциями, нормативно-правовыми актами в области безопасности и охраны труда; локальными актами организации.', NULL, 1, 1, 132, 19, 1, NULL, NULL, NULL, NULL),
(610, '2023-06-15 03:57:01', '2023-06-19 03:18:21', 'Модуль информационной поддержки работ при устранении аварий в условиях бурения', 15, 'Способы автоматических действий по устранению аварии', 'Обучение будущих специалистов нефтегазового дела автоматическим действиям при внезапных осложнениях и авариях при бурении скважин на нефть и газ.', 2, '2023-09-01', '2024-05-30', 'requirements', 'Зайцев В.И.', 'additional_inf', 'Алгоритм действий бригады КРС при авариях на скважине', 'Навыки основ ликвидации аварии на скважине', NULL, 1, 1, NULL, 18, NULL, NULL, NULL, NULL, NULL),
(611, '2023-06-15 06:56:08', '2023-06-19 03:18:25', 'Создание 3D моделей карьеров при проектировании и разработки месторождений открытым способом с помощью программы nanoCAD Geonics.', 15, 'Создать виртуальную объемную копию месторождения или карьера, которая позволит наблюдать за процессами, протекающими при проектировании и разработке, прогнозировать результаты работы, вносить корректировки по мере эксплуатации.', 'Идея проекта заключается в создании 3D модели карьерного поля или месторождения с использованием программы nanoCAD Geonics при проектировании и разработки месторождения открытым способом, позволяющее визуализировать рассматриваемый объект, построение рельефа поверхности, определение объемов открытых горных работ, демонстрация технологии разработки.', 2, '2023-09-01', '2024-05-30', 'requirements', 'ПКБ \"Горняк\" ИрНИТУ', 'additional_inf', 'Создать 3D модель карьера на стадии проектирования с помощью программы nanoCAD Geonics.', 'Получение основных навыков работы в программе nanoCAD Geonics.\nПриобретение навыков проектирования карьеров при разработке месторождений открытым способом.', NULL, 1, 1, NULL, 22, 4, NULL, NULL, NULL, NULL),
(612, '2023-06-15 08:48:14', '2023-07-11 08:44:46', 'Разработка проекта капитального ремонта жилого дома с применением цифровых технологий', 15, 'Разработка проекта на капитальный ремонт жилого дома', 'В ходе работы над проектом студенты знакомятся с работой фонда капитального ремонта Иркутской области, выезжают на объекты, которые планируются к капитальному ремонту в будущем периоде.  Выполняют обмерочные чертежи и выявляют дефекты. После чего разрабатывают мероприятию и создают проектно-сметную документацию на капитальный ремонт жилого здания с помощью современных программных комплексов.', 2, '2023-09-01', '2024-05-30', 'requirements', 'Фонд капитального ремонта Иркутской области', 'additional_inf', 'Проект капитального ремонта жилого дома', 'Обмер существующего здания, выявление дефектов, создание проектной документации с применением цифровых технологий', NULL, 1, 1, NULL, 26, 4, NULL, NULL, NULL, NULL),
(613, '2023-06-15 14:14:14', '2023-07-01 02:00:32', 'Разработка регулируемого демпфера для корректировки амплитудно-частотных характеристик колебательных систем.', 15, 'Совершенствование конструкций резонансных вибромашин', 'Регулируемый демпфер должен состоять из стандартных элементов гидрооборудования и изменять коэффициент демпфирования в пределах 3...25 кНс/м.', 1, '2023-09-01', '2023-12-30', 'requirements', 'Инициативная', 'additional_inf', 'Разработка конструкции и технической документации на изготовление регулируемого демпфера', 'Работа с технической и патентной литературой, конструирование узлов и деталей, разработка технической документации, работа в коллективе.', NULL, 1, 1, NULL, 16, NULL, 'Здравствуйте! Прошу добавить  3-й и 5-й  курс СДМ', NULL, NULL, NULL),
(614, '2023-06-15 14:53:33', '2023-09-04 04:06:01', 'Проектирование лабораторной установки для разделения сыпучих материалов.', 15, 'Повышение энергоэффективности процесса разделения сыпучих материалов', 'Лабораторная вибрационная установка должна работать в резонансном режиме, который сохраняется при изменении массы рабочего или частоты вынуждающей силы.', 2, '2023-09-01', '2024-05-30', 'requirements', 'Инициативная', 'additional_inf', 'Создание лабораторной установки для разделения сыпучих материалов', 'Проведение литературного обзора и патентного поиска, конструирование узлов и деталей машин, разработка технической документации на изготовление, работа в коллективе', NULL, 1, 1, NULL, 16, NULL, 'Здравствуйте! Прошу добавить  3-й и 5-й  курс СДМ', NULL, NULL, NULL),
(615, '2023-06-16 00:49:26', '2023-07-11 08:44:58', 'Методические рекомендации по разработке и оформлению организационно-технологической документации в строительстве', 15, 'Создание методических рекомендаций по разработке и оформлению организационно-технологической документации в строительстве', 'Организационно-технологической документация- это основополагающий документ, учитывающий последовательность технологических процессов и организации строительства, с учетом затрат времени и ресурсов. Данными документами являются:\n1.	Проект организации строительства ( ПОС)\n2.	Проект производства работ ( ППР)\n3.	Технологические карты ( ТК)\n4.	Проект организации демонтажных работ ( ПОД)\n5.	Проект организации капитального ремонта ( ПОКР)', 2, '2023-09-01', '2024-05-30', 'requirements', NULL, 'additional_inf', 'Создание методических рекомендаций в внедрением в строительную отрасль', 'Формирование знаний в организации, планировании и управлении в строительстве; Повышение качества  знаний в технологии строительного производства.', NULL, 1, 1, NULL, 26, NULL, NULL, NULL, NULL, NULL),
(617, '2023-06-16 08:15:43', '2023-06-22 04:53:28', 'Разработка сервиса \"Служба технической поддержки ИРНИТУ\"', 15, 'Создать платформу для принятия и контроля выполнения заявок в технические службы ИРНИТУ', 'Внутренний сервис ИРНИТУ по организации \"одного окна\" для всех заявок всех технических служб, от направлений административно-хозяйственной деятельности, до технического обслуживания ИТ и инженерной инфраструктуры ИРНИТУ. \nОценка возможностей технических служб при прозрачной системе контроля требований пользователей, размещающих заявки позволит оптимизировать нагрузку сотрудников и объем нереализованных требований.', 2, '2023-09-01', '2023-12-30', 'requirements', 'ИРНИТУ, Управление информационных систем', 'additional_inf', 'Опытная эксплуатация сервиса приема заявок технических служб ИРНИТУ', 'Верстка и дизайн Web-страниц, BackEnd Database', NULL, 1, 1, NULL, 59, 1, NULL, NULL, NULL, NULL),
(618, '2023-06-17 02:43:15', '2023-06-17 02:45:31', 'Расстановка электрозаправок в населённом пункте', 0, 'разработать алгоритм расстановки электрозаправочных станций в произвольном населенном пункте, с возможностью дальнейшего тиражирования решения. Критерий оптимальности размещения - максимальная утилизация станций.', 'с увеличением количества электромобилей, электроскутеров, электросамокатов и т.п., растёт потребность в организации для них электрозаправочных станций. Стратегия их размещения в населённых пунктах должна учитывать факторы, которые позволят достигнуть максимального использования каждой станции (т. е. утилизацию, в часах).', 1, '2023-09-01', '2023-12-30', 'requirements', 'ООО «Эн+ Диджитал»', 'additional_inf', '1.Определён перечень факторов, влияющих на определение точек размещения электрозаправочных станций;\n2. Определены источники информации для получения исходных данных;\n3. Разработан программный продукт для реализации алгоритма расстановки электрозаправок в произвольном населённом пункте.', 'в соответствии с целями и задачами проекта разрабатывать и планировать собственную деятельность; - четко отбирать информацию, относящуюся к теме задания-проекта; - анализировать и выбирать наиболее обоснованные способы решения проблемы проекта; - создавать и осуществлять свои варианты действий по созданию проектов; - осуществлять самооценку своих действий и давать оценку созданному проекту.', NULL, 8, 1, NULL, 54, 2, 'укажите уровень сложности проекта', NULL, NULL, NULL),
(619, '2023-06-17 02:50:23', '2023-06-17 02:52:37', 'расстановка электрозаправок в населённом пункте.', 0, 'разработать алгоритм расстановки электрозаправочных станций в произвольном населённом пункте, с возможностью дальнейшего тиражирования решения. Критерий оптимальности размещения – максимальная утилизация станций.', 'с увеличением количества электромобилей, электроскутеров, электросамокатов и т.п., растёт потребность в организации для них электрозаправочных станций. Стратегия их размещения в населённых пунктах должна учитывать факторы, которые позволят достигнуть максимального использования каждой станции (т. е. утилизацию, в часах).', 2, '2023-09-01', '2023-12-30', 'requirements', 'ООО «Эн+ Диджитал»', 'additional_inf', '1. Определён перечень факторов, влияющих на определение точек размещения электрозаправочных станций;\n2. Определены источники информации для получения исходных данных;\n3. Разработан программный продукт для реализации алгоритма расстановки электрозаправок в произвольном населённом пункте.', 'в соответствии с целями и задачами проекта разрабатывать и планировать собственную деятельность; - четко отбирать информацию, относящуюся к теме задания-проекта; - анализировать и выбирать наиболее обоснованные способы решения проблемы проекта; - создавать и осуществлять свои варианты действий по созданию проектов; - осуществлять самооценку своих действий и давать оценку созданному проекту.', NULL, 8, 1, NULL, 54, 2, 'не корректно сформулирована тема', NULL, NULL, NULL),
